P.entries["subzone:long-wash"] = {n="Довга Обмілина",s="Довга Обмілина — похмура, продувана вітрами смуга пляжу на Темному Узбережжі, що тягнеться на південь від Обердайна до руїн Амет'Арану. Цей сумний берег усіяний тушами морських створінь і уламками, а останнім часом став небезпечним через дедалі більше ворожих мурлоків.",h="Довга Обмілина — похмура, продувана вітрами смуга пляжу на Темному Узбережжі, що тягнеться на південь від...",kw={"довга обмілина","мурлоки","пляж","обердайн","темне узбережжя"},ang={["race:NightElf"]="Для калдореїв Обердайна мурлоки, що наступають уздовж Довгої Обмілини, — ще одна ознака тривожного безладу, що підповзає просто до порога їхнього головного порту."},sec={{t="Похмурий берег",b="Despite its name, the Long Wash is actually the shortest distinct stretch of coastline in Darkshore. It sits under the region's perpetual overcast skies, an expanse of damp sand littered with flotsam, beached driftwood, and the carcasses of sea creatures washed up by the Veiled Sea. While local crabs comb through the surf, travelers southward from Auberdine must tread cautiously: murloc tribes have established camps along the water's edge, aggressively attacking anyone encroaching on their scavenged territory."}},faq={{q="Де розташована Довга Обмілина?",a="Довга Обмілина тягнеться вздовж узбережжя Темного Узбережжя одразу на південь від Обердайну й сягає приблизно до того місця, що лежить на захід від давніх руїн Амет'Арану.",al={"розташування довгої обмілини","де довга обмілина","як знайти довгу обмілину"}},{q="Чому вона зветься Довгою Обмілиною?",a="«Обмілиною» тут звуть ту частину берега, яку омивають і заливають морські хвилі. Іронія в тому, що попри назву «Довга», це насправді найкоротша окрема смуга пляжу на Темному Узбережжі.",al={"чому довга обмілина","значення довгої обмілини","що означає обмілина"}},{q="Які небезпеки чатують на Довгій Обмілині?",a="Головна небезпека — агресивні клани мурлоків, що дедалі численніше збираються на узбережжі, а також прибережні повзуни, які ревно бережуть свої ділянки, та інші мешканці пляжу.",al={"небезпеки довгої обмілини","моби довгої обмілини","хто живе на довгій обмілині"}},{q="Чому на пляжі стільки мертвих істот?",a="Бурхливий прибій Прихованого Моря й скверна, що поширюється прибережними водами Темного Узбережжя, раз у раз викидають на вологий пісок уламки, корабельне начиння й умирущих морських тварин.",al={"мертві тварини довгої обмілини","викинуті істоти темного берега","уламки на березі"}}},fp="9,278,18.515.0,31.166.0,31.216.0,46.198.0,50.199.0"}
P.entries["subzone:longshore"] = {n="Лонгшор",s="Лонгшор — широке піщане узбережжя, що тягнеться вздовж усього західного краю Вестфолу. Попри мальовничі простори, берег славиться своєю небезпекою: тут повно агресивних мурлоків, а біля узбережжя розкидані уламки кораблів.",h="Лонгшор — широке піщане узбережжя, що тягнеться вздовж усього західного краю Вестфолу.",kw={"лонгшор","вестфол","узбережжя","мурлоки","старий мутноокий","дафна стілвелл"},ang={["class:Druid"]="Друїдам Альянсу доведеться пірнути в глибини біля північно-західної частини Лонгшору й відшукати скриньку, заховану біля затонулого корабля: без неї не зібрати підвіски, потрібної для водної подоби.",["class:Paladin"]="Паладинів, які йдуть за настановами Дуторіана Ралла в Стормвінді, посилають на південь, на хутір Дафни Стілвелл у Лонгшорі: там вони доводять свою звитягу, захищаючи безневинну фермерку від нападників Дефіас."},sec={{t="Підступне узбережжя",b="Лонгшор тягнеться вздовж усього західного Вестфолу й є одним із найширших суцільних пляжів у Східних Королівствах. Проте спокою подорожнім він не дарує. Прибій належить мурлокам на чолі з горезвісними страховиськами на кшталт Старого Мутноокого, а мілини встелені рештками затонулих суден — серед них і розбиті ельфійські військові кораблі. Ближче до півдня самотні поселенці, як-от Дафна Стілвелл, ледве тримаються проти розбійників Дефіас — а звідти через воду видно Маяк Вестфолу."}},faq={{q="Чому Лонгшор такий небезпечний?",a="Береги заполонили агресивні племена мурлоків, які безкарно блукають пісками й нападають на кожного, хто підійде надто близько до прибою. Крім мурлоків, південний край пляжу тривожать розбійники Дефіас, що грабують прибережні господарства.",al={"чому лонгшор небезпечний","чому стільки мурлоків","чи безпечний лонгшор"}},{q="Хто така Дафна Стілвелл?",a="Дафна Стілвелл — самотня поселенка, що тримає відлюдну ферму на південно-західній частині Лонгшора. Вона беззахисна, тож Братство Дефіас часто на неї нападає, і Лицарі Срібної Длані посилають їй на захист паладинів-послушників.",al={"дафна стілвелл","ферма стілвелл","жінка на пляжі"}},{q="Що за корабельні уламки біля узбережжя?",a="Біля Лонгшора під водою лежить чимало уламків — від торгових суден до ельфійських есмінців, що загинули в минулих морських битвах. Ці підводні руїни приваблюють мародерів, мурлоків і шукачів пригод, які шукають скарби, втрачені під хвилями.",al={"ельфійські руйнівники вестфолл","затонулі кораблі лонгшору","розбиті кораблі"}},{q="Навіщо друїди приходять на Лонгшор?",a="Друїди Альянсу проходять обряд, відомий як Випробування Морського Лева, щоб опанувати свою водяну подобу. Частина випробування — знайти затонулу скриню біля уламків корабля неподалік від північно-західного Лонгшора й дістати Половину Амулета Водяної Витривалості.",al={"завдання друїдів лонгшор","дивна скринька вестфолл","половина кулона водної витримки"}}},fp="9,255,23.513.0,34.260.0,23.284.0,44.239.0,34.262.0"}
P.entries["subzone:lordamere-internment-camp"] = {n="Табір для інтернованих Лордамер",s="Табір для інтернованих Лордамер — колишнє місце ув'язнення часів Другої війни на висотах над Кратером Даларану. Колись його звели, щоб тримати там млявих орків, а нині тут засіли вцілілі маги й вартові Даларану разом із підступною зграєю перебіжчиків-Відступників.",h="Табір для інтернованих Лордамер — колишнє місце ув'язнення часів Другої війни на висотах над Кратером...",kw={"табір лордамер","інтерновані","даларан","кеґан даркмар","кровокамінь","відступники","беламур"},ang={["race:Orc"]="Для орків цей табір — похмуре нагадування про часи після Другої війни, коли тисячі їхніх родичів чахли в неволі, доки Тралл не згуртував свій народ.",["race:Undead"]="Дезертири, що засіли в Лордамері, — пряма зрада Темної Леді. Вистежити Кеґана Даркмара й повернути кровокамені вкрай важливо, щоб таємниці Відступників не потрапили до людських рук."},sec={{t="Від в'язниці до дослідної застави",b="Після Другої війни Альянс звів по всіх північних королівствах табори для інтернованих, щоб тримати там переможену орківську Орду. Лордамер вирізнявся тим, що був єдиним табором у Горах Альтерак і підлягав Даларану. Відомо, що колись юні принц Артас Менетіл і Леді Джайна Праудмур прокралися повз сторожові вежі, щоб поглянути на полонених орків, і сперечалися, чи справедливо їх ув'язнювати. Орки давно звільнилися або втекли, і тепер табір під орудою Наглядача Беламура правує за заставу для залишків Даларану, які вивчають небезпечні магічні реліквії."},{t="Перебіжчики-Відступники",b="Табір заплутався в політиці нежиті Лордерону. Четверо ренегатів-Відступників — Кеґан Даркмар і його спільники — викрали з Андерсіті могутні артефакти з кровокаменю й утекли сюди, віддавши їх Наглядачеві Беламуру в обмін на прихисток за лініями Даларану. Маги охоче взяли артефакти для досліджень, а екзекутори з Таррен Мілла посилають вірних агентів Орди вистежити перебіжчиків і повернути викрадені кровокамені, поки Даларан не розкрив їхньої сили."}},faq={{q="Для чого спершу збудували цей табір?",a="Альянс заснував його після Другої війни, щоб тримати полонених орків, які впали в летаргію, втративши демонічну жагу крові. Через близькість до міста магів вежі охороняв і нагляд за табором вів Даларан.",al={"історія табору для інтернованих","чому тут табір","що це за місце"}},{q="Хто зараз тримає табір?",a="Табір тримають Наглядач Беламур і загін вартових та магів Даларану. Хоча сам Даларан тяжко постраждав і закритий захисним куполом у сусідньому кратері, ці вцілілі продовжують свої дослідження з укріпленого пагорба.",al={"хто живе в таборі","хто керує табором","хто наглядач беламур"}},{q="Чому в таборі нежить-Відступники?",a="Це дезертири з Андерсіті на чолі з Кеґаном Даркмаром. Зрадивши Королеву Сильвану й викравши священні артефакти з кровокаменю, вони віддали ці реліквії Наглядачеві Беламуру в обмін на захист Даларану від помсти Відступників.",al={"чому в таборі нежить","кеґан даркмар","відступники-дезертири"}},{q="Як це місце пов'язане з Артасом і Джайною?",a="За кілька років до того, як Погибель упала на Лордерон, принц Артас Менетіл і Леді Джайна Праудмур одного вечора прослизнули повз вартових табору, щоб подивитися на полонених орків. Джайна глибоко співчула ув'язненим родинам, а Артас стояв на тому, що табори — сувора необхідність.",al={"артас і джайна табір","візит артаса","джайна табір"}}},fp="25,274,31.595.0,18.501.1,40.265.0,32.224.0,46.240.0,57.294.0"}
P.entries["subzone:lordamere-lake"] = {n="Озеро Лордамер",s="Озеро Лордамер — одна з найбільших прісних водойм Східних Королівств, що межує з Галявинами Тірісфалю, Срібноліссям і Горами Альтерак. Колись гамірне водне серце людської цивілізації на півночі, тепер воно належить некромантам Погибелі, диким мурлокам і тіні нежиті, що шириться над його холодними водами й островами.",h="Озеро Лордамер — одна з найбільших прісних водойм Східних Королівств, що межує з Галявинами Тірісфалю...",kw={"озеро лордамер","острів фенріс","погибель","даларан","лордерон","відступники"},ang={["race:Human"]="Тихі туманні води Лордамера — сумне нагадування про зруйновану славу північних людських королівств, що колись вільно торгували на його берегах.",["race:Undead"]="Для Відступників Озеро Лордамер — і оборонний рів, що захищає Тірісфаль, і активна передова, де треба винищити рештки Погибелі на Острові Фенріс."},sec={{t="Серце занепалих королівств",b="У золоту добу Альянсу Лордерона Озеро Лордамер лежало на перехресті людської влади. Місто Лордерон, столиця королівства, стерегло його північні береги, біля південного краю височіло місто-держава чарівників Даларан, а гористий східний край облямовувало королівство Альтерак. Колись торгові судна й рибальські човни безстрашно перетинали його широкий, оповитий туманом простір. Після спустошень Третьої війни озеро з осередку торгівлі перетворилося на природний бар'єр, що відділяє землі Відступників у Тірісфалі та Срібноліссі від підступних висот Альтерака."},{t="Спірні простори",b="Сьогодні плавати темними водами Лордамера небезпечно. Посеред озера лежить Острів Фенріс, де некромант Погибелі Тул Рейвенклов і його раби-нежить тримають оборону від Відступників, а довкола никають люті воргени. Далі на схід лежать Світанкові Острови, цілком заполонені агресивними мурлоками-Темноплавцями. Від руїн довкола Даларана до берегів Андерсіті озеро вже не мирний шлях, а затоплене прикордоння, за яке змагаються недобиті потвори й армії мерців."}},faq={{q="Які королівства колись межували з Озером Лордамер?",a="У розквіт Альянсу Лордерона з Озером Лордамер межували три великі людські королівства: королівство Лордерон на півночі й заході, Даларан на півдні та Альтерак уздовж гірських круч на сході.",al={"хто жив біля озера лордамер","історія озера лордамер","королівства навколо лордамеру"}},{q="Хто тримає Острів Фенріс посеред озера?",a="Острів Фенріс нині тримають прислужники Погибелі під командуванням некроманта Тула Рейвенклова, хоча на них безперервно нападають Відступники, а голодні воргени не дають спокою.",al={"хто на острові фенріс","острів фенріс лордамер","правитель острова фенріс"}},{q="Що таке Світанкові Острови?",a="Світанкові Острови — гурт невеликих острівців у східній частині Озера Лордамер, на схід від Острова Фенріс. Їх заполонили й захопили ворожі мурлоки-Темноплавці.",al={"розташування світанкових островів","острови озера лордамер","монстри світанкових островів"}},{q="Звідки озеро дістало свою назву?",a="Озеро назвали так само, як сусідню столицю й королівство Лордерон, що своєю чергою дістали ім'я на честь давнього людського полководця Лордейна.",al={"походження назви лордамер","чому озеро лордамер"}}},fp="14,349,28.598.0,19.525.0,51.222.0,51.207.0,27.184.0,30.150.0"}
P.entries["subzone:lost-fleet"] = {n="Загублений Флот",s="Загублений Флот — розтрощені дерев'яні корпуси Третього флоту Кул Тіраса, що затонули біля північного узбережжя Багнокраю вздовж Затоки Барадін. Під час Другої війни флот знищили червоні дракони, поневолені Драконячою Пащею, а тепер уламки населяють неспокійні прокляті моряки-нежить, прикуті до решток загадковим прокляттям.",h="Загублений Флот — розтрощені дерев'яні корпуси Третього флоту Кул Тіраса, що затонули біля північного...",kw={"загублений флот","третій флот","кул тірас","дерек праудмур","прокляте око палета","затока барадін"},ang={["faction:Alliance"]="Розбиті кораблі — скорботне нагадування про тяжку ціну, яку Кул Тірас і Альянс заплатили в Другій війні, і вони вимагають шани до полеглих і кінця їхніх проклятих мук.",["profession:Blacksmithing"]="Ковалі Альянсу часто чують розповіді про затонулий флот, адже ще один корабель з тієї самої ескадри, «Летюча Скопа», пішов на дно з рідкісними злитками загартованого Світлом заліза."},sec={{t="Трагічний кінець у Другій війні",b="Під час Другої війни Третім флотом Кул Тіраса командував Дерек Праудмур, старший син лорда-адмірала. Під час битви з Орківською Армадою кораблі Альянсу зазнали удару згори — від червоних драконів, поневолених кланом Драконячої Пащі. Суцільні завіси драконячого полум'я швидко поглинули флот, і горді кораблі, як-от «Володарка Хвиль» і «Безстрашний», розбилися об мілини й рифи на півночі Багна Блакитнозябрих. Майже весь загін потонув або згорів, і Перший Помічник Фіцсіммонс лишився єдиним живим уцілілим у тій катастрофі."},{t="Прокляття Палета",b="Водяна могила не стала кінцем для моряків Третього флоту. Глибоко в затонулому трюмі «Безстрашного» лежав заборонений артефакт — Прокляте Око Палета, яке ревно беріг жадібний командир корабля, Капітан Галіндор. Темна реліквія спотворила утоплені команди й прикувала їхні душі до розтрощених дощок як навіжену, прокляту нежить. Лише привид Першого Помічника Снелліґа зберіг якусь подобу розуму: він блукає болотистим берегом, тоді як його колишні товариші люто кидаються на кожного, хто наблизиться до уламків."}},faq={{q="Що таке Загублений Флот?",a="Загублений Флот — це уламки кількох бойових кораблів Третього флоту Кул Тірасу, що лежать біля північного узбережжя Багнокраю, у Затоці Барадін. Їх знищили під час Другої війни, і тепер там блукають їхні мертві екіпажі.",al={"загублений флот","що це за місце","корабельні уламки багнокраю","третій флот"}},{q="Як знищили ці кораблі?",a="Під час Другої війни на флот напали з засідки й спалили його поневолені червоні дракони оркського клану Драконячої Пащі. Нещадне драконяче полум'я перетворило кораблі на палаючі остови, що пішли на дно біля узбережжя.",al={"хто потопив кораблі","як вони затонули","що знищило флот"}},{q="Чому тутешні моряки — нежить?",a="Їхні духи прикуті до уламків прокляттям. Перший Помічник Фіцсіммонс шукає допомоги, щоб з'ясувати, чому вони не можуть упокоїтися.",al={"чому вони привиди","нежить-моряки","прокляття палета"}},{q="Чи вижив хтось після загибелі флоту?",a="Перший Помічник Фіцсіммонс з корабля «Володарка Хвиль» — єдиний відомий живий свідок катастрофи. Він дістався безпечного місця й тепер живе в Гавані Менетіл.",al={"чи є вцілілі","хтось вижив","фітцсіммонс"}},{q="Хто командував Третім флотом?",a="Третім флотом командував Дерек Праудмур, старший син Великого Адмірала Даліна Праудмура. Дерек загинув у марсовому гнізді свого флагмана, коли дракони охопили флот полум'ям.",al={"хто командував флотом","капітан флоту","дерек праудмур"}}},fp="10,323,30.561.0,19.546.1,23.230.0,31.209.0,32.122.0,48.160.0,37.197.0"}
P.entries["subzone:lost-point"] = {n="Загублений Мис",s="Загублений Мис — занедбана дерев'яна сторожова вежа в західній частині Багна Пилоброду, яку колись звели сили Терамору як передовий розвідувальний пост. Відтоді вона занепала й вийшла з-під контролю варти Леді Джайни Праудмур, а тепер слугує схованкою для дезертирів-ренегатів.",h="Загублений Мис — занедбана дерев'яна сторожова вежа в західній частині Багна Пилоброду, яку колись звели сили...",kw={"загублений мис","багно пилоброду","терамор","дезертири","балос джекен","змова","рядовий гендел"},ang={["faction:Alliance"]="Для вірних Альянсу Загублений Мис — гіркий символ того, як розхитується дисципліна в лавах Терамору, і кубло ренегатів, що приховують темні таємниці військової зради."},sec={{t="Покинутий форпост",b="Загублений Мис, зведений експедиційними силами Терамору, щоб стежити за рухом і загрозами з боку Пусток, давно пережив своє військове призначення. Форпост занепав під невпинною вологою болота: колоди гниють, а регулярні війська покинули його укріплення. Замість вартових гарнізону вежу й околиці зайняли люди-дезертири, що втекли зі служби Терамору й знайшли прихисток у відлюдній глушині, далеко від дисципліни міських командирів."},{t="Кубло дезертирів",b="Дезертири, що окопалися на Загубленому Мисі, підкоряються Балосу Джекену — невдоволеному колишньому солдатові, який згуртував цих ренегатів. Їхня присутність — куди більше, ніж просто непокора наказам. Джекен і його спільники мають ключові свідчення про зрадників у лавах Терамору, зокрема про причетність Рядового Гендела до небезпечної змови, що сягає верхівки Альянсу."}},faq={{q="Що таке Загублений Мис?",a="Загублений Мис — занедбана сторожова вежа, яку люди з Терамора збудували на західних болотах Пилоброду. Її задумували як передову розвідувальну вежу, але військо її покинуло, і її захопили дезертири.",al={"огляд загубленого мису","що це за вежа","про загублений мис"}},{q="Хто зараз живе на Загубленому Мисі?",a="Вежу й табір довкола неї займають дезертири з Терамора. Ці вояки-ренегати зреклися присяги Тераморові й діють під проводом Балоса Джекена.",al={"хто на загубленому мисі","вороги загубленого мису","моби загубленого мису"}},{q="Хто такий Балос Джекен?",a="Балос Джекен — ватажок дезертирів із Терамора, що ховаються на Загубленому Мисі. Попри злочинну славу, він володіє важливими відомостями про тривожні справи в лавах Терамора.",al={"балос джекен","ватажок дезертирів","хто керує загубленим мисом"}},{q="Чому Терамор покинув вежу?",a="Багно Пилоброду вороже й погано придатне для постачання. Коли дух гарнізону впав, а дисципліна розхиталася, відрізана застава занепала й стала ідеальним прихистком для вояків, які хотіли втекти від служби, не тікаючи на землі Орди.",al={"чому покинули","чому загублений мис у руїнах","чому занепав"}}},fp="10,298,18.537.0,16.431.1,19.221.0,34.198.0,20.194.1,36.246.0"}
P.entries["subzone:lost-rigger-cove"] = {n="Бухта Загублених такелажників",s="Бухта Загублених такелажників, схована серед східних скель Танарісу, — головна база Піратів Південних морів у цьому краї. З трьох боків її захищають високі пустельні гори, а в цьому прихованому порту є причали, укріплені табори й діюча верф, де будують нові піратські кораблі.",h="Бухта Загублених такелажників, схована серед східних скель Танарісу, — головна база Піратів Південних морів у...",kw={"бухта загублених такелажників","пірати південних морів","флібустьєри","верф","танаріс","ґаджетзан"},ang={["class:Rogue"]="Розлогий піратський табір рясніє кишенями, які можна обчистити, приватними скриньками й головорізами, що знають усі брудні хитрощі морського розбою.",["race:Gnome"]="Для гномівських майстрів піратський сухий док — грубий, але промовистий виставковий зал зібраних із брухту механізмів і крадених деталей, а ще постійна загроза для кожного торгового судна в південних морях."},sec={{t="Пірати й гірські мури",b="Бухта Загублених такелажників, яку майже з усіх боків природно захищають прямовисні скелясті стіни, — ідеальна морська твердиня для Флібустьєрів Південних морів на південно-східному краю Калімдору. Тут піратські головорізи, вантажники й розбійники тягають здобуте добро й складають нові корпуси кораблів просто під носом у влади Ґаджетзана. Бухта дає змогу піратам Південних морів поширювати свою владу на Велике Море й грабувати торгові шляхи між Раджетом, Буті Беєм і прибережними поселеннями."},{t="Суперники на порозі",b="Пірати володіють бухтою не без боротьби. Гоблінам Ґаджетзана й сусіднього Порту Стімвідла не до вподоби нальотники на їхньому порозі, тож вони платять найманцям, щоб ті вирізали піратів Південних морів, прорідили їхні лави й зривали їхні оборудки."}},faq={{q="Хто тримає Бухту Загублених такелажників?",a="Бухту тримають Пірати Південного Моря — горезвісне морське угруповання, що діє по всьому Калімдору й Південних Морях. У цій природній гавані вони лагодять свій флот і будують нові бойові кораблі.",al={"хто володіє бухтою загублених такелажників","хто живе в бухті загублених такелажників","фракції бухти загублених такелажників"}},{q="Хто тут воює з піратами?",a="Гобліни з Ґаджетзана й Порту Стімвідла, яким не до вподоби грабіжники під самим порогом, наймають заїжджих шукачів пригод, щоб ті вдарили по піратській твердині й прорідили лави Південного Моря.",al={"табір гномів і гоблінів танаріс","чому тут гноми","чому воювати з піратами"}},{q="Де розташована Бухта Загублених такелажників?",a="Вона на східному узбережжі Танарісу, на південний схід від Ґаджетзана. Дістатися туди можна звивистою стежкою каньйоном, що прорізає прибережний гірський кряж.",al={"де бухта загублених такелажників","як дістатися до бухти загублених такелажників","бухта на мапі"}},{q="Що будують пірати в бухті?",a="Посеред бухти Пірати Південного Моря тримають діючий сухий док і верф, де теслярі й розбійники зводять корпус великого океанського бойового корабля.",al={"верф бухти загублених такелажників","будівництво піратських човнів"}}},fp="16,310,26.461.0,22.235.0,30.201.0,33.178.0,34.154.0,42.180.0"}
P.entries["subzone:lower-wilds"] = {n="Нижні Хащі",s="Нижні Хащі — східний поріг Фераласу, де вологі ліси сходяться з посушливими каньйонами Тисячі Голок. Головний шлях крізь ці ліси з'єднує прикордонний Таланаар із поселеннями далі на заході; обабіч нього — прадавня зелень і непередбачувані лісові створіння.",h="Нижні Хащі — східний поріг Фераласу, де вологі ліси сходяться з посушливими каньйонами Тисячі Голок.",kw={"нижні хащі","фералас","таланаар","тисяча голок","табір моджаче","тракт"},ang={["faction:Alliance"]="Для мандрівників з Альянсу, що залишають Тисячу Голок, Нижні Хащі — перше, що вони бачать у Фераласі; опорою тут є прикордонна застава нічних ельфів у Таланаарі.",["faction:Horde"]="Гінцям і обозам Орди, що прямують до Табору Моджаче, доводиться пройти Нижні Хащі з кінця в кінець, щойно вони спустяться з прикордонних каньйонів."},sec={{t="Східне прикордоння",b="Spanning the eastern reaches of Feralas, the Lower Wilds serve as the natural transition between the sun-baked ravines of Thousand Needles and the deep, primordial jungle to the west. Travelers entering the zone must traverse this stretch of forest along the main highway, past the elven outpost of Thalanaar guarding the mountain pass. The dense canopies here house ancient treants, alongside indigenous wildlife that makes straying from the beaten path perilous."},{t="Спірний тракт",b="Нижні Хащі пов'язують південні нетрі зі східними землями, тож тут постійно ходять мандрівники, розвідники й гінці. Нічні ельфи тримають браму в Таланаарі, а Орда утримує Табір Моджаче глибше в краї. Тож дорога крізь Нижні Хащі — життєво важлива артерія для кожного, хто везе припаси через південний Калімдор, і небезпек на ній вистачає: і від природи, і від ворожнечі фракцій."}},faq={{q="Де розташовані Нижні Хащі?",a="Нижні Хащі — найсхідніша частина Фераласу. Вони безпосередньо межують із Тисячею Голок і тягнуться на захід від гірського порогу Таланаару вглиб джунглів.",al={"розташування нижніх хащ","де нижні хащі","як дістатися до нижніх хащ"}},{q="Хто живе в Нижніх Хащах?",a="The woodlands are inhabited by ancient forest guardians, including treants, as well as the native predatory beasts that roam the feral forest floor.",al={"моби нижніх хащ","що в нижніх хащах","вороги нижніх хащ"}},{q="Які поселення поблизу Нижніх Хащ?",a="На далекому східному кордоні стоїть застава нічних ельфів Таланаар — головний вхід Альянсу до Фераласу. Далі на захід дорогою лежить поселення Орди — Табір Моджаче.",al={"містечка нижніх хащ","табори біля нижніх хащ","поселення орди й альянсу в нижніх хащах"}},{q="Чи безпечна дорога крізь Нижні Хащі?",a="Сама дорога — найбезпечніший шлях краєм, але мандрівникам слід бути напоготові. Зійдете зі стежки — нарветеся на напади агресивних лісових звірів і захисників, що бережуть свої угіддя, а часом на шлях перекидаються ще й сутички ворожих фракцій.",al={"чи безпечні нижні хащі","безпека дороги нижніх хащ"}}},fp="11,295,20.464.0,19.428.0,34.197.0,39.148.0,47.194.0,41.250.0"}
P.entries["subzone:lushwater-oasis"] = {n="Оаза Буйних Вод",s="Оаза Буйних Вод — одна з трьох живодайних водойм посушливих Пусток, трохи на південь від Перехрестя. Попри пишну зелень, оаза сповнена небезпек: тут кишать агресивні кентаври Колкари, а ще тут вхід до Печер Стогонів. Її отруєні води добре знайомі рибалкам, які шукають дивну Девіантну Рибу.",h="Оаза Буйних Вод — одна з трьох живодайних водойм посушливих Пусток, трохи на південь від Перехрестя.",kw={"оаза буйних вод","печери стогонів","колкари","девіантна риба","оаза","пустки"},ang={["class:Druid"]="Оаза Буйних Вод вражає тривожним, неприродним розростанням зелені, яке живлять спотворені сили, що вириваються із сусідніх Печер Стогонів.",["profession:Cooking"]="Ці ставки — одні з небагатьох водойм, де рибалки можуть зловити Девіантну Рибу, цінований на всьому Калімдорі інгредієнт для Смачних Девіантних Делікатесів."},sec={{t="Хиткий прихисток",b="Оаза Буйних Вод, до якої недалеко йти на південь від Перехрестя, обіцяє оманливий перепочинок серед вибілених сонцем просторів Пусток. Пальмові крони й свіжі джерела приваблюють спраглих звірів з усієї савани, але береги захопили кентаври Колкари, що чатують, аби вбивати і дичину, і необережних мандрівників. Оаза — ще й брама до Печер Стогонів, чиї розлогі підземні ходи просочують згубну енергію у ставки нагорі, породжуючи неприродних звірів і химерні мутації."}},faq={{q="Де вхід до Печер Стогонів?",a="Вхід до системи Печер Стогонів вирубано в природних скелях, що нависають над східним боком Оази Буйних Вод.",al={"де вхід у печери стогонів","вхід у печери стогонів","печера стогонів"}},{q="Хто тримає Оазу Буйних Вод?",a="По всій оазі панують кентаври-Колкари: під покривом буйної зелені вони полюють на звірину й нападають на мандрівників, що прямують від Перехрестя.",al={"хто живе в оазі буйних вод","вороги оази буйних вод","кентаври в оазі"}},{q="Чому тутешня риба дивна?",a="Глибинна енергія, що просочується з Печер Стогонів, отруїла води по всій оазі, і місцева риба мутувала на незвичайну Девіантну Рибу.",al={"де збочена риба","чому збочена риба","мутована риба оази"}},{q="Чи проходила тут Орда Тралла?",a="Під час Довгого Походу орків Пустками разом із тауренами Тралл вів своїх воїнів від однієї розкиданої оази до іншої, щоб запастися конче потрібною питною водою, відбиваючи безугавні засідки кентаврів.",al={"довгий похід тралла","орки в оазі пустовиськ"}}},fp="15,364,22.501.0,53.138.0,29.174.0,30.153.0,39.206.0"}
P.entries["subzone:maclure-vineyards"] = {n="Виноградники Маклюрів",s="Виноградники Маклюрів — розлогий сільськогосподарський маєток на півдні Лісу Елвінн, що належить родині Маклюрів. Відомий виноградом і вином для королівства Стормвінд, маєток не менш сумнозвісний через тривалу запеклу ворожнечу з сусідньою родиною Стоунфілдів.",h="Виноградники Маклюрів — розлогий сільськогосподарський маєток на півдні Лісу Елвінн, що належить родині...",kw={"виноградники маклюрів","виноград","вино","ворожнеча","стоунфілди","мейбелл маклур","ліс елвінн"},ang={["faction:Alliance"]="Маєток — важлива житниця й виноградник, що постачає сусідні Ґолдшир і Стормвінд харчами та напоями.",["race:Human"]="Для людей Стормвінда ворожнеча на виноградниках — класичний приклад сільської впертості; вона нагадує мандрівникам, що навіть у серці королівства сусіди часто сваряться через паркани, поки назріває більша небезпека."},sec={{t="Гіркий урожай",b="Виноградники Маклюрів серед буйних пагорбів південного Лісу Елвінн мали б бути мирним прихистком виноробства та хліборобства. Натомість щоденну працю затьмарює люте давнє суперництво зі Стоунфілдами, що живуть трохи далі дорогою. Між господарствами глибоко вкорінилися звинувачення в крадіжках і злопам'ятство, і пристрасті не вщухають навіть тоді, коли спільні біди — голодні вепри та кобольди, що насуваються, — загрожують обом садибам."},{t="Заборонене кохання",b="Попри люту ворожнечу двох патріархів, юне кохання перетнуло межу. Мейбелл Маклур і Томмі Джо Стоунфілд таємно покохали одне одного й зустрічаються в потаємних гаях подалі від підозріливих батьківських очей. Ті, хто проходить через виноградники, часто виявляють, що вже носять таємні записки, залагоджують дрібні образи й намагаються допомогти юній парі вирватися з тіні родинної ворожнечі."}},faq={{q="Чому ворогують Маклури й Стоунфілди?",a="Це давня сільська ворожнеча, що виросла з років недовіри, дрібних звинувачень і впертої гордині. Жодна родина не вірить іншій ні на макове зерно, і обидві звинувачують одна одну в утраті добра й худоби, хоча прямих доказів лиходійства не має ніхто.",al={"ворожнеча маклурів і стоунфілдів","чому вони ненавидять одне одного","сімейна ворожнеча"}},{q="Хто така Мейбелл Маклур?",a="Мейбелл — донька родини Маклурів. Усупереч запеклій ненависті своєї родини до сусідів, вона потай покохала Томмі Джо Стоунфілда й сподівається знайти спосіб бути з ним разом.",al={"мейбелл","дочка маклура"}},{q="Що загрожує виноградникам?",a="Окрім родинних чвар, виноградникам дошкуляють ненажерливі дикі вепри, що топчуть посіви й лози, а також кобольди з довколишніх золотих копалень, що грабують сусідні поля.",al={"небезпеки виноградників","вепри маклурів"}},{q="Що вирощують тут Маклури?",a="Родина Маклурів вирощує виноград, постачаючи вино й свіжі ягоди корчмарям і крамарям по всьому Лісу Елвінн і Стормвінду.",al={"що тут росте","врожай маклурів"}}},fp="17,281,16.441.0,19.440.1,46.246.0,23.216.0,35.187.0,34.148.0"}
P.entries["subzone:maestra-s-post"] = {n="Пост Маестри",s="Пост Маестри — невелике поселення Альянсу в західному Ашенвалі, при дорозі на північний захід від Астранаару й на південь від Руїн Ордил'Аран. Його охороняють Вартові нічних ельфів, а ще тут живуть люди — рідкісні гості в прадавньому лісі Калімдору. Пост слугує передовою вартою проти загроз, що насуваються.",h="Пост Маестри — невелике поселення Альянсу в західному Ашенвалі, при дорозі на північний захід від Астранаару...",kw={"пост маестри","ашенваль","вартові","альянс","застава","фіро айронгенд"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що залишають безпечне Темне Узбережжя, ця застава — перший дружній прийом і укріплений прихисток у спірних лісах Ашенвалю.",["race:NightElf"]="Пост показує, як міцніє партнерство в новому Альянсі: тут Вартові ділять вогнище й варту з молодшими расами Східних Королівств."},sec={{t="Передова варта",b="Пост Маестри, що стоїть під кронами західного Ашенвалю, — це струнка вежа нічних ельфів і відкритий будиночок. Тут важлива зупинка для мандрівників, що прямують між Темним Узбережжям і більшим осередком — Астранааром. Попри спокійну ельфійську архітектуру, застава завжди насторожі. Місцеві Вартові пильно стежать за довколишніми нетрями, де заворушилися осквернені фурболги, а загони Орди неподалік раз у раз загрожують шляхам постачання Альянсу."},{t="Зустріч союзників",b="На відміну від багатьох замкнених анклавів нічних ельфів у глибині лісу, Пост Маестри вирізняється тим, що тут живе кілька союзників-людей. Такі постаті, як Фіро Айронгенд і Делґрен Очищувач, мешкають тут поруч із Вартовими, віддаючи свою бойову міць і відданість Святому Світлу на службу всьому Альянсу. Завдяки їм цей віддалений табір — одне з перших місць зустрічі Східних Королівств із давніми захисниками Калімдору."}},faq={{q="Де розташований Пост Маестри?",a="Він на заході Ашенвалю, біля дороги на північний захід від Астранаару й трохи на південь від Руїн Ордил'Арану.",al={"розташування посту маестри","де пост маестри","знайти пост маестри"}},{q="Хто така Маестра?",a="Пост названо на честь Місячної Жриці Маестри — шанованої серед нічних ельфів постаті, хоча самої жриці на заставі зараз немає.",al={"хто така маестра","жриця місяця маестра","ким була маестра"}},{q="Чому на ельфійській заставі люди?",a="Після Третьої війни, коли нічні ельфи приєдналися до Альянсу, мандрівники й воїни, як-от Фіро Айронгенд і Делґрен Очищувач, вирушили до Калімдору, щоб допомогти союзникам — нічним ельфам — і зміцнити зв'язки з ними.",al={"чому люди в ашенвейлі","фіро айронхенд чому тут","делґрен очисник чому тут"}},{q="Що загрожує Посту Маестри?",a="Заставі доводиться протистояти зіпсованим кланам фурболгів, що чатують у довколишніх лісах, а також розвідувальним загонам і вилазкам сил Орди, які пробиваються в Ашенваль.",al={"хто нападає на пост маестри","небезпеки посту маестри"}}},fp="14,306,15.496.0,21.462.0,32.125.0,16.155.0,41.223.0,33.186.0"}
P.entries["subzone:mage-quarter"] = {n="Квартал магів",s="Квартал магів — чародійне серце Стормвінда, що лежить за каналами в південно-західному куті столиці. Над його брукованими вулицями й крамницями езотеричних товарів височіє Святилище Чародія, де чарівники королівства вдосконалюють своє мистецтво. Та під ученою поверхнею кварталу ховаються й тіньові закутки, де знайшли притулок адепти куди темніших мистецтв.",h="Квартал магів — чародійне серце Стормвінда, що лежить за каналами в південно-західному куті столиці.",kw={"квартал магів","святилище чародія","маги","чорнокнижники","зарізане ягня","стормвінд"},ang={["class:Mage"]="Квартал — ваш головний дім у Стормвінді: у Святилищі Чародія на вас чекають майстри-наставники й реагенти для заклинань.",["class:Warlock"]="Під показною личиною таверни «Зарізане Ягня» ховається таємний ковен, де адепти темних мистецтв збираються, щоб навчатися й потай викликати слуг."},sec={{t="Святилище таємних мистецтв",b="До Кварталу магів ведуть мости через канали із Соборної Площі чи Торгового Кварталу, і він цілком присвячений містичним потребам Альянсу. Довкола шпиля Святилища Чародія збираються людські чарівники та їхні союзники, щоб вивчати плетиво таємної магії й навчати учнів. Довколишні вулиці заповнюють торговці тканинами для кравців, реагентами, алхімічним приладдям і зачарованими палицями, і квартал живе власним відокремленим життям, присвяченим дослідженням і обороні королівства."},{t="Таємниці під поверхнею",b="Не все чаклунство, яке практикують у кварталі, схвалюють верховні чарівники королівства. Такі заклади, як «Синій Відлюдник», дають ученим тихий прихисток, а от сумнозвісна таверна «Зарізане Ягня» ховає в підземних склепах таємний ковен чорнокнижників. Там, подалі від міської варти й святих очей Соборної Площі, демонологи вивчають заборонені обряди скверни й підкорюють потойбічних істот, ховаючись за загальною терпимістю кварталу до містичних дивацтв."}},faq={{q="Що таке Святилище Чародія?",a="Святилище Чародія — помітна вежа, що височіє над Кварталом магів. Це головна академія, бібліотека й тренувальне місце магів Стормвінда, де живуть учені, наставники містичного мистецтва й чаклуни-захисники, яким доручено оберігати столицю.",al={"вежа магів","святилище чародія","святилище магів стормвінда"}},{q="Де в Кварталі магів навчаються чорнокнижники?",a="Чорнокнижники потай збираються під «Зарізаним Ягням» — непримітною таверною в кварталі. У її склепах і прихованих льохах прихильники магії Скверни вивчають темні обряди, викликають демонів і навчаються подалі від пильного ока міської варти.",al={"де вчаться чорнокнижники","наставник чорнокнижників","зарізане ягня"}},{q="Які крамниці є в Кварталі магів?",a="Квартал повний крамниць для чарівників і ремісників. Тут є кравецькі крамниці, як-от «Тканини Дункана» й «Одяг Ларсона», крамарі з алхімічним і травницьким крамом, продавці приладдя для зачарування, феєрверків і чарівних палиць.",al={"крамниці кварталу магів","що за крамниці тут","торговці кварталу магів"}},{q="Як дістатися до Кварталу магів?",a="Квартал магів займає південно-західний куток Стормвінда. Потрапити туди можна прямо — мостами через Канали з Торгового Кварталу або з Соборної Площі.",al={"де квартал магів","як дістатися до кварталу магів","шлях до кварталу магів"}}},fp="12,378,21.510.0,27.491.1,29.257.0,45.246.0,43.254.0,34.193.0"}
P.entries["subzone:magic-quarter"] = {n="Магічний Квартал",s="Магічний Квартал — північно-східний район Андерсіті, осередок чародійних студій і темного чаклунства Відступників. Над кварталом панує зловісний Храм Проклятих, а живуть тут знавці і чародійних мистецтв, і магії скверни.",h="Магічний Квартал — північно-східний район Андерсіті, осередок чародійних студій і темного чаклунства...",kw={"магічний квартал","андерсіті","маги","чорнокнижники","храм проклятих","відступники"},ang={["class:Mage"]="Магічний Квартал — серце чародійства Відступників: тут навчають чародійних мистецтв і телепортації, що пов'язує Андерсіті з рештою Орди.",["class:Warlock"]="У темних нішах Храму Проклятих чорнокнижники прикликають демонічних слуг і відточують тіньову магію далеко від осудливих очей Альянсу."},sec={{t="Зібрання темних мистецтв",b="Магічний Квартал займає північно-східну частину підземного міста: тут Відступники бережуть свою чародійну спадщину й заглиблюються в темніші методи. Осердя району — похмурий Храм Проклятих, архітектурна пам'ятка Погибелі, яку нежить із вільною волею пристосувала для своїх потреб. Під його тінистими склепіннями маги тонко керують магічною енергією, а поруч чорнокнижники спілкуються з демонічними істотами, тож квартал став осердям інтелектуальної сили й окультних досліджень у Лордероні."},{t="Учені, ткачі й заклиначі",b="Окрім вивчення чистих заклинань і прикликання, Магічний Квартал — важливий громадський осередок для заклиначів. Наставники порталів підтримують сполучення з усіма землями Орди, а майстри-кравці працюють із зачарованими тканинами, шиючи мантії й савани. На відміну від Даларана з його суворою межею між академічним чародійством і забороненою магією, Відступники відкрито поєднують у цих залах чародійну допитливість і силу скверни, щоб утриматися проти численних ворогів."}},faq={{q="Для чого потрібен Магічний Квартал?",a="Магічний Квартал — осередок чарівних і демонічних наук Відступників. Тут є наставники магів і чорнокнижників, майстри порталів, що сполучають з іншими містами, і кравці, які тчуть зачаровану тканину.",al={"що таке магічний квартал","призначення магічного кварталу","магічний район підміської"}},{q="Чому в Андерсіті є Храм Проклятих?",a="Коли Погибель видовбала Андерсіті під руїнами столиці Лордерона, вона звела там споруди на кшталт Храму Проклятих. Захопивши підземний комплекс, Сильвана та її вільні Відступники забрали собі ці споруди й пристосували їх для власних чаклунів.",al={"храм проклятих підміська","чому тут храм проклятих","будівля погибелі в підміській"}},{q="Кого навчають у Магічному Кварталі?",a="У кварталі навчають наставники магів, чорнокнижників і демонів, а знавці порталів і майстри кравецтва навчають мандрувати й ремесла.",al={"наставники магічного кварталу","хто тут навчає","класи магічного кварталу"}},{q="Де розташований Магічний Квартал?",a="Він у північно-східній частині Андерсіті, просто навпроти Апотекаріуму через центральне кільце.",al={"де магічний квартал","розташування магічного кварталу","знайти магічний квартал"}}},fp="13,245,23.561.0,32.481.0,41.233.0,53.301.0,40.165.0,35.117.0"}
P.entries["subzone:magram-village"] = {n="Село Маґрам",s="Село Маґрам — поселення клану кентаврів Маґрам серед смердючих жовтих озерець у південно-східному Пустограї. Це головна база Маґрам у безжальній війні з ненависними суперниками — Ґелкіс.",h="Село Маґрам — поселення клану кентаврів Маґрам серед смердючих жовтих озерець у південно-східному Пустограї.",kw={"село маґрам","пустограй","кентаври","маґрам","ґелкіс","сірчані озера"},ang={["race:Tauren"]="Дикість кентаврів поколіннями була лихом для племен Калімдору, тож будь-яке поселення цих кочових мародерів — тривожне нагадування про пролиту кров."},sec={{t="Твердиня в трясовині",b="Село Маґрам, що розкинулося на острівцях і берегах застояних сірчаних озерець у південно-східному Пустограї, — грубе поселення, зліплене з примітивних дерев'яних містків і наметів зі шкур. Кентаври Маґрам живуть тут у постійній пильності щодо сусідніх кланів. Відомі своєю жорстокістю й закоренілою ворожнечею до південного клану Ґелкіс, Маґрам терплять чужинців лише тоді, коли ті доведуть свою вартість, вирізаючи їхніх ворогів Ґелкіс."}},faq={{q="Хто живе в Селі Маґрам?",a="У селі живе клан Маґрамів — один із кількох ворогуючих кланів кентаврів, споконвічних мешканців Пустограю. Вони живуть під грубими шкіряними наметами на острівцях, сполучених хиткими кладками.",al={"хто тут","мешканці маґрам","кентаврове село"}},{q="Чи можна увійти до Села Маґрам так, щоб на мене не напали?",a="Спершу кентаври-Маґрами ворожі до всіх чужинців. Проте мандрівники можуть здобути їхню довіру, полюючи на їхніх заклятих ворогів — кентаврів-Ґелкіс, — щоб піднести свою репутацію в клані.",al={"чи дружні маґрам","маґрам ворожі","як відвідати село маґрам"}},{q="Чому ставки довкола села жовті?",a="Ставки в селі й довкола нього отруєні сіркою й мінеральними стоками, звичними для безплідних пусток Пустограю, тож вода в них застояна, вицвіла й брудна.",al={"жовта вода","забруднені ставки","вода маґрам"}},{q="Чому Маґрами воюють із Ґелкіс?",a="Клани кентаврів Пустограю славляться легендарною кровожерливою ворожнечею. Особливо запекло вже кілька поколінь воюють Маґрами й Ґелкіс — за панування над південними краями пустки.",al={"маґрам проти ґелкіс","кентаврова кривава ворожнеча","війна кентаврів"}}},fp="14,232,24.482.0,28.176.0,50.201.0,44.169.0,39.210.0"}
P.entries["subzone:main-hall-northshire"] = {n="Головна Зала (Нортшир)",s="Головна Зала — центральна вхідна зала Абатства Нортшира в Лісі Елвінн. Це головне перехрестя, що сполучає подвір'я абатства з його верхньою вежею, Залою Зброї та Бібліотечним Крилом. Сюди з'являються щойно набрані шукачі пригод з людей, щоб отримати перші доручення на службі королівству Стормвінд.",h="Головна Зала — центральна вхідна зала Абатства Нортшира в Лісі Елвінн.",kw={"головна зала","абатство нортшира","вхід","новобранці","доручення","нортшир","стормвінд"},ang={["race:Human"]="Для людей королівства Головна Зала Абатства Нортшира знаменує початок їхнього шляху на службі Стормвінду та Святому Світлу."},sec={{t="Серце абатства",b="Ступивши крізь величні арки Абатства Нортшира, відвідувачі одразу потрапляють до Головної Зали. Як центральний вузол будівлі, вона спрямовує прибулих учнів і церковний люд між окремими крилами абатства: військовою Залою Зброї з одного боку, ученим Бібліотечним Крилом з іншого та сходами, що ведуть у вежу абатства. Тихе святилище зали затьмарює безперервна боротьба в долині, бо офіцери скликають дужих новоприбулих боронити кордони королівства."}},faq={{q="Для чого потрібна Головна Зала?",a="Головна Зала — центральна приймальня й перехрестя Абатства Нортшира. Звідси новобранців, жерців і гостей спрямовують до Зали Зброї, Бібліотечного Крила й верхньої вежі абатства.",al={"що таке головна зала","призначення головної зали нортшира"}},{q="Хто тут спрямовує новобранців?",a="Офіцери й клірики оборони Стормвінда в Головній Залі оцінюють новоприбулих шукачів пригод і дають їм перші накази — очистити землі абатства від загроз, що підступають.",al={"хто видає завдання тут","командир абатства"}}},fp="22,334,18.494.0,37.202.0,30.208.0"}
P.entries["subzone:maker-s-terrace"] = {n="Тераса Творця",s="Тераса Творця — розлогі розкопки просто неба на півночі Пустищ, перед самим входом до прадавнього сховища титанів Ульдаман. Мандрівникам, що йдуть на південь із Лох Модану, доводиться пробиратися її скелястими околицями, які агресивно утримують дворфи Темного Заліза. Ці розкопки — спірний поріг між пустирями на поверхні й таємницями титанів, похованими внизу.",h="Тераса Творця — розлогі розкопки просто неба на півночі Пустищ, перед самим входом до прадавнього сховища...",kw={"тераса творця","ульдаман","пустища","темне залізо","розкопки","титани"},ang={["profession:Mining"]="Розлогі кар'єри й земляні вали, вирізані в пісковикових скелях, мають явні сліди активного видобутку руди дворфськими копачами.",["race:Dwarf"]="Для дворфів Айронфорджа бачити Терасу Творця в руках підступного клану Темного Заліза — гірко, адже Ульдаман зберігає найглибші таємниці походження дворфів."},sec={{t="Поріг сховища",b="Тераса Творця, що розкинулася на північних кручах Пустищ, — зовнішній плацдарм перед підземними залами Ульдамана. Ще до того, як мандрівники спустяться в підземні руїни, їм доведеться подолати випалені сонцем земляні вали, риштування й кам'яні траншеї цих величезних розкопок. Тераса лежить просто біля перевалу, що спускається з Лох Модану, тож вона — перший орієнтир, який зустрічає кожного, хто наважиться вирушити в посушливі пустирі. Тут кипить жорстока робота: ворожі сили шукають шлях до прадавніх таємниць, похованих під скелею."},{t="Окупація Темного Заліза",b="Місцина міцно під чоботом клану Темного Заліза, який патрулює рови й околиці з ворожою пильністю. Приваблені запахом реліквій титанів і жагою панувати в надрах, ці підземні дворфи невпинно вгризаються в схил пагорба, шукаючи зброю, записи чи реліквії землян, які лишили по собі прадавні Творці. Кожен, хто спробує дістатися глибоких залів Ульдамана, не прорвавшись крізь ці укріплені пости, швидко опиниться в оточенні."}},faq={{q="Де розташована Тераса Творця?",a="Тераса Творця — на далекій півночі Пустищ, біля перевалу, що сполучає край із Лох Моданом. Вона оточує зовнішній вхід до давнього комплексу Ульдаману.",al={"розташування тераси творця","де тераса творця","як знайти терасу творця"}},{q="Хто тримає Терасу Творця?",a="Терасу зайняли й патрулюють ворожі дворфи Темного Заліза: вони ведуть тут розкопки й люто стережуть від чужинців зовнішній підступ до Ульдаману.",al={"хто на терасі творця","вороги тераси творця","хто контролює терасу творця"}},{q="Навіщо ці розкопки?",a="Дворфи Темного Заліза розкопують давній комплекс титанів Ульдаман. Вони прагнуть знайти реліквії, могутні механізми й давні таємниці титанів, поховані в підземних склепіннях, раніше за суперницькі фракції.",al={"навіщо тут копають","розкопки тераси творця","що шукає темне залізо"}},{q="Чи Тераса Творця — частина Ульдаману?",a="Так, Тераса Творця — це зовнішній відкритий котлован розкопок, що веде просто в підземелля й печери Ульдаману.",al={"чи це ульдаман","тераса творця й ульдаман","зв'язок тераси з підземеллям"}}},fp="15,402,22.586.0,20.471.0,37.203.0,33.169.0,38.225.0,35.127.0"}
P.entries["subzone:malaka-jin"] = {n="Малака'джин",s="Малака'джин — невеликий табір Орди в нижніх пагорбах Гір Кам'яного Кігтя, трохи південніше Застави Ґрімтотем. Тут живуть переважно мисливці-тролі з племені Темного Спису, а саме поселення — проста придорожня станція й мисливська застава для мандрівників, що підіймаються з Пусток у суворі гори.",h="Малака'джин — невеликий табір Орди в нижніх пагорбах Гір Кам'яного Кігтя, трохи південніше Застави Ґрімтотем.",kw={"малака'джин","тролі","темний спис","мисливці","застава орди","гори кам'яного кігтя"},ang={["faction:Horde"]="Малака'джин — найпівденніший поріг Орди в Кам'яному Кігті, важлива придорожня станція на шляху між Пустками та північними гірськими твердинями.",["race:Troll"]="Для тролів Темного Спису Малака'джин — гордий доказ тролячої самостійності й майстерності слідопитів: вони облаштували собі дім у суворих височинах, далеко від тропічних берегів Калімдору."},sec={{t="Притулок мисливців",b="Малака'джин, захований біля головного шляху в Гори Кам'яного Кігтя, дає жаданий прихисток мандрівникам Орди, що рушають у спірні височини. Тут живе ватага загартованих мисливців-тролів, які добувають собі прожиток серед скель і чагарників. Живуть вони скромно, але постачають припаси, продають утомленим шукачам пригод свіжу дичину й пильно стежать за ворожими гірськими звірами та войовничими тауренами Ґрімтотем, що чатують вище на стежках."},{t="Опора у височинах",b="Малака'джин, що примостився біля самого краю Пусток, — одна з найперших застав Орди в Кам'яному Кігті. Він невеликий і тихий порівняно з великою фортецею в Притулку Сонячної Скелі далі на півночі, але слугує важливою опорою для постачання: звідси слідопити Орди стежать за заворушеннями племен і захищають звивисті шляхи від загроз, що підступають."}},faq={{q="Що таке Малака'джин?",a="Малака'джин — невелике село й застава Орди на півдні Гір Кам'яного Кігтя. Тут живе громада мисливців — тролів Темного Списа, які дають прихисток, торгують і споряджають мандрівників, що піднімаються з Пусток.",al={"де малака'джин","що це за місце","малака'джин кам'яний кіготь"}},{q="Хто живе в Малака'джині?",a="Поселення населяють майже самі тролі-мисливці. Вони живуть із полювання на гірську дичину й торгують м'ясом і шкірою із заїжджими шукачами пригод.",al={"нпс малака'джина","хто тут","тролі кам'яного кігтя"}},{q="Що загрожує табору?",a="Окрім лютих гірських хижаків, село стоїть просто на південь від ворожої Застави Ґрімтотем, тож маленький тролівський табір мусить постійно бути напоготові перед ворожим племенем тауренів.",al={"вороги малака'джина","хто нападає на малака'джин"}},{q="Чи є тут розпорядник польотів?",a="Ні. У цю добу в Малака'джині немає розпорядника польотів. Мандрівникам Горами Кам'яного Кігтя доводиться покладатися на розпорядника польотів у Притулку Сонячної Скелі далі на північному заході або йти дорогою пішки.",al={"політ до малака'джина","майстер польотів малака'джина"}}},fp="10,305,17.479.0,25.373.0,19.227.0,24.169.0,27.211.0,30.203.0"}
P.entries["subzone:malden-s-orchard"] = {n="Сад Малдена",s="Сад Малдена — зруйнований хутір на півночі Срібнолісся, названий на честь господаря-людини, що втік під час навали Погибелі на Лордерон. Давно покинуті темні вічнозелені дерева заросли, а угіддями никають люті чорні ворги. Напівзруйнована хата в саду правила за тимчасовий прихисток розвідникові-Відступникові, якого відрізало від загону.",h="Сад Малдена — зруйнований хутір на півночі Срібнолісся, названий на честь господаря-людини, що втік під час...",kw={"сад малдена","ворги","ерланд маккрі","скрадачі смерті","хутір","срібнолісся"},ang={["faction:Horde"]="Мандрівникам, що йдуть на південь від Гробниці чи кордону Тірісфалю, варто обережно обходити сад: на фермі гніздяться агресивні зграї воргів.",["race:Undead"]="Для Відступників сад — нагадування про людську руїну й спірний клапоть північного Срібнолісся, який розвідники-скрадачі смерті мають відвоювати в диких звірів."},sec={{t="Сплюндрований сад",b="До Третьої війни ця садиба постачала свіжі фрукти містам Лордерона, а доглядав її фермер на ім'я Малден. Коли Погибель пройшлася королівством, Малден покинув свою землю, рятуючись від чуми. Відтоді сад задихається під темними туманами Срібнолісся, що підступають. Вічнозелені дерева стоять необрізані, плоди гниють незібраними на уражених гілках, і ділянку цілком відвоювали дикі хижаки."},{t="У пастці в хаті",b="Зарослий сад став мисливськими угіддями для чорних воргів, ревнивих до своєї території, тож шлях крізь північне Срібнолісся тут небезпечний. Під час розвідувальної місії скрадачів смерті розвідника Ерланда Маккрі послали оглянути місцевість, але звірі взяли гору. Кілька днів він сидів у пастці в напівзруйнованій хаті Малдена й вижив лише тому, що підкріплення Відступників прорвалося крізь зграю й провело його назад до товаришів-розвідників на Ділянці Івара."}},faq={{q="Хто такий Малден?",a="Малден — фермер-людина, що жив тут до падіння Лордерона. Коли під час Третьої війни Погибель вторглася в королівство, він покинув сад і втік, рятуючи своє життя.",al={"історія малдена","хто володів садом","хто такий малден"}},{q="Чому в саду повно воргів?",a="Живих господарів, щоб боронити садибу, не лишилося, тож дикі чорні ворги, що блукають Срібноліссям, забрали густий гай і покинуте подвір'я собі як мисливські угіддя зграї.",al={"чому в саду варги","пси саду малдена","навала варгів"}},{q="Хто застряг у хаті?",a="У хаті застряг Скрадач Смерті Ерланд Маккрі. Відступники послали його на розвідку, але на нього напали ворги з саду, і він сховався всередині, доки не надійшла допомога.",al={"розвідник у хаті","хто в хаті","скрадач смерті в халупі"}},{q="Чи збирає хтось тепер плоди в цьому саду?",a="Ні. Темні дерева роками ніхто не доглядав, і плоди гниють на гілках серед занепаду, що розповзається Срібноліссям.",al={"чи їстівні плоди","урожай саду малдена","чи можна збирати плоди"}}},fp="16,362,18.448.0,22.486.1,15.174.0,33.159.0,34.186.0,48.140.0"}
P.entries["subzone:mannoroc-coven"] = {n="Шабаш Маннорока",s="Шабаш Маннорока — руїни на півдні Пустограю, де кишать демони; назву їм дали на честь володаря безодні Маннорота. Цей осередок серед давніх споруд нічних ельфів — найбільша твердиня Палаючого Легіону в центральному Калімдорі. Культисти Палаючого Клинка підтримують тут діючі портали призову, наповнюючи задушену попелом землю псами Скверни, сукубами й інферналами.",h="Шабаш Маннорока — руїни на півдні Пустограю, де кишать демони; назву їм дали на честь володаря безодні...",kw={"шабаш маннорока","пустограй","палаючий легіон","палаючий клинок","демони","портали","рука іруксоса"},ang={["class:Warlock"]="Зосереджена енергія Скверни й діючі розломи призову Легіону роблять шабаш предметом пильного тактичного інтересу: тут можна власними очима спостерігати, як демонічна сила являє себе у світ.",["race:NightElf"]="Бачити, як демонічні загарбники сплюндрували й топчуть кам'яну кладку ваших давніх предків, — болісно; Шабаш Маннорока гірко нагадує про Війну Прадавніх."},sec={{t="Бастіон Вогню Скверни",b="Шабаш Маннорока, що лежить на південь від Застави Духоходів і на схід від Села Тіньової Здобичі, огортає давні руїни нічних ельфів гнітючою, отруєною Скверною млою. На місці шабашем командує Лорд Азреток разом із чорнокнижником Палаючого Клинка Джуґкаром Ґрім'родом. Удвох вони використовують діючі портали призову, щоб перетягувати демонічні підкріплення просто в Калімдор — зокрема вартових загибелі, інферналів і псів Скверни. І хоча мандрівники, прихильні до Орди, намагаються розірвати ці зв'язки за допомогою реліквій на кшталт Руки Іруксоса, крізь пошрамовану землю знову й знову розверзаються нові розломи."}},faq={{q="Чому це місце зветься Шабашем Маннорока?",a="Табір названо на шану Маннороту Руйнівнику — горезвісному володарю безодні, що поневолив орків кровним прокляттям і загинув в Ашенвалі.",al={"хто такий маннорок","походження назви маннорок","чому шабаш маннорока"}},{q="Хто править шабашем?",a="Демонічні сили тут очолює демон Лорд Азреток. Справами смертних заправляє Джуґкар Ґрім'род — чорнокнижник культу Палаючого Клинка.",al={"хто керує шабашем маннорока","бос шабашу маннорока","азретох"}},{q="На яких руїнах стоїть шабаш?",a="Демонічний табір займає напівзруйновані кам'яні підмурки давнього поселення нічних ельфів, яке лежало в руїнах задовго до того, як демони залили край магією Скверни.",al={"які руїни тут","стародавні руїни маннорока","ельфійські руїни дезоласу"}},{q="Як демони потрапляють у Пустограй?",a="Сектанти Палаючого Клинка підтримують серед руїн чарівні портали виклику. Крізь них з Викривленого Нижнього Світу безперервно прибуває підкріплення, тож усі спроби ззовні назавжди очистити це місце марні.",al={"звідки демони","портали палаючого клинка дезолас"}}},fp="14,360,21.572.0,40.165.0,25.152.0,36.169.0,40.217.0"}
P.entries["subzone:manor-mistmantle"] = {n="Маєток Містмантл",s="Маєток Містмантл — занепала садиба серед темних пагорбів північно-східного Сутінколісся, на північ від Даркшира. Колись це було пристойне родинне обійстя, а тепер — руїна й жах, де кишать гулі, прив'язані до її сумнозвісного господаря.",h="Маєток Містмантл — занепала садиба серед темних пагорбів північно-східного Сутінколісся, на північ від...",kw={"маєток містмантл","сталван містмантл","гулі","сльоза тіллоа","сутінколісся"},ang={["faction:Alliance"]="Для слідчих Альянсу, що з'ясовують похмуру долю жертв із Мунбрука й Ґолдшира, Маєток Містмантл — трагічний кінець легенди про Сталвана."},sec={{t="Сплюндрована садиба",b="Маєток Містмантл, що стоїть на захід від Притону Жебрака, — похмурий пам'ятник убивству й божевіллю. Подвір'я заполонив тлін, а довкола зруйнованої будівлі никають люті гулі, що її охороняють. Серед гнилі й зів'ялої рослинності єдина ознака живої краси на всій садибі — самотня сумна квітка в занедбаному саду: Сльоза Тіллоа."},{t="Господар маєтку",b="Маєток належить Сталванові Містмантлу — колишньому вчителеві й домашньому наставникові, чиї жахливі злочини в Мунбруку та Ґолдширі стали темною легендою по всьому королівству. Тепер, служачи нежиті, Сталван причаївся на горішньому поверсі родинного дому серед решток своїх жертв, під охороною шкандибаючих жахіть. Мандрівники й слідчі з Даркшира часто переконуються, що слід найсумнозвіснішого привида Сутінколісся обривається саме в цьому залитому кров'ю маєтку."}},faq={{q="Де розташований Маєток Містмантл?",a="Маєток Містмантл лежить на північному сході Сутінколісся, просто на північ від Даркширу й трохи на захід від Притону Жебрака.",al={"розташування маєтку містмантл","де маєток містмантл","як знайти маєток містмантл"}},{q="Хто живе в Маєтку Містмантл?",a="Маєток належить Сталвану Містмантлу — колишньому вчителеві, який нині існує як нежить в оточенні гулів.",al={"хто в маєтку містмантл","бос маєтку містмантл","дім сталвана"}},{q="Що таке Сльоза Тіллоа?",a="Сльоза Тіллоа — самотня ніжна квітка, що цвіте в саду Маєтку Містмантл: єдина вціліла ознака живої природи серед зотлілих угідь.",al={"квітка сльози тіллоа","квітка саду містмантл","квітка тіллоа"}},{q="Чому угіддя охороняє нежить?",a="Гулі, що блукають угіддями маєтку, — прислужники, прив'язані до Сталвана Містмантла: вони захищають свого господаря й убивають кожного, хто наважиться вдертися до його проклятого маєтку.",al={"чому гулі в містмантл","нежить містмантл","вороги маєтку містмантл"}}},fp="16,239,20.393.0,24.491.1,34.132.0,30.115.1,27.177.0,42.173.1"}
P.entries["subzone:mardenholde-keep"] = {n="Фортеця Марденгольд",s="Фортеця Марденгольд — велична кам'яна цитадель, що височіє над Гартгленом на півночі Західних Чумних Земель. Колись це було родове гніздо Верховного Лорда Тіріона Фордрінга, а нині тут штаб фанатичного Багряного Хрестового Походу в цьому краї, яким править його син, Верховний Лорд Телан Фордрінг.",h="Фортеця Марденгольд — велична кам'яна цитадель, що височіє над Гартгленом на півночі Західних Чумних Земель.",kw={"фортеця марденгольд","гартглен","тіріон фордрінг","телан фордрінг","срібний світанок","срібна длань"},ang={["class:Paladin"]="Марденгольд — трагічна сторінка в історії паладинів. Колись він був шляхетним прихистком Срібної Длані, а саме в його залах орден розколовся на фанатичний Багряний Хрестовий Похід і пильний Срібний світанок.",["race:Human"]="Для лордеронців Марденгольд — гірке нагадування про те, як найславетніші твердині їхньої батьківщини вистояли в оркських війнах лише для того, щоб піддатися божевіллю й фанатизму в часи Погибелі."},sec={{t="Осідок Фордрінгів",b="Фортецю Марденгольд звели як серце гартгленських володінь, і лордеронці довго пишалися тим, що за всю Другу війну її мурів так і не пробили. У її залах ради Верховний Лорд Тіріон Фордрінг разом із вірними радниками правив довколишніми долинами й беріг мир — аж до гучного суду й вигнання за те, що став на захист орка Ейтріґґа. Після падіння Тіріона влада перейшла до його честолюбного учня Бартіласа, а згодом — до Тіріонового сина Телана, який успадкував батькові землі напередодні загибелі Лордерону."},{t="Колиска Хрестового Походу",b="Коли Погибель прокотилася Лордероном, Телан відчинив Марденгольд для вцілілих командирів Лицарів Срібної Длані, серед яких були Александрос Моґрейн і Сайдан Датроган. У цих залах рештки ордену замишляли опір нежиті. Та взаємна підозріливість і чиїсь темні підступи невдовзі розкололи братство. Коли після загибелі Моґрейна посипалися звинувачення у зраді, Максвелл Тайросус відколовся й заснував Срібний світанок, а Датроган із рештою фанатиків перетворив Гартглен на укріплений оплот новоствореного Багряного Хрестового Походу."}},faq={{q="Хто зараз тримає Фортецю Марденгольд?",a="Фортеця в руках Багряного Хрестового Походу й слугує його головним військовим штабом у Західних Чумних Землях. Нею безпосередньо керує Верховний Лорд Телан Фордрінг, що перебуває в головній залі в оточенні добірних багряних охоронців.",al={"хто керує марденгольдом","хто головний у фортеці гартглен","бос марденгольда"}},{q="Чому ця фортеця така важлива для Тіріона Фордрінга?",a="Марденгольд — родове гніздо Тіріона Фордрінга, звідки він, паладин Альянсу, правив цим краєм. У її стінах він ростив родину, доки його не позбавили титулів і не вигнали за те, що він заступився за шляхетного ворога.",al={"зв'язок тіріона з марденгольдом","чи жив тут тіріон"}},{q="Як Багряний Хрестовий Похід захопив Марденгольд?",a="Після вигнання Тіріона й падіння Лордерона в Третій війні його син Телан віддав фортецю під прихисток уцілілим паладинам Срібної Длані. Під впливом командирів на кшталт Сайдана Датрогана Телан присягнув гарнізоном Гартглена їхньому новому радикальному орденові.",al={"як багряний похід узяв гартглен","чому багряний похід тут"}},{q="Чи можуть гравці безпечно увійти до Фортеці Марденгольд?",a="Ні. Багряний Хрестовий Похід вважає всіх чужинців можливими носіями чуми чи ворогами своєї справи. На будь-якого шукача пригод, що наблизиться до фортеці, нападуть одразу — хіба що його приховує могутня магія ілюзій.",al={"чи дружній марденгольд","чи може альянс зайти в марденгольд","чи може орда зайти в марденгольд"}}},fp="16,306,21.581.0,21.597.1,40.234.0,53.235.0,50.266.0,42.225.0"}
P.entries["subzone:marris-stead"] = {n="Садиба Марріса",kw={"садиба марріса","натанос блайткаллер","натанос марріс","відступники","рейнджер","рамштайн жерун","si:7"},ang={["faction:Horde"]="Для Відступників і їхніх союзників з Орди садиба — безцінна й надійно захищена база для війни проти Погибелі й Багряного Хрестового Походу."},sec={{t="Зруйнований дім рейнджера",b="До Третьої війни ця садиба належала Натаносу Маррісу — славетному стрільцеві, єдиному людському лорду-рейнджеру, якого прийняли до Далекоходів. Коли після падіння Стратгольма Погибель пройшлася Лордероном, жахлива гидота Рамштайн Жерун загнала Натаноса в кут і вбила просто в його власному домі. Піднятий як безвольний раб Короля-Ліча, він згодом потрапив до рук рейнджерів Сильвани Віндраннер, які його визволили: Натанос вирвався з-під влади Погибелі й став одним із Відступників."},{t="Оплот Поборника",b="Тепер він називає себе Натаносом Блайткаллером і повернувся на родинний хутір разом зі зграєю лютих чумних псів. За наказом Королеви Баньші він координує удари по всіх Чумних Землях — і проти Погибелі, і проти Багряного Хрестового Походу. Хутір привернув і похмуру увагу розвідки Стормвінда: агентів SI:7, яких послали розслідувати дії Відступників тут, вирізали. Так Альянс дізнався про жахливе перетворення Натаноса й призначив за його голову чималу винагороду."}},faq={{q="Хто живе в Садибі Марріса?",a="The homestead is occupied by Nathanos Blightcaller. He resides here accompanied by his pack of blighthounds, serving as a frontline commander and Champion of the Banshee Queen.",al={"хто в садибі марріса","хто тут живе","нпс на фермі","де натанос"}},{q="Як Натанос став нежиттю?",a="The Scourge devastated Lordaeron during the Third War, raising many of its victims as undead. Nathanos's own history and release from Scourge control are explored in the protected section.",al={"як натанос помер","смерть натаноса","хто вбив натаноса"}},{q="Чому ця ферма цікавить Альянс?",a="SI:7 spymaster Mathias Shaw received disturbing reports of unusual Forsaken activity and sent agents to investigate. When only one returned, further investigators were sent to learn what happened to the others.",al={"альянс садиба марріса","сі:7 чумні землі","чому вбити натаноса"}},{q="Які артефакти зберігаються в хаті?",a="У зруйнованій хаті зберігається кілька історичних реліквій з трагічної Битви за Дарроушир — зокрема Лібрам Девіла Крокфорда й Щит Редпата, зібрані серед боїв, що й досі тривають у Чумних Землях.",al={"предмети садиби марріса","реліквії в хаті","реліквії дарроуширу"}}},fp="12,267,22.511.1,22.543.1,26.176.0,31.188.0,44.210.1,41.214.0"}
P.entries["subzone:marshal-s-refuge"] = {n="Притулок Маршала",s="Притулок Маршала — хиткий нейтральний прихисток, що тулиться в північних кручах Кратера Ун'Ґоро. Його заснували Вілліден Маршал і члени його експедиції як аварійний оплот після того, як первісні звірі западини розгромили їхні нижні табори.",h="Притулок Маршала — хиткий нейтральний прихисток, що тулиться в північних кручах Кратера Ун'Ґоро.",kw={"притулок маршала","вілліден маршал","експедиція","ун'ґоро","нейтральний табір","дослідники"},ang={["class:Hunter"]="Притулок безпечно примостився над дном кальдери, тож мисливці можуть із висоти вивчати найрідкісніших і найсмертоносніших звірів Ун'Ґоро, перш ніж спуститися на мисливські угіддя.",["race:Gnome"]="Учені-гноми й польові інженери вважають Притулок ідеальною базою, щоб випробовувати свої прилади на химерних кристалах сили й непередбачуваних гейзерах кратера."},sec={{t="Гніздо над прірвою",b="Коли Вілліден і Гол'аньї Маршал повели свою експедицію в Кратер Ун'Ґоро, вони тяжко недооцінили лютість його доісторичних мешканців. Після того як розлючені звірі знову й знову трощили їхні перші табори, побиті вцілілі видерлися на печеристі північні скелі, рятуючись від різанини. Відбудований як Притулок Маршала, табір чіпляється високо над дном джунглів і дає втомленим дослідникам на півночі кратера єдине надійне місце для відпочинку, найнеобхідніші припаси й повітряне сполучення з рештою світу."},{t="Перехрестя допитливих",b="Кратер Ун'Ґоро ховає прадавні біологічні дива й загадкові кристалічні утворення, тож Притулок Маршала приваблює строкату ватагу дослідників, шукачів щастя й дивакуватих мандрівників. Натуралісти і з Альянсу, і з Орди — серед них посланці тауренів і гномські майстри-механіки — ділять тісний уступ із рештою команди Маршала. Звідси розвідники вирушають до вулканічних вершин, як-от Хребта Вогняного Шлейфу, чи до вируючих пам'яток на кшталт Гарячих Джерел Ґолакка, сподіваючись описати первісну глушину, перш ніж та їх поглине."}},faq={{q="Чому Притулок Маршала збудували так високо на скелі?",a="Спершу експедиція Маршалів ставила табори нижче, в улоговині, але люті динозаври й агресивні звірі Ун'Ґоро раз у раз їх топтали й руйнували. Уцілілі відступили на північну скельну стіну, щоб зайняти зручне для оборони місце, куди не дістануть великі звірі.",al={"чому притулок маршала на скелі","розташування притулку маршала","чому табір на скелі"}},{q="Чи привітний Притулок Маршала і до Орди, і до Альянсу?",a="Так. Це нейтральна застава. Прадавні небезпеки Кратера Ун'Ґоро роблять ворожнечу фракцій недозволеною розкішшю, тож представники обох фракцій мирно поповнюють тут припаси й обмінюються результатами досліджень.",al={"чи нейтральний притулок маршала","чи орда може сюди","чи альянс може сюди"}},{q="Хто очолює табір?",a="Заставу очолюють Вілліден Маршал і Гол'аньї Маршал — ті, хто організував невдалі Експедиції Маршалів у кратер.",al={"хто головний","хто керує притулком маршала","лідер табору"}},{q="Які послуги є в Притулку?",a="Притулок дає найнеобхідніше для виживання в цій віддаленій улоговині: розпорядників польотів для обох фракцій, звичайних крамарів, ремонт і місце, де збираються дослідники, що пропонують винагороди й розвідки по всьому кратеру.",al={"політ","ремонт","торговці"}}},fp="16,250,18.523.0,25.535.0,52.295.0,56.206.0,25.138.0,42.248.0"}
P.entries["subzone:marshlands"] = {n="Мочарі",s="Мочарі — розлоге драгове болото в південно-східній частині Кратера Ун'Ґоро. Воно лежить просто біля підніжжя звивистого схилу, що веде з Танарісу, тож нерідко стає першою глушиною, яку бачать новоприбулі в первісній западині.",h="Мочарі — розлоге драгове болото в південно-східній частині Кратера Ун'Ґоро.",kw={"мочарі","болото","раптори","сині кристали сили","торва патфайндер","мор'век","ун'ґоро"},ang={["class:Hunter"]="Мочарі — справжній полігон для виживання в дикій природі: тут повно прудких рапторів, отруйних хижаків і рідкісних звірів, а досвідчені слідопити на кшталт Торви Патфайндера підкажуть, як на них полювати.",["profession:Herbalism"]="Північні краї болота заполонили агресивні паростки кровопелюсток і волога зелень, тож тут добре видно, якою ворожою й рухливою буває місцева рослинність."},sec={{t="Ворота до кратера",b="Хто спускається крутою стежкою з посушливих просторів Танарісу, потрапляє просто у вологу драговину Мочарів. Будь-де інде на прямовисному краю кратера можна смертельно розбитися, тож ця підступна смуга боліт — головний поріг Ун'Ґоро. Густий полог дерев, стояча вода й грязюка ховають численні зграї лютих рапторів, зокрема отруйних, що крадуться в очереті. На вологих галявинах дослідники знаходять розсипані по землі Сині кристали сили, які трапляються лише в цій частині кратера."},{t="Табори на болоті",b="Попри постійну загрозу хижаків, кілька самотніх знавців дикої природи тримають на болоті свої застави. З високого земляного пагорба таурен Торва Патфайндер і його товариш Ґарл Стормклоу, які дісталися западини на каное, наглядають за первісною живністю. А по той бік боліт троль Мор'век вивчає й приручає місцевих равазаврів."}},faq={{q="Чому Мочарі зазвичай перше, що бачать в Ун'Ґоро?",a="Прямовисні скелі довкола Кратера Ун'Ґоро роблять будь-який спуск, окрім південно-східного перевалу з Танарісу, майже напевно смертельним. А пандус із перевалу веде просто в Мочарі, тож усі, хто мандрує суходолом, проходять крізь ці мокрі хащі.",al={"як зайти в ун'ґоро","вхід у кратер ун'ґоро","вхід у мочарі"}},{q="Які істоти тут найпоширеніші?",a="Мочарі славляться великою кількістю рапторів — і звичайних мисливців, і смертельно отруйних, здатних здолати необачних дослідників у густих заростях.",al={"звірі мочарів","раптори мочарів","хто тут живе"}},{q="Які унікальні ресурси є в Мочарях?",a="Мочарі — єдине місце в Кратері Ун'Ґоро, де природно утворюються Сині Кристали Сили. Ці сяйні уламки мінералів цінують дослідники, які вивчають загадкові кришталеві пілони, розкидані по всій улоговині.",al={"сині кристали сили","кристали мочарів","сині кристали ун'ґоро"}},{q="Хто такий Торва Патфайндер?",a="Торва Патфайндер — досвідчений тауренський мисливець, що стоїть табором на високому пагорбі в Мочарях разом із Ґарлом Стормкловом. Він вивчає природу кратера й спрямовує вправних шукачів пригод проти найлютіших звірів Ун'Ґоро.",al={"торва","табір торви патфайндер"}},{q="Чи можна приручити чи вишколити тутешніх равазаврів?",a="Так. Мор'век, троль, що живе в Мочарях, знається на догляді й вирощуванні місцевих равазаврів і може багато розповісти про їхню агресивну вдачу й інстинкти.",al={"навчач равазаврів","морвек","приборкати равазавра"}}},fp="10,248,21.540.0,22.362.0,67.252.0,36.190.0,50.222.0,24.227.0,43.162.0"}
P.entries["subzone:mast-room"] = {n="Щоглова Кімната",s="Щоглова Кімната — простора підземна лісопильня глибоко в Мертвих Копальнях. Тут під наглядом гобліна Сніда та його теслів обробляють деревину, вирубану у Вестфолі.",h="Щоглова Кімната — простора підземна лісопильня глибоко в Мертвих Копальнях.",kw={"щоглова кімната","лісопильня","снід","деревина","мертві копальні"},ang={["faction:Alliance"]="Деревина, яку обробляють у цій залі, доводить: грабунки Дефіас по всьому Вестфолу — не простий розбій, а злагоджена промислова справа.",["profession:Engineering"]="Гоблінський потрощувач, яким тут керує Снід, — диво грубої техніки з пари й шестерень, яку з лісоповалу переробили на знаряддя проти непроханих гостей."},sec={{t="Підземна лісопильня",b="За глибшими тунелями Мертвих Копалень лежить Щоглова Кімната — величезна печера, перетворена на справжню лісопильню. Простір заповнюють штабелі зрубаних колод, тирса й громіздкі пильні верстати. Саме тут гобліни-теслі виготовляють велетенські щогли, шпангоути й дошки для бойового корабля, захованого далі, у Бухті Айронклад. Під пильним оком Сніда Братство Дефіас перетворює деревину з Вестфолу на знаряддя війни."},{t="Промислова праця",b="Ця зала — гоблінська промисловість у найбезжальнішому вигляді. Снід керує роботою з механічного потрощувача, стежачи, щоб теслі виконували виснажливі норми. Величезні колоди одну за одною піднімають і обстругують, і колишня сонна золота копальня перетворюється на гуркітливу, закіптюжену корабельню."}},faq={{q="Звідки в підземній шахті лісопилка?",a="Братство Дефіас потай будує величезний бойовий корабель у бухті під копальнями. У Щогловій Кімнаті збирають і обтесують щогли, каркас і обшивку корабля з деревини, яку потай привозять із поверхні Вестфолу.",al={"чому тут лісопилка","чому дерево в мертвих копальнях","призначення щоглової кімнати"}},{q="Хто керує Щогловою Кімнатою?",a="Залою заправляє Снід — гоблін, майстер-ремісник, що керує гоблінами-різьбярами, сидячи за кермом смертоносної механічної лісорізки.",al={"бос щоглової кімнати","хто керує щогловою кімнатою","хто такий снід"}},{q="Чому тут на Дефіас працюють гобліни?",a="Едвін Венкліф найняв гоблінів-інженерів і ремісників заради технічних знань, яких бракувало людям-каменярам. Гобліни дають важкі машини, вибухівку й уміння будувати кораблі в обмін на золото й зиск.",al={"чому гобліни працюють на дефіас","гобліни мертвих копалень"}}},fp="9,203,23.487.1,16.324.1,54.252.1,23.146.0,44.217.1"}
P.entries["subzone:master-s-cellar"] = {n="Льох Володаря",s="Льох Володаря — розлогий підземний комплекс під зруйнованим поселенням на південь від Каражану на Перевалі Мертвого Вітру. Колись тут були винні льохи й комори маєтку Медіва, а тепер це примарні руїни, що кишать неспокійними привидами колишніх слуг і доглядачів.",h="Льох Володаря — розлогий підземний комплекс під зруйнованим поселенням на південь від Каражану на Перевалі...",kw={"льох володаря","каражан","медів","привиди","перевал мертвого вітру","печери"},ang={["class:Mage"]="Примарні рештки під маєтком Стража свідчать про страшну таємну віддачу, що вирвалася на волю, коли Медів упав, і перетворила звичайні господарські льохи на вузол залишкової примарної енергії.",["class:Priest"]="Змучені привиди, ув'язнені в сирих склепіннях, — трагічні душі простих доглядачів і слуг, яким прокляття, що досі тяжіє над Перевалом Мертвого Вітру, не дає спокою."},sec={{t="Примарне черево Каражану",b="Трохи на південь від велетенської вежі Каражан лежать руїни селища, де колись жили слуги, садівники й челядь, що доглядали маєток Медіва. Під цими розваленими будинками й ховається Льох Володаря. До нього ведуть два окремі входи з руїн на поверхні, а сам комплекс тягнеться далеко під землю. Один вхід відкривається в просторий склепінчастий винний льох, а другий спускається крізь обвалену кладку в глибокі природні печери. Хай яка темна доля спіткала Каражан і його господаря, вона поглинула й цей підвал, залишивши немертвих доглядачів, привидів, що завивають, і проклятих душ у нескінченній службі."},{t="Нижні печери",b="Найглибші закутки комплексу, що звуться Нижнім Льохом, показують, де підлога льоху провалилася в непорушну скелю Перевалу Мертвого Вітру. Фундамент льоху обвалився в ці печери, утворивши зубчастий лабіринт, де лунає примарне виття. Хоча шукачі пригод, що досліджують Перевал, рідко зустрічають тут живих, всепроникна магічна скверна, що сочиться з сусідньої вежі, міцно прикувала цих привидів до каменю, тож печери не менш небезпечні, ніж руїни нагорі."}},faq={{q="Для чого спершу використовували Льох Володаря?",a="Це були головні комори й винні льохи вежі Каражан. У селі нагорі жили слуги й доглядачі угідь, що утримували розлоге господарство Вартового Медіва, а в підземних склепіннях зберігали харчі й бочки витриманого вина.",al={"призначення льоху володаря","що це за льох","чому тут винний льох"}},{q="Чому в льоху повно привидів?",a="Ніхто напевно не знає, що з ними сталося. Яка б темна доля не спіткала Каражан і його господаря, вона забрала й село, і слуги та селяни, що колись тут жили, тепер блукають руїнами неспокійними тінями, завивальними примарами й неживими доглядачами.",al={"чому в льоху привиди","хто нежить у льоху","чому льох володаря з привидами"}},{q="Як потрапити до печер під льохом?",a="Серед зруйнованих будівель на південь від Каражану є два окремі входи до льохів. Східний веде у впорядкований винний льох, а західний спускається в обвалену частину кладки, звідки можна потрапити в природні підземні печери Нижнього Льоху.",al={"як зайти в нижній льох","входи в льох володаря","де вхід у печеру"}},{q="Чи сполучений Льох Володаря безпосередньо з Каражаном?",a="Ні. Попри близькість до підніжжя вежі й колишню роль комори маєтку Вартового, підземні зали не мають відкритого проходу до самого Каражану. Льох — окремий світ під руїнами села.",al={"чи веде льох володаря в каражан","вхід у каражан із льоху"}}},fp="15,302,30.662.0,17.508.0,49.272.0,33.256.0,52.288.0,70.251.0"}
P.entries["subzone:master-s-glaive"] = {n="Глефа Володаря",s="Глефа Володаря — давня моторошна пам'ятка в південно-західній частині Темного Узбережжя, де велетенська адамантитова зброя стирчить, устромлена в колосальний скам'янілий череп. Місцеві нічні ельфи здавна шанували це місце як священну таємницю, але тепер тут кишать культисти Молота Присмерку, яких приваблює залишкова злоба давньої сутності.",h="Глефа Володаря — давня моторошна пам'ятка в південно-західній частині Темного Узбережжя, де велетенська...",kw={"глефа володаря","скам'янілий череп","молот присмерку","ону","темне узбережжя"},ang={["race:NightElf"]="Поколіннями нічні ельфи вважали цей дивний скам'янілий пам'ятник урочистим святим місцем, тож нинішнє вторгнення культу Молота Присмерку — нестерпне осквернення священної землі Темного Узбережжя."},sec={{t="Пам'ятник давньої битви",b="Глефа Володаря, що здіймається із землі Темного Узбережжя, — масивне адамантитове лезо, глибоко встромлене в колосальний скам'янілий череп. Жоден запис не називає ні істоти, що загинула тут, ні руки, що вгородила лезо. Ону, Древо Знань, каже лише, що на цьому місці впав старий-престарий володар землі, а нічні ельфи довго вірили, що таку велетенську зброю могли тримати лише титани. Сьогодні пробитий моноліт стоїть суворим скам'янілим пам'ятником тієї забутої боротьби."},{t="Темні розкопки",b="Хоч нічні ельфи поколіннями шанували це місце, нещодавно його захопили зловісні сили. Фанатики культу Молота Присмерку отаборилися довкола занурених у землю решток, риючи траншеї й відкопуючи скам'янілі ребра. Приваблені шепотом з-під каменю, культисти одержимо вивчають рештки й єднаються зі злою силою, що досі чіпляється за давні кістки, прагнучи відродити чи підкорити ту мерзенну сутність, що дрімає в землі."}},faq={{q="Що за величезна зброя застрягла в черепі?",a="Напевно ніхто не знає. Велетенське адамантинове лезо — це й є сама Глефа Володаря, увігнана в череп у якусь забуту добу. Нічні ельфи вірили, що зброєю такого розміру могли б орудувати лише титани.",al={"що за меч","меч глефа володаря","хто встромив меч"}},{q="Чий череп тут похований?",a="Його ім'я загубилося. Ону, Древо Знань, каже лише, що тут упав якийсь давній-предавній володар землі, а Молот Присмерку вважає, що скам'янілі рештки належать слузі Древніх Богів.",al={"що тут померло","чий череп похований біля глефи володаря"}},{q="Чому тут зібрався культ Молота Присмерку?",a="Культ Молота Присмерку поклоняється Древнім Богам. Сектанти заполонили Глефу Володаря, щоб відкопати скам'янілі рештки: їх вабить темна сила, що досі тут жевріє, і вони сподіваються повернути полеглу істоту до життя.",al={"чому тут культисти","молот присмерку темний берег","що копають культисти"}},{q="Хто знає історію цього місця?",a="Ону, Древо Знань, що живе на Темному Узбережжі, впізнає в цьому місці останній спочинок давнього володаря землі й просить дослідників з'ясувати більше.",al={"хто вивчає глефу"}}},fp="15,333,30.490.0,16.506.0,46.219.0,37.192.0,48.207.0,41.160.0"}
P.entries["subzone:maul-subzone"] = {n="Паща (підзона)",s="Паща — заглиблена бійцівська арена на Зруйнованому Майдані біля руїн Лютопащу у Фераласі. Колись це була велична споруда прадавнього ельфійського Елдре'Таласу, а нині — некерований ринг кривавих забав, де мандрівники б'ються за славу чи за власне життя проти лютих звірів і суперників.",h="Паща — заглиблена бійцівська арена на Зруйнованому Майдані біля руїн Лютопащу у Фераласі.",kw={"паща","арена","зруйнований майдан","лютопащ","гладіатори","фералас"},ang={["class:Warrior"]="Для воїнів, що шукають справжнього бою поза влаштованими полями битв, Паща пропонує неприкрашені криваві забави, де виживання вирішують лише власна вправність і товста броня.",["race:NightElf"]="Бачити, як горду архітектуру прадавнього Елдре'Таласу обернули на кишучу ограми яму для страт, — гірке й болісне нагадування про те, як низько впала цивілізація Високородних."},sec={{t="Заглиблена яма",b="Вирубана глибоко в камені Зруйнованого Торгових Рядів, Паща колись служила Високородним Елдре'Таласу театром чи обрядовою ареною. Після Розколу й подальшого захоплення ограми Ґордок яма перетворилася на грубий колізей. Як і славнозвісна Арена Ґурубаші в далекій Долині Стренглторну, на піску Пащі всі союзи втрачають силу: бійці опиняються в беззаконній сутичці всіх проти всіх, де межі фракцій зникають, а виживання залежить лише від бойової вправності."},{t="Звірі й кровопролиття",b="Тим, хто спускається на арену, варто добре обміркувати, як саме. Сміливці часто стрибають просто з високих уступів майдану, але падіння дається взнаки. Безпечніша західна арка веде тунелями, де дрімають гієни Ґордок, — це єдиний пішохідний вихід із бойового майданчика. Час від часу в яму виходять небезпечні звірі й сумнозвісні гладіатори, тож кожен спуск — непередбачуване випробування сталі й чуття."}},faq={{q="Чому тут я можу нападати на членів своєї ж фракції?",a="Паща — це бійцівська яма без законів, на кшталт Арени Ґурубаші в Долині Стренглторну. Щойно ви ступаєте на її пісок, звичні угоди й перемир'я між фракціями втрачають силу, і бійці можуть битися з усіма, хто не входить до їхньої групи.",al={"вільний пвп лютопащ","арена без правил","чому я можу бити орду"}},{q="Як безпечно потрапити до Пащі й вибратися звідти?",a="Можна зістрибнути просто зі Зруйнованого Торгових Рядів, але так легко добряче забитися. Найбезпечніше — крізь двері на західному боці майдану: вони ведуть тунелем повз сплячих гієн Ґордок. Цей тунель — і єдиний шлях, яким можна вибратися назад пішки.",al={"як зайти в пащу","вхід у пащу","вихід із пащі"}},{q="Які вороги з'являються на арені?",a="Окрім суперників — інших шукачів пригод, — до ями часом забредають екзотичні й люті супротивники: величезний грибний велетень Мушґоґ, химера на ім'я Разза й лютий гладіатор Скарр Незламний.",al={"рідкісні на арені","хто з'являється в пащі","боси пащі"}},{q="Для чого спершу використовували цю арену?",a="До того, як Розкол зруйнував давній Калімдор, цей кам'яний колізей належав великому місту Високородних — Ельдре'Таласу. Огри Ґордок, що вдерлися сюди, пристосували давню ельфійську споруду під криваву арену на свій дикунський смак.",al={"історія пащі","хто збудував пащу","арена ельдре'таласу"}}},fp="14,297,14.496.0,20.468.0,48.270.0,41.288.0,42.219.0,40.240.0"}
P.entries["subzone:mazthoril"] = {n="Мазторіл",s="Мазторіл — величезна, скута морозом печера в центрі Вінтерспрінгу, головна твердиня синього драконячого роду в північному Калімдорі. Її пильно стережуть драконоподібні, змії-чародії та магічні вартові, а звивисті крижані тунелі приховують могутню магію й ведуть до гнізда Гале, відлюдної праматері синіх драконів.",h="Мазторіл — величезна, скута морозом печера в центрі Вінтерспрінгу, головна твердиня синього драконячого роду...",kw={"мазторіл","сині дракони","малігос","гале","лігво оніксії","вінтерспрінг","евірлук"},ang={["class:Mage"]="Мазторіл — володіння слуг Малігоса, і він аж кишить створіннями, наскрізь просякнутими чистою таємною магією, тож для дослідників таємних мистецтв це місце надзвичайно цікаве."},sec={{t="Оплот синіх драконів",b="Carved into the frozen mountains just south of Everlook, Mazthoril houses an extensive brood answering to the Spell-Weaver, Malygos. The cavern and its surrounding crags are patrolled by vigilant dragonkin including Spellmaw, Azurous, and General Colbatann, while elite guardians watch the inner caverns. Intruders who wander into Mazthoril face dragonspawn thoroughly attuned to raw arcane energy, making any venture inside perilous without serious preparation."},{t="Руна перенесення і праматір",b="Глибоко в крижаному лабіринті лежить містична руна на підлозі, яку пильно стережуть дракони Манакло й Провидець. Хто ступить на руну, того перенесе до відлюдного гірського гнізда над печерою. Там живе Гале — праматір синього роду, яка ходить у подобі високої ельфійки. Хоч вона з природи остерігається смертних, Гале знає чимало про драконячі родоводи й відіграє вирішальну роль у тому, щоб зняти приховані чари, які захищають Лігво Оніксії."}},faq={{q="Хто править Мазторілом?",a="Мазторілом опікується Гале — могутня матріарх синіх драконів. Вона живе у відокремленому гнізді високо над печерами, куди можна потрапити лише через чарівну руну телепортації в глибині тунелів. Смертних гостей вона зустрічає в подобі високої ельфійки.",al={"хто керує мазторілом","бос мазторіла","матріарх мазторіла"}},{q="Чому сині дракони живуть у Вінтерспрінгу?",a="Синій драконячий рід, якому титани доручили берегти чарівну магію Азероту, пильно стежить за давніми джерелами енергії по всьому світу. У Вінтерспрінгу довкола Озера Кел'Теріл лишилися рештки давньої цивілізації Високородних, тож Мазторіл — природна твердиня для їхніх вартових у Калімдорі.",al={"чому дракони у вінтерспрінгу","чому тут синій політ","виводок малігоса вінтерспрінг"}},{q="Як дістатися до Гале?",a="Щоб дістатися до Гале, доведеться пробитися крізь драконячих створінь у глибину внутрішньої печери Мазторілу. Там, між драконами Манакло й Провидцем, на підлозі сяє чарівна руна. Ставши в її центр, ви перенесетеся до гнізда Гале на вершині гори.",al={"дістатися до гале","потрапити до гале","телепорт до гале","де гале"}},{q="Яку роль відіграє Мазторіл у тому, щоб увійти до Лігва Оніксії?",a="Alliance heroes investigating Onyxia's protections are sent to consult Haleh. Her part in that journey is explored in the protected section.",al={"ключ оніксії мазторіл","допуск до оніксії гале","амулет вогню дракона гале"}}},fp="9,330,25.462.0,40.462.1,20.292.0,44.320.0,23.273.0,56.140.2"}
P.entries["subzone:menethil-bay"] = {n="Затока Менетіл",s="Затока Менетіл — захищена водойма вздовж західного узбережжя Багнокраю, між Гаванню Менетіл і стрімкими північними кручами Дун Мороґа. Вона відкривається в ширшу Затоку Барадін, і в її водах живуть агресивні кроколіски й лежать рештки затонулих кораблів. Це головний морський підхід для суден Альянсу, що ходять між Східними Королівствами й Калімдором.",h="Затока Менетіл — захищена водойма вздовж західного узбережжя Багнокраю, між Гаванню Менетіл і стрімкими...",kw={"затока менетіл","гавань менетіл","затока барадін","кроколіски","летюча скопа","багнокрай"},ang={["faction:Alliance"]="Затока Менетіл — життєво важливий морський підхід до Гавані Менетіл, що оберігає крихкий морський шлях, який пов'язує Айронфордж і Стормвінд із Калімдором."},sec={{t="Захищені води Багнокраю",b="Частина більшої Затоки Барадін на узбережжі Великого Моря, Затока Менетіл утворює природну бухту, яку на півночі облямовує Гавань Менетіл, на сході — Багно Чорного Каналу, а на півдні — високі прибережні кручі Дун Мороґа. На її мілких берегах і болотистих узбережжях кишать кроколіски різного віку й розміру, тож мілина підступна для мандрівників без провідника, хоч затока й живить морське сполучення Альянсу. Біля входу до затоки лежать розтрощені уламки «Летючої Скопи» — мовчазне нагадування про небезпеки, що чигають під поверхнею."}},faq={{q="Де саме розташована Затока Менетіл?",a="Затока Менетіл лежить на західному узбережжі Багнокраю, у межах ширшої Затоки Барадін: на півночі її обмежує Гавань Менетіл, на сході — Багно Чорного Каналу, а на півдні — північні гірські скелі Дун Мороґу.",al={"де затока менетіл","розташування затоки менетіл","затока багнокраю"}},{q="Хто живе в Затоці Менетіл?",a="На болотистих берегах і мілких затоках аж кишать кроколіски різних розмірів. Вони нападають на необачних плавців, а шкірники часто полюють на них заради цінних шкур.",al={"моби затоки менетіл","що в затоці","кроколіски затоки менетіл"}},{q="Що за затонулий корабель у затоці?",a="Уламки біля входу до Затоки Менетіл — це «Летюча скопа», загублене судно, що лежить під прибережними водами на підходах до гавані.",al={"корабель-уламок затока менетіл","летючий скопа","затонулий корабель багнокраю"}},{q="Чому затока важлива для Альянсу?",a="Затока прикриває Гавань Менетіл — головну морську браму, що сполучає Айронфордж і північні землі Каз Модану з Калімдором і півднем. Транспортні кораблі, що ходять до Терамора й Темного Узбережжя та назад, мусять проходити цими водами.",al={"чому затока менетіл важлива","порт альянсу багнокрай","вода гавані менетіл"}}},fp="12,405,32.571.0,38.247.0,36.200.0,35.161.0,41.241.0"}
P.entries["subzone:menethil-harbor"] = {n="Гавань Менетіл",s="Гавань Менетіл — добре укріплене дворфійське портове містечко на острові біля західного берега Багнокраю. Збудоване на місці старої орківської верфі й назване на честь короля Теренаса Менетіла II, воно є головною морською артерією, що з'єднує Східні Королівства з далекими берегами Калімдору. Захищене могутніми кам'яними мурами та міцними вежами Фортеці Менетіл, це жвавий осередок для купців, вояків у відпустці й просолених шукачів пригод.",h="Гавань Менетіл — добре укріплене дворфійське портове містечко на острові біля західного берега Багнокраю.",kw={"гавань менетіл","порт","багнокрай","теренас менетіл","альянс","кораблі","дворфи"},ang={["faction:Alliance"]="Для кожного мандрівника Альянсу, що прямує на захід, Гавань Менетіл — важливий плацдарм і єдиний морський міст, що поєднує Східні Королівства з Терамором і Калімдором.",["race:Dwarf"]="Хоч порт і носить ім'я людського короля, його тримає переважно дворфійська кам'яна кладка, а охороняє варта Айронфорджа, що пильнує зовнішній поріг Каз Модану."},sec={{t="Порт, народжений війною",b="Уперше це місце прислужилося Вождеві Орґріму Думхаммеру під час Другої війни, коли Орда будувала тут армаду вторгнення з дерева й заліза, награбованих у Каз Модані. Після розгрому орків великий адмірал Дейлін Праудмур наглядав за відбудовою стоянки, перетворивши її на найкращу гавань Альянсу, і назвав її на честь покійного короля Лордерону Теренаса Менетіла II. Попри віддалене розташування серед боліт, це добре захищений бастіон: його обороняють могутні мури, єдина гребля з мостом і чотири кам'яні сторожові вежі Фортеці Менетіл."},{t="Ворота через Велике Море",b="Нині гавань — велике перехрестя Альянсу. Кораблі безупинно ходять через океан до Острова Терамор у Багні Пилоброду та до Обердайна на Темному Узбережжі, везучи товари, дипломатів і кул-тіраських морських піхотинців у відпустці, що просаджують платню в Таверні «Глибока Вода». Та мир тут крихкий: за внутрішні шляхи постачання через Дун Алґаз раз у раз б'ється клан Драконячої Пащі, а ворожі загони Темного Заліза тиснуть на північні болота, тож Капітан Стаутфіст і гарнізон гавані завжди напоготові."}},faq={{q="Куди ходять кораблі з Гавані Менетіл?",a="Судна з причалів Гавані Менетіл перетинають Велике Море до континенту Калімдор. Пасажирські кораблі регулярно ходять до Острова Терамор у Багні Пилоброду й на північ — до ельфійської гавані Обердайн.",al={"човен із менетілу","куди пливе човен","пороми менетілу","човни до калімдору"}},{q="Хто править Гаванню Менетіл?",a="Гавань Менетіл — поселення Альянсу під владою Айронфорджа. Капітан Стаутфіст командує міською вартою й керує обороною гавані з Фортеці Менетіл, оберігаючи причали від болотяних звірів, орків-ренегатів і нападників із глибини краю.",al={"хто керує менетілом","лідер гавані менетіл","хто очолює менетіл"}},{q="Чому місто зветься Менетіл?",a="Гавань назвав Великий Адмірал Далін Праудмур після Другої війни на честь короля Лордерона Теренаса Менетіла II, під чиїм проводом людські, дворфійські й ельфійські держави об'єдналися в перший Альянс Лордерона.",al={"чому гавань менетіл","походження назви менетіл","хто такий менетіл"}},{q="Що зараз загрожує гавані?",a="Гавані постійно загрожує клан Драконячої Пащі, що чатує в пагорбах Багнокраю й раз у раз намагається перерізати перевал крізь Дун Алґаз, щоб відрізати порт від підкріплень. До бід гарнізону додаються вилазки Темного Заліза на півночі, біля Дун Модра, і хижі раптори.",al={"чи гавань менетіл у небезпеці","загрози менетілу","орки багнокраю менетіл"}}},fp="15,461,22.571.0,28.516.0,46.228.0,26.258.0,31.231.0,44.285.0"}
P.entries["subzone:menethil-keep"] = {n="Фортеця Менетіл",s="Фортеця Менетіл — кам'яна твердиня, що панує над обрієм Гавані Менетіл у Багнокраї. Із чотирма міцними сторожовими вежами, вона — адміністративне серце й оборонний бастіон порту Альянсу, де перебуває командир місцевого ополчення, Капітан Стаутфіст.",h="Фортеця Менетіл — кам'яна твердиня, що панує над обрієм Гавані Менетіл у Багнокраї.",kw={"фортеця менетіл","гавань менетіл","капітан стаутфіст","вежі","альянс","багнокрай"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що прибувають кораблем із Калімдору чи прямують на північ до Айронфорджа й Араті, Фортеця Менетіл — головна військова твердиня, що оберігає цей життєво важливий транспортний вузол."},sec={{t="Бастіон гавані",b="Здіймаючись над дерев'яними причалами й мокрими болотами Багнокраю, Фортеця Менетіл — головна військова опора Гавані Менетіл. Чотири кам'яні сторожові вежі дивляться на містечко й затоку, даючи чудовий огляд проти морських розбійників, ренегатів і болотяних звірів, що підступають. Усередині Капітан Стаутфіст керує обороною порту, командує міським ополченням і організовує патрулі, щоб захищати інтереси Альянсу по всьому краю."}},faq={{q="Для чого потрібна Фортеця Менетіл?",a="Фортеця Менетіл — штаб міського ополчення Гавані Менетіл і головний командний пункт Альянсу в Багнокраї. З-за її кам'яних мурів Капітан Стаутфіст командує місцевим гарнізоном, керує обороною й спрямовує шукачів пригод на боротьбу із загрозами по всіх болотах.",al={"призначення фортеці менетіл","роль фортеці менетіл","що це за замок"}},{q="Хто очолює Фортецю Менетіл?",a="Фортецею й ополченням Менетілу командує Капітан Стаутфіст. Він організовує оборону гавані від місцевих загроз — нападників з дворфів Темного Заліза, болотяних звірів і піратів.",al={"хто очолює фортецю менетіл","командир фортеці","капітан стаутфіст"}},{q="Де розташована фортеця?",a="Фортеця помітно височіє в Гавані Менетіл на західному узбережжі Багнокраю, нависаючи над поселенням чотирма високими кам'яними вежами.",al={"де фортеця менетіл","розташування фортеці менетіл","як знайти фортецю менетіл"}}},fp="13,269,21.473.0,31.297.0,34.184.0,26.160.0"}
P.entries["subzone:merchant-coast"] = {n="Узбережжя Крамарів",s="Узбережжя Крамарів — смуга східного берега Пусток над Великим Морем. Тут панує гамірний гоблінський порт Раджет, а назва узбережжя походить від прибуткової морської торгівлі, хоча за нього постійно змагаються пірати.",h="Узбережжя Крамарів — смуга східного берега Пусток над Великим Морем.",kw={"узбережжя крамарів","раджет","картель стімвідл","пірати","велике море","пустки"},ang={["faction:Alliance"]="Альянс тримає неподалік морські сили у Твердині Північної Варти, насторожено стежачи і за гоблінською торгівлею через Раджет, і за непокірними піратами Південних морів на березі.",["faction:Horde"]="Узбережжя Крамарів — головна торгова артерія Орди до моря в Пустках, тож безпека Раджета й приборкання місцевих піратів важливі для постачання всього краю."},sec={{t="Брама торгівлі й чвар",b="Узбережжя Крамарів, що тягнеться східним краєм Пусток, — важлива морська артерія, яка з'єднує центральний Калімдор зі Східними Королівствами й Терамором. Назва вшановує працьовитих гоблінських торговців картелю Стімвідл, чий нейтральний порт Раджет приймає вантажі від кожного, у кого водяться гроші. Проте відкриті морські шляхи приваблюють не лише торгові кораблі: Флібустьєри Південних морів нишпорять пісками й ближніми водами, полюють на купецькі судна й облаштовують на пляжах свої темні справи."}},faq={{q="Чому воно зветься Узбережжям Крамарів?",a="Свою назву узбережжя дістало завдяки прибутковій торгівлі через гоблінський порт Раджет. Крамарі Стімвідла переправляють звідси вантажі через Велике Море до портів по всьому Азероту.",al={"походження назви узбережжя крамарів","чому узбережжя крамарів"}},{q="Які великі поселення є на Узбережжі Крамарів?",a="Найвідоміше поселення — Раджет, нейтральне гоблінське портове місто, яким керує Ґазлоу. Далі на південь уздовж узбережжя лежить твердиня Альянсу Твердиня Північної Варти, а неподалік від берега — Острів Бійки.",al={"міста узбережжя крамарів","що на узбережжі крамарів"}},{q="Хто тримає тутешні пляжі?",a="Сама гавань — у руках Раджета, але на довколишніх пляжах отаборилися Флібустьєри Південних морів. Ці пірати заважають торгівлі, грабують гоблінські каравани й кидають виклик владі Раджета.",al={"пірати узбережжя крамарів","хто нападає на узбережжя крамарів"}}},fp="14,248,35.506.0,36.200.0,49.201.0,37.222.0"}
P.entries["subzone:military-ward"] = {n="Військовий Квартал",s="Військовий Квартал — бойове серце Айронфорджа, де розташовані командні споруди міста, майстри зброї й казарми. Тут, під яскраво-червоними стягами, дворфійські вояки, мисливці й облогові інженери вправляються поруч із механізованими облоговими машинами й літальними апаратами.",h="Військовий Квартал — бойове серце Айронфорджа, де розташовані командні споруди міста, майстри зброї й казарми.",kw={"військовий квартал","айронфордж","зала зброї","воїни","мисливці","майстер зброї"},ang={["class:Hunter"]="Слідопити й гірські вояки знайдуть у Залі Зброї приборкувачів звірів і спорядження, а поруч — «Мисливське спорядження Ґолдф'юрі» з набоями й амуніцією.",["class:Warrior"]="Військовий Квартал — головний бойовий осередок Айронфорджа: тут є наставники воїнів, тренувальні опудала для вправ і майстри зброї, що допоможуть вам розширити бойовий арсенал."},sec={{t="Ковадло дворфійської потуги",b="Військовий Квартал лежить у північній частині гірської твердині й зосереджує оборонні сили Айронфорджа на гамірному плацдармі. У центральному комплексі — Залі Зброї — працюють наставники воїнів і мисливців та розпорядники битв, а в ангарах стоять дворфійські літальні машини й парові танки. Довкола плаців і тренувальних опудал розташовані крамниці — «Лати й кольчуги Креґгелма», «Мисливське спорядження Ґолдф'юрі», «Зброя Тімберлайна», — тож квартал став головним місцем збору для гірських вояків і захисників міста."},{t="Гарнізон під бойовими стягами",b="На відміну від блідо-блакитних барв Торгових Рядів і вогняно-помаранчевих — Великої Кузні, Військовий Квартал убраний у бойові червоні стяги. Між муштрою й оглядами зброї вояки й вартові після зміни збираються на кухоль елю в «Куточку Брука», а Майстер Зброї Булівіф Стоунгенд навчає новобранців давніх дворфійських бойових традицій."}},faq={{q="Що таке Військовий Квартал?",a="Це бойовий квартал Айронфорджа — головна база дворфійського війська, де є наставники воїнів і мисливців, зброярі й облогові машини.",al={"військовий квартал айронфорджа","казарми айронфорджа","квартал воїнів айронфорджа"}},{q="Де в Айронфорджі можна навчитися володіти зброєю?",a="Майстер Зброї Булівіф Стоунгенд стоїть у зброярні «Тімберлайн» у Військовому Кварталі й навчає бійців Альянсу володіти різною зброєю.",al={"майстер зброї айронфорджа","де булівіф стоунгенд","навчитися зброї в айронфорджі"}},{q="Що зберігається в Залі Зброї?",a="Зала Зброї — військовий штаб: тут бойові наставники, розпорядники битв і великі відсіки, де стоять парові танки й дворфійські літальні апарати.",al={"зала зброї айронфорджа","що в залі зброї","облогові машини айронфорджа"}},{q="Чому в цьому кварталі червоні стяги?",a="Квартали Айронфорджа мають свої геральдичні кольори — це і традиція, і спосіб орієнтуватися. Військовий Квартал прикрашають яскраво-червоні стяги, що символізують бойову міць гірського міста.",al={"кольори військового кварталу","червоні стяги айронфорджа"}}},fp="13,282,26.548.0,31.342.0,26.158.0,42.150.0,37.166.0,41.179.0"}
P.entries["subzone:mirage-flats"] = {n="Міражні Рівнини",s="Міражні Рівнини — безплідний, випалений сонцем простір у центральних пустирях Пустищ. Це сухе плато на схід від Гроту Курного Виверга славиться мерехтливим маревом спеки й голодними хижаками.",h="Міражні Рівнини — безплідний, випалений сонцем простір у центральних пустирях Пустищ.",kw={"міражні рівнини","пустища","марево","койоти","скрадачі","стерв'ятники"},ang={["class:Hunter"]="Широкі відкриті простори Міражних Рівнин пропонують безліч агресивних звірів, яких можна вистежувати, вивчати чи приручати, — особливо лютих гребеневих скрадачів і витривалих койотів, загартованих пустелею."},sec={{t="Випалений пустир",b="Міражні Рівнини на схід від Гроту Курного Виверга зустрічають мандрівників безжальною смугою потрісканої червоної землі й мерехтливими хвилями спеки, що й дали рівнині назву. Цивілізовані душі тут рідко затримуються: на відкритих просторах панують спритні падальники й смертоносні звірі. Зграї велетенських стерв'ятників ліниво кружляють у гарячих висхідних потоках, видивляючись рештки здобичі лютих гребеневих скрадачів і скельних койотів, що полюють зграями й прочісують чагарі в пошуках легкої поживи."}},faq={{q="Де розташовані Міражні Рівнини?",a="Рівнини лежать у центрі Пустищ, на схід від Гроту Курного Виверга. Мандрівники, що прямують між західними скелями й східними каньйонами, часто перетинають цю випалену сонцем землю.",al={"розташування міражних рівнин","де міражні рівнини","міражні рівнини на мапі"}},{q="Чому ця місцевість зветься Міражними Рівнинами?",a="Назва походить від сліпучого пустельного сонця й гнітючої спеки, що пашить від пласкої кам'янистої землі: повітря безперестанку тремтить і породжує міражі, що збивають з пантелику спраглих мандрівників.",al={"чому міражні рівнини","значення назви міражних рівнин","марево бедлендсу"}},{q="Хто нишпорить рівнинами?",a="Тут живуть витривалі хижаки й падлоїди, що пристосувалися до суворих пустищ. Скажені скелясті койоти полюють зграями, патріархи гребеневих нишпорок крадуться чагарником, а над головою кружляють велетенські стерв'ятники, чекаючи, хто впаде в порох.",al={"моби міражних рівнин","хто живе на міражних рівнинах","звірі міражних рівнин"}}},fp="12,203,20.473.0,35.189.0,36.216.0,31.268.0"}
P.entries["subzone:mirage-raceway"] = {n="Перегони Міражу",s="Перегони Міражу — імпровізований інженерний полігон на мерехтливих солончаках Тисячі Голок. Він виник із запеклого суперництва між гоблінським майстром Поззіком і гномом-інженером Фіззлом Брассболтсом: тут ракетні автомобілі змагаються на розпеченій землі. Траса — нейтральне місце, куди приходять і Альянс, і Орда, щоб робити ставки, майструвати й уболівати за улюблені машини.",h="Перегони Міражу — імпровізований інженерний полігон на мерехтливих солончаках Тисячі Голок.",kw={"перегони міражу","мерехтливі низини","гобліни","гноми","ракетні машини","інженерна справа"},ang={["profession:Engineering"]="Для майстрів будь-якої сторони Перегони — вирішальний двобій гоблінського ризику й гномської ретельної конструкції: тут на ділі випробовують чисту швидкість, нестабільне пальне й експериментальні деталі машин.",["race:Gnome"]="Фіззл Брассболтс тримає тут прапор Гномреґана: разом з одноплемінниками й союзниками він доводить, що дисциплінований винахід легко перевершує безрозсудне гоблінське горіння."},sec={{t="Швидкість, сіль і суперництво",b="Перегони Міражу розкинулися на безкраїй білій пустелі Мерехтливих Низин і народилися із запеклої давньої ворожнечі двох майстрів-винахідників: гобліна Поззіка й гнома Фіззла Брассболтса. Вирішивши раз і назавжди з'ясувати, чия раса технічно кмітливіша, обидва збудували власні ракетні гоночні машини, найняли суперницькі команди й щодня зводять їх у шалених швидкісних двобоях. Невпинне змагання перетворило голі солончаки на гамірний осередок винахідництва, диверсій і випробувань: кожна команда відчайдушно шукає бодай якоїсь механічної переваги."},{t="Нейтральне перехрестя",b="The raceway draws supporters from both the Horde and Alliance. Spectators gather from across Kalimdor to cheer on either gnome precision or goblin firepower, while gamblers and shady opportunists thrive on the constant wagers placed on the results. Beyond the roar of rocket thrusters, the camps serve as a busy trading depot for travelers journeying between Thousand Needles and the blazing sands of Tanaris."}},faq={{q="Що таке Перегони Міражу?",a="Перегони Міражу — відкрита траса для реактивних автомобілів, прокладена солончаками Тисячі Голок. Її збудували суперники-інженери, щоб з'ясувати, чия механіка краща — гоблінська чи гномська.",al={"що таке перегони міражу","призначення перегонів","траса мерехтливих рівнин"}},{q="Хто тут влаштовує перегони?",a="Трасу спільно утримують гном-інженер Фіззл Брассболтс і гоблін-майстер Поззік. Кожен має власну команду й майстерню біля траси, звідки виставляє на змагання свої реактивні автомобілі.",al={"хто керує перегонами","фізл і позік","хто збудував трасу"}},{q="Чи можуть тут бувати і Орда, і Альянс?",a="Yes. Supporters from both factions gather at the raceway to cheer for their favorites, wager on races, and aid the rival engineering crews.",al={"чи нейтральні перегони міражу","чи може альянс відвідати","чи може орда відвідати"}},{q="Чому перегони саме на солончаках?",a="Пласкі широкі простори Мерехтливих Низин — рівна, вільна від перешкод поверхня, ідеальна для реактивних машин, яким потрібні милі, щоб набрати найвищу швидкість і безпечно загальмувати.",al={"чому перегони на солончаках","чому у тисячі голок","чому на мерехтливих рівнинах"}}},fp="14,445,24.616.0,20.409.0,27.200.0,24.197.0,42.139.0,31.191.0"}
P.entries["subzone:mirkfallon-lake"] = {n="Озеро Міркфаллон",s="Озеро Міркфаллон лежить у високогірній улоговині в центрі Гір Кам'яного Кігтя, під прямовисними скелями Кручі Вітрорізу. Його води й береги кишать дикою живністю: тут водяться агресивні слизуни, бродячі громові ящери та віверни, що спускаються сюди з висоти.",h="Озеро Міркфаллон лежить у високогірній улоговині в центрі Гір Кам'яного Кігтя, під прямовисними скелями Кручі...",kw={"озеро","високогір'я","громові ящери","віверни","слизуни","гори кам'яного кігтя"},ang={["class:Druid"]="Дикі звірі довкола Озера Міркфаллон уособлюють тендітну рівновагу природи Кам'яного Кігтя — надто вже близько вони живуть до механічних сокир, що наступають із кручі вгорі."},sec={{t="Високогірна улоговина",b="Озеро Міркфаллон лежить у самому центрі хребта Кам'яного Кігтя, між гірськими перевалами, що ведуть на південь до Стежки Павутинника й на північ до Піка Кам'яного Кігтя. Наповнене високогірними стоками, озеро — родюча оаза посеред скелястих вершин: сюди сходять на водопій громові ящери, а віверни злітають зі своїх гнізд високо вгорі. У воді живуть ще й дивні булькотливі слизуни, тож це спокійне гірське озерце стає небезпечною переправою для самотніх мандрівників."},{t="Перехрестя біля кручі",b="Улоговину озера перетинають стежки в усіх напрямках. На сході кам'янисті шляхи підіймаються до Кручі Вітрорізу й лісозаготівель, що заходять глибоко в лісисті долини. Мандрівники, які рушають на північ повз озеро, піднімаються до святилищ нічних ельфів і тауренських височин, а ті, хто обходить його з півдня, мусять пробиратися повз отруйні павучі лігва. Тож береги Озера Міркфаллон часто стають непередбачуваним перехрестям для дослідників і розвідників, що мандрують спірними горами."}},faq={{q="Хто живе біля Озера Міркфаллон?",a="На озері й берегах блукають громоящери, на мілинах повзають отруйні слизи, а гірські віверни полюють у довколишній улоговині й гніздяться на висотах.",al={"звірі озера міркфаллон","дика природа міркфаллону","що на озері міркфаллон"}},{q="Куди веде озеро?",a="Якщо піднятися на північ, дійдете до Піку Кам'яного Кігтя. На південь шлях спускається Стежкою Павутинника, а скелясті підйоми на схід ведуть до Кручі Вітрорізу.",al={"шляхи міркфаллону","куди веде міркфаллон","напрямки озера міркфаллон"}},{q="Чи безпечно рибалити в Озері Міркфаллон?",a="Озеро багате на шавлієвих риб і плавучі уламки, тож рибалок воно вабить. Проте на берегах часто трапляються агресивні істоти — слизи й віверни, — тож спокійно порибалити тут нелегко.",al={"риболовля на озері міркфаллон","чи можна рибалити в міркфаллоні"}}},fp="15,267,16.492.0,22.484.0,43.200.0,25.156.0,35.200.0"}
P.entries["subzone:mirror-lake"] = {n="Дзеркальне Озеро",s="Дзеркальне Озеро — мальовнича водойма на північному заході Лісу Елвінн, біля саду. Живлене лагідним водоспадом під скелями Стормвінда, його спокійне плесо приховує небезпеки на берегах — від розбійників Дефіас, що тут нишпорять, до дивних збурень у місцевих лей-лініях.",h="Дзеркальне Озеро — мальовнича водойма на північному заході Лісу Елвінн, біля саду.",kw={"дзеркальне озеро","озеро","водоспад","дефіас","лей-лінії","маги","ліс елвінн"},ang={["class:Mage"]="Учнів Святилища Чародія в Стормвінді посилають сюди брати проби води, щоб вони на власні очі побачили, як бурхливі таємні канали просочуються в природне довкілля.",["faction:Alliance"]="Хоч озеро й лежить поруч із високими стінами столиці, воно нагадує, як тонко розтягнуті вартові королівства перед розбійниками Дефіас."},sec={{t="Неспокійна ідилія",b="Дзеркальне Озеро під високими валами Стормвінда мало б бути мирним прихистком для рибалок і втомлених мандрівників. Натомість довколишніми садами скрадаються розбійники Братства Дефіас, тож будь-яке тривале перебування тут небезпечне для місцевих. Ще гірше: містичні збурення по всьому Азероту почали викривлювати природні канали таємної енергії по всьому лісу. Маги зі Святилища Чародія пильно наглядають за озером і посилають учнів брати проби його течій, щоб переконатися, що хаотичні таємні стоки не отруюють громади нижче за течією."}},faq={{q="Чому Дзеркальне Озеро небезпечне?",a="Попри мальовничий вигляд, довкола озера нишпорять розбійники Дефіас, що полюють на мандрівників і фермерів. До того ж недавні коливання магії в краї викликали тривогу, чи безпечна вода в озері.",al={"чи безпечне дзеркальне озеро","вороги дзеркального озера","дефіас дзеркальне озеро"}},{q="Чому маги вивчають Дзеркальне Озеро?",a="Великі чарівні сутички по всьому Азероту розхитали лей-потоки в Лісі Елвінн і Стормвінді. Святилище Чародія посилає учнів брати проби води з озера, щоб перевірити, чи немає в ній непостійних чарівних решток, перш ніж вони зашкодять тим, хто її п'є.",al={"святилище чародія дзеркальне озеро","завдання дзеркального озера","магія дзеркального озера"}},{q="Звідки береться водоспад біля Дзеркального Озера?",a="Водоспад спадає з високих скель і водотоків, що оточують Стормвінд: він наповнює озеро, а звідти вода тече далі річками Елвінна.",al={"водоспад дзеркального озера","джерело води дзеркального озера"}}},fp="11,296,15.590.0,29.236.0,35.262.0,50.177.0"}
P.entries["subzone:mirror-lake-orchard"] = {n="Сад Дзеркального Озера",s="Сад Дзеркального Озера — тихий гай із хатиною на південному березі Дзеркального Озера на заході Лісу Елвінн. Колись мирна садиба біля Громових водоспадів, нині він у руках розбійників Дефіас, які визискують околицю, поки вартові Стормвінда дивляться деінде.",h="Сад Дзеркального Озера — тихий гай із хатиною на південному березі Дзеркального Озера на заході Лісу Елвінн.",kw={"сад дзеркального озера","сад","хатина","дефіас","розбійники","громові водоспади","ліс елвінн"},ang={["class:Rogue"]="Сад показує класичну стратегію Дефіас: захоплювати зручні для оборони, непомітні маєтки біля води та скель, щоб стежити за дорогами й уникати міських патрулів.",["faction:Alliance"]="Для мандрівників Альянсу захоплений сад — ще одна гірка ознака зухвалого розростання Братства Дефіас у серці королівства."},sec={{t="Захоплений гай",b="Схований біля спадаючих вод Громових водоспадів, Сад Дзеркального Озера колись був родючою садибою, що користалася чистими водами Дзеркального Озера. Нині мирна хатина захоплена спритними злодіями й розбійниками під кольорами Братства Дефіас. Поки військо королівства розтягнуте до краю, а Король Варіан Рінн зник, сільські маєтки на кшталт цього саду стали легкою здобиччю для злочинців, що шукають сховків по всій елвіннській околиці."}},faq={{q="Хто зараз тримає Сад Дзеркального Озера?",a="Сад Дзеркального Озера й хату поряд нині займають розбійники Дефіас. Вони прогнали чесних людей, що колись доглядали дерева, і тепер мають у цьому відлюдному місці свою базу на заході Елвінна.",al={"хто в саду дзеркального озера","хто тут живе","вороги саду"}},{q="Де розташований Сад Дзеркального Озера?",a="Сад лежить на південному березі Дзеркального Озера на заході Лісу Елвінн, трохи на схід від Громових водоспадів і на північ від головної дороги до Вестфолу.",al={"розташування саду дзеркального озера","де сад","знайти сад елвін"}},{q="Чому Стормвінд не повернув собі сад?",a="Постійного війська Стормвінда в сільському Елвінні майже немає через політичний глухий кут і загадкове зникнення короля Варіана Рінна. Місцевим гарнізонам бракує людей, тож віддалені ферми й сади часто мусять самі давати раду Братству Дефіас.",al={"чому тут дефіас","де вартові"}},{q="Як сад пов'язаний із Громовими водоспадами?",a="Дзеркальне Озеро стікає просто в Громові водоспади, тож сад стоїть якраз над ревучим каскадом. Відлюдне місце біля скель — ідеальний і зручний для оборони сховок для розбійників.",al={"зв'язок із громовими водоспадами","сад і водоспад"}}},fp="19,281,21.494.0,43.208.0,37.161.0,43.283.0,61.185.0"}
P.entries["subzone:mist-s-edge"] = {n="Край Імли",s="Край Імли — довге, продуване вітрами узбережжя, що тягнеться на північ від Обердайна західним краєм Темного Узбережжя. Оповиті вологим морським туманом, ці сірі пляжі всіяні уламками кораблів, рештками велетенських морських створінь і мандрівними зграями крабів і мурлоків.",h="Край Імли — довге, продуване вітрами узбережжя, що тягнеться на північ від Обердайна західним краєм Темного...",kw={"край імли","темне узбережжя","обердайн","мурлоки","краби","корабельні уламки"},ang={["race:NightElf"]="Для нічних ельфів Обердайна Край Імли — і важливий морський кордон, і непокірне прикордоння, яке заполонили мурлоки-загарбники й мерзенні падальники."},sec={{t="Оповитий туманом берег",b="Край Імли, що тягнеться західним краєм Темного Узбережжя, — це вологі піски, кам'янисті припливні калюжі й вічний прибережний туман. Пляж — справжнє морське кладовище, всіяне тушами морських велетнів, що розкладаються, плавником і розтрощеними ребрами розбитих суден. Хоч берег здається безлюдним, він кишить падальниками: передусім агресивними крабами й ревнивими до своєї території племенами мурлоків, що гніздяться в прибої."},{t="Уламки й падальники",b="Підступні води біля берегів Темного Узбережжя поглинули незліченні судна, розкидавши розтрощені корпуси й викинутий вантаж уздовж пісків. Вартові нічних ельфів і місцеві збирачі насторожено стежать за узбережжям, де табори мурлоків раз у раз загрожують мандрівникам, що йдуть уздовж берега на північ і на південь від Обердайна."}},faq={{q="Що таке Край Імли?",a="Край Імли — довга смуга узбережжя, що тягнеться на північ від Обердайна західним берегом Темного Узбережжя. Він славиться холодним морським туманом, уламками кораблів і викинутими на берег морськими істотами.",al={"край імли","пляж темного узбережжя","що таке край імли"}},{q="Які небезпеки чатують на цьому узбережжі?",a="На березі повно ворожих прибережних крабів і агресивних зграй мурлоків, що живуть у примітивних таборах біля самої води.",al={"монстри краю імли","хто нападає на пляжі","небезпеки узбережжя темного берега"}},{q="Чому тут стільки уламків кораблів і кістяків?",a="Через сильні течії, приховані рифи й густий туман біля Темного Узбережжя плавати тут небезпечно, і кораблі розбиваються об скелі. Так само течії часто викидають на берег рештки величезних левіафанів і морських істот.",al={"викинуті кити темного берега","уламки кораблів краю імли","гігантські кістки темного берега"}}},fp="11,248,20.407.0,21.337.0,20.187.0,31.141.0,52.216.0"}
P.entries["subzone:misty-pine-refuge"] = {n="Притулок Туманних Сосен",s="Притулок Туманних Сосен — невелика будівля-застава Срібного світанку серед морозних снігів центрального Дун Мороґу.",h="Притулок Туманних Сосен — невелика будівля-застава Срібного світанку серед морозних снігів центрального Дун...",kw={"притулок туманних сосен","срібний світанок","отець ґевін","застава","дун мороґ","жрець"},ang={["class:Priest"]="Скромний пост Отця Ґевіна показує, що служіння Світлу часто полягає в тихій пильності далеко від полів битв."},sec={{t="Прихисток серед снігів",b="Розташований серед обвіяних вітрами пагорбів Дун Мороґу, Притулок Туманних Сосен — непримітна застава Срібного світанку в дворфському краї. Поки навколишні скелі патрулюють горяни Айронфорджа, у притулку живе Отець Ґевін, єдиний представник ордену в цих краях, що дає тихе вогнище посеред лютої негоди й небезпек, які загрожують гірським дорогам."}},faq={{q="Що таке Притулок Туманних Сосен?",a="Це будиночок-застава Срібного Світанку в центрі Дун Мороґу, де живе лише один посланець ордену — Отець Ґевін.",al={"що це за місце","туманні сосни","огляд притулку туманних сосен"}},{q="Чому Срібний Світанок тут, у Дун Мороґу?",a="Срібний Світанок насамперед бореться з загрозою нежиті на півночі, але його посланці, як-от Отець Ґевін, пильнують і з тихіших куточків земель Альянсу.",al={"чому тут срібний світанок","отець ґевін срібний світанок","срібний світанок дворфійські землі"}},{q="Хто живе в притулку?",a="Отець Ґевін, посланець Срібного Світанку, — єдиний член ордену, що перебуває в притулку.",al={"хто в туманних соснах","нпс туманних сосен"}}},fp="17,118,19.366.0,26.118.0,42.164.0,24.99.0"}
P.entries["subzone:misty-reed-post"] = {n="Застава Імлистого Очерету",s="Застава Імлистого Очерету — суворий табір Орди між Стаґалбоґом і Узбережжям Туманного Очерету на сході Болота Скорботи. Її заснували як передовий пост під орудою Стонарда, щоб наглядати за небезпечними драговинами й підступним узбережжям.",h="Застава Імлистого Очерету — суворий табір Орди між Стаґалбоґом і Узбережжям Туманного Очерету на сході Болота...",kw={"застава імлистого очерету","орда","стонард","ток'кар","катар","болото скорботи"},ang={["class:Hunter"]="Застава тримається переважно на мисливцях зі Стонарда, які знають довколишню болотяну природу, і втілює ту завзятість, без якої не вистежиш здобич і не виживеш серед ворожих болотяних хижаків.",["faction:Horde"]="Табір — бажаний острівець безпеки й місцевих підказок для розвідників Орди, які пробираються небезпечними східними околицями болота."},sec={{t="Самотня застава",b="Застава Імлистого Очерету, що загубилася у вологій імлі між Стаґалбоґом і східним берегом, — це, по суті, лише спартанський табір під стягом Стонарда. Тут служить жменька мисливців зі Стонарда, шаман Катар і Ток'Кар, який очолює варту. Умови суворі: жодного укріпленого прихистку від ворожої болотяної звірини й вічної вогкості. Ток'Кар потай сподівається, що командування Орди в Стонарді колись зміцнить позицію міцною орківською землянкою чи сторожовою вежею, але поки що розвідникам доводиться тримати болото з наметами, димом багать і нагостреною сталлю."}},faq={{q="Для чого потрібна Застава Імлистого Очерету?",a="Це допоміжний передовий табір гарнізону Орди зі Стонарда. Він стоїть між болотами Стаґалбоґу й Узбережжям Туманного Очерету, і його вартові стежать за загрозами з моря та місцевими болотяними звірами.",al={"чому тут застава імлистого очерету","призначення застави імлистого очерету","що це за табір"}},{q="Хто тут головний?",a="Заставу очолює Ток'Кар — орк, якому доручено втримати цей вразливий табір разом із Катаром, шаманом зі Стонарда, і кількома мисливцями Стонарда. Ток'Кар сподівається, що колись поселенню дадуть кошти на постійні укріплення.",al={"хто керує заставою імлистого очерету","токкар","ток'кар"}},{q="Чи є на Заставі Імлистого Очерету розпорядник польотів?",a="Ні. Застава Імлистого Очерету — скромний польовий табір без сідала вітрокрилів. Мандрівникам, що шукають польоту, доведеться йти дорогою на захід до Стонарда.",al={"майстер польотів імлистого очерету","чи є тут політ","майстер польотів застави імлистого очерету"}}},fp="15,285,16.597.0,39.226.0,22.247.0,44.166.0"}
P.entries["subzone:misty-reed-strand"] = {n="Узбережжя Туманного Очерету",s="Узбережжя Туманного Очерету — оповитий туманом безлюдний східний берег Болота Скорботи. Його всіяли гострі скелі, викинуті морем уламки й повзуча болотяна імла, а живуть тут агресивні краби, кроколіски й прибережні племена мурлоків. Мандрівникам, які спускаються до прибою, часто доводиться змагатися з місцевою звіриною за все, що викидає на берег.",h="Узбережжя Туманного Очерету — оповитий туманом безлюдний східний берег Болота Скорботи.",kw={"узбережжя туманного очерету","мурлоки","краби","плавник","болото скорботи","стонард"},ang={["faction:Alliance"]="Розвідники Альянсу, що прямують на південь від Незерґарда чи пробираються болотами, часто збирають на пляжі вдосталь плавнику й інших припасів, тримаючи агресивну звірину на відстані.",["faction:Horde"]="Захисники Стонарда вважають мурлочі племена узбережжя загрозою, яку ніхто не стримує, і часто посилають бойові дозори вичищати їхні табори вздовж прибою."},sec={{t="Туманний берег",b="Узбережжя Туманного Очерету тягнеться вздовж усієї східної межі Болота Скорботи й утворює вологий бар'єр між глибокою трясовиною та Великим Морем. З води безупинно накочуються густі тумани, що застилають очі й приглушують крики місцевої звірини. Пляжі всіяні морським сміттям, плавником і гнилою рослинністю, винесеною з болота. Через віддаленість і суворий клімат на березі немає жодних постійних поселень, тож пісок належить агресивним ракоподібним, кроколіскам, що чатують на здобич, і мурлокам, які люто захищають свої угіддя."},{t="Спірні води",b="І Альянс, і Орда час від часу посилають шукачів пригод на узбережжя, хоча жодна з фракцій не вважає пляж своєю територією. Альянс часто збирає тут плавник і викинуте морем добро, водночас намагаючись зменшити кількість крабів, що снують піском. Тим часом застави Орди в глибині болота пильно стежать за таборами мурлоків на березі й посилають досвідчених бійців прорідити їхні лави, перш ніж ці земноводні нальотники просунуться далі до Стонарда чи почнуть загрожувати подорожнім на болоті."}},faq={{q="Де розташоване Узбережжя Туманного Очерету?",a="Узбережжя Туманного Очерету тягнеться вздовж далекого східного краю Болота Скорботи, на межі з Великим Морем. Дістатися туди можна, рушивши просто на схід болотами від Стонарда чи довколишніми болотяними стежками.",al={"де узбережжя туманного очерету","розташування узбережжя туманного очерету","як дістатися до узбережжя туманного очерету"}},{q="Хто живе на узбережжі?",a="На березі повно велетенських прибережних крабів, болотяних кроколісків і різних племен ворожих мурлоків, що нишпорять уздовж лінії прибою.",al={"монстри узбережжя туманного очерету","хто живе на узбережжі туманного очерету","вороги туманного очерету"}},{q="Чи є на пляжі якісь поселення?",a="На самому пляжі немає ні постійних дружніх поселень, ні військових застав. Найближчі поселення — глибше в Болоті Скорботи.",al={"містечка біля туманного очерету","база туманного очерету","дружні табори туманного очерету"}},{q="Навіщо фракції посилають шукачів пригод на Узбережжя Туманного Очерету?",a="І Альянс, і Орда час від часу посилають на узбережжя найманців. Посланці Альянсу зазвичай шукають викинуте морем дерево й прибережні матеріали, а Орда посилає воїнів прорідити агресивні племена мурлоків, що живуть біля прибою.",al={"навіщо йти на узбережжя туманного очерету","завдання туманного очерету"}}},fp="17,365,17.603.0,16.496.0,39.221.0,34.141.0,39.173.0,62.242.0"}
P.entries["subzone:misty-shore"] = {n="Туманний Берег",kw={"туманний берег","озеро лордамер","гори альтерак","фортеця фенріс","даларан","черепахи-кусаки"},ang={["faction:Horde"]="Туманний берег — природний прохід між землями Відступників біля Таррен Мілла та північним берегом озера, де мандрівники сховані від відкритих патрулів.",["profession:Cooking"]="Береги Озера Лордамер — щедрі угіддя для полювання на черепах-кусак, чиє ніжне м'ясо цінують кухарі, що мандрують Горами Альтерак."},sec={{t="Берег у тумані",b="Туманний Берег пролягає вздовж Озера Лордамер між Кошарою Дандреда й Далараном. З озера раз у раз насувається густе вологе повітря, ховаючи черепах-кусак і зрідка — завзятого фанатика, що забрів сюди з навколишніх твердинь."},{t="Погляд на озеро",b="З Туманного Берега мандрівники дивляться через воду на Світанкові острови й грізну тінь Фортеці Фенріс. Звідси видно все Озеро Лордамер, а поруч — і Даларан, і клапті земель під владою Багряних, тож подорожні на березі здебільшого тримаються тихо, щоб не привертати зайвої уваги."}},faq={{q="Де розташований Туманний Берег?",a="Misty Shore lies in the Alterac Mountains, running along the eastern shore of Lordamere Lake between Dandred's Fold and the Dalaran perimeter.",al={"розташування туманного берега","де туманний берег","туманний берег на мапі"}},{q="Що видно звідси за водою?",a="Looking across the waters of Lordamere Lake, you can see the Dawning Isles and the looming structure of Fenris Keep out in the fog.",al={"що видно за водою","вид з туманного берега","вид на озеро"}},{q="Які небезпеки зазвичай трапляються на березі?",a="На березі живуть озерні звірі, як-от черепахи-хапозуби, але мандрівники ризикують натрапити й на фанатиків Багряного Хрестового Походу чи на розвідників, що блукають від сусідніх ферм і руїн.",al={"небезпеки туманного берега","вороги туманного берега","істоти туманного берега"}}},fp="11,263,24.244.0,17.332.0,33.142.0,44.131.0,49.198.0"}
P.entries["subzone:misty-valley"] = {n="Туманна Долина",s="Туманна Долина, що ховається на північному заході Болота Скорботи, — затінена, просякнута туманом улоговина на північ від проходу до Перевалу Мертвого Вітру. Цю відлюдну котловину заполонили первісні болотяні звірі, блукаючі болотоходи й сплутані жахіття. А в найглибшій печері живе колосальний і страхітливий Володар Трясовини.",h="Туманна Долина, що ховається на північному заході Болота Скорботи, — затінена, просякнута туманом улоговина...",kw={"туманна долина","володар трясовини","болотоходи","елементалі","перевал мертвого вітру","болото скорботи"},ang={["class:Druid"]="Громіздкі болотоходи й сплутані жахіття, що населяють цю відлюдну долину, втілюють дику, неприборкану лють болотяних елементалей, глибоко сплетених із первісною природою болота."},sec={{t="Оповита туманом улоговина",b="Туманна Долина, що лежить під високими скелями, які відділяють Болото Скорботи від Перевалу Мертвого Вітру, повсякчас тоне в густих болотяних випарах. На відміну від відкритих боліт на сході, цей відлюдний закуток кишить колосальними болотяними елементалями — велетенськими болотоходами, прадавніми старійшинами-болотоходами й повзучими сплутаними жахіттями. У дальньому кінці туманної ущелини відкривається печера — лігво Володаря Трясовини, однієї з найгрізніших природних загроз цього болота."}},faq={{q="Де розташована Туманна Долина?",a="Туманна Долина лежить у далекому північно-західному куті Болота Скорботи, просто на північ від дороги, що веде на Перевал Мертвого Вітру.",al={"розташування туманної долини","де туманна долина","туманна долина болото скорботи"}},{q="Хто живе в цій долині?",a="Долину заполонили велетенські рослинні елементалі й болотяні жахіття — болотоходи, старші болотоходи й сплутані жахи, що блукають густим туманом.",al={"моби туманної долини","хто живе в туманній долині","вороги туманної долини"}},{q="Що в печері в глибині долини?",a="Глибоко в печері в кінці Туманної Долини живе Володар Трясовини — величезний і могутній болотяний елементаль, що панує в цій відлюдній улоговині.",al={"печера туманної долини","печера володаря драговини","хто в печері туманної долини"}},{q="Чи безпечно перетинати Туманну Долину?",a="Аж ніяк. Височенні болотоходи й сплутані жахи, що блукають густим туманом, ворожі й агресивні, тож долина небезпечна для необачних мандрівників, які зійдуть з головної дороги.",al={"чи небезпечна туманна долина","рівень туманної долини"}}},fp="12,324,19.487.0,34.145.0,35.171.0,50.151.0,37.187.0"}
P.entries["subzone:mizjah-ruins"] = {n="Руїни Мізджа",s="Руїни Мізджа — прадавні кам'яні рештки на півночі Долини Стренглторну, трохи на південний схід від Базового Базового Табору Ґром'ґол. Тролі-будівничі давно покинули ці споруди, що розсипаються, і їх захопили огри Мош'Оґґ, які покладаються на грубу силу. Звідси огри влаштовують засідки на каравани з припасами, що прямують до Болота Скорботи.",h="Руїни Мізджа — прадавні кам'яні рештки на півночі Долини Стренглторну, трохи на південний схід від Базового...",kw={"руїни мізджа","огри","мош'оґґ","ґром'ґол","стонард","долина стренглторну"},ang={["faction:Horde"]="Огри Мош'Оґґ у Мізджа прямо загрожують важливому постачанню Орди, тож Базовий Табір Ґром'ґол мусить посилати воїнів боронити шлях до Стонарда."},sec={{t="Кубло огрів",b="Як і чимало прадавніх кам'яних руїн, розкиданих Долиною Стренглторну, Руїни Мізджа збудувала Імперія Ґурубаші задовго до появи нинішніх держав. Сьогодні в порослих мохом арках і на потрісканих плитах засів клан Мош'Оґґ — переважно грубі воїни й неотесані знахарі. Ці огри не сидять у своїх захоплених межах: вони раз у раз нападають на обози з припасами, що прямують до поселення Орди Стонард, тож стародавні руїни стають постійним і кривавим головним болем для командирів Ґром'ґола."}},faq={{q="Хто збудував Руїни Мізджа?",a="Як і більшість кам'яних споруд, розкиданих по півночі Долини Стренглторну, Руїни Мізджа спершу звели тролі джунглів Імперії Ґурубаші, перш ніж століття війн і руйнувань спорожнили їх.",al={"хто збудував мізджа","походження мізджа","тролячі руїни мізджа"}},{q="Хто тепер живе в Руїнах Мізджа?",a="Руїни нині займають огри Мош'Оґґ — громили Мош'Оґґ і знахарі Мош'Оґґ, що укріпили кам'яні споруди як свій табір.",al={"хто тут живе","моби мізджа","табір мош'оґґ"}},{q="Чому Орда хоче очистити руїни?",a="Огри Мош'Оґґ із Мізджа полюють на шляхи постачання Орди, влаштовуючи засідки на обози між Базовим Табором Ґром'ґол і заставою Стонард на Болоті Скорботи.",al={"чому вбивати мош'оґґ","оборона ґром'ґола","завдання каравана стонарда"}}},fp="12,387,14.535.0,27.229.0,34.175.0,50.184.0"}
P.entries["subzone:mo-grosh-stronghold"] = {n="Твердиня Мо'ґрошів",s="Твердиня Мо'ґрошів — укріплене лігво огрів, викопане в північно-східних пагорбах Лох Модану. Ці жорстокі велетні, що засіли серед давніх обвітрених руїн, постійно загрожують дворфійським поселенням унизу.",h="Твердиня Мо'ґрошів — укріплене лігво огрів, викопане в північно-східних пагорбах Лох Модану.",kw={"твердиня мо'ґрошів","огри","мо'ґрош","телсамар","лох модан"},ang={["faction:Alliance"]="Щоб убезпечити Лох Модан, треба тримати огрів Мо'ґрош під контролем, — тоді шлях між Айронфорджем і північними гірськими дорогами лишатиметься безпечним.",["race:Dwarf"]="Огри Мо'ґрош постійно загрожують дворфійським патрулям і мандрівникам, тож знищення їхньої твердині — справа громадської оборони для горян Лох Модану."},sec={{t="Загроза, що нависає",b="Твердиня Мо'ґрошів, що ховається серед скель північно-східного Лох Модану, — головна база клану огрів Мо'ґрош у краї. Громили, що засіли в печерах і зовнішніх таборах, нападають на дворфійські каравани з припасами й становлять постійну небезпеку для спокою Телсамара. Грубе каміння, розкидане довкола табору, свідчить, що колись тут було давніше поселення, доки незграбні огри не захопили цю землю й не насипали своїх характерних курганів."}},faq={{q="Що таке Твердиня Мо'ґрошів?",a="Це огрське поселення серед пагорбів на північному сході Лох Модану. Огри Мо'ґрош живуть у печерах і на довколишніх землях — це найбільший ворожий огрський анклав у краї.",al={"твердиня мо'ґрошів","огрівський табір лох модан","печера мо'ґроша"}},{q="Хто жив тут до огрів?",a="Стара кам'яна кладка підказує, що до огрів тут стояло якесь поселення, але хто були його мешканці — невідомо.",al={"стародавні руїни лох модан","хто збудував мо'ґроша","тролі в лох модані"}},{q="Чим огри небезпечні для дворфів?",a="Огри живуть біля важливих шляхів, тож становлять серйозну загрозу для подорожніх і торгових караванів Лох Моданом. Дворфійська влада регулярно закликає шукачів пригод прорідити їхні лави й тримати гірські перевали в безпеці.",al={"чому вбивати огрів мо'ґроша","загроза мо'ґрошів для айронфорджа"}}},fp="19,211,16.489.0,28.192.0,39.110.0,44.235.0"}
P.entries["subzone:molsen-farm"] = {n="Ферма Молсена",s="Ферма Молсена — покинутий хутір у хліборобському краї Вестфолу. Колись ця родюча земля годувала Стормвінд, а тепер ферма лежить у руїнах: спершу прийшло Братство Дефіас, а по ньому лишилися механічні големи жнив, що й досі нишпорять полями.",h="Ферма Молсена — покинутий хутір у хліборобському краї Вестфолу.",kw={"ферма молсена","вестфол","хутір","вартові врожаю","братство дефіас"},ang={["faction:Alliance"]="Порослі бур'яном поля Ферми Молсена — похмуре нагадування про те, що Стормвінд дедалі гірше тримає свої сільські землі, а Братство Дефіас стає дедалі грізнішим."},sec={{t="Зруйнований хутір",b="Як і чимало хуторів Вестфолу, Ферма Молсена стала жертвою королівської байдужості та злочинного заколоту. Коли Братство Дефіас узяло край під свою руку, фермерів вигнали — а то й гірше, — і вони покинули і врожай, і будівлі. Тепер замість женців неприбраними полями нишпорять ворожі механічні Вартові Урожаю та блукають розбійники, тож ферма небезпечна для кожного, хто мандрує цим краєм."}},faq={{q="Чому Ферму Молсена покинуто?",a="Ферму покинули, коли Братство Дефіас заполонило Вестфол. Без військового захисту Стормвінда господарі не змогли вберегти свою землю від розбійників і збунтованих жнивних големів і мусили тікати з рідних домівок.",al={"чому порожньо","хто тут жив","що сталося з фермою молсена"}},{q="Хто тепер тримає ферму?",a="Поля заполонили несправні Жнивні Вартові й розбійники, вірні Братству Дефіас. Жоден законослухняний мешканець нині тут не живе й не працює.",al={"вороги ферми молсена","хто на фермі молсена"}},{q="Хто такий Молсен?",a="Ферма носить ім'я місцевої родини, яка першою оселилася тут і обробляла землю, доки недавні заворушення не прирекли селян Вестфолу на вигнання чи злидні.",al={"хто такий молсен","родина молсена"}}},fp="11,268,18.458.0,29.243.0,26.164.0,15.174.0"}
P.entries["subzone:moon-horror-den"] = {n="Лігво Місячного Жаху",s="Лігво Місячного Жаху — відлюдна, вкрита інеєм печера трохи на північний схід від гоблінського торгового містечка Евірлук у Вінтерспрінгу. Сховане під зубчастим гірським схилом, воно слугує гніздовищем для лютих скажених диких місячників. Мандрівникам варто бути обережними біля його крижаного входу: ці совозвіри ревно боронять свій прихисток.",h="Лігво Місячного Жаху — відлюдна, вкрита інеєм печера трохи на північний схід від гоблінського торгового...",kw={"лігво місячного жаху","совозвіри","евірлук","вінтерспрінг","печера","село зимопадів"},ang={["class:Druid"]="Друїди, хранителі священних створінь Елуни, з болем дивляться на несамовитий шал диких місячників у цьому лігві — він віддзеркалює дику бурю, що охопила Вінтерспрінг.",["class:Hunter"]="Печера — тісна й небезпечна арена для полювання на лютих диких місячників: ближній бій із товстошкірими звірами випробує нерви будь-якого слідопита."},sec={{t="Кубло пір'я й морозу",b="Лігво Місячного Жаху, зовсім недалеко на північний схід від вартованих воріт Евірлука, глибоко врізається в гірську скелю. У печері живуть могутні скажені совозвіри — грізні створіння, відомі своєю грубою силою й лютою вдачею серед суворих снігів Вінтерспрінгу. Хоча неподалік на півдні лежить поселення фурболгів Село Зимопадів, стрімка гірська стіна стає непрохідною природною перепоною, тож лігво лишається відрізаним прихистком диких місячників, а не шляхом для мандрівників."}},faq={{q="Хто живе в Лігві Місячного Жаху?",a="У печері живуть скажені дикі місячники — великі агресивні створіння, звиклі до морозного клімату Вінтерспрінгу. Ці звірі люто боронять свої володіння й нападають на кожного, хто забреде до їхнього підземного лігва.",al={"що в лігві місячного жаху","моби лігва місячного жаху","дикі місячники в печері"}},{q="Де розташоване Лігво Місячного Жаху?",a="Воно на сході Вінтерспрінгу, за кілька кроків на північний схід від гоблінського містечка Евірлук. Вхід до печери ховається в північній скельній стіні.",al={"розташування лігва місячного жаху","як знайти лігво місячного жаху","де лігво місячного жаху"}},{q="Чи можна з лігва дістатися до Села Зимопадів?",a="Ні. Хоча на мапі Село Зимопадів лежить просто на півдні, високий гірський хребет утворює за лігвом неприступну природну стіну. Щоб дістатися до села, доведеться обійти гірські схили відкритою долиною.",al={"шлях до села зимопадів","скорочення до зимопадів","з лігва до зимопадів"}},{q="Навіщо мандрівники заходять у цю печеру?",a="Шукачі пригод зазвичай заходять у лігво, щоб полювати на скажених диких місячників, допомагаючи природознавцям і дослідникам, що вивчають зіпсованих чи агресивних диких місячників Вінтерспрінгу.",al={"навіщо йти в лігво місячного жаху","завдання лігва місячного жаху"}}},fp="15,356,27.526.0,43.211.0,37.160.0,46.228.0,40.182.0"}
P.entries["subzone:moonbrook"] = {n="Мунбрук",s="Колись Мунбрук був жвавим хліборобським і гірницьким містечком на південному заході Вестфолу, а тепер це беззаконне місто-примара. Його цілком захопило Братство Дефіас і використовує як укріплену ширму, за якою ховається їхній підземний штаб у Мертвих Копальнях.",h="Колись Мунбрук був жвавим хліборобським і гірницьким містечком на південному заході Вестфолу, а тепер це...",kw={"мунбрук","вестфол","братство дефіас","мертві копальні","едвін венкліф","місто-примара"},ang={["class:Rogue"]="Провулки й пограбовані оселі Мунбрука без прикрас показують, як цілий злочинний синдикат орудує серед білого дня.",["faction:Alliance"]="Мунбрук — гірке нагадування про байдужість королівства, що кинуло законослухняних підданих на поталу Братству Дефіас."},sec={{t="Занепале місто",b="До Першої війни Мунбрук був важливою громадою в самому серці житниці Вестфолу: тут жили фермерські родини, а поруч давали прибуток золоті шахти Мертвих Копалень. Стара Орда спалила його вщент, після Другої війни його старанно відбудували, та спокій тривав недовго. Дім Вельмож у Стормвінді не дбав про поселення, військового захисту воно не мало — і не змогло вистояти перед мстивою Гільдією Каменярів, коли та подалася в глушину. Бандити прогнали чесних хуторян, і городянам разом з учителями довелося тікати до Сентінел Гілла та Лісу Елвінн."},{t="Твердиня Дефіас",b="Нині Мунбрук — по суті наземний гарнізон заколоту Едвіна Венкліфа. Вулицями й пограбованими будинками ходять головорізи в червоних масках і маги-ренегати, а зарослі бур'яном поля довкола патрулюють големи жнив. Тихі житлові вулички приховують вхід до Мертвих Копалень — він під непримітною клунею на краю містечка. Тож Мунбрук — найнебезпечніше кубло зради в усьому королівстві."}},faq={{q="Чому Мунбрук покинутий?",a="Мирні мешканці покинули Мунбрук, коли Братство Дефіас захопило Вестфол. Без гарнізону армії Стормвінда містян вигнали, і розбійники забрали все містечко собі як твердиню.",al={"що сталося з мунбруком","чому в мунбруку бандити","хто захопив мунбрук"}},{q="Куди веде шахта в Мунбруку?",a="Вхід до шахти під стодолою на краю Мунбрука веде до Мертвих Копалень. Колись вони були величезним джерелом золота для Стормвінда, а тепер ці лабіринти тунелів — таємний оплот і плацдарм Братства Дефіас.",al={"де мертві копальні","що під мунбруком","вхід у шахту мунбрука"}},{q="Хто жив тут до розбійників?",a="Колись у Мунбруку жили рудокопи, фермери й ремісники, на яких трималося господарство Вестфолу. Серед відомих колишніх мешканців — Сталван Містмантл, що недовго був директором місцевої Школи Мунбрука, доки розбійники не заполонили містечко.",al={"мешканці мунбрука","хто жив у мунбруку","школа сталвана містмантла"}},{q="Чи збирається Стормвінд повернути містечко?",a="Двір Стормвінда не раз відмовлявся посилати королівські війська, щоб звільнити Мунбрук чи довколишні ферми, посилаючись на брак сил. Оборону цілком полишено на добровольців Народного ополчення, що стоїть на Сентінел Гілл.",al={"чи врятує стормвінд мунбрук","чому армія не допомагає мунбруку"}}},fp="9,275,13.594.0,17.406.1,27.252.0,42.229.0,41.266.0,40.245.0"}
P.entries["subzone:moonbrook-schoolhouse"] = {n="Школа Мунбрука",s="Школа стоїть у північно-західному куті Мунбрука — показна будівля, схожа на ратушу, з невеликим цвинтарем позаду. Її звели, щоб навчати місцевих дітей під проводом директора Сталвана Містмантла, а нині вона стоїть пусткою посеред окупованого Дефіас Вестфолу.",h="Школа стоїть у північно-західному куті Мунбрука — показна будівля, схожа на ратушу, з невеликим цвинтарем...",kw={"школа мунбрука","мунбрук","сталван містмантл","вестфол","цвинтар","листи"},ang={["faction:Alliance"]="Покинута школа — суворе нагадування про те, як далеко Вестфол відпав від захисту Корони: осередки знань перетворилися на сховки для розбійників."},sec={{t="Світоч, що поринув у тінь",b="Before Moonbrook fell to ruin and bandits, the community invested in the education of its youth by raising this grand schoolhouse. After Stalvan Mistmantle began tutoring local children, the mayor commissioned him to run a school. In those brighter days, the hall bustled with students rather than thieves, standing as proof of Moonbrook's former prosperity. Now, the schoolhouse lies abandoned to the elements and infested with outlaws, while the weathered headstones of its rear cemetery silently oversee Westfall's steady decay."},{t="Таємниці під мостинами",b="Though long abandoned by scholars, the schoolhouse holds the beginning of a grim mystery. An old footlocker left behind on the main floor contains an unsent letter describing Stalvan's arrival in Moonbrook, his tutoring of local children, and the mayor's commission to build a new schoolhouse. A separate letter later found in Goldshire explains that regional troubles forced him to leave his post and seek work as a private tutor."}},faq={{q="Для чого спершу була ця будівля?",a="Це була школа Мунбрука, збудована саме для того, щоб місцеві діти здобували освіту. Її простора будова, схожа на ратушу, свідчить про амбіції й гордість містечка до його занепаду.",al={"чому збудували","призначення школи мунбрука","що це за місце"}},{q="Хто такий Сталван Містмантл?",a="Stalvan Mistmantle was a learned scholar who became the schoolhouse's headmaster. Investigators can follow the letters he left behind to learn more about his career.",al={"хто такий сталван","сталван містмантл історія","директор школи"}},{q="Чому школа тепер покинута?",a="Коли Мунбрук занепав через господарську скруту, а Братство Дефіас захопило південь Вестфолу, громадські установи містечка розвалилися. Школу покинули разом із рештою містечка, і тепер у ній хазяйнують розбійники.",al={"чому покинута","що сталося зі школою мунбрука","хто тепер тут живе"}},{q="Що можна знайти в школі сьогодні?",a="Alliance investigators tracking Stalvan Mistmantle can find an old, dusty footlocker on the ground floor containing an unsent letter.",al={"де скриня","здобич у школі","предмет завдання всередині"}}},fp="21,293,27.531.0,26.431.1,43.225.0,27.165.0,37.236.0,47.133.0"}
P.entries["subzone:moonshrine-ruins"] = {n="Руїни Місячної Святині",s="Руїни Місячної Святині — затоплений простір давньої архітектури нічних ельфів глибоко в Чорноглибинних Печерах. Колись присвячені поклонінню Елуні, ці напівзруйновані зали осквернив і захопив культ Молота Присмерку.",h="Руїни Місячної Святині — затоплений простір давньої архітектури нічних ельфів глибоко в Чорноглибинних...",kw={"руїни місячної святині","елуна","молот присмерку","барон аквеніс","чорноглибинні печери"},ang={["class:Shaman"]="Те, як темні руничні камені скують духів води на кшталт Барона Аквеніса, показує, наскільки глибоко Молот Присмерку спотворює й поневолює сили стихій.",["race:NightElf"]="Бачити, як священні зали, присвячені Елуні, обернулися на затоплені руїни, повні культистів, — гірка кривда для кожного нічного ельфа, що спускається в глибини."},sec={{t="Затоплені зали Елуни",b="За печерним Ставком Аск'ар лежать Руїни Місячної Святині — сумне свідчення давнього минулого нічних ельфів на узбережжі Ашенвалю. У цих напівзатоплених залах колись лунали співи на честь Місячної Богині Елуни, але Великий Розкол зруйнував храм і затопив його нижні яруси морською водою. Сьогодні каламутні води кишать дикими морськими звірами — від агресивних крабів до змієподібних трешадонів, а культ Молота Присмерку хазяйнує серед каміння, правлячи темні ритуали, що глузують зі священного походження святині."},{t="Стихійні глибини",b="Руїни ведуть просто до Забутого ставка й Святилища Місячної Святині і слугують культові майданчиком для викликів. Під поверхнею затоплених залів лежить давній руничний камінь, пов'язаний зі стихіями. Через цей підводний фокус Молот Присмерку керує водами глибин і викликає Барона Аквеніса — жахливого водяного елементаля, скутого їхніми темними задумами."}},faq={{q="Для чого спершу збудували Руїни Місячної Святині?",a="Руїни колись були частиною величного підземного храмового комплексу, присвяченого ельфійській богині Елуні, і збудували його ще до того, як Великий Розкол роздер давній континент.",al={"походження місячної святині","хто збудував руїни місячної святині","що це за місце"}},{q="Хто тепер тримає Руїни Місячної Святині?",a="Руїни заполонили ворожі морські істоти — трешадони й краби-хапуни, — а також сектанти Молота Присмерку, що захопили весь затоплений комплекс.",al={"хто тут","моби місячної святині","молот присмерку чорнотрясовини"}},{q="Куди ведуть Руїни Місячної Святині?",a="Руїни лежать за тунелями, що починаються біля Ставка Аск'ар. Із Руїн Місячної Святині шляхи ведуть глибше — до Святилища Місячної Святині — і до Забутого ставка.",al={"виходи місячної святині","куди це веде","шлях через руїни"}},{q="Хто такий Барон Аквеніс?",a="Барон Аквеніс — могутній водяний елементаль, якого викликають, торкнувшись затопленого рунного каменя, захованого в каламутній воді під руїнами. Він служить зловісним задумам Молота Присмерку.",al={"барон аквеніс історія","підводний бос місячної святині","елементаль у воді"}}},fp="16,234,22.564.0,20.402.1,52.185.0,38.186.0,35.189.0,21.183.0"}
P.entries["subzone:moonshrine-sanctum"] = {n="Святилище Місячної Святині",s="Святилище Місячної Святині — давня ельфійська святиня глибоко в Чорноглибинних Печерах, що нині слугує культові Молота Присмерку внутрішньою твердинею. Тут панує сутінковий володар Келріс; у залі стоїть незаймана пам'ятка королеві Азшарі, а сама зала прикриває запечатаний вхід до лігва Аку'мая.",h="Святилище Місячної Святині — давня ельфійська святиня глибоко в Чорноглибинних Печерах, що нині слугує...",kw={"святилище місячної святині","келріс","азшара","аку'май","молот присмерку","чорноглибинні печери"},ang={["class:Priest"]="Спотворені обряди, які сутінковий володар Келріс править у цій залі, вивертають навиворіт священні молитви: замість цілющої божественної благодаті вони кличуть божевільний шепіт Порожнечі.",["race:NightElf"]="Бачити, як давній храм, вирізьблений вашими предками ще до Розколу, обернено на жертовну яму для Молота Присмерку й наг, — гірке свідчення того, як тіні дедалі глибше вповзають в Ашенваль."},sec={{t="Осквернений храм",b="Святилище Місячної Святині, що лежить одразу за затопленими Руїнами Місячної Святині, — головний осередок культистів у Чорноглибинних Печерах. Хоч тисячоліття тому нічні ельфи збудували цю залу на честь місяця й своїх правителів, тепер її осквернив Молот Присмерку. Цікаво, що культисти дбайливо зберегли височенну статую королеви Азшари — вони відчувають спорідненість зі зміїстими нагами, які служать тим самим темним господарям із глибин. Під пильним оком сутінкового володаря Келріса під кам'яним склепінням печери вдень і вночі звучать темні заклинання."},{t="Поріг до Аку'мая",b="Святилище — остання перепона перед Лігвом Аку'мая. Важкі двостулкові кам'яні двері, які тримають давні захисні чари, замикають страхітливу гідру. Навколо статуї Азшари в центрі стоять чотири обрядові жаровні: щоб розплести печать, їх треба запалити. Та це будить сплячих вартових святині — полчища велетенських крабів, клацозубих черепах, закутих у панцири макрур і викликаних водяних елементалів, що мусять боронити святилище від необачних зайд."}},faq={{q="Де розташоване Святилище Місячної Святині?",a="Святилище Місячної Святині — глибоко в підземеллі Чорноглибинні Печери на Зорамському Узмор'ї в Ашенвалі. Воно лежить одразу за затопленими Руїнами Місячної Святині, просто перед лігвом гідри Аку'май.",al={"розташування святилища місячної святині","де святилище місячної святині","святилище чорнотрясовини"}},{q="Хто править у Святилищі Місячної Святині?",a="Святилищем командує сутінковий володар Келріс — грізний чаклун культу Молота Присмерку, майстер сонних чарів, що править обряди на честь давнього покровителя культу, позначеного Порожнечею.",al={"хто тут править","бос святилища місячної святині","хто керує святилищем"}},{q="Чому тут уціліла статуя Азшари?",a="Святилище колись було давнім ельфійським храмом, присвяченим Королеві Азшарі ще до Великого Розколу. Молот Присмерку береже статую в бездоганному стані, бо культ діє в прямому союзі з нагами Азшари з глибин.",al={"статуя азшари","чому статуя азшари","статуя наги чорнотрясовини"}},{q="Як відчинити великі двері в глибині зали?",a="Щоб відімкнути двері до Лігва Аку'мая, шукачі пригод мають запалити чотири обрядові свічки біля підніжжя статуї Азшари. Кожна запалена свічка пробуджує хвилю морських звірів-вартових і водяних елементалів, яких доведеться здолати.",al={"як відчинити двері чорнотрясовини","відчинення дверей акумай","запалити свічки чорнотрясовини"}}},fp="18,295,19.587.0,24.469.1,32.213.0,38.179.0,46.247.0,59.240.0"}
P.entries["subzone:moonspray"] = {n="Місячні Бризки",s="«Місячні Бризки» — транспортне судно Альянсу з Флоту калдореїв. Воно перевозить мандрівників через води, що відділяють материковий Калімдор від велетенського Світового Дерева, Тельдрассилу.",h="«Місячні Бризки» — транспортне судно Альянсу з Флоту калдореїв.",kw={"місячні бризки","корабель","обердайн","рут'теран","тельдрассил","пором"},ang={["faction:Alliance"]="«Місячні Бризки» — важлива транспортна ланка, що з'єднує головний прибережний осередок Альянсу на півночі Калімдору з відокремленою столицею — Дарнасусом.",["race:NightElf"]="Для молодих нічних ельфів, що залишають Тельдрассил, аби побачити широкий світ, «Місячні Бризки» часто стають тим самим судном, яке вперше везе їх із відлюдної домівки на материк."},sec={{t="Важливий острівний пором",b="«Місячні Бризки» — незамінна нитка між доками Обердайна на березі Темного Узбережжя й Селищем Рут'теран біля коріння Тельдрассилу. Перетинаючи Приховане Море, судно перевозить шукачів пригод, гінців і важливі припаси між відокремленим святилищем нічних ельфів у кроні Світового Дерева й давнім материком Калімдору."}},faq={{q="Куди ходять «Місячні Бризки»?",a="«Місячні Бризки» ходять між портовим містечком Обердайн на Темному Узбережжі й Селищем Рут'теран біля підніжжя Тельдрассилу, що здіймається з океану.",al={"маршрут місячних бризок","куди пливуть місячні бризки","пункт призначення місячних бризок"}},{q="Кому належить цей корабель і хто ним керує?",a="«Місячні Бризки» — корабель нічних ельфів зі складу флоту калдореїв, що ходить під стягом Альянсу.",al={"хто керує місячними бризками","флот келдореїв місячні бризки","чи місячні бризки альянсу"}},{q="Чому цей поромний маршрут важливий?",a="Тельдрассил — острів, що високо здіймається над морем біля північно-західного узбережжя Калімдору. Кораблі на кшталт «Місячних Бризок» — головний спосіб переправляти війська, припаси й мандрівників через воду на материк.",al={"навіщо їхати на місячних бризках","човен до тельдрассила"}}},fp="9,203,20.354.0,32.139.0,32.120.0,34.218.0"}
P.entries["subzone:moonwell-ashenvale"] = {n="Місячний колодязь (Ашенваль)",s="Це відлюдне святилище, яке нічні ельфи звуть Місячним Колодязем Чистоти, лежить у центральному Ашенвалі, на схід від Озера Ірисів і на захід від Притулку Рейнвуд. Його благословенні води несуть ласку Елуни, живлячи прадавній ліс і очищаючи землю від повзучої скверни. Мандрівники Альянсу й вартові нічних ельфів часто приходять до його тихої чаші, щоб очистити осквернені артефакти, знайдені в лісі.",h="Це відлюдне святилище, яке нічні ельфи звуть Місячним Колодязем Чистоти, лежить у центральному Ашенвалі, на...",kw={"місячний колодязь","колодязь чистоти","елуна","очищення","ашенваль","місячна тканина"},ang={["profession:Tailoring"]="Кравці можуть скористатися густою місячною енергією, що збирається у водах колодязя, щоб із тканини скверни виткати чисту місячну тканину.",["race:NightElf"]="Кожен місячний колодязь для калдореїв — священний куточок дому далеко від дому: і духовне джерело ласки Елуни, і передовий оплот проти демонічної скверни, що загрожує Ашенвалю."},sec={{t="Святилище чистоти",b="Цей місячний колодязь, що сховався під кронами центрального Ашенвалю, — духовна опора калдореїв. Його сяйливі води черпають приховану магію природи та світло Місячної Богині. Довколишній ліс потерпає від скверни сатирів, демонічної отрути й вирубок, тож чисті святилища на кшталт цього стають рятівною ниткою для тих, хто намагається зцілити ліс."},{t="Зцілення лісу",b="Чаша колодязя стає джерелом очищення для осквернених реліквій. Шукачі пригод, що допомагають Рейн Вульфраннер, приходять сюди занурити у воду осквернені уламки жезла: незаймана місячна сила проганяє скверну там, де звичайні засоби безсилі."}},faq={{q="Як зветься саме цей місячний колодязь?",a="Це місце відоме як Місячний колодязь Чистоти. Це один із кількох місячних колодязів в Ашенвалі: він лежить на схід від Озера Ірисів і на захід від Притулку Рейнвуд.",al={"який це місячний колодязь","назва місячного колодязя","місячний колодязь чистоти"}},{q="Для чого потрібні місячні колодязі?",a="Місячні колодязі — священні чаші, присвячені Елуні, у яких місячна сила поєднується з магією природи. Нічні ельфи використовують їх, щоб підтримувати землю, відновлювати духовну силу й очищати речі, осквернені темним чи демонічним впливом.",al={"для чого місячний колодязь","призначення місячних колодязів","чому існують місячні колодязі"}},{q="Чому шукачі пригод з Альянсу приходять до цього колодязя?",a="Героїв Альянсу посилають сюди очищати осквернені реліквії, знайдені в лісі, — наприклад, під час розслідувань, які веде Рейн Вульфраннер з Астранаару.",al={"місячний колодязь очищення рейни","чому приходять сюди","очищення жезла тут"}}},fp="20,400,19.380.0,16.245.1,38.151.0,28.225.0,48.182.0"}
P.entries["subzone:mor-shan-rampart"] = {n="Вал Мор'шан",s="Вал Мор'шан — потужно укріплена барикада Орди на північному кордоні Пусток, що стереже вхід до Ашенвалю. Збудований переважно кланом Бойової Пісні, він захищає землі Орди від контрударів нічних ельфів і водночас слугує плацдармом для вилазок углиб лісу.",h="Вал Мор'шан — потужно укріплена барикада Орди на північному кордоні Пусток, що стереже вхід до Ашенвалю.",kw={"вал мор'шан","бойова пісня","орда","пустки","золотий шлях","ашенваль"},ang={["faction:Alliance"]="Бійці Альянсу вважають Вал Мор'шан зухвалою барикадою, яку лісорубні Орди звели, щоб захищати загарбані землі й готувати набіги на Ашенваль.",["faction:Horde"]="Для Орди Вал — головна сухопутна брама, що захищає серце Пусток від вилазок нічних ельфів і береже шляхи постачання до лісорубень Ашенвалю."},sec={{t="Північна брама",b="Вал Мор'шан, що стоїть на північному кінці Золотого Шляху, позначає межу між посушливими рівнинами Пусток і прадавніми кронами Ашенвалю. Цей оплот із важких колод, оборонних частоколів і укріплених сторожових веж звели, щоб стримати відплатні удари нічних ельфів, обурених вирубками Орди. Він водночас і щит, що береже північну браму до глибин Калімдору, і передовий плацдарм для загонів, які прориваються на північ до Астранаару."},{t="Застава Бойової Пісні",b="Вал обороняють переважно загартовані в боях вояки клану Бойової Пісні, і він завжди в повній бойовій готовності. З його бійниць вартові стежать за узліссям, виглядаючи розвідниць і лучниць нічних ельфів, і бережуть відкритими шляхи постачання між передовими заставами Ашенвалю та більшими поселеннями Орди на півдні."}},faq={{q="Що таке Вал Мор'шан?",a="Це укріплена прикордонна застава Орди там, де Пустки сходяться з Ашенвалем. Її збудували, щоб не пускати контрнаступи Альянсу в Пустки й охороняти північний кінець Золотого Шляху.",al={"вал мор'шан","що за барикада","північна брама пустовиськ"}},{q="Хто тримає це укріплення?",a="В укріпленні стоїть гарнізон Орди — воїни й вартові з клану Бойової Пісні. Вони тримають сторожові вежі й частоколи вздовж узлісся.",al={"хто тримає мор'шан","хто охороняє вал","оборонці мор'шан"}},{q="Чому вал стоїть тут, а не глибше в Ашенвалі?",a="Він тримає північний кінець Золотого Шляху — головного суходільного шляху, що сполучає центральні Пустки з Ашенвалем. Хто контролює це вузьке місце, той не дасть нічним ельфам легко прорватися на південь, у серце земель Орди.",al={"чому вал тут","стратегічне значення мор'шан"}},{q="Чи можуть мандрівники з Альянсу безпечно пройти крізь вал?",a="Ні. Вал — діюча військова позиція Орди. На мандрівників з Альянсу, що підійдуть з Ашенвалю чи з Пусток, вартові нападуть одразу.",al={"чи пройде альянс","перетин мор'шан альянсом"}}},fp="16,318,17.523.0,15.337.0,29.205.0,32.173.0,55.251.0,55.172.0"}
P.entries["subzone:morgan-s-plot"] = {n="Ділянка Морґана",s="Ділянка Морґана — безлюдний цвинтар і напівзруйнована каплиця просто за вежею Каражан на Перевалі Мертвого Вітру. Тут панують неспокійна нежить і гнітюча тиша, а в забутих склепах спочивають ті, хто колись був пов'язаний із володіннями Медіва.",h="Ділянка Морґана — безлюдний цвинтар і напівзруйнована каплиця просто за вежею Каражан на Перевалі Мертвого...",kw={"ділянка морґана","цвинтар","каражан","медів","мороес","нежить","перевал мертвого вітру"},ang={["class:Mage"]="Маги Даларана ставляться до цього місця з тихим острахом, знаючи, що тут поховано тих, хто загинув під час трагічного кінця Медіва.",["class:Priest"]="Осквернені могили й неприкаяні немертві мешканці роблять Ділянку Морґана суворим нагадуванням про згубну скверну, що лишається скрізь, де звершилася темна доля Стража."},sec={{t="Могила в тіні вежі",b="Ділянка Морґана, притулена до прямовисних скелястих схилів просто за Каражаном, — сумний зарослий цвинтар довкола зруйнованої каплиці й підземних склепів. Задовго до того, як ця земля занепала й стала Перевалом Мертвого Вітру, тут ховали мешканців вежі й довколишніх угідь. Після падіння Останнього Стража, Медіва, у землю просочилася темна енергія, і від колишнього звичного життя не лишилося й сліду. Нині цвинтарем каплиці блукають неспокійні немертві, кружляючи між надгробками і слуг, і видатних постатей минулого."},{t="Спочинок Стражів і слуг",b="The graveyard has held several figures tied intimately to Karazhan's history. Medivh, his seneschal Moroes, and the tower's cook were laid to rest here following the tragedy that shattered the tower. Medivh was later resurrected, before his return during the Third War. While mysteries linger as to what truly remains in the crypts beneath the soil, the soil itself feels heavy with old, lingering arcana and unquiet spirits."}},faq={{q="Де розташована Ділянка Морґана?",a="Ділянка Морґана лежить на півдні Перевалу Мертвого Вітру, у похмурій улоговині просто за високим шпилем Каражану.",al={"де ділянка морґана","розташування ділянки морґана","як дістатися до ділянки морґана"}},{q="Хто тут похований?",a="Здавна цвинтар і склепи належали господарству Каражану. Після падіння Медіва тут поховали Вартового разом із його вірним сенешалем Мороузом і кухарем вежі.",al={"хто похований на ділянці морґана","могила медіва","могила мороза","поховання еґвін"}},{q="Які небезпеки чатують на Ділянці Морґана?",a="У каплиці й на довколишніх угіддях блукають неживі мешканці й неспокійні духи, що тиняються між надгробками й біля входу до склепу.",al={"моби ділянки морґана","які вороги тут","монстри каплиці"}}},fp="13,271,34.529.0,39.425.1,31.117.0,19.180.0,43.155.0"}
P.entries["subzone:morgan-s-vigil"] = {n="Дозор Морґана",s="Дозор Морґана — зруйнована твердиня Альянсу на південно-східних висотах Палаючих Степів. Колись тут було невелике село, а тепер його обгорілі хати й розбита вежа чарівника правлять за суворий передовий табір для розвідників, що стежать за перевалами до Гори Блекрок. Це єдиний плацдарм Альянсу в задушеному попелом краї, де панують дворфи Темного Заліза й орки Блекрок.",h="Дозор Морґана — зруйнована твердиня Альянсу на південно-східних висотах Палаючих Степів.",kw={"дозор морґана","палаючі степи","альянс","грифони","блекрок","редрідж","застава"},ang={["faction:Alliance"]="Ця побита скеля — ваш єдиний безпечний прихисток у Палаючих Степах: звідси можна полетіти просто до Стормвінда, а тут гуртують опір загрозам Темного Заліза й Блекрок.",["race:Human"]="Утримуючи цей хребет, ви не даєте жахам, породженим під Горою Блекрок, безперешкодно ринути крізь перевал у беззахисні долини Редріджу й саме серце Стормвінда."},sec={{t="Останнє вогнище в Пустках",b="Дозор Морґана, що стоїть на високій скелі над вогняними пустирями, колись був скромним поселенням — аж доки жахи Палаючих Степів не захлеснули його. Нині обгорілі колоди й потріскана оболонка зруйнованої вежі мага — похмуре нагадування про той напад. Захисники, що лишилися, тулються під грубими полотняними наметами серед кіптяви. Попри руїну, у таборі досі є гніздовище грифонів, яке дає безперервне повітряне сполучення через гори зі Стормвіндом. Це вкрай потрібний прихисток, де розвідники, маршали й мандрівні шукачі пригод можуть перевести подих подалі від мародерських ватаг унизу."},{t="Довга варта",b="Назву й призначення застава отримала від пильної варти проти загрози, що нависає з Гори Блекрок. Поки клан Темного Заліза заглиблюється в темне чаклунство, а орки Блекрок прибирають до рук довколишні пустирі, табір слугує передовим плацдармом. Його захисники тримають оборону, координують розвідувальні рейди попелищами й охороняють важливий перевал, що веде на південь, до Редріджу."}},faq={{q="Що сталося з тутешніми будівлями?",a="Хати й інші споруди села спалили дощенту, а вежу магів зруйнували вщент. Уцілілі мешканці живуть у наметах серед руїн. Хто саме вчинив це спустошення — невідомо.",al={"чому дозор морґана спалений","руїни дозору морґана","хто зруйнував дозор морґана"}},{q="Хто така Морґан?",a="Морґан — жінка, на честь якої названо Дозор. Серед захисників, що нині стоять у таборі, її немає.",al={"хто такий морґан","хто названий морґаном","де морґан"}},{q="Навіщо Альянс тримає цей табір?",a="Це єдиний укріплений спостережний пункт Альянсу в Палаючих Степах: він стереже північний перевал до Редріджу й стежить за пересуванням військ довкола Гори Блекрок, швидко отримуючи припаси й підкріплення просто зі Стормвінда.",al={"чому альянс тут","призначення дозору морґана","чому тримати дозор морґана"}},{q="Як дістатися до Дозору Морґана й звідти?",a="На заставі є розпорядник грифонів Альянсу з прямими польотами до Стормвінда й до Торієвого Мису за Палючою Ущелиною.",al={"майстер польотів дозору морґана","як дістатися до дозору морґана","маршрути з дозору морґана"}},{q="Чи захищений Дозор Морґана від нападів?",a="Його пильно охороняють вартові Альянсу, але околиці постійно під загрозою блукаючих звірів, вогняних елементалів і орків-нападників, що чатують одразу за кряжем.",al={"чи дозор морґана спірний","чи може орда зайти в дозор морґана","безпечна зона"}}},fp="14,374,30.620.0,14.408.0,36.238.0,14.114.0,41.259.0,44.130.0,35.171.0"}
P.entries["subzone:morlos-aran"] = {n="Морлос'Аран",s="Морлос'Аран — давні руїни нічних ельфів на півдні Сквернолісся. До Великого Розколу це було горде й квітуче поселення, а тепер воно стоїть як похмурий пам'ятник утраченому золотому вікові, потопаючи в демонічній заразі, що отруює довколишній ліс.",h="Морлос'Аран — давні руїни нічних ельфів на півдні Сквернолісся.",kw={"морлос'аран","руїни","калдореї","великий розкол","сквернолісся","нічні ельфи"},ang={["class:Druid"]="Покручена земля довкола зруйнованих фундаментів показує, якої страшної шкоди зазнало Сквернолісся, і спонукає Коло Кенарія очищати цей край.",["race:NightElf"]="Прохід крізь Морлос'Аран — трагічне нагадування про те, як низько впала імперія: священна кладка предків тепер поглинута мерзенною демонічною скверною Легіону."},sec={{t="Відлуння золотого віку",b="Десять тисяч років тому, ще до Розколу, Морлос'Аран був великим міським осередком давньої цивілізації калдореїв. Як і споріднені поселення на півночі Калімдору — Амет'Аран, Башал'Аран та Ордил'Аран, — він вирував ельфійським життям і чарами серед мармурових арок і залитих місячним світлом площ. Коли Колодязь Вічності зруйнувався, місто розкололося, і від нього лишилися тільки потрощені колонади — пам'ятники вершині їхньої цивілізації."},{t="Зачумлена реліквія",b="Сусідні руїни на Темному Узбережжі та в Ашенвалі просто занепали й поросли диким лісом, а Морлос'Аран спіткала значно похмуріша доля в Третю війну. Він опинився просто на шляху, яким пройшов Палаючий Легіон, і його вцілілі фундаменти задушили демонічна скверна й отруйне багно. Нині руїнами блукають звірі, осквернені елементалі й рештки темних сил, що досі таяться в Скверноліссі."}},faq={{q="Чим спершу був Морлос'Аран?",a="Це було велике поселення нічних ельфів, що процвітало до Великого Розколу. Разом із містами-побратимами по всьому давньому Калімдору воно становило серцевину цивілізації калдореїв у їхню золоту добу, доки десять тисяч років тому не обернулося на руїни.",al={"що таке морлос'аран","історія морлос'арана","хто збудував морлос'аран"}},{q="Чому назва закінчується на «'Аран»?",a="Цей суфікс трапляється в назвах кількох міст нічних ельфів, збудованих до Розколу: Амет'Аран і Башал'Аран на Темному Узбережжі, Ордил'Аран в Ашенвалі, Тетріс'Аран у Пустограї. Він позначає поселення, засновані за часів давньої імперії.",al={"значення аран","суфікс аран","зв'язок із амет аран"}},{q="Де саме розташований Морлос'Аран?",a="Він лежить на півдні Сквернолісся, біля переходу з Ашенвалю. Його напівзруйновані мармурові споруди видно серед зіпсованих, зів'ялих дерев трохи збоку від головної стежки.",al={"розташування морлос'арана","де морлос'аран","знайти морлос'аран"}},{q="Які небезпеки чатують у цих руїнах сьогодні?",a="Довколишній ліс заполонили зіпсовані звірі, осквернені деревні й рештки демонічного поріддя, тож Морлос'Аран украй небезпечний для мандрівників, що прямують на північ, у Сквернолісся.",al={"що всередині морлос'арана","моби морлос'арана","небезпеки морлос'арана"}}},fp="11,274,24.437.0,16.413.0,32.242.0,33.223.0,37.193.0,38.185.0"}
P.entries["subzone:mortwake-s-tower"] = {n="Вежа Клавена",s="Вежа Клавена, яку ще звуть Вежею Дефіас, — укріплена сторожова вежа біля річки на південному сході Вестфолу. Нею командує розбійник Клавен Мортвейк, і для контрабанди краденого через кордони королівства вона слугує важливою перевалочною точкою.",h="Вежа Клавена, яку ще звуть Вежею Дефіас, — укріплена сторожова вежа біля річки на південному сході Вестфолу.",kw={"вежа клавена","вежа дефіас","клавен мортвейк","братство дефіас","вестфол","si:7"},ang={["class:Rogue"]="Для розбійників-початківців, вишколених у Стормвінді, Вежа Клавена — справжній обряд посвяти: SI:7 посилає сюди агентів проникнути до твердині Мортвейка, перевірити майстерність зламування замків і скрадання та опанувати небезпечне ремесло сильних отрут.",["faction:Alliance"]="Ця твердиня Дефіас, що причаїлася на межі Елвінна, Вестфолу й Редріджу, показує, наскільки глибоко Братство підточило внутрішні річкові й торговельні шляхи королівства."},sec={{t="Твердиня контрабандистів",b="Вежа Клавена стоїть у прикордонні на північ від Кинджальних Пагорбів і є важливим осередком Братства Дефіас у південному Вестфолі. Разом із Пристанню Джерода на тому боці річки, у Лісі Елвінн, вона править за приймальний пункт і перевалочну базу для контрабанди, награбованої в Горах Редріджу. Звідси видно всі водні шляхи, тож Братство непомітно проводить свої вантажі повз королівські патрулі й ховає від очей Корони всю мережу постачання."},{t="Чад і тіні",b="Вежу тримає Клавен Мортвейк — алхімік і розбійник, одержимий смертельними сумішами. Мортвейк годинами варить тут екзотичні тролячі отрути, і густий отруйний чад заповнює верхні покої. Для непроханих гостей ці випари смертельні, але й власній варті Мортвейка вони притуплюють чуття. Цією сліпою плямою вміло користаються таємні агенти SI:7, розвідслужби Стормвінда, що стежать за вежею з сусідніх пагорбів."}},faq={{q="Хто тримає цю вежу?",a="Вежу тримає Клавен Мортвейк — розбійник Дефіас, що керує контрабандою й проводить досліди з летючими отрутами. Під його командуванням угіддя стереже загін вартових і патрульних Дефіас.",al={"хто такий мортвейк","хто такий клейвен","хто живе у вежі"}},{q="Чому вежа важлива для Братства Дефіас?",a="Це головна перевалка для крадених товарів, що йдуть у Вестфол. Контрабанду з Гір Редріджу везуть через Ліс Елвінн, повз Пристань Джерода, а звідти — через цю вежу, щоб постачати ширше повстання Братства.",al={"призначення вежі дефіасу","для чого вежа","чому вежа тут"}},{q="Чому SI:7 стежить за цим місцем?",a="Розвідка Стормвінда на чолі з Майстром Матіасом Шоу пильно стежить за цим місцем через смертоносні отрути Мортвейка й головну роль вежі на шляхах постачання Дефіас. Агенти, як-от Ембер Кернен, розвідують околиці, щоб оцінити пересування Братства й здобути цінні відомості.",al={"сі:7 вежа мортвейка","амбер кернен вежа","чому стормвінд стежить"}},{q="Що за випари стоять у вежі?",a="The haze comes from Klaven Mortwake's experiments with troll poisons. Their effects on the tower's guards are described in the protected section.",al={"отруйна вежа вестфолл","випари вежі","отрута клейвена"}}},fp="14,245,23.473.0,17.485.1,24.219.0,53.264.0,32.301.0,46.145.0"}
P.entries["subzone:mosh-ogg-ogre-mound"] = {n="Курган Огрів Мош'Оґґ",s="Курган Огрів Мош'Оґґ — укріплений печерний комплекс на півночі Долини Стренглторну, трохи на південь від руїн Зул'Ґурубу. Це головна твердиня грубого племені Мош'Оґґ у джунглях, де панує їхній безжальний вождь, огр-маг Май'Зот. Задовго до того, як огри оселилися тут, курган був священним місцем зі святилищем лоа Луку.",h="Курган Огрів Мош'Оґґ — укріплений печерний комплекс на півночі Долини Стренглторну, трохи на південь від руїн...",kw={"курган огрів мош'оґґ","май'зот","око розуму","огри","луку","долина стренглторну"},ang={["class:Mage"]="Огр-маг Май'Зот глибоко в кургані володіє Оком Розуму й має неприборкану чародійську силу — рідкість для грубих огрів.",["race:Troll"]="Колись у печері було шановане святилище лоа зцілення Луку, але поклоніння йому згасло, коли ваш народ був змушений покинути рідні джунглі предків."},sec={{t="Кубло огрів і давня віра",b="Курган Огрів Мош'Оґґ, видовбаний у суворих гірських пасмах джунглів на південь від Зул'Ґурубу, аж кишить грубими трощителями, шаманами й паліями війни Мош'Оґґ. Огри захопили цю мережу печер як ідеальну твердиню проти ворожих тролів джунглів і хижих звірів. Проте під грубістю їхнього поселення ховається давніша історія: доки плем'я Темного Списа не покинуло південні джунглі, ця печера була священною схованкою зі святилищем Луку — лоа зцілення й життя. Коли тролі пішли, святилище занепало, і огри прибрали підземний лабіринт до своїх рук."},{t="Май'Зот і Око Розуму",b="Глибоко у звивистих надрах кургану панує Май'Зот — грізний двоголовий огр-маг, що очолює клан Мош'Оґґ. Він володіє Оком Розуму — могутньою й небезпечною чародійською реліквією, що зміцнює його владу над розумом і чарами послідовників. Майстерність Май'Зота в магії та його груба сила роблять найглибші закутки кургану смертельно небезпечними для кожного мандрівника, що наважиться податися на північ Стренглторну."}},faq={{q="Хто живе в Кургані Огрів Мош'Оґґ?",a="У кургані живе огрське плем'я Мош'Оґґ — воїни, громили, шамани й палії війни. Ними править із глибини печери їхній ватажок, двоголовий огр-маг Май'Зот.",al={"хто в кургані","мешканці мош'оґґ","монстри кургану мош'оґґ"}},{q="Що таке Око Розуму?",a="Око Розуму — могутній чарівний артефакт, що його тримає в кургані огр-маг Май'Зот. Його дивна чарівна сила живить чаклунство Май'Зота і його владу над місцевими ограми.",al={"що має май'зот","реліквія ока розуму","око розуму"}},{q="Для чого був курган до приходу огрів?",a="До того, як сюди прийшли огри, печера була місцем поклоніння зі святинею Луку, лоа зцілення. Шанували його переважно тролі джунглів, зокрема плем'я Темного Списа, доки ті не втекли з Долини Стренглторну.",al={"історія кургану","святиня луку","історія тролячої печери"}},{q="Де розташований курган?",a="Курган лежить на півночі Долини Стренглторну, серед пагорбів трохи на південь від входу до тролівського міста Зул'Ґуруб.",al={"де курган мош'оґґ","розташування кургану огрів","як знайти курган огрів"}}},fp="19,389,32.606.0,27.425.0,37.204.0,23.172.0,54.222.0,27.133.0"}
P.entries["subzone:mosshide-fen"] = {n="Драговина Мохошкірих",s="Драговина Мохошкірих — болотиста, підступна місцевість на сході Багнокраю, яку заполонило плем'я гнолів-Мохошкірих. Поцяткована первісними таборами, вона — одне з найнебезпечніших місць для мандрівників, що сходять із головних торгових шляхів.",h="Драговина Мохошкірих — болотиста, підступна місцевість на сході Багнокраю, яку заполонило плем'я...",kw={"драговина мохошкірих","мохошкірі","гноли","кістогриз","болото","багнокрай"},ang={["race:Dwarf"]="Горяни Айронфорджа мусять повсякчас пильнувати Драговину Мохошкірих, адже агресивні зграї гнолів загрожують рудошукачам, що прочісують болота, і розвідникам, що охороняють східні стежки."},sec={{t="Територія зграї",b="Драговина Мохошкірих, що розкинулася каламутними східними закутками Багнокраю, — головні володіння агресивних гнолів-Мохошкірих. Болото тут густе й заплутане, всіяне грубими куренями й таборами, засипаними кістками. Під лютим проводом ватажків зграї на кшталт Кістогриза гноли запекло боронять свої багнисті володіння й охоче нападають на мандрівників, розвідників і рудошукачів, яким забракне розуму забрести в їхні мисливські угіддя, — і пожирають їх."}},faq={{q="Що таке Драговина Мохошкірих?",a="Драговина Мохошкірих — частина сходу Багнокраю: розмоклі болота, які цілком захопили й заселили гноли-Мохошкірі.",al={"історія драговини мохошкірих","що це за місце","болото мохошкірих"}},{q="Хто править Драговиною Мохошкірих?",a="У драговині живе плем'я гнолів-Мохошкірих, що слухаються жорстоких ватажків на кшталт Кістогриза: той велить своїй зграї ловити й пожирати всіх чужинців, що вдираються на їхні землі.",al={"хто керує гнолами","гнобон","ватажок мохошкірих"}},{q="Чому ця місцевість небезпечна для мандрівників?",a="Гноли Драговини Мохошкірих славляться агресивністю й пожадливістю до м'яса. Мандрівники, що сходять із протоптаних стежок чи нишпорять у мокрих чагарях у пошуках припасів, ризикують раптово потрапити в засідку мисливських зграй.",al={"чому небезпечно","небезпеки драговини"}}},fp="12,228,21.449.0,21.144.0,23.179.0,40.222.0"}
P.entries["subzone:mystic-ward"] = {n="Квартал містиків",s="Квартал містиків — північно-західний район Айронфорджа, тихий прихисток дворфійської столиці для духовного служіння й чародійних студій. Його легко впізнати за прохолодними блідо-блакитними стягами й тихими залами: він разюче відрізняється від дзвону ковадел сусідньої Великої Кузні. Найвеличніша його споруда, Зала Таїнств, збирає жерців, паладинів і магів під печерними кам'яними арками.",h="Квартал містиків — північно-західний район Айронфорджа, тихий прихисток дворфійської столиці для духовного...",kw={"квартал містиків","айронфордж","зала таїнств","маги","жерці","чародійство"},ang={["class:Mage"]="Для чародіїв Альянсу Квартал містиків — головний осередок у Каз Модані, де можна придбати чародійні припаси й книги заклять і здобути поглиблену науку поза академіями Стормвінда.",["class:Priest"]="Квартал і його велична Зала Таїнств — мирний прихисток, де дворфійські й прийшлі служителі Святого Світла збираються для молитви, настанов і єднання."},sec={{t="Святилище віри й чародійства",b="Дворфи славляться по всьому Азероту майстерністю в кузні та на полі бою, а Квартал містиків уособлює тихіші, розумові й духовні пошуки королівства. Позначений блідо-блакитною геральдикою, цей печерний квартал поєднує гамірні Торгові Ряди з Покинутою Печерою та Великою Кузнею. Тут купці постачають ученим і чародіям вбрання, сувої та алхімічні реагенти — у крамницях на кшталт «Бойового чарівника» чи «Містичного вбрання Мейви». Над районом панує велична Зала Таїнств, де святі дисципліни Святого Світла перетинаються з вивіреним мистецтвом чародійної магії й де настанови отримують ті, хто володіє невидимими силами на захист Альянсу."}},faq={{q="Для чого потрібен Квартал містиків?",a="Квартал містиків — район Айронфорджа, відведений чарівній магії, науковим дослідженням і духовному служінню. Тут продають приладдя для чаклунів і реагенти, а ще навчають паладинів, жерців і магів.",al={"призначення кварталу містиків","що тут відбувається","роль кварталу містиків"}},{q="Яка головна будівля в Кварталі містиків?",a="Серце кварталу — Зала Таїнств, велична склепінчаста зала, де працюють міські наставники святих і чарівних мистецтв і де є помітний оздоблений басейн.",al={"зала таїнств","великий храм","будівля кварталу містиків"}},{q="Чому стяги в цьому кварталі блідо-сині?",a="Айронфордж розмежовує свої квартали власною геральдикою. Військовий Квартал має бойові червоні стяги, Велика Кузня — вогняно-помаранчеві, а Квартал містиків вивішує блідо-сині, що символізують споглядання, мудрість і вивчення магії.",al={"сині стяги айронфорджа","чому сині прапори"}},{q="Куди веде Квартал містиків?",a="Квартал розташований у північно-західній частині міста. Переходи ведуть із нього на південь — до Торгових Рядів, на південний схід — до Великої Кузні, і на схід — просто до Покинутої Печери.",al={"зв'язки кварталу містиків","як дістатися до кварталу містиків"}}},fp="11,406,32.715.0,33.214.0,45.179.0,43.248.0,32.174.0"}
P.entries["subzone:mystral-lake"] = {n="Озеро Містраль",s="Озеро Містраль — найбільша водойма Ашенвалю, що лежить у південно-центральній частині лісу, трохи нижче Притулку Срібного Вітру. Колись це був тихий прихисток під охороною водяних елементалів, вірних нічним ельфам, але відколи місцевих елементалів осквернили, води озера стали небезпечними.",h="Озеро Містраль — найбільша водойма Ашенвалю, що лежить у південно-центральній частині лісу, трохи нижче...",kw={"озеро містраль","водяні елементалі","сарілус фоулборн","поклик води","шамани","ашенваль"},ang={["class:Shaman"]="Неспокійні глибини Озера Містраль — важлива зупинка на шляху Поклику Води: тут шамани-початківці мають зустрітися з місцевими духами, щоб опанувати своє стихійне ремесло.",["race:NightElf"]="Колись тут жили мирні охоронці, союзні вашому народові, а тепер озеро гірко нагадує про чужу скверну, що підступає до священних гаїв Ашенвалю."},sec={{t="Осквернене святилище",b="Озеро Містраль, що розкинулося на південь від Притулку Срібного Вітру й на схід від Долини Глибокого Кігтя, калдореї здавна цінували за чисті води й мирних елементалів-охоронців. Та темне втручання зруйнувало давній спокій. Маг-ренегат Сарілус Фоулборн обернув свої чари проти водяних духів озера й перетворив їх на ворожих, лютих створінь. Сьогодні дорога часто приводить мандрівників і з Орди, і з Альянсу до цих неспокійних берегів, де їм доводиться протистояти гніву духів, які колись оберігали ліс."},{t="Духовне перехрестя",b="Озеро Містраль непокоїть не лише нічних ельфів, що потерпають від скверни, — його знають по обидва боки фронту. Шамани Орди, що йдуть шляхом єднання зі стихіями, шукають його глибоких вод під час своїх випробувань, щоб пізнати стихію води. Попри скверну, що вразила духів-охоронців, сира первісна сила озера робить його обов'язковим місцем паломництва для тих, хто вчиться підкоряти й шанувати духів припливів."}},faq={{q="Де розташоване Озеро Містраль?",a="Озеро Містраль лежить на півдні центрального Ашенвалю — просто на південь від Притулку Срібного Вітру й на схід від Долини Глибокого Кігтя. Це найбільша відкрита водойма в лісі.",al={"де озеро містраль","розташування озера містраль","озеро містраль на мапі"}},{q="Чому тутешні водяні елементалі ворожі?",a="Спершу водяні елементалі були мирними й вірними нічним ельфам Ашенвалю. Проте чаклун-відступник Сарілус Фоулборн зіпсував їх, обернувши лагідну вдачу на нестримну ворожість до кожного, хто підходить до озера.",al={"чому водяні елементалі нападають","зіпсовані водяні елементалі","хто зіпсував озеро містраль"}},{q="Навіщо шамани приходять до Озера Містраль?",a="Шаманів Орди посилають до Озера Містраль під час духовних випробувань заради Поклику Води. Озеро має глибокий стихійний відгомін, тож це важливе місце, щоб зрозуміти духів води й налаштуватися на них.",al={"поклик води озеро містраль","завдання шамана озеро містраль"}},{q="Хто тримає Озеро Містраль?",a="Жодна фракція не має прямого військового контролю над самим озером. Нічні ельфи пильнують його з довколишніх застав, як-от Притулок Срібного Вітру, але у водах нині панують ворожі зіпсовані елементалі, що загрожують і Альянсу, і Орді.",al={"чи озеро містраль орди чи альянсу","хто володіє озером містраль"}}},fp="12,287,21.554.0,20.429.0,30.173.0,42.241.0,33.222.0,26.259.0"}
P.entries["subzone:nat-s-landing"] = {n="Причал Ната",s="Причал Ната — скромна рибальська стоянка на березі Затоки Пилоброду в Багні Пилоброду. Це особистий табір і прихисток Ната Паґла, якого вважають найславетнішим рибалкою Азерота. Шукачі пригод з усього світу добираються до цього невибагливого причалу, щоб удосконалити свою рибальську майстерність.",h="Причал Ната — скромна рибальська стоянка на березі Затоки Пилоброду в Багні Пилоброду.",kw={"причал ната","нат паґл","затока пилоброду","багно пилоброду","рибальство","рибалка"},ang={["faction:Alliance"]="Для громадян Альянсу, що служать у Тераморі, Причал Ната — коротка тиха прогулянка узбережжям до найкращого рибалки світу.",["faction:Horde"]="Рибалки Орди, які пробираються небезпечним болотом із Пусток, побачать, що Натові байдужа війна: він судить гостей лише за тим, як вони закидають вудку."},sec={{t="Притулок майстра",b="Причал Ната, захований на південний захід від Острова Терамор над каламутними водами Затоки Пилоброду, — це лише вивітрений табір: простий полотняний намет, сушарки, обважнілі від денного улову, запасні снасті на деревах і хиткий дерев'яний поміст, що виступає в затоку. Попри тумани й небезпеки болота, цей тихий клаптик берега дає легендарному рибалці Нату Паґлу усамітнене місце, де можна закинути вудку й спокійно випити подалі від гамору цивілізації."},{t="Паломництво рибалки",b="Хоч на перший погляд причал і непоказний, для початківців-рибалок це обов'язкова зупинка. Рибалок, які вичерпали науку звичайних наставників в Айронфорджі, Оргріммарі чи деінде, посилають сюди, щоб довести свою вартість самому Натові. Паґлу байдужі політика й чвари фракцій; кожен рибалка, що здолав болотяних хижаків і дістався до його пристані, мусить показати терпіння й уміння в найнебезпечніших водах світу, щоб отримати від нього найвищу науку."}},faq={{q="Де розташований Причал Ната?",a="Причал Ната стоїть на невеликому прибережному виступі над водами Затоки Пилоброду, на сході Багна Пилоброду, трохи на південний захід від Острова Терамор.",al={"де причал ната","розташування причалу ната","як дістатися до причалу ната"}},{q="Хто живе на Причалі Ната?",a="Причал — особистий табір Ната Паґла, славетного рибалки-людини, який цілими днями рибалить із помосту з чаркою в руці.",al={"хто на причалі ната","нпс причалу ната","хто тут живе"}},{q="Навіщо сюди приходять рибалки?",a="Коли рибалки опанують усе, чого можуть навчити їх наставники у великих столицях, їх посилають до Ната Паґла. Він перевіряє їхню відданість складними уловами по всьому світу, а тоді навчає їх майстерності найвищого рівня.",al={"навіщо йти до причалу ната","наставник рибальства майстра","навчання у ната паґла"}},{q="Чи радий Нат Паґл і Альянсу, і Орді?",a="Так. Нат Паґл ставиться до відданих рибалок нейтрально: йому однаково раді й мандрівники Альянсу з Терамора, і мандрівники Орди, що приходять із Пусток, — незалежно від фракції.",al={"чи причал ната ворожий","чи може орда говорити з натом","чи нат паґл нейтральний"}}},fp="13,320,16.503.0,26.473.0,31.167.0,27.139.0,27.229.0,47.184.0"}
P.entries["subzone:nek-mani-wellspring"] = {n="Джерело Нек'мані",s="Високо на скелях над Південним Диким Узбережжям ховається Джерело Нек'мані — фонтан напрочуд чистої святої води. Воно славиться як єдине незаймане джерело прісної води на південь від Сутінколісся. Утім, нещодавно цю священну місцину захопили ворожі наги-дослідники, які ревно стережуть його води.",h="Високо на скелях над Південним Диким Узбережжям ховається Джерело Нек'мані — фонтан напрочуд чистої святої...",kw={"джерело нек'мані","свята вода","наги","долина стренглторну","прісна вода","прочани"},ang={["class:Priest"]="Перекази про божественне походження вод Нек'мані роблять джерело справжньою цікавинкою для жерців, хоча суперечка про те, якій вірі воно належить, давно стала нескінченною темою вчених диспутів."},sec={{t="Священна чаша",b="Джерело Нек'мані сховалося серед зубчастих прибережних висот на заході Долини Стренглторну. Воно дає єдину чисту прісну воду на південь від Сутінколісся, тож чимало вчених і прочан називають його святим. Різні народи й традиції запевняють, що його божественні води благословлені саме для них, і тому джерело досі розпалює жваві богословські суперечки. Та попри духовну славу, спокійно поміркувати тут не вдасться: нещодавно чашу джерела захопив лютий загін наг, і тепер вони боронять воду від усіх непроханих гостей."}},faq={{q="Чим особливе Джерело Нек'мані?",a="Джерело дає надзвичайно чисту святу воду: кажуть, що це єдине незаймане джерело зовсім свіжої води в дикому краї на південь від Сутінколісся. Чимало релігійних учених вважають його воду божественною, хоча різні віри сперечаються, для чийого народу вона була призначена спершу.",al={"чому нек'мані важливе","що таке свята вода ясності","святе джерело стренґлторну"}},{q="Де саме розташоване джерело?",a="Воно високо на скелі над Південним Диким Узбережжям, на західних берегах Долини Стренглторну.",al={"де джерело нек'мані","як знайти нек'мані","розташування нек'мані"}},{q="Хто зараз тримає Джерело Нек'мані?",a="Нещодавно експедиція ворожих наг рушила з океану вглиб суходолу й захопила священну чашу, люто нападаючи на кожного, хто підходить до води.",al={"хто на нек'мані","монстри нек'мані","наги нек'мані"}},{q="Навіщо шукачів пригод посилають до цього джерела?",a="Мандрівники й дослідники шукають святу воду джерела для могутніх зачарувань, очищень і алхімічних сумішей, які вимагають абсолютно чистої води.",al={"завдання нек'мані","завдання зі святою водою","чиста вода стренґлторну"}}},fp="19,322,14.571.0,43.288.0,40.121.0,47.153.0,40.168.0"}
P.entries["subzone:nesingwary-s-expedition"] = {n="Експедиція Несінґварі",s="Експедиція Несінґварі — простий мисливський табір на півночі Долини Стренглторну, трохи північніше від Озера Назферіті. Його заснував славетний дворф-стрілець Гемет Несінгварі, і тепер табір править за вихідну точку для мисливців, які хочуть помірятися силою з найлютішими хижаками джунглів.",h="Експедиція Несінґварі — простий мисливський табір на півночі Долини Стренглторну, трохи північніше від Озера...",kw={"експедиція несінґварі","гемет несінгварі","мисливці","полювання","долина стренглторну","рукопис"},ang={["class:Hunter"]="Для стрільців і приборкувачів звірів цей табір — справжній полігон, де ви можете відточити вміння вистежувати найнебезпечніших хижаків Долини Стренглторну.",["race:Dwarf"]="Гемет Несінгварі та інші горяни з Каз Модану, що облаштували квітучий табір посеред вологих тропічних нетрів, — знайома картина дворфійської завзятості й любові до полювання."},sec={{t="Мисливська застава в джунглях",b="Цей віддалений табір притулився біля річки на північ від Озера Назферіті й гуде, мов вулик: тут збираються мисливці на велику дичину, слідопити й стрільці. Гемет Несінгварі заснував його, щоб вистежувати легендарних звірів Долини Стренглторну, а поруч із ним — досвідчені товариші: Сер С. Дж. Ерлґадін, Аджек Роак і Барніл Стоунпот. Табір стережуть наймані стрільці, а постачають нейтральні торговці, тож тут раді кожному, хто вміє тримати рушницю чи лук, хоч до якої сторони він належить. Усіх їх єднає одна пристрасть — вистежити найнебезпечніших хижаків, яких лише можуть запропонувати джунглі."},{t="Сторінки й хижаки",b="Життя в таборі експедиції обертається довкола запеклого суперництва й неймовірних мисливських байок. Мисливцям раз у раз кидають виклик: навчитися вистежувати й уполювати місцевих пантер, рапторів і тигрів, аж поки справа не дійде до полювання на найгрізніших звірів. Окрім азарту погоні, табір має й власні дрібні клопоти: передусім величезний рукопис Несінгварі, сторінки якого розлетілися по всіх нетрях, тож табірні книжники прагнуть розшукати кожен загублений розділ."}},faq={{q="Хто керує Експедицією Несінґварі?",a="Табір заснував і очолює легендарний дворф-мисливець на велику дичину Гемет Несінгварі разом із гуртом досвідчених стрільців.",al={"хто керує табором","лідер табору несінґварі","хто тут головний"}},{q="Чому експедиція тут, у Долині Стренглторну?",a="Експедиція прибула до Стренглторну, щоб полювати на найнебезпечніших звірів густих джунглів — пантер, агресивних рапторів, лютих тигрів і легендарних звірів-трофеїв.",al={"що вони тут роблять","чому несінґварі в стренглторні","призначення табору"}},{q="Чи привітна Експедиція Несінґварі і до Альянсу, і до Орди?",a="Так. Табір — нейтральна мисливська артіль. Найняті Несінгварі стрільці підтримують мир, доки гості шанують табір, і раді мисливцям і з Альянсу, і з Орди, які хочуть довести свою майстерність слідопитів.",al={"чи нейтральна експедиція несінґварі","чи може орда відвідати несінґварі","чи може альянс відвідати несінґварі"}},{q="Що за історія із загубленими сторінками рукопису?",a="Гемет Несінгварі написав великі мисливські спогади під назвою «Зелені Пагорби Стренглторну». На жаль, окремі сторінки рукопису розлетілися по нетрях, тож архіваріус табору Барніл Стоунпот просить мандрівників їх знайти.",al={"зелені пагорби стренґлторну історія","чому сторінки розкидані","книга барніла стоунпота"}}},fp="23,306,32.579.0,19.482.0,33.130.0,49.188.0,63.211.0,54.255.0"}
P.entries["subzone:nethander-stead"] = {n="Хутір Нетандера",s="Хутір Нетандера — покинуте господарство при дорозі трохи на схід від Саутшора в Передгір'ї Гілсбреда. Колись тут працювала людська ферма, а тепер вона лежить у руїні, і її цілком захопила зграя гнолів Багнорилів. Поля поросли велетенськими білими грибами, відомими як Суцвіття Багнорила, — і вони цікавлять алхіміків Відступників.",h="Хутір Нетандера — покинуте господарство при дорозі трохи на схід від Саутшора в Передгір'ї Гілсбреда.",kw={"хутір нетандера","саутшор","гноли","багнорили","гриби","аптекарі","гілсбред"},ang={["faction:Alliance"]="Захоплений хутір — тривожне нагадування про те, які хиткі досі межі Саутшора: дикі гноли окопалися лише трохи далі східною дорогою.",["faction:Horde"]="Щоб зібрати Суцвіття Багнорила для смертоносних досліджень Королівського Аптекарського Товариства, вам доведеться пробратися на цей хутір біля Саутшора."},sec={{t="Зруйнована садиба",b="Хутір Нетандера, видний зі східних меж Саутшора, колись був живою частиною хліборобського краю. Як і більшість господарств у східних передгір'ях, його покинули, коли безпека в краї похитнулася й сюди посунули дикі зграї. Нині це єдиний осідок гнолів Багнорилів у передгір'ях. Звірюки живуть серед поламаних парканів і господарських будівель і люто проганяють кожного мандрівника, що надто наблизиться до їхніх володінь."},{t="Суцвіття Багнорила",b="На занедбаній землі хутора буйно розрослися незвичні гриби. Велетенські бліді гриби, відомі як Суцвіття Багнорила, вкривають покинуті ділянки. У них є сильні природні отрути, і це привернуло увагу Королівського Аптекарського Товариства в Таррен Міллі. Аптекарям потрібні зразки, зібрані просто на землях гнолів, щоб виганяти з них їдкі зілля, — тож цей нікчемний хутір став ціллю таємних вилазок Орди на землі Альянсу."}},faq={{q="Що таке Хутір Нетандера?",a="Хутір Нетандера — покинута людська ферма трохи на схід від Саутшора в Передгір'ї Гілсбреда. Її цілком заполонила ворожа зграя гнолів-Багнорилів.",al={"що це за ферма","інформація про хутір нетандера","де хутір нетандера"}},{q="Хто зараз тримає Хутір Нетандера?",a="На хуторі отаборилося плем'я гнолів-Багнорилів. Це єдине місце в Передгір'ї Гілсбреда, де ця зграя стоїть табором.",al={"хто тут живе","хто на хуторі нетандера","які моби тут"}},{q="Що за велетенські білі гриби ростуть на полях?",a="Це Суцвіття Багнорила — великі білі гриби, що буяють на необробленій землі хутора. Вони отруйні, тож цінні для алхіміків-Відступників, які досліджують отрути.",al={"білі гриби","гриби мадснаута","квіти мадснаута"}},{q="Чому Орду цікавить ця зруйнована ферма?",a="Аптекар Лайдон із Таррен Мілла шукає Суцвіття Багнорила, що ростуть на полях хутора. Їхній їдкий сік — неодмінний складник Еліксиру Агонії.",al={"навіщо орді йти сюди","інтерес відступників","завдання орди нетандер"}}},fp="15,347,18.467.0,21.472.1,24.169.0,39.145.0,57.190.0,47.169.0"}
P.entries["subzone:nethergarde-keep"] = {n="Замок Незерґард",s="Замок Незерґард — укріплена твердиня Альянсу високо на кручах над дорогою, що веде до Спустошених Земель. Зведений Гільдією Каменярів після Другої війни, він пильно вартує приспаний Темний Портал і хаотичні енергії, що розтікаються червоними пустирями. Нині маги й гарнізони, яких підтримує Стормвінд, і далі несуть свою самотню варту проти демонів і залишків скверни.",h="Замок Незерґард — укріплена твердиня Альянсу високо на кручах над дорогою, що веде до Спустошених Земель.",kw={"незерґард","замок","альянс","темний портал","кірін-тор","хадґар","спустошені землі"},ang={["class:Mage"]="Для знавців таємної магії Незерґард — це десятиліття досліджень Кірін-Тору: міжвимірні розриви, їхнє запечатування й стримування руйнівного поширення скверни.",["faction:Alliance"]="Фортеця — один із найважливіших передових бастіонів Альянсу, оплачений кров'ю та золотом, щоб жахи Першої й Другої воєн ніколи більше не вихлюпнулися з порталу."},sec={{t="Вартовий проти червоного світу",b="Коли наприкінці Другої війни Темний Портал зруйнували, архімаг Хадґар і провідники Альянсу Лордерону зрозуміли, що Азерот більше ніколи не може лишити розрив без охорони. Під наглядом Едвіна Венкліфа Гільдія Каменярів звела вздовж перевалу до Спустошених Земель високі бастіони, казарми й шпилі для магів. Чарівники Кірін-Тору, що служили тут, мали подвійну місію: невпинно стежити за зруйнованою брамою й плести обереги, які не давали б демонічній порчі випаленого краю розповзтися на північ, до людських королівств."},{t="Самотня варта",b="Коли Темний Портал знову відчинився й Експедиція Альянсу вирушила на Дренор, Хадґар і його товариші запечатали браму за собою, залишивши Незерґард стерегти мовчазні рештки. Два десятиліття вчені з Даларана й зі Святилища Чародія досліджують залишкові енергії порталу, спотворену місцеву фауну й вторгнення демонів. Відколи Даларан спустошили під час Третьої війни, Незерґард цілком залежить від обозів зі Стормвінда, які утримують його воїнів і магів, поки ті самотою протистоять жахам пустирів."}},faq={{q="Навіщо збудували Замок Незерґард?",a="Його заклали після Другої війни архімаг Хадґар і Альянс Лордерона, щоб стерегтися нової навали орків із Дренору й стримувати демонічну скверну, що розповзалася Спустошеними Землями.",al={"призначення незерґарда","чому незерґард тут","історія незерґарда"}},{q="Хто збудував замок?",a="Замок Незерґард збудувала Гільдія Каменярів під архітектурним проводом Едвіна Венкліфа, а оплатили будівництво спільно королівства — члени Альянсу Лордерона.",al={"хто збудував незерґард","будівельники незерґарда","ванкліф незерґард"}},{q="Хто тепер командує фортецею й постачає її?",a="Спершу фортецю утримував Кірін-Тор Даларану, але після того, як Даларан упав під ударами Погибелі й Легіону, вона покладається насамперед на королівство Стормвінд — на його війська, регулярні обози й постачання.",al={"хто керує незерґардом","постачання незерґарда","стормвінд незерґард"}},{q="Що вивчають маги в замку?",a="Дослідники зі Святилища Чародія вивчають приспану енергію Темного Порталу, дивні мутації місцевих звірів і способи захиститися від скверни, що нависає над червоною землею.",al={"маги незерґарда","святилище чародія незерґард","що вони досліджують"}}},fp="16,416,32.597.0,16.556.0,31.211.0,25.172.0,43.223.0,44.205.0"}
P.entries["subzone:night-run"] = {n="Нічний Потік",s="Нічний Потік — невелика відлюдна застава сатирів на оточеному кручами пагорбі в східно-центральному Ашенвалі. Тут живуть демонічні сатири Мускусу Скверни, які перетворили давні ельфійські руїни на осквернений табір, де ховають темну магію душ.",h="Нічний Потік — невелика відлюдна застава сатирів на оточеному кручами пагорбі в східно-центральному Ашенвалі.",kw={"нічний потік","сатири","сквернопахі","культ темного берега","самоцвіти душ","ашенваль"},ang={["faction:Alliance"]="Нічний Потік, що лежить трохи на північ від Притулку Рейнвуд, — постійна демонічна загроза, яка нависає над важливими шляхами постачання Вартових.",["race:NightElf"]="Осквернення Нічного Потоку — незагойний шрам: це давнє каміння просякло кров'ю нічних ельфів ще під час Війни Сатирів і досі сплюндроване спотвореними Мускусу Скверни."},sec={{t="Неприступне гніздо на кручі",b="Нічний Потік — найменша й найвіддаленіша з трьох головних твердинь сатирів в Ашенвалі, поряд із Ксавіаном і Сатирнааром. Поселення, що ховається серед напівзруйнованої ельфійської кладки й поламаних колон, виступає на високому гребені, обмеженому стрімкими неприступними кручами. Щоб дістатися сюди, доводиться або йти кружним шляхом уздовж Річки Фалфаррен біля вод Ксавіана, або пробиратися небезпечним північним уступом над Притулком Рейнвуд. Попри скромні розміри, це гніздо дуже небезпечне: сатири Мускусу Скверни діють разом із таємничим Культом Темного Берега й закріплюють тут спотворені самоцвіти душ, що збирають демонічну есенцію в лісі."}},faq={{q="Хто тримає Нічний Потік?",a="Нічний Потік займають сатири Мускусу Скверни — угруповання демонічних сквернителів, колишніх нічних ельфів, пов'язаних із Культом Темного Берега.",al={"хто живе в нічному потоці","моби нічного потоку","що в нічному потоці"}},{q="Як дістатися до Нічного Потоку?",a="Він лежить на високому урвищі серед прямовисних скель, тож мандрівникам доведеться підійти або вузьким уступом на північ від Притулку Рейнвуд, або вздовж Річки Фалфаррен у бік Ксавіана, а тоді звернути на захід, угору на кряж.",al={"як дістатися до нічного потоку","шлях до нічного потоку","вхід у нічний потік"}},{q="Що робить тут Культ Темного Берега?",a="Культ діє разом із сатирами: у Нічному Потоці вони тримають темний самоцвіт душ, щоб збирати демонічну енергію й спрямовувати її по всьому Ашенвалю.",al={"культ темного берега нічний потік","камінь душі нічного потоку"}},{q="Які історичні події відбулися в Нічному Потоці?",a="Тисячі років тому, після Великого Розколу, перші друїди в дикій Подобі Зграї напали тут на Вартових нічних ельфів і поранили Шандріс Фезермун — це був вибуховий початок Війни Сатирів.",al={"лор нічного потоку","війна сатирів нічний потік"}}},fp="9,235,26.643.0,23.130.0,27.228.0,47.138.0,45.219.0"}
P.entries["subzone:night-web-s-hollow"] = {n="Лощина Нічної Павутини",s="Лощина Нічної Павутини — запала долина й покинута золота копальня одразу на північний захід від Похоронного Подзвону в Галявинах Тірісфалю. Густо заполонена павуками, вона править за полігон для щойно пробуджених Відступників, яких посилають винищити гидь і довести бойову готовність.",h="Лощина Нічної Павутини — запала долина й покинута золота копальня одразу на північний захід від Похоронного...",kw={"лощина нічної павутини","павуки","золота копальня","похоронний подзвін","випробування","тірісфаль"},ang={["profession:Mining"]="Хоч шахти спершу копали заради золота, видобуток тут давно припинено через смертоносну павучу навалу.",["race:Undead"]="Для щойно воскреслих лощина — одне з ваших найперших випробувань. Убивство павуків доводить, що ви маєте зосередженість і силу волі, потрібні для служби Темній Леді."},sec={{t="Заражена копальня",b="Tucked away in the northern hills of Deathknell, Night Web's Hollow was once an ordinary human gold mine before the plague swept through Lordaeron. In the aftermath of the kingdom's fall, the shafts were entirely abandoned to nature. Today, thick strands of webbing shroud the rock walls and suffocating shadows conceal a thriving colony of aggressive night web spiders. Freshly raised Forsaken are routinely dispatched into the hollow and its subterranean tunnels to cull the young and adult spiders so the Forsaken can regain access to the mine's gold."}},faq={{q="Що таке Лощина Нічної Павутини?",a="Це покинута золота копальня й невеликий яр на північний захід від Похоронного Подзвону. Обплутана павутинням і повна агресивних павуків, вона — одне з перших місць випробування для новобранців-Відступників.",al={"лощина нічної павутини","павуча шахта дедненелл","павуча печера тіріфаль"}},{q="Навіщо Відступники винищують павуків?",a="The Forsaken need the mine's gold but cannot reach it while spiders infest the tunnels. Executor Arren has little manpower to spare, so he asks new recruits to help clear the infestation gradually.",al={"навіщо відступники вбивають павуків","завдання про павуків дедненелл"}},{q="Хто живе глибоко в штольнях копальні?",a="Молоді павуки снують назовні, у долині, а дорослі нічні тенетники нишпорять тунелями копальні. У найглибшій, найтемнішій залі сидить Матріарх Нічних Тенетників — праматір усього цього поріддя.",al={"бос павуків у шахті","де матріарх нічної павутини"}},{q="Чи завжди тут було павуче лігво?",a="Ні. До падіння Лордерона це була діюча золота копальня, де працювали місцеві люди. Після того як Погибель винищила край, штольні занепали, і павуки оселилися в темних, захищених тунелях.",al={"хто викопав шахту","історія шахти дедненелл"}}},fp="18,266,17.554.0,27.197.0,46.197.0,39.208.0,29.221.0"}
P.entries["subzone:nighthaven"] = {n="Нічний Притулок",s="Нічний Притулок — відлюдне поселення на північному березі Озера Елуне'ара в Місячному Гаю. Це серце Кола Кенарія, притулок, де друїди — нічні ельфи й таурени — мирно навчаються разом, далеко від війн між фракціями Азерота.",h="Нічний Притулок — відлюдне поселення на північному березі Озера Елуне'ара в Місячному Гаю.",kw={"нічний притулок","місячний гай","коло кенарія","друїди","озеро елуне'ара","місячний фестиваль"},ang={["class:Druid"]="Нічний Притулок — ваш духовний дім далеко від дому. Завдяки вмінню «Телепортація: Місячний Гай» ви миттю потрапляєте до наставників вашого ордену, до випробувань звірячих подоб і до особливих повітряних шляхів у Селище Рут'теран чи Тандер Блаф.",["profession:Herbalism"]="Нічний Притулок — мирне місце, де серед тихих гаїв Місячного Гаю можна порадитися з наставниками травництва."},sec={{t="Святиня Кола Кенарія",b="Збудований у традиційному стилі нічних ельфів на тихому березі Озера Елуне'ара, Нічний Притулок — спокійний закуток, майже відрізаний від зовнішнього світу. Тут місячні колодязі лагідно освітлюють гаї й зали, присвячені збереженню природної рівноваги. Як головний осередок Кола Кенарія, поселення має наставників, травників і особливих постачальників для новачків-друїдів. Притулок суворо дотримується нейтралітету й радо приймає кожного, хоч би кому — Альянсу чи Орді — той був вірний удома."},{t="Давня історія й священні зібрання",b="Спокій Нічного Притулку не раз зазнавав випробувань. Через століття після Війни Прадавніх тут зібралися герої, щоб протистояти розлюченому напівбогові Омену, і загнали його на дно Озера Елуне'ара. А ще поселення відчиняє свої відлюдні межі під час Місячного фестивалю й вітає прочан з усього Азерота, які приходять ушанувати предків і святкувати під пильним поглядом Елуни."}},faq={{q="Хто править чи наглядає за Нічним Притулком?",a="Нічним Притулком керує Коло Кенарія під проводом Хранителя Ремулоса й старших друїдів, як-от Лоґанаар. Це незалежний нейтральний прихисток, а не земля уряду нічних ельфів.",al={"хто керує нічним притулком","лідери нічного притулку","хто головний тут"}},{q="Чи можуть відвідати Нічний Притулок не друїди?",a="Так. Не друїди можуть дістатися Місячного Гаю тунелями Деревопащих або скористатися загальними розпорядниками польотів в інших куточках долини, а звідти дійти до Нічного Притулку. Розпорядники польотів самого селища обслуговують лише друїдів.",al={"чи можуть недруїди зайти в нічний притулок","як недруїдам потрапити сюди"}},{q="Чому нічні ельфи й таурени живуть тут у мирі?",a="Коло Кенарія понад усю політику фракцій ставить зцілення природи й Смарагдового Сну. У Місячному Гаю його члени дають обітницю нейтральності, відкладають убік суперництво Альянсу й Орди й вивчають друїдство як рівні.",al={"чому тут немає бою","чому таурени тут дозволені","мир орди й альянсу"}},{q="Які польоти доступні з Нічного Притулку?",a="Особливі розпорядники польотів Кенарія возять лише друїдів: гіпогрифи повертають друїдів Альянсу до Селища Рут'теран, а вітрокрили відносять друїдів Орди назад до Тандер Блафа.",al={"майстри польотів нічного притулку","куди звідси летіти"}}},fp="10,253,34.541.0,37.385.0,33.224.0,32.202.0,63.228.0,49.198.0"}
P.entries["subzone:nightmare-vale"] = {n="Долина Жахіть",s="Долина Жахіть — тіниста улоговина в південно-західних Галявинах Тірісфалю, одразу на захід від Застави Хрестоносця. Колись пишний лісовий притулок, тепер її дерева всохли від пошесті, а серед покручених стовбурів нишпорять люті хижаки.",h="Долина Жахіть — тіниста улоговина в південно-західних Галявинах Тірісфалю, одразу на захід від Застави...",kw={"долина жахіть","темні гончаки","кажани-вампіри","рессан колій","тірісфаль","застава хрестоносця"},ang={["class:Hunter"]="У долині водяться люті темні гончаки й кажани-вампіри, зокрема рідкісний білий кажан Рессан Колій, тож це примітний полігон для мисливців, які шукають грізних звірів.",["race:Undead"]="Покручена живність Долини Жахіть нагадує про незгладний слід чуми по всьому Тірісфалю й становить пряму загрозу мандрівникам з-поміж Відступників, що вирушають за межі Брілла."},sec={{t="Струхлявіла пуща",b="До Третьої війни ця долина була зеленою частиною сільського Тірісфалю, повною співочих птахів і звичайної лісової дичини. Після чуми Погибелі рослинність почорніла й згнила. Ненажерливі темні гончаки й величезні кажани-вампіри пожерли місцеву живність, обернувши улоговину на похмурий притулок падложерів і хижих звірів."},{t="Мисливці улоговини",b="У тінях Долини Жахіть чаїться Рессан Колій — незвично великий блідий кажан-вампір, сумнозвісний серед місцевих подорожніх. Незатишно затиснута між примарною пущею й ревними вартовими сусідньої Застави Хрестоносця, долина — безжальний простір, де необачні шукачі пригод швидко стають здобиччю."}},faq={{q="Де розташована Долина Жахіть?",a="Долина Жахіть лежить на південному заході Галявин Тірісфалю, трохи на захід від Застави Хрестоносця.",al={"розташування долини жахіть","де долина жахіть","знайти долину жахіть"}},{q="Чому долина зветься Долиною Жахіть?",a="Колись мирний, буйний ліс, долина цілком скорилася чумі, що спустошила Лордерон. Зів'ялі дерева й хижаки — голодні темні гончаки та кажани-кровопивці — перетворюють її на жахіття наяву для кожного, хто тут проходить.",al={"чому долина жахіть","лор долини жахіть"}},{q="Хто блукає Долиною Жахіть?",a="Долину заполонили люті темні гончаки й величезні кажани-вампіри, що вигнали чи пожерли місцевих лісових звірів. У цій улоговині також полює рідкісний білий кажан-вампір Рессан Колій.",al={"моби долини жахіть","монстри долини жахіть","звірі тут"}},{q="Хто такий Рессан Колій?",a="Рессан Колій — рідкісний, сліпучо-білий кажан-вампір, що полює в темному небі над зів'ялими кронами Долини Жахіть.",al={"рессан","рессан колій","рідкісний кажан тіріфаль"}}},fp="14,238,20.366.0,22.325.0,32.111.0,40.250.0,35.196.0,26.126.0"}
P.entries["subzone:nightsong-woods"] = {n="Ліс Нічної Пісні",s="Ліс Нічної Пісні — охоплений боями східний простір Ашенвалю, що тягнеться від Притулку Рейнвуд до кордонів Азшари. Це головне поле битви між нічними ельфами, які боронять свій священний ліс, і кланом Бойової Пісні, що заготовляє деревину для Орди. Серед його тінистих галявин давні гаї протистоять укріпленим таборам, а довкола не вщухає демонічна скверна.",h="Ліс Нічної Пісні — охоплений боями східний простір Ашенвалю, що тягнеться від Притулку Рейнвуд до кордонів...",kw={"ліс нічної пісні","бойова пісня","вартові срібнокрилих","застава розщепленого дерева","вирубки","ашенваль"},ang={["faction:Horde"]="Цей східний фронт забезпечує Орду цінною будівельною деревиною й важливими шляхами постачання через Заставу Розщепленого Дерева, тож тут треба остерігатися засідок Вартових і демонічних звірів.",["race:NightElf"]="Ліс Нічної Пісні — священне прикордоння в облозі: боронити його давні гаї від сокир Бойової Пісні й викорінювати скверну сатирів — найперший обов'язок калдореїв."},sec={{t="Ліс, пошрамований війною",b="Ліс Нічної Пісні, що простягається через Ашенваль на схід аж до Азшари, — край, де насильство тільки наростає. Річка Фалфаррен розтинає його західну частину, утворюючи хитку межу між поселеннями Альянсу та загарбаними землями Орди. Далі на схід ліс розпадається на запекло спірні території, де Застава Розщепленого Дерева керує походами Орди проти Вартових Срібнокрилих. Орківські сокири невпинно вирубують південні гаї, живлячи розширення Орди й залишаючи голі просіки, що доводять калдореїв до люті. Небезпеки додають твердині сатирів на кшталт Сатирнаару й Ксавіана та демонічні рештки в Каньйоні Падіння Демона й на Пагорбі Вогню Скверни, які отруюють східні крони."}},faq={{q="Де розташований Ліс Нічної Пісні?",a="Ліс Нічної Пісні охоплює східну половину Ашенвалю. Його межі тягнуться від Притулку Рейнвуд і північної дороги до Сквернолісся аж на схід, до дикого кордону з Азшарою.",al={"розташування лісу нічної пісні","де ліс нічної пісні","східний ліс ашенвейлу"}},{q="Чому в цій частині Ашенвалю так багато боїв?",a="Цей край — лінія фронту між Вартовими Срібнокрилих і кланом Бойової Пісні. Орда дуже залежить від цінної деревини, яку рубає на півдні, щоб будувати й утримувати свої поселення, а нічні ельфи запекло борються, щоб зупинити суцільну вирубку й повернути землю предків.",al={"чому в лісі нічної пісні бої","орда проти альянсу ашенвейл","конфлікт співаків війни"}},{q="Хто тримає Ліс Нічної Пісні?",a="Жодна фракція не панує в лісі одноосібно. Річка Фалфаррен приблизно відділяє західні землі Альянсу від східних позицій Орди довкола Застави Розщепленого Дерева й Лісозаготівельного Табору Бойової Пісні. Окремі клапті лісу тримають і зіпсовані сатири — у Сатирнаарі й Ксавіані, — і сили Легіону біля Каньйону Падіння Демона.",al={"хто володіє лісом нічної пісні","контроль фракцій лісу нічної пісні"}},{q="Які демонічні загрози тут є?",a="Східні нетрі зазнають сильного демонічного й руйнівного впливу. Сатири живуть в укріплених давніх руїнах, як-от Сатирнаар і Ксавіан, а рештки демонів Палаючого Легіону засіли на Пагорбі Вогню Скверни й у глибинах Каньйону Падіння Демона.",al={"демони лісу нічної пісні","сатири східного ашенвейлу","демони пагорба вогню скверни"}}},fp="15,388,22.678.0,38.187.0,56.319.0,29.325.0,32.240.0"}
P.entries["subzone:nijel-s-point"] = {n="Мис Ніджела",s="Мис Ніджела — укріплений редут Альянсу й Кола Кенарія високо на північних кручах Пустограю. Він стоїть далеко від сплюндрованих долин унизу й слугує єдиним безпечним притулком для мандрівників, дослідників і вояків Альянсу в цьому суворому пустирі.",h="Мис Ніджела — укріплений редут Альянсу й Кола Кенарія високо на північних кручах Пустограю.",kw={"мис ніджела","пустограй","альянс","коло кенарія","хранитель марандіс","мародон","капітан пентіґаст"},ang={["class:Druid"]="Хранитель Марандіс використовує цей високогірний прихисток, щоб організувати повернення останків Заетара зі скверни, що гноїться в Мародоні.",["faction:Alliance"]="Мис Ніджела — ваш єдиний укріплений притулок і пункт польотів у Пустограї, що з'єднує шляхи постачання між Горами Кам'яного Кігтя, Терамором і Фераласом."},sec={{t="Бастіон над пустирями",b="Видовбаний у прямовисних скелях на межі з Горами Кам'яного Кігтя, Мис Ніджела височить над сірим пилом і зграями кентаврів-мародерів Пустограю. Поселення тримає загін армії Стормвінда під командою Капітана Пентіґаста, якому доручено стежити за жорстокими клановими війнами, що загрожують інтересам Альянсу на півдні Калімдору. Висота й вузькі стежки роблять мис легким для оборони, тож це надійний плацдарм для гінців, розвідників і вершників на грифонах, що літають між Піком Кам'яного Кігтя, Терамором і Твердинею Перистого Місяця."},{t="Експедиції Кола й Хрестового Походу",b="Окрім стормвіндського гарнізону, застава прихищає посланців із власними, небезпечними цілями. Хранитель Марандіс і його дріади використовують табір як базу, щоб кинути виклик Принцесі Терадрас глибоко в Мародоні й повернути останки полеглого напівбога Заетара. Навіть Багряний Хрестовий Похід тримає тут свого посланця — Брата Антона, який прагне винищити нежить, що спустошує дно долини. Попри метушню вояків і друїдів, хто такий сам Ніджел — давня загадка, розгадки якої не знають навіть ті, хто несе службу на хребті."}},faq={{q="Чому Альянс стоїть у Пустограї?",a="Капітан Пентіґаст очолює загін армії Стормвінда, що стежить за ворогуючими кланами кентаврів. Альянс побоюється: щойно один клан винищить інші, переможна орда оберне свою лють на сусідні землі й поселення — у Горах Кам'яного Кігтя й Фераласі.",al={"чому альянс у дезоласі","армія стормвінда в дезоласі","чому існує мис ніджела"}},{q="Хто такий Ніджел?",a="Схоже, на заставі ніхто цього не знає. Його справжня історія загубилася в часі.",al={"хто такий ніджел","ніджел історія","на честь кого мис ніджела"}},{q="Що робить Коло Кенарія на Мисі Ніджела?",a="Хранитель Марандіс і його сестри-дріади прибули до Пустограю, щоб очистити Мародон, убити Принцесу Терадрас і повернути рештки Заетара до священних гаїв Гір Кам'яного Кігтя.",al={"друїди на мисі ніджела","місія наглядача маранді","чому тут дріади"}},{q="Чому на Мисі Ніджела Багряний Хрестовий Похід?",a="Брат Антон — далекий посланець Багряного Хрестового Походу. Брат Кроулі в Стормвінді посилає до нього шукачів пригод з Альянсу, а він випробовує їхню рішучість у боях із нежиттю-спустошувачами в Долині Кісток у Пустограї.",al={"брат антон багряний похід","багряний хрестовий похід у дезоласі"}}},fp="13,281,26.564.0,32.548.0,42.271.0,14.76.0,51.202.0,44.216.0"}
P.entries["subzone:north-coast"] = {n="Північне Узбережжя",s="Північне Узбережжя — похмура, оповита туманом смуга берега, що позначає північний край Галявин Тірісфалю вздовж Великого Моря. Отруєні падінням Лордерона, холодні пляжі всіяні гнилою морською живністю, і їх запекло боронять племена ворожих мурлоків.",h="Північне Узбережжя — похмура, оповита туманом смуга берега, що позначає північний край Галявин Тірісфалю...",kw={"північне узбережжя","берег","мурлоки","мерзенний плавець","діб","тірісфаль","велике море"},ang={["race:Undead"]="Поки патрульні маршрути Відступників тримаються дороги через Брілл, зачистка Північного Узбережжя від мурлоків, що насуваються, тримає північний фланг Галявин Тірісфалю у відносній безпеці."},sec={{t="Уражений чумою берег",b="До Третьої війни ці північні води й кам'янисті пляжі були частиною мирного північного рубежу Лордерона. Коли Чума Нежиті прокотилася континентом, її згубна пошесть стекла з круч і отруїла узбережжя. Води стали холодними й каламутними, викидаючи туші велетенських морських створінь, що тепер гниють на піску серед вічного прибережного туману."},{t="Берег Темноплавців",b="Коли людське королівство було розбите, а Відступники зосередили увагу довкола Брілла й столичного міста, прибережні мурлоки захопили безлюдні піски. Місцеве плем'я Темноплавців тримає хатини вздовж прибою й використовує сусідні мілини як нерестовища. Зграї ненажерливих мурлоків, серед них помітні постаті на кшталт Діба й численні пуголовки, що підростають, люто стережуть лінію припливу від усіх, хто живе на суходолі."}},faq={{q="Хто живе на Північному Узбережжі?",a="На пляжі здебільшого хазяйнують агресивні мурлоки-Темноплавці, їхні пуголовки й падлоїди, що порпаються в гнилих морських тваринах, яких Велике Море викидає на берег.",al={"моби північного узбережжя","хто живе на північному узбережжі","монстри північного узбережжя"}},{q="Хто такий Діб?",a="Діб — окремий мурлок, якого можна зустріти на Північному Узбережжі серед хиж і мілин.",al={"діб","мурлок діб","хто такий діб"}},{q="Чому узбережжя вкрите гнилими тушами?",a="Чума нежиття, що спустошила Лордерон, просочилася в прибережну природу й отруїла мілини, тож мертвих морських звірів викидає на берег, і вони гниють на зачумленому піску.",al={"мертві морські чудовиська","викинуті кити тіріфаль","чому мертві істоти"}},{q="Чи борються за Північне Узбережжя великі фракції?",a="Ні Відступники, ні рештки Альянсу не тримають на Північному Узбережжі гарнізонів. Це дикі, неприборкані околиці, полишені здебільшого мурлокам і морській наволочі.",al={"хто володіє північним узбережжям","відступники на північному узбережжі"}}},fp="11,272,20.385.0,18.410.0,39.165.0,12.119.0,46.192.0,51.162.0"}
P.entries["subzone:north-gate-outpost"] = {n="Застава Північної Брами",s="Застава Північної Брами — укріплений дворфський табір високо на Перевалі Північної Брами в Дун Мороґу. Охороняючи суворий шлях між засніженим серцем земель Айронфорджа та Лох Моданом, тутешні горяни боронять мандрівників від ворожої звірини, якою кишать скелі.",h="Застава Північної Брами — укріплений дворфський табір високо на Перевалі Північної Брами в Дун Мороґу.",kw={"застава північної брами","перевал","горяни","лох модан","патрулі","дун мороґ"},ang={["race:Dwarf"]="Застава показує стоїчну відданість горян Айронфорджа, які тримають суворі високогірні перевали відкритими попри мороз і хижаків.",["race:Gnome"]="Розселившись по Дун Мороґу, гноми часто допомагають дворфському гарнізонові своєю кмітливістю та влучністю, вистежуючи зниклі патрулі."},sec={{t="Варта перевалу",b="Розташоване посеред Перевалу Північної Брами, це невелике поселення — північно-східний поріг Дун Мороґу. Дворфські горяни, що стоять тут, очищають головну дорогу від хижаків і стежать за рухом крізь гірські тунелі до Лох Модану. Суворий клімат і круті яри роблять патрулювання небезпечним, тож гарнізон часто просить мандрівників обшукати навколишні хребти в пошуках зниклих патрулів і небезпечних хижаків."}},faq={{q="Для чого потрібна Застава Північної Брами?",a="Це гірський військовий пост, що охороняє Перевал Північної Брами — північну дорогу між Дун Мороґом і Лох Моданом. Горяни, що стоять тут, тримають перевал відкритим для торгівлі й мандрівників, стримуючи диких звірів.",al={"призначення застави північної брами","чому тут застава північної брами"}},{q="Куди веде дорога через перевал?",a="Якщо йти на схід гірськими тунелями за заставою, потрапите в помірну долину Лох Модану, а на захід дорога веде назад до Хараноса й Айронфорджа.",al={"куди веде перевал північної брами","дорога повз заставу північної брами"}},{q="Чому горянам потрібна допомога мандрівників?",a="Звірі на засніжених скелях люто бережуть свої володіння. Кілька горян, полюючи на небезпечних звірів, зникли серед круч, тож гарнізон кличе вправних розвідників з'ясувати, що з ними сталося.",al={"завдання застави північної брами","зниклі горяни"}}},fp="18,261,18.469.0,36.233.0,42.175.0,49.223.0"}
P.entries["subzone:north-gate-pass"] = {n="Перевал Північної Брами",s="Перевал Північної Брами — важливий гірський шлях, що з'єднує засніжені скелі Дун Мороґу з пологою улоговиною Лох Модану. Це північний коридор крізь вершини Каз Модану під наглядом укріпленої дворфійської застави. Мандрівники, що прямують до північних низин Багнокраю, часто йдуть цим високим шляхом.",h="Перевал Північної Брами — важливий гірський шлях, що з'єднує засніжені скелі Дун Мороґу з пологою улоговиною...",kw={"перевал північної брами","застава північної брами","дун мороґ","лох модан","багнокрай","горяни"},ang={["faction:Alliance"]="Перевал — важливий військовий і постачальний коридор, що з'єднує дворфійську столицю з північними експедиціями Альянсу до Багнокраю.",["race:Dwarf"]="Для дворфів, що мандрують між високими брамами Айронфорджа й прикордонними поселеннями довкола Озера, перевал — знайомий, вирубаний у камені поріг під охороною побратимів-горян."},sec={{t="Брама між вершинами",b="Перевал Північної Брами, вирубаний у прямовисних скелях Каз Модану, — північна артерія, що з'єднує високі замерзлі долини Дун Мороґу з помірними водами Лох Модану. Спустившись крутими гірськими тунелями, мандрівники, що виходять із заходу, бачать широкий простір долини з озером. Оскільки перевал лежить недалеко від шляхів, що спускаються в Багнокрай, ним постійно ходять дворфійські гінці, купці й мандрівні шукачі пригод. Його стратегічне значення тримає Застава Північної Брами, де горяни пильно вартують від трогів і гірських хижаків."}},faq={{q="Куди веде Перевал Північної Брами?",a="Перевал сполучає схід Дун Мороґу з північним заходом Лох Модану. Якщо йти дорогою далі на північ довкола озера, потрапите до гірських тунелів, що спускаються в Багнокрай, тож це важливе перехрестя для мандрівників на півночі.",al={"куди веде перевал північної брами","кінець перевалу північної брами","шлях крізь перевал північної брами"}},{q="Хто охороняє перевал?",a="Горяни Айронфорджа тримають Заставу Північної Брами просто біля дороги: вони стежать за мандрівниками й очищають гірський шлях від хижих звірів і блукаючих трогів.",al={"хто охороняє перевал північної брами","варта перевалу північної брами","дворфійська застава північної брами"}},{q="Чим він відрізняється від Проходу Південної Брами?",a="Обидва переходи сполучають Дун Мороґ із Лох Моданом прорубаними тунелями, але Перевал Північної Брами лежить північніше й дає найпрямішу суходільну дорогу тим, хто прямує далі — до Багнокраю й північних земель.",al={"різниця між північною і південною брамою","північна брама проти південної"}}},fp="15,332,25.629.0,32.231.0,21.178.0,42.212.0"}
P.entries["subzone:north-tide-s-hollow"] = {n="Лощина Північного Припливу",s="Лощина Північного Припливу — дикий куточок Срібнолісся трохи на північ від Гробниці. Тут никають дикі воргени-Мунрейджі, вірні архімагові-ренегату Аруґалу, і галявина править за базу для звірів, що полюють у прибережних лісах.",h="Лощина Північного Припливу — дикий куточок Срібнолісся трохи на північ від Гробниці.",kw={"лощина північного припливу","воргени","мунрейджі","аруґал","гробниця","срібнолісся"},ang={["race:Undead"]="Зграя Мунрейджів у Лощині Північного Припливу, що засіла незатишно близько від Гробниці, — безпосередня загроза владі Відступників і їхнім шляхам постачання в Срібноліссі."},sec={{t="Дикий плацдарм",b="Лощина Північного Припливу, захована в густому лісі на північ від поселення Відступників — Гробниці, — під владою лютої зграї Мунрейджів. Ці дикі воргени, що потрапили до Лордерона через безрозсудне чаклунство Архімага Аруґала, облаштували грубі табори по всій лощині. Збудовані лише з найпотрібнішого для витривалих звірів, ці грубі прихистки правлять за передовий плацдарм небезпечно близько до шляхів, якими ходять Відступники."},{t="У тіні Шадовфенга",b="На відміну від звичайних хижаків, воргени Лощини Північного Припливу коряться зловісній волі, що лине з Фортеці Шадовфенг. Близькість і до західного узбережжя, і до головної дороги через Срібнолісся робить їх постійною загрозою для гінців і патрулів Відступників, що намагаються убезпечити край."}},faq={{q="Де розташована Лощина Північного Припливу?",a="Лощина Північного Припливу — на заході Срібнолісся, трохи на північ від застави Відступників під назвою Гробниця, біля прибережних круч.",al={"розташування лощини північного припливу","де лощина північного припливу","розташування лощини"}},{q="Хто живе в Лощині Північного Припливу?",a="Лощину заполонили воргени Мунрейджа — надприродні вовкулаки, скуті божевіллям архімага Аруґала.",al={"хто живе в лощині північного припливу","вороги лощини північного припливу","моби лощини північного припливу"}},{q="Чому воргени живуть тут у грубих таборах?",a="Воргени люті й дикі, проте зграя Мунрейджа зберегла досить хитрості, щоб облаштувати прості табори. Від природи витривалі й загартовані, вони обходяться найпримітивнішими прихистками й найнеобхіднішим, щоб вижити в нетрях Лордерона.",al={"табори воргенів","чому в воргенів намети"}},{q="Хто керує воргенами в цьому краї?",a="Воргени Мунрейджа в Лощині Північного Припливу служать Архімагові Аруґалу, який викликав воргенів у Лордерон і командує ними з Фортеці Шадовфенг.",al={"хто керує воргенами","майстер воргенів"}}},fp="19,263,16.462.0,25.309.0,29.160.0,43.110.0,43.253.0,37.140.0"}
P.entries["subzone:north-tide-s-run"] = {n="Потік Північного Припливу",s="Потік Північного Припливу — продуване вітрами північно-західне узбережжя Срібнолісся, що тягнеться краєм Великого Моря. Позначений самотнім багаттям і напівзатонулим кораблем, цей відтинок піску відомий як відлюдне місце випробувань для мандрівних друїдів, що шукають гармонії з водами.",h="Потік Північного Припливу — продуване вітрами північно-західне узбережжя Срібнолісся, що тягнеться краєм...",kw={"потік північного припливу","воллас сліпий","друїди","морський лев","узбережжя","срібнолісся"},ang={["class:Druid"]="Для тауренів-друїдів це холодне узбережжя — важливий обряд посвяти: тут лежать під водою реліквії випробування, потрібні, щоб опанувати подобу морського лева.",["race:Tauren"]="Далеко від теплих рівнин Малгору Потік Північного Припливу — одне з небагатьох місць Лордерона, куди молоді таурени вирушають на початку свого духовного шляху."},sec={{t="Самотня прибережна застава",b="Потік Північного Припливу, що тягнеться північно-західним краєм Срібнолісся, — це холодний пісок, гуркітливий прибій і смуга Великого Моря. Його найпомітніша прикмета — напівзатонулий корабель, небезпечно похилений на мілині біля пляжу. Окрім уламків, єдина ознака людського життя тут — скромне багаття, яке доглядає Воллас Сліпий, що несе тиху варту біля хвиль, які плещуть об берег."},{t="Води Морського Лева",b="Попри похмурий дух, Потік Північного Припливу має священне значення для учнів Орди, що йдуть шляхом Кенарія. Молодих тауренів-друїдів посилають сюди в паломництво, щоб дістати з-під води реліквії, поглинуті хвилями, — так вони випробовують свою витримку без повітря й витривалість, щоб здобути благословення водяної форми."}},faq={{q="Що таке Потік Північного Припливу?",a="Це північно-західне узбережжя й прибережна смуга Срібнолісся на межі з Великим Морем. Тут — затонулий корабель, припливні води й похмурий, тихий берег.",al={"потік північного припливу","де потік північного припливу","що це за пляж"}},{q="Хто такий Воллас Сліпий?",a="Воллас Сліпий — самітник, що розбив невеликий табір і розклав вогнище біля самої води на пляжі й тихо сидить неподалік від затонулого судна.",al={"воллас сліпий","воллас сліпий сілверпайн","хто хлопець біля багаття"}},{q="Навіщо друїди приходять до Потоку Північного Припливу?",a="Тауренські друїди приходять сюди на прощу під час випробувань, щоб поспілкуватися з духами моря. Пірнаючи в глибини біля берега по загублені частини амулета, вони здобувають силу перетворюватися на водяну подобу.",al={"завдання друїдів сілверпайн","водяна форма сілверпайн","чому тут таурени"}},{q="Що за затонулий корабель у воді?",a="Уламки — це напівзатоплене судно, що лежить на мілині неподалік від берега. Воно слугує прикметою для мандрівників, що обшукують узбережжя.",al={"уламки корабля північного припливу","затонулий човен сілверпайн","розбитий корабель"}}},fp="16,282,24.412.0,22.304.0,25.178.0,25.150.0,39.219.0,37.164.0"}
P.entries["subzone:northdale"] = {n="Нортдейл",s="Нортдейл — зруйноване поселення на північ від Каплиці Надії Світла у Східних Чумних Землях, біля кордону з Кель'Таласом. Колись тут вирувало життя північного містечка, а тепер воно лежить у руїнах і кишить баньші, тіньовими спостерігачами та оскверненими елементалями. Найбільше Нортдейл відомий як гірке роздоріжжя, де Тейлан Фордрінг зрікся Ордену Срібної Длані й прийняв фанатизм Багряного Хрестового Походу.",h="Нортдейл — зруйноване поселення на північ від Каплиці Надії Світла у Східних Чумних Землях, біля кордону з...",kw={"нортдейл","тейлан фордрінг","срібна длань","багряний хрестовий похід","баньші","руїни"},ang={["class:Paladin"]="Для лицарів Світла Нортдейл — тверезий пам'ятник утраченій вірі, та сама земля, де Тейлан Фордрінг покинув Срібну Длань, щоб гнатися за помстою.",["race:Human"]="Обгорілі фундаменти й неприкаяні баньші Нортдейлу — ще одна втрачена громада Лордерона, вирізана й загарбана Погибеллю."},sec={{t="Містечко скорботи",b="Нортдейл, що лежить на пагорбах на північ від Каплиці Надії Світла, колись був мирною громадою при північному тракті до Кель'Таласу. Третя війна залишила його в руїнах: вогнища захололи, а мешканців убили або вигнали. Нині крізь кладку, що розсипається, пропливають баньші, які голосять, а в темряві чатують невидимі Безокі Спостерігачі, наглядаючи за проклятими дорогами. Навіть сусіднє озеро не встояло перед чумою: у його водах вирують спотворені, осквернені водяні елементалі."},{t="Зречена присяга",b="Нортдейл має похмуре значення в трагічній історії роду Фордрінгів. Після падіння Лордерона й розпаду Лицарів Срібної Длані молодий Тейлан Фордрінг став посеред цих зруйнованих вулиць і урочисто відкинув батькові настанови. Вважаючи рештки Срібної Длані надто слабкими, щоб вичистити нежить, він зрікся свого священного обов'язку й приєднався до радикальних лав Багряного Хрестового Походу. Це доленосне рішення визначило владу Походу над Гартгленом."}},faq={{q="Що сталося з Нортдейлом?",a="Нортдейл знищено під час Третьої війни, коли Погибель прокотилася Лордероном. Будівлі зрівняли з землею, люди загинули від чуми, і лишився кам'яний кістяк, де нині блукають мстиві духи й зіпсовані елементалі.",al={"чому нортдейл зруйнований","історія нортдейла","що таке нортдейл"}},{q="Яка важлива подія тут сталася?",a="Саме тут Телан Фордрінг зрікся Ордену Срібної Длані. У розпачі через падіння Лордерона він відкинув тут паладинські обітниці й присягнув Багряному Хрестовому Походу, що тоді тільки зароджувався.",al={"тейлан фордринг нортдейл","що сталося з тейланом","орден срібної руки нортдейл"}},{q="Хто блукає руїнами сьогодні?",a="У руїнах містечка кишать завивальні баньші й невидимі Безокі Спостерігачі на службі Погибелі. Сусідні води теж зіпсовані й аж кишать зіпсованими водяними елементалями.",al={"моби нортдейла","вороги нортдейла","що в нортдейлі"}},{q="Де розташований Нортдейл?",a="Нортдейл — на північному сході Східних Чумних земель, трохи на північ від Каплиці Надії Світла й на південний схід від Талассійського перевалу до Кель'Таласу.",al={"розташування нортдейла","де нортдейл","знайти нортдейл"}}},fp="9,406,16.499.0,17.503.1,27.235.0,39.205.0,37.178.0,27.159.0"}
P.entries["subzone:northfold-manor"] = {n="Маєток Нортфолд",s="Маєток Нортфолд — занедбане господарство на північно-західних окраїнах Аратійського нагір'я. До занепаду Стромґарда це була заможна людська садиба, а тепер тут засіли злочинці Синдикату, що вдаються до тривожних темних практик.",h="Маєток Нортфолд — занедбане господарство на північно-західних окраїнах Аратійського нагір'я.",kw={"маєток нортфолд","синдикат","кровокамінь","демони","мур торадіна","аратійське нагір'я"},ang={["class:Shaman"]="Демонічний осад над Маєтком Нортфолд розладнує природні стихії, тож чутливі шамани, що наближаються, відчувають духовний неспокій і вогняну лють.",["faction:Horde"]="Шамани Гаммерфолла пильно стежать за Маєтком Нортфолд і посилають воїнів відібрати амулети з кровокаменю, за допомогою яких Синдикат бавиться демонічними викликаннями."},sec={{t="Розбійницьке лігво",b="Маєток Нортфолд, що стоїть на горбистому нагір'ї біля проходу в Мурі Торадіна, колись годував королівство Стромґард. У хаосі, що настав після розпаду держави, панський дім, клуню й поля захопили вигнана альтерацька знать і розбійники Синдикату, зробивши їх своєю базою. Замість того щоб доглядати посіви, найманці, розбійники з великої дороги й слідопити Синдикату влаштовують звідси засідки на дорогах і керують своїми загонами по всьому нагір'ю."},{t="Демонічний присмак",b="За буденним злодійством і показною збройною бравадою в Маєтку Нортфолд криються лиховісніші задуми. Над хутором досі висять сліди демонічних викликань, які гостро відчувають чутливі заклиначі й шамани краю. Земля всіяна викинутими амулетами з кровокаменю — потужними оберегами, що живлять темні закляття, — а отже, розбійники Синдикату заплуталися в демонічній магії, яка виходить далеко за межі звичайного розбою."}},faq={{q="Хто тримає Маєток Нортфолд?",a="Маєток потрапив до рук Синдикату — угруповання позбавлених маєтностей альтеракських вельмож, розбійників і найманців-відступників, які тепер тримають тут озброєний табір.",al={"хто тут живе","хто володіє нортфолдом","ферма синдикату"}},{q="Яку темну магію тут творять?",a="Відвідувачі, чутливі до магії, відчувають залишкові сліди демонічного виклику. Сили Синдикату в маєтку мають амулети з кровокаменю, якими спрямовують силу й допомагають у небезпечних демонічних обрядах.",al={"демони нортфолда","кривавий камінь","що вони закликають"}},{q="Чому Орду цікавить ця ферма?",a="Троль-шаман Тор'ґан у Гаммерфоллі відчув неприродний неспокій, що назрівав на нагір'ї. Шукаючи його джерело, він вийшов просто на Маєток Нортфолд, і Орда взялася розслідувати окультні справи Синдикату.",al={"інтерес орди до нортфолда","чому тор'ґан піклується"}},{q="Хто такий Співець?",a="Співець — невловима постать із Синдикату, яку часом помічають у головному будинку Маєтку Нортфолд серед інших розбійників.",al={"співець","рідкісний співець","хто такий співець"}}},fp="15,292,17.469.0,18.439.1,29.183.0,40.212.0,40.232.0,14.133.0"}
P.entries["subzone:northpass-tower"] = {n="Вежа Північного Перевалу",s="Вежа Північного Перевалу — зруйнована дозорна вежа Лордерона на півночі Східних Чумних Земель, на шляху до Кель'Таласу. Її розтрощили в Третю війну, але завдяки вигідному розташуванню вона стала ключовою стратегічною здобиччю в дедалі запеклішому протистоянні Альянсу й Орди.",h="Вежа Північного Перевалу — зруйнована дозорна вежа Лордерона на півночі Східних Чумних Земель, на шляху до...",kw={"вежа північного перевалу","дозорна вежа","кель'талас","альянс","орда","східні чумні землі"},ang={["faction:Alliance"]="Відвоювати Вежу Північного Перевалу — важливий крок до відновлення полеглих оплотів Лордерона й до того, щоб не дати Орді плацдарму на півночі.",["faction:Horde"]="Утримати ці стратегічні руїни означає захистити пересування на півночі й зміцнити наступ Орди і проти Погибелі, і проти зайд з Альянсу."},sec={{t="Північний вартовий",b="Королівство Лордерон звело Вежу Північного Перевалу, щоб стерегти важливий шлях на північ, до Кель'Таласу, але під час навали Погибелі від неї лишилася тільки зруйнована шкаралупа. Попри потрощену кладку, висока позиція вежі й досі має величезну тактичну цінність: звідси видно зачумлене прикордоння між спустошеними околицями Стратгольма й далекими ельфійськими землями."},{t="Спірна передова",b="Поки Срібний Світанок тримається в Каплиці Надії Світла, і Альянс, і Орда прагнуть облаштувати по всіх Чумних Землях застави, які можна втримати. Вежа Північного Перевалу стала частим осередком сутичок: хто втримає її руїни, той зміцнить свої шляхи постачання в краї й матиме передовий плацдарм проти ворожої фракції та дедалі ближчих патрулів Погибелі."}},faq={{q="Для чого спершу збудували Вежу Північного Перевалу?",a="Королівство Лордерон звело її як спостережний пост, щоб стежити за північною дорогою до ельфійського королівства Кель'Талас.",al={"що таке вежа північного перевалу","історія північного перевалу","чому збудували вежу північного перевалу"}},{q="Чому Вежа Північного Перевалу в руїнах?",a="Її знищили разом з рештою північних укріплень Лордерона під час навали Погибелі в Третій війні, і лишилися тільки потріскана кладка й риштовання.",al={"хто зруйнував вежу північного перевалу","чому вежа північного перевалу зламана"}},{q="Чому Альянс і Орда воюють за цю вежу?",a="Обидві фракції пробиваються в Чумні Землі, щоб протистояти Погибелі — і одна одній. Хто тримає Вежу Північного Перевалу, той має укріплений розвідувальний пост і важливий вплив уздовж північних доріг.",al={"чому воюють за північний перевал","хто контролює вежу північного перевалу"}},{q="Куди веде дорога повз Вежу Північного Перевалу?",a="Дорога веде просто на північ — до талассійського кордону й південних земель Кель'Таласу.",al={"дорога повз вежу північного перевалу","куди веде північна дорога"}}},fp="15,289,17.375.0,20.351.0,46.154.0,32.167.0,52.199.0,46.101.0"}
P.entries["subzone:northridge-lumber-camp"] = {n="Лісозаготівельний Табір Нортріджа",s="Лісозаготівельний Табір Нортріджа — діюча лісопилка серед північних пагорбів Західних Чумних Земель, неподалік від Гартглена. Нині її тримає й укріплює Багряний Хрестовий Похід: звідси надходить деревина, без якої не встояли б сусідні твердині. І Альянс, і Орда бачать у лісопилці першу ціль, щоб підірвати господарство фанатиків у цьому краї.",h="Лісозаготівельний Табір Нортріджа — діюча лісопилка серед північних пагорбів Західних Чумних Земель...",kw={"лісозаготівельний табір нортріджа","лісопилка","гартглен","багряний хрестовий похід","терміти","західні чумні землі"},ang={["faction:Alliance"]="Хоч Багряний Хрестовий Похід і заявляє, що бореться з нежиттю, через жорстоку ненависть до чужинців хрестоносці загрожують розвідці й діям Альянсу на півночі Лордерону.",["faction:Horde"]="Для Відступників та їхніх союзників з Орди кожен зірваний лісоповал хрестоносців послаблює Гартглен і відтісняє фанатиків ближче до їхніх твердинь."},sec={{t="Деревина для Хрестового Походу",b="Лісозаготівельний Табір Нортріджа стоїть неподалік від Гартглена, при тій самій дорозі, і для Багряного Хрестового Походу це важливий вузол постачання. Хоча довколишні ліси досі задихаються від чуми, у таборі валять і обробляють місцеву деревину — на укріплення, на лагодження сторожових веж і на всі воєнні потреби Хрестового Походу в Лордероні. Лісопилку щільно обсадили фанатичні робітники й вартові, і вони люто боронять її і від Погибелі, і від сторонніх зайд."},{t="Ціль для диверсії",b="Оборона Гартглена тримається здебільшого на цій деревині, тож сторонні сили раз у раз змовляються, як би зірвати її постачання. І командири Альянсу, і розвідники Орди розуміють, що відкритий штурм укріплених позицій хрестоносців коштуватиме надто дорого. Тож агенти вдаються до незвичних диверсій — скажімо, випускають на склади лісопилки ненажерливих термітів-деревоточців, щоб ті тихо згноїли запаси Хрестового Походу зсередини."}},faq={{q="Хто тримає Лісозаготівельний Табір Нортріджа?",a="Нині табором володіє й керує Багряний Хрестовий Похід: його вартові й робітники заготовляють деревину для сусіднього Гартглена.",al={"хто керує нортріджем","хто контролює лісопилку","фракція нортріджа"}},{q="Чому ця лісопилка важлива?",a="Вона постачає деревину й будівельні матеріали, без яких Багряний Хрестовий Похід не втримав би своїх укріплень і застав по всій півночі Західних Чумних Земель.",al={"чому нортрідж важливий","значення нортріджа","навіщо цей табір"}},{q="Чому Альянс і Орда хочуть зірвати її роботу?",a="Обидві фракції вважають агресивний і фанатичний Багряний Хрестовий Похід небезпечною загрозою в Чумних Землях. Позбавивши хрестоносців деревини, можна послабити укріплення Гартглена без дорогого прямого наступу.",al={"чому нападати на нортрідж","завдання з термітами","чому зіпсувати ліс"}},{q="Хто тримав лісопилку до Третьої війни?",a="До того як королівство Лордерон упало під ударами Погибелі, тут жили й працювали місцеві родини, як-от Дюма й Левайни: лісопилка була тихим місцевим промислом.",al={"хто володів нортріджем","історія лісопилки нортріджа"}}},fp="22,356,19.470.0,19.440.0,36.139.0,34.158.0,50.218.0,38.165.0"}
P.entries["subzone:northshire-abbey"] = {n="Абатство Нортшира",s="Абатство Нортшира — історичний монастир у Долині Нортширу серед північних передгір'їв Лісу Елвінн. Відбудоване після знищення в Першій війні, воно є духовним серцем Братства Нортшира й головним осередком підготовки нових захисників, що відгукнулися на поклик королівства Стормвінд.",h="Абатство Нортшира — історичний монастир у Долині Нортширу серед північних передгір'їв Лісу Елвінн.",kw={"абатство нортшира","монастир","стартова локація","люди","братство нортшира","клірики","ліс елвінн"},ang={["class:Paladin"]="Нортшир утілює спадок Архієпископа Алонсуса Фаола й перших кліриків, чиї жертви заклали підвалини Лицарів Срібної Длані.",["race:Human"]="Для людей Стормвінда Абатство Нортшира — колиска вашого шляху, де історія стійкості й відданості королівства вітає кожного новобранця, що береться за зброю."},sec={{t="Спадок віри й руїни",b="Століття тому клірики з Лордерону вирушили на південь, у королівство Стормвінд, щоб ширити поклоніння Святому Світлу, і заснували Святий Орден Нортширських Кліриків та їхнє абатство. Монастир швидко став опорою життя королівства: він дбав про хворих і навіть доглядав юного Вартового Медіва в роки його коми. Під час Першої війни абатство зазнало повторюваних нападів розбійників і Орди орків, що завершилися його цілковитим знищенням. Коли Альянс Лордерону звільнив цей край у Другій війні, Архієпископ Алонсус Фаол допоміг відбудувати святиню й наново заснував її захисників як Братство Нортшира."},{t="Тренувальний майданчик",b="Нині Абатство Нортшира — місце, звідки починають добровольці, ополченці та новачки, що прагнуть боронити обложений Стормвінд. Поділене на Головну Залу, Залу Зброї та Бібліотечне Крило, воно вміщує наставників військових, таємних і святих мистецтв, а розвідники й розбійники тренуються на зовнішніх подвір'ях. Попри пильну присутність Лицарів Срібної Длані, мир тут лишається хитким. Кобольди заполонили сусідні копальні, войовничі вовки блукають садами, а агенти Братства Дефіас скрадаються дорогами долини, крадучи давні сувої та священні лібрами зі славетних архівів абатства."}},faq={{q="Що таке Братство Нортшира?",a="Братство Нортшира — релігійний орден кліриків, жерців і паладинів з осідком в Абатстві Нортшира. Спершу його століття тому заснували клірики-місіонери з Лордерону, а після Першої війни Архієпископ Алонсус Фаол заснував його наново, щоб готувати вірних захисників і зберігати священне писання.",al={"хто керує абатством нортшира","нортширські клірики","лор братства нортшира"}},{q="Чому Абатство Нортшира зруйнували в Першій війні?",a="Під час Першої війни абатство мало для Стормвінда стратегічне й духовне значення. Орки підбурили людських розбійників напасти на нього, а після того, як напіворчиху Ґарону ненадовго тримали тут у полоні, потужний натиск Орди зрівняв святу землю з землею. Абатство лишалося в руїнах до кінця війни, доки Альянс не вигнав орківські клани й не відбудував його.",al={"хто зруйнував абатство нортшира","нортшир перша війна","що сталося з нортширом"}},{q="Чому біля абатства розбійники Дефіас і кобольди?",a="Військо Стормвінда розтягнуте до краю, захищаючи далекі кордони, тож околиці охороняються погано. Спритні кобольди заполонили місцеві золоті копальні, а Братство Дефіас користається прогалинами, щоб грабувати мандрівників, дошкуляти тутешнім виноградникам і спустошувати бібліотеку абатства заради таємних фоліантів і святих реліквій.",al={"чому нортшир атакують","кобольди в нортширі","дефіас біля нортширу"}},{q="Що пов'язує Абатство Нортшира з Мертвими Копальнями?",a="Під час Першої війни вождь огрів на ім'я Турок викрав з Абатства Нортшира священний Фоліант Божественності й сховався в Мертвих Копальнях. Сер Андуїн Лотар очолив похід у глибини, щоб повернути святе писання, і потрапив у пастку, доки королівський рятувальний загін не визволив його й не повернув фоліант під опіку абатства.",al={"фоліант божественності нортшир","лор нортшир мертві копальні","андуїн лотар мертві копальні"}}},fp="16,322,26.656.0,20.618.0,38.314.0,52.351.0,59.321.0,66.320.0"}
P.entries["subzone:northshire-valley"] = {n="Долина Нортширу",s="Сховавшись у північних горах Лісу Елвінн, Долина Нортширу — мирна колиска й тренувальна база для наймолодших захисників королівства Стормвінд. Оточена природними перешкодами, вона дає прихисток старовинному Абатству Нортшира, родючим виноградникам і багатій Шахті Ехо-Рідж. Та попри спокійний вигляд, долині дедалі дошкуляють розбійники, кобольди й витіснені з лісів хижаки.",h="Сховавшись у північних горах Лісу Елвінн, Долина Нортширу — мирна колиска й тренувальна база для наймолодших...",kw={"нортшир","долина нортширу","абатство нортшира","виноградники нортшира","дефіас","кобольди"},ang={["faction:Alliance"]="Нортшир — важливий пункт набору й відновлення сил Великого Альянсу: тут готують нове покоління захисників, щоб утримати серце королівства.",["race:Human"]="Для людей Стормвінда Долина Нортширу — місце, де починається їхній шлях: тут вони ступають на землі абатства, відгукнувшись на поклик королівства в скрутну годину."},sec={{t="Відлюдний прихисток",b="Долину Нортширу обрамляють майже неприступні гірські хребти, і єдина дорога веде звідси на південь, крізь укріплену браму, до Ґолдшира та решти Лісу Елвінн. Пасовищами в'ється прозора річка, що далі на південь впадає в Кришталеве Озеро. У серці долини стоїть Абатство Нортшира — давнє святилище, де навчають Святого Світла, а рекрутів тренують Лицарі Срібної Длані та досвідчені ветерани. За мурами абатства лежать щедрі Виноградники Нортшира й Шахта Ехо-Рідж: разом вони утворюють самодостатній куточок земель Стормвінда, що здається далеким від воєн решти світу."},{t="Нові загрози",b="Навіть цей затишний прихисток відчув, як розтягнуто оборону Стормвінда. Маршал Макбрайд і його загін Варти Стормвінда ледве втримують лад у долині. Зграї вовків, витіснені на північ із ураженого Сутінколісся, нишпорять довколишніми лісами, а кобольди, наче шкідники, заполонили тунелі Шахти Ехо-Рідж. Ба гірше: замасковані головорізи з Братства Дефіас відкрито нападають на виноградники й загрожують землям абатства, тож місцеві командири змушені вербувати кожного здатного тримати зброю, хто дістається до їхніх воріт."}},faq={{q="Чому Долину Нортширу так пильно охороняють?",a="У долині стоїть Абатство Нортшира — важливий духовний осередок і тренувальний табір війська Стормвінда, а ще тут цінні місцеві ресурси, як-от Шахта Ехо-Рідж і виноградники. Військо Стормвінда розпорошене, тож Маршал Макбрайд тримає варту біля брами на південному перевалі, щоб загрози не перекидалися між долиною й рештою Лісу Елвінн.",al={"чому долину нортширу охороняють","брама нортширу","хто захищає нортшир"}},{q="Звідки в долині стільки вовків?",a="Помічник Віллем каже, що останнім часом зграї вовків масово перебираються через річку, тікаючи в долину з потемнілих лісів Сутінколісся на півдні. Темрява, що розповзається Сутінколіссям, жене диких звірів на зазвичай спокійні пасовища.",al={"чому стільки вовків","навала вовків","вовки із сутінколісся"}},{q="Чому кобольди нападають на Шахту Ехо-Рідж?",a="Кобольди — спритні копачі, яких вабить підземна руда. Коли королівських патрулів поменшало, клан кобольдів скористався відсутністю охорони й захопив Шахту Ехо-Рідж заради золота й свічок, вигнавши людей-рудокопів із тунелів.",al={"кобольди ехо-рідж","чому кобольди в нортширі","проблема з кобольдами"}},{q="Хто ці розбійники, що тривожать виноградники?",a="Злодії, що орудують біля виноградника Міллі Осворт, — агенти Братства Дефіас. Вони полюють на околицях долини, щоб зривати постачання, дошкуляти місцевим фермерам і перевіряти оборону абатства.",al={"бандити на виноградниках","дефіас у нортширі","червоні маски"}},{q="Що сталося з Нортширом під час Другої війни?",a="Під час Другої війни Абатство Нортшира потрапило до рук ворога й недовго слугувало штабом клану Молота Присмерку на чолі з Чо'ґаллом, доки Альянс не відвоював і не відновив долину.",al={"нортшир друга війна","молот присмерку нортшир","чо'ґалл нортшир"}},{q="Як вибратися з Долини Нортширу?",a="Єдиний прохідний пішки вихід — південна дорога крізь браму з вартою. Пройшовши нею, мандрівники потрапляють просто в центр Лісу Елвінн, на головну дорогу до Ґолдшира.",al={"вихід з нортширу","шлях до ґолдшира","як вибратися"}}},fp="17,423,20.635.0,20.549.0,44.358.0,49.250.0,42.256.0,44.204.0,50.196.0,35.215.0"}
P.entries["subzone:northshire-vineyards"] = {n="Виноградники Нортшира",s="Виноградники Нортшира — доглянуті виноградні поля просто на схід від Абатства Нортшира, у захищеній улоговині долини. Колись мирне джерело вина для кліриків, нині поля опинилися під владою Братства Дефіас та їхніх місцевих розбійників.",h="Виноградники Нортшира — доглянуті виноградні поля просто на схід від Абатства Нортшира, у захищеній улоговині...",kw={"виноградники нортшира","виноград","дефіас","розбійники","ґаррик педфут","міллі осворт","нортшир"},ang={["faction:Alliance"]="Заворушення на цих мирних виноградних полях показують, як глибоко беззаконня проникло навіть у найзахищеніші закутки королівства Стормвінд.",["race:Human"]="Для багатьох молодих людей, що вирушають у світ, захоплені виноградники — перша пряма зустріч із гіркотою та розмахом Братства Дефіас."},sec={{t="Пограбований урожай",b="Виноградники Нортшира на схід від Абатства Нортшира, за струмком, утілюють тихе хліборобське життя долини. Поля доглядають місцеві робітники, як-от Міллі Осворт, та через дедалі більші заворушення вони лишилися беззахисними. Розбійники, пов'язані з Братством Дефіас, яких на місці очолює горлоріз на ім'я Ґаррик Педфут, захопили угіддя. Злодії зайняли поля не заради простого вандалізму: вони грабують урожай і позбавляють місцевих хліборобів засобів до існування, даючи новобранцям Братства легку опору просто під носом в абатства."}},faq={{q="Хто зараз тримає Виноградники Нортшира?",a="Поля захопили злодії й головорізи з Братства Дефіас. Їхній місцевий ватажок — Ґаррик Педфут, розшукуваний розбійник, що керує розграбуванням урожаю й тероризує місцевих робітників.",al={"хто на виноградниках","хто захопив виноградники нортшира","хто такий ґаррік падфут"}},{q="Чому абатство дозволяє розбійникам хазяйнувати на полях?",a="Король Варіан Рінн зник, і військових сил Стормвінда катастрофічно бракує. Варта абатства відступила, щоб боронити саме абатство й пильнувати дороги долини, тож місцеві фермери змушені покладатися на новоприбулих шукачів пригод, щоб повернути вкрадене.",al={"чому немає варти стормвінда","чому абатство не обороняє виноградники"}},{q="Хто така Міллі Осворт?",a="Міллі Осворт — місцева фермерка, що працює на виноградниках. Коли розбійники Дефіас прийшли й захопили врожай винограду, її прогнали, і тепер вона шукає сміливців, які пішли б на поля й повернули її розграбовані ящики.",al={"міллі освотр","хто така міллі"}}},fp="20,269,19.577.0,48.206.0,59.276.0,21.227.0"}
P.entries["subzone:noxious-glade"] = {n="Отруйна Галявина",s="Отруйна Галявина — відлюдна улоговина серед пагорбів трохи на північ від Каплиці Надії Світла, просякнута густою чумою. Задушена отруйним зеленим повітрям і потемнілим ґрунтом, вона слугує Погибелі близьким прихистком просто під носом у Срібного Світанку.",h="Отруйна Галявина — відлюдна улоговина серед пагорбів трохи на північ від Каплиці Надії Світла, просякнута...",kw={"отруйна галявина","погибель","зикурат","чумний казан","каплиця надії світла","гидота"},ang={["class:Paladin"]="Галявина — тривожне нагадування про те, як близько зараза Погибелі підповзає до святого прихистку Каплиці Надії Світла. Тут вистачає і гидот нежиті, і некромантів, яких треба знищити.",["race:Undead"]="Поборники з-поміж Відступників упізнають тутешні бойні й чумні казани — звичні знаряддя Короля-Ліча, що наочно показують долю тих, хто не вирвався з-під його влади."},sec={{t="Мерзенний плацдарм",b="Поки Срібний Світанок несе варту в Каплиці Надії Світла, табір Погибелі причаївся просто над ним, на пагорбах на півночі. Отруйна Галявина заражена значно сильніше, ніж більшість довколишніх земель: у повітрі висить густий хворобливо-зелений туман, а ґрунт згнив до глибоких синюшно-фіолетових барв. В улоговині нежить звела зикурати, бойню, де збирають гидот, і чумний казан, що безупинно вивергає в повітря моровицю."},{t="Під поглядом Світанку",b="Галявина так близько від каплиці, що постійно загрожує мандрівникам, гінцям і святим воїнам, які діють з Каплиці Надії Світла. Сили Погибелі, що окопалися тут, складають мерзенних потвор і варять отрути, не потривожені сонячним світлом. Природний гребінь довкола ховає їх від чужих очей — аж доки необережний подорожній не підніметься стежкою просто в їхнє кубло."}},faq={{q="Де розташована Отруйна Галявина?",a="Отруйна Галявина сховалася серед пагорбів просто на північ від Каплиці Надії Світла, на сході Східних Чумних земель.",al={"де отруйна галявина","розташування отруйної галявини","як дістатися до отруйної галявини"}},{q="Чому тут повітря й земля іншого кольору?",a="Галявина отруєна навіть сильніше, ніж решта Чумних Земель. Діючий чумний казан і сусідні споруди Погибелі безперервно виливають в улоговину отрути, фарбуючи землю в темно-фіолетовий колір і вкриваючи галявину отруйною зеленою імлою.",al={"чому зелено","чому земля фіолетова","скверна отруйної галявини"}},{q="Які споруди Погибелі є на галявині?",a="На галявині — звичні споруди Погибелі: височенний чумний казан, кілька зикуратів і бойня, де збирають жахливі створіння на кшталт гидот.",al={"що всередині отруйної галявини","будівлі отруйної галявини"}},{q="Чи знає про це місце Срібний Світанок?",a="Так, але його сил постійно бракує на відбиття масових нападів Погибелі по всіх Чумних Землях, тож такі місця, як Отруйна Галявина, лишаються небезпечними гнійниками одразу за межами каплиці.",al={"чи знає надія світла","срібний світанок отруйна галявина"}}},fp="13,268,15.527.0,21.374.0,35.134.0,49.257.0,41.186.0,43.224.0"}
P.entries["subzone:noxious-lair"] = {n="Отруйне Лігво",s="Отруйне Лігво — запалий вулик силітидів у південно-західних пустелях Танарісу, на межі з Кратером Ун'Ґоро. Колись це була зелена улоговина з проточною водою, але рій Сентіпаар, що риє ходи, заполонив її й висмоктав усі життєво важливі ресурси. Тепер це їдке розплідне гніздо, повне комахоподібних роїв і багатих рудних жил.",h="Отруйне Лігво — запалий вулик силітидів у південно-західних пустелях Танарісу, на межі з Кратером Ун'Ґоро.",kw={"отруйне лігво","силітиди","сентіпаар","кратер ун'ґоро","руда","танаріс"},ang={["class:Druid"]="Вулик — тривожне збочення природи, що показує, як швидко загарбники-силітиди можуть перетворити колись повноводну улоговину на суху, їдку пустку.",["profession:Mining"]="Силітиди, прориваючи ходи в улоговині, оголили незвично різноманітні руди, тож гірники можуть добувати залізо, мітрил, справжнє срібло й торій на одній території."},sec={{t="Висушена улоговина",b="Отруйне Лігво лежить під західними гребенями, що здіймаються над Кратером Ун'Ґоро, і займає западину в пісках, де колись було озеро чи мілка річка. Коли сюди вдерлися силітиди Сентіпаар, вони поглинули рештки підземної вологи пустелі й перетворили улоговину на колонію, що дедалі розростається. Просто з піщаних дюн стирчать величезні клешні й кінцівки, що сіпаються, а довкола зяють підземні тунелі, слизькі від їдких виділень комах і вкриті кладками яєць, що визрівають."},{t="Рій Сентіпаар",b="Підземні тунелі з'єднують входи на поверхні з вологими, вкритими кислотою розплідними камерами під пісками. Робітники, копачі, оси й колосальні піщані жнеці Сентіпаар патрулюють околиці, захищаючи свій виводок від зовнішніх загроз. Окрім біологічних небезпек, розкопки силітидів вивернули на поверхню глибинні рудні поклади, і тепер тут незвично різноманітні угіддя для полювання й розвідки надр, де підземна руда лежить відкрито посеред кишучих вуликів."}},faq={{q="Хто живе в Отруйному Лігві?",a="У лігві живуть Сентіпаари — колонія комах-силітидів. Вулик боронять робітники, тунелерийники, летючі оси й хижі піщані розорювачі, а над усіма панують рідкісні жахи вулика, як-от Соріід Пожирач.",al={"які моби в отруйному лігві","комахи отруйного лігва","сентіпаар силітид"}},{q="Що було тут до приходу силітидів?",a="Улоговина підказує, що колись тут було річище чи мілке пустельне озеро. Силітиди, прийшовши, зарилися під землю, висмоктали із заходу Танарісу життєдайну воду й природні багатства й лишили по собі безплідну, просочену кислотою улоговину.",al={"історія отруйного лігва","чи було озеро","вода в отруйному лігві"}},{q="Чому гоблінів цікавить цей вулик?",a="Гобліни Ґаджетзана вважають вулик загрозою для пустельної торгівлі й посилають шукачів пригод розвідати лігво й з'ясувати, як шириться навала силітидів.",al={"гоблінські завдання отруйне лігво","стімвіддл отруйне лігво","тандердом силітиди"}},{q="Чи пов'язане Отруйне Лігво з іншими комашиними вуликами пустелі?",a="Отруйне Лігво — вулик Сентіпаарів, одна з кількох комашиних колоній, що розповзаються з південних пусток. Фізично він відокремлений від вуликів далі на півдні, проте його тунелі мають ту саму моторошну підземну будову й загрожують задушити все живе в Танарісі.",al={"інші вулики танарісу","зв'язок із вуликом сентіпаар","розширення силітидів"}}},fp="12,359,15.475.0,19.467.0,48.244.0,44.252.0,40.140.0,66.279.0"}
P.entries["subzone:old-ironforge"] = {n="Старий Айронфордж",s="Старий Айронфордж, який ще називають Зібранням Танів, — прадавня підземна зала просто під Високим Престолом Айронфорджа. Висічена глибоко в корінні гори над сяйливими жилами магми, вона — родове серце дворфійської столиці. Нині її важкі ворота в королівській тронній залі зачинені й пильно охороняються.",h="Старий Айронфордж, який ще називають Зібранням Танів, — прадавня підземна зала просто під Високим Престолом...",kw={"старий айронфордж","зібрання танів","айронфордж","тани","високий престол","лава"},ang={["class:Rogue"]="Майстер шпигунів Стормвінда Матіас Шоу суворо застерігає вас від спроб прокрастися до Старого Айронфорджа: охорона там пильна, а тим, кого схоплять вартові Короля Маґні, доведеться гірко поплатитися.",["race:Dwarf"]="Для дворфів Старий Айронфордж і Зібрання Танів — священний зв'язок із родовим корінням: тут збереглися найглибші кам'яні підвалини, висічені на світанку їхнього гірського королівства."},sec={{t="Зібрання Танів",b="Під троном Короля Маґні Бронзбірда на Високому Престолі лежить печерна зала, відома як Старий Айронфордж, або Зібрання Танів. Глибоко в цих вогняних підземних підвалинах звивисті кам'яні мости перекинуто над озерами лави. Задовго до того, як гамірні зали Великої Кузні й Торгових Рядів сповнилися відлунням сучасної дворфійської торгівлі, перші тани збиралися в цих печерних глибинах, щоб радитися й правити гірським королівством."},{t="Запечатана зала",b="Нині прохід до Старого Айронфорджа з тронної зали надійно замкнено. Королівська варта Айронфорджа суворо стереже пороги, що ведуть до старих склепінь. Навіть Майстер Матіас Шоу з SI:7 у Стормвінді відзначає посилену охорону довкола цих нижніх ярусів і застерігає: будь-яка спроба вдертися чи пхнути носа в охоронюване підземне місто загрожує суворим дворфійським правосуддям."}},faq={{q="Що таке Старий Айронфордж?",a="Старий Айронфордж, здавна відомий як Збори Танів, — давній нижній квартал, вирубаний просто під сучасним містом Айронфордж. Він складається з печерних зал і лавових каналів.",al={"збори танів","що таке старий айронфордж","підземний айронфордж"}},{q="Чи можуть гравці увійти до Старого Айронфорджа?",a="Ні. Головна брама в тронній залі Високого Престолу замкнена, а вхід пильно стереже королівська варта дворфів. Нижні зали лишаються закритими для звичайних городян і шукачів пригод.",al={"як зайти у старий айронфордж","чи відкритий старий айронфордж","замкнені двері старого айронфорджа"}},{q="Де розташований вхід?",a="Вхід — просто у Високому Престолі, королівській залі для аудієнцій, де сидить Король Маґні Бронзбірд у місті Айронфордж.",al={"де вхід у старий айронфордж","розташування старого айронфорджа"}},{q="Чому Старий Айронфордж важливий для історії дворфів?",a="Відомий як Збори Танів, він був давнім місцем зустрічей дворфійських ватажків і гірських королів у ранні часи, ще до того, як остаточно постали верхні кільця сучасної гірської столиці.",al={"історія старого айронфорджа","чому збори танів"}}},fp="13,365,22.435.0,16.387.0,22.194.0,32.198.0,30.141.0,52.202.0"}
P.entries["subzone:old-port-authority"] = {n="Стара Портова Управа",s="Стара Портова Управа — гамірний склад із безліччю торговців на дерев'яних помостах Буті Бею. Поки гоблінські будівельники латають його побитий негодою дах, мандрівники всередині роздивляються все підряд — від екзотичних вихованців і рушниць до ситних харчів і майстерно викуваних клинків.",h="Стара Портова Управа — гамірний склад із безліччю торговців на дерев'яних помостах Буті Бею.",kw={"стара портова управа","буті бей","ринок","торговці","гобліни","вогнепальна зброя"},ang={["class:Hunter"]="Завдяки торговцям «Гримучого імпорту: Схід» ця будівля — надійне місце, щоб поповнити запас куль і пороху, перш ніж вирушити в глибокі джунглі Стренглторну.",["profession:Cooking"]="Мандрівні кулінари можуть зазирнути до «Доброї їжі», щоб придбати місцеві кулінарні інгредієнти й припаси, які привозять торговельні судна."},sec={{t="Торгівля під дірявим дахом",b="Стара Портова Управа, що стоїть посеред піратського притулку Буті Бей, — це критий ринок, поділений на окремі ятки. Поки над головою гоблінські будівельники гупають молотками по даху, всередині вирує жвава торгівля. Купці наперебій пропонують шибайголовам і каперам усе, що потрібно в мандрах: звичайне спорядження, вогнепальну зброю, луки, харчі й клинки. Є тут і заморські дивовижі: барвисті птахи й морські дрібнички просто з причалів — для кожного, хто має монету."}},faq={{q="Що таке Стара Портова Управа?",a="Це помітний торговий склад у Буті Беї, поділений на кілька крамничок. Шукачі пригод і пірати приходять сюди по харчі, набої, зброю й усіляку дрібницю — під дахом, який гобліни майже безперестанку лагодять.",al={"що це за будівля","склад бутті бей","портова управа бутті бей"}},{q="Чому гобліни працюють на даху?",a="Вологе, солоне морське повітря Долини Стренглторну невпинно точить дерев'яні споруди Буті Бею. Гоблінських будівельників часто можна побачити, як вони стукають молотками по дерев'яних кроквах, щоб галасливий ринок мав дах над головою.",al={"чому будівельні роботи на даху","гобліни лагодять дах","робітники на даху"}},{q="Які крамниці є всередині?",a="На складі п'ять окремих крамничок: «Морські потреби», «Добра їжа», «Швидкі польоти», «Імпорт бахкалок — Схід» і «Порізи й Синці, Інк.» — тут є харчі, зброя, свійські пташки й звичайні припаси.",al={"торговці всередині","крамниці портової управи","що можна купити"}},{q="Чи можна тут купити улюбленця?",a="Так. У «Морських потребах» мандрівники можуть придбати екзотичних пташок-супутників, як-от корел і сенегальських папуг, — улюблених друзяк місцевих моряків і каперів.",al={"торговець улюбленцями бутті бей","папуги бутті бей","торговець морськими товарами"}}},fp="18,283,29.466.0,31.235.0,36.220.0,28.212.0,22.171.0"}
P.entries["subzone:old-town"] = {n="Старе Місто",s="Старе Місто — найдавніший і найсуворіший квартал Стормвінда, що здебільшого вцілів під час руйнувань Першої війни. Замість блискучих кам'яних площ тут вузькі провулки з вивітреною цеглою, робітничі житлові будинки й гамірні воєнні установи. Тут розташовані Командний центр королівського війська й таємний штаб SI:7.",h="Старе Місто — найдавніший і найсуворіший квартал Стормвінда, що здебільшого вцілів під час руйнувань Першої...",kw={"старе місто","si:7","командний центр","зала чемпіонів","стормвінд","свиня і свисток"},ang={["class:Rogue"]="Старе Місто — ваш природний прихисток у столиці: за звичайними провулками ховається штаб SI:7, де майстри-шпигуни й таємні куратори дають настанови.",["class:Warrior"]="Командний центр і Зала Чемпіонів роблять Старе Місто головним місцем збору в Стормвінді для загартованих у боях ветеранів, що шукають спорядження й бойової науки."},sec={{t="Пам'ятка старого королівства",b="Поки решту Стормвінда після Першої війни каменярі старанно відбудовували з нуля, Старе Місто уникло цілковитої руйнації. Йому не знадобилася повна перебудова, тож воно так і не отримало бездоганних мармурових фасадів і величних каналів, як Торговий Квартал чи Соборна Площа. Натомість це досі простий, тісний квартал, де живуть трудящі, робітники й найбідніші містяни. Його бруковані вулиці вужчі, брудніші й значно хаотичніші, ніж у решті столиці, але саме вони зберігають справжній дух довоєнного Стормвінда."},{t="Солдати, шпигуни й таверни",b="За вивітреними житловими будинками Старе Місто — бойовий хребет столиці Альянсу. У Командному центрі розміщені воєнні офіцери Стормвінда, казарми й бойові наставники, а поруч — Зала Чемпіонів, де збираються найкращі воїни Альянсу. Ближче до краю кварталу сховано таємний осідок SI:7 — потаємної розвідувальної служби королівства, яку очолює Майстер Матіас Шоу. Піхотинці у вільний від служби час і тіньові агенти разом збираються в таверні «Свиня і Свисток», товкучись пліч-о-пліч в одному з найжвавіших шинків міста."}},faq={{q="Чому Старе Місто виглядає набагато бруднішим за решту Стормвінда?",a="Старе Місто здебільшого вціліло, коли Орда в Першій війні сплюндрувала Стормвінд. Його не зрівняли з землею, тож Гільдія Каменярів не відбудовувала його з нуля — і воно не отримало ні нової бездоганної кладки, ні величної архітектури, якою прикрасили решту міста.",al={"чому старе місто занедбане","бідність старого міста","чому старе місто бридке"}},{q="Що таке SI:7 і де воно розташоване?",a="SI:7 — таємна розвідувальна служба Стормвінда й Альянсу під орудою Майстра Матіаса Шоу. Її прихований штаб — у глибині Старого Міста, за тренувальними дворами й військовими стайнями.",al={"де сі:7","що таке сі:7","шпигуни стормвінда"}},{q="Для чого потрібен Командний центр у Старому Місті?",a="Командний центр — головний гарнізон і штаб війська Стормвінда. Усередині й на його подвір'ї офіцери керують обороною міста, а воїни й мисливці навчаються поряд із доглядачами стаєнь і наставниками верхової їзди.",al={"призначення командного центру","казарми старого міста","військовий штаб стормвінда"}},{q="Де в Старому Місті таверна?",a="Місцева пивниця — Таверна «Свиня і Свисток» неподалік від центру кварталу. Вона славиться тим, що тут гуртуються голодні вояки, шукачі пригод і мандрівники, які шукають рецептів ситних страв.",al={"корчма старого міста","де свиня і свисток","таверна старого міста"}}},fp="8,373,26.585.0,28.556.0,66.262.0,37.217.0,48.237.0,32.200.0"}
P.entries["subzone:olsen-s-farthing"] = {n="Олсенів Наділ",s="Олсенів Наділ колись був квітучою садибою при головному торговому шляху через Срібнолісся. Після Третьої війни поля занепали, і їх заполонили підняті раби-мерці, підвладні некромантові-ренегату Тулу Рейвенклову.",h="Олсенів Наділ колись був квітучою садибою при головному торговому шляху через Срібнолісся.",kw={"олсенів наділ","тул рейвенклов","нежить","погибель","садиба","срібнолісся"},ang={["faction:Horde"]="Вигнати нападників з Олсенового Наділу вкрай важливо, щоб убезпечити шлях постачання, що з'єднує Гробницю з північчю, і дорогу до Галявин Тірісфалю.",["race:Undead"]="Для Відступників місця на кшталт Олсенового Наділу — похмуре нагадування про загрозу Погибелі, що прагне поневолювати мерців, а не звільняти їх."},sec={{t="Сплюндрована садиба",b="Доки чума не поглинула Лордерон, Олсенів Наділ був жвавою хліборобською садибою з прямим виходом на головний сухопутний торговий шлях Срібнолісся. Сьогодні його оброблені поля задушені бур'янами, будівлі лежать розбиті, а будь-яку пам'ять про чесну хліборобську працю стерла некромантія Погибелі. Раби-нежить, скуті як невільники й нападники під командуванням Тула Рейвенклова, блукають голою землею, вбиваючи кожного мандрівника, що підійде надто близько."},{t="Лабети Рейвенклова",b="Шкутильгаючі жахіття, що никають Олсеновим Наділом, — не бездумні мандрівники, а слуги Тула Рейвенклова, могутнього некроманта, що діє з Острова Фенріс посеред Озера Лордамер. Темним чаклунством піднімаючи й поневолюючи мерців довколишніх сіл, Тул простягає свою руку й на Олсенів Наділ і становить пряму загрозу для Відступників, що прагнуть убезпечити північ Срібнолісся."}},faq={{q="Чим був Олсенів Наділ до Третьої війни?",a="Це було прибуткове господарство при дорозі, що підтримувало місцеву торгівлю на головному торговому шляху Срібнолісся й годувало поселення Лордерона, доки королівство не впало під ударами Погибелі.",al={"історія олсенового наділу","що це було за місце","хто жив в олсеновому наділі"}},{q="Чому ферму заполонила нежить?",a="Ферму знищили під час Третьої війни, а її рештки захопив некромант Тул Рейвенклов: він підняв мерців як невільників і нападників, щоб тероризувати подорожніх на дорозі.",al={"чому тут нежить","хто керує нежиттю олсенового наділу","раби рейвенкловів"}},{q="Хто такий Тул Рейвенклов?",a="Тул Рейвенклов — небезпечний некромант на службі Погибелі, що зі своєї твердині на Острові Фенріс керує набігами нежиті по всьому Срібноліссю.",al={"хто такий тул рейвенклов","тул рейвенклов історія","хто командує рейвенклов"}},{q="Чи є тут Орда чи Відступники?",a="Ні. Ферму цілком заполонила ворожа нежить, вірна Тулу Рейвенклову, тож це ворожа земля і для розвідників-Відступників, і для мандрівників Орди.",al={"чи олсенів наділ орди","чи живуть тут відступники","чи є тут осередок завдань"}}},fp="16,270,20.455.0,22.434.1,47.192.0,37.190.0,23.163.0,50.150.0"}
P.entries["subzone:oneiros"] = {n="Онейрос",s="Онейрос — розлогі руїни прадавнього міста нічних ельфів на південь від Озера Джейдмір у північному Фераласі. Вони тісно пов'язані з порталами неподалік, що ведуть до царства Ізери, а їхні порослі мохом камені стережуть елітні зелені драконороди.",h="Онейрос — розлогі руїни прадавнього міста нічних ельфів на південь від Озера Джейдмір у північному Фераласі.",kw={"онейрос","руїни","зелені дракони","смарагдовий сон","ізера","фералас"},ang={["class:Druid"]="Друїди ставляться до Онейроса з глибокою шаною і тривогою: вони відчувають його незримий зв'язок із царством Ізери та невідступну загрозу скверни Жахіття.",["race:NightElf"]="Для нічних ельфів мандрівка Онейросом — урочисте нагадування про колишню міць їхньої прадавньої імперії та про невсипну варту зелених драконородів."},sec={{t="Руїни під покровом Сну",b="На густому лісовому долі північного Фераласу розкидані обвалені кам'яні арки й уламки колон Онейроса — сліди прадавнього поселення калдореїв, покинутого тисячоліття тому. Нині природа забрала ці споруди собі, оповивши їх велетенським корінням і буйною зеленню. Елітні вартові Зеленого драконячого роду невтомно патрулюють затінені стежки й зруйновані майдани, відганяючи смертних від прадавніх таємниць."},{t="Відлуння й скверна",b="Духовний зв'язок Онейроса зі Смарагдовим Сном робить цей край неспокійним. Драконороди, вірні Сновидиці, невсипно пильнують його межі, але за завісою вже ворушиться темрява. Смертні, що забредуть до Онейроса, мусять мати справу з могутніми драконородами, для яких кожен зайда — потенційна загроза тендітним оберегам, що стримують скверну."}},faq={{q="Де розташований Онейрос?",a="Онейрос лежить на півночі Фераласу, просто на південь від Озера Джейдмір і на північ від головних лісових шляхів. Він неподалік від Великого Дерева, біля якого відкривається портал до Смарагдового Сну.",al={"розташування онейроса","де онейрос","знайти онейрос"}},{q="Хто живе в Онейросі?",a="Руїни пильно патрулюють могутні зелені драконороди й драконячі створіння, що присягнули зеленому драконячому роду. Мандрівникам слід підходити обережно: ці вартові — грізні добірні охоронці.",al={"моби онейроса","вороги онейроса","хто живе в онейросі"}},{q="Звідки тут руїни нічних ельфів?",a="Онейрос — давнє поселення нічних ельфів, що існувало ще до Великого Розколу. Як і більша частина Фераласу, тутешня цивілізація розсипалася понад десять тисяч років тому, лишивши кам'яні колонади й двори, які забрала собі природа.",al={"чому тут руїни","руїни келдореїв фералас","історія онейроса"}},{q="Як Онейрос пов'язаний зі Смарагдовим Сном?",a="Він стоїть так близько до велетенських гілок, що з'єднують Калімдор зі світом Сну, що межа між матеріальним світом і світом духів тут розмивається.",al={"онейрос і смарагдовий сон","зв'язок зі сном фералас"}},{q="Чи є поблизу безпечне місце для відпочинку?",a="У самих руїнах — ні, вони належать зеленим драконячим створінням. Мандрівники з Альянсу можуть відступити до Твердині Перистого Місяця біля західного узбережжя, а Орда знаходить прихисток у Таборі Моджаче на сході Фераласу.",al={"безпечний табір біля онейроса","спочинок сновидців фералас","дружній осередок онейроса"}}},fp="7,245,23.440.0,21.360.1,25.194.0,31.199.0,35.230.0,61.151.0,37.210.0"}
P.entries["subzone:onyxia-s-lair"] = {n="Лігво Оніксії",s="Лігво Оніксії — підземна печера глибоко у Вірмовому Болоті Багна Пилоброду. Це гніздовище й твердиня Оніксії, матері виводку чорних драконів. У її задушливих, сповнених магми залах велика драконка стереже кладки яєць чорних драконів.",h="Лігво Оніксії — підземна печера глибоко у Вірмовому Болоті Багна Пилоброду.",kw={"лігво оніксії","оніксія","вірмове болото","багно пилоброду","чорні дракони","нефаріан","детвінг"},ang={["faction:Alliance"]="Для чемпіонів Альянсу ця печера — лігво матері чорних драконів, чий дедалі більший виводок загрожує Терамору й кожному поселенню довкола болота.",["faction:Horde"]="Багно Пилоброду межує з володіннями Орди в Пустках і Малгорі; дозволити матері чорних драконів вивести в Калімдорі ціле драконяче військо — смертельна загроза для всієї нової Орди."},sec={{t="Кубло магми й розрухи",b="Вхід до печери, видовбаний у підступній багнюці й скам'янілому дереві Вірмового Болота, нагадує роззявлену пащу дракона. Усередині прохолодна гниль болота поступається пекучому вулканічному жару. Магма сочиться з тріщин в обсидіановому камені, а підземні поштовхи раз у раз струшують склепіння. Центральна зала відкривається у величезний інкубатор, де серед попелу й жаринок лежать сотні яєць чорних драконів під наглядом драконячого кодла, вартових-драконородів і самої Оніксії."},{t="Сховок матері виводку",b="Поки брат Оніксії Нефаріан плете змови за морем, у Шпилі Блекрок, сама Оніксія давно тримає цей відлюдний прихисток у Калімдорі, щоб виводити нове покоління чорних драконів. Лігво стає їй сховком, коли її хитромудрі політичні інтриги розплутуються. Тут, далеко від дворів смертних королівств, вона може скинути людську личину й набути свого справжнього, жахливого вигляду доньки Детвінга."}},faq={{q="Де саме розташоване Лігво Оніксії?",a="Лігво лежить на півдні Багна Пилоброду, у Вірмовому Болоті, трохи на південь від Драконячої Мли. Вхід позначають величезні драконячі кістки, тліюча земля й вартові-чорні драконячі створіння, що стережуть кам'яну розколину, схожу на роззявлену пащу.",al={"де оніксія","розташування оніксії","як знайти лігво оніксії","печера драконячої мряки"}},{q="Хто живе в лігві?",a="Печеру населяють майже самі представники чорного драконячого роду. Праматір Оніксія панує в глибокій залі в оточенні роїв щойно вилуплених дракончиків, драконородів-вартових і дорослих чорних драконів.",al={"моби лігва оніксії","хто живе в лігві оніксії","що всередині"}},{q="Чому в печері так гаряче, якщо вона серед болота?",a="Оніксія вирила лігво глибоко в кору Калімдору й дісталася підземних жил магми. Нестерпний вулканічний жар дає пекучі умови, потрібні для висиджування яєць чорних драконів, — і різко контрастує з холодною багнюкою Багна Пилоброду вгорі.",al={"чому лава в пилотрясині","вулкан лігва оніксії"}},{q="Чому Оніксія ховається в Калімдорі?",a="Багно Пилоброду дає відлюддя й схованку. Густі тумани, похмурі трясовини й небезпечні звірі тримають смертні армії на відстані, тож праматір може спокійно поповнювати лави свого роду, потай плетучи інтриги далеко звідси.",al={"чому оніксія тут","чому пилотрясина","оніксія в калімдорі"}}},fp="13,299,23.478.0,25.400.1,31.246.0,37.218.0,45.255.0,37.253.0"}
P.entries["subzone:oracle-glade"] = {n="Галявина Оракула",s="Галявина Оракула в північно-західному Тельдрассилі — священне лісове святилище, домівка дивовижного Дерева Оракула й найголовнішого місячного колодязя Світового Дерева. Попри мирне призначення — бути осередком єднання й пильності — галявина потерпає від постійних наскоків гарпій Кривавого Пера.",h="Галявина Оракула в північно-західному Тельдрассилі — священне лісове святилище, домівка дивовижного Дерева...",kw={"галявина оракула","дерево оракула","місячний колодязь","гарпії","кривавого пера","тельдрассил","дарнасус"},ang={["class:Druid"]="Для друїдів дикої природи Дерево Оракула — живий партнер у служінні, що дає письмові звіти про здоров'я землі просто зі своєї кори.",["race:NightElf"]="Галявина Оракула втілює ніжну турботу, потрібну, щоб виплекати Тельдрассил: тут наймогутніший місячний колодязь крони й мовчазний спостерігач, що говорить напряму з проводирями Кола Кенарія."},sec={{t="Серце лісу",b="Галявина Оракула тихо лежить між Дарнасусом і Озером Джерела — важливий вузол єднання нічних ельфів із природою. У її центрі стоїть Дерево Оракула, прадавній велет, чиє могутнє гілля нагадує обриси орла, що сидить на ведмеді. Поруч мерехтить перший і наймогутніший зі священних місячних колодязів Тельдрассила — оаза місячної магії, омита ласкою Елуни. Разом із Колом Древніх Дерево Оракула наглядає за гіллям острова, скидаючи кору з написами, що правлять за важливі послання Архідруїду Фандралу Стаґгелму про здоров'я Світового Дерева."},{t="Гілля в облозі",b="Спокій галявини крихкий. Агресивні гарпії Кривавого Пера злетілися в гай, звили гнізда серед високих гілок і загрожують священному дереву. Вартові, послані з Дарнасуса, насилу викорінюють крилатих падложерів, що нападають на мандрівних друїдів і споганюють природну тишу місячного колодязя. Мандрівникам у північному гіллі слід ступати обережно: гарпії блискавично б'ють кожного, хто наблизиться до їхніх гнізд."}},faq={{q="Що таке Дерево Оракула?",a="Дерево Оракула — давнє дерево, виплекане магією, що має вигляд великого орла, який сидить на ведмедеві. Воно стежить за ростом і здоров'ям Тельдрассилу й скидає кору з вирізьбленими докладними звітами, які друїди відносять просто до Верховного друїда Фандрала Стаґгелма в Дарнасусі.",al={"хто дерево оракула","лор дерева оракула","розмовне дерево тельдрассил"}},{q="Чому гарпії нападають на Галявину Оракула?",a="Клан гарпій Кривавопірих звив гнізда у високих кронах галявини, бо його вабить її дика природа й чарівна сила. Вони люто боронять свої гнізда й дошкуляють Дереву Оракула, тож місцевим Вартовим доводиться їх стримувати.",al={"гарпії криваве пір'я","чому гарпії тут","вороги галявини оракула"}},{q="Яке значення має місячний колодязь на цій галявині?",a="Ставок на Галявині Оракула — найперший і наймогутніший місячний колодязь, закладений на Тельдрассилі. Він спрямовує священну силу Елуни, живлячи довколишній ліс і підтримуючи друїдів і жриць калдореїв, які приходять черпати з нього силу.",al={"місячний колодязь галявини оракула","перший місячний колодязь","перший колодязь тельдрассила"}},{q="Де розташована Галявина Оракула?",a="Вона на північному заході Тельдрассилу, трохи на захід від Озера Джерела. Південна дорога веде з галявини просто на головну стежку, що оперізує ворота Дарнасуса.",al={"розташування галявини оракула","де галявина оракула","як дістатися до галявини оракула"}}},fp="12,297,21.596.0,16.473.0,24.279.0,43.245.0,53.253.0,34.178.0"}
P.entries["subzone:orgrimmar"] = {n="Оргріммар",s="Оргріммар — грізна столиця воїнів Нової Орди, вирубана в звивистих червоних каньйонах північного Дуротару. Заснований Вождем Траллом і названий на честь Орґріма Думхаммера, він є серцем відродження орків і спільного виживання племен на Калімдорі.",h="Оргріммар — грізна столиця воїнів Нової Орди, вирубана в звивистих червоних каньйонах північного Дуротару.",kw={"оргріммар","столиця","орда","тралл","дуротар","орґрім думхаммер"},ang={["faction:Horde"]="Як найвище осердя влади Орди, Оргріммар — головний плацдарм для військових кампаній, союзів кланів і дипломатичних стосунків по всьому Калімдору й за його межами.",["race:Orc"]="Для орків Оргріммар — утілення їхньої спокути: тут вони скинули спадок демонічного прокляття, щоб будувати чесне, незалежне майбутнє."},sec={{t="Твердиня в камені",b="Після Третьої війни й перемоги на горі Гіджал Вождь Тралл привів свій уцілілий народ на південь, щоб заснувати постійну батьківщину в Дуротарі. Угніздившись у природній перепоні з прямовисних гірських круч, Оргріммар був збудований так, щоб витримати облогу: шпичасті дерев'яні частоколи, кам'яні сторожові вежі та глибокі печери, вирубані в горі. Зведена спільно з тролями Темного Списа, тауренськими каменярами й гоблінськими інженерами, твердиня перетворила безлюдну пустку на неприступний бастіон сили."},{t="Серце Нової Орди",b="Звільнені від демонічної жаги крові, що колись їх сковувала, орки збудували Оргріммар як маяк честі, спільноти й виживання. Нині, у 25 році після відкриття Темного Порталу, місто дає притулок не лише оркам і тролям Темного Списа, а й вітає посланців тауренів із Малгору та посланців нових союзників — Відступників. У його укріплених каньйонах шамани навчають нове покоління рівноваги предків, а ветерани б'ються на гладіаторських аренах, гартуючи військо, що береже крихкий мир Калімдору."}},faq={{q="На честь кого названо Оргріммар?",a="Вождь Тралл назвав місто на честь свого наставника й попередника — легендарного оркського Вождя Орґріма Думхаммера. Думхаммер загинув у Східних Королівствах під час визволення таборів для інтернованих орків і передав Траллу свої знамениті обладунки й бойовий молот.",al={"походження назви оргріммар","чому оргріммар","на честь кого оргріммар"}},{q="Хто допомагав будувати місто?",a="Столицю звели дуже швидко спільними зусиллями орків, тролів Темного Списа, тауренів, найманих гоблінів-саперів та інженерів і мандрівного героя Рекссара. Природні кам'яні стіни розкопали й укріпили, щоб швидко дати надійний прихисток серед суворої землі Дуротару.",al={"хто збудував оргріммар","як збудували оргріммар","будівельники оргріммара"}},{q="Які раси вважають Оргріммар своїм домом?",a="В Оргріммарі живуть переважно орки й тролі Темного Списа з племені Сен'джина, що ділять між собою квартали міста. Таурени, вірні союзники, часто живуть тут як гості, а посланці нещодавно прийнятих Відступників поволі закріплюються поряд із ними.",al={"хто живе в оргріммарі","мешканці оргріммара","раси оргріммара"}},{q="Де живе Вождь Тралл?",a="Тралл очолює Нову Орду з Фортеці Ґроммаш — головної твердині в Долині Мудрості в Оргріммарі, названої на честь його полеглого друга Ґрома Хеллскріма.",al={"де тралл","тралл в оргріммарі","трон вождя"}}},fp="9,274,25.514.0,22.488.0,29.268.0,26.292.0,32.271.0,34.176.0"}
P.entries["subzone:ortell-s-hideout"] = {n="Сховок Ортелла",s="Сховок Ортелла — скромна відлюдна печера під горами на південному сході Силітусу. Тут живе Відлюдник Ортелл, одна з небагатьох самотніх душ, достатньо загартованих — чи нерозважливих, — щоб мешкати самотою в цьому безплідному краї.",h="Сховок Ортелла — скромна відлюдна печера під горами на південному сході Силітусу.",kw={"сховок ортелла","відлюдник ортелл","печера","силітус","відлюдник"},sec={{t="Прихисток відлюдника",b="Сховок Ортелла, захований серед зубчастих урвищ південно-східного Силітусу, дає скупий прихисток від лютих піщаних бур і роїв силітидів, що панують у пустелі. Живе в печері лише Відлюдник Ортелл — дивакуватий самітник, який перебивається далеко від цивілізації та укріплених гарнізонів Цитаделі Кенаріуса. Мандрівники, що наважуються на небезпечну дорогу до цього віддаленого куточка, часто шукають його своєрідних знань про пустелю та її небезпеки."}},faq={{q="Де розташований Сховок Ортелла?",a="Сховок вирубано в гірській скелі на південно-східному краю Силітусу, далеко від центральних пустельних доріг, глибоко під прикордонними кручами.",al={"де ортелл","розташування ортелла","як знайти печеру ортелла"}},{q="Хто такий Відлюдник Ортелл?",a="Відлюдник Ортелл живе на самоті, осторонь від експедиції Кола Кенарія й усіх фракцій світу. Він свідомо оселився сам посеред небезпек Силітусу й тримається своєї маленької печери.",al={"хто такий ортелл","відлюдник ортелл історія"}},{q="Чи безпечний Сховок Ортелла від силітидів?",a="Сама печера не заражена, але вона стоїть відрізана посеред украй ворожого краю, де кишать комахи-силітиди й сектанти Молота Присмерку. Щоб дістатися сховку, доведеться пробиватися крізь небезпечні землі.",al={"чи є комахи в печері","чи безпечна печера ортелла"}}},fp="16,236,18.475.0,26.163.0,21.201.0,43.208.0"}
P.entries["subzone:owl-wing-thicket"] = {n="Гущавина Совиного Крила",s="Гущавина Совиного Крила — нагромадження печер і кам'яних сідал на півдні Вінтерспрінгу. Засніженими кручами тут нишпорять навіжені, місяцем торкнуті й божевільні совозвіри. Глибоко всередині давні вівтарі нічних ельфів зберігають священні знання про походження цих створінь та їхній зв'язок із богинею місяця Елуною.",h="Гущавина Совиного Крила — нагромадження печер і кам'яних сідал на півдні Вінтерспрінгу.",kw={"гущавина совиного крила","совозвіри","місячники","елуна","раншалла","вінтерспрінг"},ang={["class:Druid"]="Подобу місячника друїди вважають священною, тож ця гущавина — сумне видовище: тут створіння, наділені місячною силою, поринули в нестримне божевілля.",["race:NightElf"]="Для калдореїв Гущавина Совиного Крила — свята земля, що здичавіла: тут зберігаються давні перекази про ласку Елуни, а поруч живуть люті місячники, які втратили давню рівновагу."},sec={{t="Святилище місячників",b="Гущавина Совиного Крила, врізана в засніжене високогір'я на південь від Евірлука, — одне з найгустіших гніздовищ диких диких місячників Вінтерспрінгу. Колись давно нічні ельфи-доглядачі шанували цих створінь як священних захисників, благословенних Елуною. Під печерними навісами досі ховаються давні святилища й вівтарі з місячного каменю, над якими чатують духи Охоронців Елуни, що так і не покинули цих місць. Та нині багато звірів збожеволіли й накидаються на мандрівників, які порушують межі їхніх святих сховищ."},{t="Переказ про місячників",b="Учені й жерці нічних ельфів вирушають до Гущавини Совиного Крила, щоб поспілкуватися з Охоронцями Елуни. Під проводом жриці Раншалли шукачі з Альянсу запалюють священні жаровні по всіх печерах, щоб пробудити давніх духів. Ці охоронці переповідають легенду про те, як Елуна створила перших диких місячників, щоб вони оберігали недоторкані природні святилища, — і проливають світло на божественне походження звірів, попри їхню нинішню дику ворожість."}},faq={{q="Що таке Гущавина Совиного Крила?",a="Гущавина Совиного Крила — мережа засніжених круч і печер на півдні Вінтерспрінгу. Вона славиться численними дикими дикими місячниками й кількома давніми святинями ельфійської богині Елуни.",al={"гущавина совиного крила","де гущавина совиного крила","лор гущавини совиного крила"}},{q="Чому тутешні дикі місячники такі агресивні?",a="Спершу диких місячників створили як захисників природи, благословенних Елуною, але чимало з них у Вінтерспрінгу впали в шалену лють. У Гущавині Совиного Крила вони блукають збожеволілі, несамовиті й навіжені від місячного сяйва й нападають на кожного, хто підходить до їхніх лігв.",al={"чому місячники скажені","скажені дикі місячники вінтерспрінг","шалені дикі місячники"}},{q="Хто така Раншалла?",a="Раншалла — нічна ельфійка, жриця Елуни, що вирушає в Гущавину Совиного Крила. Вона шукає настанов давніх Вартових Елуни, щоб розкрити священне походження й історію місячників.",al={"раншалла","хто така раншалла","жриця раншалла"}},{q="Хто такі Вартові Елуни в гущавині?",a="Вартові Елуни — давні духи нічних ельфів, прив'язані до вівтарів у печерах. Коли їх кличуть, знову розпаливши священні вогні, вони розповідають, як місячників створили, щоб ті пильнували дикі й святі землі.",al={"вартові елуни","духи гущавини совиного крила","духи місячників"}}},fp="16,334,24.512.0,23.458.1,25.206.0,41.253.0,17.199.0,57.216.0"}
P.entries["subzone:palemane-rock"] = {n="Скеля Пейлмейн",s="Скеля Пейлмейн — печера й стійбище в західних горах Малгору. Це головна твердиня войовничого племені гнолів Пейлмейн, що постійно дошкуляє й загрожує сусіднім тауренам із Села Бладгуф.",h="Скеля Пейлмейн — печера й стійбище в західних горах Малгору.",kw={"скеля пейлмейн","гноли","печера","малгор","село бладгуф"},ang={["faction:Horde"]="Убезпечити кордони Малгору від таких місцевих шкідників, як гноли Пейлмейн, конче потрібно, щоб батьківщина тауренів лишалася безпечною й міцною.",["race:Tauren"]="Гноли Пейлмейн, що засіли в цих західних печерах, — постійна скалка в боці вашого народу: вони загрожують дичині й необачним мандрівникам на пасовищах Малгору."},sec={{t="Твердиня гнолів",b="Скеля Пейлмейн лежить на західному краю трав'янистих рівнин Малгору: розлоге стійбище просто неба перед глибокою тінистою печерою, вирубаною в гірському схилі. Гноли Пейлмейн оголосили своїми і нутро печери, і передгір'я одразу за нею. Ворожі й ревниві до своєї території, вони люто боронять лігво й нападають на мисливців, подорожніх і розвідників, що підходять до їхнього скелястого притулку занадто близько."}},faq={{q="Що таке Скеля Пейлмейн?",a="Скеля Пейлмейн — природна печера й укріплене поселення гнолів у західних скелях Малгору.",al={"інформація про скелю пейлмейн","печера пейлмейн","де скеля пейлмейн"}},{q="Хто живе на Скелі Пейлмейн?",a="Печеру й табір довкола тримають гноли з племені Пейлмейн. Вони люто боронять свої угіддя від чужинців, зокрема й від місцевих тауренів.",al={"хто тут","моби пейлмейн","гноли скелі пейлмейн"}},{q="Чому Скеля Пейлмейн важлива для тауренів?",a="Скеля Пейлмейн так близько до центру Малгору й Села Бладгуф, що це справжнє гніздо ворожих нападників, яких тауренським мисливцям і сміливцям доводиться раз у раз приборкувати.",al={"чому таврени дбають","гноли села криваве копито","загроза мулґору"}}},fp="13,242,18.449.0,22.113.0,27.172.0,44.172.0"}
P.entries["subzone:park"] = {n="Парк",s="Парк, що лежить уздовж західного краю Стормвінда між Соборною Площею й Кварталом магів, — пишний зелений прихисток для тихих роздумів. Присвячений природі й відпочинку посеред гамірної кам'яної столиці, він став головною гаванню для нічних ельфів, що приїздять у гості, і тут працюють єдині наставники друїдів у Східних Королівствах.",h="Парк, що лежить уздовж західного краю Стормвінда між Соборною Площею й Кварталом магів, — пишний зелений...",kw={"парк","нічні ельфи","друїди","місячний колодязь","стормвінд","нара мейдерос"},ang={["class:Druid"]="Цей тихий анклав — ваш єдиний прихисток для навчання й порад на всіх теренах Східних Королівств.",["race:NightElf"]="Для нічних ельфів, що перепливли море, Парк — приємний смак рідного дому: сяйливий Місячний Колодязь у центрі й знайомі наставники, віддані Елуні й дикій природі."},sec={{t="Гай у кам'яній столиці",b="Поки в решті Стормвінда панують бруковані доріжки, височенні вапнякові мури й тісні ринкові ятки, Парк дарує тихий подих дикої природи. Спершу його облаштували як тихе місце відпочинку для містян, але згодом він природно перетворився на анклав для посланців нічних ельфів і мандрівників, що прибувають з-за Великого Моря. Під тінистими кронами, довкола Місячного Колодязя в центрі, квартал приносить у серце людського королівства клаптик священних галявин Калімдору."},{t="Прихисток і братерство",b="Для нічних ельфів Парк — важлива опора на чужій землі. Тут жерці калдореїв, як-от Нара Мейдерос, опікуються прочанами, а наставники-друїди дають поради всім, хто відданий дикій природі. Квартал також служить мирним прихистком, де втомлені шукачі пригод відпочивають від гамору Торгового Кварталу й урочистих обов'язків Собору."}},faq={{q="Де в Стормвінді розташований Парк?",a="Парк лежить уздовж далекого західного краю Стормвінда. До його зелених алей можна дійти на південний захід від Соборної Площі або на північний захід від Кварталу магів.",al={"де парк у стормвінді","як дістатися до парку","розташування парку"}},{q="Чому в Парку так багато нічних ельфів?",a="Нічні ельфи, що прибували до міста, облюбували Парк як прихисток від височенних кам'яних вулиць Стормвінда. Буйні гаї й спокійна атмосфера нагадували їм рідні ліси, тож вони оселилися тут і навіть заклали на площі Місячний Колодязь.",al={"чому нічні ельфи в парку","район нічних ельфів стормвінда","район келдореїв"}},{q="Чи можна тут навчитися друїдських умінь?",a="Так. Нині Парк — єдине місце в усіх Східних Королівствах, де є наставники друїдів Альянсу: вони навчають калдореїв, що опинилися далеко від Калімдору.",al={"друїдські наставники стормвінд","де вчитися друїдом у східних королівствах","навчання друїдів у парку"}},{q="Що за сяйний ставок посеред Парку?",a="Ставок посеред Парку — освячений ельфійський Місячний Колодязь, який створили калдореї, щоб серед людського міста мати священне джерело духовного спокою й місячної сили.",al={"місячний колодязь парку","сяйний фонтан парку","ставок у парку"}}},fp="4,338,28.525.0,24.376.0,39.170.0,46.264.0,33.196.0,51.186.0"}
P.entries["subzone:pestilent-scar"] = {n="Моровий Шрам",s="Моровий Шрам — глибока зачумлена ущелина в спотвореній землі Східних Чумних Земель. На відміну від зубчастих розломів, які роздерла катастрофічна зараза Погибелі, ця прірва, схоже, була природним каньйоном або висохлим дном озера, яке згодом осквернили й заполонили ненажерливі слизи.",h="Моровий Шрам — глибока зачумлена ущелина в спотвореній землі Східних Чумних Земель.",kw={"моровий шрам","ущелина","слизи","сльози артаса","східні чумні землі","чума"},ang={["profession:Herbalism"]="Краї ущелини просякнуті густою гниллю, і на її урвищах іноді проростають рідкісні, загартовані чумою рослини, як-от Сльози Артаса та Чумоцвіт.",["race:Undead"]="Аптекарі Відступників часто вивчають слизи з таких глибоких розломів, щоб виокремити нестійкі різновиди найпідступніших отрут Погибелі."},sec={{t="Зачумлена прірва",b="Моровий Шрам в'ється східними околицями Східних Чумних Земель, утворюючи похмурий розлом в оскверненому краї. Сусідні розломи, як-от Шрам Інфектис, вирвали в землі раптові катастрофічні вибухи Чуми нежиття, але вчені зауважують, що Моровий Шрам, схоже, має природне геологічне походження. Найімовірніше, це був глибокий річковий каньйон або природне озеро, що висохло, коли Погибель прокотилася Лордероном. Лишився безплідний рів, у якому поступово збиралися отруйні стоки й мерзенний слиз."},{t="Слизові ями",b="Позбавлена чистої води й оповита невпинним нечестивим тлінням, улоговина стала розплідником для мутованих їдких слизів і паразитів-падальників. Ходити біля її краю, що осипається, небезпечно: над урвищем стоять їдкі випари, а хисткий ґрунт раз у раз загрожує скинути необачного шукача пригод просто у вируючу твань унизу."}},faq={{q="Що таке Моровий Шрам?",a="Моровий Шрам — глибока ущелина у Східних Чумних землях. Осквернений під час падіння Лордерона, каньйон повний смердючих стоків, хворої землі й агресивних слизових потвор.",al={"лор морового шраму","що таке моровий шрам","каньйон морового шраму"}},{q="Як утворився Моровий Шрам?",a="На відміну від неприродних розколин, які пороздирали землю нищівні вибухи Погибелі, Моровий Шрам, схоже, був природною долиною, озером чи річковим каньйоном, що висох і зачах під гниллю чуми нежиття.",al={"як утворився моровий шрам","походження морового шраму","хто створив моровий шрам"}},{q="Чим він відрізняється від Шраму Інфектис?",a="Шрам Інфектис було жорстоко розірвано — це неприродний вулканічний розлом, що сочиться чистою чарівною гниллю. А Моровий Шрам — давніша природна западина, у якій після смерті землі поступово збиралися скверна й стоки.",al={"моровий шрам проти шраму інфектис","різниця зі шрамом інфектис"}},{q="Хто живе в Моровому Шрамі?",a="На дні провалля панують їдкі слизи, породжені чумою, і паразити-падлоїди, яким чудово живеться серед отруйних калюж і гнилої органіки, що застрягла на дні.",al={"моби морового шраму","хто живе в моровому шрамі"}}},fp="14,293,16.543.0,14.354.0,27.201.0,32.237.0,42.228.0,42.175.0"}
P.entries["subzone:petitioner-s-chamber"] = {n="Палата Прохача",s="Палата Прохача, відома також як Зала Прохачів, — передпокій одразу біля головного пандуса Фортеці Стормвінда. Це офіційна приймальня для знаті, церковних достойників і підданих, що прагнуть аудієнції в корони. Ті, хто чекає тут, часто згають години за розмовами, чаркою чи чеканням на ласку регента.",h="Палата Прохача, відома також як Зала Прохачів, — передпокій одразу біля головного пандуса Фортеці Стормвінда.",kw={"палата прохача","фортеця стормвінда","аудієнція","знать","двір","стормвінд"},ang={["class:Priest"]="Єпископ ДеЛаве часто перебуває в цьому передпокої, тож кімната стає перехрестям адміністративної ієрархії Святого Світла й королівського двору.",["faction:Alliance"]="Для прихильників Альянсу ця палата — вузьке горло управління Стормвінда, де внутрішні звернення, церковні справи й прохання знаті чекають на скупу увагу королівської ради."},sec={{t="Кімната чекання й впливу",b="Палата Прохача, що відкривається праворуч, щойно піднімешся до Фортеці Стормвінда, — місце, де державні справи зустрічаються з буденною бюрократією. Вельможі на кшталт Графа Ремінгтона Ріджвелла й високі церковники, як-от Єпископ ДеЛаве, коротають тут час, чекаючи аудієнції в короля-хлопчика Андуїна Рінна й Верховного Лорда Болвара Фордрагона. За блискучою личиною придворного етикету це ідеальний куточок замку для пліток, тихого лобіювання й з'ясування, хто насправді має вплив у королівстві."}},faq={{q="Де розташована Палата Прохача?",a="Палата — у Фортеці Стормвінда. Щойно ви піднімаєтеся величним пандусом до фортеці, це перша кімната праворуч.",al={"де палата прохача","як знайти палату прохача","розташування палати прохача"}},{q="Хто збирається в цій кімнаті?",a="Сюди часто приходять прохачі, придворні й вельможі, що шукають уваги трону, — серед них Граф Ремінгтон Ріджвелл, Каледра Доунбриз і Єпископ ДеЛаве з Церкви Святого Світла.",al={"хто в палаті прохача","нпс палати прохача","хто тут чекає"}},{q="Чому її ще звуть Залою Прохачів?",a="Її офіційне призначення — приймати підданих, які подали короні офіційні прохання. Відвідувачі мусять чекати тут, доки регент, Верховний Лорд Болвар Фордрагон, чи королівська рада не допустять їх до тронної зали.",al={"зала прохачів","чому зала прохачів","палата прохачів"}},{q="Що тут відбувається під час міських завдань?",a="До палати здебільшого приходять, щоб доставити товари чи поговорити з вельможами й духовенством фортеці, — наприклад, принести вишукані напої на кшталт портвейну спраглим аристократам, що чекають своїх справ при дворі.",al={"завдання палати прохача","які завдання ведуть сюди"}}},fp="20,373,31.524.0,42.151.0,25.219.0,46.222.0,37.226.0"}
P.entries["subzone:pig-and-whistle-tavern"] = {n="Таверна «Свиня і Свисток»",s="Таверна «Свиня і Свисток» — гомінкий шинок у суворому кварталі Старого Міста в Стормвінді. Це улюблене місце зустрічей для мандрівників Альянсу, місцевих робітників і бувалих ветеранів, що згадують давні війни королівства.",h="Таверна «Свиня і Свисток» — гомінкий шинок у суворому кварталі Старого Міста в Стормвінді.",kw={"свиня і свисток","таверна","старе місто","кендор кабонка","рецепти","стормвінд"},ang={["faction:Alliance"]="Для солдатів і мандрівників Альянсу, що проходять столицею, таверна — гостинне, невибагливе вогнище й товариство ветеранів давніших воєн королівства.",["profession:Cooking"]="Кулінари часто вирушають у паломництво до таверни, щоб розшукати Кендора Кабонку, що продає неперевершену збірку рідкісних рецептів з усього Азероту."},sec={{t="Прихисток у Старому Місті",b="Таверна «Свиня і Свисток», що стоїть серед похмурих звивистих провулків Старого Міста, дає тепло, ель і нічліг тим, хто ходить грубішим кварталом столиці. Поки міська знать збирається на соборних площах і мармурових майданах, цей заклад обслуговує простих містян, трудящих і мандрівників, що щойно з дороги. Усередині можна знайти купців на кшталт славетного торговця рецептами Кендора Кабонки, а також сивих ветеранів, що цмулять із кухлів, згадуючи Першу й Другу війни."}},faq={{q="Де розташована Таверна «Свиня і Свисток»?",a="Таверна «Свиня і Свисток» стоїть у Старому Місті — східному кварталі Стормвінда, відомому військовими казармами, розбійницькими кублами й робітничими кварталами.",al={"де свиня і свисток","розташування свині і свистка","таверна старого міста"}},{q="Хто часто буває в таверні?",a="Таверна полюбилася мандрівникам, вартовим після служби й ветеранам, що обмінюються історіями про Першу й Другу війни, а також відомим крамарям, як-от Кендорові Кабонці, майстрові кулінарних рецептів.",al={"хто буває в свині і свистку","відвідувачі свині і свистка"}},{q="Які послуги надає таверна?",a="«Свиня і Свисток» — таверна, де втомлені мандрівники можуть відпочити й купити їжу, напої та особливі кулінарні рецепти.",al={"чи свиня і свисток корчма","послуги свині і свистка"}}},fp="22,246,20.527.0,44.158.0,25.203.0,38.122.0"}
P.entries["subzone:plaguemist-ravine"] = {n="Яр Чумної Імли",s="Яр Чумної Імли — вузький гірський прохід, що з'єднує дикі зелені нетрі Пригір'я з моторошними берегами Озера Дарроумер у Західних Чумних Землях. Назву він дістав від хворобливого туману, що сповзає сюди з півночі. Це тихий і безлюдний шлях через гірський хребет.",h="Яр Чумної Імли — вузький гірський прохід, що з'єднує дикі зелені нетрі Пригір'я з моторошними берегами Озера...",kw={"яр чумної імли","пригір'я","озеро дарроумер","каер дарроу","ложа кель'даніл","західні чумні землі"},ang={["class:Hunter"]="Яр — спокійне місце переходу, та через брак дичини й лісових звірів ця межа здається слідопитам моторошною, коли вони прямують на північ, до Чумних Земель.",["faction:Alliance"]="Цей прохід дає розвідникам Альянсу з Ложі Кель'Даніл змогу непомітно стежити за зачумленими берегами довкола Каер Дарроу, не натрапляючи на дорожні патрулі."},sec={{t="Зачумлений поріг",b="Яр Чумної Імли ховається в горах на північний захід від Ложі Кель'Даніл і слугує природною межею між двома зовсім несхожими світами. На півдні розкинулися буйні дикі нагірні ліси Пригір'я, а на півночі прохід виходить просто до Каер Дарроу й зачумлених просторів Західних Чумних Земель. Свою назву яр дістав через гидкі, неприродні випари, що повзуть на південь із Чумних Земель і разюче контрастують зі свіжим гірським повітрям сусідньої глушини."},{t="Тихий прохід",b="Хоча яр врізається просто в край земель, сплюндрованих Погибеллю, сам він напрочуд безлюдний. У самій ущелині мандрівники не зустрінуть ні диких звірів, ні неприкаяної нежиті. Через цю моторошну тишу звивиста стежка стала зручною, хоч і зловісною, обхідною дорогою для відчайдушних гінців і шукачів пригод, які хочуть оминути добре укріплені шляхи й прикордонні застави на в'їзді до Лордерону."}},faq={{q="Куди веде Яр Чумної Імли?",a="Яр Чумної Імли сполучає Пригір'я із Західними Чумними Землями. На північ він виводить до берегів Озера Дарроумер, біля острівної фортеці Каер Дарроу, а на південь — на лісисті пагорби на північний захід від Ложі Кель'Даніл.",al={"куди веде яр чумної імли","шлях яру чумної імли","зв'язки яру чумної імли"}},{q="Чому він зветься Яром Чумної Імли?",a="Цю назву перевалу дали недавно через густий отруйний туман, що сповзає на південь із Західних Чумних Земель. Хворе повітря різко контрастує зі свіжим, незіпсованим повітрям, звичним для Пригір'я.",al={"чому яр чумної імли","походження назви чумної імли"}},{q="Чи є в яру вороги чи інші персонажі?",a="Ні. У яру немає ні ворожих істот, ні звірів, ні дружніх персонажів, тож це незвично тихий прохід між двома жвавими краями.",al={"моби яру чумної імли","чи безпечний яр чумної імли"}},{q="Як знайти вхід у Пригір'ї?",a="У Пригір'ї вхід сховався в північній гірській стіні на захід від Ложі Кель'Даніл і на північ від табору Рапсоді Шіндіґґер.",al={"як знайти яр чумної імли","вхід у яр чумної імли"}}},fp="17,291,20.524.0,15.438.0,34.258.0,35.217.0,44.163.0,48.144.0"}
P.entries["subzone:plaguewood"] = {n="Чумнолісся",s="Колись тут шумів мирний ліс Зеленолісся, а тепер Чумнолісся — зачумлений, задушений грибами край на південь від Стратгольма. Тут кишать споруди Погибелі й патрулюють багряні хрестоносці, тож це один із найбільш осквернених куточків Східних Чумних Земель.",h="Колись тут шумів мирний ліс Зеленолісся, а тепер Чумнолісся — зачумлений, задушений грибами край на південь...",kw={"чумнолісся","зеленолісся","стратгольм","андоргал","гриби","погибель","багряні хрестоносці"},ang={["class:Paladin"]="Покручені дерева й мерзенні казани Чумнолісся — моторошне нагадування про падіння Лордерона, де кожен поборник Світла мусить вистояти проти зграй гидот і непохитних фанатиків.",["faction:Alliance"]="Для вцілілих з Альянсу ці стежки — та сама дорога, якою принц Артас ішов до сумнозвісної різанини в Стратгольмі. Тепер вона потопає в гнилі й шалених багряних фанатиках."},sec={{t="Від Зеленолісся до тління",b="До Третьої війни цей край звався Зеленолісся — це був пишний ліс, схожий на буйні гаї Елвінна. Біля входу до нього стояло скромне село, а його дорогами ходили і фермери, і солдати. Усе це завалилося, коли з Андоргала привезли заражене зерно. Нині замість родючої землі тут губчастий, осквернений ґрунт, а велетенські гриби височіють над мертвими деревами й без упину випускають над лісовою підстилкою отруйні бурі випари."},{t="Оплот мерців",b="Тепер Чумнолісся цілком належить Погибелі й слугує похмурим плацдармом для нежиті довкола Стратгольма. Зикурати й бойні всіяли зогнилий край і без кінця випускають гидот і культистів. І наче цього мало, фанатичні багряні хрестоносці невпинно патрулюють дорогу до брам Стратгольма: вони рвуться вичистити Погибель і безжально вбивають кожного живого мандрівника, який їм трапиться."}},faq={{q="Як звався цей ліс до чуми?",a="До Третьої війни цей край звався Зеленим Лісом. Це був квітучий ліс із невеликим селом біля узлісся — красою й кліматом він дуже нагадував Ліс Елвінн.",al={"стара назва чумнолісся","лор зеленого лісу","чим було чумнолісся"}},{q="Чому скрізь ростуть велетенські гриби?",a="Чума докорінно спотворила місцеву природу. Земля стала губчастою, а лісом розрослися потворні гриби, що вивергають отруйні бурі хмари, схожі на випари чумних казанів.",al={"гігантські гриби чумнолісся","грибок чумнолісся","чому гриби"}},{q="Хто сьогодні тримає Чумнолісся?",a="Ліс майже цілком у руках Погибелі — тут і некроманти, і гулі, і зикурати, і бойні. Крім того, головними дорогами регулярно ходять патрулі Багряного Хрестового Походу, що нападають і на нежить, і на будь-яких живих мандрівників.",al={"хто править чумнолісся","вороги чумнолісся","хто живе в чумнолісся"}},{q="Куди веде дорога крізь ліс?",a="Головна дорога веде просто на північ, до брами полеглого міста Стратгольм, а західні простори отруєного лісу тягнуться до зруйнованого села Террордейл.",al={"куди веде дорога чумнолісся","куди веде шлях","дорога до стратхольма"}}},fp="10,276,23.444.0,21.427.0,46.176.0,51.204.0,34.257.0,43.184.0"}
P.entries["subzone:plaguewood-tower"] = {n="Вежа Чумнолісся",s="Вежа Чумнолісся — зруйнована дозорна вежа Лордерона на півночі Чумнолісся, біля Террордейлу. Її розтрощили під час навали Погибелі, і тепер вона стоїть розваленою руїною посеред зачумленого лісу.",h="Вежа Чумнолісся — зруйнована дозорна вежа Лордерона на півночі Чумнолісся, біля Террордейлу.",kw={"вежа чумнолісся","дозорна вежа","чумнолісся","террордейл","лордерон","руїни"},ang={["faction:Alliance"]="Для сил Альянсу потрощені дозорні вежі Лордерона — гірке нагадування про людські землі, втрачені через Погибель.",["faction:Horde"]="Для Орди зруйновані укріплення на кшталт Вежі Чумнолісся показують, як дощенту Погибель зламала оборону північних королівств."},sec={{t="Зруйнований вартовий півночі",b="Вежа Чумнолісся, що стоїть на межі задушеного заразою Чумнолісся й зачумленого містечка Террордейл, колись була важливою північною дозорною вежею Королівства Лордерон. Коли Погибель прокотилася краєм, укріплення розбили на кладку, що кришиться, і покинули в руїнах серед осквернених грибних крон. Сьогодні потріскане каміння досі здіймається над північними стежками — мовчазне нагадування про варту, яку колись Лордерон ніс над цією землею."}},faq={{q="Для чого спершу була Вежа Чумнолісся?",a="Вежу Чумнолісся збудувало королівство Лордерон як місцеву сторожову вежу. До Третьої війни вартові звідси пильнували північні ліси, дороги й поселення на кшталт Террордейла, доки Погибель не здолала й не розбила гарнізон.",al={"первісне призначення","хто збудував вежу чумнолісся","історія вежі"}},{q="Де саме стоїть вежа?",a="Вона на півночі Східних Чумних земель, у Чумноліссі, одразу біля зруйнованого містечка Террордейл і на південь від отруєних околиць Стратгольма.",al={"розташування вежі","де вежа чумнолісся","місце на мапі"}}},fp="16,214,30.448.0,46.257.0,35.182.0"}
P.entries["subzone:pool-of-ask-ar"] = {n="Ставок Аск'ар",s="Ставок Аск'ар — розлоге затоплене печерне озеро глибоко в Чорноглибинних Печерах. Тут кишать водяні звірі й мерзенні наги-загарбники, а води ховають давню архітектуру нічних ельфів і таємні проходи, що ведуть углиб оскверненого святилища.",h="Ставок Аск'ар — розлоге затоплене печерне озеро глибоко в Чорноглибинних Печерах.",kw={"ставок аск'ар","наги","ґаму-ра","рукопис лорґаліса","чорноглибинні печери"},ang={["faction:Alliance"]="Щоб дізнатися про долю Срібного Вартового Таелріда, що спустився в ці печерні глибини зі святою місією проти Молота Присмерку, треба прорватися крізь водяні шляхи.",["race:NightElf"]="Ставок затопив те, що колись було святою землею храму Елуни: давня архітектура пішла під воду, а священні реліквії на кшталт Рукопису Лорґаліса розкидані й розграбовані нагами."},sec={{t="Глибини затонулого грота",b="Ставок Аск'ар, що лежить одразу за Затопленим Сакелумом, заповнює величезне підземне склепіння каламутною холодною водою. Природні печери й давня кладка стали гніздовищем для завеликих черепах-кусачок і глибоководних крабів, над якими панує велетенський давній черепаховий звір на ім'я Ґаму-Ра. Наги, що захопили храм, використовують цей затоплений поріг як оборонний плацдарм, стережучи залиті водою підходи, що ведуть углиб комплексу — до леді Саревесс і Руїн Місячної Святині."},{t="Таємниці під поверхнею",b="Окрім жахливих звірів і ворожих патрулів, води ставка ховають цінні реліквії святині з часів до Розколу. Затоплені уступи й приховані ніші вздовж країв печери бережуть утрачені артефакти, зокрема цінний Рукопис Лорґаліса, який шукає дворфійський учений Ґерріґ Боунґріп з Айронфорджа. Пропливши затопленими південними проходами, мандрівники виходять у сухі тунелі, які стережуть мерзенні мурлоки й культисти Древніх Богів, — тож ставок стає головним водяним перехрестям Чорноглибинних Печер."}},faq={{q="Що таке Ставок Аск'ар?",a="Це величезний підземний ставок у Чорноглибинних Печерах, одразу за Затопленою Каплицею. Тут панують черепахи-хапуни, краби й наги-вартові.",al={"ставок аск'ар","що це за ставок","водна зона чорнотрясовини"}},{q="Хто живе в цьому підземному ставку?",a="У печері живуть дикі мешканці рифів — черепахи-хапуни й краби, а найпомітніша серед них — велетенська черепаха Ґаму-Ра. Затопленими берегами й сусідніми залами також ходять ворожі наги.",al={"монстри ставка","боси ставка аск'ар","хто в ставку"}},{q="Куди ведуть підводні тунелі?",a="Затопленими південними проходами можна дістатися зал, де засіли леді Саревесс і Срібний Вартовий Таелрід, а звідти шлях в'ється повз Ґелігаста до Руїн Місячної Святині.",al={"тунелі ставка","куди йде вода","вихід зі ставка аск'ар"}},{q="Які цінні речі можна знайти в ставку?",a="У затоплених руїнах по краях ставка лежить Рукопис Лорґаліса — давній текст про Древніх Богів, якого прагне Ґерріґ Боунґріп з Айронфорджа.",al={"реліквії ставка аск'ар","рукопис лорґаліса","здобич ставка"}}},fp="14,275,27.526.0,27.525.0,27.158.0,36.192.0,37.194.0,44.152.0"}
P.entries["subzone:pool-of-tears"] = {n="Ставок Сліз",s="Ставок Сліз — велике каламутне озеро, що займає східну частину Болота Скорботи. Глибоко під його поверхнею лежить затонулий Храм Атал'Гаккара, який зелені дракони затопили, щоб стримати жахи, що ховаються всередині. Сьогодні в мутних водах нишпорять хижі риби-шаленці, а затоплені береги всіяні руїнами прадавніх тролячих споруд.",h="Ставок Сліз — велике каламутне озеро, що займає східну частину Болота Скорботи.",kw={"ставок сліз","затонулий храм","ізера","зелені дракони","атал'аї","болото скорботи"},ang={["class:Druid"]="Друїди шанують озеро, адже саме тут Ізера й зграя зелених драконів утрутилися, щоб зупинити скверну Бога Крові.",["race:Troll"]="Для тролів Темного Списа цей ставок — похмуре застереження про те, що чекає на тролячий рід, коли він приймає заборонену магію крові, як це зробили Атал'аї."},sec={{t="Затоплене святилище",b="Давним-давно фанатичні тролі Атал'аї звели величний зикурат на честь свого кровожерливого бога Гаккара Душолупа. Нажахана блюзнірством, що коїлося всередині, Ізера, Аспект драконів, розколола землю під спорудою й поглинула величезний храм глибинами болота. Озеро, що вже було тут, залило руїни храму. Дракони прагнули поховати зло навіки, але зикурат і досі стоїть під мулом і хвилями, а зелені дракони пильно чатують поблизу, щоб його скверна не вирвалася назовні."},{t="Небезпечні води",b="Перетнути каламутне озеро — ризикована справа для кожного шукача пригод, що прямує до затонулих зал. У воді кишать м'ясоїдні шаленці, а по мулистому дну розкидані артефакти Атал'аї й затоплене каміння. Щоб дістатися до верхніх проходів затопленого храму, мандрівникам доводиться долати ці ворожі мілини, а всередині культисти й дракони-вартові, що досі лишаються там, змагаються за владу над темним святилищем."}},faq={{q="Чому він зветься Ставком Сліз?",a="Звідки ця назва, ніде не записано. Озеро відоме Храмом Атал'Гаккара, який Ізера занурила під воду, щоб зупинити виклик Гаккара.",al={"походження назви ставка сліз","чому ставок сліз","значення ставка сліз"}},{q="Що за величезна будівля посеред озера?",a="Це Храм Атал'Гаккара, якого часто звуть Затонулим Храмом. Колись високий зикурат Атал'ай, він був скинутий під воду Ізерою і досі стоїть напівзатоплений посеред ставка.",al={"будівля в ставку сліз","руїни в озері болота скорботи","розташування затонулого храму"}},{q="Чому біля води зелені дракони?",a="Виводок Ізери прибув, щоб зруйнувати храм і втопити його мерзенні обряди. Зелені дракони й драконячі створіння досі пильнують озеро, щоб сектанти Атал'ай не змогли завершити виклик Бога Крові.",al={"зелені дракони болота скорботи","чому тут дракони","храм ізери на озері"}},{q="Чи безпечно перепливти ставок?",a="Ні. Озеро кишить агресивними хижими шаленцями, що нападають на кожного, хто попливе до входу в храм.",al={"плавання в ставку сліз","акули ставка сліз","шал болота скорботи"}}},fp="13,329,19.521.0,15.403.0,35.157.0,55.197.0,45.206.0,35.128.0"}
P.entries["subzone:pools-of-arlithrien"] = {n="Озерця Арлітрієну",s="Озерця Арлітрієну — скупчення відлюдних джерел у західному Тельдрассилі, одразу на південь від брами Дарнасуса. Колись тихий притулок довкола священного місячного колодязя, це місце занепало й стало небезпечним, коли на нього посунули місцева живність і ворожі фурболги-Вузлошкіри.",h="Озерця Арлітрієну — скупчення відлюдних джерел у західному Тельдрассилі, одразу на південь від брами...",kw={"озерця арлітрієну","місячний колодязь","джерела","дарнасус","фурболги","вузлошкіри","тельдрассил"},ang={["class:Druid"]="Друїди, що вивчають розлади Тельдрассила, бачать у некерованій живності й занедбаному місячному колодязі ще один знак, що Великому Дереву бракує справжнього благословення природи.",["race:NightElf"]="Покинутий святий місячний колодязь так близько до Дарнасуса — тривожне нагадування нічним ельфам про скверну й розлад, що повзуть Тельдрассилом."},sec={{t="Неспокійне святилище",b="Озерця Арлітрієну в тінистому гіллі на південь від Дарнасуса задумували як тихе місце природної гармонії. У їхньому серці — кам'яний місячний колодязь, посудина для вод, сповнених ласки Елуни. Та попри близькість до столиці нічних ельфів святилище стало небезпечним. Збурені звірі бродять мілководдям, а невпинна ворожість витіснених фурболгів-Вузлошкірів змусила нічних ельфів облишити звичний догляд за місцем, і мирне диво опинилося в тіні недуги, що охоплює острів."}},faq={{q="Де розташовані Озерця Арлітрієну?",a="Озерця сховалися на заході Тельдрассилу, трохи на південь від головного мосту й входу до столиці Дарнасус.",al={"розташування озерець арлітрієну","де арлітрієн","арлітрієн на мапі"}},{q="Чому тутешній місячний колодязь покинуто?",a="Нічні ельфи перестали доглядати колодязь через дедалі більшу небезпеку. Поряд загрозливо отаборилися ворожі фурболги-Вузлошкіри, а довколишні води заполонили агресивні лісові звірі.",al={"чому покинуто","покинутий місячний колодязь арлітрієну","порожній місячний колодязь"}},{q="Які небезпеки чекають мандрівників біля озерець?",a="Мандрівникам біля озерець доведеться мати справу з агресивними лісовими істотами, що захопили води, а ще поруч чатують Вузлошкіри, які ревно бережуть свої землі.",al={"монстри арлітрієну","моби озерець арлітрієну","вороги озерець"}},{q="Чи можуть гравці досі користуватися місячним колодязем біля Озерець Арлітрієну?",a="Так. Хоча жерці й друїди покинули колодязь без догляду через місцеві небезпеки, він досі зберігає свою священну воду й лишається діючим джерелом місячної сили.",al={"користуватися колодязем арлітрієну","чи діє місячний колодязь","вода озерець"}}},fp="19,305,20.549.0,42.146.0,36.216.0,45.190.0,62.185.0"}
P.entries["subzone:pools-of-vision"] = {n="Ставки Видінь",s="Ставки Видінь — підземна печера під Узвишшям Духів у Тандер Блафі. Зі своїми нерухомими водами й тьмяними гротами цей відлюдний підземний куточок став головним осередком Відступників у тауренській столиці.",h="Ставки Видінь — підземна печера під Узвишшям Духів у Тандер Блафі.",kw={"ставки видінь","тандер блаф","відступники","узвишшя духів","печера","нежить"},ang={["class:Mage"]="Печера — опора чародійних лей-ліній міста: кожне закляття телепортації до Тандер Блафа переносить заклинача просто до цих відлюдних ставків.",["race:Undead"]="Для Відступників, що мандрують рівнинами Калімдору, ця печера — знайомий затінений прихисток із чародійними припасами, жрецькими настановами й товариством."},sec={{t="Прихисток під горою",b="Осяяні сонцем вершини Тандер Блафа належать вітрові, землі й небу, а Ставки Видінь ховаються просто під Узвишшям Духів, у тінистій відлюдності. Сюди веде непомітна печерна стежка від мосту на узвишшя, і цей підземний грот дарує зовсім інший спочинок, ніж відкриті хатини нагорі. Тут у темряві збираються туманні води, і в цій відокремленості заклиначі Орди сходяться далеко від гамірних центральних висот."},{t="Застава нежиті",b="У Тандер Блафі Ставки Видінь фактично слугують базою Відступників. Мандрівники зі східного континенту знаходять тут споріднені душі: жерців-нежить, що практикують свої тіньові мистецтва, магів, що відкривають чародійні портали, і посланців Осквернителів, які набирають охочих для походів на Аратійське нагір'я. Чи то через недовіру тауренів, чи то через природну любов Відступників до темряви, цей тихий прихисток поєднує нежить Лордерона з союзниками в Калімдорі."}},faq={{q="Де вхід до Ставків Видінь?",a="Вхід — це печера на Узвишші Духів, одразу праворуч, щойно ви перейдете дерев'яний мотузяний міст із нижнього плато.",al={"як дістатися до ставків видінь","вхід у ставки видінь","де ставки видінь"}},{q="Чому тут унизу живуть Відступники?",a="Печера — головний осередок Відступників у Тандер Блафі. Вона ховає від пекучого сонця Калімдору й дає місце для обрядів, які могли б збентежити тауренських шанувальників духів.",al={"чому відступники тут","чому нежить у печері","нежить громовиці"}},{q="Які послуги є в Ставках Видінь?",a="У печері є наставники жерців і магів, а також посланці Осквернителів, що збирають вояків на війну в Аратійському нагір'ї.",al={"наставники ставків видінь","що в ставках видінь","ставки видінь наставники"}},{q="Де з'являються маги, коли телепортуються до Тандер Блафа?",a="Маги, що телепортуються чи відкривають портал до Тандер Блафа, з'являються просто у захищених водах Ставків Видінь під Узвишшям Духів.",al={"місце появи магів у громовиці","точка телепорту громовиця"}}},fp="15,238,24.459.0,18.509.0,45.158.0,38.217.0,54.169.0,58.151.0"}
P.entries["subzone:purgation-isle"] = {n="Острів Спокути",s="Острів Спокути — скелястий острів зі спіральними стежками біля південного узбережжя Передгір'я Гілсбреда. Його вінчають кладовище й зруйнована дозорна вежа, а сама пустельна скеля проклята й кишить неспокійними, засудженими духами полеглих людей і дворфів.",h="Острів Спокути — скелястий острів зі спіральними стежками біля південного узбережжя Передгір'я Гілсбреда.",kw={"острів спокути","гілсбред","привиди","кладовище","кул тірас","кормок"},ang={["class:Paladin"]="Сумне видовище проклятих паладинів і суддів, що блукають Островом Спокути, — похмуре нагадування про те, що буває, коли святі захисники стають жертвами темних прокльонів і не мають вічного спочинку.",["race:Dwarf"]="Серед проклятих привидів, що блукають кладовищем, є й духи дворфів: ваших родичів прикуто до цієї самотньої, обдуваної вітрами скелі далеко від гір Каз Модану."},sec={{t="Примарний притулок",b="Острів Спокути раптово здіймається з моря на південь від Гілсбреда — похмуре видовище: звивисті стежки ведуть повз надгробки до покинутої сторожової вежі. Задовго до нинішніх війн острів пов'язували з морським королівством Кул Тірас. Та нині жоден живий народ на нього не претендує. Натомість острів обсіли засуджені душі — колишні паладини, жерці, маги й судді, що блукають між могилами, не знаходячи спокою й по смерті."},{t="Темні зв'язки",b="Душі, ув'язнені на острові, привертають зловісну цікавість. Кажуть, темні чаклуни — як-от огр-некромант Кормок — охоче черпали силу з мучених мерців острова, викликаючи його духів собі на послуги."}},faq={{q="Де розташований Острів Спокути?",a="Острів Спокути — відокремлений острів біля південного узбережжя Передгір'я Гілсбреда, у затоці на південь від суходолу.",al={"розташування острова спокути","де острів спокути","як знайти острів спокути"}},{q="Хто блукає островом?",a="Острів заполонили могутні засуджені духи — прокляті паладини, юстиціарії, клірики, послушники й корчливі маги людського та дворфійського роду.",al={"хто на острові спокути","моби острова спокути","привиди острова спокути"}},{q="Кому спершу належав Острів Спокути?",a="До Першої війни Острів Спокути вважали віддаленою територією острівного королівства Кул Тірас, доки він не занепав і не став пристановищем привидів.",al={"історія острова спокути","хто збудував вежу острова спокути"}},{q="Хто такий Кормок і чому його цікавить цей острів?",a="Кормок — горезвісний огр-некромант, що навчився за допомогою особливих темних артефактів викликати засуджених духів Острова Спокути й змушувати їх виконувати свою волю.",al={"зв'язок із кормоком","жаровня виклику привиди"}}},fp="14,258,19.451.0,17.262.0,32.133.0,23.159.0,36.166.0,53.164.0"}
P.entries["subzone:pyrewood-village"] = {n="Село Пайрвуд",s="Село Пайрвуд — відокремлене людське поселення на півдні Срібнолісся, під Фортецею Шадовфенг. Колись частина Ґілнеаса, а потім покинуте по той бік Стіни Ґреймейна, воно ховає жахливу таємницю, яку наклав на живих мешканців божевільний архімаг Аруґал.",h="Село Пайрвуд — відокремлене людське поселення на півдні Срібнолісся, під Фортецею Шадовфенг.",kw={"село пайрвуд","воргени","мунрейджі","аруґал","ґілнеас","срібнолісся"},ang={["faction:Alliance"]="Село — трагічні рештки живого людства в Лордероні: удень тут охоче торгують із мандрівниками, а щоночі піддаються жахливому прокляттю.",["faction:Horde"]="Для Відступників Пайрвуд — уперте гніздо ворожих людей і жахливих воргенів на службі Архімага Аруґала просто на кордоні їхніх земель."},sec={{t="Відрізане містечко",b="Колись Пайрвуд був заможним ґілнеаським поселенням, що належало лордові Даріусу Кроулі. Коли після Другої війни король Ґенн Ґреймейн вирішив відгородити своє королівство величезною Стіною Ґреймейна, Пайрвуд і його сусіда Амбермілл покинули на північному боці. Відрізані від батьківщини, містяни лишилися цілком беззахисними під час Третьої війни, коли Погибель крокувала Лордероном. Хоч вони пережили першу хвилю нежиті, справжній кошмар почався, коли маг Аруґал знайшов прихисток у фортеці над селом."},{t="Прокляття Мунрейджів",b="З веж Фортеці Шадовфенг Архімаг Аруґал випустив на довколишні землі потойбічних звірів і зрештою прокляв живих мешканців Пайрвуда. Удень містяни мають вигляд звичайних селян: тихо доглядають ратушу, кузню й каплицю й навіть торгують із мандрівниками Альянсу. Та щойно сонце сідає за обрій, стається жахливе перетворення: кожен мешканець обертається на лютого, кровожерливого воргена зі зграї Мунрейджів і кидається на кожного, хто має нещастя затриматися в селі."}},faq={{q="Чому Село Пайрвуд нападає на мене вночі?",a="На селян наклав темне прокляття архімаг Аруґал із Фортеці Шадовфенг. Удень вони зберігають людську подобу й здоровий глузд, але щоночі обертаються на ненажерливих воргенів Мунрейджа, що нападають на всіх чужинців.",al={"чому пайрвуд нападає вночі","пайрвуд ворожий уночі","воргени пайрвуду"}},{q="Чому Пайрвуд опинився за Стіною Ґреймейна?",a="Після Другої війни король Ґенн Ґреймейн наказав звести Стіну Ґреймейна, щоб відгородити Ґілнеас від зовнішнього світу. Лорд Даріус Кроулі рішуче виступав проти стіни, бо вона відрізала його північні володіння — зокрема Пайрвуд і Амбермілл, — полишивши їхніх мешканців напризволяще.",al={"чому пайрвуд за стіною","чи пайрвуд ґілнеас","даріус краулі пайрвуд"}},{q="Чи можуть гравці Альянсу безпечно відвідати Пайрвуд?",a="Так, але лише вдень. Поки світить сонце, мандрівники з Альянсу можуть ходити серед селян і торгувати з місцевими крамарями. Та щойно западає темрява, усе село обертається на ворожих воргенів, хоч би з якої ви були фракції.",al={"чи альянс пайрвуд дружній","чи може альянс у пайрвуд","торговці пайрвуду"}},{q="Як ставиться до Пайрвуда Орда?",a="Відступники вважають село нестерпною загрозою на своєму південному кордоні. Під проводом агентів на кшталт Скрадачки Смерті Фаерлеї Орда прагне вбити раду села й розірвати зв'язок Пайрвуда з Аруґалом.",al={"відступники пайрвуд","орда ворожа пайрвуд","скрадач смерті ферлея пайрвуд"}}},fp="16,279,14.546.0,18.571.1,45.250.0,42.295.0,43.254.0,33.228.0"}
P.entries["subzone:quagmire"] = {n="Трясовина",s="Трясовина — розлоге, підступне серце центральної частини Багна Пилоброду. З півночі її обмежує Село Папоротяної Стіни, з півдня — Драконяча Мряка, а її підтоплені рівнини славляться тим, що ними вкрай важко пробиратися. Ворожі звірі й ненажерливі слизи роблять кожну подорож цим серединним болотом небезпечною.",h="Трясовина — розлоге, підступне серце центральної частини Багна Пилоброду.",kw={"трясовина","багно пилоброду","ферма табети","кроколіски","слизи","болото"},ang={["class:Mage"]="Глибоко в болоті лежить Ферма Табети — важливе місце для молодих магів, що шукають езотеричної науки подалі від пильного ока Кірін-Тору."},sec={{t="Серце болота",b="Трясовина займає широкий простір між Загубленим Мисом на заході й Затокою Пилоброду на сході — це дике осердя болота. Твердий ґрунт тут у кращому разі ненадійний: земля раз у раз поступається каламутній воді й липкій багнюці. Мандрівникам доводиться мати справу з хижими кроколісками, що чатують під ряскою, агресивними павуками, які гніздяться в сухостої, і дивними слизами, що сочаться крізь мул."},{t="Зіткнення на межі",b="Окрім природних небезпек, Трясовина — непередбачуване перехрестя для розумних сил, що змагаються за болото. Серед трясовини захована Ферма Табети — самотній прихисток для чаклунів, що шукають мудрості відлюдниці посеред болотяних небезпек."}},faq={{q="Де розташована Трясовина?",a="Трясовина займає центральну частину Багна Пилоброду. На захід вона тягнеться до Загубленого Мису, на схід — до Затоки Пилоброду, на північ — до меж Села Папоротяної Стіни, а на півдні земля спускається до Драконячої Мли.",al={"розташування трясовини","де трясовина","трясовина на мапі"}}},fp="8,306,16.411.0,19.259.0,30.225.0"}
P.entries["subzone:quel-lithien-lodge"] = {n="Ложа Кель'Літієн",s="Ложа Кель'Літієн — відлюдний прихисток високих ельфів на лісистих північних пагорбах Східних Чумних Земель, біля кордону з Кель'Таласом. Її рейнджери-Далекоходи на чолі з Рентаром Гокспіром — вигнанці з батьківщини, які відкидають радикальні магічні практики, що їх перейняли їхні родичі в Сілвермуні. Оточена Погибеллю й переслідувана розвідниками Відступників, ложа ледве виживає, але й далі береже багатовікові ельфійські архіви.",h="Ложа Кель'Літієн — відлюдний прихисток високих ельфів на лісистих північних пагорбах Східних Чумних Земель...",kw={"ложа кель'літієн","далекоходи","високі ельфи","рентар гокспір","реєстр кель'таласу","натанос блайткаллер","рейнджери"},ang={["class:Hunter"]="Далекоходи, що стоять тут, уособлюють багатовікове класичне талассійське стрілецьке мистецтво: вони зберігають навички виживання у ворожій глушині, цілком відрізані від цивілізованого світу.",["faction:Horde"]="За наказом Натаноса Блайткаллера із Садиби Марріса поборників Орди посилають сюди зі смертельною місією — силою здобути записи високих ельфів."},sec={{t="Гірке вигнання",b="До Третьої війни Кель'Літієн був улюбленим лісовим притулком Далекоходів Кель'Таласу, куди часто навідувалися досвідчені рейнджери, як-от Лор'темар Терон. Доля його змінилася, коли Погибель сплюндрувала ельфійське королівство, а щоб угамувати болісну магічну спрагу вцілілих, принесли нові магічні вчення. Рентар Гокспір і загін рейнджерів рішуче заперечили проти цих сумнівних методів із моральних міркувань. Не бажаючи терпіти внутрішній розбрат, поки народ ледве відбудовується, регент лорд Лор'темар вигнав незгодних на південь. Рентар привів своїх прибічників до Ложі Кель'Літієн. Тут вони зберігають свою високоельфійську самобутність: відрізані від дому, але рішуче відмежовані від осквернених руїн довкола."},{t="Переслідувані в Чумних Землях",b="Тиха варта рейнджерів не лишилася непоміченою. Глибоко в зараженому лісі Натанос Блайткаллер — колись єдиний людський лорд-рейнджер, який навчався пліч-о-пліч із цими самими ельфами, — послав поборників Орди проникнути до Ложі Кель'Літієн. Натанос шукає Реєстр Кель'Таласу — офіційний літопис із відомостями про орден рейнджерів і ельфійські родоводи — і велить вирізати захисників ложі, щоб його здобути. Відрізані від Сілвермуна й відмовляючись від допомоги, рейнджери Кель'Літієн опинилися в облозі і колишніх союзників, і нежиті довкола."}},faq={{q="Чому у Східних Чумних землях живуть живі високі ельфи?",a="Мешканці ложі — Далекоходи й жерці, яких вигнав із Кель'Таласу Лорд-Регент Лор'темар Терон. Вони відмовилися переймати темні, відчайдушні методи, яких навчали, щоб пережити знищення Сонячного Колодязя, і обрали вигнання замість того, що вважали моральним зіпсуттям свого народу.",al={"чому тут живі високі ельфи","хто живе в кель'літієн","ельфи кель'літієн"}},{q="Хто очолює Ложу Кель'Літієн?",a="Ложу очолює Рентар Гоукспір — досвідчений ельфійський капітан слідопитів, що командував тут мисливцями ще в часи Другої війни. Розійшовшись у поглядах із владою Сілвермуна, він привів вигнанців-незгодних до ложі, щоб разом дати відсіч.",al={"лідер кель'літієн","рентар яструбиний спис","хто такий рентар"}},{q="Чи належать ельфи з Ложі Кель'Літієн до Альянсу?",a="Ні. Вони привітні до мандрівників з Альянсу й відкрито ворожі до Орди, але ложа — цілком самостійне поселення високих ельфів, що не отримує жодної офіційної підтримки чи вказівок ні від Стормвінда, ні від Айронфорджа.",al={"чи ельфи кель'літієн альянс","фракція кель'літієн"}},{q="Чому Натанос Блайткаллер націлився на ложу?",a="Натанос Блайткаллер посилає агентів Орди нападати на ложу саме для того, щоб здобути Реєстр Кель'Таласу — важливий історичний документ зі списками й записами ельфійських слідопитів, що досі зберігається в архіві ложі.",al={"чому натанос атакує кель'літієн","наказ лорда-розвідника","реєстр кель'таласу"}},{q="Чим Кель'Літієн відрізняється від Ложі Кель'Даніл?",a="Обидві — давні мисливські ложі високих ельфів, але Кель'Даніл стоїть у безпеці серед дружніх дворфів-Вайлдгаммерів у Пригір'ї. А Кель'Літієн — відрізана від світу на передовій Східних Чумних земель, затиснута між отруєними руїнами й замкненою брамою Кель'Таласу.",al={"кель'даніл проти кель'літієн","порівняння лож нагір'я"}}},fp="18,437,14.727.0,25.568.1,59.298.0,29.255.0,57.224.0,48.234.0,51.277.0"}
P.entries["subzone:rage-scar-hold"] = {n="Твердиня Лютого Шраму",s="Твердиня Лютого Шраму — печера в нетрях Фераласу на материку, неподалік Твердині Перистого Місяця. Вона має лиху славу, бо тут живуть одні з найлютіших єті в краї. Та дивна річ: розкидані книги, символи й сліди архітектури нічних ельфів у глибині печери натякають, що колись, доки її не захопили звірі, вона мала куди мирніше призначення.",h="Твердиня Лютого Шраму — печера в нетрях Фераласу на материку, неподалік Твердині Перистого Місяця.",kw={"твердиня лютого шраму","єті","печера","фералас","калдореї","фоліанти"},ang={["class:Mage"]="Тайнознавчі символи й покинуті фоліанти в лігві звірів породжують тривожні питання: хто ж знайшов свою смерть у глибинах цієї печери?",["race:NightElf"]="Те, що брудні єті паплюжать прадавнє курганне лігво чи святилище, — гірке нагадування про дикі небезпеки, які повертають собі історичні землі калдореїв."},sec={{t="Звірине царство",b="Твердиня Лютого Шраму вгризається в дикі нетрі Фераласу, і панують тут люті єті, що нападають на кожного, хто наблизиться до їхнього лігва. Через них довколишні лісові стежки небезпечні і для вартових Альянсу, і для подорожніх. Єті звичайні для диких закутків Калімдора, але мешканці Твердині Лютого Шраму вирізняються неприхованою агресією та лютістю, з якою боронять свою територію."},{t="Сліди минулого",b="Глибше в темних коридорах печери криються ледь помітні сліди давніших мешканців. Різьблений камінь і архітектура нічних ельфів підказують, що колись тут було курганне лігво друїдів або тайнознавче святилище. Серед бруду й кісток досі лежать забуті фоліанти й містичні знаки, і мандрівникам лишається гадати: чи то нещасних учених вирізали звірі, чи то єті з якоїсь причини тягнуться до магії, яка досі тут жевріє."}},faq={{q="Що таке Твердиня Лютого Шраму?",a="Твердиня Лютого Шраму — система підземних печер у Фераласі, на суходолі неподалік від Твердині Перистого Місяця. Нині її заполонили агресивні здичавілі єті.",al={"твердиня лютого шраму","що це за печера","печера єті фералас"}},{q="Звідки в лігві єті книги й символи?",a="У твердині валяються покинуті фоліанти, сувої й чарівні символи. Навряд чи дикі звірі вміють читати чи вивчають чаклунство — радше ці реліквії свідчать, що колись тут жили нещасні чаклуни чи вчені нічні ельфи, які стали жертвами єті.",al={"чому в лігві єті книги","чи єті вивчають магію","книги лютого шраму"}},{q="Чи цю печеру збудували нічні ельфи?",a="Усередині — кам'яна кладка нічних ельфів і печерні споруди, що нагадують курганне лігво. Живих калдореїв там не лишилося, отже, колишні мешканці або давно покинули це місце, або загинули, коли сюди прийшли єті.",al={"нічноельфійська архітектура","чи лютий шрам курган ельфів","курганне лігво фералас"}},{q="Чи відрізняються тутешні єті від інших у Калімдорі?",a="Місцеві мандрівники вважають єті Твердині Лютого Шраму одними з найлютіших і найагресивніших у Фераласі: свій захоплений підземний дім вони боронять зі звірячою жорстокістю.",al={"єті фераласу","наскільки небезпечні єті","звірі лютого шраму"}}},fp="14,374,16.391.0,18.421.0,23.186.0,50.262.0,37.241.0,53.193.0"}
P.entries["subzone:ragefire-chasm"] = {n="Провалля Лютого Вогню",s="Провалля Лютого Вогню — мережа вулканічних печер просто під столицею Орди Оргріммаром. Вхід до них веде з Тіньової Розколини, а в тунелях, освітлених магмою, ховаються дикі троги й таємна секта Ради Тіней, що прагне розхитати молоду державу орків зсередини.",h="Провалля Лютого Вогню — мережа вулканічних печер просто під столицею Орди Оргріммаром.",kw={"провалля лютого вогню","оргріммар","троги","пекучий клинок","тіньова рада","тараґаман голодний","джерґош призивач","баззалан"},ang={["class:Warlock"]="Присутність Пекучого Клинка та їхніх демонічних господарів показує, що зараза магії Скверни, яку нова Орда Тралла рішуче викорінює, досі не зникла.",["faction:Horde"]="Провалля Лютого Вогню — кричуща загроза безпеці в самому серці столиці, що випробовує відданість молодих шукачів пригод справі захисту юної Орди."},sec={{t="Загроза під вулицями",b="Поки Тралл зміцнює Дуротар на поверхні, просто під підмурками Оргріммара назрівають підземні небезпеки. Провалля Лютого Вогню — хитка мережа вулканічних жерл і магмових рік, яку заполонили люті троги Лютого Вогню. Ці ворожі істоти, що вийшли з незвіданих глибин під тунелями, жорстоко відкинули мирні пропозиції Маґати Ґрімтотем. Якщо їх не зупинити, сама їхня кількість загрожує підточити столицю й захлиснути її."},{t="Пекучий Клинок",b="Значно небезпечніший за трогів Пекучий Клинок — повстанська секта демонічної Ради Тіней, що діє з темряви провалля. Під проводом чорнокнижника Джерґоша Призивача, сатира Баззалана й велетенського вартового Скверни на ім'я Тараґаман Голодний ці культисти виношують задуми знищити Орду Тралла. Хоч Ніру Файрблейд і запевняє, що протистоїть їм, культ активно випробовує сили орків і підточує їхню нову домівку знизу."}},faq={{q="Де вхід до Провалля Лютого Вогню?",a="Вхід — глибоко в Оргріммарі, у Тіньовій Розколині, біля самого намету чорнокнижника Ніру Файрблейда.",al={"де вхід у провалля лютого вогню","як дістатися до провалля лютого вогню","розташування провалля лютого вогню"}},{q="Хто живе в Проваллі Лютого Вогню?",a="Провалля заполонили агресивні троги Лютого Вогню, а ще тут засів Пекучий Клинок — культ, пов'язаний із Радою Тіней. Їх очолюють чорнокнижник Джерґош Призивач, сатир Баззалан і вартовий скверни Тараґаман Голодний.",al={"моби провалля лютого вогню","вороги провалля лютого вогню","хто контролює провалля лютого вогню"}},{q="Чому Тралл не очистив провалля?",a="Сили Орди розпорошені: вона облаштовує Дуротар і обороняється від зовнішніх загроз. Вождь Тралл покладається на вправних героїв, які мають спуститися в печери, знищити ватажків Пекучого Клинка й прорідити трогів, перш ніж ті вирвуться на вулиці міста.",al={"чому тралл дозволяє лютий вогонь","тралл і провалля лютого вогню"}},{q="Чи можуть гравці Альянсу увійти до Провалля Лютого Вогню?",a="Так, але для цього доведеться прокрастися крізь брами Оргріммара й спуститися в пильно охоронювану Тіньову Розколину, тож для шукачів пригод з Альянсу це надзвичайно небезпечна справа.",al={"чи альянс може в провалля лютого вогню","альянс у лютому вогні"}}},fp="14,283,28.459.0,17.450.1,40.128.0,32.235.0,40.270.0,42.200.0"}
P.entries["subzone:ragefire-chasm-classic"] = {n="Провалля Лютого Вогню (класика)",s="Провалля Лютого Вогню — розлога мережа вулканічних тунелів просто під Оргріммаром, до якої можна потрапити крізь тінисті глибини Тіньової Розколини. Хоч ці вогняні печери лежать під суверенною столицею Орди, тут кишать ворожі троги й підступне коло культистів, вірних Раді Тіней.",h="Провалля Лютого Вогню — розлога мережа вулканічних тунелів просто під Оргріммаром, до якої можна потрапити...",kw={"провалля лютого вогню","оргріммар","троги","палючий клинок","рада тіней","підземелля"},ang={["faction:Horde"]="Очищення Провалля Лютого Вогню — справа захисту батьківщини: воно вберігає надра Дуротару від диверсій ізсередини й викорінює посібників демонів.",["race:Tauren"]="Стара Відьма Маґата Ґрімтотем посилала посланців, щоб укласти мир із трогами-загарбниками, та їхня кривава відмова довела: з цими підземними звірами домовитися неможливо."},sec={{t="Приховане лихо",b="Під кам'яними вулицями й укріпленими вежами Оргріммара лежить Провалля Лютого Вогню — підступна мережа підземних печер, сповнених магми. Нещодавно тунелі заполонили дикі троги Лютого Вогню, що вибралися нагору з глибоких підземних розломів. Маґата Ґрімтотем із тауренів намагалася мирно домовитися з цими істотами, але її пропозиції брутально відкинули. Якщо трогів не спинити, вони прокопаються ще глибше в підвалини самого міста."},{t="Пекучий Клинок",b="Значно небезпечніший за безмозких трогів Пекучий Клинок — культ заколотників, підпорядкований демонічній Раді Тіней. Очолювані кремезним стражем скверни Тараґаманом Голодним, орком-чорнокнижником Джерґошем Призивачем і зіпсованим сатиром Баззаланом, ці змовники прагнуть зруйнувати все, що Орда Тралла збудувала в Дуротарі. Замість того щоб негайно очистити печери, Вождь Тралл стежить за їхніми діями, сподіваючись, що їхня дурна самовпевненість викаже їхніх господарів вище в ієрархії Ради Тіней."}},faq={{q="Де вхід до Провалля Лютого Вогню?",a="Портал входу — глибоко в Оргріммарі, у підземному каньйоні, що зветься Тіньовою Розколиною. Він неподалік від намету орка-чорнокнижника Ніру Файрблейда.",al={"де лютий вогонь","вхід у провалля","як дістатися до провалля","розташування провалля лютого вогню"}},{q="Звідки під Оргріммаром троги?",a="Троги вилізли з давніх глибоких печер під Дуротаром просто у вулканічне черево міста. Їхня раптова навала загрожує і спорудам, і мешканцям столиці, а мирно їх стримати неможливо.",al={"чому тут трогги","трогги лютого вогню","трогги оргріммара"}},{q="Чому Тралл дозволяє сектантам жити під столицею?",a="Вождь Тралл добре знає про культ під містом. Замість прямого наступу, через який уся мережа могла б розбігтися, він дозволяє їм діяти під пильним наглядом, сподіваючись, що вони ненароком видадуть, хто справжні ватажки Ради Тіней і де вони ховаються.",al={"чому тралл не чистить провалля","тралл і рада тіней","чому палаючий клинок під оргріммаром"}},{q="Хто очолює сектантів у проваллі?",a="Пекучим Клинком у Проваллі Лютого Вогню командують троє: Тараґаман Голодний — грізний вартовий скверни, Джерґош Призивач — орк-чорнокнижник і Баззалан — підступний сатир.",al={"боси провалля","хто очолює палаючий клинок","лідери провалля лютого вогню"}}},fp="24,324,14.477.0,17.567.1,40.181.0,39.254.0,57.310.0,40.189.0"}
P.entries["subzone:raptor-grounds"] = {n="Угіддя Рапторів",s="Угіддя Рапторів — відлюдна долина серед курних пагорбів південних Пусток, яку захопили раптори Сонцелускі. На відміну від звичайних диких звірів, ця зграя виявляє моторошну кмітливість, уміє користуватися знаряддями й має нестримну пристрасть красти блискучі дрібнички з ближніх поселень.",h="Угіддя Рапторів — відлюдна долина серед курних пагорбів південних Пусток, яку захопили раптори Сонцелускі.",kw={"угіддя рапторів","раптори","Сонцелускі","твердиня північної варти","злодії","пустки"},ang={["class:Hunter"]="Незвичайна кмітливість зграї Сонцелуских, злагодженість у полюванні й уміння будувати прості сховища роблять їх захопливим предметом вивчення для кожного вправного слідопита.",["faction:Horde"]="Раптори Сонцелускі постійно загрожують караванам і заставам Орди на півдні Пусток, тож за них призначають винагороди й споряджають походи, щоб повернути вкрадене."},sec={{t="Дивовижні звірі південних пусток",b="Угіддя Рапторів, що лежать на захід від Твердині Північної Варти, — головна гніздова територія рапторів Сонцелуских. Мандрівники швидко помічають, що ці створіння — далеко не бездумні хижаки: вони виявляють неприродний розум, будують грубі сховища, виготовляють примітивні знаряддя й злагоджено полюють. Гнані невгамовною пристрастю до всього блискучого й незвичного, раптори раз у раз нападають на каравани й табори Орди, тягнучи монети, дрібнички й припаси до своїх лігв у каньйоні."}},faq={{q="Де розташовані Угіддя Рапторів?",a="Угіддя Рапторів — невелика западина-долина на півдні Пусток, серед скелястих пагорбів на захід від Твердині Північної Варти.",al={"розташування угідь рапторів","де угіддя рапторів","угіддя рапторів на мапі"}},{q="Чим тутешні раптори відрізняються від звичайних звірів?",a="Сонцелускі раптори мають неприродно гострий розум. Вони покладаються не лише на звірячий інстинкт: збирають примітивні знаряддя й будують грубі хижі, щоб дати прихисток зграї й сховати крадене.",al={"розум сонцелускових рапторів","чому раптори мають хатини","розумні раптори пустовиськ"}},{q="Чому раптори нападають на каравани й крадуть речі?",a="Зграя має нав'язливу пристрасть до блискучих, мерехтливих чи незвичайних речей. Через це вони влаштовують засідки на мандрівників і грабують поселення Орди, ховаючи вкрадені монети й метал глибоко в своїй долині.",al={"вкрадене срібло рапторів","чому раптори крадуть","раптори й блискучі речі"}},{q="Хто тримає цю долину?",a="Долину не тримає жодна фракція. Це дикі мисливські угіддя й гніздовища сонцелуских рапторів, що люто боронять їх від кожного, хто забреде всередину.",al={"хто володіє угіддями рапторів","чи угіддя рапторів орди"}}},fp="14,278,37.521.0,28.136.0,54.208.0,51.214.0,25.171.0"}
P.entries["subzone:raptor-ridge"] = {n="Кряж Рапторів",s="Кряж Рапторів — високий скелястий простір на сході Багнокраю, на північний захід від укріплених Брам Драконячої Пащі. Це головні мисливські угіддя й гніздовища зграй лютих рапторів-Гостропащих, над якими в глибині печер панує особливо люта матріарха.",h="Кряж Рапторів — високий скелястий простір на сході Багнокраю, на північний захід від укріплених Брам...",kw={"кряж рапторів","гостропащі","матріарх гостропащих","раптори","брами драконячої пащі","багнокрай"},ang={["class:Hunter"]="Люті раптори-Гостропащі з кряжа — сильні, агресивні звірі для кожного мисливця, що шукає прудкого й чіпкого болотяного супутника."},sec={{t="Лігво хижаків",b="Здіймаючись над мокрими болотами східного Багнокраю, Кряж Рапторів — одна з найнебезпечніших диких місцин краю. Люті раптори-Гостропащі великими зграями нишпорять його кручами й скелястими стежками, тож мандрувати біля підніжжя гір Каз Модану небезпечно. У серці кряжа лежить похмура печера, де панує Матріарх Гостропащих, чий лютий виводок запекло боронить гнізда від будь-яких хижаків чи нерозважливих мандрівників, що підійдуть надто близько до Брам Драконячої Пащі."}},faq={{q="Де розташований Кряж Рапторів?",a="Кряж Рапторів лежить на далекому сході Багнокраю, просто на північний захід від Брам Драконячої Пащі, що стережуть дорогу вгору до Ґрім Батола.",al={"розташування кряжа рапторів","де кряж рапторів","як дістатися до кряжа рапторів"}},{q="Хто тут живе?",a="На кряжі аж кишать раптори-Гостропащі. А глибоко в печері мандрівники натраплять на Матріарха Гостропащих, що стереже свої гнізда й пташенят.",al={"які моби на кряжі рапторів","раптори багнокраю","звірі кряжа рапторів"}},{q="Хто така Матріарх Гостропащих?",a="Матріарх Гостропащих — величезна смертоносна ватажка місцевих зграй рапторів, що висиджує свою кладку в центральній печері кряжа.",al={"гостропащ матріарх","матріарх рапторів багнокраю","бос рапторів багнокраю"}},{q="Чому цю місцевість так небезпечно перетинати?",a="Окрім щільних зграй агресивних, швидких рапторів, що гуртом накидаються на зайд, кряж лежить у самій тіні ворожих володінь орків Драконячої Пащі біля гірських перевалів.",al={"чи небезпечний кряж рапторів","загроза кряжа рапторів"}}},fp="12,284,18.515.0,30.145.0,25.151.0,30.137.0,41.177.0"}
P.entries["subzone:ratchet"] = {n="Раджет",s="Раджет — гамірне нейтральне портове містечко картелю Стімвідл на східному узбережжі Пусток. Його заснував головний інженер Ґазлоу після того, як допоміг збудувати Оргріммар, і тепер це головний морський торговий вузол, що з'єднує центральний Калімдор зі Східними Королівствами.",h="Раджет — гамірне нейтральне портове містечко картелю Стімвідл на східному узбережжі Пусток.",kw={"раджет","порт","картель стімвідл","ґазлоу","чорнокнижники","пустки"},ang={["class:Warlock"]="Вежа на кручах над Раджетом — важливе місце вишколу, де чорнокнижники будь-якого походження збираються під проводом Страгада Фарсана й Менари Войдрендер, щоб опанувати складні демонічні виклики.",["faction:Alliance"]="Раджет дає шукачам пригод з Альянсу рідкісну безпечну пристань серед ворожих земель центральних Пусток — з кораблем і повітряним сполученням."},sec={{t="Перехрестя Великого Моря",b="Раджет, що стоїть на посушливому узбережжі між Дуротаром і Багном Пилоброду, дає безпечну гавань кожному, хто має гроші. Заснований заповзятливим інженером Ґазлоу після Третьої війни, порт виріс із контрабандистів, вигнанців і сміливих торговців, що прагнули поживитися на прикордонні Калімдору. Він діє під прапором картелю Стімвідл і суворо тримає нейтралітет між Ордою та Альянсом. Кораблі на кшталт «Мрії Діви» регулярно ходять через Велике Море до Буті Бей, перевозячи товари, найманців і сировину між континентами. Місцеві вишибали пильно стежать за доками й нещадно лупцюють кожного, хто має дурість почати бійку й завадити торгівлі."},{t="Тіні над доками",b="Хоч зовні Раджет — галасливе торгове містечко з доками, тавернами й майстернями, тут крутяться й темніші справи. Над гаванню, на пагорбах, стоїть відлюдна вежа, де відкрито збирається гурток чорнокнижників, серед яких — Страгад Фарсан і Менара Войдрендер. Поки містяни й моряки клопочуться вантажними відомостями та гоблінською інженерією, адепти темних мистецтв безперешкодно сходяться тут для єднання з демонічними силами, не зважаючи на моральні обмеження, які діють у традиційних столицях фракцій."}},faq={{q="Хто править Раджетом?",a="Раджетом керує Головний Інженер Ґазлоу від імені нейтрального картелю Стімвідл. Ґазлоу заснував містечко невдовзі після того, як Вождь Тралл щедро заплатив йому за керівництво будівництвом Оргріммара.",al={"лідер раджета","хто керує раджетом","ґазлоу раджет"}},{q="Чи можуть гравці Альянсу безпечно відвідати Раджет?",a="Так. Раджет — нейтральний гоблінський порт. Доки ви не ворогуєте з картелем Стімвідл і ні на кого не нападаєте в межах міста, і мандрівники Альянсу, і мандрівники Орди можуть користуватися корчмою, банком, крамарями, польотами й поромом.",al={"чи безпечний раджет для альянсу","альянс у раджеті","чи може альянс у раджет"}},{q="Куди ходить корабель із Раджета?",a="Судно біля південного причалу, «Примха Діви», ходить через Велике Море до Буті Бею на південному краю Долини Стренглторну. Це один із головних морських шляхів між Калімдором і Східними Королівствами.",al={"куди пливе човен із раджета","човен раджета","човен до східних королівств"}},{q="Чому в пагорбах над містечком живуть чорнокнижники?",a="У вежі над Раджетом живе ковен чорнокнижників на чолі з такими постатями, як Страгад Фарсан і Менара Войдрендер. Картелеві Стімвідл байдуже до темної магії, тож ці чаклуни можуть безперешкодно діяти, навчати учнів і скорювати демонів без утручання церковної чи світської влади.",al={"чорнокнижники раджета","вежа страхада фарсана","вежа чорнокнижників раджета"}},{q="Що буде, якщо я почну бійку в Раджеті?",a="Громили Раджета негайно втрутяться й накинуться на призвідника з важкими кийками й сітками. Зривати торгівлю в гоблінських поселеннях суворо заборонено, тож бійка тут швидко зіпсує вашу репутацію в картелі Стімвідл.",al={"вартові раджета","напад на гравців у раджеті","бійці раджета"}}},fp="7,272,31.707.0,23.547.0,18.248.0,42.248.0,34.239.0,51.291.0,43.248.0"}
P.entries["subzone:ravaged-caravan"] = {n="Сплюндрований Караван",s="Сплюндрований Караван — димуче згарище на північно-східному березі Озера Кам'яного Бика в Малгорі. Колись це була валка з припасами для копалень Наглядача Фіззпрокета, та її перехопили й знищили місцеві таурени, сповнені рішучості покласти край гоблінському визиску їхньої батьківщини.",h="Сплюндрований Караван — димуче згарище на північно-східному березі Озера Кам'яного Бика в Малгорі.",kw={"сплюндрований караван","озеро кам'яного бика","венчурна компанія","фіззпрокет","гобліни","малгор"},ang={["class:Druid"]="Чорний дим, що душить берег Озера Кам'яного Бика, — суворе нагадування про безоглядну шкоду, якої гоблінські машини завдають природній рівновазі.",["race:Tauren"]="Обвуглені вози — це негайна й рішуча відмова вашого народу дозволити чужинським промисловим синдикатам плюндрувати священні пасовища Малгору."},sec={{t="Дим над Озером Кам'яного Бика",b="Сплюндрований Караван на пагорбі над Озером Кам'яного Бика — свідчення ранньої сутички між тауренами Села Бладгуф і Венчурною Компанією, що насувалася на край. Валка везла шахтарське спорядження, креслення й обладнання на розкопки Наглядача Фіззпрокета, але тауренські захисники відрізали її й розтрощили, перш ніж вона дісталася мети. Попри розгром, уперті вцілілі з Венчурної Компанії досі чіпляються за розбиті вози й тліючі ящики, ревно стережучи рештки вантажу."}},faq={{q="Що сталося з цим караваном?",a="Караван перехопили й розгромили місцеві таурени, помітивши, що Венчурна Компанія просувається вглиб Малгору. Щоб не дати гоблінам спустошити землю, таурени знищили обоз, перш ніж вантаж дістався сусідньої шахти.",al={"чому караван спалено","що тут сталося","історія сплюндрованого каравана"}},{q="Кому належать розбиті вози?",a="Караван належить Венчурній Компанії — безсоромному гоблінському гірничому консорціуму, що намагається без дозволу почати видобуток у пагорбах Малгору.",al={"чий це караван","чиї розбиті вози","караван венчурної компанії"}},{q="Куди прямував караван?",a="Він віз інструменти, машини й припаси на північ, до Наглядача Фіззпрокета, що керує відкритим видобутком Венчурної Компанії в Шахті Венчурної Компанії.",al={"куди йшов караван","мета каравана","постачання фізспрокета"}},{q="Чому біля уламків досі тиняються робітники Венчурної Компанії?",a="Уцілілі наймити й робітники Венчурної Компанії люто бережуть майно компанії. Замість того щоб змиритися з утратою, вони засіли довкола обвуглених возів і намагаються врятувати бодай рештки свого спорядження.",al={"чому гобліни ще тут","вцілілі венчур ко","хто охороняє уламки"}}},fp="15,284,25.507.0,30.244.0,28.156.0,30.162.0,63.237.0"}
P.entries["subzone:ravaged-twilight-camp"] = {n="Сплюндрований Сутінковий Табір",s="Сплюндрований Сутінковий Табір лежить у руїнах серед височенних мінеральних утворень у відлюдній Кришталевій Долині на північному заході Силітусу. Це відокремлений прихисток дивакуватого відлюдника Верховного Лорда Демітріана, відданого слуги Шукача Вітру.",h="Сплюндрований Сутінковий Табір лежить у руїнах серед височенних мінеральних утворень у відлюдній Кришталевій...",kw={"сплюндрований сутінковий табір","демітріан","кришталева долина","молот присмерку","шукач вітру","громолють"},ang={["class:Paladin"]="Ті, хто шукає легендарну стихійну зброю давнини, мусять знайти Демітріана в Кришталевій Долині, щоб розгадати таємницю посудини принца Тандераана.",["class:Warrior"]="Кожен воїн, що йде за чутками про легендарний клинок Громолють, Благословенний Клинок Шукача Вітру, рано чи пізно опиниться біля Верховного Лорда Демітріана в цьому покинутому таборі."},sec={{t="Руїни відлюдника в долині",b="Хоча Молот Присмерку тримає чимало діючих застав у пісках Силітусу, цей зруйнований табір у Кришталевій Долині розповідає іншу історію. Далеко від головних фортець культу табір здебільшого лежить у руїнах і стоїть порожній — лишився тут тільки Верховний Лорд Демітріан. Слуга Тандераана, Демітріан тиняється серед каміння, наче ієрархія Молота Присмерку його покинула чи він сам від неї відсторонився, і похмуро розмірковує над стихійними путами й утраченою силою Шукача Вітру."}},faq={{q="Що таке Сплюндрований Сутінковий Табір?",a="Це розбита, зруйнована застава в Кришталевій Долині на північному заході Силітусу, відома тим, що тут живе Верховний Лорд Демітріан.",al={"сплюндрований сутінковий табір","зруйнований сутінковий табір силітус","табір кришталевої долини"}},{q="Хто тут живе?",a="Єдиний помітний мешканець — Верховний Лорд Демітріан, самітник, глибоко пов'язаний зі знаннями про стихії й з кайданами принца Тандераана.",al={"хто в сплюндрованому сутінковому таборі","де верховний лорд демітріан","нпс табору"}},{q="Чому табір зруйновано?",a="Записи культу згадують, що табір лежить у руїнах, але Демітріан лишається серед уламків, відрізаний від решти Молота Присмерку, що діє в Силітусі.",al={"чому табір зруйновано","що знищило табір","хто напав на табір"}},{q="Чи ворожий тут Молот Присмерку?",a="На відміну від гамірних сутінкових таборів на півдні й у центрі Силітусу, тут немає агресивних патрулів культу, тож Демітріан може спокійно віддаватися похмурим думам.",al={"чи молот присмерку тут ворожий","чи нападають культисти"}}},fp="21,246,27.486.0,34.146.0,15.135.0,23.159.0,38.150.0"}
P.entries["subzone:raven-hill"] = {n="Воронячий Пагорб",s="Воронячий Пагорб — спустошене, зруйноване село на заході Сутінколісся, що лежить у довгій тіні величезного Цвинтаря Воронячого Пагорба. Колись жваве людське поселення, тепер воно покинуте всіма, крім жменьки наляканих захожих і невидимих духів.",h="Воронячий Пагорб — спустошене, зруйноване село на заході Сутінколісся, що лежить у довгій тіні величезного...",kw={"воронячий пагорб","село","незримі","тремтій","блізтік","сутінколісся"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що переходять міст із Вестфолу, Воронячий Пагорб — зловісне привітання від кошмару, що поглинає західне Сутінколісся.",["race:Human"]="Напіврозвалені хатини — похмуре нагадування про те, скільки земель Королівство Стормвінд утратило через повзучу темряву й занедбання."},sec={{t="Місто, яке поглинула пітьма",b="Воронячий Пагорб, що стоїть при західному шляху Сутінколісся трохи на північ від Хутора Аддла, — сумна тінь самого себе. Коли темна магія й жахи нежиті прокотилися краєм Великого Селища, живі подалися на схід, до Даркшира, або взагалі покинули ці землі. Нині дерев'яні хати гниють у вічному мороці, і мандрівники обходять їх стороною, боячись і неспокійних мерців, що сходять із сусіднього цвинтаря, і невидимих Незримих, що чаяться між руїнами стін."},{t="Ті, хто лишився",b="Попри похмуру славу, Воронячий Пагорб не зовсім безлюдний. Серед покинутих будівель ховається шукач пригод на ім'я Тремтій — нервовий уламок людини, нажаханий жахами, які сам колись допоміг випустити через власну цікавість. Вище, на одному з напіврозвалених горищ, підприємливий гоблін Блізтік ледве зводить кінці з кінцями, продаючи припаси обережним перехожим. Вони ділять руїни з невидимими духами, відомими як Незримі, і живуть у позиченому часі на краю розлогого кладовища."}},faq={{q="Чому Воронячий Пагорб покинуто?",a="Воронячий Пагорб покинули, коли на Сутінколісся впала тінь, принісши жахіття нежиті, темну магію й хижих звірів. Містечко стояло поряд із величезним Цвинтарем Воронячого Пагорба, тож боронити його було особливо важко, і вцілілі мешканці втекли на схід, до укріпленого Даркширу.",al={"що сталося з воронячим пагорбом","чому воронячий пагорб зруйнований","хто жив на воронячому пагорбі"}},{q="Хто ж насправді живе тепер у селі?",a="Тут живуть лише кілька сміливців чи відчайдухів. Наляканий до смерті чоловік на прізвисько Тремтій ховається серед зруйнованих підмурків, мучений провиною й страхом, а гоблін-крамар Блізтік торгує на верхньому поверсі з усіма, кому вистачить духу обшукувати покинуті будинки.",al={"хто в воронячому пагорбі","нпс воронячого пагорба","живі люди воронячого пагорба"}},{q="Хто такі Незримі, що блукають Воронячим Пагорбом?",a="Незримі — невидимі ворожі духи, що блукають Воронячим Пагорбом і сусіднім цвинтарем. Звичайним оком їх не побачиш, тож вони становлять раптову й смертельну загрозу для необачного мандрівника, що досліджує спорожніле містечко.",al={"незримі воронячого пагорба","невидимі монстри воронячого пагорба","привиди воронячого пагорба"}},{q="Куди веде дорога крізь Воронячий Пагорб?",a="Дорога повз Воронячий Пагорб веде на захід — до річкового мосту у Вестфол, на південь — до Хутора Аддла й кордону Долини Стренглторну, а на схід — через серце Сутінколісся до Даркширу.",al={"дорога воронячого пагорба","куди веде дорога","подорож воронячим пагорбом"}}},fp="10,238,23.498.0,18.499.0,28.305.0,38.275.0,40.236.0,44.215.0"}
P.entries["subzone:raven-hill-cemetery"] = {n="Цвинтар Воронячого Пагорба",s="Цвинтар Воронячого Пагорба — величезне прокляте кладовище, що розкинулося на заході Сутінколісся. Колись тихе місце поховань для місцевих сіл, тепер воно заполонене ордами ходячих мерців, падложерних самітників і безжальних грабіжників могил.",h="Цвинтар Воронячого Пагорба — величезне прокляте кладовище, що розкинулося на заході Сутінколісся.",kw={"цвинтар воронячого пагорба","цвинтар","нежить","мор'ладім","морбент фел","сутінколісся"},ang={["class:Paladin"]="Невпинна скверна й осквернені могили Цвинтаря Воронячого Пагорба волають про святе освячення.",["class:Priest"]="На цвинтарі зосереджено потужні потоки тіньової сили й застиглої скорботи — це гірка наука про трагедію душ, яким не дано відійти до Світла."},sec={{t="Сад неспокійних мерців",b="Доки темрява не поглинула Світанковий Ліс, Цвинтар Воронячого Пагорба був головним місцем спочинку для довколишніх поселень. Коли на край упало темне чаклунство, мерці перестали лежати в могилах. Скелети, гулі й шкандибаючі жахіття вигрібалися з-під землі, розширюючи похмурі межі цвинтаря. Нині це одна з найнебезпечніших виразок Сутінколісся. Тут никають не лише гнилі потвори й велетенські павуки, а й зневірені грабіжники могил, що прагнуть безкарно сплюндрувати родові склепи, поки місцева влада безсила."},{t="Неспокійні духи й темні сили",b="Трагедію цвинтаря втілює Мор'Ладім — безтямне скелетне жахіття, на яке перетворився полеглий лицар Морган Ладімор: позбавивши себе життя в божевіллі й скорботі, він тепер без кінця обходить надгробки. Далі на північ, на схилах Покинутого Ряду, темний некромант Морбент Фел черпає мерзенну силу могил, щоб піднімати й підкоряти собі легіони нежиті. А ще ближче до північно-східного краю стоїть самотня халупа відлюдника Аберкромбі, що стежить за цвинтарем з-за туману."}},faq={{q="Чому на Цвинтарі Воронячого Пагорба повстає стільки нежиті?",a="Коли Сутінколісся охопила скверна, цвинтар потрапив під владу темної сили, і некромантична міць просочилася в землю. Мерзенний маг Морбент Фел, що засів на Покинутому Ряду на краю цвинтаря, спрямовує цю силу, щоб піднімати мерців із могил і керувати ними.",al={"чому тут стільки зомбі","чому воронячий пагорб з привидами","хто підняв мертвих"}},{q="Хто такий Мор'Ладім?",a="Мор'Ладім — смертоносний кістяк-ревенант, що обходить цвинтар і нападає на мандрівників. Хто він і яке його минуле, з'ясовується під час розслідування в Даркширі.",al={"мор'ладім","скелет на цвинтарі","морґан ладімор"}},{q="Де на цвинтарі Морбент Фел?",a="Морбент Фел живе на пагорбі, що зветься Покинутим Рядом, у північно-західному куті Цвинтаря Воронячого Пагорба. Він засів у старій хаті над надгробками й звідти керує довколишньою нежиттю.",al={"де морбент фел","розташування морбента фела","покинутий ряд"}},{q="Хто той самітник, що живе на краю цвинтаря?",a="Самітник — Аберкромбі, дивакуватий кволий дідуган, що живе в розваленій хатині біля північно-східного краю цвинтаря. Він часто просить заїжджих мандрівників зібрати дивні складники для його моторошних власних задумів.",al={"самітник воронячого пагорба","аберкромбі","халупа воронячого пагорба"}}},fp="19,251,29.579.0,32.497.1,53.274.0,17.161.1,45.206.0,53.252.0"}
P.entries["subzone:ravencrest-monument"] = {n="Монумент Рейвенкреста",s="Монумент Рейвенкреста, що стоїть на обвітрених кручах південної Азшари, — розбиті рештки прадавнього колоса нічних ельфів. Колись ця велетенська статуя-пам'ятник височіла над Великим Морем, але давно розвалилася: лишилися тільки високі ноги й розкидані кам'яні руїни, якими тепер никають ворожі наги Злобного Батога.",h="Монумент Рейвенкреста, що стоїть на обвітрених кручах південної Азшари, — розбиті рештки прадавнього колоса...",kw={"монумент рейвенкреста","кур'талос рейвенкрест","війна прадавніх","колос","наги","злобний батіг","азшара"},ang={["class:Warrior"]="Ім'я Рейвенкрест має міфічну вагу серед воєначальників: Кур'талос Рейвенкрест був найвизначнішим полководцем смертних у часи катастрофічного вторгнення Палаючого Легіону.",["race:NightElf"]="Для нічних ельфів монумент — тверезе нагадування про прадавню імперію калдореїв і шляхетний рід Рейвенкрестів, чий героїчний опір у Війні Прадавніх урятував Азерот від демонічного знищення."},sec={{t="Руїни колоса",b="Монумент Рейвенкреста, що здіймається високо над морем на південний схід від Руїн Елдарата, колись був вражаючим дивом кам'яного мистецтва калдореїв. Нині від величного колоса лишилася хіба пара велетенських розбитих ніг, що вросли в кам'яний постамент, а уламки тулуба й голови або поховані в землі на кручі, або зникли під хвилями внизу. Щоб дістатися цього віддаленого прибережного мису, доведеться йти суходолом через мости Азшари: стрімкі скелясті урвища не дають підійти з моря."},{t="Забута спадщина",b="Учені часто припускають, що монумент вшановує лорда Кур'талоса Рейвенкреста — славетного шляхтича, що згуртував і повів військо нічних ельфів у Війні Прадавніх після падіння Зін-Азшарі. Однак близькість до міста Елдарат, що існувало ще до Розколу, і невиразна кам'яна різьба, яка вціліла, не дають дійти згоди щодо справжнього походження монумента. Тепер довколишню кручу захопили не прочани й не ельфійські доглядачі, а зміїсті наги Злобного Батога, що люто боронять повалений монумент."}},faq={{q="Що таке Монумент Рейвенкреста?",a="Це зруйнований постамент велетенської статуї нічних ельфів на прибережному мисі на півдні Азшари. Досі стоять лише її величезні кам'яні ноги, а решта скульптури лежить розбита й розкидана по вершині скелі.",al={"статуя рейвенкреста","що це за статуя","гігантські ноги ашара"}},{q="На честь кого збудовано монумент?",a="Він носить ім'я дому Рейвенкрест, найвідомішим представником якого був лорд Кур'талос Рейвенкрест — шляхетний полководець, що очолив опір смертних Палаючому Легіону у Війні Прадавніх. Проте монумент стоїть біля давніх руїн Елдарата, тож неясно, чи вшановує він саме Кур'талоса, чи якогось давнішого предка з часів до Великого Розколу.",al={"хто такий рейвенкрест","чия це статуя","куртал рейвенкрест"}},{q="Як дістатися до монумента?",a="З моря на монумент не піднятися й до нього не потрапити — заважають прямовисні скелі. Мандрівникам доведеться йти суходолом через південь Азшари, перетинаючи кам'яні мости біля Руїн Елдарата, щоб дістатися мису.",al={"як дістатися до монумента рейвенкреста","шлях до рейвенкреста","доступ до рейвенкреста"}},{q="Хто живе біля монумента сьогодні?",a="Вершину скелі й довколишні тераси заполонили наги Злобного Батога, тож досліджувати давні руїни самотньому мандрівникові небезпечно.",al={"що тут живе","вороги монумента","наги ашара"}}},fp="19,325,19.535.0,18.527.0,32.240.0,36.358.0,30.213.0,42.152.0"}
P.entries["subzone:ravenholdt-manor"] = {n="Маєток Рейвенголдт",s="Маєток Рейвенголдт, що сховався високо в горах над Передгір'ям Гілсбреда, — відлюдна штаб-квартира гільдії злодіїв і вбивць, відомої як Рейвенголдт. Під наглядом Лорда Джораха Рейвенголдта маєток дає потайний прихисток, де майстри скритності гострять своє ремесло далеко від очей влади.",h="Маєток Рейвенголдт, що сховався високо в горах над Передгір'ям Гілсбреда, — відлюдна штаб-квартира гільдії...",kw={"маєток рейвенголдт","лорд джорах рейвенголдт","розбійники","синдикат","гори альтерак","гілсбред"},ang={["class:Rogue"]="Маєток Рейвенголдт — найкращий прихисток для вашого ремесла: тут на вас чекають суворі випробування, особливий вишкіл і розгалужена мережа таємних зв'язків.",["profession:Engineering"]="Вибагливі інженери пробираються гірським перевалом саме для того, щоб придбати з припасів маєтку рідкісне креслення Гномського Пристрою Невидимості."},sec={{t="Прихисток у тінях",b="Маєток Рейвенголдт, захований за вузьким гірським перевалом і звивистою печерою на північний захід від Твердині Дурнгольд, стоїть відокремлено на прикордонні Гір Альтерак. Маєток належить Лордові Джораху Рейвенголдту — вельможі, що тримає дисципліноване товариство розбійників, убивць і розвідників. На його землях є тихий сад і тренувальна арена просто неба під наглядом майстрів бою на кшталт Майстра Канґа — дисципліноване місце, щоб відпрацьовувати зламування замків, виготовлення отрут і ближній бій. Хоч маєток радо приймає тих, хто має хист до таємних справ, незграбних чужинців і непроханих гостей пильна варта зустрічає холодною підозрою."},{t="Запекла ворожнеча в передгір'ї",b="До Першої війни земля довкола маєтку належала королівству Альтерак — про це нагадує обвітрена помаранчева черепиця на даху. У бурхливих наслідках загибелі Альтерака занепалі вельможі Синдикату прагнули підкорити собі край, що поставило їх у пряме протистояння з Рейвенголдтом. Рейвенголдт підтримує непросту співпрацю з розвідкою Стормвінда SI:7, діючи разом там, де інтереси збігаються, щоб викорінювати вплив Синдикату на довколишньому нагір'ї. Для послідовників Джораха кожна сутичка в Гілсбреді й Альтераку — частина тихої війни за збереження свого незалежного прихистку."}},faq={{q="Як дістатися до Маєтку Рейвенголдт?",a="Щоб дістатися до маєтку, вирушайте на плато на північний захід від Твердині Дурнгольд у Передгір'ї Гілсбреда. Там, де плато сходиться з північними горами, непримітна ґрунтова стежка в'ється вгору й проходить крізь приховану печеру, виводячи просто на угіддя маєтку.",al={"де маєток рейвенголдт","як дістатися до рейвенголдту","шлях до рейвенголдту"}},{q="Кому належить Маєток Рейвенголдт?",a="Маєток належить лордові Джораху Рейвенголдту, який очолює добірне братство злодіїв і вбивць, відоме просто як Рейвенголдт. Серед розбійників по всьому Азероту він має глибоку повагу.",al={"хто керує рейвенголдтом","лорд рейвенголдт","власник маєтку"}},{q="Чому Рейвенголдт ненавидить Синдикат?",a="Обидва угруповання виводять своє коріння з розтрощених земель Альтераку. Та якщо позбавлені маєтностей вельможі Синдикату вдаються до розбою й беззаконня по всіх пагорбах, то Рейвенголдт тримається суворої дисципліни й діяльно зриває задуми Синдикату.",al={"рейвенголдт проти синдикату","ворожнеча з синдикатом","чому воювати з синдикатом"}},{q="Чи може будь-хто відвідати маєток?",a="Фізично на угіддя може зайти будь-який мандрівник, але вартові й убивці, що там стоять, розмовляють із чужинцями відверто вороже. Розбійників і перевірених агентів тут тепло приймають і ґрунтовно навчають, а решта чує крижані застороги забиратися геть.",al={"чи може будь-хто в рейвенголдт","чи пускають сторонніх у рейвенголдт"}}},fp="16,328,26.687.0,30.623.0,34.259.0,26.187.0,39.256.0,27.259.0"}
P.entries["subzone:raynewood-retreat"] = {n="Притулок Рейнвуд",s="Притулок Рейнвуд — давня застава нічних ельфів довкола величезного великого дерева в північно-центральному Ашенвалі. Під охороною дріад і кенарійських захисників вона пильно стежить за північними перевалами до оскверненого Сквернолісся. Тут же живе Хранитель Орданус — старший син Кенарія, на якого полюють зловісні чужі сили.",h="Притулок Рейнвуд — давня застава нічних ельфів довкола величезного великого дерева в північно-центральному...",kw={"притулок рейнвуд","хранитель орданус","кенарій","велике дерево","брейлін файргенд","ашенваль"},ang={["class:Druid"]="Притулок Рейнвуд — свята земля під опікою дітей Кенарія, оплот проти демонічної скверни.",["faction:Horde"]="Для Орди притулок — дружній до Альянсу гай, чийого охоронця, Хранителя Ордануса, таємні замовники доручають знищити."},sec={{t="Оплот великого дерева",b="Тисячоліття тому, під час давньої Війни Сатирів, задовго до нинішніх чвар між Альянсом і Ордою, Притулок Рейнвуд був військовим плацдармом для захисників-нічних ельфів. Табір і досі зберігає своє священне бойове призначення. Застава, що лежить між місячним колодязем Шаель'дрін і заполоненими сатирами руїнами Нічного Потоку, перебуває під пильною охороною кенарійських захисників, дракончиків-фей і Сестер-реготух. Разом вони невсипуще стежать за скверною, що сповзає зі Сквернолісся просто з півночі."},{t="Полювання на Ордануса",b="Високо у віттях великого дерева живе Хранитель Орданус, один зі старших синів Кенарія. Крони дають йому притулок, але водночас стали осередком темних інтриг. Агенти, пов'язані з таємничими рештками Ради Тіней, — зокрема Брейлін Файргенд — прагнуть смерті хранителя. Найманців Орди посилають штурмувати висоти й принести його голову, тож мирне лісове святилище обертається полем бою."}},faq={{q="Що таке Притулок Рейнвуд?",a="Притулок Рейнвуд — поселення нічних ельфів і Кола Кенарія довкола Великого Дерева на півночі центрального Ашенвалю. Це прихисток, прихильний до Альянсу, і сторожовий пост, що пильнує підступи до Сквернолісся.",al={"притулок рейнвуд","що це за місце","дерево рейнвуд"}},{q="Хто живе в Притулку Рейнвуд?",a="Заставу боронять захисники Кенарія, дріади, відомі як Реготливі Сестри, і феєчні дракони. Найвідоміший мешканець — Хранитель Орданус, що живе високо у Великому Дереві.",al={"хто тут","моби рейнвуду","хто охороняє рейнвуд"}},{q="Хто такий Хранитель Орданус?",a="Хранитель Орданус — могутній хранитель гаю й один зі старших синів напівбога Кенарія. Він опікується прихистком, але на нього полюють ворожі лазутчики.",al={"хранитель орданус","хто такий орданус","орданус історія"}},{q="Чому Орда нападає на Притулок Рейнвуд?",a="Брейлін Файргенд наймає шукачів пригод з Орди, щоб ті пробралися в дерево й розшукали Хранителя Ордануса. Її справжні наміри й вірність розкриваються під час завдання.",al={"завдання орди рейнвуд","чому вбивати орданус","завдання брейлін вогнерук"}},{q="Яка історія цього місця?",a="Майже десять тисяч років тому, під час Війни Сатирів, військо нічних ельфів використовувало Притулок Рейнвуд як оперативну базу для боротьби з демонічними сатирами, що загрожували Калімдору.",al={"історія рейнвуду","війна сатирів рейнвуд"}}},fp="17,353,25.538.0,20.442.1,26.206.0,31.187.0,22.176.0,44.149.0,34.189.0"}
P.entries["subzone:razor-hill"] = {n="Гострий Пагорб",s="Гострий Пагорб — головне поселення Орди в центральному Дуротарі, що лежить на стратегічному перехресті між Долиною Випробувань, Пустками та Оргріммаром. Збудоване довкола помітних укріплених казарм, воно є плацдармом і навчальним осередком для молодих воїнів з орків і тролів, які випробовують себе в суворій глушині.",h="Гострий Пагорб — головне поселення Орди в центральному Дуротарі, що лежить на стратегічному перехресті між...",kw={"гострий пагорб","поселення","казарми","орки","перехрестя","дуротар","орда"},ang={["faction:Horde"]="Як перше справжнє містечко на шляху після тренувальних угідь, Гострий Пагорб — стартовий майданчик для молодих солдатів Орди, що доводять вірність новій державі Тралла.",["race:Orc"]="Гострий Пагорб — свідчення нового життя, яке орки вирвали собі в Дуротарі, проміняв демонічне рабство на міцні землянки й тяжко здобуте виживання."},sec={{t="Серце Дуротару",b="Збудований на важливому географічному вузлі, Гострий Пагорб сполучає північний Дуротар із прибережними поселеннями на півдні та розлогими рівнинами Пусток за Річкою Південної Люті. Поселення, над яким височіють казарми з каменю та дерева й класичні орківські землянки, заклали ще на зорі заснування Дуротару. Невдовзі після Третьої війни людські війська з Кул Тірасу заманили Орду в засідку саме тут під виглядом зустрічі посланців — напад зірвався, бо замість Тралла пішов Рекссар. Нині застава повністю укріплена проти нових вторгнень із узбережжя."},{t="Варта на порубіжжі",b="Під командуванням бувалих офіцерів, як-от Ґар'Ток, Гострий Пагорб координує місцеву оборону проти кількох навислих загроз. Рештки людської морської піхоти досі утримують Фортецю Тіраґард на східному узбережжі, а войовничі племена шипогривів і гарпій дошкуляють місцевим шляхам постачання. Значно підступніша присутність культу Палаючого Клинка, чиї потаємні обряди та осквернені агенти в сусідніх скелях пильно вистежують і викорінюють слідчі на кшталт Орґніла Соулскара."}},faq={{q="Яку роль відіграє Гострий Пагорб у Дуротарі?",a="Гострий Пагорб — головна адміністративна й оборонна застава в центрі Дуротару. Він сполучає південне узбережжя й Долину Випробувань з Оргріммаром на півночі й Пустками на заході, а ще забезпечує припасами й навчає юних шукачів пригод.",al={"чому гострий пагорб тут","призначення гострого пагорба","що таке гострий пагорб"}},{q="Що сталося тут під час навали Кул Тірасу?",a="Після Третьої війни сили, вірні Кул Тірасу, запропонували Вождеві Траллу мирні перемовини на Гострому Пагорбі. Запідозривши зраду, замість Тралла туди пішов герой Рекссар — він викрив засідку й переміг людей-убивць.",al={"засідка кул тірас","рекскар гострий пагорб","що сталося на вершині гострого пагорба"}},{q="Хто командує поселенням?",a="Гарнізоном поселення командує орк-ветеран Ґар'Ток із міських казарм: він керує патрулями проти решток людей і місцевих диких звірів.",al={"лідер гострого пагорба","хто керує гострим пагорбом","ґар'ток"}},{q="Що робить Палаючий Клинок біля Гострого Пагорба?",a="Цей похмурий демонічний культ пробрався в приховані кручі й каньйони центрального Дуротару. Розвідники Орди під проводом Орґніла Соулскара діють із Гострого Пагорба, щоб викрити їхні ковени й знищити їхній вплив.",al={"палаючий клинок дуротар","оргніл душошрам","культисти біля гострого пагорба"}}},fp="10,337,16.588.0,21.469.0,40.259.0,49.233.0,28.164.0,48.210.0"}
P.entries["subzone:razor-hill-watchtower"] = {n="Сторожова вежа Гострого Пагорба",s="Ця міцна застава на червоних кам'яних кручах над Гострим Пагорбом служить постом раннього попередження для серця Дуротару. Фурл Скорнброу пильно стежить за запиленими рівнинами й узбережжям, оберігаючи поселення внизу від загроз, що насуваються.",h="Ця міцна застава на червоних кам'яних кручах над Гострим Пагорбом служить постом раннього попередження для...",kw={"сторожова вежа гострого пагорба","вежа","дозор","фурл скорнброу","гострий пагорб","дуротар"},ang={["class:Hunter"]="Висока точка дає безперешкодний огляд навколишніх скель — ідеально для спостерігачів, що вистежують здобич і пересування звірів по Дуротару.",["faction:Horde"]="Для молодих воїнів і розвідників, що виходять із Долини Випробувань, сторожова вежа — підбадьорливий орієнтир, який свідчить про безпеку й силу молодої Орди."},sec={{t="Очі над Дуротаром",b="Збудована з грубого дерева й залізного каркаса, Сторожова вежа Гострого Пагорба охороняє поселення Гострий Пагорб і навколишні каньйони. Дуротару невпинно загрожують морські піхотинці Кул Тірасу на східному березі, шипогриви-нападники, що нишпорять чагарниками, та культисти Палаючого Клинка, які чаяться в сусідніх скелях. З цієї піднесеної точки на гребені дозорець помічає бойові загони, димові сигнали та вторгнення задовго до того, як вони дістануться брами поселення."}},faq={{q="Для чого потрібна Сторожова вежа Гострого Пагорба?",a="Вежа — головний спостережний пост Гострого Пагорба й центрального Дуротару. З її висоти розвідники стежать за стежками, виглядають ворожих звірів і помічають пересування військ із сусідніх таборів Альянсу чи загонів кентаврів.",al={"чому тут сторожова вежа","призначення сторожової вежі","вежа гострого пагорба"}},{q="Хто охороняє вежу?",a="Тут чатує на загарбників літній орк Фурл Скорнброу, що за потреби сурмить у сигнальний ріг. Відколи в Дуротарі стало спокійніше, він узявся шити сумки для юних шукачів пригод.",al={"хто біля вежі","охорона сторожової вежі"}},{q="Які загрози видно звідси?",a="Розвідники здебільшого виглядають агресивних шипогривів із племен Гостроманів, людей-лазутчиків із Фортеці Тіраґард на східному узбережжі й диких звірів, що блукають сухими долинами.",al={"загрози гострому пагорбу","що вони виглядають"}}},fp="21,275,17.485.0,49.259.0,26.186.0,38.184.0"}
P.entries["subzone:razorfen-downs"] = {n="Рейзорфен Даунс",s="Рейзорфен Даунс — родова столиця й священний лабіринт-усипальниця шипогривів, видовбаний глибоко у велетенських колючих хащах на межі південних Пусток і Тисячі Голок. Колись їхня найсвятіша обитель, тепер він підпав під владу нежиті Погибелі й перетворився на гнійний оплот некромантії.",h="Рейзорфен Даунс — родова столиця й священний лабіринт-усипальниця шипогривів, видовбаний глибоко у...",kw={"рейзорфен даунс","шипогриви","погибель","амненнар хладоносець","нежить","агамаґґан"},ang={["faction:Horde"]="Шипогриви — вічна скалка в боці Перехрестя, але форпост Короля-Ліча на самому краю Пусток — смертельна загроза, яку Орда не може собі дозволити ігнорувати.",["race:Undead"]="Для Відступників звістка про те, що ліч Погибелі потай діє на Калімдорі, — моторошне нагадування про володаря, проти якого вони повстали; така загроза вимагає швидкого й рішучого знищення."},sec={{t="Осквернене священне місто",b="Рейзорфен Даунс, що споконвіку шанувався як родова столиця й місце поховань раси шипогривів, лежить серед велетенських скам'янілих терновищ, які виросли з полеглого напівбога Агамаґґана. Переказ каже, що його арковий вхід вирізано просто з пащі самого Великого Вепра. Століттями верховні жерці племені Мертвої Голови доглядали ці глибокі звивисті нори й шанували своїх небіжчиків. Та попри священність цього місця для вепролюдей, лабіринт кісток і терну нещодавно спіткало лихо, значно темніше за будь-які сварки за воду Пусток."},{t="Погибель сягає Калімдору",b="Після спустошення Третьої війни щупальця нежиті Погибелі нечутно простяглися в південний Калімдор. Під проводом ліча Амненнара Хладоносця, що володіє кригою, посланці смерті проникли в терновий лабіринт і підкорили жрецтво Мертвої Голови. Замість шанувати предків, шипогриви тепер дають прихисток гниючим гулям, скелетам і некромантам у своїх священних загонах. Ця порча загрожує розповзтися по всіх Пустках і перетворити найсвятішу землю шипогривів на плацдарм для задумів Погибелі на заході."}},faq={{q="Що таке Рейзорфен Даунс?",a="Рейзорфен Даунс — родова столиця й поховальне місце народу шипогривів. Виросле з велетенських терневих заростей, що з'явилися на місці полеглого Прадавнього Аґамаґґана, воно є духовним серцем культури шипогривів і осідком їхнього верховного жрецтва — племені Мертвої Голови.",al={"що таке даунс","рейзорфен даунс лор","хто живе в рейзорфен даунс"}},{q="Чому в Рейзорфен Даунс Погибель?",a="Ліч Амненнар Хладоносець прибув сюди після Третьої війни, щоб заснувати в Калімдорі твердиню для Короля-Ліча. Зіпсувавши жрецтво Мертвої Голови й піднявши мертвих шипогривів, Амненнар перетворив заплутане терневе місто на приховане гніздо некромантичної сили.",al={"чому нежить у рейзорфен даунс","амненнар рейзорфен даунс","погибіль у рейзорфені"}},{q="Чим Рейзорфен Даунс відрізняється від Рейзорфен Краулу?",a="Рейзорфен Краул — головний військовий оплот і живе кубло шипогривів, яким безпосередньо править стара Чарлґа Рейзорфленк. А Даунс — їхня традиційна столиця й священне поховальне місце далі на півдні, що потрапило під владу некромантії й Погибелі.",al={"різниця між краулом і даунсом","даунс проти краула","краул чи даунс"}},{q="Де розташований вхід?",a="Даунс лежить на самому південному кордоні Пусток, над великим урвищем до Тисячі Голок. Його вхід — природна арка-розколина серед височенних сплутаних заростей; за переказами, її вирізано з роззявленої пащі Аґамаґґана.",al={"вхід у даунс","де рейзорфен даунс","як зайти в рейзорфен даунс"}}},fp="14,311,23.565.0,28.557.1,23.288.0,41.273.0,51.288.0,30.259.0"}
P.entries["subzone:razorfen-downs-classic"] = {n="Рейзорфен Даунс (класичний)",s="Рейзорфен Даунс — прадавнє родове кладовище й традиційна столиця шипогривів, що ховається глибоко серед велетенських колючих терновиків на півдні Пусток. Нещодавно агенти нежиті з Погибелі на чолі з лічем Амненнаром Хладоносцем захопили лабіринт, підняли мертвих шипогривів і погрожують поширити свою владу на весь центральний Калімдор.",h="Рейзорфен Даунс — прадавнє родове кладовище й традиційна столиця шипогривів, що ховається глибоко серед...",kw={"рейзорфен даунс","амненнар хладоносець","погибель","шипогриви","аґамаґґан","підземелля"},ang={["faction:Horde"]="Цитадель Погибелі просто на південному кордоні Пусток — неминуча загроза для серця земель Орди та шляхів постачання.",["race:Undead"]="Королівське Аптекарське Товариство й провід Відступників в Андерсіті пильно цікавляться суперницькою некромантією, що розквітає в Даунсі, і прагнуть її дослідити та знищити."},sec={{t="Столиця колючок",b="Рейзорфен Даунс, що виріс із тих самих велетенських скам'янілих лоз, що й сусідній Рейзорфен Краул, лежить там, де під час Війни Прадавніх поліг давній напівбог-вепр Аґамаґґан. Покоління за поколінням цей колючий лабіринт був священним некрополем і осередком влади шипогривів під пильною охороною містиків племені Мертвої Голови. Для шипогривів густі терновики — свята земля, просякнута кров'ю їхнього божественного праотця."},{t="Твердиня Погибелі на Калімдорі",b="Святість Даунсу розбилася, коли агенти Погибелі проникли в терновики. Амненнар Хладоносець, могутній ліч на службі Короля-Ліча, підкорив шипогривів Мертвої Голови, що жили тут, і перетворив прадавнє місце спочинку на редут нежиті. Тепер Спіраллю Терну никають підняті скелети, шкутильгаючі трупи й верескливі баньші. І Орда в сусідніх Пустках, і посланці Собору Світла зі Стормвінда вважають цей дедалі більший осередок сили Погибелі серйозною загрозою для всього континенту."}},faq={{q="Що таке Рейзорфен Даунс?",a="Рейзорфен Даунс — родова столиця й некрополь народу шипогривів, вирізаний у велетенських терневих заростях на півдні Пусток. Нещодавно він потрапив під владу Погибелі.",al={"що таке рфд","рейзорфен даунс лор","передісторія даунсу"}},{q="Звідки нежить у місті шипогривів?",a="Ліч Погибелі на ім'я Амненнар Хладоносець вдерся до Даунсу, підкорив місцеве плем'я Мертвої Голови й підняв мертвих шипогривів, щоб створити плацдарм нежиті в Калімдорі.",al={"чому погибіль в даунсі","чому нежить у пустовиськах","хто привів погибіль"}},{q="Яка різниця між Рейзорфен Даунс і Рейзорфен Краулом?",a="Обидва підземелля вирізані в терні Аґамаґґана, але Рейзорфен Краул — живий оплот шипогривів на чолі з Чарлґою Рейзорфленк. А Рейзорфен Даунс — їхнє родове поховальне місце, яке нині заполонила Погибель.",al={"даунс проти краула","рфк проти рфд","різниця між даунсом і краулом"}},{q="Хто зараз править Рейзорфен Даунс?",a="Амненнар Хладоносець, ліч Погибелі, командує твердинею з глибини Спіралі Терну.",al={"бос рфд","хто править рейзорфен даунс","бос даунсу"}}},fp="24,367,17.436.0,29.535.0,23.185.0,44.173.0,65.226.0,35.111.0"}
P.entries["subzone:razorfen-kraul-classic"] = {n="Рейзорфен Краул (класичний)",s="Рейзорфен Краул — прадавнє серце земель шипогривів, вирізане глибоко у велетенських колючках, що виросли з крові полеглого напівбога-вепра Аґамаґґана. Цим укріпленим лабіринтом править безжальна стара Чарлґа Рейзорфленк, і звідси вирушають криваві набіги на південні Пустки.",h="Рейзорфен Краул — прадавнє серце земель шипогривів, вирізане глибоко у велетенських колючках, що виросли з...",kw={"рейзорфен краул","чарлґа рейзорфленк","шипогриви","аґамаґґан","погибель","підземелля"},ang={["faction:Horde"]="Люті набіги Чарлґи Рейзорфленк прямо загрожують південним поселенням і торговим шляхам, тож приборкання Краула — нагальне питання безпеки для Орди.",["race:Tauren"]="Таурени-мисливці й шамани здавна ворогують із шипогривами, а чутки про те, що нечестива скверна Погибелі вкорінюється у шанованій землі Аґамаґґана, вимагають їхнього негайного втручання."},sec={{t="Кров Бога-Вепра",b="Десять тисяч років тому, під час Війни Прадавніх, велетенський напівбог-вепр Аґамаґґан загинув у бою з Палаючим Легіоном, рятуючи Азерот. Там, де його священна кров просочилася в ґрунт південного Калімдору, із землі вирвалися величезні непрохідні колючі лози. Шипогриви, які вважають себе смертними нащадками Великого Вепра, оселилися в цих густих терновиках, шануючи його жертву. Гущавина, відома як Рейзорфен Краул, — їхній найшанованіший редут, де повно воїнів-шипогривів, приборкувачів звірів і шаманів, що підкоряють собі землю."},{t="Задуми старої",b="Влада над Краулом перейшла до старої геомантки Чарлґи Рейзорфленк. Під її залізною рукою плем'я Рейзорфен веде нещадну війну і з суперницькими зграями шипогривів, і з ближніми таборами Орди. Проте значно моторошніші за звичайні набіги — донесення пильних розвідників про постаті нежиті, що никають довкола колючих хащів. Ходять чутки, що Чарлґа почала торгуватися з агентами Погибелі, і це загрожує не лише Пусткам, а й може відкрити нежиттю похмурий плацдарм на Калімдорі."}},faq={{q="Звідки взялися велетенські терни довкола Рейзорфен Краулу?",a="За легендою, колосальні терневі лози проросли там, де кров напівбога-вепра Аґамаґґана впала на землю під час Війни Прадавніх десять тисяч років тому.",al={"чому тут терни","гігантські терни пустовиськ","терни аґамаґґана лор"}},{q="Хто править Рейзорфен Краулом?",a="Рейзорфен Краулом командує Чарлґа Рейзорфленк — безжальна стара шипогривка й геомантка, що спрямовує набіги на сусідні племена й поселення.",al={"лідер рейзорфен краулу","хто править краулом","чарлґа гострий бік"}},{q="Звідки біля Краулу нежить?",a="Кажуть, Чарлґа Рейзорфленк потай вступила в перемовини з посланцями Погибелі, шукаючи нечестивого союзу, який міг би принести силу нежиття в лави шипогривів.",al={"погибіль у рейзорфені","нежить шипогриви","чому погибіль у пустовиськах"}},{q="Де розташований Рейзорфен Краул?",a="Рейзорфен Краул лежить на самому півдні Пусток, на західному боці велетенських терневих хащ, трохи на північ від Великого Підйомника.",al={"де рфк","вхід в рфк","розташування рейзорфен краулу"}}},fp="24,306,21.566.0,20.529.1,52.176.0,25.152.0,36.179.1,32.159.0"}
P.entries["subzone:razormane-grounds"] = {n="Угіддя Гостроманів",s="Угіддя Гостроманів — передовий табір шипогривів Гостроманів, що пробиваються зі Пусток на схід, у центральний Дуротар. Забитий колючими чагарями й обгризеними тушами дичини, цей наїжачений табір є передовою у нескінченній війні шипогривів з орками Оргріммара.",h="Угіддя Гостроманів — передовий табір шипогривів Гостроманів, що пробиваються зі Пусток на схід, у центральний...",kw={"угіддя гостроманів","шипогриви","гостромани","табір","колючки","річка південної люті","дуротар"},ang={["faction:Horde"]="Тримати Угіддя Гостроманів під контролем вкрай важливо, щоб убезпечити дороги й шляхи постачання між Пустками та столицею Орди — Оргріммаром.",["race:Orc"]="Для орків Дуротару Угіддя Гостроманів — невідступна загроза в самому серці нової батьківщини, тож молоді воїни доводять свою вправність, винищуючи шипогривів."},sec={{t="Скалка в боці Дуротару",b="Розкинувшись під червоними скелями центрального Дуротару, Угіддя Гостроманів позначають найдальшу східну межу просування шипогривів зі Пусток. Обплутаний густими колючками й оточений вибіленими кістками, табір — постійна небезпека для мандрівників уздовж Річки Південної Люті. Його очолюють такі постаті, як Капітан Флет Таск із бойової варти та Геолорд Моттл, що влаштовують набіги на сусідні орківські поселення й обози. Попри регулярні патрулі з Гострого Пагорба та сусідніх застав, Гостромани невтомно поповнюють лави, проростаючи з колючок швидше, ніж Орда встигає їх викорчувати."}},faq={{q="Що таке Угіддя Гостроманів?",a="Це укріплений табір шипогривів у центрі Дуротару — передова база племені Гостроманів, що розширює свої володіння на схід від Пусток.",al={"угіддя гостроманів","табір шипогривів дуротар","де гостромани"}},{q="Чому шипогриви нападають на Дуротар?",a="Шипогриви-Гостромани вважають усі сусідні землі своїми по праву й прагнуть розширити свої терневі хащі й мисливські угіддя коштом нових поселень Орди.",al={"чому шипогриви нападають","чому гостромани тут","навала шипогривів"}},{q="Хто очолює шипогривів в Угіддях Гостроманів?",a="Табором командує Капітан Флет Таск, ватажок Бойової Варти Гостроманів, разом із геомантом, що підкоряє собі землю, — Геолордом Моттлом.",al={"боси гостроманів","хто очолює угіддя гостроманів","капітан плоскоклик"}},{q="Чому довкола табору стільки кісток?",a="Гостромани — затяті падлоїди й мисливці: вони обгризають місцевих звірів до кісток, щоб нагодувати своїх нападників, а туші лишають позначати свої володіння.",al={"кістки в таборі","туші тварин гостроманів","чому мертві тварини"}}},fp="17,305,25.653.0,30.148.0,39.180.0,48.140.0,44.174.0"}
P.entries["subzone:razorwind-canyon"] = {n="Каньйон Гострого Вітру",s="Каньйон Гострого Вітру — звивиста скеляста балка, розділена головною дорогою між Гострим Пагорбом і Оргріммаром. Заселений войовничими гарпіями Пилового Вітру, каньйон становить постійну небезпеку для мандрівників, що прямують на північ, до столиці Орди.",h="Каньйон Гострого Вітру — звивиста скеляста балка, розділена головною дорогою між Гострим Пагорбом і...",kw={"каньйон гострого вітру","гарпії","пиловий вітер","дорога","гострий пагорб","оргріммар","дуротар"},ang={["faction:Horde"]="Очистити Каньйон Гострого Вітру від гарпій Пилового Вітру вкрай важливо, щоб головний шлях між Гострим Пагорбом і столицею Оргріммаром лишався безпечним для гінців і новобранців.",["race:Orc"]="Гарпії, що гніздяться просто біля центральної дороги Дуротару, — образа для безпеки орківської батьківщини, тож молодим воїнам доводиться проріджувати їхні лави."},sec={{t="Загроза на великій дорозі",b="Каньйон Гострого Вітру обступає центральну артерію, що з'єднує Гострий Пагорб з Оргріммаром, прорізаючи шляхи і в східні кручі, і в західні чагарники в бік Ферми Тор'крена. Каньйон — місце гніздування гарпій Пилового Вітру, територіальних створінь, які без вагань нападають на мандрівників, що підійдуть надто близько до їхніх сідал. Їхня присутність так близько до торгових шляхів столиці робить зачистку цих балок постійною потребою для захисників Дуротару."},{t="Проходи та яри",b="Окрім гнізд гарпій, звивини Каньйону Гострого Вітру служать прихованими шляхами крізь червоні скелясті пагорби Дуротару. Східне відгалуження глибоко врізається в скелі й через печеру веде до Яру Сухої Балки. Оскільки гарпії сидять на високих сідалах і спускаються зграями, необачні шукачі пригод, що йдуть цими проходами, легко можуть опинитися в оточенні й бути порубаними."}},faq={{q="Де розташований Каньйон Гострого Вітру?",a="Каньйон Гострого Вітру лежить у центрі Дуротару, обабіч головної дороги між Гострим Пагорбом і Оргріммаром. Входи до нього — на північ від Гострого Пагорба, біля Ферми Тор'крена, і крізь печеру, що веде до Яру Сухої Балки.",al={"розташування каньйону гострого вітру","де каньйон гострого вітру","як знайти каньйон гострого вітру"}},{q="Хто живе в Каньйоні Гострого Вітру?",a="У каньйоні повно гарпій Пилового Вітру. Ці агресивні крилаті створіння гніздяться великими зграями по всіх ярах і скелястих виступах і полюють на необачних мандрівників.",al={"моби гострого вітру","що живе в каньйоні гострого вітру","каньйон гарпій дуротар"}},{q="Чому цей каньйон турбує Орду?",a="Каньйон Гострого Вітру межує з головним торговим і подорожнім шляхом між Гострим Пагорбом і Оргріммаром. Гарпії з гнізд раз у раз нападають на гінців, каравани з припасами й мандрівників на центральній дорозі.",al={"чому турбує орду","загроза оргріммару від гострого вітру"}},{q="Чи сполучений Каньйон Гострого Вітру з іншими місцями?",a="Так. Окрім виходу на головну дорогу, з каньйону ведуть стежки на захід — до Ферми Тор'крена, а на сході є печера, що веде до Яру Сухої Балки.",al={"зв'язки каньйону","куди веде гострий вітер"}}},fp="16,239,25.462.0,20.394.0,34.240.0,40.189.0,45.204.0,45.160.0"}
P.entries["subzone:rebel-camp"] = {n="Табір Повстанців",s="Табір Повстанців, що ховається трохи осторонь дороги на півночі Долини Стренглторну, — укріплений прихисток для солдатів Альянсу, які відкололися від Полковника Курзена. Під проводом Лейтенанта Дорена ці вояки не скорилися безумству, що охопило експедицію їхнього командира, і тепер борються за виживання та прагнуть покласти край тиранії, у яку він скотився.",h="Табір Повстанців, що ховається трохи осторонь дороги на півночі Долини Стренглторну, — укріплений прихисток...",kw={"табір повстанців","полковник курзен","лейтенант дорен","стормвінд","альянс","долина стренглторну"},ang={["faction:Alliance"]="Табір Повстанців — ваша головна база й найбезпечніший прихисток, коли ви перетинаєте міст із Сутінколісся на південь, до Долини Стренглторну.",["race:Human"]="Дивитися, як вояки регулярного війська Стормвінда втрачають розум у джунглях, — гірке видовище, і Лейтенантові Дорену конче потрібні піддані королівства, які допоможуть покінчити з ганебним загоном Курзена."},sec={{t="Опір безумству",b="Коли експедиція Полковника Курзена за наказом Стормвінда заглибилася в джунглі Долини Стренглторну, усе швидко пішло шкереберть. Уражені темною магією джунглів і прокляттям огра-мага Май'Зота, полковник і його найвірніші прибічники збожеволіли, вийшли з-під будь-якої влади й тепер тероризують нетрі. Жменька солдатів, які зберегли здоровий глузд, на чолі з Лейтенантом Дореном відмовилася брати участь у звірствах. Відколовшись від Поселення Курзена, вони заснували на півночі цей прихований табір і ведуть звідти відчайдушну партизанську війну проти колишніх товаришів."},{t="Утримати позиції",b="Табір Повстанців ризиковано примостився біля кордону із Сутінколіссям і живе під постійною загрозою. Відрізаний від регулярної допомоги Стормвінда, Дорен покладається на таємні постачання й оборонне озброєння — зокрема на гоблінську вибухівку, придбану через Буті Бей, — щоб утримувати периметр від набігів Курзенових загонів. Для мандрівників Альянсу, які вирушають на південь у дикі джунглі, цей табір — перший життєво важливий острівець здорового глузду."}},faq={{q="Хто ці повстанці з Табору Повстанців?",a="Це колишні вояки Стормвінда, що входили до експедиції Полковника Курзена в Долину Стренглторну. Коли Курзен і його найближче оточення збожеволіли й стали тиранами, Лейтенант Дорен очолив цей загін у бунті, щоб утекти від них і дати їм відсіч.",al={"хто живе в таборі повстанців","хто ці солдати","табір повстанців альянс"}},{q="Чому табір зветься Табором Повстанців, якщо вони вірні Стормвінду?",a="Повстанцями вони є лише щодо командування Полковника Курзена. Курзен був їхнім командиром, тож непокора його наказам формально була бунтом, хоча вони лишаються вірними Альянсу й Стормвінду.",al={"чому табір повстанців","чи вони зрадники","проти кого повстали"}},{q="Як табір виживає без офіційної підтримки Стормвінда?",a="Далеко від офіційних шляхів постачання Лейтенант Дорен покладається на винахідливі неофіційні зв'язки — зокрема торгує з такими знайомими, як Кразек у Буті Беї, що постачає міни й конче потрібне спорядження для оборони табору.",al={"постачання табору повстанців","де вони беруть їжу","логістика табору повстанців"}},{q="Де перебуває Полковник Курзен?",a="Курзен і його збожеволілі прибічники засіли в Поселенні Курзена — укріпленій базі просто на південний схід від Табору Повстанців.",al={"де полковник курзен","розташування курзена","поселення курзена"}}},fp="10,330,23.565.0,16.424.0,37.239.0,63.219.0,61.238.0,32.123.0"}
P.entries["subzone:red-rocks"] = {n="Червоні Скелі",s="Червоні Скелі — висока піщаникова круча в північно-східному Малгорі, священне прабатьківське поховальне місце тауренів. Тут полеглих звитяжців ввіряють Земній Матері через очисне полум'я, а молоді сміливці підіймаються на тихі висоти шукати мудрості предків.",h="Червоні Скелі — висока піщаникова круча в північно-східному Малгорі, священне прабатьківське поховальне місце...",kw={"червоні скелі","поховання","предки","шипогриви","тандер блаф","малгор","осквернення"},ang={["class:Shaman"]="Вітер несе скорботу неупокоєних духів, яких потривожило осквернення шипогривів, і закликає до шаманських обрядів, щоб відновити рівновагу стихій і спокій предків.",["race:Tauren"]="Для вашого народу Червоні Скелі — священна земля. Те, що мерзенні шипогриви риються серед погребальних вогнищ ваших шанованих предків, — відверте блюзнірство, яке вимагає очищення."},sec={{t="Освячене каміння й погребальні вогнища предків",b="Багряні скельні утворення Червоних Скель, що здіймаються над рівнинами північно-східного Малгору, позначають священний поріг між світом живих і наступним. Тауренська традиція береже цю урочисту землю для найдоблесніших героїв — вождів, захисників і звитяжців, що віддали життя, засновуючи й боронячи Тандер Блаф. Їхні рештки ввіряють небу й землі на обрядових вогнищах, повертаючи духи Земній Матері та Небесному Батькові. Та це й місце духовного початку: тут молоді таурени завершують обряди посвяти, вшановуючи могили предків і спілкуючись із вітром."},{t="Осквернення шипогривами",b="Одвічний спокій Червоних Скель розбили шипогриви Щетиноспинних. Виповзши зі своїх лігв, ці агресивні падложери заполонили піщаникові уступи й споганили погребальні вогнища предків нечистотами. Таке блюзнірство глибоко ображає духовні традиції Тандер Блафа. Шамани й хранителі переказів тепер кличуть на допомогу, щоб очистити кручі, вигнати Щетиноспинних і повернути святість місцю спочинку мертвих."}},faq={{q="Для чого потрібні Червоні Скелі?",a="Червоні Скелі — головне родове поховання й місце обрядів тауренів Малгору. Тут спалюють полеглих героїв і шанованих сміливців, щоб їхні духи повернулися до Земної Матері, а юні таурени під час випробувань дорослості піднімаються сюди вшанувати померлих.",al={"навіщо червоні скелі","призначення червоних скель","що відбувається на червоних скелях"}},{q="Звідки на Червоних Скелях шипогриви?",a="Шипогриви-Щетиноспини вибралися зі своїх терневих нір і заполонили плато, оскверняючи поховальні кургани. Таурени вважають це вторгнення нестерпним блюзнірством проти духів предків, що спочивають тут.",al={"шипогриви на червоних скелях","хто вторгається на червоні скелі","щетиноспинні тут"}},{q="Хто похований на Червоних Скелях?",a="Поховання на Червоних Скелях — честь лише для найхоробріших тауренів: великих воїнів, що разом із Кайрном Бладгуфом відвоювали Малгор і збудували Тандер Блаф, а також героїв, що загинули, служачи своїм племенам.",al={"хто кремований тут","мертві червоних скель","чиї це могили"}},{q="Які обряди тут правлять?",a="Окрім поховальних вогнищ, на яких померлих доручають Земній Матері й Небесному Батькові, скеля — осердя Обряду Мудрості: тут тауренські сміливці лишають дари й дослухаються, чи не принесе вітер настанов духів предків.",al={"обряди червоних скель","тауренські ритуали червоних скель"}}},fp="9,293,35.621.0,24.440.0,33.290.0,36.229.0,27.224.0,35.216.0"}
P.entries["subzone:refuge-pointe"] = {n="Притулок",s="Притулок — головний оплот Альянсу та вцілілих решток Стромґарда в Аратійському нагір'ї. Він стоїть посередині торгового шляху через нагір'я і правує за плацдарм, щоб відвоювати зруйновану столицю — Фортецю Стромгард — і стримувати ворожі сили по всьому краю.",h="Притулок — головний оплот Альянсу та вцілілих решток Стромґарда в Аратійському нагір'ї.",kw={"притулок","стромґард","капітан найлс","альянс","ліга аратора","аратійське нагір'я"},ang={["faction:Alliance"]="Притулок — ваш єдиний військовий прихисток і пункт польотів в Аратійському нагір'ї; він дає вкрай потрібний перепочинок у небезпечному краї, за який змагаються огри, Синдикат і Орда.",["race:Human"]="Для людей Притулок — щемке нагадування про колишню славу Стромґарда як військового серця людства, де стійкі захисники не покидають рідної землі, хоч які нерівні сили."},sec={{t="Оплот для решток Стромґарда",b="Після спустошення Третьої війни й катастрофічного падіння Фортеці Стромгард більшість уцілілих жителів Стромґарда втекли на південь, до приязніших земель. Ті, хто лишився, утворили рішучий авангард і окопалися в Притулку під проводом Капітана Найлса. Табір, де стоять загартовані в боях вояки Стромґарда, сили Ліги Аратора й допоміжні фахівці Альянсу, — останній організований опір королівства на землі предків."},{t="На межі сил",b="Притулок щомиті ризикує впасти під натиском ворогів. Його затиснули Відступники й Орда з Гаммерфолла, тролі-Сухокори, розбійники Синдикату та огри Каменекулаків, тож у гарнізону немає жодних резервів. Коли дворфійські командири на побитому Мості Тандол у розпачі попросили підкріплення проти клану Темного Заліза, Капітан Найлс мусив відмовити. Кожен меч, щит і крихта припасів у Притулку мають і далі служити обороні нагір'я та підготовці контрнаступу, щоб повернути Фортецю Стромгард."}},faq={{q="Чому Альянс має тут так мало сил?",a="Після Третьої війни королівство Стромґард лягло в руїнах, і більшість уцілілих мешканців мусила евакуюватися на південь. Війська в Притулку — виснажені рештки стромґардської армії, підсилені експедиційним загоном Альянсу. Припасів обмаль, вороги з усіх боків, тож вони ледь утримують свій укріплений табір.",al={"чому в альянсу тут мало сил","чому так мало солдатів","кількість альянсу араті"}},{q="Чому Притулок не пришле воїнів на допомогу до Мосту Тандол?",a="Коли дворфійські гінці прибули просити війська для оборони Дун Модра й Мосту Тандол від нападів Темного Заліза, Капітан Найлс мусила відмовити. Фортеця Стромгард захоплена, довкола вороги, тож обов'язок і виживання вимагають, щоб кожен вояк лишався на місці, утримуючи нагір'я й готуючись відвоювати полеглу столицю.",al={"чому не допомагають дун модру","капітан ніалс міст тандол","прохання до альянсу"}},{q="Хто командує табором?",a="Гарнізоном Притулку командує Капітан Найлс. Вона керує військовими діями Стромґарда по всьому нагір'ю: розвідкою, сутичками із Синдикатом і ограми та оборонними патрулями вздовж головної дороги.",al={"лідер притулку","хто командує тут","капітан ніалс"}},{q="Що таке Ліга Араторів?",a="Ліга Араторів — союз Альянсу, що прагне повернути Аратійське нагір'я й забезпечити цінні ресурси в сусідній Аратійській Улоговині. Разом із рештками сил Стромґарда в Притулку вони борються, щоб не віддати родючу долину Осквернителям на чолі з Відступниками.",al={"ліга араторів","хто такі ліга араторів","альянс низовини араті"}}},fp="13,302,35.464.0,22.557.0,43.337.0,66.329.0,22.238.0,30.295.0"}
P.entries["subzone:remtravel-s-excavation"] = {n="Розкопки Ремтревела",s="Розкопки Ремтревела — місце археологічних розкопок на півдні Темного Узбережжя. Експедиція, яку заснував дворф Шукач Ремтревел, нещодавно натрапила на давні підземні руїни й ненавмисно розбудила ворожих трогів і кам'яних големів, які швидко захопили кар'єр.",h="Розкопки Ремтревела — місце археологічних розкопок на півдні Темного Узбережжя.",kw={"розкопки ремтревела","шукач ремтревел","троги","големи","скам'янілість","темне узбережжя"},ang={["race:Dwarf"]="Дворфи з Ліги Дослідників славляться пошуками таємниць минулого, хоча розкопані на чужій землі небезпечні троги часто завдають знайомого головного болю.",["race:NightElf"]="Калдореї здебільшого скептично дивляться, як дворфійські кайла Альянсу вгризаються вглиб, особливо коли необачне копання будить диких трогів у давній землі Темного Узбережжя."},sec={{t="Захоплений кар'єр",b="Шукач Ремтревел прибув на Темне Узбережжя в пошуках реліквій далекого минулого й заклав сміливі розкопки далеко від безпечного Обердайна. Розкопуючи давні шари, його загін наткнувся на рій підземних трогів Гравієкременю й на кремезних кам'яних големів, похованих під землею. Науковий кар'єр умить перетворився на небезпечну зону: рудокопи розбіглися, а Ремтревел квапливо намагався врятувати свої найцінніші знахідки."},{t="Зникла скам'янілість",b="Перш ніж розкопки поринули в хаос, Ремтревел знайшов рідкісну скам'янілість, від якої віяло дивними містичними властивостями. У паніці під час навали трогів — і через свою горезвісну неуважність — шукач загубив цінну реліквію серед розлогих земляних ям. Щоб повернути її, доведеться спуститися на розкопки й протистояти і лютим трогам, і давнім автоматонам, яких розбудили кайла."}},faq={{q="Що таке Розкопки Ремтревела?",a="Це місце археологічних розкопок на півдні Темного Узбережжя, яке заснував Шукач Ремтревел — дослідник, що шукає давні скам'янілості й підземні реліквії.",al={"що це за місце","розкопки темного берега","розкопки ремтревела"}},{q="Звідки тут троги?",a="Дворфійські рудокопи копнули надто глибоко й пробилися в підземні печери, розбудивши місцеве плем'я трогів Ґравелфлінтів, а з ними — приспаних кам'яних големів.",al={"чому трогги на темному березі","трогги гравелфлінт","звідки трогги"}},{q="Хто такий Шукач Ремтревел?",a="Це дворф-археолог, що очолює розкопки. Він славиться гострим оком на артефакти — і неабиякою неуважністю: коли на розкопки напали, він загубив важливу скам'янілість.",al={"хто такий ремтревел","шукач ремтревел історія"}},{q="Яку реліквію тут знайшли?",a="Ремтревел знайшов незвичайну скам'янілість, наділену дивними містичними властивостями, — незадовго до того, як із нижніх глибин ринули троги.",al={"що вони знайшли","скам'янілість ремтревела","містична скам'янілість"}}},fp="22,296,16.470.0,18.413.1,31.154.0,26.167.0,28.184.0,39.133.0"}
P.entries["subzone:render-s-rock"] = {n="Скеля Рендера",s="Скеля Рендера — печерна твердиня в північно-західних кручах Гір Редріджу, неподалік високого перевалу, що веде до Палаючих Степів. Її тримають люті орки Блекрок: для них це передовий оплот і діючий плацдарм для набігів на долини внизу.",h="Скеля Рендера — печерна твердиня в північно-західних кручах Гір Редріджу, неподалік високого перевалу, що...",kw={"скеля рендера","орки блекрок","печера","капрал кішан","гори редріджу","палаючі степи"},ang={["faction:Alliance"]="Для бійців Альянсу Скеля Рендера — одна з найміцніших позицій Блекрок у Редріджі, і її зачистка конче потрібна, щоб визволити Капрала Кішана й захистити Лейкшир."},sec={{t="Твердиня Блекрок на висотах",b="Видовбана в скелястих висотах на північ від Лейкшира, Скеля Рендера — укріплена мережа печер клану Блекрок, що вдерся в край. З цього зручного для оборони оплоту біля гірського перевалу до Палаючих Степів бувалі орки Блекрок спрямовують напади на місцевих захисників Редріджу. Її темні глибини суворо охороняються, тож будь-який рейд усередину — небезпечна справа для тих, хто хоче перерізати орочі шляхи постачання чи визволити полонених, захоплених у цій війні."},{t="Бранець у тіні",b="Окрім стратегічного значення для орків, Скеля Рендера має похмуру вагу й для захисників Лейкшира. У її глибинах тримають пораненого вояка з Редріджу — Капрала Кішана. Опинившись глибоко в тилу ворога, відрізаний від товаришів, Кішан своїм полоном нагадує і про зухвалість вторгнення Блекрок, і про високу ціну, яку заплатив місцевий гарнізон, намагаючись утримати гірську дорогу відкритою."}},faq={{q="Де розташована Скеля Рендера?",a="Скеля Рендера — серед далеких північно-західних вершин Гір Редріджу, неподалік від стежки, що веде на північ, у Палаючі Степи.",al={"розташування скелі рендера","де скеля рендера","знайти скелю рендера"}},{q="Хто тримає Скелю Рендера?",a="Печеру займають грізні орки Блекрок: ця круча — їхній оплот, звідки вони керують нападами й наглядають за гірськими перевалами на межі з Палаючими Степами.",al={"хто на скелі рендера","вороги скелі рендера","хто тримає скелю рендера"}},{q="Кого ув'язнено в печері?",a="У Скелі Рендера тримають у полоні Капрала Кішана — пораненого ветерана гарнізону Альянсу, якому потрібна допомога, щоб безпечно втекти назад до Лейкшира.",al={"де кішан","бранець скелі рендера","хто в пастці на скелі рендера"}},{q="Чому ця печера важлива для оборони Лейкшира?",a="Тут, просто над долиною Редріджу, засіли досвідчені воїни Блекрок, тож Скеля Рендера — пряма загроза містечку Лейкшир і плацдарм орків на південь від Палаючих Степів.",al={"чому нападати на скелю рендера","загроза скелі рендера","значення скелі рендера"}}},fp="13,300,34.483.0,24.411.1,31.144.0,27.164.0,34.166.0,50.220.0"}
P.entries["subzone:render-s-valley"] = {n="Долина Рендера",s="Долина Рендера — відлюдний табір орків Блекрок на південному сході Гір Редріджу. Він укріплений далеко не так, як величезні твердині Кам'яної Варти, але все одно становить постійну загрозу для мандрівників і тримає полонених, захоплених у довколишніх землях.",h="Долина Рендера — відлюдний табір орків Блекрок на південному сході Гір Редріджу.",kw={"долина рендера","орки блекрок","табір","слуга азори","болото скорботи","гори редріджу"},ang={["faction:Alliance"]="Табір — другорядна застава грабіжників Блекрок, що загрожує південному Редріджу, тож його зачистка вкрай важлива для безпеки торгівлі й подорожей довкола Лейкшира.",["profession:Tailoring"]="Полонений Слуга Азори, ув'язнений в орочому таборі, пропонує рідкісні викрійки й матеріали кравцям, готовим пробитися до нього крізь вартових."},sec={{t="Опора на південному сході",b="Захована серед кам'янистих кряжів на південний схід від Озера Незрушного, Долина Рендера служить допоміжним табором для орків Блекрок, що діють у Редріджі. На відміну від добре укріплених фортець і кам'яних веж північних круч, тут лише скромне скупчення бойових наметів, прапорів і сторожових постів. Загін тут менший і гірше озброєний, ніж головні сили клану, проте місцеві воїни грабують дороги, нападають на мандрівників і тримають бранців у грубих клітках під вартою."},{t="Таємні стежки й полонені",b="Окрім бойових загонів на ґрунтових стежках, долина ховає несподівані цікавинки для сміливих розвідників. У таборі часом бачили людей-бранців, серед них полоненого слугу, пов'язаного з Вежею Азори, який примудрявся торгувати особливими товарами просто під носом у вартових. А ще суворі, ніким не позначені стежки крізь високі південні урвища за долиною дають змогу відважним слідопитам прослизнути через кордон до каламутних трясовин Болота Скорботи."}},faq={{q="Хто тримає Долину Рендера?",a="Долину займає клан Блекрок — войовниче оркське угруповання, що прорвалося з Палаючих Степів на південь, у Редрідж, щоб захоплювати землі й нападати на людські поселення.",al={"хто в долині рендера","орки долини рендера","який клан у долині рендера"}},{q="Чи такі ж небезпечні тутешні орки, як ті, що в Кам'яній Варті?",a="Ні. Воїни Блекрок у Долині Рендера здебільшого молодші чи слабші бійці порівняно із загартованим добірним гарнізоном Фортеці Кам'яної Варти на півночі.",al={"наскільки сильні орки долини рендера","складність долини рендера"}},{q="Хто той полонений, якого тримають у таборі?",a="Клан Блекрок схопив слугу, пов'язаного з Вежею Азори в Лісі Елвінн, і тримає його тут у клітці. Ті, кому вистачить сміливості дістатися до нього, можуть придбати особливе кравецьке приладдя.",al={"полонений у долині рендера","слуга азори редрідж","кравець долини рендера"}},{q="Чи можна звідси дістатися до Болота Скорботи?",a="Так. Крута неофіційна гірська стежка в'ється південними кручами одразу за Долиною Рендера — це прихований короткий шлях просто до північних околиць Болота Скорботи.",al={"шлях до болота скорботи","гірський прохід долини рендера","скорочення з редріджа до болота"}}},fp="15,279,27.484.0,25.498.0,29.186.0,57.188.0,37.197.0,45.187.0"}
P.entries["subzone:rethban-caverns"] = {n="Печери Ретбану",s="Печери Ретбану — розлога мережа печер у північно-західних кручах Гір Редріджу. Їх заполонили агресивні гноли Редріджу, а найбільше вони відомі як єдине джерело рідкісної ретбанської руди.",h="Печери Ретбану — розлога мережа печер у північно-західних кручах Гір Редріджу.",kw={"печери ретбану","ретбанська руда","гноли","ардо діртпо","гори редріджу","лейкшир"},ang={["faction:Alliance"]="Агресивна зграя гнолів, що засіла в печерах, — постійна загроза для мандрівників у північному Редріджі, тож захисникам Лейкшира доводиться пильнувати ці урвища.",["profession:Mining"]="Печери славляться ретбанською рудою — покладами, за які люто змагаються місцеві племена гнолів."},sec={{t="Нора гнолів",b="Видовбані глибоко в північно-західних горах над Озером Незрушним, Печери Ретбану служать укріпленим оплотом місцевих гнолів. Під хитрим проводом Ардо Діртпо зграя люто стереже покручені ходи й підземні зали, нападаючи на кожного мандрівника, що підійде надто близько до входу на схилі."},{t="Жили Ретбану",b="Печери відомі передусім ретбанською рудою — особливим мінералом, що трапляється в скельних стінах і який носять при собі гноли зграї Діртпо. Ковалі й дослідники з Лейкшира часто посилають мандрівників у небезпечні звивисті тунелі по зразки цієї рідкісної гірської руди."}},faq={{q="Де розташовані Печери Ретбану?",a="Печери лежать у зубчастих кручах на північному заході Гір Редріджу, на північ від головної дороги до Лейкшира.",al={"розташування печер ретбану","де ретбан","як знайти печери ретбану"}},{q="Хто живе в Печерах Ретбану?",a="Тунелі заполонили гноли Редріджу з клану Діртпо, що слухаються хитрого ватажка Ардо Діртпо.",al={"моби ретбану","хто живе в печерах ретбану","вороги ретбану"}},{q="Навіщо шукачі пригод заходять у печери?",a="Мандрівники й мешканці Лейкшира шукають Ретбанську Руду — рідкісну жилу, що трапляється глибоко в печерах, які тримають гноли.",al={"завдання печер ретбану","навіщо йти в печери ретбану","завдання з рудою ретбану"}}},fp="15,209,14.331.0,20.267.0,34.142.0,44.113.0,44.146.0"}
P.entries["subzone:ridgepoint-tower"] = {n="Вежа Ріджпойнт",s="Вежа Ріджпойнт — укріплений вартовий пост, що стереже східне порубіжжя Лісу Елвінн. Її тримають вартові Стормвінда, і вона служить оплотом раннього попередження проти ворожих вторгнень, що загрожують серцю королівства. Її вартові пильнують небезпечні проходи до сусідніх диких земель.",h="Вежа Ріджпойнт — укріплений вартовий пост, що стереже східне порубіжжя Лісу Елвінн.",kw={"вежа ріджпойнт","сторожова вежа","вартові стормвінда","східний кордон","редрідж","сутінколісся","ліс елвінн"},ang={["class:Warrior"]="І солдати, і найманці можуть шанувати стоїчну рішучість вартових, що тримають таку відкриту прикордонну заставу проти ворогів з усіх боків.",["faction:Alliance"]="Для мандрівників Альянсу Вежа Ріджпойнт — підбадьорливий маяк безпеки й порядку перед переходом у небезпечні перевали Редріджу чи на примарні дороги Сутінколісся."},sec={{t="Сторож східного кордону",b="Вежа Ріджпойнт, що стоїть на чатах на височині східного Лісу Елвінн, позначає останній бастіон прямої влади Стормвінда, перш ніж починаються неприборкані нетрі. Розквартирований тут гарнізон невпинно стежить за навколишніми долинами та дорогами. Поки напруга на континенті зростає, ця кам'яна сторожова вежа дбає, щоб загрози, які насуваються, помічали й зупиняли, перш ніж вони зможуть зашкодити фермам і поселенням ближче до Нортширу та Ґолдшира."},{t="Загрози на кожному обрії",b="Вежа Ріджпойнт зазнає тиску з кількох фронтів водночас. На сході лежать Гори Редріджу — домівка войовничих зграй гнолів і орків-нападників із клану Блекрок, які випробовують людську оборону. За південною річкою височіє похмурий ліс Сутінколісся з його хижими жахіттями нежиті. Ближче до дому розбійники Братства Дефіас нишпорять дикими таборами, прагнучи скористатися будь-якою прогалиною в лінії оборони варти."}},faq={{q="Що таке Вежа Ріджпойнт?",a="Вежа Ріджпойнт — укріплена розвідувальна вежа Варти Стормвінда на сході Лісу Елвінн. Це передовий сторожовий пост, що має попереджати королівство про ворожі вторгнення й захищати від них.",al={"вежа ріджпойнт елвін","що це за вартова вежа","східна вежа елвіну"}},{q="Хто тримає вежу й несе в ній службу?",a="У вежі стоїть гарнізон вартових і розвідників, вірних королівству Стормвінд, під командуванням Варти Стормвінда.",al={"хто у вежі ріджпойнт","хто володіє вежею ріджпойнт"}},{q="Що виглядає гарнізон?",a="Вартові пильнують гнолів і орків-загарбників, що сунуть із Гір Редріджу, нежить, що приходить з отруєних гаїв Сутінколісся, і розбійників Дефіас із прихованих лісових таборів неподалік.",al={"вороги біля ріджпойнта","хто нападає на ріджпойнт","чому тут вежа"}},{q="Де розташована Вежа Ріджпойнт?",a="Вона стоїть на узвишші на далекому сході Лісу Елвінн, біля кордонів, що сполучають Елвінн і з Горами Редріджу, і з Сутінколіссям.",al={"розташування вежі ріджпойнт","де ріджпойнт"}}},fp="16,309,30.471.0,24.421.0,25.209.0,32.143.0,45.206.0,34.155.0"}
P.entries["subzone:rocktusk-farm"] = {n="Ферма Кам'яного Ікла",s="Ферма Кам'яного Ікла — невелике свиняче ранчо на півночі Дуротару, трохи далі дорогою за брамою Оргріммара. Притулена до укріплених підступів до столиці, садиба постачає мешканцям міста конче потрібне м'ясо та харчі.",h="Ферма Кам'яного Ікла — невелике свиняче ранчо на півночі Дуротару, трохи далі дорогою за брамою Оргріммара.",kw={"ферма кам'яного ікла","свині","ферма","харчі","оргріммар","кулінарія","дуротар"},ang={["faction:Horde"]="Свині, вирощені тут, просто за столицею, — важливий харч для воїнів і робітників, що служать в Оргріммарі.",["profession:Cooking"]="Свиней із цієї ферми цінують кухарі Орди, яким потрібні свіжа свинина, реберця та смачні шматки для смаження."},sec={{t="Харчі для столиці",b="Вирвана в посушливій землі Дуротару, Ферма Кам'яного Ікла розводить витривалих свиней, пристосованих до суворого пустельного клімату. Через горезвісно сухий і кам'янистий ґрунт Дуротару вирощувати збіжжя важко, тож свинарські ферми — життєво важлива нитка, що годує дедалі численніше населення Оргріммара. Притулена до укріплених околиць столиці, садиба тішиться безпекою, якої рідко знайдеш у суворих нетрях червоних каньйонів."}},faq={{q="Для чого потрібна Ферма Кам'яного Ікла?",a="Ферма Кам'яного Ікла — свиноферма. Тут вирощують свиней, щоб постачати свіже м'ясо й харчі до сусідньої столиці, Оргріммара, де орної землі обмаль.",al={"що це за місце","призначення ферми кам'яного ікла","чому тут свині"}},{q="Де розташована Ферма Кам'яного Ікла?",a="Ферма — на півночі Дуротару, трохи на південний захід від головної брами Оргріммара, під скелястими кручами.",al={"де ферма кам'яного ікла","розташування ферми кам'яного ікла"}},{q="Чи захищена ферма від диких звірів?",a="Близькість до Оргріммара й патрулів Орди робить її безпечнішою за більшість віддалених господарств Дуротару, хоча на околицях досі нишпорять дикі звірі й шкідники.",al={"чи безпечна ферма кам'яного ікла","небезпеки ферми кам'яного ікла"}}},fp="13,241,26.449.0,31.159.0,31.140.0,34.187.0"}
P.entries["subzone:roguefeather-den"] = {n="Лігво Диких Пер",s="Лігво Диких Пер — печера в південно-центральній частині Тисячі Голок. Вона кишить лютими верескливими гарпіями й служить укріпленим гніздовищем, де зграя ховає награбовані припаси в темних закутках.",h="Лігво Диких Пер — печера в південно-центральній частині Тисячі Голок.",kw={"лігво диких пер","гарпії","печера","тисяча голок","гніздовище","мерехтливі низини"},ang={["faction:Horde"]="Для мандрівників з Орди, що йдуть довгим шляхом до Мерехтливих Низин, войовнича зграя з Лігва Диких Пер — постійна загроза нападу з повітря й засідок на дні південного каньйону."},sec={{t="Гніздовище серед каньйонів",b="Видовбане в стрімких пісковикових кручах південної Тисячі Голок, Лігво Диких Пер — мерзенне гніздовище місцевих гарпій. Відомі своїм диким вереском і агресивною охороною території, гарпії вважають печеру водночас надійним прихистком і коморою, пильно стережучи зібрану їжу й крадені припаси, звалені в темних закутках у глибині печери."}},faq={{q="Що таке Лігво Диких Пер?",a="Це невелика печера в південних скелях Тисячі Голок, що слугує гніздовищем і коморою для гарпій Диких Пер, які ревно бережуть свої володіння.",al={"що це за печера","лігво диких пер інформація","де дикі пера"}},{q="Хто живе в печері?",a="Печеру заполонили ворожі верескливі гарпії, що люто боронять свої гнізда й зібрані харчі від будь-яких непроханих гостей.",al={"хто живе в лігві диких пер","моби лігва диких пер"}},{q="Що зберігається глибоко в Лігві Диких Пер?",a="У глибині печери гарпії тримають запаси знайденої й краденої їжі, яку з безугавною лютістю захищають.",al={"що в глибині печери","їжа диких пер"}}},fp="16,246,22.378.0,25.157.0,32.138.0,42.133.0"}
P.entries["subzone:rogues-quarter"] = {n="Квартал Розбійників",s="Квартал Розбійників — тьмяно освітлений район у південно-східному крилі Андерсіті. Тут збираються розвідники, вбивці й таємні агенти Відступників, а також ремісники, що їм допомагають.",h="Квартал Розбійників — тьмяно освітлений район у південно-східному крилі Андерсіті.",kw={"квартал розбійників","андерсіті","розбійники","отрути","відступники","шкірництво"},ang={["class:Rogue"]="Для вбивць Відступників і всієї Орди цей квартал — найкраще місце, щоб опанувати скритність, вивчити бойові прийоми й запастися складниками для смертельних отрут.",["profession:Engineering"]="Умільці навідуються до Кварталу Розбійників, щоб вивчати креслення й майструвати бомби, пристрої та механічні знаряддя, які так полюбляють таємні агенти."},sec={{t="Тіні Андерсіті",b="Квартал Розбійників, що ховається в південно-східній частині підземного міста, збирає найхитріших і найсмертоносніших із тих, хто вижив серед Відступників. За життя чимало з них були злодіями, кишеньковими злодюжками чи безшумними клинками королівства Лордерон; після смерті їхнє вміння скрадатися, труїти й заплутувати сліди знадобилося, щоб захищати молоду державу від Погибелі й Багряного Хрестового Походу. У районі тихо вирує життя: це потаємний прихисток, де агенти гострять кинджали, варять смертельні отрути й відточують таємні навички."},{t="Знаряддя ремесла",b="Окрім скритності й убивств, у Кварталі Розбійників живуть особливі ремесла, що допомагають вижити під прикриттям. Майстри навчають тут подорожніх шкірництва й здирання шкур, перетворюючи сирі шкури на легкі, безшумні обладунки. Кам'яними залами відлунює брязкіт інженерних верстатів, де умільці збирають пристрої, а польові лікарі й аптекарі навчають першої допомоги й продають смертельні отрути, без яких не обійтися в таємній роботі."}},faq={{q="Де розташований Квартал Розбійників?",a="Квартал Розбійників — у південно-східній частині зовнішнього кільця Андерсіті, за Торговим Кварталом.",al={"розташування кварталу розбійників","де квартал розбійників","квартал розбійників підміська"}},{q="Які наставники тут є?",a="У кварталі є наставники розбійників, а також учителі шкірництва, білування, інженерії й першої допомоги. Поряд стоять і продавці отрут, що постачають реагенти.",al={"наставники кварталу розбійників","наставник розбійників підміська","хто навчає в кварталі розбійників"}},{q="Навіщо Відступникам окремий квартал для розбійників?",a="Оточені ворогами на кшталт Погибелі й Багряного Хрестового Походу, Відступники значною мірою покладаються на шпигунство, вбивства й тактику «вдар і тікай», щоб боронити свої землі, тож таємні агенти для них життєво важливі.",al={"навіщо відступникам розбійники","вбивці відступників","лор розбійників підміської"}}},fp="15,226,24.540.0,18.454.0,37.114.0,32.181.0,61.226.0"}
P.entries["subzone:roland-s-doom"] = {n="Погибель Роланда",s="Погибель Роланда — покинута, оповита тінню шахта в південно-східних пагорбах Сутінколісся, трохи на схід від Гнилого Саду. Колись звичайна копальня, тепер вона сумно відома як небезпечне лігво лютих воргенів.",h="Погибель Роланда — покинута, оповита тінню шахта в південно-східних пагорбах Сутінколісся, трохи на схід від...",kw={"погибель роланда","шахта","воргени","коса елуни","велінде старсонг","сутінколісся"},ang={["profession:Mining"]="Колись тут добували руду, але кожен рудошукач, що наважиться змахнути кайлом, швидко зрозуміє: єдині жили в Погибелі Роланда — це жили кровожерливих воргенів.",["race:NightElf"]="Трагічна загибель жриці Велінде Старсонг у цій шахті робить Погибель Роланда місцем сумних роздумів для нічних ельфів, що з'ясовують долю своєї родички й невловимої Коси Елуни."},sec={{t="Лігво тіней і дикості",b="Погибель Роланда, вирубана в кряжах на схід від Гнилого Саду, давно перестала бути робочою шахтою. Натомість вона стала жорстоким плацдармом для зграї воргенів Найтбейн, яку очолюють такі звірі, як Кишкодер і Нефару. Темні тунелі відлунюють утробним гарчанням і смердять вогкою землею та кров'ю, тож для необачних мандрівників це один із найнебезпечніших закутків усього Сутінколісся."},{t="Загибель Велінде Старсонг",b="Справжня трагедія Погибелі Роланда похована глибоко в її тунелях. Саме тут знайшла свою смерть нічна ельфійка, жриця Велінде Старсонг, що несла Косу Елуни — давній артефакт величезної й непередбачуваної сили. Згодом наляканий мандрівник Тремтій натрапив у шахті на косу й ненароком спричинив навалу лютих воргенів, а також привів у Сутінколісся смертоносних Темних Вершників. Розкопана земля в шахті досі може розбудити неспокійний дух Велінде, і він розповість про її останні хвилини."}},faq={{q="Що таке Погибель Роланда?",a="Погибель Роланда — зруйнована, покинута копальня на південному сході Сутінколісся, на схід від Гнилого Саду. Нині її заполонили люті воргени Найтбейн.",al={"де погибель роланда","що це за шахта"}},{q="Звідки в копальні воргени?",a="Воргени заполонили копальню після втрати Коси Елуни. Нині в її вологих штольнях облаштували лігво могутні звірі зграї Найтбейн, зокрема Нефару й Кишкодер.",al={"чому тут воргени","хто живе в погибелі роланда"}},{q="Хто така Велінде Старсонг і як вона пов'язана з цим місцем?",a="Велінде Старсонг — жриця Елуни з нічних ельфів, що орудувала Косою Елуни в боях із демонами Сквернолісся. Її мандри привели її через море до Сутінколісся, де вона загинула саме в цій копальні, а Коса лишилася тут.",al={"велінде старсонг погибель роланда","хто тут помер"}},{q="Яку роль у історії Погибелі Роланда відіграє Тремтій?",a="Тремтій увійшов до Погибелі Роланда й знайшов закопану Косу Елуни. Його втручання ненароком випустило в Сутінколісся ще більше воргенів і привабило в цей край зловісних Темних Вершників, наразивши ліс на ще більшу небезпеку.",al={"тремтій шахта","коса тремтія"}}},fp="13,225,29.390.0,28.522.1,22.157.0,37.200.1,64.240.1,53.225.1"}
P.entries["subzone:rolling-plains"] = {n="Хвилясті Рівнини",s="Хвилясті Рівнини розкинулися на південних просторах Малгору, між Селом Бладгуф і кордоном Пусток. На цих обвітрених пасовищах буяють стада дичини, та вони ж вимагають постійної пильності через ватаги кентаврів, що нишпорять довкола, і агресивних гарпій.",h="Хвилясті Рівнини розкинулися на південних просторах Малгору, між Селом Бладгуф і кордоном Пусток.",kw={"хвилясті рівнини","малгор","кентаври","гарпії","полювання","кодо","довгоступи"},ang={["class:Hunter"]="Із рясними стадами кодо, довгоступів, вовків і пум Хвилясті Рівнини — ідеальна дика місцина, щоб відточувати вміння слідопита, запасатися харчем і приборкувати перших звірів-супутників.",["race:Tauren"]="Хвилясті Рівнини дають щойно об'єднаним племенам життєво важливі мисливські угіддя, та вторгнення одвічних ворогів-кентаврів так близько до Села Бладгуф робить охорону цього південного коридору питанням виживання племені."},sec={{t="Серце південного Малгору",b="Простягаючись на південь від Села Бладгуф до природних земляних воріт у Пустки, Хвилясті Рівнини втілюють безмежні простори тауренської батьківщини. Край кишить дичиною, без якої племенам не вижити: тут водяться степові вовки, стада кодо, рівнинні пуми й прудкі довгоступи. Для молодих мисливців, що доводять свою вартість старійшинам, ці розлогі савани — незамінний полігон, де випробовують уміння вистежувати, терпіння й шану до природи."},{t="Небезпеки, що насуваються",b="Попри природне кільце круч, що укріплює Малгор, Хвилясті Рівнини лишаються надзвичайно вразливими до зовнішніх загроз. Це єдиний кордон, де агресивним вершникам-кентаврам вдалося пробитися крізь оборонні рубежі й дошкуляти подорожнім і мисливським загонам. На додачу в східних кручах гніздиться зграя хижих гарпій Вітрофурій, що кидаються згори на заблукалу дичину й беззахисні кочові табори."}},faq={{q="Які тварини водяться на Хвилястих Рівнинах?",a="Пустки живлять розмаїття місцевих звірів: тут блукають стада диких кодо, бігають прудкі довгоступи, нишпорять степові вовки й підкрадаються рівнинні кугуари. Ці звірі дають племенам Села Бладгуф м'ясо, шкури й жили.",al={"тварини хвилястих рівнин","моби хвилястих рівнин","звірі рівнин мулґору"}},{q="Звідки в цій частині Малгору кентаври?",a="Хвилясті Рівнини межують зі східними перевалами до Пусток, тож це єдиний край Малгору, куди кентаврам-нападникам удалося прорватися. Їхні вершники-розвідники безперестанку нишпорять рівнинами, промацуючи оборону тауренів і загрожуючи самотнім мисливцям.",al={"чому кентаври в мулґорі","кентаври хвилястих рівнин","кентаври-розвідники"}},{q="Які ще ворожі істоти загрожують рівнинам?",a="Окрім блукаючих розвідників-кентаврів, на східних кручах краю гніздиться небезпечна зграя гарпій Вітрофурій, що полюють на необачних мандрівників і дошкуляють місцевим звірам.",al={"гарпії хвилястих рівнин","небезпеки хвилястих рівнин"}},{q="Де починаються й закінчуються Хвилясті Рівнини?",a="Рівнини займають більшу частину півдня Малгору — від Села Бладгуф до гірського кордону з Пустками.",al={"розташування хвилястих рівнин","де хвилясті рівнини","межі хвилястих рівнин"}}},fp="14,296,25.493.0,19.418.0,48.256.0,53.268.0,49.179.0,42.122.0"}
P.entries["subzone:rotting-orchard"] = {n="Гнилий Сад",s="Гнилий Сад — сплюндрований, покинутий фруктовий сад на півдні Сутінколісся. Колись він давав урожай сусідньому Даркширу, а тепер занепав і кишить ненажерливими вовкоподібними хижаками — зграєю Найтбейн.",h="Гнилий Сад — сплюндрований, покинутий фруктовий сад на півдні Сутінколісся.",kw={"гнилий сад","воргени","нічна згуба","марус","сутінколісся"},ang={["class:Hunter"]="Покручені дерева й зруйновані будівлі — чудове місце для полювання, але хижацьке чуття й чаклунство зграї Найтбейн перетворюють його на засідку, яка от-от спрацює.",["faction:Alliance"]="Воргени Найтбейн, що засіли в Гнилому Саду, — пряма хижацька загроза хиткій безпеці Даркшира, який лежить зовсім поруч, трохи далі дорогою."},sec={{t="Лігво Найтбейн",b="Гнилий Сад, що лежить на схід від зруйнованого Хутора Йорґенів і на захід від Цвинтаря Тихих Садів, — похмуре свідчення занепаду Сутінколісся. Дерева вгинаються під зморщеними, зіпсованими плодами, а напіврозвалені стодоли й господарські будівлі воргени Найтбейн перетворили на грубі табори. Переслідувачі Найтбейн никають покрученими хащами, а темні чаклуни — Тіньові Ткачі — плетуть зловісну магію серед трухлявих колод. Зграя кориться своєму лютому ватажкові Марусу, що никає довколишніми лісами, стережучи захоплені володіння."}},faq={{q="Хто живе в Гнилому Саду?",a="Сад цілком заполонила зграя Найтбейн — угруповання ненажерливих воргенів. Тут і хитрі нишпорки — Скрадачі Найтбейн, і темні чаклуни — Тіньові Ткачі Найтбейн, і їхній ватажок Марус, що блукає довкола.",al={"моби гнилого саду","хто живе в гнилому саду","що в гнилому саду"}},{q="Де в Сутінколіссі розташований Гнилий Сад?",a="Гнилий Сад лежить на півдні Сутінколісся, на південний захід від містечка Даркшир, якраз між зруйнованим Хутором Йорґена на заході й Цвинтарем Тихих Садів на сході.",al={"розташування гнилого саду","де гнилий сад","як знайти гнилий сад"}},{q="Хто очолює воргенів у цьому саду?",a="Ватажок тутешньої зграї воргенів — Марус. Він сходжує землі між гниючим садом і своїм лігвом неподалік, люто боронячи володіння зграї.",al={"бос гнилого саду","ватажок зграї марус","хто веде воргенів"}},{q="Чи завжди тут хазяйнували чудовиська?",a="Ні. Як і багато довколишніх господарств Сутінколісся, колись це була прибуткова ферма й плодовий сад, що годували місцевих людей, доки темні прокляття й надприродні жахіття не охопили край і не прогнали фермерів.",al={"історія саду","чому сад гниє"}}},fp="15,253,20.573.0,42.231.0,49.197.0,37.172.0,42.223.0"}
P.entries["subzone:royal-gallery"] = {n="Королівська Галерея",s="Захована у Фортеці Стормвінда за внутрішнім садом, Королівська Галерея — тиха зала пам'яті. Тут стоять чудові статуї й витончені мистецькі твори на честь видатних постатей з історії королівства й Великого Альянсу.",h="Захована у Фортеці Стормвінда за внутрішнім садом, Королівська Галерея — тиха зала пам'яті.",kw={"королівська галерея","фортеця стормвінда","статуї","ллейн рінн","праудмур","стормвінд"},ang={["faction:Alliance"]="Галерея — тихий пам'ятник жертвам Альянсу, що вшановує легендарних провідників на кшталт Дейліна Праудмура й короля Ллейна.",["race:Human"]="Для людей Стормвінда ця зала шанує спадщину дому Ріннів і дому Фордрагонів, зберігаючи їхню королівську пам'ять у стінах фортеці."},sec={{t="Зала героїв",b="Королівська Галерея прилягає до Королівської Бібліотеки, одразу за зеленим внутрішнім садом Фортеці Стормвінда. У залі стоять статуї велетнів, що творили історію краю: короля Ллейна Рінна, полеглого правителя Стормвінда; Великого Адмірала Дейліна Праудмура з Кул Тірасу; і Мари Фордрагон, пращурки нинішнього регента. Це водночас приватний музей шляхетної спадщини й тихий прихисток для придворних гостей на кшталт Леді Дени Кеннеді."}},faq={{q="Де розташована Королівська Галерея?",a="Королівська Галерея — у Фортеці Стормвінда. Пройдіть фортецею повз невеликий внутрішній дворик-сад: галерея поруч із Королівською Бібліотекою.",al={"розташування королівської галереї","як дістатися до королівської галереї","де вона"}},{q="Яких історичних постатей тут вшановано?",a="У галереї стоять величні статуї короля Ллейна Рінна, Великого Адмірала Даліна Праудмура й Мари Фордрагон, що прославляють родовід і звитягу королівства та його найближчих союзників.",al={"статуї королівської галереї","чиї це статуї","кого тут вшановано"}},{q="Кого можна зустріти в галереї?",a="Тут часто буває Леді Дена Кеннеді, що милується витонченим мистецтвом і задумливою атмосферою галереї.",al={"хто тут","нпс королівської галереї","леді дена кеннеді"}},{q="Чим Королівська Галерея відрізняється від Королівської Бібліотеки?",a="Вони розташовані поруч у королівському крилі Фортеці Стормвінда, але це окремі зали. У бібліотеці — королівські архіви й учені, а галерея присвячена мистецтву й меморіальній скульптурі.",al={"королівська галерея проти бібліотеки","чи це частина бібліотеки"}}},fp="13,249,16.443.0,35.155.0,47.187.0,38.105.0,71.221.0"}
P.entries["subzone:royal-library"] = {n="Королівська Бібліотека",s="Захована глибоко в кам'яному крилі Фортеці Стормвінда, Королівська Бібліотека зберігає спільну пам'ять, сувої хронік і трактати королівства. Під пильним оком Головного Бібліотекаря Мілтона Шіфа на її полицях лежать важливі записи про давні війни, загублені легенди й краї за морем.",h="Захована глибоко в кам'яному крилі Фортеці Стормвінда, Королівська Бібліотека зберігає спільну пам'ять, сувої...",kw={"королівська бібліотека","мілтон шіф","книга медіва","архів","фортеця стормвінда","стормвінд"},ang={["class:Mage"]="Для знавців таємних мистецтв бібліотека пропонує рідкісні першоджерела про минуле Тірісфалю, давні полювання на драконів і спадщину Останнього Хранителя.",["faction:Alliance"]="Полиці зберігають засадничі договори й воєнні хроніки, що поєднують людей, дворфів та ельфів крізь покоління війн."},sec={{t="Скарбниця королівства",b="Поки Фортеця Стормвінда наїжачується закутими в броню вартовими й двірськими інтригами, Королівська Бібліотека дарує острівець ученої тиші. Під наглядом Мілтона Шіфа зала служить головним архівом історії південних людей: тут зберігаються вцілілі тексти з часів до Першої війни, нові воєнні хроніки й повернуті фоліанти. Учені Альянсу, жерці й мандрівники можуть вільно гортати відкриті трактати — від створення першого Альянсу Лордерону до недавньої появи Орди Тралла в Калімдорі."},{t="Тіні між полицями",b="Бібліотеку не завжди оминали зовнішні чвари. Після Другої війни в її сховищах зберігали небезпечну Книгу Медіва, і по неї зухвало вдерлися в замок лазутчики з Альтераку та лицарі смерті, яких послав Нер'жул."}},faq={{q="Де розташована Королівська Бібліотека?",a="Вона у Фортеці Стормвінда — королівській твердині в східній частині Стормвінда. Пройшовши величний вестибюль фортеці, ідіть коридорами до крил учених і архівів.",al={"де бібліотека","розташування бібліотеки стормвінда","як знайти бібліотеку"}},{q="Хто керує бібліотекою?",a="Головний бібліотекар — Мілтон Шіф. Він опікується архівними записами й допомагає вченим і шукачам пригод, що шукають утрачені томи чи певні трактати королівства.",al={"хто бібліотекар","головний бібліотекар","мілтон шиф"}},{q="Які книги тут можна прочитати?",a="Відвідувачі можуть прочитати історичні праці про Альянс Лордерона, Вартових Тірісфалю, наслідки Другої війни й звіти про Нову Орду, а також історії Стормвінда й Альтераку.",al={"книги бібліотеки","книги з лором","що почитати"}},{q="Чому тут зберігалася Книга Медіва?",a="Після поразки Орди в Другій війні небезпечну книгу заклять сховали в Королівській Бібліотеці. Проте її викрали змовники з Альтераку, і їхні шляхи перетнулися з лицарями смерті Терона Ґорфіенда, які готували напад, щоб здобути книгу для Нер'жула.",al={"книга медіва стормвінд","викрадена книга медіва"}}},fp="13,302,25.545.0,25.242.0,35.204.0,21.167.0,37.222.0,37.272.0"}
P.entries["subzone:royal-quarter"] = {n="Королівський Квартал",s="Королівський Квартал — відокремлений осідок влади в Андерсіті й тронна зала Леді Сильвани Віндраннер. Тут Королева Баньші керує Відступниками разом із повелителем жаху Варіматрасом, що втілює її волю, під охороною добірного загону Королівських Стражів Жаху.",h="Королівський Квартал — відокремлений осідок влади в Андерсіті й тронна зала Леді Сильвани Віндраннер.",kw={"королівський квартал","андерсіті","сильвана","варіматрас","темна леді","тронна зала"},ang={["faction:Horde"]="Посланці Орди, що навідуються до Королівського Кварталу, часто дивляться на радника Темної Леді, натрезима, з глибокою підозрою й сумніваються, чи мудро довіряти демонові в самому серці столиці Орди.",["race:Undead"]="Королівський Квартал — серце незалежності Відступників: тут Сильвана Віндраннер та її поплічник, жахолорд, прокладають шлях у майбутнє для свого визволеного народу."},sec={{t="Осідок Темної Леді",b="Королівський Квартал, захований за височенними арками й тінистими коридорами й відомий також як Зала Темної Леді, — політичний і військовий нервовий центр Відступників. Сильвана Віндраннер тримає двір у цій печерній підземній залі, плануючи виживання своєї нежиті з вільною волею й знищення Погибелі. Важко закуті Королівські Стражі Жаху стоять на варті вздовж підвищення, дбаючи, щоб непрохані гості й можливі вбивці ніколи не дісталися до їхньої королеви."},{t="Небезпечний союз",b="Поруч із Темною Леді стоїть натрезим Варіматрас — несподівана й тривожна постать у самому серці Андерсіті. Щоб урятувати власне життя, жахолорд під час громадянської війни в руїнах Лордерона перейшов на бік Сильвани й присягнув її справі. З Королівського Кварталу він командує скрадачами смерті й координує оборону королівства. Його тактична хитрість добре служить Відступникам, та демонічна природа змушує багатьох союзників з Орди сумніватися в його справжній вірності."}},faq={{q="Хто править із Королівського Кварталу?",a="Леді Сильвана Віндраннер, Королева Баньші, править Відступниками з трону в Королівському Кварталі. Поруч із нею — натрезим Варіматрас, що присягнув їй на вірність під час відвоювання Лордерона.",al={"хто в королівському кварталі","володар тронної зали андерсіті","хто править андерсіті"}},{q="Чому в тронній залі стоїть жахолорд?",a="Варіматрас здався Сильвані Віндраннер, коли вона відвойовувала столицю Лордерона, а потім зрадив своїх братів Детерока й Балназзара. Він урятував собі життя, присягнувши Сильвані на вірність, і тепер служить її виконавцем і очільником розвідників.",al={"чому тут варіматрас","жахолорд в андерсіті","чому демон у королівському кварталі"}},{q="Хто такі Королівські Вартові Жаху?",a="Королівські Вартові Жаху — добірні охоронці-Відступники, вибрані саме для того, щоб стерегти Леді Сильвану й Королівський Квартал. Це одні з найдисциплінованіших і найсмертоносніших захисників Андерсіті.",al={"жахолорди-вартові","вартові тронної зали підміської","королівська варта жаху"}},{q="Яку ще роль відіграє ця зала?",a="Окрім того, що це головна зала для аудієнцій у Темної Леді й Варіматраса, у Королівському Кварталі є розпорядники битв, що збирають бійців Орди для далеких походів і стратегічних сутичок по всьому Азероту.",al={"яка ще роль зали","що ще в королівському кварталі","майстри битв королівського кварталу"}}},fp="13,267,25.479.0,20.495.0,33.216.0,53.245.0,31.192.0,44.215.0"}
P.entries["subzone:ruined-reaches"] = {n="Зруйновані Простори",s="Зруйновані Простори — підступне південне узбережжя Азшари біля кордону з Дуротаром. Тут повно прадавніх руїн, що розсипаються, розбитих кораблів і зубчастих мілин, а пляжі заполонили агресивні прибережні хижаки. Посеред цього безлюддя на кручі високо над прибоєм тулиться невеличка застава гномів.",h="Зруйновані Простори — підступне південне узбережжя Азшари біля кордону з Дуротаром.",kw={"зруйновані простори","азшара","ґаджетспрінґ","гноми","інженерія","мурлоки","макрури"},ang={["profession:Engineering"]="Самотня майстерня Блімо й Джубі Ґаджетспрінґ — цінне джерело деталей і припасів для інженерів, що досліджують дикі землі Азшари.",["race:Gnome"]="Побачити високотехнологічну гномівську оселю, що процвітає на ворожих кручах Азшари, — приємне нагадування про гномівську винахідливість далеко від Айронфорджа."},sec={{t="Побите узбережжя",b="Зруйновані Простори, що тягнуться південними кордонами Азшари просто на північ від Дуротару, — лабіринт скелястих бухт, стрімких урвищ і піску, всіяного уламками. Як і на Зубчастому Рифі далі на півночі, приховані мілини роблять плавання тут украй небезпечним, і на березі лежить чимало розбитих суден. У водах і на пляжах аж кишать ворожі звірі, зокрема ревниві до своїх земель мурлоки, люті гідри й закуті в панцир макрури, тож іти суходолом не менш небезпечно, ніж пробиратися крізь прибій."},{t="Застава Ґаджетспрінґів",b="На західній кручі над пляжами несподівано тулиться осередок майстровитої цивілізації — гномівська майстерня, до якої веде крута стежка з материкової частини Азшари. Цю заставу тримають Блімо й Джубі Ґаджетспрінґ, які пропонують мандрівним шукачам пригод інженерні деталі й усякий крам. Усередині є підйомник до житлових кімнат із трьома ліжками, і хто — та й чи хтось узагалі — спить на третьому, лишається маленькою домашньою загадкою."}},faq={{q="Де розташовані Зруйновані Простори?",a="Вони утворюють найпівденнішу прибережну смугу Азшари, на межі з північним краєм Дуротару. Це піщані пляжі, прибережні затоки й скелі під кручами суходолу.",al={"розташування зруйнованих просторів","де зруйновані простори","як дістатися до зруйнованих просторів"}},{q="Які небезпеки чатують на цьому узбережжі?",a="На пляжах і мілинах живуть ворожі істоти — здебільшого агресивні племена мурлоків, багатоголові гідри й макрури, що причаїлися на припливних мілинах.",al={"моби зруйнованих просторів","що тут живе","монстри зруйнованих просторів"}},{q="Хто живе в гномській споруді на скелях?",a="Там живуть і працюють Блімо та Джубі Ґаджетспрінґ. Вони тримають невеличку крамницю з інженерними деталями й товарами для мандрівників, що пробираються пустельним узбережжям.",al={"гноми зруйнованих просторів","будинок гаджетспрінг","хто живе в гномському будинку"}},{q="Чому тут стільки корабельних уламків?",a="Як і біля сусіднього Зубчастого Рифу, прибережні води всіяні мілкими скелями й прихованими небезпеками, що раз у раз заскочують кораблі зненацька й розбивають їх об скелі.",al={"уламки кораблів ашару","чому розбиті кораблі","уламки зруйнованих просторів"}}},fp="14,331,16.490.0,24.465.0,37.184.0,43.169.0,49.161.0,38.171.0"}
P.entries["subzone:ruins-of-aboraz"] = {n="Руїни Абораза",s="Руїни Абораза — давні кам'яні рештки часів Ґурубаші на південно-східних кручах Долини Стренглторну. Колись ці тераси були частиною неосяжної імперії тролів джунглів, а нині, розсипаючись, правлять за відлюдний сховок для знахаря-ренегата Занзіла Вигнанця та його одурманених рабів.",h="Руїни Абораза — давні кам'яні рештки часів Ґурубаші на південно-східних кручах Долини Стренглторну.",kw={"руїни абораза","занзіл вигнанець","єнніку","вуду","тролі","долина стренглторну"},ang={["faction:Alliance"]="Капери й найманці Альянсу частенько натрапляють на справи Занзіла, коли женуться за боржниками чи нагородами, пов'язаними з гоблінами й піратами Буті Бею.",["race:Troll"]="Для племені Темного Списа Абораз — відверта образа: вигнанець спотворює вуду, щоб поневолювати тролів, і тримає юного Єнніку в заручниках на прадавніх землях Ґурубаші."},sec={{t="Володіння знахаря",b="На кручах на південний схід від Руїн Джубувалу й на південь від Шахти Кришталевої Жили вивітрене каміння Абораза перетворилося на алхімічний полігон. Занзіла Вигнанця прогнали і місцеві племена, і жителі материка, тож він сховався тут, щоб варити сильні зілля, які затьмарюють розум, і отруйні еліксири. У кам'яних дворах Занзіл цілковито владарює над моторошним звіринцем слуг: тут і гулі-нежить, що човгають ногами, і зіпсовані тролі-раби, і навіть підкорені наги з узбережжя."},{t="Пішаки й бранці",b="Дивні зілля Занзіла не просто отруюють тіло — вони ламають волю. Серед загублених душ, що блукають терасами, є й зачарований юнак із племені Темного Списа Єнніку, чий розум досі скутий чаклунством Занзіла. Поруч із ним безцільно тиняється Чакі «Криворукий» — піратський боржник, що втік від стягувачів «Морського Вовка» Маккінлі з Буті Бею, а тепер, напоєний Занзіловими настоянками, став бездумним вартовим цього місця."}},faq={{q="Хто править Руїнами Абораза?",a="Руїнами володіє Занзіл Вигнанець — вигнаний знахар, сумно відомий по всій Долині Стренглторну своєю темною алхімією й могутніми зіллями, що підкоряють розум.",al={"хто керує аборазом","бос абораза","хто в руїнах абораза"}},{q="Чому тут разом наги й гулі?",a="Особливі суміші Занзіла дають йому змогу підкоряти розум і оживляти трупи. Він скорив тролів-вигнанців, піднятих гулів джунглів і прибережних наг, щоб ті беззаперечно стерегли його терасу.",al={"чому тут наги","гулі абораза","моби абораза"}},{q="Де розташовані Руїни Абораза?",a="Вони на високих кручах на південному сході Долини Стренглторну, на південь від Шахти Кришталевої Жили й трохи на південний схід від Руїн Джубувалу, над східним морем.",al={"розташування абораза","де руїни абораза","як дістатися до абораза"}}},fp="15,297,23.525.0,18.425.1,35.167.0,44.199.0,38.165.0"}
P.entries["subzone:ruins-of-alterac"] = {n="Руїни Альтераку",s="Засипані снігом Руїни Альтераку — усе, що лишилося від Міста Альтерак, колись гордої гірської столиці Королівства Альтерак. Після зради короля Ейдена Перенольда в Другу війну королівство вигнали з Альянсу й запровадили там воєнний стан, а зруйновану твердиню тепер заполонили брутальні огри Трощихребти.",h="Засипані снігом Руїни Альтераку — усе, що лишилося від Міста Альтерак, колись гордої гірської столиці...",kw={"руїни альтераку","альтерак","перенольд","трощихребти","огри","муґ'тол","друга війна"},ang={["faction:Horde"]="Занепале місто — відлуння давніх союзів Старої Орди, а нині Відступники можуть збирати тут магічні реліквії, поки огри Трощихребти дивляться деінде.",["race:Human"]="Для людей Альянсу руїни — сумне нагадування про людську слабкість і зраду в Другу війну, коли боягузтво Перенольда розірвало братерство Семи Королівств."},sec={{t="Зрада королівства",b="Альтерак колись був незалежним людським королівством, що постало з давньої імперії Аратор і височіло над гірськими торговими шляхами. У Другу війну, боячись загинути від рук Старої Орди, король Ейден Перенольд таємно уклав угоду з орками. Коли після боїв під Каер Дарроу зраду викрили, Альянс Лордерону відповів швидко. Король Теренас Менетіл II запровадив у місті воєнний стан і скинув Перенольда. Величні укріплення, церква й палац занепали, а мешканці розбіглися або подалися в розбійники."},{t="Огрська окупація",b="Вцілілі альтерацькі вельможі та свавільні вояки створили Синдикат і вели партизанську війну з таких містечок, як Странбрад, але свою прадідівську столицю втратили цілком. Нині серед розбитих валів, палацових зал і потрощених баліст живуть огри Трощихребти на чолі з Муґ'толом. Ні Синдикат, ні людські захисники Саутшора так і не змогли відвоювати занепале місто, тож його вежі, що розсипаються, і покинуті сховища — небезпечні місця для шукачів скарбів і мародерів."}},faq={{q="Чому Альтерак зруйновано?",a="Під час Другої війни король Ейден Перенольд уклав союз з оркською Ордою, що вдерлася в королівство, щоб уберегти свої землі. Альянс Лордерона викрив зраду, вторгся в Місто Альтерак, зруйнував його укріплення й запровадив у королівстві воєнний стан.",al={"чому альтерак у руїнах","що сталося з альтераком","падіння альтерака"}},{q="Хто тепер живе в руїнах?",a="Палац, мури й засніжені двори захопили огри-Трощихребти на чолі з Муґ'толом. А на північних мурах тихенько сидить заповзятливий гоблін-продавець алхімічного краму Бро'кін.",al={"хто контролює руїни альтерака","огри альтерака","хто в альтераку"}},{q="Як із цим місцем пов'язаний Синдикат?",a="Синдикат складається здебільшого з колишніх альтеракських аристократів і вояків, що втратили землі після розпуску королівства. Вони гірко мріють повернути Альтерак, але зі столиці їх вигнали огри-Трощихребти, тож тепер вони діють із застав на кшталт Странбрада.",al={"чи синдикат тут живе","зв'язок синдикату з альтераком"}},{q="Навіщо сюди приходять шукачі пригод з Альянсу?",a="Вояки Альянсу з Саутшора оголошують винагороди за ворожих огрів-Трощихребтів, що грабують на дорогах, а вельможі на півдні, як-от Граф Ремінгтон Ріджвелл, посилають у руїни агентів, щоб повернути втрачені родові реліквії, як-от Діадему Переноль.",al={"завдання альянсу руїни альтерака","нагорода крашрідж"}},{q="Чому ці руїни цікавлять Орду?",a="Леді Сильвана Віндраннер і Відступники пильно цікавляться артефактами, розкиданими по полеглому людському королівству, і посилають героїв у твердиню, де кишать огри, щоб здобути могутні реліквії, як-от Корону Волі.",al={"завдання орди руїни альтерака","сильвана альтерак"}}},fp="16,313,20.584.0,19.495.0,26.242.0,27.204.0,49.291.0,38.248.0,43.234.0"}
P.entries["subzone:ruins-of-andorhal"] = {n="Руїни Андоргала",s="Колись Андоргал був житницею північного Лордерону, звідки зерно розвозили по всьому краю, а тепер Руїни Андоргала лежать у самому серці Західних Чумних Земель як сплюндрована твердиня Некрополя. Зруйноване містечко, яким володарює ліч Арадж Призивач, кишить полчищами нежиті: гидотами, гулями й примарами.",h="Колись Андоргал був житницею північного Лордерону, звідки зерно розвозили по всьому краю, а тепер Руїни...",kw={"руїни андоргала","андоргал","арадж призивач","хромі","чума","культ проклятих","західні чумні землі"},ang={["class:Paladin"]="Для Лицарів Срібної Длані й паладинів усього Альянсу Андоргал — освячена земля, що обернулася кошмаром: саме тут чума отруїла лордеронські запаси зерна й прирекла північне королівство на загибель.",["race:Undead"]="Відступники дивляться на зруйноване місто з похмурою пам'яттю: чимало з тих, хто сьогодні ходить вулицями Андерсіті, колись були лордеронцями й самі їли отруєне зерно, зібране з довколишніх полів."},sec={{t="Серце чуми",b="Саме з Андоргала почалася чума нежиття в Лордероні: тут зерно, отруєне Культом Проклятих, пакували й розвозили по всьому людському королівству. Нині зруйноване місто — розлогий оплот Погибелі в Західних Чумних Землях. У серці руїн владарює Арадж Призивач, оточений гулями, кістяними жахами й велетенськими големами з плоті. Розвідзагони Багряного Хрестового Походу час від часу навідуються на околиці міста, та Погибель тримає зруйновані вулиці в залізному кулаці."},{t="Час, що розплітається",b="Окрім самої нежиті, Андоргал потерпає від дивних часових аномалій. Годинник на ратуші й покинуті кишенькові годинники, розкидані вулицями, навіки зупинилися на третій годині. Бронзова драконка Хромі, що знайшла прихисток у корчмі на краю руїн, досліджує часових паразитів, які загніздилися в зерносховищах. Схоже, Погибель втручається в самий плин часу, щоб змінити хід трагічного падіння міста."}},faq={{q="Хто править Руїнами Андоргала?",a="Руїнами керує Арадж Призивач — могутній ліч, що спрямовує дії Погибелі в цьому краї. Він засів у центрі міста в оточенні добірного авангарду кістяків-вартових і зшитих із плоті потвор.",al={"хто керує андорґалом","бос андорґала","арай закликач"}},{q="Чому в руїнах Хромі?",a="Хромі, прибравши подоби гномки, розслідує неприродні збурення в плині часу. Вона підозрює втручання довкола міських силосів і просить мандрівників допомогти розібратися.",al={"що робить хромі в андорґалі","чому тут хромі","хромі андорґал"}},{q="Чому всі годинники зупинилися на третій?",a="Годинник на ратуші й кишенькові годинники, знайдені серед уламків, зупинилися на третій годині. Можливо, це пов'язано з часовими збуреннями в Андоргалі, але точна причина не підтверджена.",al={"годинник на третій","зупинений годинник андорґала","чому о третій"}},{q="Чому Багряний Хрестовий Похід нападає на Андоргал?",a="Невеликі ударні загони з Багряних медиків, мисливців і заклиначів намагаються пробратися до міста. Фанатичні хрестоносці прагнуть повернути Лордерон і знищити Погибель, хоча їхні вилазки в укріплений центр рідко бувають успішними.",al={"багряний похід в андорґалі","патрулі багряних в андорґалі"}}},fp="17,325,19.543.0,15.488.1,32.212.0,32.185.0,48.193.0,45.245.0"}
P.entries["subzone:ruins-of-constellas"] = {n="Руїни Констелласа",s="Руїни Констелласа — уламки давнього поселення нічних ельфів у Скверноліссі, біля підніжжя Гори Гіджал. Нині колись священні землі заполонили сатири Нефритового Вогню, які жорстоко осквернили місячний колодязь поселення демонічною магією скверни.",h="Руїни Констелласа — уламки давнього поселення нічних ельфів у Скверноліссі, біля підніжжя Гори Гіджал.",kw={"руїни констелласа","сатири","нефритовий вогонь","місячний колодязь","ксаватрас","ксаварік","сквернолісся"},ang={["class:Druid"]="Видовище того, як Смарагдові ведмедолюди б'ються з демонічними загарбниками, робить Констеллас суворим нагадуванням про обітницю друїдів повернути рівновагу Скверноліссю.",["race:NightElf"]="Осквернення Констелласа та його місячного колодязя — кричуща образа для Елуни, і нічні ельфи мусять вигнати звідси сатирів Нефритового Вогню."},sec={{t="Осквернене святилище",b="Класичні кам'яні арки й розвалені площі Констелласа свідчать, що колись тут була ідилічна громада нічних ельфів. У Третю війну похід Палаючого Легіону крізь Сквернолісся зруйнував цей прихисток і відкрив його для демонічної скверни, що лишилася. Тепер над камінням панують мерзенні сатири Нефритового Вогню. На чолі з Ксаватрасом вони доглядають осквернений місячний колодязь, перетворюючи чисту воду на джерело отруйної сили скверни для свого володаря, лорда Ксаваріка."},{t="Боротьба за очищення",b="Осквернення Констелласа викликало рішучий опір захисників Калімдору. Друїдичні Смарагдові ведмедолюди б'ються із сатирами по всіх руїнах, намагаючись повернути ліс, а дослідники з нічних ельфів спостерігають за ними з табору неподалік, на південному сході. Щоб захистити свої мерзенні обряди й не підпустити непроханих гостей до Ксаватраса, сатири запечатали глибші проходи в руїнах непробивною стіною чарівного вогню."}},faq={{q="Чим був Констеллас до скверни?",a="Констеллас — давнє поселення нічних ельфів біля підніжжя Гори Гіджал. Його архітектура й місячний колодязь свідчать, що це був тихий гай, присвячений Елуні й природі, доки Палаючий Легіон не вдерся в ліс під час Третьої війни.",al={"історія констелласа","чим був констеллас","хто збудував констеллас"}},{q="Хто тепер тримає руїни?",a="Руїни займають сатири Нефритового Вогню на чолі з місцевим ватажком Ксаватрасом. Вони плекають демонічну енергію по всьому краю за наказами Лорда Ксаваріка.",al={"хто тут живе","хто править констелласом","сатири нефритового вогню констеллас"}},{q="Що сталося з місячним колодязем у Констелласі?",a="Сатири Нефритового Вогню захопили місячний колодязь і зіпсували його магією Скверни. Замість лагідного благословення Елуни він тепер — отруйне джерело енергії Скверни, яке плекає Ксаватрас.",al={"зіпсований місячний колодязь скверноліс","місячний колодязь констелласа","чому колодязь зелений"}},{q="Звідки в руїнах вогняна стіна?",a="Сатири звели палаючу перепону впоперек внутрішньої стежки, щоб захистити Ксаватраса й свої обряди від друїдів і смарагдових ведмежників, які прийшли б помститися.",al={"вогняна стіна констелласа","вогняна перешкода констелласа","як пройти вогняну стіну"}}},fp="19,281,19.479.0,26.443.0,42.240.0,27.172.0,44.210.0,45.160.0"}
P.entries["subzone:ruins-of-eldarath"] = {n="Руїни Елдарата",s="Руїни Елдарата — розтрощені рештки міста Високороджених, що існувало ще до Розколу, на скелястих кручах Азшари. Колись це був оплот тайної науки калдореїв, а нині його зруйновані площі й храми, що розсипаються, заполонили ворожі наги. Учені й шукачі пригод ризикують, обходячи небезпечні прибережні руїни в пошуках списаних табличок і забутих реліквій далекого минулого.",h="Руїни Елдарата — розтрощені рештки міста Високороджених, що існувало ще до Розколу, на скелястих кручах...",kw={"руїни елдарата","елдарат","високороджені","наги","ліга дослідників","таблиці","азшара"},ang={["class:Mage"]="Елдарат — священне, хоч і повчальне місце для навчання: кам'яні таблиці на його площах викладають основи тайної теорії, викарбувані найобдарованішими чародіями Високороджених до падіння їхньої імперії.",["race:NightElf"]="Ці вибілені сонцем руїни — гірке нагадування про пиху Високороджених і Розкол; сучасні калдореї давно їх уникають, а тепер їх оскверняють спотворені наги."},sec={{t="Розбитий оплот Високороджених",b="Перш ніж десять тисяч років тому Великий Розкол розтрощив прадавній Калімдор, Елдарат був квітучим містом нічних ельфів. Тут збиралися славетні маги з Високороджених, що висікали свої найглибші тайні прозріння й основоположні закони магії на великих кам'яних таблицях, залишених на площах, аби їх вивчали колеги. У часи згубної Війни Прадавніх місто стало полем бою між Опором калдореїв і демонічним Палаючим Легіоном, а потім Розкол скинув більшу частину Елдарата в Затоку Бур. Уцілілих решток на східних кручах тисячоліттями уникають сучасні нічні ельфи, і їх поволі обсідають морські бризки й плющ."},{t="Влада наг і забуті реліквії",b="Віднедавна люті наги вийшли з моря й захопили зруйновані вулиці Елдарата; ними командують воєначальники, що ховаються в недалеких святилищах на кшталт Храму Зін-Малора. Попри небезпеку від змієлюдів, руїни й далі нестримно вабять чужинців. Ліга Дослідників посилає шукачів пригод з Альянсу в зруйновані двори, щоб зняти відбитки з прадавніх тайних таблиць Елдарата. Чутки про втрачені скарби й залишки магічної енергії привабили в довколишні дикі землі й синього дракона Азурегоса — ще один доказ того, що під потрісканими плитами руїн досі дрімають таємниці неймовірної сили."}},faq={{q="Чим був Елдарат до того, як обернувся на руїни?",a="До Великого Розколу десять тисяч років тому Елдарат був величним містом нічних ельфів, населеним Високородними. Це був осередок чарівної науки й укріплений прихисток, доки Війна Прадавніх і розкол світу не спустошили його.",al={"чим був елдарат","історія елдарата","походження елдарата"}},{q="Хто сьогодні тримає Руїни Елдарата?",a="Ворожі наги цілком заполонили руїни: напівзруйновані площі й сусідні споруди, як-от Храм Зін-Малора, стали їхніми прибережними твердинями під проводом таких ватажків, як Воєначальник Крелліан.",al={"хто живе в елдараті","що в елдараті","моби елдарата"}},{q="Навіщо вчені й дослідники приходять до Елдарата?",a="Вчені шукають кам'яні скрижалі, що вціліли після давніх магів Високородних. Ці публічні написи містять основоположні закони чарівної магії й давно втрачені дослідження — такі цінні, що угруповання на кшталт дворфійської Ліги Дослідників посилають розвідників зняти з них відбитки.",al={"навіщо йти до елдарата","завдання елдарата","що в елдараті"}},{q="Чому біля руїн блукає синій дракон Азурегос?",a="Азурегоса вабить надзвичайне скупчення давньої чарівної сили вздовж узбережжя Азшари. Ходять чутки, що в руїнах чи довкола них досі заховані могутні реліквії з часів до Розколу — можливо, навіть фіали, яких торкнувся давній Колодязь Вічності.",al={"чому азурегос тут","азурегос елдарат","синій дракон ашара"}}},fp="17,377,29.664.0,30.642.0,44.253.0,41.200.0,49.275.0,55.266.0"}
P.entries["subzone:ruins-of-isildien"] = {n="Руїни Ісілдієна",s="Руїни Ісілдієна — розлогі залишки прадавнього міста нічних ельфів у південно-західному Фераласі, зруйнованого десять тисячоліть тому під час Великого Розколу. Нині зарослу кам'яну кладку й потріскані храмові подвір'я посіли брутальні огри Ґордунні.",h="Руїни Ісілдієна — розлогі залишки прадавнього міста нічних ельфів у південно-західному Фераласі, зруйнованого...",kw={"руїни ісілдієна","калдореї","огри ґордунні","елуна","храм місяця","фералас"},ang={["class:Priest"]="Велика ротонда на вершині повторює план високих святилищ Елуни — у ній досі ніби відлунюють молитви, які десять тисяч років тому підносили Білій Леді.",["race:NightElf"]="Прогулянка Ісілдієном — гірке нагадування про велич вашої імперії до Розколу, що тепер лежить у руїнах і зазнає наруги від варварів-огрів Ґордунні."},sec={{t="Занепале місто калдореїв",b="Десять тисяч років тому, ще до того, як світ розколовся, Ісілдієн був величним поселенням нічних ельфів серед прадавніх лісів давнього Калімдора. Його витончені мармурові арки й розкішні тераси були пам'ятниками цивілізації та побожності калдореїв. Коли Колодязь Вічності вибухнув і розірвав континенти, Ісілдієн обернувся на руїну, яку тисячоліттями душили дикі хащі джунглів. Над верхньою терасою височіє велетенська купольна споруда, напрочуд схожа на Храм Місяця в Дарнасусі, — тож, найпевніше, колись місто було важливим святилищем Елуни."},{t="Твердиня Ґордунні",b="Нині витончена кладка Ісілдієна служить куди грубішим цілям. Огри Ґордунні з Фераласу захопили розлогі тераси й уступи й зробили їх одним зі своїх головних поселень. Вони укріпили обвалені переходи, сплюндрували прадавні майдани грубими вогнищами, примітивними барикадами й бойовими стягами — і люто боронять своє вкрадене житло від кожного чужинця, що забреде надто близько до південних пагорбів."}},faq={{q="Чим спершу був Ісілдієн?",a="Ісілдієн — велике місто нічних ельфів, збудоване до Великого Розколу десять тисяч років тому. Тут були просторі кам'яні площі, багатоярусні тераси й величні храми, доки катаклізм не обернув його на руїни.",al={"чим був ісілдієн","історія ісілдієна","хто збудував ісілдієн"}},{q="Хто тепер тримає Руїни Ісілдієна?",a="Руїни захопили й укріпили огри Ґордунні: розбиті мармурові зали й природні висоти стали їхньою твердинею на півдні Фераласу.",al={"хто живе в ісілдієні","вороги ісілдієна","огри в ісілдієні"}},{q="Що за великий круглий павільйон на верхівці сходів?",a="Помітний круглий павільйон дуже нагадує архітектуру Храму Місяця в Дарнасусі — це переконливо свідчить, що верхній поміст колись був священним святилищем, присвяченим поклонінню Елуні.",al={"храм ісілдієна","круглий павільйон ісілдієна","храм елуни фералас"}},{q="Чи є щось приховане в руїнах?",a="У східних скелях на межі руїн є печера, якою користуються тутешні огри, — поряд із розкиданими кам'яними терасами на північних і південних угіддях.",al={"печера ісілдієна","таємниці ісілдієна"}}},fp="17,260,29.600.0,23.441.0,29.214.0,39.159.0,61.207.0,42.170.0"}
P.entries["subzone:ruins-of-jubuwal"] = {n="Руїни Джубувалу",s="Руїни Джубувалу — розсипані рештки давнього поселення Ґурубаші трохи на схід від Арени Ґурубаші в Долині Стренглторну. Колись тут вирувало життя імперії й творилися ритуали, а тепер руїни опинилися під владою знахаря-ренегата Занзіла Вигнанця та його химерного почту прислужників.",h="Руїни Джубувалу — розсипані рештки давнього поселення Ґурубаші трохи на схід від Арени Ґурубаші в Долині...",kw={"руїни джубувалу","занзіл вигнанець","ґурубаші","вуду","маккінлі","буті бей"},ang={["class:Rogue"]="Тіні й розсипане каміння Джубувалу — ідеальне прикриття, щоб улаштувати засідку на злочинців, які ховаються від мисливців за головами з Буті Бею.",["race:Troll"]="Для тролів Темного Списа Джубувал — це водночас трагічний занепад спадщини Ґурубаші та збочене викривлення прадавнього вуду, яке практикують відщепенці на кшталт Занзіла."},sec={{t="Прихисток для вигнанців",b="Джубувал, що лежить осторонь головного шляху крізь Долину Стренглторну, колись був частиною величної цивілізації Ґурубаші. Сьогодні кам'яну різьбу й оповиті плющем мури захопив Занзіл Вигнанець — дивакуватий знахар, відомий своїми сильними зіллями й мерзенним вуду. Занзіл наповнив руїни неприродним звіринцем послідовників: тут і зачаровані гулі, і підкорені наги, і тролі-ренегати. Серед кам'яних арок причаїлися й відчайдушні втікачі — Джон-Джон Ворон і Морі «Клишоногий» Вілкінс, які переховуються від безжального збирача боргів «Морського Вовка» Маккінлі з Буті Бею."}},faq={{q="Де розташовані Руїни Джубувалу?",a="Руїни лежать у центрі Долини Стренглторну, трохи на схід від Арени Ґурубаші й одразу біля головної ґрунтової дороги між північним і південним Стренглторном.",al={"розташування руїн джубувалу","де джубувал","джубувал на мапі"}},{q="Хто тримає Руїни Джубувалу?",a="Руїнами володіють Занзіл Вигнанець і його прислужники. Серед його строкатих прибічників — тролі з промитими мізками, оживлені гулі, союзні наги й усілякі пройдисвіти, що ховаються тут від закону.",al={"хто живе в джубувалі","вороги джубувалу","хто контролює джубувал"}},{q="Чому тут разом діють гулі й наги?",a="Занзіл Вигнанець використовує отруйні вуду-суміші й зілля, що змінюють свідомість, щоб підкоряти довколишніх і командувати ними. Завдяки цим сумішам він скував піднятих мерців, наг і тролів у слухняне військо.",al={"чому гулі в джубувалі","посіпаки занзіла"}},{q="Чому тут ховаються такі злочинці, як Джон-Джон і Морі?",a="І Джон-Джон Ворон, і Морі «Клишоногий» Вілкінс утекли до Джубувалу від гніву «Морського Вовка» Маккінлі — горезвісного вибивайла боргів із Буті Бею.",al={"джон-джон ворон","морі кульгавий вілкінс","боржники маккінлі"}}},fp="16,299,23.628.0,39.172.0,34.203.0,46.208.0,51.167.0"}
P.entries["subzone:ruins-of-kel-theril"] = {n="Руїни Кел'Теріл",s="Руїни Кел'Теріл — уламки прадавнього міста нічних ельфів на березі скутого кригою Озера Кел'Теріл, у самому серці Вінтерспрінгу. Місто знищено десять тисяч років тому, під час Великого Розколу, і досі серед його вкритих інеєм кам'яних колон і храмів блукають змучені духи Високородних, що загинули в тій катастрофі.",h="Руїни Кел'Теріл — уламки прадавнього міста нічних ельфів на березі скутого кригою Озера Кел'Теріл, у самому...",kw={"руїни кел'теріл","вінтерспрінг","високородні","великий розкол","нічні ельфи","привиди","озеро кел'теріл"},ang={["class:Mage"]="Маги, які досліджуватимуть руїни, відчують давню приспану таємну енергію, що колись живила одне з найвеличніших магічних міст Калімдору доби до Розколу.",["race:NightElf"]="Для нічних ельфів Кел'Теріл — скорботне нагадування про пиху прадавньої касти Високородних і про страшне спустошення, яке накликало їхнє безрозсудне захоплення таємною магією."},sec={{t="Розтрощена спадщина",b="Задовго до того, як Вінтерспрінг став крижаним нагір'ям, Кел'Теріл був величним поселенням прадавньої імперії нічних ельфів. Коли під час Великого Розколу Колодязь Вічності зруйнувався, місто обернулося на руїни й зникло під кригою та снігом. Лихо заскочило Високородних, що жили тут, зненацька й прикувало їхні душі до засніжених каменів. Нині духи цих колишніх чарівників блукають попід скутими морозом арками й без кінця переживають свої останні, страшні миті."},{t="Відлуння в снігах",b="Мандрівники, що наважуються вирушити в центр Вінтерспрінгу, натрапляють на неспокійних примарних Високородних, що бродять зруйнованими колонадами над озером. Здебільшого ці привиди ворожі: тисячоліття самотності й жорстока магія, що розірвала їхню цивілізацію, звели їх із розуму. Утім, кілька скорботних видінь — як-от Розкаяний Високородний — шукають мандрівників, готових вислухати їхні давні жалі, щоб нарешті примиритися із забутим минулим."}},faq={{q="Що сталося з містом Кел'Теріл?",a="Кел'Теріл знищено десять тисяч років тому під час Великого Розколу. Коли Колодязь Вічності вибухнув досередини й роздер давній континент Калімдор, місто обернулося на купу уламків, і його скував раптовий лютий холод, що оселився у Вінтерспрінгу.",al={"історія кел'теріл","чому кел'теріл у руїнах","як упав кел'теріл"}},{q="Які духи блукають цими руїнами?",a="У руїнах блукають привиди нічних ельфів-Високородних, що загинули під час Великого Розколу. Їхні душі досі прив'язані до поваленого каміння: вони мучаться й блукають засніженими околицями Озера Кел'Теріл.",al={"привиди кел'теріл","хто блукає кел'теріл","нежить кел'теріл"}},{q="Чи можна поговорити з кимось із привидів?",a="Більшість духів ворожі й втратили розум, але серед руїн є самотній Розкаяний Високородний, який охоче розмовляє з мандрівниками Альянсу, що хочуть зрозуміти трагічне минуле цього місця.",al={"дружній привид кел'теріл","кається високородний","завдання привидів кел'теріл"}},{q="Де розташовані руїни?",a="Руїни Кел'Теріл лежать на берегах Озера Кел'Теріл — замерзлого озера в самому серці центрального Вінтерспрінгу.",al={"розташування кел'теріл","де кел'теріл","знайти кел'теріл"}}},fp="19,341,18.488.0,18.422.0,40.267.0,31.226.0,37.216.0,28.133.0"}
P.entries["subzone:ruins-of-lordaeron"] = {n="Руїни Лордерона",s="Руїни Лордерона — випалені рештки Столиці на поверхні, колись осяйного серця північної держави людей. Її знищив принц Артас, убивши батька й напустивши Погибель; тепер спустошені двори й тронна зала служать укріпленою брамою до Андерсіті, що лежить унизу.",h="Руїни Лордерона — випалені рештки Столиці на поверхні, колись осяйного серця північної держави людей.",kw={"руїни лордерона","столиця","артас","теренас менетіл","фросморн","сильвана віндраннер","тронна зала"},ang={["race:Human"]="Стояти в цих залах — гірке нагадування про найтяжчу зраду в історії людей: тут принц Артас розтрощив Альянс Лордерона й віддав перлину людства в руки мертвих.",["race:Undead"]="Ці зруйновані мури — ваш рідний дім. Те, що колись було престолом живого королівства, яке вас породило, тепер священна брама, що стереже Андерсіті й Королеву Баньші."},sec={{t="Брама занепалої держави",b="Колись Столиця була сяйливою вершиною людської цивілізації й поєднувала північні королівства під владою короля Теренаса Менетіла Другого. Коли принц Артас повернувся з Нортренда з проклятим рунічним клинком Фростморном, святкування обернулося на різанину. Артас убив батька на троні й покинув велике місто гнити під владою Погибелі. Після міжусобиці, що розкраяла Погибель, Леді Сильвана Віндраннер заволоділа зруйнованим палацом: вона закріпила поверхню, а склепи й підземелля під нею розбудувала в Андерсіті."},{t="Відголоси зради",b="Руїни палацу й досі несуть на собі слід того страшного падіння. Мандрівники, що проходять передпокоєм і дворами, часто чують привидний дзвін святкових дзвонів, стишений гомін захопленого натовпу й холодну розмову Артаса з батьком за мить до вбивства. Підлога великої тронної зали й досі заплямована кров'ю, а ті, хто володіє магічним зором, можуть угледіти примарних міщан, які вічно переживають той день, коли їхній принц прирік усіх."}},faq={{q="Чому біля входу чути дзвони й шепіт?",a="Раптова різанина короля Теренаса та його міста лишила на камені психічний відбиток. Кожен, хто проходить зовнішню браму й зруйновану тронну залу, може почути примарні дзвони, привидні вітальні вигуки й останню розмову Теренаса з Артасом, що відлунює крізь час.",al={"моторошні звуки лордерона","шепіт у тронній залі","звуки з привидами у замку"}},{q="Хто сьогодні править руїнами?",a="Наземні руїни тримають і патрулюють Відступники під владою Леді Сильвани Віндраннер. Сильвана та її двір живуть просто під ними, в Андерсіті, а руїни нагорі слугують величним укріпленим входом до її підземного королівства.",al={"хто володіє руїнами лордерона","хто контролює руїни лордерона"}},{q="Що сталося з людьми, які тут жили?",a="Більшість мешканців вирізали, коли Артас напустив на місто Погибель. Чимало з них підняли як безмозку нежить, а згодом вони вирвалися на волю й пристали до Сильвани як Відступники, а невидимі духи інших досі блукають палацовими дворами.",al={"куди поділися люди лордерона","що сталося з людьми столиці"}},{q="Що за темна пляма в тронній залі?",a="Темний засохлий слід на королівському помості — це кров короля Теренаса Менетіла II, пролита його власним сином Артасом, коли принц устромив Фростморн йому в серце.",al={"кров у тронній залі","пляма в тронній залі лордерона"}}},fp="18,306,25.542.0,18.474.0,67.269.0,26.238.0,50.260.0,42.171.0"}
P.entries["subzone:ruins-of-mathystra"] = {n="Руїни Матістри",s="Руїни Матістри — напівзруйновані рештки давнього міста нічних ельфів на північному узбережжі Темного Узбережжя. Розбиті під час Великого Розколу десять тисяч років тому, прибережні руїни тепер заполонили ворожі наги Штормової Луски, а серед них никають невловимі примарні шаблезуби.",h="Руїни Матістри — напівзруйновані рештки давнього міста нічних ельфів на північному узбережжі Темного...",kw={"руїни матістри","наги","штормолусі","примарні шаблезуби","високородні","темне узбережжя"},ang={["class:Hunter"]="Напівпрозорі примарні шаблезуби, що никають серед руїн Матістри, — славетні звірі для приборкувачів, які шукають ефектного супутника, пов'язаного зі світом духів.",["race:NightElf"]="Матістра — сумний пам'ятник гордині давніх Високородних, чиє безрозсудне чаклунство обрушило катаклізм на їхні ж величні приморські поселення."},sec={{t="Місто, скинуте в море",b="Десять тисячоліть тому Матістра була гамірним поселенням нічних ельфів, домівкою високої знаті з Високородних. Коли під час Великого Розколу обвалилося Колодязь Вічності, катастрофічні хвилі зруйнували прибережне місто, повалили його величні мармурові арки й змили більшу частину кладки в море. Вцілілі нічні ельфи покинули зруйноване місто заради менших лісових селищ далі на півдні, залишивши затоплені двори й потріскані фундаменти Матістри невблаганним прибережним стихіям."},{t="Наги Штормової Луски й примарні шаблезуби",b="Нині Матістра — небезпечне володіння наг Штормової Луски. Виповзши з темних глибин, ці змієподібні потвори люто стережуть зруйновані зали, проганяючи кожного мандрівника, що наважиться піти на північ за Вежу Альталакса. Серед розбитих плит досі лежать напівзасипані піском і морською піною давні реліквії Високородних. Відчайдушні молоді нічні ельфи часом кидають виклик нагам, сподіваючись повернути рештки своєї втраченої спадщини, — і їм часто доводиться протистояти не лише зміїним клинкам, а й примарним шаблезубам, що никають зруйнованими вулицями."}},faq={{q="Що було тут до руїн?",a="Матістра — квітуче місто нічних ельфів, збудоване в розквіт давньої імперії Високородних. Десять тисяч років тому, під час Великого Розколу, коли Колодязь Вічності вибухнув і розколов Калімдор, місто зруйнувалося й здебільшого пішло під воду.",al={"історія матістри","хто збудував матістру","чим була матістра"}},{q="Хто зараз тримає Руїни Матістри?",a="Руїни нині займають наги Штормової Луски, що вийшли з моря й захопили затоплені павільйони та узбережжя. Вони люто нападають на всіх суходільних мешканців, що вдираються в їхні володіння.",al={"хто живе в матістрі","моби матістри","хто в матістрі"}},{q="Що таке примарні шаблезуби?",a="Примарні шаблезуби — безтілесні напівпрозорі кішки, що блукають зруйнованою кам'яною кладкою Матістри. Мисливці часто шукають їх на узбережжі, а якщо потривожити тутешні давні статуетки, ці духи виходять із тіні.",al={"примарний шаблезуб матістра","сяйна кішка темного берега","примарні шаблезуби"}},{q="Навіщо нічні ельфи приходять до цих руїн сьогодні?",a="Молоді нічні ельфи й учені часом вирушають у руїни, щоб повернути давні реліквії Високородних, що лишилися після Розколу. Проте через лютих наг Штормової Луски повернути ці історичні скарби надзвичайно небезпечно.",al={"реліквії матістри","навіщо йти до матістри"}}},fp="18,285,24.507.0,38.584.0,38.249.0,46.209.0,22.242.0,43.247.0"}
P.entries["subzone:ruins-of-ordil-aran"] = {n="Руїни Ордил'Аран",s="Руїни Ордил'Аран — напівзруйновані залишки давнього поселення нічних ельфів на північному заході Ашенвалю, між Постом Маестри й Притулком Батрана. Колись тут ховалися культисти тіні, але нещодавно повалене каміння захопили осквернені фурболги Будякохутрі.",h="Руїни Ордил'Аран — напівзруйновані залишки давнього поселення нічних ельфів на північному заході Ашенвалю...",kw={"руїни ордил'аран","будякохутрі","фурболги","культ темного берега","серцедерево","ашенваль"},ang={["faction:Alliance"]="Ворожі мешканці Ордил'Арану, що засіли трохи на північ від Посту Маестри, загрожують розвідникам і мандрівникам Альянсу, які прямують до Темного Узбережжя.",["race:NightElf"]="Ці руїни — ще одне болюче нагадування про занепад давньої імперії на Калімдорі, а тепер їх оскверняють зіпсовані фурболги й темні культисти."},sec={{t="Спірні руїни",b="Від первісної архітектури калдореїв в Ордил'Арані мало що лишилося — хіба вивітрені колони, потріскані арки й порослі мохом камені. Певний час ці відлюдні руїни були лігвом Культу Темного Берега, чиї прихильники ховалися серед уламків і влаштовували засідки на мандрівників на північно-західних стежках Ашенвалю. Проте нещодавно люті фурболги з племені Будякохутрих вигнали культистів у кривавій сутичці. Тіла полеглих адептів Темного Берега досі лежать на землі, а агресивні фурболги патрулюють околиці, затято охороняючи руїни й давнє Серцедерево, що росте всередині."}},faq={{q="Чим спершу був Ордил'Аран?",a="Ордил'Аран — давнє поселення нічних ельфів, що існувало ще до Великого Розколу. Як і багато застав калдореїв по всьому Ашенвалю, воно тисячоліттями занепадало, і лишилися тільки порослі зеленню кам'яні арки й напівзруйнована кладка.",al={"історія ордил'арана","що таке ордил'аран","хто збудував ордил'аран"}},{q="Чому довкола руїн лежать мертві сектанти?",a="Колись Культ Темного Берега мав у цих руїнах свою базу. Фурболги-Будякохутрі люто напали на них і вигнали, захопивши руїни собі, тож по всьому місцю лежать тіла вбитих сектантів.",al={"мертві культисти","трупи темного берега","чому культисти мертві"}},{q="Що таке Серцедерево?",a="Серцедерево — особливе давнє дерево, що росте в Руїнах Ордил'Аран. Його гілки й деревину цінують за могутні чарівні й природні властивості.",al={"серцедерево","завдання серцедерева","серцедерево ордил'аран"}},{q="Хто нині тримає руїни?",a="Нині руїни займають агресивні фурболги-Будякохутрі, що вбили або вигнали сектантів Темного Берега, які жили тут раніше.",al={"хто тут живе","хто в ордил'арані","моби ордил'арана"}}},fp="19,291,16.608.0,31.233.0,51.224.0,23.172.0,33.149.0"}
P.entries["subzone:ruins-of-ravenwind"] = {n="Руїни Рейвенвінду",s="Руїни Рейвенвінду — розбиті рештки прадавнього міста Високородних у північному Фераласі. Нині ці обвалені мармурові споруди кишать лютими гарпіями Нортспрінг, а стережуть їх похмурі драконороди.",h="Руїни Рейвенвінду — розбиті рештки прадавнього міста Високородних у північному Фераласі.",kw={"руїни рейвенвінду","високородні","гарпії","драконороди","фералас","реліквії"},ang={["faction:Alliance"]="Застави на кшталт Твердині Перистого Місяця пильно стежать за Рейвенвіндом і посилають відважних розвідників по могутні магічні реліквії, перш ніж їх поглинуть дикі створіння чи темніші сили.",["race:NightElf"]="Для калдореїв ці руїни — гірке нагадування про безрозсудну тайнознавчу імперію, що розірвала прадавній Калімдор, а тепер стала поживою для гарпій і диких звірів."},sec={{t="Відлуння Високородних",b="Так само як велике місто Лютопащ на сході, Руїни Рейвенвінду стоять урочистим пам'ятником величі й пихи прадавньої цивілізації Високородних до Великого Розколу. Давно покинуте своїми творцями-калдореями, це місце поглинули дикі хащі; тут лишилися забуті тайнознавчі вівтарі та смердючі гнізда гарпій Нортспрінг, що полюють на все живе під розбитими арками."},{t="Перехрестя диких небезпек",b="Окрім верескливих гарпій, Рейвенвінд оточують інші загрози, різноманітні й ревниві до своєї території. Люті зелені драконороди, відомі як Джейдмір, кружляють над центральними гаями й водоймами, оберігаючи прадавні лісові святині. А заблукалі мандрівники — від неуважних нічних ельфів-дослідників до дивних гнолів-самітників, що тиняються неподалік, — частенько опиняються між двох вогнів: магією, що досі жевріє в руїнах, і дикими хижаками."}},faq={{q="Хто збудував Руїни Рейвенвінду?",a="Поселення звели тисячоліття тому Високородні — аристократична верхівка давньої цивілізації калдореїв. Після Розколу воно занепало, як Лютопащ та інші ельфійські пам'ятки Фераласу.",al={"хто збудував рейвенвінд","історія рейвенвінду","походження руїн рейвенвінду"}},{q="Хто нині заполонив руїни?",a="Руїни заполонили гарпії Північного Джерела — дикі крилаті створіння, що гніздяться серед розбитої кам'яної кладки. Крім того, драконячі створіння роду Джейдміра нишпорять довколишніми водами й центральним гаєм, люто охороняючи місцеві рослини.",al={"монстри рейвенвінду","що живе в рейвенвінді","гарпії рейвенвінду"}},{q="Навіщо Альянс приходить у цей край?",a="Учені й вартові Альянсу з Твердині Перистого Місяця посилають сюди шукачів пригод, щоб знайти втрачені чарівні реліквії й скористатися давніми вівтарями, аби знову наповнити силою могутні артефакти, як-от Посох Еквінекса.",al={"завдання альянсу рейвенвінд","перистий місяць рейвенвінд"}}},fp="18,237,23.417.0,28.423.0,33.234.0,33.234.0,38.214.0"}
P.entries["subzone:ruins-of-stardust"] = {n="Руїни Зоряного Пилу",s="Руїни Зоряного Пилу — давнє зруйноване святилище нічних ельфів на острові посеред озера в південно-західному Ашенвалі. Колись тихе місце молитви, тепер воно потерпає від скверни: води острова й місцеві болотяні звірі отруєні демонічною гниллю, що стікає зі Сквернолісся. Та попри всюдисущу пошесть, серед руїн досі буяють сяйливі кущі зоряного пилу, що зберігають могутню цілющу силу.",h="Руїни Зоряного Пилу — давнє зруйноване святилище нічних ельфів на острові посеред озера в південно-західному...",kw={"руїни зоряного пилу","зоряний пил","болотяні звірі","скверна","поклик води","ашенваль"},ang={["class:Shaman"]="Неосквернений зоряний пил, який трапляється тут, — важливий очисний інгредієнт для духовних випробувань, зокрема для Поклику Води, що навчає опановувати цілющі стихії.",["race:NightElf"]="Бачити, як колишнє святилище поволі гине від гнилих стоків Сквернолісся, — болюче нагадування про нескінченну боротьбу за Ашенваль проти демонічної скверни."},sec={{t="Сплюндроване святилище",b="Руїни Зоряного Пилу, що лежать на самотньому острові на південь від Астранаару, колись були шанованим святим місцем нічних ельфів. Сьогодні над водою висить моторошний хворобливий жовто-зелений серпанок — наслідок мерзенної демонічної гнилі, що стікає на південь зі Сквернолісся, як і на сусідньому Озері Ірисів. Місцеві рослини обернулися на ворожих болотяних звірів, що нишпорять серед поваленої кладки; їхню вдачу зіпсувало отруєне озеро."},{t="Незламний зоряний пил",b="Хоч скверна просочила ґрунт і береги, острів зберігає незламну іскру життя. Серед руїн трапляються кущі зоряного пилу, що квітнуть, не зачеплені демонічною отрутою. Їхнє листя й цвіт мають дивовижну очисну й цілющу силу, тож сюди приходять шамани, травники й місцеві захисники-нічні ельфи, шукаючи ліків від занепаду, що насувається на Ашенваль."}},faq={{q="Для чого спершу були Руїни Зоряного Пилу?",a="У давнину це місце було священною землею, яку доглядали нічні ельфи. Класичні мармурові колони й оглядовий майданчик над озером слугували тихим місцем пошани задовго до того, як у лісі вкоренилася демонічна скверна.",al={"що це за руїни","лор зоряного пилу","хто збудував зоряний пил"}},{q="Чому вода довкола острова змінила колір?",a="Демонічна скверна, що стікає з отруєних вершин Сквернолісся у водотоки Ашенвалю, отруїла озеро, надавши воді каламутного жовтаво-зеленого відтінку й порушивши природну рівновагу.",al={"чому вода зелена","чому озеро зіпсоване","вода зоряного пилу"}},{q="Чим особливі кущі зоряного пилу?",a="Хоч кущі зоряного пилу ростуть на ґрунті, просоченому демонічними стоками, вони лишаються цілком чистими. Вони опираються скверні довкола й мають надзвичайні відновлювальні й цілющі властивості, тож цінуються як складники для обрядів очищення.",al={"що таке кущ зоряного пилу","рослина зоряного пилу","кущі зоряного пилу"}},{q="Хто блукає руїнами?",a="Острів заполонили великі зіпсовані болотяні звірі. Отруєна вода озера обернула цих елементалів природи з мирних захисників лісу на агресивних неповоротких потвор, небезпечних для кожного, хто переходить мілиною.",al={"моби зоряного пилу","які монстри тут","болотні звірі"}}},fp="17,400,20.409.0,21.391.0,52.222.0,46.201.0,39.232.0,32.212.0"}
P.entries["subzone:ruins-of-thaurissan"] = {n="Руїни Тауріссана",s="Руїни Тауріссана — обгорілі рештки першої наземної столиці клану Темного Заліза в Палаючих Степах. Колись це було горде місто серед буйної зелені північних околиць Гір Редріджу, та його спалило дотла під час Війни Трьох Молотів, коли тан-чародій Тауріссан ненароком викликав Володаря вогню Рагнароса.",h="Руїни Тауріссана — обгорілі рештки першої наземної столиці клану Темного Заліза в Палаючих Степах.",kw={"руїни тауріссана","темне залізо","рагнарос","війна трьох молотів","палаючі степи","архесонус"},ang={["faction:Alliance"]="Розвідники й дослідники Альянсу, яких найняла Королівська Історикиня Архесонус з Айронфорджа, прочісують ці тліючі фундаменти в пошуках реліквій, що відкривають правду про господаря Гори Блекрок.",["race:Dwarf"]="Для дворфів Айронфорджа ці руїни — похмурий пам'ятник гордині клану Темного Заліза у Війні Трьох Молотів і жахливій ціні, яку довелося заплатити за виклик стихійних сил."},sec={{t="Падіння королівства",b="Близько двох століть тому, коли по смерті Верховного короля Модімуса Анвілмара клан Темного Заліза вигнали з Айронфорджа, дворфи рушили на південь і заснували Місто Тауріссан. У розпал Війни Трьох Молотів, опинившись перед неминучою поразкою від об'єднаних сил кланів Бронзбірда й Вайлдгаммерів, тан-чародій Тауріссан шукав остаточну зброю, щоб переломити хід війни. Разом із сімома довіреними чародіями він спрямував прадавню магію глибоко під землю. Та замість слухняного слуги їхній ритуал розверз прохід до Царства Стихій і викликав Рагнароса, Володаря вогню. Катастрофічне виверження розтрощило довколишні гори, спопелило квітучий край, перетворивши його на попелясті Палаючі Степи, звело вулкан Гори Блекрок і спалило місто."},{t="Відлуння в попелі",b="Нині пустирем розкидані розтрощена кладка й обвалені колони, де патрулюють рештки Темного Заліза й никають вогняні елементалі. Альянс за порадою Королівської Історикині Архесонус з Айронфорджа відрядив експедиції, щоб відшукати прадавні реліквії, поховані під попелом. Дотик до цих зачарованих решток пробуджує яскраві й моторошні спогади про катастрофу: вісім дворфів у розпачі співають закляття, сім трупів лежать довкола самотнього тавматурга, що стоїть на колінах, і височіє моноліт первісного полум'я, який забрав душі й свободу цілого клану."}},faq={{q="Чим було це місто до того, як його знищили?",a="Це було місто Тауріссан — горда наземна столиця клану Темного Заліза. Збудоване після того, як дворфів вигнали з Айронфорджа по смерті Верховного короля Модімуса Анвілмара, воно було серцем їхнього молодого королівства, доки його не знищили дощенту.",al={"лор міста тауріссан","чим був тауріссан","хто збудував тауріссан"}},{q="Як місто знищили?",a="Відчайдушно прагнучи виграти Війну Трьох Молотів проти інших дворфійських кланів, чаклун-тан Тауріссан спробував викликати могутнього надприродного слугу. Обряд розірвав кайдани, що тримали Рагнароса під землею. Поява Володаря вогню вибухнула апокаліптичним вулканом, що обернув місто й довколишні буйні долини на обвуглені руїни.",al={"як згорів тауріссан","що знищило тауріссан","хто знищив тауріссан"}},{q="Чому земля довкола руїн — попеляста пустка?",a="Колись Палаючі Степи були родючими зеленими північними краями Гір Редріджу. Нищівний катаклізм, яким обернувся виклик Рагнароса, розірвав землю, звів Гору Блекрок і випалив увесь простір на посушливу пустку, задушену попелом.",al={"чому палаючі степи попелясті","що сталося з землею","зв'язок із червоногір'ям"}},{q="Куди поділися вцілілі дворфи Темного Заліза?",a="Уцілілих поневолили Рагнарос і його стихійні прислужники. Вони пішли глибоко під Гору Блекрок і збудували там Місто Тінькузні, покинувши зруйновану столицю пустці й гнучи спину на Володаря вогню.",al={"де дворфи темного заліза тепер","походження міста тіньової кузні"}}},fp="19,344,21.775.0,17.557.1,43.249.0,27.352.0,54.256.0,45.232.0"}
P.entries["subzone:ruins-of-uldum"] = {n="Руїни Ульдуму",s="Руїни Ульдуму, сховані в зубчастих скелях Долини Вартових на півдні Танарісу, — це прадавній кам'яний передпокій, що стереже запечатану споруду титанів. Масивні кам'яні двері й напівзруйновані земляни бережуть її таємниці і від грабіжників могил, і від допитливих дослідників.",h="Руїни Ульдуму, сховані в зубчастих скелях Долини Вартових на півдні Танарісу, — це прадавній кам'яний...",kw={"руїни ульдуму","ульдум","титани","земляни","долина вартових","танаріс"},ang={["profession:Mining"]="Кам'яне муровання й механізми Ульдуму — взірець майстерності титанів, що тисячі років без жодної вади витримувала тектонічний тиск і руйнівну дію пустелі.",["race:Dwarf"]="Для дворфів, що ведуть свій родовід від землян, Ульдум — одна з первісних колисок титанів, де їхні предки вперше спочили після Розколу."},sec={{t="Передпокій титанів",b="Руїни Ульдуму, видовбані глибоко в скельній основі південного Танарісу, схожі на передпокій або величний поріг набагато більшого запечатаного підземного комплексу. Усередині мовчки несуть варту земляни з пісковику, а поруч стоять відкриті механізми титанів і прадавня реліквія, відома як Допотопна Скриня. Хоча колись давно потужні поштовхи вирвали зовнішній вхід, обвали всередині й масивні кам'яні загорожі не пускають далі в глибинні тунелі. Приспані земляни не ворухнуться, хіба що їм загрожують або хтось торкається реліквій, які оберігає передпокій."},{t="Таємниці біосфери",b="За прадавніми записами й свідченнями небесних вартових, титани заснували Ульдум разом з Ульдаманом і Ульдуаром як дослідницькі осередки, призначені змінювати біосферу Азероту й стежити за нею. Коли десять тисяч років тому Великий Розкол розірвав світ, земляни відчули муки світу й відступили в ці підземні сховища, щоб поринути в сплячку. Щоб пройти за запечатаний внутрішній поріг руїн, потрібні загублені Скрижалі Ульдуму, тож справжні масштаби комплексу досі приховані від сучасних мешканців поверхні."}},faq={{q="Що всередині Руїн Ульдуму?",a="Руїни — це передпокій, повний приспаних пісковикових землян, оголені механізми титанів і Допотопна скриня. Глибші тунелі, що ведуть далі в комплекс, обвалилися й замкнені велетенськими кам'яними дверима.",al={"що в ульдумі","що таке ульдум танаріс","інтер'єр ульдуму"}},{q="Чи можуть гравці увійти до головного комплексу за дверима?",a="Ні. Внутрішній вхід назавжди запечатаний і завалений. Давні вартові зазначають, що потрапити в глибини комплексу можна лише за допомогою втрачених Пластин Ульдуму, але нині ними не обійти перепону.",al={"чи можна відчинити двері ульдуму","як зайти в ульдум","відчинити двері ульдуму"}},{q="Чому пісковикові земляни стоять нерухомо?",a="Пісковикові земляни в руїнах несправні й приспані. Від часів Великого Розколу вони перебувають у сплячці всередині комплексу й лишаються нерухомими, доки хтось чужий не нападе на них чи не потривожить Допотопну скриню.",al={"чому земляни дружні","чому земляни не нападають","пісковикові земляни пасивні"}},{q="Для чого збудували Ульдум?",a="Конструкти титанів, як-от Кам'яний Дозорець Норґаннона, описують Ульдум як дослідницький комплекс, створений, щоб вивчати, підтримувати й удосконалювати біосферу Азероту, — за походженням схожий на Ульдаман і Ульдуар.",al={"навіщо титани збудували ульдум","призначення ульдуму","лор ульдуму"}},{q="Що буде, якщо хтось відчинить Допотопну скриню?",a="Якщо потривожити скриню, спрацює давній захисний механізм і викличе ворожого конструкта — Вартового Передпокою, — щоб знищити зайду.",al={"пастка допотопної скрині","хто охороняє скриню","страж передпокою"}}},fp="14,294,29.582.0,24.555.1,34.235.0,52.204.0,45.221.0,25.205.0,53.157.0"}
P.entries["subzone:ruins-of-zul-mamwe"] = {n="Руїни Зул'Мамве",s="Руїни Зул'Мамве ховаються в гірській западині на південь від Кургану Огрів Мош'Оґґ і правлять за добре укріплену твердиню племені тролів Череполомів. Майже з усіх боків їх оточують стрімкі скелі, а прадавні кам'яні майданчики нині кишать лютими тролями джунглів під владою безжального вождя Ана'тека Жорстокого.",h="Руїни Зул'Мамве ховаються в гірській западині на південь від Кургану Огрів Мош'Оґґ і правлять за добре...",kw={"руїни зул'мамве","череполоми","ана'тек жорстокий","тролі джунглів","імперія ґурубаші","долина стренглторну"},ang={["race:Troll"]="Для тролів Темного Списа, що стали на бік Орди, Зул'Мамве — тверезе нагадування про дикі, замкнені звичаї їхніх родичів із джунглів, які не захотіли зректися кровожерливих традицій і пристосуватися до ширшого світу."},sec={{t="Твердиня Череполомів",b="Руїни Зул'Мамве — один із головних осередків влади племені Череполомів у центральній частині Долини Стренглторну. Місце лежить у природному гірському амфітеатрі, і підступитися до нього можна лише з півночі, тож тут винятково зручно оборонятися. З вершин вивітрених зикуратів і кам'яних терас вождь Ана'тек Жорстокий керує своїми воїнами й знахарями, люто захищаючи свою територію і від непроханих шукачів пригод, і від ворожих племен тролів джунглів."},{t="Рештки прадавньої імперії",b="Як і багато інших кам'яних поселень, розкиданих джунглями, Зул'Мамве — пам'ятка прадавньої Імперії Ґурубаші, що колись безроздільно панувала над південними землями континенту. Хоча велика імперія давно розкололася на ворожі угруповання, що гризуться між собою, сучасні Череполоми ревно стережуть це прабатьківське каміння й далі правлять давні племінні обряди серед зарослих мурів і повалених монолітів."}},faq={{q="Хто тримає Руїни Зул'Мамве?",a="Руїни тримає тролівське плем'я Череполомів — одне з двох панівних і войовничих племен тролів джунглів у Долині Стренглторну. На місці ними командує їхній вождь Ана'тек Жорстокий.",al={"хто тут живе","тролі зул'мамве","хто володіє зул'мамве"}},{q="Де розташований Зул'Мамве?",a="Зул'Мамве — у центрі Долини Стренглторну, трохи на південь від Кургану Огрів Мош'Оґґ. Табір майже з усіх боків оточують височенні гори, і потрапити туди можна здебільшого перевалом через долину на півночі.",al={"як дістатися до зул'мамве","розташування зул'мамве","де воно"}},{q="Чому Череполоми ворожі до мандрівників?",a="Плем'я Череполомів затято тримається осторонь і вороже ставиться до чужинців, вважаючи всі інші раси й суперницькі племена тролів зайдами на землях своїх предків. Під проводом безжального Ана'тека Жорстокого вони нападають на кожного, хто наближається до їхнього прихистку в джунглях.",al={"чому тролі нападають","ворожість череполомів"}},{q="Яка історія цих руїн?",a="Кам'яні споруди Зул'Мамве сягають часів розквіту Імперії Ґурубаші. Коли імперія розпалася на ворогуючі уламки, Череполоми зайняли це місце як базу в глибині суходолу, зберігши його давні кам'яні тераси.",al={"історія руїн","хто збудував зул'мамве","лор зул'мамве"}}},fp="18,340,32.494.0,29.411.0,36.201.0,27.218.0,48.260.0,39.254.0"}
P.entries["subzone:rustmaul-dig-site"] = {n="Розкопки Растмолів",s="Розкопки Растмолів — зруйнований розкоп на півдні Мерехтливих Низин. Його заснувала дворфійська Ліга Дослідників, щоб відкопати прадавні руїни, але табір спіткала трагедія: бойовий загін Орди вирізав копачів, а слідом із-під землі вирвався рій силітидів. Тепер смертні покинули це місце, і воно кишить ворожими комахами, що лізуть із печер унизу.",h="Розкопки Растмолів — зруйнований розкоп на півдні Мерехтливих Низин.",kw={"розкопки растмолів","ліга дослідників","моктар крін","силітиди","мерехтливі низини","дворфи"},ang={["faction:Horde"]="Хоч загін Моктара Кріна й здобув перемогу над дворфами-розкопувачами, після битви вирвалася прадавня повзуча загроза силітидів, що тепер нависає над усім краєм.",["race:Dwarf"]="Для дворфів Айронфорджа Растмол — трагічне нагадування про небезпеки, що чигають на Лігу Дослідників: тут вирізали її вчених, а тоді сама земля розступилася, випускаючи жахливих комах."},sec={{t="Різанина на солончаках",b="Рудошукачі з Ліги Дослідників Айронфорджа облаштували Розкопки Растмолів, сподіваючись відкопати забуті артефакти, поховані під солончаками. Їхні зусилля жорстоко обірвав войовничий загін Орди на чолі з Моктаром Кріном: він налетів на табір і вибив дворфів-розкопувачів до ноги. Та переможці не встигли натішитися тріумфом. Жорстока сутичка, схоже, потривожила приспану мережу печер під розкопом і випустила незліченний рій комах-силітидів, що швидко здолали й прогнали побитих уцілілих."},{t="Пробудження рою",b="Сьогодні Растмол цілком утрачено для народів поверхні. Те, що лишилося від гірничого спорядження й риштувань, поховане під шарудінням щелеп і чужинських панцирів. Уцілілі з бойового загону Моктара Кріна відступили на північ, до Табору Залізного Каменя, нажахані невпинною хвилею комах, що вирвалася після їхнього нападу."}},faq={{q="Що таке Розкопки Растмолів?",a="Це табір розкопок на Мерехтливих Низинах у Тисячі Голок. Спершу його заснували дворфи-дослідники, щоб відкопати давні руїни, але відтоді його заполонили смертоносні рої силітидів.",al={"що таке растмол","лор растмолу","розкопки мерехтливих рівнин"}},{q="Хто раніше тут жив і працював?",a="Спершу розкопки вели шукачі й копачі з дворфійської Ліги Дослідників, що відкопували артефакти й руїни, поховані під солончаками.",al={"хто копав растмол","хто володів растмолом","дворфи растмолу"}},{q="Чому розкопки покинуті й повні комах?",a="Бойовий загін Орди на чолі з Моктаром Кріном напав на табір і вирізав дворфів. Схоже, гамір потривожив підземне гніздо силітидів у печері копальні, і рій, що вирвався звідти, прогнав уцілілих нападників.",al={"що сталося в растмолі","чому тут комахи","хто напав на растмол"}},{q="Куди поділися вцілілі нападники?",a="Пошарпані рештки бойового загону Орди Моктара Кріна втекли на північ через низини, щоб оговтатися в Таборі Залізного Каменя, а гінці понесли застороги аж до Оргріммара.",al={"де моктар крін","вцілілі растмолу","зв'язок із табором залізного каменя"}}},fp="17,399,23.531.0,19.332.0,30.196.0,31.152.0,47.241.0,37.170.0"}
P.entries["subzone:rut-theran-village"] = {n="Селище Рут'теран",s="Селище Рут'теран — прибережна пристань біля південного підніжжя Тельдрассила. Головна морська гавань Дарнасуса, вона з'єднує відлюдне Світове Дерево з материковим Калімдором поромом і маршрутами гіпогрифів.",h="Селище Рут'теран — прибережна пристань біля південного підніжжя Тельдрассила.",kw={"селище рут'теран","пристань","пором","гіпогрифи","портал","дарнасус","тельдрассил","обердайн"},ang={["class:Druid"]="Друїди, що проходять через Селище Рут'теран, можуть сісти на гіпогрифа й полетіти просто через північний Калімдор до священного святилища — Місячного Гаю.",["race:NightElf"]="Для молодих нічних ельфів, що залишають Тельдрассил допомагати Альянсу, Селище Рут'теран — останнє прощання з кроною Світового Дерева перед відплиттям на материковий Калімдор."},sec={{t="Брама до Світового Дерева",b="Селище Рут'теран край води, під височенним Тельдрассилом, — поріг між столицею нічних ельфів і широким світом. Поки Дарнасус спочиває в гіллі високо вгорі, Рут'теран дає господарську основу, потрібну, щоб його утримувати. Під деревами вигинається містичний портал, що вмить переносить подорожніх між берегом і Дарнасусом. Для морських мандрівок із пристані селища ходить пором просто до Обердайна на материку, на Темному Узбережжі, а наставники польотів доглядають сідала навчених гіпогрифів."}},faq={{q="Як звідси дістатися до Дарнасуса?",a="Піднімайтеся пологим схилом від причалів до великого павільйону-намету. Ступіть просто в сяйний фіолетовий портал на помості — і миттю опинитеся в Храмових Садах у Дарнасусі.",al={"дістатися до дарнасуса","портал до дарнасуса","як потрапити до дарнасуса"}},{q="Куди ходить корабель від причалу?",a="Корабель біля причалу Селища Рут'теран, «Місячні Бризки», перевозить мандрівників через Приховане Море до містечка Обердайн на узбережжі Темного Узбережжя.",al={"куди пливе човен","пором рут'теран","маршрут корабля рут'теран"}},{q="Чому це селище внизу, біля моря, а не нагорі, на дереві?",a="Крона Тельдрассилу надто висока для звичайних вітрильників і морської торгівлі. Селище Рут'теран заснували біля його коріння, щоб мати порт на рівні моря й сідало для летючих звірів, а з висотами його сполучає постійний телепортаційний портал.",al={"чому рут'теран унизу","чому підніжжя тельдрассила"}},{q="Чи можна звідси кудись полетіти?",a="Так. На сідалі селища працює доглядач гіпогрифів: він пропонує польоти через воду до Обердайну на Темному Узбережжі, а також особливий транспорт до Місячного Гаю для друїдів Кола Кенарія.",al={"політ із рут'теран","куди летять гіпогрифи"}}},fp="18,232,25.597.0,36.205.0,37.144.0,64.242.0,29.199.0"}
P.entries["subzone:saldean-s-farm"] = {n="Ферма Салдина",s="Ферма Салдина — єдиний хутір у Вестфолі, який Братство Дефіас не захопило й не спустошило. Ним володіють уперті Фермер Салдін і його дружина Салма, і їхня хата лишається рідкісним безпечним прихистком серед лихоліття.",h="Ферма Салдина — єдиний хутір у Вестфолі, який Братство Дефіас не захопило й не спустошило.",kw={"ферма салдина","фермер салдін","салма салдін","вестфол","кулінарія","прихисток"},ang={["faction:Alliance"]="Ферма Салдина — неприкрита, надламана межа королівського прикордоння: тут видно, як тяжко страждають прості люди, коли провід Стормвінда зайнятий іншим.",["profession:Cooking"]="Салма Салдін славиться серед мандрівників тим, що з усього, що вдається роздобути у Вестфолі, готує ситні страви, які рятують життя, — як-от Пиріг із Печінки Кровоікла."},sec={{t="Світоч серед пилу",b="Поки сусідні землі падали під натиском розбійників і механічних диверсій, родина Салдінів відмовилася покинути свою землю. Фермер Салдін і його дружина Салма залишилися на хуторі й частують перехожих гарячою стравою та добрим словом. Та попри їхню стійкість, поля потерпають від збунтованих големів жнив, розкиданих рівнинами, тож родина тримається ближче до стін хати."},{t="Стояти до кінця",b="Корона Стормвінда здебільшого забула про Вестфол, тож за порядком тут майже нікому стежити. Кілька вартових із Сентінел Гілла та Стормвінда обходять околиці, але ферма тримається передусім на впертості господарів і допомозі перехожих. Для Салдінів знамените Вестфоллське Рагу Салми, Пиріг із Печінки Кровоікла й дах власної хати — невелика розрада перед вічною загрозою Дефіас."}},faq={{q="Чому ця ферма досі стоїть, коли інші впали?",a="Фермер Салдін і його дружина просто відмовилися збирати манатки й тікати, коли Братство Дефіас прокотилося Вестфолом. Хоча посівами нишпорять ворожі жнивні големи, родина вперто боронить подвір'я з допомогою ополченців і заїжджих шукачів пригод.",al={"чому ферма вціліла","виживання ферми салдина","як ферма жива"}},{q="Хто всі ці люди довкола будинку?",a="На фермі живуть Фермер Салдін і його дружина Салма; усі інші, кого ви тут побачите, найпевніше, мандрівники, бо подружжя радо приймає гостей і шукачів пригод, готових допомогти з небезпеками, що дошкуляють їхнім полям.",al={"біженці салдина","безхатченки вестфолла","сироти на фермі"}},{q="Чому механічні големи нападають на поля?",a="Братство Дефіас перетворило місцеві механічні жатки й големів на смертоносних вартових. Вони блукають полями й нападають на кожного, хто намагається обробляти чи розчищати землю.",al={"жнивні големи","чому роботи на полях","механічні опудала"}},{q="Чи захищає ферму армія Стормвінда?",a="Офіційного війська тут майже немає. Кілька розрізнених вартових із Сентінел Гілл і Стормвінда ледь-ледь пильнують околиці, але корона здебільшого полишила оборону Вестфолу на самих місцевих.",al={"присутність війська стормвінда","вартові сентінел гілла тут","підтримка варти"}}},fp="14,249,20.398.0,16.415.0,53.267.0,49.228.0,47.189.0,42.204.0"}
P.entries["subzone:saltspray-glen"] = {n="Долина Солоних Бризок",s="Долина Солоних Бризок — продуваний вітрами простір на північному заході Багнокраю, що тулиться до берегів Затоки Барадін. Сильні прибережні шквали раз у раз жбурляють солону морську воду на мохувату низину, яку заполонили агресивні дикі раптори. Вона утворює підступний природний коридор між сусідніми болотами, де кишать мурлоки, і прадавніми дворфійськими руїнами.",h="Долина Солоних Бризок — продуваний вітрами простір на північному заході Багнокраю, що тулиться до берегів...",kw={"долина солоних бризок","раптори","затока барадін","багно синьозябрих","гробниця айронбірда","багнокрай"},ang={["class:Hunter"]="Люті раптори, що нишпорять вогкою прибережною травою долини, — ситна здобич і надійні, люті звірі для слідопитів, що вистежують на узбережжі."},sec={{t="Сіль і пазурі",b="Захована в далекому північно-західному закутку Багнокраю, Долина Солоних Бризок дістала назву від морських бризок, що їх жене вглиб суходолу із Затоки Барадін щоразу, як здіймаються прибережні шквали. На півдні її облямовують води Багна Блакитнозябрих, де хазяйнують мурлоки, а на сході — тихі кручі Гробниці Айронбірда, тож долина не дає мандрівникам жодного затишку. Зграї хитрих диких рапторів гніздяться в болотяній траві й полюють на солонуватих рівнинах разом із родичами із сусіднього Кряжа Рапторів і Багна Чорного Каналу."}},faq={{q="Чому вона зветься Долиною Солоних Бризок?",a="Долина лежить просто на відкритому березі Затоки Барадін. Щойно люті морські вітри зриваються над затокою з півночі й заходу, морську воду розносить далеко вглиб низинної землі густою солоною мжичкою.",al={"значення долини солоних бризок","чому солоні бризки","походження назви"}},{q="Хто живе в Долині Солоних Бризок?",a="Долину цілком заполонили агресивні дикі раптори, для яких прибережні чагарі й болотисті улоговини — найкращі гніздовища. Вони охоче нападають із засідки на кожного, хто зійде з протоптаної стежки.",al={"монстри долини солоних бризок","раптори солоних бризок","що тут"}},{q="Куди веде Долина Солоних Бризок?",a="Долина Солоних Бризок лежить на північному заході Багнокраю. На півночі й заході вона межує із Затокою Барадін, на півдні — з мурлоцькими володіннями Багна Блакитнозябрих, а на сході — зі скелястим узвишшям Гробниці Айронбірда.",al={"розташування долини солоних бризок","де долина солоних бризок","межі"}}},fp="14,335,15.512.0,32.221.0,38.187.0,31.200.0"}
P.entries["subzone:salty-sailor-tavern"] = {n="Таверна «Солоний Моряк»",s="Таверна «Солоний Моряк» — серце світського життя Буті Бею, головний заїзд і шинок порту. Господарює тут гоблін Корчмар Скіндл, і сюди охоче заходять шахраї, найманці й мандрівники обох фракцій, щоб перепочити від небезпек джунглів.",h="Таверна «Солоний Моряк» — серце світського життя Буті Бею, головний заїзд і шинок порту.",kw={"солоний моряк","таверна","буті бей","корчмар скіндл","пірати","нейтральна територія"},ang={["class:Rogue"]="Тісна, задимлена зала «Солоного Моряка» — ідеальне місце, щоб обмінятися чутками, підслухати піратські балачки й не спускати ока зі свого гаманця."},sec={{t="Безпечна гавань у джунглях",b="Таверна «Солоний Моряк», що примостилася серед дерев'яних ярусів Буті Бею, пропонує теплі ліжка й міцні напої під пильним оком Нападників Чорної Води. За шинквасом стоїть Корчмар Скіндл і стежить, щоб келихи не порожніли, а тим часом строката юрба буканірів, торговців і шукачів пригод гуляє пліч-о-пліч на нейтральній території. Знадвору висить величезна дивовижа — Камінь Захисника Зул'Ґурубу, химерний трофей у цьому гамірному кублі торгівлі."}},faq={{q="Хто тримає Таверну «Солоний Моряк»?",a="Таверною й корчмою опікується Корчмар Скіндл — працьовитий гоблін, що обслуговує всіляких моряків, найманців і шукачів пригод, які проходять через Буті Бей.",al={"корчмар","хто корчмар","скіндл"}},{q="Що за великий камінь висить біля таверни?",a="Біля будівлі висить Камінь-Захисник Зул'Ґурубу — зловісна реліквія, привезена з давніх тролівських руїн у глибині джунглів.",al={"камінь біля таверни","камінь зул'ґуруб","камінь-захисник"}},{q="Чи можуть тут зупинятися і Альянс, і Орда?",a="Так. Як і весь Буті Бей, Таверна «Солоний Моряк» живе під нейтральною владою картелю Стімвідл. Доки відвідувачі поводяться чемно й не хапаються за зброю, і мандрівники Альянсу, і мандрівники Орди можуть тут спокійно відпочити.",al={"чи нейтральна","альянс і орда дозволені","чи може орда користуватися корчмою"}}},fp="19,279,26.453.0,33.179.0,52.145.0,38.244.0"}
P.entries["subzone:sanctum-stromgarde-keep"] = {n="Святилище (Фортеця Стромгард)",s="Святилище — священний оплот, захований за каплицею у Фортеці Стромгард. Сховане серед мурів фортеці, що розсипаються, воно стереже вхід до родового склепу Троллбейнів і лишається одним з останніх оплотів Святого Світла посеред аратійських руїн.",h="Святилище — священний оплот, захований за каплицею у Фортеці Стромгард.",kw={"святилище","фортеця стромгард","каплиця","святе світло","ґален троллбейн","склеп","паладини"},ang={["class:Paladin"]="Каплиця й Святилище — останні неосквернені святині Святого Світла в занепалій столиці Аратійського нагір'я, тож їхня оборона — справа урочистого обов'язку.",["faction:Alliance"]="Утримуючи Святилище, королівський рід Троллбейнів зберігає владу над престолом предків, а отже, Альянс і далі присутній у спірних руїнах Стромґарда."},sec={{t="Оплот серед руїн",b="Хоча значна частина Фортеці Стромгард дісталася лазутчикам Синдикату й ограм Каменекулаків, Святилище й сусідню каплицю досі завзято боронять уцілілі захисники Стромґарда. Святилище, що лежить за храмом, межує з цвинтарем цитаделі й позначає поріг королівського склепу, де спочивають королі Стромґарда. Для знесилених вірних, що згуртувалися довкола Принца Ґалена Троллбейна, утримати цю освячену землю — більше, ніж тактична перевага: це відчайдушна боротьба за те, щоб загарбники не потоптали спадщину й віру їхнього королівства."},{t="Поріг королів",b="Під кам'яними плитами Святилища починається хід до королівської гробниці. Земля тут освячена: це місце мало слугувати для тихих роздумів і поклоніння Святому Світлу. Та після вбивства короля Тораса Троллбейна й подальшого розпаду королівства Святилище стало оборонним сховком. Хто захоче пробитися в його глибини, мусить подолати не лише королівську варту, що стоїть по всіх залах, а й моторошну правду: прадавній людський рід із останніх сил чіпляється за життя на своєму священному порозі."}},faq={{q="Що таке Святилище?",a="Святилище — внутрішня частина за каплицею Церкви Світла у Фортеці Стромгард. Воно прилягає до цвинтаря фортеці й веде просто до родового склепу Троллбейнів.",al={"що таке святилище","святилище стромґарду","святилище фортеці стромґард"}},{q="Хто зараз тримає Святилище?",a="Святилище тримають уцілілі вояки Стромґарда, вірні Альянсу й Принцові Ґалену Троллбейну. На відміну від решти зруйнованого міста, яке заполонили розбійники Синдикату й огри-Каменекулаки, каплиця й Святилище досі під людською вартою.",al={"хто в святилищі","охорона святилища","хто тримає святилище"}},{q="Що лежить за Святилищем?",a="За Святилищем — родовий склеп Троллбейнів, де поховано полеглих правителів Стромґарда, зокрема нещодавно вбитого короля Тораса Троллбейна.",al={"куди веде святилище","склеп святилища","що за святилищем"}},{q="Чому ця частина важлива для Стромґарда?",a="Святилище — не лише освячене місце поклоніння Святому Світлу, а й захист королівської усипальниці королів Стромґарда. Для вцілілих захисників здати його означало б дозволити загарбникам осквернити могили предків.",al={"чому святилище важливе","значення святилища","чому охороняють святилище"}}},fp="25,272,22.618.0,22.542.0,20.183.0,35.238.0,29.154.0,41.249.0"}
P.entries["subzone:sandsorrow-watch"] = {n="Чата Піщаної Скорботи",s="Чата Піщаної Скорботи — розлога пустельна застава трохи на захід від Ґаджетзана в Танарісі. Довколишні дюни й руїни заполонили ворожі тролі Піщаної Люті та їхні воскрешені мерці, а східна сторожова вежа височіє над пустелею, мов спостережний пост.",h="Чата Піщаної Скорботи — розлога пустельна застава трохи на захід від Ґаджетзана в Танарісі.",kw={"чата піщаної скорботи","піщана лють","фарракі","тролі","ґаджетзан","танаріс"},ang={["profession:Blacksmithing"]="У вежі, яку тримає Піщана Лють, ковалів немає: пустельні ковалі збираються за мурами Ґаджетзана, трохи на схід.",["race:Troll"]="Тролі Темного Списа не знайдуть тут спорідненості: вороже плем'я Фарракі з Піщаної Люті вважає всіх чужинців загарбниками, яких треба знищити й підняти як мерців, що човгають ногами."},sec={{t="Ненадійний пост",b="Чата Піщаної Скорботи, що лежить просто на захід від гамірного гоблінського торгового осередку Ґаджетзан, — похмуре прикордоння в пустелі Танаріс. Цим широким простором володіє плем'я Піщаної Люті, яке ще називають тролями Фарракі: вони люто боронять посушливу територію разом із легіонами тролів-зомбі, що човгають ногами. Позицію утримує висока сторожова вежа на східному краю — укріплений оглядовий пункт серед пустельної глушини й ворожих місцевих племен."},{t="Прикордонна застава",b="Навіть сторожову вежу на східному краю, звідки видно мури Ґаджетзана, тримають тролі Піщаної Люті. З її висоти Фарракі пильно стежать за гоблінським містечком, а мандрівники, які виходять із західної брами Ґаджетзана, майже одразу потрапляють на їхню територію — постійне нагадування про вибухову напругу на прикордонні між заповзятливими поселенцями Танарісу й місцевими піщаними тролями."}},faq={{q="Де розташована Чата Піщаної Скорботи?",a="Чата Піщаної Скорботи — просто на захід від Ґаджетзана, на північних пустельних рівнинах Танарісу. Мандрівники, що виходять із Ґаджетзана західною брамою, натрапляють на неї майже одразу.",al={"розташування чати піщаної скорботи","де піщана скорбота","як дістатися до чати піщаної скорботи"}},{q="Хто тримає Чату Піщаної Скорботи?",a="Руїни, довколишні дюни й східну сторожову вежу займають ворожі тролі Піщаної Люті та їхні прислужники-нежить.",al={"хто в піщаній скорботі","фракція чати піщаної скорботи","хто тримає чату піщаної скорботи"}},{q="Звідки в Чаті Піщаної Скорботи тролі-нежить?",a="Плем'я Піщаної Люті вдається до темної некромантії й вуду: вони часто піднімають полеглих воїнів-фарракі як зомбі Піщаної Люті, щоб ті стерегли їхні пустельні володіння й застави по всьому Танарісу.",al={"зомбі піщаної люті","чому тролі-зомбі танаріс","зомбі піщаної скорботи"}},{q="Які загрози чекають шукачів пригод серед довколишніх дюн?",a="Тут щільно патрулюють метальники сокир, закликачі вогню й білувальники Піщаної Люті разом зі своїми оживленими тролями-зомбі. Непідготовлені мандрівники, що зійдуть із головної дороги на захід від Ґаджетзана, легко потраплять під удар блукаючих бойових загонів фарракі.",al={"моби піщаної скорботи","вороги чати піщаної скорботи","ворожі тролі піщаної скорботи"}}},fp="16,260,18.489.0,16.386.0,34.189.0,30.130.0,48.188.0,61.249.0"}
P.entries["subzone:sar-theris-strand"] = {n="Узбережжя Сар'теріс",s="Узбережжя Сар'теріс — західна берегова лінія Пустограю, що виходить до Прихованого Моря. На противагу безплідним сірим пустирям усередині краю, берег тут сонячний і трав'янистий, хоча й небезпечний через наг, морських велетнів і макрур.",h="Узбережжя Сар'теріс — західна берегова лінія Пустограю, що виходить до Прихованого Моря.",kw={"узбережжя сар'теріс","пустограй","наги","макрури","морські велетні","рибальство","приховане море"},ang={["profession:Cooking"]="Береги узбережжя й навколишні води багаті на морську здобич — тут і макрури, і рідкісна океанська риба, — проте кухонні вогнища доводиться розпалювати під постійним наглядом наг, що нишпорять поблизу."},sec={{t="Зелена облямівка сірих пустирів",b="Узбережжя Сар'теріс, що тягнеться вздовж усього західного Пустограю, дарує дивний перепочинок від попелу й пилу внутрішніх рівнин. Тут верхівки скель і пляжі яскраві й зелені. Та гостинним це узбережжя не назвеш: у прибої патрулюють зміюваті наги, поруч із ними — височенні морські велетні й ревниві до своєї території макрури. Мілини всіяні уламками кораблів — від розбитого судна Карнітола на півночі до маленьких розтрощених човнів під вежами Етель Ретор, — і це доводить, що море тут таке ж підступне, як і берег."},{t="Уламки й рідкісні води",b="Окрім постійної загрози від наг і велетнів, води біля узбережжя відомі серед досвідчених мандрівників своїми незвичайними дарами. Зубчасті прибережні мілини ховають рештки загублених експедицій і купецьких походів, а в глибокому прибої водиться рідкісна морська живність — зокрема цінований Сар'теріський Окунь, якого шукають майстри-рибалки з усього Калімдору."}},faq={{q="Чому Узбережжя Сар'теріс зелене, коли решта Пустограю мертва?",a="Узбережжя сонячне й трав'янисте — на противагу безплідній сірій глибині Пустограю. Джерела не пояснюють, звідки береться такий контраст.",al={"чому узбережжя зелене","трав'яне узбережжя дезолас","погода сар'теріс"}},{q="Хто живе на Узбережжі Сар'теріс?",a="На узбережжі панують наги-амфібії Ковзкого Клинка, блукають морські велетні й снують макрури. Мандрівникам слід пильно стежити за прибоєм, бо патрулі ходять біля самої води.",al={"хто тут живе","моби сар'теріс","монстри узбережжя"}},{q="Які корабельні уламки лежать на березі?",a="Уламки «Карнітола» лежать у північних водах узбережжя, а менші судна розбиті об прибережні кручі під зруйнованими ельфійськими вежами Етель Ретора.",al={"корабель карнітоль","затонулі човни узбережжя","уламки на пляжі"}},{q="Чому рибалки шукають Узбережжя Сар'теріс?",a="Лише тутешні прибережні води — дім Сар'теріського Окуня, невловимої риби, яку славетний рибалка Нат Паґл вважає одним із найвищих випробувань рибальської майстерності.",al={"ударник сар'теріс","риболовля дезолас","риба ната паґла"}}},fp="17,241,28.496.0,24.369.0,65.143.0,41.190.0,36.169.0,44.178.0"}
P.entries["subzone:sardor-isle"] = {n="Острів Сардор",s="Острів Сардор — зелений острів біля західного узбережжя Фераласу, на північ від небезпечного Острова Жаху. На ньому стоїть Твердиня Перистого Місяця — головний військовий оплот нічних ельфів на півдні Калімдора. Хоч Вартових тут чимало, частиною острова досі нишпорять дикі звірі й ворожі наги, що вилазять із мілин.",h="Острів Сардор — зелений острів біля західного узбережжя Фераласу, на північ від небезпечного Острова Жаху.",kw={"острів сардор","твердиня перистого місяця","шандріс фезермун","вартові","наги","фералас"},ang={["faction:Alliance"]="Острів Сардор — головна опора сили Альянсу у Фераласі: у Твердині Перистого Місяця на вас чекають безпечна гавань, припаси й приборкувачі гіпогрифів.",["race:NightElf"]="Під проводом генерала Шандріс Фезермун Вартові на Острові Сардор пильно стежать за прадавніми руїнами й новою загрозою з боку наг по всьому Фераласу."},sec={{t="Оплот Вартових і дикі береги",b="Острів Сардор лежить через протоку від материкового Фераласу, а його серце — Твердиня Перистого Місяця, вражаюча ельфійська фортеця під командуванням генерала Шандріс Фезермун. Сама фортеця добре укріплена, а з материком її пов'язують регулярні поромні переправи, та решта острова аж ніяк не приручена. Порослі лісом схили належать вовчим зграям, а на скелястих західних і північних берегах чатують наги, що підбираються дедалі ближче й раз у раз випробовують стійкість вартових нічних ельфів."}},faq={{q="Де розташований Острів Сардор?",a="Острів Сардор лежить біля західного узбережжя Фераласу на півдні Калімдору, трохи на північ від Острова Жаху. Дістатися туди можна човном, що ходить із Забутого Узбережжя на суходолі.",al={"розташування острова сардор","де сардор","знайти острів сардор"}},{q="Яке головне поселення на Острові Сардор?",a="На острові панує Твердиня Перистого Місяця — головна фортеця й плацдарм нічних ельфів і Альянсу у Фераласі під командуванням генерала Шандріс Фезермун.",al={"хто живе на острові сардор","місто острова сардор","база нічних ельфів сардор"}},{q="Які небезпеки чатують на острові за межами твердині?",a="За захисними мурами Твердині Перистого Місяця мандрівників чекають зграї диких вовків у лісах, а також ворожі наги, що чатують біля прибережних рифів і пляжів.",al={"вороги острова сардор","небезпека на сардорі","монстри сардора"}},{q="Чим Острів Сардор відрізняється від Острова Жаху?",a="Острів Сардор лежить на півночі, і на ньому міцно отаборилися нічні ельфи з Твердині Перистого Місяця. Острів Жаху — південніше, і це значно суворіший, дикий край, де аж кишать небезпечні хімери й наги.",al={"острів сардор проти острова жаху","відмінність від острова жаху"}}},fp="11,355,32.491.0,29.184.0,43.181.0,60.181.0,51.221.0"}
P.entries["subzone:sargeron"] = {n="Сарґерон",s="Сарґерон — руїни давнього міста нічних ельфів на півночі Пустограю. Місто розтрощив Великий Розкол, а колишні храми Елуни сплюндрували й захопили сатири Лютої Ненависті, які перейменували це місце на честь свого господаря Сарґераса.",h="Сарґерон — руїни давнього міста нічних ельфів на півночі Пустограю.",kw={"сарґерон","пустограй","нічні ельфи","елуна","сатири","сарґерас","руїни"},ang={["class:Priest"]="Жерці Місяця впізнають рештки Собору Елуни та святі реліквії, розкидані серед уламків, — і відчують заклик очистити їх.",["race:NightElf"]="Для кожного калдорея ці руїни — болісне видовище: демонічні сатири відкрито оскверняють священні вівтарі Елуни й глузують з богині в ім'я Сарґераса."},sec={{t="Сплюндроване святилище",b="До того як Війна Прадавніх розколола континент, це поселення було квітучим осередком поклоніння Елуні з такими святими місцями, як Храм Елуни, Святилище й Собор. Його справжня назва загубилася в давнині. Коли світ розколовся, місто обернулося на руїни, лишивши по собі освячені реліквії — Чашу Елуни, Жаровню Елуни та Служницю Елуни. За тисячоліття, що минули відтоді, ці камені заполонили зіпсовані сатири Лютої Ненависті й перетворили священну калдорейську архітектуру на твердиню на честь титана Сарґераса."}},faq={{q="Як звався Сарґерон до Розколу?",a="Його первісна назва нічними ельфами загубилася в часі. Нинішню назву, Сарґерон, руїнам дали сатири Ненависної Люті на шану полеглому титанові Саргерасу.",al={"первісна назва","первісна назва сарґерона","як він називався"}},{q="Хто тепер займає Сарґерон?",a="Руїни займають сатири Ненависної Люті — зіпсовані демонічні створіння, що з'явилися під час Війни Прадавніх і завзято оскверняють давні ельфійські святині.",al={"хто тут живе","моби сарґерона","вороги сарґерона"}},{q="Які святі місця колись тут були?",a="У місті було кілька великих святинь Місячної Богині — зокрема Храм Елуни, Святилище Елуни й Собор Елуни, де колись зберігалися шановані реліквії, як-от Чаша Елуни.",al={"храми елуни","святі місця","які будівлі були тут"}},{q="Чому Сарґерон важливий для нічних ельфів?",a="Він — похмуре нагадування про Війну Прадавніх і осквернення святинь калдореїв демонічними силами, а ще тут лежать давні ельфійські артефакти, які можуть бути втрачені чи зіпсовані.",al={"лор нічних ельфів сарґерон","чому нічним ельфам важливий"}}},fp="8,270,19.549.0,46.166.0,26.156.0,45.192.0,43.186.0"}
P.entries["subzone:satyrnaar"] = {n="Сатирнаар",s="Сатирнаар — давнє зруйноване поселення нічних ельфів на північному сході Ашенвалю, яке цілком опинилося в руках сатирів Похмурого Серця. Розташоване трохи осторонь головної дороги між Заставою Розщепленого Дерева й Азшарою, це найкраще збережена й найдоступніша з твердинь сатирів у лісі.",h="Сатирнаар — давнє зруйноване поселення нічних ельфів на північному сході Ашенвалю, яке цілком опинилося в...",kw={"сатирнаар","сатири","похмуросерді","культ темного берега","руїни","ашенваль"},ang={["class:Druid"]="Спотворена скверна, яку ширять сатири Похмурого Серця, душить природний дух Ашенвалю, і її треба якнайшвидше очистити.",["race:NightElf"]="Бачити, як каміння предків оскверняє скверна, а в руїнах живуть прокляті нащадки Високородних, — гірка образа для кожного нічного ельфа, що мандрує Ашенвалем."},sec={{t="Лігво скверни й тіні",b="Сатирнаар, що лежить на північний схід від Застави Розщепленого Дерева й на південний захід від Лісової Пісні, — одне з трьох головних поселень сатирів в Ашенвалі поряд із Ксавіаном і Нічним Потоком. На відміну від руїн у глибині нетрів, Сатирнаар порівняно добре зберігся: серед напівзруйнованої ельфійської архітектури стоять намети. Це гамірний табір сатирів Похмурого Серця, через який торговий шлях неподалік стає небезпечним для мандрівників, що прямують на схід до Азшари. Ба більше, тут визрівають темні зв'язки: сатири уклали союз із таємничим Культом Темного Берега й ховають серед оскверненого каміння один із його підступних самоцвітів душ."}},faq={{q="Що таке Сатирнаар?",a="Сатирнаар — руїни нічних ельфів на північному сході Ашенвалю, які захопили сатири Похмурого Серця. Це одна з їхніх головних твердинь у краї.",al={"огляд сатирнаару","що це за місце","табір сатирів"}},{q="Хто живе в Сатирнаарі?",a="Поселення тримає плем'я сатирів Похмурого Серця. Вони поставили намети серед давніх руїн і діють у змові з Культом Темного Берега.",al={"хто тут","моби сатирнаару","сатири похмурого серця"}},{q="Чим Сатирнаар важливіший за інші руїни сатирів?",a="З трьох головних осередків сатирів в Ашенвалі — Сатирнаару, Нічного Потоку й Ксавіана — Сатирнаар найцілісніший і розташований найзручніше: просто біля дороги до Азшари.",al={"сатирнаар проти ксавіану","чому сатирнаар"}},{q="Що за темний артефакт захований у Сатирнаарі?",a="У Сатирнаарі зберігається один із зіпсованих самоцвітів душ Культу Темного Берега — смертного тіньового культу, що в союзі із сатирами Похмурого Серця.",al={"камінь душі темного берега","кристал сатирнаару","камінь душі"}}},fp="9,298,23.645.0,18.184.0,23.158.0,59.172.0,46.144.0"}
P.entries["subzone:savage-coast"] = {n="Дикунське Узбережжя",s="Дикунське Узбережжя — скелястий західний берег північної частини Долини Стренглторну, що тягнеться від південного кордону Вестфолу аж до Базового Базового Табору Ґром'ґол. Тут нишпорять річкові кроколіски, прибережні василіски й ворожі племена тролів, і з кожним припливом цей берег знову виправдовує свою жорстоку назву.",h="Дикунське Узбережжя — скелястий західний берег північної частини Долини Стренглторну, що тягнеться від...",kw={"дикунське узбережжя","долина стренглторну","кроколіски","василіски","ґром'ґол","вестфол"},ang={["class:Hunter"]="Пляжі рясніють кроколісками й василісками: тут є кого вистежувати, з кого знімати шкуру і кого приручати.",["faction:Horde"]="Північна частина узбережжя лежить трохи вище від Базового Базового Табору Ґром'ґол і править за буферну смугу, що прикриває табір від звірини й агресивних загонів тролів біля Великого Моря."},sec={{t="Підступний берег",b="Дикунське Узбережжя біжить від скель на межі з Вестфолом на південь до Базового Базового Табору Ґром'ґол і позначає небезпечний західний край північної частини Долини Стренглторну. Піщані береги не надто гостинні: між калюжами, що лишає відплив, і викинутими на берег колодами вільно бродять клацозуби, кроколіски й кам'яні скрадачі. Трохи далі від моря стоять табори тролів джунглів, які ревно стережуть свою землю, тож будь-яка прогулянка пляжем обертається боротьбою за виживання. А в морі дно опускається до підводних небезпек Мерзенного Рифу, тож загроза чигає і на піску, і під хвилями."}},faq={{q="Де розташоване Дикунське Узбережжя?",a="Дикунське Узбережжя тягнеться західним морським краєм північної частини Долини Стренглторну. Воно починається біля кордону з Вестфолом на півночі й простягається на південь повз води біля Мерзенного Рифу аж до Базового Базового Табору Ґром'ґол.",al={"розташування дикунського узбережжя","де дикунське узбережжя","дикунське узбережжя на мапі"}},{q="Хто живе на Дикунському Узбережжі?",a="Берег заполонили небезпечні звірі — найперше агресивні кроколіски й василіски, що гріються на піску. Одразу за лінією води й на сусідніх кручах джунглів ворожі тролівські племена тримають табори з видом на прибій.",al={"моби дикунського узбережжя","що на дикунському узбережжі","звірі дикунського узбережжя"}},{q="Чи безпечне Дикунське Узбережжя для мандрівників, що йдуть на південь із Вестфолу?",a="Аж ніяк. Якщо входити в Долину Стренглторну вздовж узбережжя, можна оминути густі джунглі, але Дикунське Узбережжя кишить лютими хижаками-амфібіями й місцевими тролями-воїнами, які швидко здолають необачних мандрівників.",al={"шлях зі вестфолла до стренґлторну","від вестфолла до дикунського узбережжя"}},{q="Які прикмети є біля Дикунського Узбережжя?",a="Просто біля берега лежить затонулий Мерзенний Риф, а далі вздовж узбережжя — укріплена застава Орди, Базовий Табір Ґром'ґол. На півночі кручі здіймаються до ферм і узбережжя Вестфолу.",al={"пам'ятки дикунського узбережжя","що біля дикунського узбережжя"}}},fp="12,282,20.539.0,26.227.0,43.251.0,66.215.0,41.207.0"}
P.entries["subzone:scarab-dais"] = {n="Поміст Скарабея",s="Поміст Скарабея — прадавнє кам'яне підвищення на північний захід від Стіни Скарабея на півдні Силітусу. На ньому стоїть легендарний Гонг Скарабея — обрядовий інструмент, безпосередньо пов'язаний із магічними оберегами, що замикають імперію кіражів в Ан'Кіражі.",h="Поміст Скарабея — прадавнє кам'яне підвищення на північний захід від Стіни Скарабея на півдні Силітусу.",kw={"поміст скарабея","гонг скарабея","ан'кіраж","скіпетр мінливих пісків","силітус","кіражі"},ang={["race:NightElf"]="Для калдореїв Поміст Скарабея — суворе нагадування про трагічну Війну Мінливих Пісків тисячу років тому, коли нічні ельфи й драконячі роди заплатили кров'ю, щоб замкнути кіражів за стіною."},sec={{t="Гонг Ан'Кіражу",b="Поміст Скарабея, звідки видно мінливі піски перед велетенською перепоною Стіни Скарабея, — серце печаті, накладеної на Ан'Кіраж тисячу років тому. На цьому кам'яному помості спочиває Гонг Скарабея — реліквія, викувана під час Війни Мінливих Пісків. Згідно з прадавніми переказами нічних ельфів і бронзової драконячого роду, вдарити в цей гонг відновленим Скіпетром Мінливих Пісків — єдиний спосіб зламати магічний бар'єр і прорвати браму. Доки не настала та доленосна мить, поміст стоїть зловісною вартою над запечатаними жахіттями-комахами, що дрімають за стіною."}},faq={{q="Що таке Поміст Скарабея?",a="Поміст Скарабея — кам'яна обрядова тераса на півдні Силітусу, трохи на північний захід від Стіни Скарабея. Її збудували для Гонгу Скарабея, що керує чарівними захистами, якими запечатано Ан'Кіраж.",al={"що це за платформа","поміст скарабея інформація","платформа з гонгом"}},{q="Що буде, якщо вдарити в гонг на помості?",a="Легенда каже: якщо вдарити в Гонг Скарабея відновленим Скіпетром Мінливих Пісків, захисні чари Стіни Скарабея розлетяться, брама Ан'Кіража відчиниться, і на волю вийдуть ув'язнені там армії кіраджі.",al={"що робить гонг","вдарити в гонг скарабея","вдарити гонг"}},{q="Хто пильнує Поміст Скарабея?",a="Посланці бронзового драконячого роду, як-от дракон Ронорму, пильнують поміст і запечатану браму, стережучи їх від смертних і сектантів, що хотіли б передчасно втрутитися в бар'єр.",al={"хто біля помосту","бронзові дракони біля помосту","рононму"}}},fp="11,242,21.618.0,24.207.0,51.220.0,33.194.0"}
P.entries["subzone:scarab-wall"] = {n="Стіна Скарабея",kw={"стіна скарабея","ан'кіраж","війна мінливих пісків","кіражі","бронзова драконячий рід","силітус"},ang={["class:Druid"]="Друїди відчувають, як уздовж периметра неприродно пригнічено життя: прадавні обереги ледве стримують підземну заразу, що все псує.",["race:NightElf"]="Для нічних ельфів ця стіна — священний пам'ятник жахливим жертвам Війни Мінливих Пісків, коли ціле покоління полягло, щоб зупинити рій."},sec={{t="Щит проти Тіні",b="Стіна Скарабея, що тягнеться пустелею зі сходу на захід, постала тисячу років тому наприкінці катастрофічної Війни Мінливих Пісків. Кіражі поставили армії нічних ельфів на межу знищення, але ті разом із союзниками-драконами загнали рої назад у прадавнє царство. Щоб стримати їх навіки, калдореї обернули пустельний камінь на величезний вал заввишки щонайменше сто футів, а бронзова драконячий рід виплела над ним колосальний магічний бар'єр. Дарнаською мовою стіну називають Ірана'етіл — «Щит проти Тіні». Вона таки відрізала армії комах від Калімдору, хоча жахлива присутність, замкнена за її камінням, відчутна й досі."},{t="Запечатані руїни",b="Beyond the sandstone masonry and draconic wards lies Ahn'Qiraj, a stronghold of the ancient qiraji. The wall was raised to imprison their armies after the War of the Shifting Sands. Its gates can be opened by ringing the Scarab Gong with the Scepter of the Shifting Sands, a relic tied to the dragons and Fandral Staghelm."}},faq={{q="Що таке Стіна Скарабея?",a="Стіна Скарабея — величезний кам'яний і чарівний бар'єр на південному краю Силітусу. Її звели, щоб запечатати давнє комашине королівство Ан'Кіраж і тримати його ненажерливі рої замкненими в пустельних руїнах.",al={"призначення стіни скарабея","що це за стіна в силітусі","стіна ан'кіраджа"}},{q="Хто збудував Стіну Скарабея?",a="Її спільно створили нічні ельфи й бронзовий драконячий рід наприкінці Війни Мінливих Пісків. Ельфи виліпили з пустельної скелі стіну заввишки сто футів, а дракони накинули над нею неосяжний чарівний бар'єр.",al={"хто збудував стіну","хто створив стіну скарабея"}},{q="Що означає Ірана'етіл?",a="Ірана'етіл — дарнаська назва Стіни Скарабея, яку їй дали нічні ельфи, що її створили. Приблизно вона перекладається як «Щит проти Тіні».",al={"значення ірана'етіл","ельфійська назва стіни скарабея"}},{q="Чи можуть гравці пройти за стіну?",a="The Scarab Wall was raised to seal Ahn'Qiraj, but its gates can be opened by ringing the Scarab Gong with the Scepter of the Shifting Sands.",al={"чи можна пройти за стіну скарабея","як пройти стіну в силітусі"}}},fp="11,329,25.704.0,13.322.1,24.223.0,26.250.0,27.147.0,29.140.0"}
P.entries["subzone:scarlet-base-camp"] = {n="Багряний Базовий Табір",s="Багряний Базовий Табір — укріплена застава на східному березі Озера Мерельдар у Східних Чумних Землях, трохи на захід від Руки Тіра. Його барикади позначають зовнішній рубіж оборони Багряного Хрестового Походу.",h="Багряний Базовий Табір — укріплена застава на східному березі Озера Мерельдар у Східних Чумних Землях, трохи...",kw={"багряний базовий табір","застава","озеро мерельдар","рука тіра","багряний хрестовий похід"},ang={["class:Paladin"]="Табір відбиває трагічне спотворення спадщини Срібної Длані: праведна завзятість у захисті святої землі Лордерона переродилася тут в агресивну параною щодо інших уцілілих.",["race:Undead"]="Застава — пряме нагадування про живих фанатиків, які прагнуть вичистити Відступників із Лордерона так само безжально, як полюють на безтямну Погибель."},sec={{t="Передова лінія на Озері Мерельдар",b="Багряний Базовий Табір, що стоїть на східному березі Озера Мерельдар, — обнесене барикадами укріплення трохи на захід від Руки Тіра. Він позначає зовнішню позицію Багряного Хрестового Походу в зачумленій сільській місцевості."},{t="Щит для твердині",b="Рука Тіра — одна з твердинь Багряного Хрестового Походу в Лордероні. Табір лежить на її західних підступах, у краї, де Похід прагне відвоювати землю в нежиті й з підозрою ставиться до чужинців."}},faq={{q="Для чого потрібен Багряний Базовий Табір?",a="Табір — забарикадоване укріплення Багряного Хрестового Походу на східному березі Озера Мерельдар, трохи на захід від Руки Тіра.",al={"що таке багряний базовий табір","чому тут багряний табір","призначення базового табору"}},{q="Хто очолює сили в таборі?",a="Командир первісного табору в класичній версії не названий. Це позиція Багряного Хрестового Походу біля Руки Тіра.",al={"хто очолює багряний базовий табір","командир табору","лідери багряного табору"}},{q="Чи ворожі тутешні мешканці до мандрівників?",a="Багряний Хрестовий Похід ворожий до чужинців з обох фракцій і вважає їх можливими носіями чуми чи агентами Погибелі.",al={"чи нападе багряний базовий табір","чи ворожий багряний табір","чи вони дружні"}},{q="Де стоїть табір відносно Озера Мерельдар?",a="Він стоїть на східному березі Озера Мерельдар, трохи на захід від Руки Тіра.",al={"озеро мерельдар біля багряного табору","де багряний табір","табір біля руки тіра"}}},fp="17,203,31.197.0,21.221.0,45.117.0,43.107.0,39.138.0,47.67.0"}
P.entries["subzone:scarlet-basilica"] = {n="Багряна Базиліка",s="Багряна Базиліка — величний собор у самому серці Руки Тіра у Східних Чумних Землях. Це найвищий осередок духовної й військової влади Багряного Хрестового Походу на сході. Під проводом Лорда-хрестоносця Вальдельмара її зали стали непохитним оплотом фанатиків проти Погибелі.",h="Багряна Базиліка — величний собор у самому серці Руки Тіра у Східних Чумних Землях.",kw={"багряна базиліка","собор","рука тіра","вальдельмар","багряний хрестовий похід"},ang={["class:Paladin"]="Базиліка — спотворений пам'ятник святій відданості, що збилася з путі: колишні лицарі Срібної Длані обернули свій запал на безжальний фанатизм.",["race:Undead"]="Для Відступників базиліка — один із найукріпленіших форпостів фанатиків, які прагнуть цілковито знищити всю нежить, байдуже, чи має вона власну волю."},sec={{t="Серце східного Походу",b="Багряна Базиліка, що гордо височіє над укріпленим анклавом Руки Тіра, — головний собор і командний центр Багряного Хрестового Походу у Східних Чумних Землях. Духовне серце ордену — Багряний Монастир далеко на заході, у Галявинах Тірісфалю, а ця базиліка тримає вцілілу територіальну твердиню хрестоносців серед зачумлених жахіть Лордерона. Добірні хрестоносці люто стережуть собор, де перебуває Лорд-хрестоносець Вальдельмар: він керує місцевою обороною й завзято знищує кожного чужинця, що наважиться підійти."}},faq={{q="Що таке Багряна Базиліка?",a="Багряна Базиліка — величний собор у місті-фортеці Рука Тіра у Східних Чумних землях. Це головний осідок релігійної й військової влади Багряного Хрестового Походу в краї.",al={"багряна базиліка інформація","що це за собор","церква руки тіра"}},{q="Хто очолює сили в Базиліці?",a="Силами в Багряній Базиліці командує Лорд-хрестоносець Вальдельмар — один із високопоставлених ватажків Багряного Хрестового Походу, що тримає Руку Тіра проти Погибелі й інших, кого орден має за ворогів.",al={"хто в багряній базиліці","вальдельмар","бос багряної базиліки"}},{q="Як вона порівнюється з Багряним Монастирем?",a="Багряний Монастир на Галявинах Тірісфалю — головний духовний штаб ордену, а Багряна Базиліка — його східний відповідник, могутній релігійний і укріплений осередок глибоко в Чумних Землях.",al={"монастир проти базиліки","чи це багряний монастир"}},{q="Чи раді в Базиліці мандрівникам?",a="Ні. Багряний Хрестовий Похід скотився в божевільну ненависть до чужинців і вірить, що кожен, хто не вбраний у його багряні кольори, заражений нежиттям. На зайд з Альянсу й з Орди нападають одразу.",al={"чи може альянс зайти","чи ворожа багряна базиліка","чи можна відвідати"}}},fp="16,315,28.565.0,29.223.0,41.202.0,47.237.0,42.209.0"}
P.entries["subzone:scarlet-monastery"] = {n="Багряний Монастир",s="Багряний Монастир, що стоїть на північно-східних пагорбах Галявин Тірісфалю, колись був мирним осередком науки й богослужіння Церкви Святого Світла. Після падіння Лордерону він став добре укріпленою твердинею фанатичного Багряного Хрестового Походу. Кожного, хто наближається без червоних барв, мають за заразного носія чуми і страчують на місці.",h="Багряний Монастир, що стоїть на північно-східних пагорбах Галявин Тірісфалю, колись був мирним осередком...",kw={"багряний монастир","багряний хрестовий похід","моґрейн","вайтмейн","монастир","собор","тірісфаль"},ang={["class:Paladin"]="Колись цей комплекс готував паладинів під проводом Срібної Длані, тож його переродження на нетерпимий бастіон фанатизму — гірке видовище для вірних святих воїнів.",["faction:Horde"]="Монастир стоїть просто на порозі Андерсіті, тож його добре озброєні хрестоносці — діяльна, смертельна загроза землям Відступників."},sec={{t="Від святині до твердині",b="До Третьої війни цей комплекс знали просто як Старий Монастир. Під опікою духівництва Лордерону й покровительством шляхетних домів він був важливим осередком богословських студій, священних архівів і вишколу паладинів. Коли Королівство Лордерон упало перед Погибеллю, уцілілі рештки Срібної Длані повернули собі це місце як передовий бастіон для ударів по нежиті, що зайняла Столицю — стольне місто королівства. Коли ж захисники виродилися в ревний Багряний Хрестовий Похід, вони укріпили обитель, обернувши її мирні бібліотеки, сади й собор на озброєну цитадель."},{t="Бастіон фанатизму",b="Поділений на чотири окремі крила — осквернений цвинтар, простору бібліотеку, збройову палату й великий собор, — Монастир нині вміщує величезний гарнізон під командою Багряного командира Моґрейна та Верховної інквізиторки Вайтмейн. Тутешні хрестоносці бачать у всіх чужинцях — живих чи нежиті, Альянсі чи Орді — носіїв чуми. Поки Відступники прагнуть знищити гарнізон, що загрожує самому їхньому порогу, провід Альянсу дедалі більше вважає жорстокий екстремізм Хрестового Походу небезпечним збоченням Світла."}},faq={{q="Чому тут стоїть Багряний Монастир?",a="Спершу його збудували за часів королівства Лордерон як мирну обитель для навчання: тут зберігали священні писання й навчали паладинів. Після падіння королівства вцілілі хрестоносці захопили й укріпили його, зробивши військовим плацдармом проти нежиті на Галявинах Тірісфалю.",al={"що таке багряний монастир","чому збудували монастир у тіріфалі","призначення монастиря"}},{q="Чому Багряний Хрестовий Похід нападає на членів Альянсу?",a="Фанатизм Походу переріс у цілковиту параною. Хрестоносці вірять, що кожен, хто бував за межами їхніх укріплених поселень, може нести чуму нежиття Погибелі, і не ризикують із чужинцями — хоч би якої вони були раси й вірності.",al={"чому багряні вороги альянсу","чи багряний похід з альянсом","чому хрестоносці нападають на людей"}},{q="Хто очолює сили в Монастирі?",a="Гарнізон тримає Багряний командир Моґрейн, що керує військовими діями із собору, і Верховна інквізиторка Вайтмейн — ревна жриця, славетна своєю відданістю й силою воскрешати.",al={"бос багряного монастиря","лідери монастиря","хто керує багряним походом"}},{q="Які чотири крила має комплекс?",a="Комплекс поділено на чотири окремі частини: Кладовище, де повно неспокійних мерців і катівень; Бібліотеку, що береже історичні архіви й фоліанти; Зброярню, де Похід кує зброю й обладунки; і Собор — духовне серце й осідок командира.",al={"секції монастиря","які крила в багряному монастирі","планування монастиря"}}},fp="17,382,28.595.0,23.524.0,34.281.0,53.264.0,42.212.0,39.286.0"}
P.entries["subzone:scarlet-monastery-armory"] = {n="Зброярня Багряного Монастиря",s="Зброярня — укріплене військове крило Багряного Монастиря, де кують зброю й навчають новобранців для Багряного Хрестового Походу. За замкненою залізною брамою шеренги ревних піхотинців і хрестоносців муштруються під суворою рукою Герода, Багряного Чемпіона.",h="Зброярня — укріплене військове крило Багряного Монастиря, де кують зброю й навчають новобранців для Багряного...",kw={"зброярня","багряний монастир","герод","багряний чемпіон","зала чемпіонів","багряний ключ"},ang={["class:Warrior"]="Зброярня — справжній полігон смертельного бою, де багряні воїни показують убивчі стійки, обеззброєння й знаменитий вихор Герода.",["faction:Horde"]="Поки Багряний Хрестовий Похід стягує військо просто під брамою Андерсіті, сплюндрувати їхні арсенали й убити їхнього чемпіона — життєво важливо для виживання Відступників."},sec={{t="Кузня фанатизму",b="Колись монастир був частиною мирного притулку для духівництва Лордерону, але після Третьої війни його повністю переробили. Тепер Зброярня — головна кузня, склад зброї та бойовий полігон Походу. Від відкритих тренувальних дворів до глибоких збройових зал шеренги багряних піхотинців, чаклунів і хрестоносців невтомно готуються знищувати Погибель і всіх, кого вважають зараженими. Крило відгороджене від Великого Вестибюлю, і потрапити туди можна лише з Багряним Ключем, який знаходять у сусідній Бібліотеці."},{t="Зала Чемпіонів",b="У серці крила лежить Зала Чемпіонів, де вишикувалися височенні статуї легендарних героїв із минулого Походу. Наглядає за залою Герод — брутальний воїн, чия лють і вихори серед хрестоносців уже стали легендою. Герод особисто навчає нове покоління фанатиків, і коли в бою йому доводиться скрутно, його відчайдушні новобранці вриваються до зали, щоб битися й гинути за свого чемпіона."}},faq={{q="Як потрапити до Зброярні?",a="Двері Зброярні у Великому Вестибюлі міцно замкнені. Щоб їх відчинити, треба пройти в крило Бібліотеки й дістати Багряний Ключ зі скрині за арканістом Доаном в Атенеумі — або взяти із собою розбійника, вправного у зламуванні замків.",al={"зброярня замкнена","як відімкнути зброярню","багряний ключ зброярня","відчинити двері зброярні"}},{q="Хто очолює війська в Зброярні?",a="Крилом командує Герод, відомий як Багряний Чемпіон. Він стоїть у Залі Чемпіонів, муштрує вояків і проводить новобранців крізь жорсткі бойові випробування.",al={"бос зброярні","хто керує зброярнею","хто головний у зброярні","герод зброярня"}},{q="Яке призначення цього крила для Багряного Хрестового Походу?",a="Це головний арсенал і військова академія Походу. Тут великі кузні, зброярні для піхотинців і хрестоносців і плаци просто неба, де вояків гартують, перш ніж послати по всьому Тірісфалю й Чумних Землях.",al={"чому існує зброярня","що вони тут роблять","призначення зброярні"}},{q="Чиї статуї вшановано в Залі Чемпіонів?",a="Статуї прославляють найшанованіших мучеників і героїв ордену, зокрема ранніх бійців і чемпіонів, як-от Бареана Вествінда, Ормана зі Стромґарда й Феррена Маркуса.",al={"статуї зброярні","статуї зали чемпіонів","статуї в залі героду"}}},fp="24,276,19.544.0,21.418.0,33.236.0,35.179.0,57.256.0,51.167.0"}
P.entries["subzone:scarlet-monastery-cathedral"] = {n="Собор Багряного Монастиря",s="Собор — духовне й військове серце Багряного Монастиря, де міститься внутрішнє святилище Походу. Колись тиха зала молитви для духівництва Лордерону, тепер він — осідок влади Верховної інквізиторки Вайтмейн і Багряного командира Моґрейна, який стережуть найвідданіші фанатики Походу.",h="Собор — духовне й військове серце Багряного Монастиря, де міститься внутрішнє святилище Походу.",kw={"собор","багряний монастир","вайтмейн","моґрейн","каплиця хрестоносця","сади каплиці"},ang={["faction:Alliance"]="Для Альянсу Похід — трагічне, зіпсоване перекручення Святого Світла й гордої спадщини Лордерону, тож командувачі в Саутшорі посилають героїв покласти край цьому божевіллю.",["faction:Horde"]="Собор, що небезпечно близько до Андерсіті, ховає фанатиків, які присяглися повністю винищити Відступників і всіх союзників з Орди, що стоять поруч із ними."},sec={{t="Святилище фанатизму",b="Колись Собор був мирним осередком просвіти й молитви для духівництва Лордерону, але після Третьої війни поринув у божевілля. Коли королівство впало під натиском Погибелі, уцілілі фанатики обернули комплекс на фортецю непримиренної ненависті. За доглянутою обителлю Садів Каплиці лежить велична Каплиця Хрестоносця, де жерці й воїни збираються, віддані своєму хрестовому походу. Усіх чужинців — незалежно від раси чи фракції — вони вважають носіями чуми нежиття, яких треба очистити клинком і святим вогнем."},{t="Верховна інквізиторка та її командир",b="Сили, що стоять у Соборі, підкоряються безпосередньо Багряному командирові Моґрейну, який тримає залогу в залізній дисципліні. Та справжнє серце фанатизму цієї твердині — Верховна інквізиторка Вайтмейн. Грізна володарка Світла, вона завдяки божественній відданості здатна воскрешати полеглих чемпіонів просто в розпалі бою. Удвох із Моґрейном вони утримують внутрішню каплицю від кожного, хто посміє прорватися крізь браму монастиря, — і доводять, що хватка Походу на півночі Лордерону досі смертоносно міцна."}},faq={{q="Для чого потрібен Собор?",a="Це внутрішній оплот і священний престол Багряного Хрестового Походу в Монастирі. Тут найвищі ватажки ордену правлять служби й керують військовими походами по всіх Галявинах Тірісфалю.",al={"призначення собору","навіщо йти в собор","що це за місце"}},{q="Хто очолює тут Багряний Хрестовий Похід?",a="Гарнізоном командує Багряний командир Моґрейн, а духовна влада належить Верховній інквізиторці Вайтмейн — грізній і ревній жриці.",al={"хто бос тут","боси собору","вайтмейн моґрейн"}},{q="Чому двері до Собору замкнені?",a="Важкі ворота крила Собору замкнені, щоб непрохані гості не вдерлися до внутрішнього святилища. Щоб увійти, потрібен Багряний Ключ, який зберігається в крилі Бібліотеки Монастиря.",al={"собор замкнений","як відчинити собор","де ключ"}},{q="Чому хрестоносці нападають на інших живих людей?",a="Доведений до параноїдального божевілля тим, як Погибель знищила Лордерон, Похід вірить, що всі чужинці — носії чуми нежиття. Він не має справ із зовнішніми фракціями й страчує кожного, хто наближається до його твердинь.",al={"чому нападають на альянс","багряний похід злий","чому хрестоносці ворожі"}}},fp="27,313,15.561.0,37.517.1,31.224.0,35.160.0,40.190.0,52.243.0"}
P.entries["subzone:scarlet-monastery-graveyard"] = {n="Кладовище Багряного Монастиря",s="Кладовище Багряного Монастиря — поховальне крило величного релігійного комплексу на північному сході Галявин Тірісфалю. Колись тихе місце спочинку для духівництва й знаті Лордерону, нині воно моторошно занедбане: його заполонили неупокоєні мерці й зіпсована магія полеглого хрестоносця — мага крові Талноса.",h="Кладовище Багряного Монастиря — поховальне крило величного релігійного комплексу на північному сході Галявин...",kw={"кладовище","багряний монастир","маг крові талнос","гробниця честі","покинута обитель","гробовий мох"},ang={["profession:Herbalism"]="Волога осквернена земля Покинутої Обителі — одне з найнадійніших місць на півночі Лордерону, де можна зібрати Гробовий Мох.",["race:Undead"]="Заклиначі й аптекарі Відступників бачать у Кладовищі похмурий доказ лицемірства Походу: фанатики засуджують Відступників, а в їхньому ж підвалі гниє маг крові з нежиті."},sec={{t="Осквернена святиня",b="До Третьої війни цей обгороджений цвинтар був мирним місцем поховання для духівництва Лордерону. Коли Багряний Хрестовий Похід укріпив монастир проти нежиті, його фанатична пильність так і не змогла очистити власні склепи. Нині Кладовище занедбане, і тут кишить нечисть. Неупокоєні духи, неспокійні мерці й незграбні почвари блукають Палатою Спокути та оповитою туманом Покинутою Обителлю. Замість освяченого спочинку мертві знайшли безкінечні муки під байдужим поглядом Походу."},{t="Скверна зсередини",b="У глибині цвинтаря стоїть Гробниця Честі, де гниє найбільша насмішка з догматів Походу — маг крові Талнос. Колись він мав лиху славу в Поході через жорстокі тортури, якими «очищав» новобранців, а потім заразився чумою нежиття й повстав кістяною почварою, що метає стріли тіні й вогонь. Хрестоносці нагорі проповідують повне винищення чуми нежиття — а самі ховають у своїй освяченій землі гнилого полеглого чаклуна."}},faq={{q="Звідки нежить у твердині Багряного Хрестового Походу?",a="Проводом Походу заволодів фанатизм: хрестоносців посилають назовні вбивати живих чужинців і воювати в Тірісфалі. Тож склепи й поховання монастиря цілком занедбані, і приспані рештки чуми та неспокійні духи померлого духовенства безперешкодно повстають.",al={"чому нежить на кладовищі монастиря","нежить багряного монастиря","чому тут привиди"}},{q="Хто такий маг крові Талнос?",a="Талнос колись був садистом-магом Багряного Хрестового Походу, сумно відомим жорстокими тортурами, якими «очищав» новобранців. Він підхопив чуму нежиття й повстав кістяком-жахіттям, що нині править оскверненими склепами Гробниці Честі.",al={"талнос історія","хто такий маг крові талнос","бос кладовища"}},{q="Де в монастирі розташоване крило Кладовища?",a="Увійшовши до Великого Вестибюля Багряного Монастиря, ви побачите вхід до Кладовища — це крайній лівий портал. На відміну від Зброярні й Собору, ключ для нього не потрібен.",al={"де кладовище монастиря","як знайти крило кладовища","які двері до кладовища"}},{q="Що таке Покинута Обитель?",a="Покинута Обитель — сад і цвинтар просто неба між вхідними склепами й Гробницею Честі. Тут повно надгробків, блукаючих гулів і вологої землі, багатої на Гробовий Мох.",al={"покинута обитель","подвір'я кладовища"}}},fp="27,310,19.531.0,22.463.0,57.314.0,25.233.0,57.190.0,29.185.0"}
P.entries["subzone:scarlet-monastery-library"] = {n="Бібліотека Багряного Монастиря",s="Бібліотека — східне крило Багряного Монастиря в Галявинах Тірісфалю, колись присвячене святій науці й духівництву Лордерону. Тепер її стережуть бойові пси й фанатики, а всередині зберігаються прадавні архіви й рідкісні фоліанти, яких палко прагнуть учені й маги обох фракцій.",h="Бібліотека — східне крило Багряного Монастиря в Галявинах Тірісфалю, колись присвячене святій науці й...",kw={"бібліотека","багряний монастир","атенеум","арканіст доан","псар локсі","компендіум полеглих"},ang={["class:Mage"]="Атенеум — обов'язкове місце паломництва для амбітних магів, які шукають прадавніх обрядів сили й хочуть випробувати себе проти руйнівного чаклунства арканіста Доана.",["faction:Alliance"]="У Бібліотеці зберігаються священні записи про полеглих героїв Лордерону й історії титанів, які Зала Дослідників в Айронфорджі відчайдушно хоче вирвати з рук хрестоносців."},sec={{t="Архіви Лордерону",b="До Третьої війни монастир був осередком знань і просвіти для духівництва Лордерону. У східних галереях зберігалися величезні архіви релігійної думки, історичні хроніки й тайнознавчі трактати. Коли Багряний Хрестовий Похід укріпив монастир проти Погибелі, ці сховища лишилися, а тихі зали обернулися на озброєну твердиню. Нині псарі ганяють слідчих псів подвір'ями, а бойові маги патрулюють між полицями, стережучи від чужинців історичні томи, як-от Компендіум Полеглих, і прадавні дослідження про титанів."},{t="Охоронці Атенеуму",b="Щоб прорватися до Бібліотеки, треба пройти повз Псаря Локсі в Обителі Ловчого: його вишколені пси винюхують лазутчиків, які шукають шляху до внутрішніх покоїв. За Галереєю Скарбів лежить Атенеум, яким опікується арканіст Доан. Цей грізний маг, що володіє нищівним вогнем і захисними чарами, працює на самоті й люто боронить накопичені Походом знання від кожного, хто наважиться вдертися в серце комплексу."}},faq={{q="Де в Багряному Монастирі розташована Бібліотека?",a="Увійшовши до Великого Вестибюля комплексу Багряного Монастиря на Галявинах Тірісфалю, до крила Бібліотеки ви потрапите через крайній правий портал.",al={"вхід у бібліотеку","які двері до бібліотеки","як знайти крило бібліотеки"}},{q="Навіщо шукачів пригод посилають до Бібліотеки?",a="Учені, жерці й маги з Альянсу та Орди шукають цінні тексти, що зберігаються в її стінах. Серед найважливіших — Компендіум Полеглих, знання про Титанів, яких шукають історики Айронфорджа, і давні посібники з магії для молодих чарівників.",al={"навіщо йти в бібліотеку","завдання бібліотеки","що в бібліотеці"}},{q="Хто править крилом Бібліотеки?",a="Внутрішнє святилище Бібліотеки, Атенеум, очолює арканіст Доан — могутній багряний чаклун. Зовнішній двір стереже Псар Локсі зі своїми лютими собаками-слідчими.",al={"бос бібліотеки","хто керує бібліотекою","хто очолює бібліотеку"}},{q="Що за Багряний Ключ тут можна знайти?",a="У скриньці в Атенеумі арканіста Доана лежить Багряний Ключ — без нього не відімкнути важкі залізні двері до Зброярні й Собору монастиря.",al={"ключ доана","багряний ключ","де багряний ключ"}}},fp="25,282,21.587.0,26.457.0,50.155.0,40.258.0,27.198.0,35.175.0"}
P.entries["subzone:scarlet-raven-tavern"] = {n="Таверна «Багряний Крук»",s="Таверна «Багряний Крук» — осередок громадського життя й головний заїзд Даркшира, що дає прихисток біля вогнища посеред мороку Сутінколісся. Під орудою Шинкаря Смітса тут збираються змучені місцеві, перехожі шукачі пригод і нажахані мандрівники, що тікають від жахів за межами міста.",h="Таверна «Багряний Крук» — осередок громадського життя й головний заїзд Даркшира, що дає прихисток біля...",kw={"таверна багряний крук","таверна","шинкар смітс","даркшир","сутінколісся","заїзд"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що перетинають південний кордон, «Багряний Крук» — одне з небагатьох безпечних вогнищ і місць відпочинку між Лісом Елвінн і Перевалом Мертвого Вітру.",["profession:Cooking"]="У меню заїзду є місцеві страви на кшталт Сутінкових Крабових Котлет — їх жадають навіть такі зневірені мандрівники, як Тремтій, коли ховаються на цвинтарі."},sec={{t="Тьмяний прихисток",b="Таверна «Багряний Крук», що стоїть неподалік серця Даркшира, підтримує вогонь у своєму вогнищі, хоч вічні сутінки й душать довколишній ліс. Колись тут вирувало життя: Маршал Гаґґард і Вартові Стормвінда заходили на кухоль після патрулів. Нині справи підупали разом із безпекою міста. Шинкар Смітс наливає похмурим, стривоженим відвідувачам, що тулються тут від холоду й страху. І все ж таверна лишається незамінним перехрестям чуток — саме звідси мандрівники починають шукати відповіді на темні явища, що поглинають край."},{t="Таємниці й крадені кухлі",b="Таверна не лише дає прихисток — тут зберігаються частинки кількох таємниць, що поступово розкриваються. Відлюдний мандрівник Тремтій кілька днів винаймав тут кімнату, ночами гарячково строчив у щоденнику, а потім утік із міста, рятуючись від страхітливих Темних Вершників. Давні міські плітки й збережені записи про гостей під цим дахом ведуть і до давно забутих постатей на кшталт Сталвана Містмантла, тож шинок Смітса — перше місце, куди зазирають допитливі слідчі, коли шукають історію неспокійних мерців Сутінколісся."}},faq={{q="Хто тримає Таверну «Багряний Крук»?",a="Господар таверни — Шинкар Смітс. У корчмі є також корчмар та інша прислуга, що обслуговує мандрівників у Даркширі.",al={"корчмар даркшира","хто власник багряного крука","шинкар сміттс"}},{q="Чому в таверні така похмура атмосфера?",a="Прокляття, що нависло над Сутінколіссям, задушило торгові шляхи й до смерті налякало місцевих. Довкола в лісах нишпорять нежить, дикі воргени й тіньові вершники, тож відвідувачі тут — перелякані городяни й відчайдушні найманці, а не безтурботні мандрівники.",al={"чому в багряному крукові похмуро","атмосфера корчми даркшира"}},{q="Чи зупинявся Тремтій у «Багряному Круку»?",a="Тремтій зупинявся в таверні й гарячково записував щось у щоденник, перш ніж утекти з міста. Чому він так учинив — з'ясовується під час розслідування в Сутінколіссі.",al={"кімната тремтія","тремтій таверна","чи жив тремтій тут"}},{q="Як ця таверна пов'язана з Легендою про Сталвана?",a="Старі відвідувачі й давні міські записи, що збереглися в таверні й довкола неї, містять підказки про Сталвана Містмантла, який колись часто бував у містечку, перш ніж його спіткали трагедія й ганьба.",al={"зв'язок зі сталваном","сталван містмантл корчма даркшира"}}},fp="20,330,12.576.0,24.516.1,34.117.0,41.266.0,38.153.0,63.184.0"}
P.entries["subzone:scarlet-watch-post"] = {n="Багряна Сторожова Застава",s="Багряна Сторожова Застава — відособлена сторожова вежа на скелястих пагорбах північно-східних Галявин Тірісфалю, одразу на північ від Багряного Монастиря. Її тримає пильний гарнізон хрестоносців, і єдине її призначення — берегти вразливий північний фланг монастиря від обхідних нападів.",h="Багряна Сторожова Застава — відособлена сторожова вежа на скелястих пагорбах північно-східних Галявин...",kw={"багряна сторожова застава","багряний хрестовий похід","сторожова вежа","багряний монастир","капітан мелраш","тірісфаль"},ang={["faction:Horde"]="Хрестоносці вважають усіх чужинців — живих чи мертвих — зараженими носіями нежиті, тож ця сторожова застава — суто ворожа земля для будь-яких мандрівників Орди, що зважаться на ці пагорби.",["race:Undead"]="Для Відступників Багряний Хрестовий Похід — смертельна загроза просто на порозі Андерсіті; зачистка таких відособлених веж розриває мережу зв'язку фанатиків і убезпечує північний Тірісфаль."},sec={{t="Охорона північного підступу",b="Багряна Сторожова Застава на скелястих висотах за Багряним Монастирем — важливий бастіон раннього попередження для фанатиків унизу. Поки південна дорога до монастирської брами людна й добре укріплена, скелясті кручі вздовж північного узбережжя Тірісфалю дають спокусливий обхідний шлях для диверсантів. Щоб закрити цю сліпу пляму, Багряний Хрестовий Похід тримає цю укріплену кам'яну вежу — одну з кількох застав хрестоносців, розкиданих по Галявинах Тірісфалю. Під суворим командуванням Капітана Мелраша змішаний загін неофітів, передових бійців і побожних братів-ченців невпинно пильнує кручі, щоб ні Погибель, ні Відступники не заскочили орден зі спини."}},faq={{q="Для чого потрібна Багряна Сторожова Застава?",a="Застава захищає Багряний Монастир від обхідного удару. Головний вхід монастиря дивиться на південь, на дороги Тірісфалю, а тил спускається до північних нетрів і вразливий для злагоджених нападів. Застава дає вартовим змогу помітити й перехопити будь-яких зайд, що спробують обійти монастир з півночі.",al={"чому тут багряна сторожова застава","призначення багряної сторожової застави","роль хрестоносців"}},{q="Хто командує Багряною Сторожовою Заставою?",a="Гарнізоном у вежі командує Капітан Мелраш. У його оборонному загоні — особисті охоронці, авангардні бійці, новачки-неофіти й брати-чаклуни.",al={"лідер багряної сторожової застави","хто командує багряною заставою","капітан мелраш"}},{q="Чи пов'язана Багряна Сторожова Застава з іншими вежами Тірісфалю?",a="Так. Це одна з чотирьох окремих застав хрестоносців, що оперізують північ і захід Галявин Тірісфалю. Ці кам'яні вежі утворюють оборонний периметр, щоб стежити за Погибеллю й стримувати поширення Відступників з Андерсіті.",al={"вежі тіріфалю","застави хрестоносців тіріфаль","інші багряні вежі"}}},fp="18,297,30.721.0,46.327.0,36.192.0,66.241.0"}
P.entries["subzone:scholomance"] = {n="Сколомансія",s="Сколомансія, схована глибоко в криптах під Каер Дарроу, — найголовніша академія темних мистецтв і некромантії Погибелі. Тут смертні й нежить разом вивчають чуму нежиття та ліплення плоті під садистським наставництвом Темного Майстра Ґандлінґа й пильним оком ліча Раса Фроствіспера.",h="Сколомансія, схована глибоко в криптах під Каер Дарроу, — найголовніша академія темних мистецтв і некромантії...",kw={"сколомансія","каер дарроу","ґандлінґ","рас фроствіспер","барови","некромантія","кел'тузад"},ang={["class:Mage"]="Викривлені уроки Сколомансії — цілковите збочення магічної науки: тут дослідження теорії магії поступилися місцем гнилі, тіні й нечестивому оскверненню.",["race:Undead"]="Заклиначі-Відступники знають Сколомансію надто добре й дивляться на неї з холодною відразою: чимало найпідліших методів поневолення й біологічної війни Погибелі відточили саме в цих класах."},sec={{t="Згубна угода",b="До Третьої війни Каер Дарроу був гордим осідком дому Баровів — багатого аристократичного роду, якому належали розлогі землі по всьому Лордерону, зокрема Брілл, Таррен Мілл і Саутшор. Боячись утратити статки й страшачись смерті, Барови піддалися спокусливим обіцянкам Кел'Тузада про вічне життя. Вони віддали Культу Проклятих свою фортецю й родові катакомби, а культ віддячив вельможам тим, що перебив їх і перетворив розлогі крипти на таємний вишкільний табір некромантів."},{t="Школа Некромантії",b="Під моторошними наземними руїнами Каер Дарроу вирує справжня кузня Погибелі. У цих вогких залах випробовували на живих слугах перші штами чуми й зшивали докупи перших потворних гидот. Нині сюди злітаються смертні послушники, щоб удосконалити владу над темною магією під наглядом директора — Темного Майстра Ґандлінґа — та крижаного вартового Раса Фроствіспера, а неупокоєні рештки роду Баровів навіки мучаться в цих стінах."}},faq={{q="Що таке Сколомансія?",a="Сколомансія — таємна академія некромантії, якою керують Культ Проклятих і Погибель. Вона розташована під острівною фортецею Каер Дарроу й навчає смертних некромантів, дослідників чуми й майстрів плоті.",al={"що це за місце","лор сколомансії","поясніть сколомансію"}},{q="Кому належать Каер Дарроу й склепи?",a="Спершу фортеця належала Дому Баровів — одній із найзаможніших шляхетних родин Лордерона. Прагнучи безсмертя, вони віддали своє родове гніздо Кел'Тузаду, але їх убили й підняли як нежить-невільників у їхніх же власних залах.",al={"кому це належало","дім баровів","родина баровів"}},{q="Хто тепер керує академією?",a="Темний Майстер Ґандлінґ — підступний смертний директор школи, що наглядає за навчанням і муками. Крім того, від імені Погибелі це місце пильно стереже ліч Рас Фроствіспер.",al={"хто бос","хто керує сколомансією","директор"}},{q="Які жахіття тут створили?",a="Сколомансія була першою кузнею Культу Проклятих. Сектанти випробовували на слугах родини Баровів ранні різновиди чуми нежиття й зшивали в її лабораторіях перших гидот Погибелі.",al={"що тут створили","експерименти сколомансії","поганьби"}}},fp="11,304,14.507.0,24.467.1,20.241.0,36.242.0,25.195.0,33.243.0"}
P.entries["subzone:scholomance-classic"] = {n="Сколомансія (класична)",s="Сколомансія — підземна академія некромантії, схована в криптах під Каер Дарроу в Західних Чумних Землях. Її заснували Кел'Тузад і Культ Проклятих, і тепер це найголовніший вишкільний центр Погибелі для смертних заклиначів, які прагнуть опанувати смерть.",h="Сколомансія — підземна академія некромантії, схована в криптах під Каер Дарроу в Західних Чумних Землях.",kw={"сколомансія","каер дарроу","кел'тузад","культ проклятих","рас фроствіспер","ґандлінґ","рейвеніан"},ang={["class:Mage"]="Сколомансія — потворне перекручення вченої традиції Даларана: ось що буває, коли знання Кірін-Тору цілком віддають некромантії й тліну.",["class:Paladin"]="Для лицарів Срібної Длані очистити осквернені зали під Каер Дарроу — нагальний обов'язок: це удар просто по джерелу, з якого Погибель черпає смертних ватажків."},sec={{t="Школа в гробницях",b="Ще до того, як Третя війна спустошила Лордерон, архімаг-ренегат Кел'Тузад шукав прибічників для свого Культу Проклятих. Щедрих покровителів він знайшов у багатому роді Баровів, володарях Каер Дарроу, які віддали свої землі й крипти в обмін на обіцяне безсмертя. Натомість культ вирізав їх і підняв як жахливу нежить. Під зруйнованою фортецею культисти перебудували давні катакомби, що збереглися ще з часів Аратору, на академію темних мистецтв. Тут, подалі від пильних очей, смертні послушники вчаться творити чуму, зв'язувати душі й ліпити плоть, відточуючи ту мерзенну магію, що розтрощила Лордерон."},{t="Ліч і директор",b="Хоча Кел'Тузад тепер керує справами Погибелі з висоти, школа працює на повну силу. Безсмертний ліч Рас Фроствіспер стереже школу в ім'я Погибелі, а смертний некромант Темний Майстер Ґандлінґ є її директором і наставляє честолюбних чаклунів у жахливих дослідах. Учнів, які виявляють слабкість, скидають у катакомби на поживу Рейвеніану — ненажерному мертвякові, що чатує в нижніх склепах."}},faq={{q="Що таке Сколомансія?",a="Сколомансія — таємна академія некромантії під орудою Культу Проклятих. Розташована в глибоких склепах під острівною фортецею Каер Дарроу, вона навчає смертних чаклунів темних мистецтв Погибелі.",al={"що це за місце","лор сколомансії","поясніть сколомансію"}},{q="Хто тепер править Сколомансією?",a="Від імені Погибелі за фортецею наглядає ліч Рас Фроствіспер, а справами смертних і навчанням керує Темний Майстер Ґандлінґ — безжальний директор школи.",al={"хто керує сколомансією","хто головний","бос сколомансії"}},{q="Як Погибель заволоділа Каер Дарроу?",a="Після Другої війни фортецею володіла шляхетна родина Баровів. Спокушені обіцянками Кел'Тузада про вічне життя, вони переписали своє родове гніздо й склепи на Культ Проклятих. Культ «дотримав» угоди, вирізавши Баровів і піднявши їх як нежить.",al={"історія баровів","хто володів кер дарроу","як культ захопив сколомансію"}},{q="Чому школа замкнена?",a="Величезні залізні ворота запечатали, щоб захистити дослідження академії й закличників від зайд. Щоб відчинити двері, потрібна Відмичка, яку виготовляють за складним обрядом, що охоплює всі Чумні Землі.",al={"двері сколомансії замкнені","як зайти в сколомансію","скелетний ключ сколомансії"}}},fp="21,270,21.603.0,19.465.0,20.211.0,26.179.0,40.271.0,25.208.0"}
P.entries["subzone:screaming-gully"] = {n="Волаючий Яр",s="Волаючий Яр — перша розлога підземна печера одразу за входом до Печер Стогонів. Залита протиприродним сяйвом грибів і мілкою водою, вона править за зовнішній оплот спотворених Друїдів Ікла та їхніх мутованих звірів.",h="Волаючий Яр — перша розлога підземна печера одразу за входом до Печер Стогонів.",kw={"волаючий яр","печери стогонів","леді анакондра","друїди ікла","девіантні раптори","креш"},ang={["class:Druid"]="Для друїдів Кола Кенарія Волаючий Яр — болюче видовище: тут їхні занепалі побратими, що зійшли зі шляху кігтя й неба й віддалися зміїній порчі."},sec={{t="Поріг Жахіття",b="Ступивши за поріг Печер Стогонів, мандрівник одразу потрапляє у Волаючий Яр — відлунну прірву, де вітер стогне в підземних розколинах. Тут, далеко від посушливих Пусток нагорі, яр заріс вологими хащами, оповитий задушливим туманом і повний лютих звірів, спотворених Смарагдовим Жахіттям. Над залою пильнує Володарка іклів Леді Анакондра в оточенні послушників Друїдів Ікла та лютих девіантних рапторів, а мілкими протоками внизу патрулюють прадавні кусючі черепахи на кшталт Креша."}},faq={{q="Де розташований Волаючий Яр?",a="Волаючий Яр — перша велика зала, до якої ви потрапляєте, щойно пройдете крізь портал до Печер Стогонів під північними Пустками.",al={"розташування волаючого яру","де волаючий яр","як знайти волаючий яр"}},{q="Чому він зветься Волаючим Яром?",a="Печери Стогонів дістали свою назву через виття й стогін підземної пари й вітрів, що виходять крізь скельні розколини, а цей широкий вхідний провал приймає на себе найгучнішу луну цих криків.",al={"чому волаючий яр","походження назви волаючого яру"}},{q="Хто править Волаючим Яром?",a="Залою опікується Леді Анакондра — одна з головних Володарок Ікла, що разом із Наралексом піддалася скверні Смарагдового Жахіття.",al={"бос волаючого яру","хто у волаючому ярі","лідер волаючого яру"}},{q="Хто блукає цією залою?",a="У яру живуть девіантні раптори, зіпсовані Друїди Ікла й блукаючі водяні істоти — зокрема давня черепаха Креш, що бродить затопленим дном.",al={"моби волаючого яру","вороги волаючого яру"}}},fp="15,265,26.511.0,37.165.0,37.209.0,35.145.0,33.162.0"}
P.entries["subzone:scuttle-coast"] = {n="Дріботливе Узбережжя",s="Дріботливе Узбережжя — побитий хвилями східний берег Дуротару між Гострим Пагорбом і Фортецею Тіраґард. Скелястий пляж усіяний затонулими уламками флоту Кул Тірасу під проводом Адмірала Дейліна Праудмура, тож це жваве місце для збирачів Орди й невідступне нагадування про недавню морську війну.",h="Дріботливе Узбережжя — побитий хвилями східний берег Дуротару між Гострим Пагорбом і Фортецею Тіраґард.",kw={"дріботливе узбережжя","уламки","кораблі","кул тірас","праудмур","краби","макрури","дуротар"},ang={["faction:Horde"]="Розбиті корпуси, якими всіяний цей пляж, стоять суворими пам'ятниками обороні Дуротару від загарбницького флоту Дейліна Праудмура.",["profession:Engineering"]="У затоплених трюмах Альянсу вздовж берега лишилися покинуті гномські пристрої, металобрухт і хитромудрі механізми, що так і просяться на розбирання й вивчення."},sec={{t="Уламки флоту",b="Дріботливе Узбережжя, що тягнеться вздовж східного краю Дуротару до Великого Моря, набуло свого похмурого вигляду під час вторгнення Великого Адмірала Дейліна Праудмура. Коли флот Кул Тірасу напав на молоду державу Дуротар, люті бої з Ордою загнали чимало людських кораблів на зубчасті мілини й розтрощили їх на тріски. Нині берег завалений порослими мушлями колодами, поламаним такелажем і врятованими бочками з вантажем. Для сусідніх таборів Гострого Пагорба узбережжя — водночас і невідступна загроза безпеці, і цінне джерело віднайдених припасів та покинутих механізмів Альянсу."},{t="Збирачі та припливи",b="Назва Дріботливого Узбережжя нагадує не лише про затоплені кораблі, навмисне пущені на дно чи посаджені на мілину під час боїв, а й про рої крабів та макрур, які порпаються в гниючому мотлосі. Хоч прибережна звірина й небезпечні припливи відлякують випадкових мандрівників, збирачі Орди час від часу прочісують уламки, щоб дістати цінне спорядження, зокрема гномські технічні деталі, покинуті в трюмах затонулих кораблів."}},faq={{q="Звідки взялися всі ці корабельні уламки?",a="Розтрощені кораблі належали флоту Кул Тірасу під командуванням Великого Адмірала Даліна Праудмура. Вони розбилися об скелясті мілини Дуротару під час невдалого військового походу адмірала проти щойно заснованої Орди.",al={"чому тут кораблі","чиї розбиті кораблі","затонулі кораблі дуротару"}},{q="Чому воно зветься Дріботливим Узбережжям?",a="Назва має подвійне значення. Вона натякає і на бойові кораблі, що пішли на дно вздовж узбережжя під час морських боїв, і на численних макрур та крабів, що дрібно снують скелястими пісками.",al={"чому дріботливе узбережжя","походження назви дріботливого узбережжя"}},{q="Що шукає Орда на узбережжі?",a="Розвідники й збирачі Орди обшукують розбиті трюми, шукаючи придатні інструменти, припаси й кинуті гномські механізми, які лишили сили Альянсу.",al={"що орки рятують","орда рятує дріботливе узбережжя"}},{q="Чи безпечно подорожувати Дріботливим Узбережжям?",a="Ні. Окрім підступних хвиль і гострих скель, у прибої нишпорять ворожі прибережні істоти на кшталт макрур, а трохи на південь, у Фортеці Тіраґард, окопалися озброєні вцілілі з Кул Тірасу.",al={"небезпеки дріботливого узбережжя","чи небезпечне дріботливе узбережжя"}}},fp="13,315,21.634.0,20.450.0,41.229.0,35.198.0,46.153.0,36.187.0"}
P.entries["subzone:sea-of-cinders"] = {n="Море Жарин",s="Море Жарин — простір випаленої, обвітреної землі в південній частині Палючої Ущелини, просто на північ від Гори Блекрок. Стихійний жар і безупинні пориви вітру сплюндрували цю рівнину: з неї раз у раз вириваються попіл і жарини, тож у цьому задушливому мертвому краї мало що здатне вижити.",h="Море Жарин — простір випаленої, обвітреної землі в південній частині Палючої Ущелини, просто на північ від...",kw={"море жарин","палюча ущелина","гора блекрок","рагнарос","попіл","жарини"},ang={["profession:Mining"]="Нестійкий, потрісканий від жару камінь біля підніжжя Гори Блекрок часто відкриває багаті поклади руди й жили темного заліза — для тих, кому стане сміливості шукати їх серед летючого попелу.",["race:Dwarf"]="Для дворфів Бронзбірда й Вайлдгаммерів мандрівка цими палаючими пустелями — похмуре нагадування про безумство Тауріссана й темні сили, що розтрощили Гори Редріджу."},sec={{t="Пустеля жарин",b="Море Жарин, що простяглося між скелястими урвищами Палючої Ущелини й грізною громадою Гори Блекрок, дістало свою назву від задушливого серпанку з пилу й палючого піску, який безупинно мете його рівнинами. Коли століття тому Володаря вогню Рагнароса викликали у смертний світ, страшний струс розколов Гори Редріджу й обернув довколишній край на суху купу шлаку. Море Жарин — один із найбезплідніших слідів того катаклізму: непридатна для життя рівнина, де сама земля не хоче охолонути."},{t="Небезпека під схилами",b="Море Жарин межує з північним підступом до Гори Блекрок, тож мандрівникам і збирачам часто нема іншого вибору, як перетинати ці пекучі рівнини. Вітри тут здіймають густі хмари сліпучого попелу, які ховають раптові розколини, стихійних жахіть і бродячих хижаків, звиклих до палючої спеки. Ворожа природа, а ще дворфи Темного Заліза, що вважають цей край своїм, — тож будь-який перехід через жарини вимагає пильності й поспіху."}},faq={{q="Що таке Море Жарин?",a="Це безплідна, вкрита попелом рівнина на півдні Палючої Ущелини, під самим північним схилом Гори Блекрок. Її вкриває тліюча земля й летючі іскри.",al={"що таке море жарин","лор моря жарин","де море жарин"}},{q="Чому земля тут безперестанку горить?",a="Століття тому цей край геть спустошило, коли чаклун-тан Тауріссан під час Війни Трьох Молотів викликав Володаря вогню Рагнароса. Нищівне виверження розпекло землю й розтрощило гори, і рівнини досі тліють.",al={"чому все горить","чому тут жарини","чому земля димить"}},{q="Чи живе тут хтось?",a="У самому Морі Жарин немає жодного організованого поселення. Задушлива спека, погане повітря й брак води унеможливлюють постійне життя, тож тут лише блукають звірі, вогняні елементалі й патрулі, пов'язані з Горою Блекрок.",al={"хто тут живе","мешканці моря жарин","поселення"}},{q="Чим небезпечні мандри цими краями?",a="Окрім ворожих звірів і дворфів Темного Заліза, що чатують біля гори, смертельне саме довкілля. Повітря густе від сліпучої сажі й палючого попелу, а пласку землю всюди прорізають глибокі гарячі розколини.",al={"чи безпечно","небезпеки моря жарин"}}},fp="14,313,21.560.0,24.462.0,27.182.0,37.270.0,22.272.0,44.212.0"}
P.entries["subzone:sen-jin-village"] = {n="Село Сен'джин",s="Село Сен'джин — прибережне поселення на південних берегах Дуротару, притулок для тролів Темного Списа. Засноване Вождем Вол'джином після того, як його народ вигнали з прадавнього дому на Островах Відлуння, селище вшановує його полеглого батька, знахаря Сен'джина. Нині це крихкий прихисток, зосереджений на виживанні, травництві й поверненні вкраденого.",h="Село Сен'джин — прибережне поселення на південних берегах Дуротару, притулок для тролів Темного Списа.",kw={"село сен'джин","тролі","темний спис","вол'джин","притулок","травництво","острови відлуння","дуротар"},ang={["profession:Herbalism"]="Село — важливий початковий осередок природної медицини, оточений прибережним мирноцвітом, срібнолистом і земнокоренем, якими місцеві знахарі лікують отруту й прокляття.",["race:Troll"]="Для тролів Темного Списа, що виходять із Долини Випробувань, цей притулок — живе серце їхнього вигнаного народу, що береже пам'ять про втраченого вождя й незгасний біль зради Залазана."},sec={{t="Берег біженців",b="Коли темний знахар Залазан зрадив Темний Спис і захопив владу над Островами Відлуння, Вождь Вол'джин був змушений перевести вцілілих через протоку на материк Дуротару. Там, під прибережними скелями, з видом на воду, вони поставили грубі хатини й заснували Село Сен'джин. Поселення носить ім'я батька Вол'джина — шанованого старійшини, що пожертвував собою під час Третьої війни, рятуючи свій народ від прибережних мурлоків. Попри тісний союз з Ордою Тралла, тутешні тролі живуть у тіні вигнання, щодня дивлячись через мілини на втрачений дім."},{t="Очі на острови",b="Щоденне життя Села Сен'джин обертається довкола підготовки й оборони. Між набігами місцевих кентаврів, лютими морськими тварюками й насланнями Залазана, що сягають через море, селяни чимало покладаються на трав'яні ліки та варіння міцних алхімічних настоянок. Поки Вол'джин керує ширшою обороною племені зі столиці Орди, місцеві шамани, мисливці та розвідники збираються тут, щоб залучати нових мандрівників, які виходять із Долини Випробувань. Їхня мета ясна: зібрати ресурси, захистити південний фланг Дуротару й підготувати неминуче падіння зрадника Залазана."}},faq={{q="Чому Темний Спис збудував Село Сен'джин саме тут?",a="Тролі Темного Списа втекли через протоку на узбережжя Дуротару після того, як знахар Залазан збожеволів і захопив їхній дім на Островах Відлуння. Село Сен'джин заснував Вол'джин як тимчасовий прихисток і плацдарм просто навпроти їхньої відібраної землі.",al={"чому село сен'джин тут","чому тролі в дуротарі","чому тролі покинули острови відлуння"}},{q="Хто такий Сен'джин?",a="Сен'джин — шанований знахар і вождь племені Темного Списа, батько Вол'джина. Під час Третьої війни він передбачив прихід Тралла й віддав життя, рятуючи своє плем'я й молоду Орду від фанатичних морських мурлоків у Південних Морях.",al={"хто був сен'джин","на честь кого сен'джин","сен'джин історія"}},{q="Чому тут так багато травників і алхіміків?",a="Місцеві знахарі й цілителі значною мірою покладаються на прибережні рослини Дуротару й отруту скорпоків, щоб готувати обереги, протиотрути й обряди. Ці трав'яні вари підтримують поранених і захищають від темних заклять, що долітають з Островів Відлуння.",al={"наставники села сен'джин","професії села сен'джин","чому тут алхімія"}},{q="Чи можна дістатися з Села Сен'джин до Островів Відлуння?",a="Острови Відлуння лежать просто через воду на схід від села. Шукачі пригод часто перепливають чи переходять убрід мілку протоку, щоб завдати удару вуду-сектантам Залазана, повернути вкрадені артефакти чи зібрати ресурси для захисників села.",al={"як дістатися до островів відлуння","острови біля сен'джин","допливти до островів відлуння"}}},fp="15,393,15.634.0,17.569.0,49.282.0,16.271.0,53.258.0,50.247.0"}
P.entries["subzone:sentinel-hill"] = {n="Сентінел Гілл",s="Сентінел Гілл — головна твердиня Альянсу у Вестфолі й командний центр Народного ополчення. Довкола — зарослі поля, гноли-мародери й ворожі розбійники, тож цей укріплений пагорб — єдиний надійний оплот для законослухняних мешканців краю.",h="Сентінел Гілл — головна твердиня Альянсу у Вестфолі й командний центр Народного ополчення.",kw={"сентінел гілл","вестфол","народне ополчення","ґраян стаутмантл","вежа вартових","альянс"},ang={["faction:Alliance"]="Сентінел Гілл — ваша єдина укріплена застава й осередок постачання у Вестфолі, опора Альянсу проти розбійників і грабіжників.",["race:Human"]="Те, що фермерам Вестфолу довелося самим збирати тут ополчення, показує, як глибоко загрузло королівство в кризі, поки трон стоїть порожній."},sec={{t="Твердиня серед пилу",b="Сентінел Гілл височіє на узвишші в центрі Вестфолу й править за життєво важливий прихисток на беззаконних землях. Тут є таверна, схожа на казарму, гніздо грифонів, звідки летять до Стормвінда й далі, кузня та лісопилка, а над усім панує велична Вежа Вартових. Довколишні землі дісталися розбійникам і хижим звірам, але табір утримує хиткий периметр, де мандрівники, знесилені фермери й новобранці можуть перевести подих під пильним оком досвідчених захисників."},{t="Серце ополчення",b="Королівська армія застрягла в Стормвінді й не може виділити вояків на захист віддалених земель, тож Ґраян Стаутмантл заснував Народне ополчення просто на цьому пагорбі. Звідси добровольці висилають розвідників, завдають ударів по гнолах Річколапів і розслідують організований розбій, що шматує покинуті хутори Вестфолу. Сентінел Гілл — не розкішна фортеця й не затишний сховок, а робочий табір на передовій, сповнений рішучості повернути колишню житницю королівства."}},faq={{q="Чому Стормвінд не прислав воїнів боронити Сентінел Гілл?",a="Король Варіан Рінн зник, сили королівства розпорошені, тож регентство Стормвінда здебільшого покинуло західні провінції напризволяще. Місцеві мешканці й ветерани мусили самі створити Народне ополчення, щоб утримати Сентінел Гілл і захистити те, що лишилося від Вестфолу.",al={"чому немає стормвіндської варти","де армія стормвінда","чому тут ополчення"}},{q="Хто очолює Сентінел Гілл?",a="Ґраян Стаутмантл командує Народним ополченням біля підніжжя Вежі Вартових. Він організовує місцеву оборону, збирає відомості про довколишні загрози й спрямовує заїжджих шукачів пригод проти гнолів і грабіжників, що підступають до поселення.",al={"хто керує сентінел гіллом","командир сентінел гілла","ґріан стаутмантл"}},{q="Що зараз загрожує пагорбу?",a="На табір постійно тиснуть агресивні гноли Річколапів із західних рівнин, а ще підступний злагоджений саботаж Братства Дефіас, що ховається на покинутих фермах.",al={"що нападає на сентінел гілл","вороги сентінел гілла","хто нападає"}},{q="Які послуги є тут для мандрівників?",a="Сентінел Гілл має все, що потрібно на прикордонні: розпорядника грифонів із польотами до Стормвінда й інших застав Альянсу, корчмаря, поштову скриньку, крамарів і ремонт біля місцевої кузні.",al={"послуги сентінел гілла","політ сентінел гілл","чи є тут корчма"}}},fp="13,276,21.516.0,20.514.0,59.292.0,34.253.0,40.211.0,47.234.0"}
P.entries["subzone:sentinel-tower"] = {n="Вежа Вартових",s="Вежа Вартових вінчає вершину Сентінел Гілла — це головний оглядовий пункт і штаб захисників Вестфолу. Звідси Ґраян Стаутмантл і Народне ополчення відчайдушно обороняються від бандитів, гнолів і дедалі темнішої тіні Братства Дефіас.",h="Вежа Вартових вінчає вершину Сентінел Гілла — це головний оглядовий пункт і штаб захисників Вестфолу.",kw={"вежа вартових","сентінел гілл","ґраян стаутмантл","народне ополчення","вестфол"},ang={["faction:Alliance"]="Вежа Вартових — утілення стійкості простих підданих Альянсу, що б'ються за рідну землю, поки знатні лорди в Стормвінді заплющують на це очі.",["race:Human"]="Для людей королівства ця вежа — болісне нагадування: хліборобська житниця Стормвінда ледве тримається проти заколоту, що виріс на власному ґрунті."},sec={{t="Варта над Диким Заходом",b="Вежа Вартових, зведена на гребені Сентінел Гілла, — військове серце неспокійного Вестфолу. Офіційна армія Стормвінда здебільшого відсутня й допомоги не дає, тож місцеві добровольці й ветерани об'єдналися, щоб звести центральний редут. Із кам'яної вежі дозорці бачать усю курну рівнину — від покинутих гарбузових грядок до туманних берегів — і вчасно попереджають, коли на дорогах з'являються розбійники чи загони гнолів."},{t="Штаб ополчення",b="Вежа — командний пункт Ґраяна Стаутмантла й осередок місцевого проводу. Довкола — нашвидкуруч зведені укріплення, поранені біженці й утомлені вояки, тож вона водночас править і за штаб, і за притулок для хуторян, вигнаних зі своїх земель. Тут по крихтах збирають відомості про Братство Дефіас і гуртують добровольців для злагоджених ударів по синдикату, який задушив цей край."}},faq={{q="Хто керує у Вежі Вартових?",a="З вежі діями керує Ґраян Стаутмантл. Як очільник Народного ополчення, він організовує захист фермерів Вестфолу, що лишилися без домівок, і набирає охочих шукачів пригод.",al={"лідер вежі вартових","хто керує вежею вартових","хто керує вежею"}},{q="Чому вежа така важлива для Вестфолу?",a="Це єдиний укріплений гарнізон і спостережний пост, що лишився на центральних рівнинах. Стормвінд майже не захищає Вестфол, тож вежа — останній організований оплот порядку й безпеки для біженців у краї.",al={"чому вежа вартових важлива","призначення вежі вартових"}},{q="Хто живе у вежі й довкола неї?",a="Тут ви побачите офіцерів ополчення, вартових на чатах, інтендантів і родини фермерів, що покинули свої зруйновані землі й шукають прихистку під її міцними кам'яними мурами.",al={"хто у вежі вартових","мешканці вежі вартових"}},{q="За якими загрозами стежать із вежі?",a="Вартові стежать за пересуваннями гнолів Річколапів, за мурлоками, що заповзають углиб суходолу з узбережжя, а понад усе — за грабіжниками й розбійниками з Братства Дефіас.",al={"вороги вежі вартових","від чого стереже вежа"}}},fp="14,299,24.456.0,27.450.0,35.196.0,42.229.0,34.188.0,40.185.0"}
P.entries["subzone:sentry-point"] = {n="Дозорний Мис",s="Дозорний Мис — людська сторожова вежа на материковому краю Багна Пилоброду, що стереже насипний міст до Острова Терамор. Її утримують сили Терамору, стежачи за всіма, хто в'їжджає до острівної цитаделі Леді Джайни Праудмур і виїжджає з неї.",h="Дозорний Мис — людська сторожова вежа на материковому краю Багна Пилоброду, що стереже насипний міст до...",kw={"дозорний мис","острів терамор","багно пилоброду","сторожова вежа","міст","терамор"},ang={["faction:Alliance"]="Для мандрівників, що прибувають із небезпечних трясовин Багна Пилоброду, Дозорний Мис — гостинний поріг безпеки Острова Терамор.",["faction:Horde"]="Вежа — суворе нагадування про військову присутність Терамору на материку Калімдору; її пильно охороняють від будь-яких розвідників Орди."},sec={{t="Брама Терамору",b="Дозорний Мис, що стоїть на західному кінці довгого мосту між Островом Терамор і підступними болотами Багна Пилоброду, — перша лінія оборони твердині на материку. Кам'яна розвідувальна вежа пильнує болотяну дорогу, щоб ні ворожі болотяні звірі, ні мандрівні таурени Ґрімтотем, ні рейдери Орди не могли непомітно наблизитися до острівного міста."}},faq={{q="Для чого потрібен Дозорний Мис?",a="Це пост раннього попередження й прикордонний пункт Острова Терамор. Вартові тут стежать за рухом на болотяній дорозі й попереджають міську варту про загрози, що наближаються.",al={"призначення дозорного мису","що це за вежа","чому тут дозорний мис"}},{q="Хто тримає цю заставу?",a="На заставі несе службу й утримує її Варта Терамору під командуванням Леді Джайни Праудмур та її офіцерів.",al={"хто володіє дозорним мисом","чи дозорний мис альянсу","сторожова вежа терамору"}},{q="Чи безпечний Дозорний Мис для мандрівників з Орди?",a="Ні. Хоча Леді Джайна Праудмур прагне миру з Ордою, вартові на цій заставі охороняють землі Альянсу й одразу нападуть на членів Орди, що вдеруться сюди.",al={"чи може орда на дозорний мис","чи дружній дозорний мис до орди"}}},fp="12,269,22.378.0,30.193.0,26.140.0,41.190.0"}
P.entries["subzone:sepulcher"] = {n="Гробниця",s="Гробниця — головне поселення й твердиня Відступників у Срібноліссі. Колись звичайне лордеронське кладовище й склеп над західним узбережжям, тепер це укріплений прихисток Орди від загроз довкола.",h="Гробниця — головне поселення й твердиня Відступників у Срібноліссі.",kw={"гробниця","відступники","орда","срібнолісся","кладовище"},ang={["faction:Horde"]="Для кожного мандрівника Орди, що прямує на південь із Галявин Тірісфалю, Гробниця — єдиний надійний прихисток на багато миль довкола, де можна полагодити спорядження й вирушити в політ.",["race:Undead"]="Гробниця — плацдарм боротьби Відступників за приборкання Срібнолісся: звідси керують діями проти вірних Погибелі недобитків, решток Кірін-Тору й диких воргенів."},sec={{t="Святилище в тумані",b="Гробниця, що стоїть на пагорбах над узбережжям Лордерона, спершу була тихим кладовищем і склепом при західній дорозі. Після Третьої війни щойно звільнені Відступники пристосували давнє кам'яне склепіння та його землі під важливу заставу. Оточена ворожими силами з усіх боків — дикими воргенами на півдні, недобитками Погибелі на сході й чарівниками Кірін-Тору, що стежать з Амбермілла, — Гробниця дає мандрівникам Срібнолісся рідкісний прихисток, припаси й командування."}},faq={{q="Чим була Гробниця до приходу Відступників?",a="До Третьої війни й падіння королівства Лордерон це був звичайний придорожній цвинтар і кам'яний склеп, де місцеві селяни ховали своїх померлих.",al={"історія гробниці","чим була гробниця","хто збудував гробницю"}},{q="Чому Гробниця така важлива для Відступників?",a="Це єдиний укріплений осередок Відступників у Срібноліссі. З цього центрального місця розвідники й командири Відступників можуть стежити за магами Даларану, що підступають, за рештками Погибелі й за звірячою загрозою воргенів, що поширюється біля Фортеці Шадовфенг.",al={"чому гробниця важлива","відступники в сілверпайні","роль гробниці"}},{q="Чи раді тут мандрівникам з інших рас Орди?",a="Так. Хоча базою керують і живуть у ній лише Відступники — вартові смерті, крамарі й аптекарі, — це офіційний прихисток Орди, де можуть відпочити й поторгувати орки, тролі й таурени, що проходять краєм.",al={"чи можуть орки в гробницю","чи гробниця дружня до орди","орда в гробниці"}},{q="Що загрожує Гробниці?",a="Поселення затиснуте ворожими силами: на сході блукає Погибель, на південному сході Кірін-Тор тримає Амбермілл, а на півдні лісами нишпорять люті воргени.",al={"загрози гробниці","вороги сілверпайну","що нападає на гробницю"}}},fp="9,261,20.549.0,52.153.0,46.254.0,58.231.0,36.178.0"}
P.entries["subzone:serpent-s-coil"] = {n="Кільця Змія",s="Кільця Змія — звивиста мережа печер і спалених таборів у східних хребтах Спустошених Земель. Ця місцина, всіяна обгорілими орчими спорудами, що лишилися з давніх воєн, править за відлюдний прихисток для темних культистів і самотніх дослідників.",h="Кільця Змія — звивиста мережа печер і спалених таборів у східних хребтах Спустошених Земель.",kw={"кільця змія","спустошені землі","культисти","аллістарж","присяжні тіні","печери"},ang={["class:Warlock"]="Присяжні Тіні в Кільцях Змія правлять обряди підкорення й переховують могутні артефакти, тож печера — похмуре відображення безрозсудного вивчення демонів.",["race:Gnome"]="Самотній гном-дослідник глибоко в печері, що кишить культистами, — яскравий приклад того, на які безстрашні чи безрозсудні кроки готовий гномський розум, аби розгадати заборонену магію."},sec={{t="Лабіринт попелу й каменю",b="Звивиста стежка й печери Кілець Змія, вирубані в зубчастих східних скелях Спустошених Земель, в'ються повз зруйновані орчі хижі, що пам'ятають Першу й Другу війни. У тунелях ховаються не прості звірі, а гуртки культистів Присяжних Тіні та послідовників темних мистецтв, яких вабить залишкова демонічна енергія, що просякла червоні пустирі. Глибоко в звивистих порожнинах дивні постаті віддаються власним одержимостям далеко від пильних очей Замку Незерґард."},{t="Лігво культистів",b="Печери давно слугують плацдармом для культистів Архімага Аллістаржа, які шанують демонічних владик і експериментують зі зловісними артефактами на кшталт Амулета Аллістаржа. Навіть коли влада їхнього господаря слабне, вірні фанатики Присяжних Тіні й далі патрулюють закрути печер, правлять обряди на службі Кіріта Проклятого й ховаються за обгорілими барикадами."}},faq={{q="Що таке Кільця Змія?",a="Кільця Змія — звивиста мережа печер і каньйон на сході Спустошених Земель, відомі обвугленими оркськими руїнами й зловісними мешканцями.",al={"кільця змія","що це за печера","кільця змія спустошені землі"}},{q="Звідки тут старі оркські споруди?",a="Табірні споруди сягають часів Першої й Другої воєн, коли Стара Орда пройшла крізь сусідній Темний Портал і укріпила довколишній край, доки не зазнала поразки.",al={"чому тут орківські руїни","орківські споруди спустошених земель","спалені хатини"}},{q="Хто живе в Кільцях Змія?",a="У печерах засіли сектанти-Тіньоприсяжні, що служать Архімагові Аллістаржу й темним силам, а також поодинокі дослідники незвичайної магії Спустошених Земель.",al={"хто тут","вороги кілець змія","хто контролює печеру"}},{q="Чому гном з Альянсу отаборився в печері, де довкола сама небезпека?",a="Касим Шарім проводить глибоко в печері власні небезпечні магічні дослідження: він ризикує поруч із сектантами, щоб вивчати могутні демонічні артефакти, розкидані по цих землях.",al={"гном у печері","касім шарім","чому тут касім"}}},fp="14,274,28.474.0,16.369.1,23.148.0,38.180.0,32.177.0,73.188.0"}
P.entries["subzone:sewers"] = {n="Каналізація",s="Каналізація — розлога підземна дренажна мережа, що дає ще один вхід просто до Андерсіті. Вона пролягає під пагорбами на захід від зруйнованого палацу Лордерона й дає змогу приборкувачам кажанів і обережним мандрівникам оминути хиткі підйомники, що спускаються з тронної зали.",h="Каналізація — розлога підземна дренажна мережа, що дає ще один вхід просто до Андерсіті.",kw={"каналізація","андерсіті","кажани","тірісфаль","лордерон","таємний вхід"},ang={["faction:Alliance"]="Кожен, хто достатньо безрозсудний чи відважний, щоб штурмувати столицю Відступників, знає: каналізація — єдиний потаємний шлях повз добре захищені руїни на поверхні.",["race:Undead"]="Для Відступників каналізація — важлива життєва артерія й повітряний коридор, що пов'язує Андерсіті з рештою Лордерона, не створюючи заторів біля підйомників у дворі."},sec={{t="Чорний хід до катакомб",b="До того як чума знищила Лордерон, ці кам'яні водостоки були звичайною каналізацією королівської столиці. Та у Відступників Сильвани Віндраннер стічні тунелі стали частиною зовнішньої оборони Андерсіті. Прохід виходить на поверхню на захід від руїн, поблизу спірної Багряної Вартової Вежі в Галявинах Тірісфалю, і веде рівним, прямим схилом усередину. Приборкувачі кажанів Відступників використовують цей печерний хід, щоб швидко переносити вершників до підземних кілець, цілком оминаючи повільні підйомники-клітки. Оскільки він обходить добре укріплені двори на поверхні, це небезпечне вразливе місце, яке ворожі лазутчики постійно намагаються використати."}},faq={{q="Куди виходить тунель каналізації?",a="Канал виходить на пологі пагорби Галявин Тірісфалю, трохи на захід від головної брами Руїн Лордерона. Неподалік — Багряна сторожова вежа, що дивиться на озеро.",al={"куди виходить каналізація","вихід з каналізації підміської","чорний вхід каналізації"}},{q="Навіщо комусь користуватися каналізацією замість головного входу?",a="Головний шлях до Андерсіті — це залізні клітки-підйомники з палацових руїн, а вони повільні й небезпечні під час нападу. Каналізація — прямий похилий шлях, яким літають кажани Відступників і яким можна швидко вибратися, не чекаючи на підйомник.",al={"чому каналізація","каналізація проти ліфтів","чорний хід підміської"}},{q="Чи безпечна каналізація від нападників з Альянсу?",a="Навряд. Вона оминає укріплену браму й тронну залу Лордерона, тож відчайдушні розвідники й ударні загони Альянсу найохочіше обирають саме її, щоб прокрастися просто до столиці Відступників.",al={"чи альянс нападе на каналізацію","чи охороняється каналізація","оборона каналізації підміської"}}},fp="6,312,29.696.0,41.190.0,61.273.0,40.221.0"}
P.entries["subzone:shadow-grave"] = {n="Тіньова Могила",s="Тіньова Могила — кам'яний склеп на вершині похилого цвинтаря над Похоронним Подзвоном у Галявинах Тірісфалю. Це фізична точка пробудження, де щойно звільнені Відступники скидають заціпеніння смерті й послаблену владу, яку над ними мав Король-Ліч.",h="Тіньова Могила — кам'яний склеп на вершині похилого цвинтаря над Похоронним Подзвоном у Галявинах Тірісфалю.",kw={"тіньова могила","склеп","пробудження","похоронний подзвін","гробар мордо","відступники","тірісфаль"},ang={["race:Undead"]="Кожен шукач пригод з-поміж Відступників починає свою путь на холодних кам'яних плитах цього склепу, розплющуючи очі на похмуру дійсність нежиття й вільної волі."},sec={{t="Колиска Відступників",b="Тіньова Могила, схована в скелястих передгір'ях за Могилами Похоронного Подзвону, — простий кам'яний мавзолей із надзвичайним призначенням. У його вологих склепіннях трупи, підняті для безтямної служби Погибелі, поступово пробуджуються до вільної волі. Під пильним оком доглядачів на кшталт Гробаря Мордо ці щойно звільнені мерці підводяться з кам'яних плит і роблять перші тремтливі кроки у світ, що їх зневажає, рушаючи стежкою вниз до Похоронного Подзвону, щоб присягнути Королеві Баньші."}},faq={{q="Для чого потрібна Тіньова Могила?",a="Це склеп, де щойно пробуджені Відступники приходять до тями. Замість лишатися безмозкими невільниками Погибелі в землі, воскреслі повертають собі вільну волю в цій гробниці й починають друге життя на службі Сильвані Віндраннер.",al={"призначення тіньової могили","що таке тіньова могила","склеп тіньової могили"}},{q="Де розташована Тіньова Могила?",a="Тіньова Могила стоїть на вершині пагорба над могилами Похоронного Подзвону, під південними горами Галявин Тірісфалю. Від її входу ґрунтова стежка в'ється вниз до поселення Похоронний Подзвін.",al={"де тіньова могила","розташування тіньової могили","тіньова могила на мапі"}},{q="Хто тут опікується щойно пробудженими?",a="Гробар Мордо наглядає за щойно пробудженими в гробниці: він перевіряє, чи ті, хто встає з кам'яних плит, повернули собі розум і чи придатні служити справі Відступників.",al={"хто в тіньовій могилі","нпс тіньової могили","де гробар морд"}}},fp="12,244,22.531.0,34.255.0,34.217.0,37.174.0"}
P.entries["subzone:shadow-hold"] = {n="Твердиня Тіні",s="Твердиня Тіні — розлогий підземний комплекс, схований у зачумленому каньйоні Джеденару в західному Скверноліссі. Колись це було священне курганне лігво нічних ельфів, а тепер його захопила й осквернила Рада Тіней, зробивши своїм головним бастіоном у Калімдорі.",h="Твердиня Тіні — розлогий підземний комплекс, схований у зачумленому каньйоні Джеденару в західному...",kw={"твердиня тіні","рада тіней","джеденар","лорд бейнголлоу","арко'нарін","чорнокнижники","сквернолісся"},ang={["class:Warlock"]="У найглибших закутках Твердині Тіні зберігаються рідкісні демонічні реагенти, як-от Зоротський Зоряний Пил. Здобути їх можна лише хитрим проникненням, завоювавши прихильність Лорда Бейнголлоу.",["race:NightElf"]="Для нічних ельфів твердиня — жахливе видовище: курганне лігво предків, осквернене мулом скверни, клітками для в'язнів і демонічними обрядами."},sec={{t="Осквернене святилище",b="Під оскверненою червоною землею Джеденару лежить Твердиня Тіні — величезний підземний лабіринт, вирубаний на місці давнього курганного лігва нічних ельфів. Там, де колись спочивали сплячі друїди, що оберігали Смарагдовий Сон, тепер звивистими коридорами, освітленими вогнем скверни, никають темні чорнокнижники й демонічні слуги. На найглибших ярусах культ має грізні сили під проводом жахолорда Лорда Бейнголлоу, Принца Ксаваліса та Тіньового Лорда Фел'дана, тож це найвищий осередок демонічного впливу в краї."},{t="Жахіття в глибинах",b="Рада Тіней використовує печери, щоб координувати осквернення Сквернолісся й проводити жорстокі допити. Розвідники Альянсу, зокрема нічна ельфійка Арко'нарін Старшейд і паладин-людина Трей Лайтфордж, потрапили до рук культистів глибоко у твердині. Арко'нарін вижила завдяки вчасному порятунку, а Трея закатували до смерті кати культу. Його дух на якийсь час обернувся на злобу, але згодом знайшов спокій. Смарагдове Коло й місцеві шамани невпинно працюють, щоб пробити темні бар'єри, які захищають твердиню, і завдати удару її демонічним володарям."}},faq={{q="Чим була Твердиня Тіні до того, як її захопила Рада Тіней?",a="Спершу Твердиня Тіні була давнім курганним лігвом нічних ельфів, присвяченим друїдам, що спали, доглядаючи землю, і спілкуванню зі Смарагдовим Сном. Після Третьої війни й демонічного зіпсуття Сквернолісся Рада Тіней захопила підземний комплекс і осквернила його священні зали, обернувши їх на фортецю Скверни.",al={"історія твердині тіні","хто збудував твердиню тіні","чим була твердиня тіні"}},{q="Хто править у Твердині Тіні?",a="Твердинею керує жахолорд Лорд Бейнголлоу разом із могутніми помічниками — сатиром Принцом Ксавалісом і чорнокнижником Тіньовим Лордом Фел'даном, що командує смертними сектантами.",al={"бос твердині тіні","хто керує твердинею тіні","лідери твердині тіні"}},{q="Навіщо шукачеві пригод мирно пробиратися до Твердині Тіні?",a="Знавці темних мистецтв, яким потрібні могутні реагенти для виклику, як-от Зоротський Зоряний Пил, часом заходять у твердиню під виглядом вірних сектантів Ради Тіней. Лорд Бейнголлоу дозволяє торгувати з чужинцями, лише якщо вони доведуть вірність, викриваючи шпигунів і зрадників у його лавах.",al={"проникнути у твердиню тіні","маскування ради тіней","зоротіанський зоряний пил"}},{q="Що сталося з полоненими у твердині?",a="Нічну ельфійку Арко'нарін Старшейд і паладина Трея Лайтфорджа схопили, коли вони розвідували Раду Тіней. Трея закатувала до смерті сектантка Ракайя, а Арко'нарін шукачі пригод визволили з клітки й згодом повернули рештки Трея, щоб гідно його поховати.",al={"в'язні джеденара","трей лайтфорж і арконарін","клітка твердині тіні"}}},fp="11,252,19.501.0,19.573.1,60.318.0,29.197.0,58.293.1,42.281.1"}
P.entries["subzone:shadowbreak-ravine"] = {n="Яр Тіньового Зламу",ang={["class:Warlock"]="Темні кола призову й зосереджена присутність Скверни роблять цей потаємний каньйон наочним свідченням того, як далеко сягає темне мистецтво Палаючого Клинка."},sec={{t="Потаємний анклав Скверни",b="Tucked deep into the barren mountain ridges southeast of Magram Village, Shadowbreak Ravine provides the Burning Blade with a secluded staging ground away from the eyes of wandering centaur tribes. Amid strange, oversized mushrooms and grim ritual encampments, cultists labor alongside summoned demons. Here, dark practitioners invoke fel energies and tend heavy ritual chains, using the natural isolation of the ravine to marshal reinforcements and maintain a firm demonic foothold within the badlands of Desolace."}},faq={{q="Що таке Яр Тіньового Зламу?",a="Shadowbreak Ravine is a hidden mountain ravine situated in southeastern Desolace, just beyond Magram Village. It serves as a concealed camp and staging ground for demonic minions and cultists serving the Burning Blade.",al={"інформація про яр тіньового зламу","що це за місце","де яр тіньового зламу"}},{q="Хто займає яр?",a="У яру засіли сектанти Палаючого Клинка, що діють пліч-о-пліч із демонами. Захищена місцевість яру дає їм змогу правити темні обряди й підтримувати ширший наступ по всьому краю.",al={"хто тут живе","моби яру тіньового зламу","вороги яру тіньового зламу"}},{q="Що можна знайти в яру?",a="У яру — темні обрядові споруди, масивні залізні ланцюги й помітні велетенські гриби, що проростають серед осквернених Скверною таборів, захованих у гірських розколинах.",al={"що в яру тіньового зламу","пам'ятки яру тіньового зламу"}}},fp="18,243,23.515.0,27.218.0,24.209.0,45.176.0"}
P.entries["subzone:shadowfang-keep"] = {n="Фортеця Шадовфенг",s="Фортеця Шадовфенг, що височіє на суворій кручі над Селом Пайрвуд у південному Срібноліссі, — темне лігво божевільного Архімага Аруґала та його диких воргенів. Колишня Фортеця Сільверлейн упала під натиском ненажерливих вовкоподібних звірів, викликаних під час Третьої війни, і тепер її давні зали населяють привиди вбитої знаті й кишать вовчі жахіття.",h="Фортеця Шадовфенг, що височіє на суворій кручі над Селом Пайрвуд у південному Срібноліссі, — темне лігво...",kw={"фортеця шадовфенг","архімаг аруґал","воргени","барон сільверлейн","село пайрвуд","срібнолісся","фенрус"},ang={["class:Mage"]="Фортеця Шадовфенг — похмуре нагадування про пиху Кірін-Тору й про лихо, до якого призводять нестримні виклики з інших вимірів.",["faction:Horde"]="Для Відступників Аруґалові воргени — непередбачувана загроза, що розповзається просто на порозі зовнішніх земель Андерсіті в Срібноліссі й вимагає швидкого знищення."},sec={{t="Падіння Сільверлейнів",b="До Третьої війни ця височенна твердиня звалася Фортецею Сільверлейн — родовим гніздом Барона Сільверлейна й осередком влади для сусіднього Села Пайрвуд. Коли Погибель пронеслася Лордероном, відчайдушні чарівники вдалися до заборонених засобів, щоб спинити хвилю нежиті. Спираючись на дослідження інших вимірів даларанського мага Ура, Архімаг Аруґал викликав в Азерот позавимірних воргенів. Дикі звірі шматували Погибель, але швидко вийшли з-під контролю. Шаленіючи по всьому південному Срібноліссю, зграя взяла твердиню в облогу й вирізала Барона Сільверлейна, його родину й оборонців Командира Спрінґвейла. Провина й горе зламали розум Аруґала: замість тікати, він захопив фортецю, перейменував її на Фортецю Шадовфенг і назвав жахливих хижаків своїми «дітьми»."},{t="Примарний оплот",b="Нині Фортеця Шадовфенг — осердя вовчого прокляття, що дедалі ширше мучить Срібнолісся. Аруґал живе в найвищій обсерваторії в оточенні своїх ненажерливих воргенів — зокрема зграй Мунрейдж і Шадовфенг — та зловісних звірів на кшталт його величезного улюбленого вовка Фенруса. Нижче його святилища неспокійні привиди колишніх володарів фортеці, як-от Барон Сільверлейн і Командир Спрінґвейл, лишаються ув'язненими в муках, приречені без кінця боронити зали, яких не вберегли за життя. З цих мурів Аруґал простягає свій підступний вплив до Села Пайрвуд і навколишніх лісів, становлячи страшну загрозу для сусідів-Відступників, що прагнуть очистити ліс від його божевілля."}},faq={{q="Як звалася Фортеця Шадовфенг до того, як її захопив Аруґал?",a="Спершу вона звалася Фортецею Сільверлейн. Це було родове гніздо Барона Сільверлейна, вельможі, чиє військо на чолі з паладином Командиром Спрінґвейлом опікувалося Селом Пайрвуд і довколишніми землями, доки їх не заполонили воргени.",al={"стара назва","хто володів шадовфенгом","фортеця сільверлейн"}},{q="Навіщо Аруґал викликав сюди воргенів?",a="Під час Третьої війни Погибель нещадно громила сили Даларану й піднімала вбитих чарівників як нежить. Усупереч застереженням Кірін-Тору, архімаг Аруґал скористався дослідженнями чарівника Ура й викликав воргенів з іншого виміру, щоб переломити хід війни. Вони справді винищили нежить, але швидко обернулися проти живих і розбіглися по Срібноліссю.",al={"навіщо аруґал викликав воргенів","історія аруґала","як воргени потрапили сюди"}},{q="Хто зараз править Фортецею Шадовфенг?",a="Фортецю тримає Архімаг Аруґал. Збожеволівши від провини за те, що випустив чудовиськ, він прийняв воргенів як своїх «дітей» і править із висот фортеці разом зі своєю смертоносною зграєю.",al={"хто тепер править шадовфенгом","хто живе у фортеці шадовфенг","фортеця аруґала"}},{q="Чому у Фортеці Шадовфенг є привиди?",a="Це привиди Барона Сільверлейна, Командира Спрінґвейла й колишніх мешканців фортеці. Коли воргени ринули до фортеці й вирізали всіх, хто був усередині, духи мешканців лишилися прикуті до каміння й приречені блукати зруйнованими коридорами.",al={"привид сільверлейн","привид коменданта спрінґвейла","нежить усередині шадовфенгу"}},{q="Як Село Пайрвуд пов'язане з фортецею?",a="Пайрвуд лежить у тіні фортеці й здавна підлягав Баронові Сільверлейну. Під дедалі сильнішим впливом Аруґала селян уразило прокляття воргенів: удень вони схожі на звичайних людей, а під нічним небом обертаються на скажених звірів.",al={"пайрвуд і шадовфенг","прокляття пайрвуду"}}},fp="15,366,24.815.0,17.707.0,56.237.0,38.369.0,36.195.0,40.253.0,55.270.1"}
P.entries["subzone:shadowglen"] = {n="Тінедол",s="Тінедол — відлюдна сутінкова долина в північно-східному гіллі Тельдрассила. Над нею височіє велике дерево-курган Алдрассил; це безпечний прихисток, де молоді нічні ельфи роблять перші кроки на службі, перш ніж вирушити в широкий світ.",h="Тінедол — відлюдна сутінкова долина в північно-східному гіллі Тельдрассила.",kw={"тінедол","алдрассил","стартова зона","нічні ельфи","тельдрассил","печера тіньової нитки","долина"},ang={["faction:Alliance"]="Розташований високо в гіллі Тельдрассила й далеко за охоронюваними портами, Тінедол — одна з найзахищеніших і найвідособленіших долин-святилищ Альянсу.",["race:NightElf"]="Кожен молодий нічний ельф починає свою діяльну путь тут, серед захищеного коріння Алдрассила, отримуючи перші благословення й настанови, перш ніж зустріти небезпеки Калімдору."},sec={{t="Захищена колиска",b="Тінедол, схований у північно-східній кроні Тельдрассила, оточений високими хребтами, що відгороджують його від решти світу. Залита вічними сутінками долина зосереджена довкола Алдрассила — велетенського дерева-кургану, у чиєму видовбаному стовбурі живуть старійшини, жриці й наставники молодих нічних ельфів, що починають навчання. Єдиний шлях із долини веде на південь вузьким гірським проходом до Села Зоряного Вітерця й Доланаара, тож Тінедол — одне з найзахищеніших самою природою й наймирніших святилищ Світового Дерева."},{t="Тіні підкрадаються",b="Попри тихе усамітнення, Тінедол не зовсім вільний від небезпек. На крайньому північному заході лежить Печера Тіньової Нитки — темна печера, що кишить отруйними павуками, які постійно загрожують тихому гаю. Навіть на незайманих гілках Тельдрассила потрібна пильність, і захисникам-початківцям доручають відганяти набридливу гидь і дику живність, перш ніж вирушати в ширші простори гілля."}},faq={{q="Що таке Тінедол?",a="Тінедол — захищений стартовий гай нічних ельфів у північно-східній частині Тельдрассила. Це мирний, відлюдний прихисток довкола великого дерева Алдрассил, де новачки навчаються в наставників, перш ніж вирушити мандрувати Світовим Деревом.",al={"що це за місце","лор тінедолу","про тінедол"}},{q="Що за величезне дерево в центрі долини?",a="Це Алдрассил — дерево-курган, що становить серце Тінедолу. Його видовбане нутро править за оселю громади й осередок навчання, де нічні ельфи-новачки зустрічають наставників класів, учителів і доглядачів.",al={"велике дерево в тінедолі","алдрассил","дерево тінедолу"}},{q="Які загрози є в Тінедолі?",a="Головна загроза — на північному заході, у Печері Тіньової Нитки: печера кишить отруйними павуками, що раз у раз виповзають у гай. Молодим захисникам доручають винищувати павуків і втихомирювати неспокійну місцеву живність.",al={"чому тут павуки","небезпеки тінедолу","печера тіньової нитки"}},{q="Як вийти з Тінедолу?",a="Тінедол повністю оточений хребтами, за винятком єдиної стежки на південь. Цей вузький гірський прохід веде на південь, до Села Зоряного Вітерця й поселення Доланаар.",al={"вихід із тінедолу","куди веде стежка","як вибратися з тінедолу"}}},fp="10,269,18.533.0,16.444.0,19.264.0,51.216.0,33.239.0,28.197.0"}
P.entries["subzone:shadowprey-village"] = {n="Село Тіньової Здобичі",s="Село Тіньової Здобичі — віддалене рибальське поселення Орди на скелястому південному березі Узбережжя Сар'теріс у Пустограї. Тут живуть переважно рибалки-тролі з племені Темного Списа, а таурени тримають корчму та інші служби; це важливий прибережний форпост і торговельна рятівна нитка посеред безплідного пустиря.",h="Село Тіньової Здобичі — віддалене рибальське поселення Орди на скелястому південному березі Узбережжя...",kw={"село тіньової здобичі","пустограй","тролі","темний спис","рибальство","узбережжя сар'теріс","орда"},ang={["faction:Horde"]="Для мандрівників Орди, що перетинають Пустограй, Село Тіньової Здобичі — єдиний прибережний перепочинок, вузол польотів і безпечна база постачання на південь від Цвинтаря Кодо.",["race:Troll"]="Село Тіньової Здобичі — рідкісний осередок прибережної культури Темного Списа в центральному Калімдорі, де видно споконвічну майстерність племені в рибальстві з острогою, пірнанні й виживанні на узбережжі."},sec={{t="Притулок на узбережжі",b="Притулившись до скель південного Пустограю, Село Тіньової Здобичі дає безпечну гавань у краї, відомому кланами кентаврів і безлюдними пустирями. Поселення — передусім табір рибалок-тролів, чий улов годує не лише їхнє село, а й форпости в глибині краю, як-от Заставу Духоходів. Попри скелястий берег, високі дерев'яні пристані сягають далеко в океан, тож місцеві рибалки виходять на глибину й пірнають по молюсків серед затонулих уламків, якими всіяне Узбережжя Сар'теріс."},{t="Прибережні випробування",b="Тримати прикордонний порт у Пустограї — справа, повна небезпек. Окрім кентаврів-мародерів у глибині краю, виживання села випробовує й сам океан. У місцевих водах лютує ненажерлива морська живність — передусім жахлива косатка Блаббергат, що пожирає рибні запаси, — а з південних берегів насуваються войовничі лобстроки. Союзники-таурени, серед них Тайга Вайзмейн і господарі корчми та сідала вітрокрилів, допомагають зміцнювати оборону й тримати відкритими торгові шляхи по всьому Калімдору."}},faq={{q="Чому Село Тіньової Здобичі важливе для Орди?",a="Пустограй — негостинна пустка, бідна на природні багатства. Село Тіньової Здобичі — єдиний морський порт Орди в краї: сюди привозять життєво важливі улови риби й молюсків, щоб годувати гарнізони на кшталт Застави Духоходів, а ще тут є сідало вітрокрилів із польотами до Гір Кам'яного Кігтя, Тандер Блафа й Фераласу.",al={"навіщо село тіньової здобичі","чому тіньова здобич тут","роль тіньової здобичі для орди"}},{q="Хто очолює Село Тіньової Здобичі?",a="Єдиного офіційного вождя в селі немає. Це вільна громада тролів-рибалок: старійшини, як-от Май'Лагії, підтримують зв'язки з гостями на кшталт Кола Кенарія, а мешканці-таурени, як-от Тайга Вайзмейн, дбають про безпеку узбережжя й місцеву оборону.",al={"лідер тіньової здобичі","хто керує тіньовою здобиччю","май'лахі"}},{q="Чому в тролівському селі послуги ведуть таурени?",a="Тіньова Здобич почалася як рибальська застава тролів Темного Списа, але роль місцевого осередку постачання привабила ширшу господарську машину Орди. Таурени опікуються спільною інфраструктурою: ведуть корчму, стайні й сідало вітрокрилів, що сполучає порт із Малгором і далі.",al={"таурени в тіньовій здобичі","чому тут таурени","таурени тіньової здобичі"}},{q="Що турбує рибалок?",a="Окрім ворожих кентаврів у глибині краю, селу дошкуляє брак риби, бо величезна косатка на прізвисько Салобрюх пожирає прибережні косяки, а ще на південних припливних мілинах кишать лобстроки.",al={"проблеми тіньової здобичі","бламбутроб","загрози тіньової здобичі"}}},fp="18,298,21.503.0,20.497.0,49.317.0,29.300.0,61.319.0,41.217.0"}
P.entries["subzone:shadowsong-shrine"] = {n="Святиня Шедовсонг",s="Святиня Шедовсонг — зруйноване святилище на схилі пагорба на заході Азшари, неподалік кордону з Ашенвалем. Тут блукають неспокійні духи прадавніх Високороджених; місце носить славетне ім'я роду Шедовсонгів, хоча його справжній історичний зв'язок із ними досі оповитий таємницею.",h="Святиня Шедовсонг — зруйноване святилище на схилі пагорба на заході Азшари, неподалік кордону з Ашенвалем.",kw={"святиня шедовсонг","джарод шедовсонг","маєв","високороджені","привиди","війна прадавніх","азшара"},ang={["race:NightElf"]="Для нічних ельфів ім'я Шедовсонг викликає глибоку шану завдяки тому, як Джарод вів військо у Війні Прадавніх, тож осквернення цього місця змученими привидами Високороджених особливо трагічне."},sec={{t="Спадщина з привидами",b="Святиня Шедовсонг, що стоїть на високому пагорбі над розтрощеними землями Азшари, давно лежить у порослих руїнах. Як і більшу частину довколишнього узбережжя, її досі терзають примари Високороджених, що блукають серед поваленого каміння й прагнуть погасити кожне смертне життя, яке посміє ступити на їхні володіння. Святиня має спільне ім'я з двома легендарними постатями історії калдореїв: Джародом Шедовсонгом, мимовільним полководцем, що очолив опір нічних ельфів у Війні Прадавніх, і його сестрою Маєв — невблаганною наглядачкою Іллідана Стормрейджа. Чи звели це святилище на честь їхніх звершень, чи воно сягає часів, коли родина мала вагу ще до Розколу, — таємниця, що загубилася у віках."}},faq={{q="Що таке Святиня Шедовсонг?",a="Це давні руїни нічних ельфів на узвишші на заході Азшари. Нині вони напівзруйновані й занедбані, і їх заполонили ворожі примари Високородних.",al={"що це за місце","інформація про святиню шедовсонг","руїни на пагорбі ашара"}},{q="На честь кого названо святиню?",a="Вона носить ім'я славетного роду Шедовсонгів — передусім Джарода Шедовсонга, героя Війни Прадавніх, і його старшої сестри Маєв, знаменитої наглядачки. Проте чи вшановує святиня когось із них безпосередньо, достеменно не записано.",al={"джаред шедовсонг","майєв шедовсонг","чому шедовсонг"}},{q="Чому в святині блукають привиди?",a="Як і багато руїн по всій Азшарі, це місце спустошив Великий Розкол десять тисяч років тому. Духи Високородних, що загинули в катаклізмі, досі прикуті до каміння, замкнені в божевіллі й ворожі до живих.",al={"чому тут привиди","високородні привиди ашара","привиди святині шедовсонг"}},{q="Де розташована святиня?",a="Вона стоїть на вершині пагорба на заході Азшари, на схід від лісистого кордону з Ашенвалем і неподалік від застави Мис Талрендіс.",al={"де святиня шедовсонг","розташування святині шедовсонг","як знайти святиню шедовсонг"}}},fp="17,306,16.730.0,26.158.0,30.265.0,26.242.0,28.131.0"}
P.entries["subzone:shadowthread-cave"] = {n="Печера Тіньової Нитки",s="Печера Тіньової Нитки — волога печера в північно-західних скелях Тінедолу на Тельдрассилі. Здавна заселена тутешніми павуками Вебвуда, вона нещодавно стала небезпечно агресивною під владою їхньої матки — Ґітіісс Мерзенної.",h="Печера Тіньової Нитки — волога печера в північно-західних скелях Тінедолу на Тельдрассилі.",kw={"печера тіньової нитки","павуки","вебвуд","ґітіісс мерзенна","тінедол","тельдрассил","виводок"},ang={["class:Druid"]="Нестримна агресія виводку Вебвуда в Печері Тіньової Нитки — тривожний знак для друїдів, що природна гармонія Тельдрассила глибоко порушена.",["race:NightElf"]="Для молодих нічних ельфів очищення Печери Тіньової Нитки та вбивство Ґітіісс Мерзенної — одне з найперших випробувань у захисті священної домівки від скверни, що підкрадається."},sec={{t="Неспокійний виводок",b="Печера Тіньової Нитки в тінистій околиці Тінедолу здавна була природним лігвом велетенських павуків Тельдрассила. Раніше ці павуки тихо співіснували з молодим гіллям Світового Дерева. Та віднедавна їхня вдача стала люто територіальною. Товсті шари павутиння Вебвуда тепер душать кам'яні коридори, а агресивність виводку становить пряму загрозу молодим калдореям, що роблять перші кроки за межі Алдрассила."},{t="Ґітіісс Мерзенна",b="Головна загроза, що чаїться в найтемніших закутках печери, — Ґітіісс Мерзенна, жахлива матка виводку, чия лють далеко перевершує звичайних павуків Вебвуда. Вартових і друїдів нічних ельфів-новачків посилають до печери стримати навалу павуків і вбити Ґітіісс, щоб скверна, яка торкнулася живності Тельдрассила, не поглинула святилище Тінедолу цілком."}},faq={{q="Де розташована Печера Тіньової Нитки?",a="Печера Тіньової Нитки — у північно-західному куті Тінедолу, під скелястим схилом на межі долини, де починають свій шлях нічні ельфи на Тельдрассилі.",al={"розташування печери тіньової нитки","де печера тіньової нитки","знайти печеру тіньової нитки"}},{q="Чому павуки в печері такі агресивні?",a="Павуки жили в печері завжди, але мерзенна хвороба й дедалі більший розлад рівноваги на Тельдрассилі звели з розуму місцевих звірів, і павуки Вебвуда стали надзвичайно лютими.",al={"чому павуки ворожі","скверна павуків тіньової нитки","чому павуки нападають"}},{q="Хто така Ґітіісс Мерзенна?",a="Ґітіісс Мерзенна — величезна отруйна павучиха-матріарх Вебвуда, що засіла в найглибшій точці Печери Тіньової Нитки. Вона праматір агресивного поріддя, що загрожує юним калдореям у Тінедолі.",al={"ґітіісс","хто така ґітіісс","бос павуків тіньової нитки"}},{q="Чим цінна печера, попри небезпеку?",a="Печера аж напхана шарами густого природного шовку павуків Вебвуда — цінного й міцного матеріалу для ремесел, який тчуть нескінченні рої павуків, що живуть у її темних залах.",al={"шовк тіньової нитки","павучий шовк тіньової долини"}}},fp="17,263,24.490.0,17.400.0,35.151.0,46.192.0,25.200.0,48.183.0"}
P.entries["subzone:shady-rest-inn"] = {n="Корчма «Затишний Спочинок»",s="Корчма «Затишний Спочинок» колись була гостинним придорожнім притулком, збудованим людьми біля дороги між Пустками й Островом Терамор. Нині від неї лишилися тільки обвуглені колоди й тліючий попіл після раптового жорстокого підпалу. Трагедія зламала корчмаря й посіяла напругу по всьому болоту, поки слідчі перебирають згарище в пошуках доказів.",h="Корчма «Затишний Спочинок» колись була гостинним придорожнім притулком, збудованим людьми біля дороги між...",kw={"затишний спочинок","корчма","багно пилоброду","підпал","ґрімтотем","джеймс гайал","терамор"},ang={["faction:Alliance"]="Знищення корчми — серйозний пролом у безпеці на головному суходільному шляху до Острова Терамор: воно загрожує мандрівникам і роздмухує страх перед прихованими ворогами.",["race:Tauren"]="Жорстокий, неспровокований наліт клану Ґрімтотем загрожує зруйнувати крихкий мир між Ордою й силами Джайни Праудмур у Багні Пилоброду."},sec={{t="Попіл на кордоні",b="Збудована для мандрівників, що долали небезпечний шлях між Багном Пилоброду й Пустками, Корчма «Затишний Спочинок» була острівцем цивілізованого затишку серед суворої глушини. Усе скінчилося, коли корчму раптово знищила нищівна пожежа. Корчмар Джеймс Гайал вижив у вогні, але полум'я забрало життя його дружини й дитини. Травмований і вбитий горем, Гайал лишився ні з чим, а згарище стало місцем злочину, яке пильно досліджує влада Терамору, відчайдушно намагаючись з'ясувати, хто підпалив корчму."},{t="Павутина підозр",b="Перші розслідування підпалу вказували на людей-дезертирів і підозрілих солдатів: під важку підозру потрапили такі постаті, як Павал Ріт і Лейтенант Колдвелл, — обидва згодом передчасно загинули. Проте речові докази, знайдені в попелі, — зокрема характерні сліди копит і ритуальні знаки — показали, що напад був не просто внутрішньою зрадою. Підпал учинили безжальні таурени Ґрімтотем, які завдають ударів із глибини болота, щоб посіяти розбрат між Терамором і його сусідами."}},faq={{q="Що сталося з Корчмою «Затишний Спочинок»?",a="На корчму напали й спалили її дощенту. Спершу підозрювали дезертирів і вояків-відступників з Альянсу, і слідчі досі перебирають попіл у пошуках доказів, хто насправді стоїть за підпалом.",al={"чому корчма затишний спочинок згоріла","що сталося з корчмою","хто спалив затишний спочинок"}},{q="Кому належала корчма й хто її тримав?",a="Корчму «Затишний Спочинок» тримав Джеймс Гайал. Він пережив пожежу, але його дружина й дитина загинули у вогні, і це глибоко його травмувало.",al={"корчмар затишного спочинку","хто тримав затишний спочинок","джеймс гайал"}},{q="Де розташована Корчма «Затишний Спочинок»?",a="Руїни лежать біля головної дороги на заході Багна Пилоброду, неподалік від кордону, де болото переходить у Пустки.",al={"розташування затишного спочинку","де корчма затишний спочинок"}},{q="Хто такі Павал Ріт і Лейтенант Колдвелл?",a="Це люди, яких запідозрили на початку розслідування пожежі. Обидва загинули, перш ніж слідчі встигли дістати з них зізнання чи остаточно з'ясувати, наскільки вони були причетні.",al={"хто такий ріт","лейтенант колдвелл затишний спочинок","ріт і колдвелл"}}},fp="14,361,19.565.0,18.526.1,36.201.1,31.136.0,36.126.0,45.200.1"}
P.entries["subzone:shalzaru-s-lair"] = {n="Лігво Шалзару",s="Лігво Шалзару — розлога напівзатоплена печера на північному краю Острова Жаху у Фераласі. Це головна твердиня наг Гребеня Ненависті й притулок їхнього грізного володаря Шалзару. Із цих вологих тунелів зміюваті загарбники керують своїм наступом просто на південь від Твердині Перистого Місяця.",h="Лігво Шалзару — розлога напівзатоплена печера на північному краю Острова Жаху у Фераласі.",kw={"лігво шалзару","лорд шалзару","наги","острів жаху","твердиня перистого місяця","фералас"},ang={["faction:Alliance"]="Наги Гребеня Ненависті, що збираються в цій печері, загрожують шляхам постачання й спокою Твердині Перистого Місяця, тож знищити Шалзару та його кубло — першочергове завдання для Вартових та їхніх союзників.",["race:NightElf"]="Мерзенні наги, що паплюжать прадавні прибережні руїни Фераласу, — болісне нагадування про Розкол і про те, як Високородні скотилися до потворної скверни."},sec={{t="Зміїне кубло на мілині",b="Лігво Шалзару, вирубане в урвистих кручах на північному кінці Острова Жаху, складається з величезної головної печери та меншої бічної зали, сполучених затопленими підземними протоками. Усередині кишать зміїні вартові Гребеня Ненависті й чарівниці, які пильно стоять на сторожі. У найглибших закутках живе Лорд Шалзару — зміюватий володар, що керує всім кублом Гребеня Ненависті на острові. Лігво розташоване так близько до Острова Сардор, що становить пряму й постійну загрозу для Вартових нічних ельфів, які стоять залогою в Твердині Перистого Місяця просто за протокою."}},faq={{q="Де розташоване Лігво Шалзару?",a="Лігво Шалзару — на північному краю Острова Жаху, що лежить просто на південь від Острова Сардор і Твердині Перистого Місяця біля західного узбережжя Фераласу.",al={"де лігво шалзару","розташування лігва шалзару","як знайти лігво шалзару"}},{q="Хто такий Шалзару?",a="Шалзару — могутній воєначальник наг і володар племені Гребеня Ненависті, що живе на Острові Жаху. Він командує своїми силами з глибин затоплених печер лігва.",al={"хто такий шалзару","лор шалзару","бос лігва шалзару"}},{q="Хто живе в цій печері?",a="Печера кишить нагами Гребеня Ненависті — здебільшого пильними зміями-вартовими, що стережуть сухі проходи, і чаклунками, що спрямовують магію над підземними водами.",al={"вороги лігва шалзару","моби печери наг"}},{q="Чому це лігво важливе для місцевих нічних ельфів?",a="Острів Жаху лежить просто через протоку від Твердині Перистого Місяця, тож скупчення наг у Лігві Шалзару — пряма військова загроза для сил Шандріс Фезермун і безпеки Острова Сардор.",al={"чому нічним ельфам важливий шалзару","загроза наг перистому місяцю"}}},fp="15,343,29.575.0,33.177.0,16.176.0,33.185.0,52.245.0"}
P.entries["subzone:shaper-s-terrace"] = {n="Тераса Формувальника",s="Тераса Формувальника — загадковий оглядовий майданчик із прадавньою архітектурою титанів, що височіє на північних кручах над Притулком Маршала. Названа на честь Каз'ґорота Формувальника, вона мовчки свідчить про первісні експерименти, які сформували Кратер Ун'Ґоро.",h="Тераса Формувальника — загадковий оглядовий майданчик із прадавньою архітектурою титанів, що височіє на...",kw={"тераса формувальника","титани","каз'ґорот","ун'ґоро","дворфи","руїни"},ang={["race:Dwarf"]="Для дворфів, які шукають свого титанічного родоводу, Тераса Формувальника — ще одна спокуслива нагода зазирнути в архітектуру Каз'ґорота й величні творіння творців."},sec={{t="Спадок титанів",b="Над буйною доісторичною западиною Кратера Ун'Ґоро, на Терасі Формувальника, стоять монументальні кам'яні споруди, які лишили по собі титани. Вважають, що це високе плато присвячене Каз'ґороту Формувальнику; воно свідчить про небесних зодчих, які плекали кратер як живу лабораторію для ранніх форм життя на Азероті. З цих піднесених каменів прадавні сутності колись спостерігали за рослинами й тваринами внизу та спрямовували їхній розвиток. Холодні кам'яні арки й масивні металеві постаменти разюче й загадково контрастують із дикою природою, що буяє просто під ними."}},faq={{q="Що таке Тераса Формувальника?",a="Тераса Формувальника — висока пам'ятка титанів на північних кручах Кратера Ун'Ґоро, просто над Притулком Маршала. Тут стоять кам'яні споруди, пов'язані з титанами, що колись формували цю землю.",al={"тераса формувальника","що це за тераса","тераса ун'ґоро"}},{q="Хто такий «Формувальник»?",a="Назва тераси вказує на Каз'ґорота Формувальника — одного з титанів-творців, що в давнину допомагали створювати й плекати світ Азероту.",al={"хто такий формувальник","хазґорот","хто створив терасу формувальника"}}},fp="16,272,22.577.0,29.204.0,21.143.0"}
P.entries["subzone:shatter-scar-vale"] = {n="Долина Розтрощеного Шраму",s="Долина Розтрощеного Шраму — випалена улоговина в центральному Скверноліссі, трохи на північ від Водоспаду Кривавої Отрути. Саме сюди в Третю війну врізалися демонічні інфернали, впавши на північ Калімдору. Нині кратери досі палають вогнем скверни, і тут ховаються рештки Палаючого Легіону.",h="Долина Розтрощеного Шраму — випалена улоговина в центральному Скверноліссі, трохи на північ від Водоспаду...",kw={"долина розтрощеного шраму","інфернали","палаючий легіон","кратери","сквернолісся","третя війна"},ang={["class:Druid"]="Тліючі шрами цієї долини — відкриті рани на душі Калімдору, які не загояться, доки творіння Легіону ще палають.",["class:Warlock"]="Насичені скверною ядра інферналів, що бродять цими кратерами, — потужні провідники хаотичної магії, які лишилися після вторгнення Легіону."},sec={{t="Удар інферналів",b="У Третю війну Палаючий Легіон обрушив на північний Калімдор зливу живих облогових машин. Долина Розтрощеного Шраму прийняла на себе основний удар цього небесного натиску. Демонічні інфернали падали з неба, проривалися крізь давні крони й вибивали в землі глибокі кратери. Нищівні удари розтрощили місцевість, залишивши почорнілі западини, що й досі тліють нечестивим вогнем. Хоч Легіон і розбили біля Гори Гіджал, інфернали й дрібніші демони так і не розсіялися, міцно закріпившись у пошрамованій землі."}},faq={{q="Чому земля вкрита кратерами?",a="Кратери з'явилися під час Третьої війни, коли Палаючий Легіон бомбардував ліс інферналами. Ці громіздкі створіння з каменю Скверни падали з неба, мов метеори, вгризалися в землю й лишали по всій долині тліючі шрами від ударів.",al={"кратери скверноліссі","чому долина розтрощеного шраму в кратерах","що зробило кратери"}},{q="Хто блукає Долиною Розтрощеного Шраму?",a="Долину досі заполоняють створіння й слуги Палаючого Легіону. Живі інфернали й далі стережуть тліючі вирви, а поряд блукають інші дрібніші демони, що лишилися, коли навала захлинулася.",al={"які моби тут","вороги долини розтрощеного шраму"}},{q="Де розташована Долина Розтрощеного Шраму?",a="Долина Розтрощеного Шраму лежить у центрі Сквернолісся, просто на північ від Водоспаду Кривавої Отрути, на східному боці головної лісової стежки.",al={"розташування долини розтрощеного шраму","де долина розтрощеного шраму"}}},fp="17,294,23.559.0,37.260.0,38.214.0,35.153.0"}
P.entries["subzone:shattered-strand"] = {n="Розтрощене Узмор'я",s="Розтрощене Узмор'я — дике скелясте узбережжя вздовж північного краю Затоки Бур в Азшарі. Тут панують гуркітливий прибій і прадавні руїни, що розсипаються, а пляж аж кишить небезпечними морськими звірами й племенами водяних істот.",h="Розтрощене Узмор'я — дике скелясте узбережжя вздовж північного краю Затоки Бур в Азшарі.",kw={"розтрощене узмор'я","затока бур","азшара","гідри","морські гіганти","храм арккорана","вежа ельдари"},ang={["class:Hunter"]="Узмор'я — дике випробувальне поле, повне грізних гідр і прибережних звірів, ідеальне для тих, хто шукає могутніх звірів-супутників або вивчає хижу фауну узбережжя Калімдору."},sec={{t="Підступне узбережжя",b="Розтрощене Узмор'я, що тягнеться вздовж північного краю Затоки Бур, — далеко не мирний берег. На кам'янистих пляжах і приливних мілинах повно агресивних істот: велетенських морських гігантів, багатоголових гідр і клацливих макрур, а поряд стоять табори прибережних мурлоків. Над хвилями нависають ельфійські споруди, що розсипаються, — зокрема прадавній Храм Арккорана й самотня Вежа Ельдари. Для мандрівників, що пробираються підступними кручами Азшари, спуститися на цю відлюдну смугу узбережжя означає зустрітися з одними з найнебезпечніших загроз краю, що живуть і у воді, і на суходолі."}},faq={{q="Де розташоване Розтрощене Узмор'я?",a="Розтрощене Узмор'я — північне узбережжя Затоки Бур на сході Азшари, під височенними кручами краю.",al={"розташування розтрощеного узмор'я","де розтрощене узмор'я","розтрощене узмор'я на мапі"}},{q="Хто живе на Розтрощеному Узмор'ї?",a="Узбережжям нишпорять люті гідри, величезні морські велетні, закуті в панцир макрури й гурти ворожих мурлоків, що патрулюють припливні мілини.",al={"моби розтрощеного узмор'я","хто живе на розтрощеному узмор'ї","звірі розтрощеного узмор'я"}},{q="Які відомі руїни є на пляжі?",a="На узбережжі стоять давні споруди Високородних — передусім Храм Арккорана й сусідня Вежа Ельдари, що височіє над затокою.",al={"руїни розтрощеного узмор'я","будівлі на розтрощеному узмор'ї","пам'ятки розтрощеного узмор'я"}},{q="Чи безпечне Розтрощене Узмор'я для безтурботних прогулянок?",a="Ні. Пляж відрізаний від світу, швидко втекти звідси важко через прямовисні скелі довкола, і тут аж кишить хижими морськими звірами й могутніми велетнями.",al={"чи небезпечне розтрощене узмор'я","рівень розтрощеного узмор'я"}}},fp="16,239,23.622.0,38.149.0,44.148.0,48.144.0,52.161.0"}
P.entries["subzone:shifting-mire"] = {n="Мінлива Твань",s="Мінлива Твань — велике мулисте серце Болота Скорботи, що лежить трохи на захід від Ставка Сліз. Свою назву вона отримала через дивний, неспокійний мул під каламутною водою, який ніби дрейфує й збирається докупи під впливом незримої сили.",h="Мінлива Твань — велике мулисте серце Болота Скорботи, що лежить трохи на захід від Ставка Сліз.",kw={"мінлива твань","болото скорботи","загублені","болотяні ягуари","кроколіски","мул"},ang={["class:Hunter"]="Через сплутані хащі й мінливі води вистежувати здобич тут нелегко, тож мисливцям слід бути напоготові, щоб їх не заскочили потайні болотяні ягуари й отруйні скорботні прядильники, які ховаються в заростях."},sec={{t="Живе болото",b="Мінлива Твань простягається через усю серцевину боліт — це моторошний простір, де важко знайти тверду опору під ногами. Мул на дні болота зсувається й збивається докупи, наче його рухає жива воля, яку пробуджує дивна енергія, що просякає торф. Серед мулу, що повільно пливе, нишпорять хижі болотяні ягуари, величезні скорботні прядильники й голодні пилозубі кроколіски, а потопленими стежками блукають ватаги зламаних дренеїв, відомих як Загублені."}},faq={{q="Чому вона зветься Мінливою Тванню?",a="Назва походить від надзвичайно дрібного мулу на дні болота. Замість осідати, як звичайний намул, він під дією загадкового потоку енергії збирається, дрейфує й тече болотами, наче живий.",al={"походження назви мінливої твані","чому мінлива твань","чому земля рухається"}},{q="Хто живе в Мінливій Твані?",a="Твань кишить небезпечними звірами: пилкозубі кроколіски чатують на мілинах, велетенські скорботні прядильники плетуть павутиння на гілках, а болотяні ягуари підкрадаються непомітно. Тут часто блукають і Загублені — дренеї, спотворені й вигнані з рідного світу.",al={"моби мінливої твані","що в мінливій твані"}},{q="Де розташована Мінлива Твань?",a="Вона охоплює центральну частину Болота Скорботи, просто на захід від великого озера, відомого як Ставок Сліз.",al={"розташування мінливої твані","де мінлива твань"}}},fp="13,252,12.460.0,35.237.0,41.269.0,35.139.0"}
P.entries["subzone:shimmer-ridge"] = {n="Мерехтливий Хребет",s="Мерехтливий Хребет — суворе високогір'я на півночі Дун Мороґу, просто на захід від Брами Айронфорджа. Скелясті висоти, зайняті ворожими тролями Морозогривами, складаються з двох таборів, з'єднаних хистким мостом, і славляться як єдине місце, де можна зібрати потужне мерехтливе зілля.",h="Мерехтливий Хребет — суворе високогір'я на півночі Дун Мороґу, просто на захід від Брами Айронфорджа.",kw={"мерехтливий хребет","мерехтливе зілля","морозогриви","тролі","травництво","дун мороґ"},ang={["profession:Herbalism"]="Поки звичайні рослини ледве животіють у морозному кліматі Дун Мороґу, лише на Мерехтливому Хребті ростуть цінні кошики мерехтливого зілля, доглянуті серед таборів Морозогривів.",["race:Dwarf"]="Мерехтливий Хребет у тіні брами Айронфорджа — прикре нагадування про невідступну загрозу Морозогривів і небезпечне джерело добірного мерехтливого зілля для легендарного дворфського стауту."},sec={{t="Твердиня Морозогривів",b="Мерехтливий Хребет на скелястих схилах одразу на захід від величної брами Айронфорджа служить дієвим редутом племені тролів Морозогривів. Поділений на два табори обабіч провалля й з'єднаний дерев'яним прогоном, анклав пильно охороняють тролі-збирачі та їхні приручені гірські вепри. Близькість до головної дороги та дворфської столиці робить його постійною загрозою для мандрівників і гірських патрулів, які мусять повсякчас остерігатися зухвалих набігів із висоти."},{t="Ціна мерехтливого зілля",b="Окрім вигідного розташування, хребет славиться мерехтливим зіллям — рослиною, яку вирощують тролі Морозогриви. Місцеві дворфські пивовари цінують його для міцних, насичених високогірних елів, а деінде його так просто не збереш. Відважні горяни та молоді новобранці часто ризикують потрапити в засідку Морозогривів чи під ікла диких вепрів лише заради того, щоб зібрати свіжі кошики дорогоцінної рослини просто з тролячих грядок."}},faq={{q="Де розташований Мерехтливий Хребет?",a="Мерехтливий Хребет — на півночі Дун Мороґу, просто на захід від величезної Брами Айронфорджа, що веде до дворфійської столиці.",al={"розташування мерехтливого хребта","де мерехтливий хребет","знайти мерехтливий хребет"}},{q="Хто тримає Мерехтливий Хребет?",a="Хребет займає місцеве плем'я тролів-Морозогривів: вони отаборилися двома таборами, сполученими мостом, і боронять висоти разом зі своїми прирученими вепрами.",al={"хто на мерехтливому хребті","вороги мерехтливого хребта","тролі мерехтливого хребта"}},{q="Що таке мерехтлива трава й чому її шукають?",a="Мерехтлива трава — особлива гірська рослина, що буяє на холодних схилах хребта. Місцеві дворфійські пивовари дуже її цінують як неодмінний складник особливих, смачних рецептів гірського елю.",al={"навіщо мерехтлива трава","що таке мерехтлива трава","призначення мерехтливої трави"}},{q="Чому дворфи не виженуть тролів остаточно?",a="Військо Айронфорджа зайняте ширшою обороною й зовнішніми справами, тож місцеві загрози на кшталт таборів Морозогривів у Дун Мороґу полишено місцевим горянам і заїжджим новобранцям.",al={"чому айронфордж ігнорує мерехтливий хребет","айронфордж проти морозогривів","відповідь дворфів на мерехтливий хребет"}}},fp="13,282,22.510.0,24.439.0,31.140.0,27.168.0,47.205.0,54.202.0"}
P.entries["subzone:shimmering-flats"] = {n="Мерехтливі Низини",s="Мерехтливі Низини — безкраї солончаки на південно-східному краю Тисячі Голок, на межі з пустелею Танаріс. Колись тут було дно прадавнього озера, а тепер ця випалена сонцем рівнина славиться шаленими механічними змаганнями на Перегонах Міражу та суворими пустельними звірами.",h="Мерехтливі Низини — безкраї солончаки на південно-східному краю Тисячі Голок, на межі з пустелею Танаріс.",kw={"мерехтливі низини","солончаки","перегони міражу","гоблінська інженерія","гномська інженерія","силітиди"},ang={["profession:Engineering"]="Солончаки — місце прощі для інженерів: тут усе всіяне брухтом, тут випробовують пальне й ганяють машини на шаленій швидкості, і все це живить нескінченне суперництво гоблінських і гномських механіків.",["race:Gnome"]="На Перегонах Міражу гномські пілоти та механоступи відважно обстоюють гордість гномської інженерії проти нестабільних, вибухових конструкцій суперників-гоблінів."},sec={{t="Ложе солі та швидкості",b="Мерехтливі Низини простягаються під сліпучим південним сонцем — величезне висохле дно озера без жодної рослинки, де тут і там біліють вибілені сонцем кістки черепах і навіть дерев'яний остов прадавнього вітрильника. Цілковито рівна, без жодного горбка поверхня робить низини найкращим на Калімдорі полігоном для експериментальних машин. У самому центрі солончаків лежать Перегони Міражу, де гноми й гобліни-винахідники безупинно змагаються, чиї ракетні автомобілі, гірокоптери й двигуни розженуться найшвидше, — і часто це закінчується вогняними аваріями та димними вирвами на білій кірці."},{t="Небезпеки солончаків",b="Окрім ревіння двигунів на трасі, улоговина зовсім не мирна. Загартовані василіски, агресивні скорпіди й стерв'ятники, що кружляють у небі, полюють на все, що сповільнюється на відкритому просторі. Південніше земля стає підступною довкола Розкопок Іржавого Молота. Спершу їх розробляли дворфійські рудошукачі, потім за них змагалася Орда, а тоді кар'єр зовсім покинули: кайла пробили підземні тунелі, і на південний край низин вирвався рій лютих силітидів."}},faq={{q="Звідки посеред пустелі розбитий корабель?",a="Колись Мерехтливі Низини були величезним внутрішнім озером, що давно висохло. Корабельні уламки на півночі низин — пам'ять про ту давню водойму, що лишилася, коли озеро випарувалося й обернулося на безкраї солончаки, які видно нині.",al={"корабель на мерехтливих низинах","човен на солончаках","розбитий човен у тисячі голок"}},{q="Чому тут разом гноми й гобліни?",a="Суцільна пласка соляна кірка — ідеальна місцевість для випробувань реактивних автомобілів і найновіших механізмів. Замість воювати за землю, місцеві гноми й гобліни влаштували Перегони Міражу, щоб підживлювати своє технічне суперництво, безкінечно намагаючись перевершити одне одного в швидкості, інженерії й безрозсудній відвазі.",al={"історія перегонів","чому вони змагаються","гноми й гобліни на солончаках"}},{q="Що сталося з дворфійськими розкопками на півдні?",a="Розкопки Растмолів заклали дворфи-археологи, на яких невдовзі напав загін Орди на чолі з Моктаром Кріном. А тоді копачі ненароком пробилися в підземний вулик силітидів, випустивши рої комашиних жахіть, що прогнали всіх і заполонили південь низин.",al={"історія растмолу","що сталося з растмолом","комахи на солончаках"}},{q="Куди веде дорога через Мерехтливі Низини?",a="Якщо йти слідами на південний схід через солончаки, вийдете просто до гірського перевалу, що відкривається в неозору пустелю Танарісу й до нейтрального порту Ґаджетзан.",al={"куди веде мерехтлива низина","як дістатися до танарісу","вихід у танаріс"}}},fp="16,303,23.588.0,19.504.0,59.255.0,41.336.0,51.298.0,54.164.0"}
P.entries["subzone:shining-strand"] = {n="Осяйне Узмор'я",s="Осяйне Узмор'я — смуга берега Озера Лордамер на сході Срібнолісся, що тягнеться на південь від Руїн Лордерона до суворих передгір'їв Альтерака. Колись тут панували агресивні мурлоки-Темноплавці, а тепер береги стали спірною землею, де табори Відступників стежать за водою й сходяться в сутичках із воргенами, що наступають.",h="Осяйне Узмор'я — смуга берега Озера Лордамер на сході Срібнолісся, що тягнеться на південь від Руїн Лордерона...",kw={"осяйне узмор'я","озеро лордамер","темноплавці","аптекар берард","нова чума","срібнолісся"},ang={["faction:Horde"]="Узмор'я — зручний, хоч і небезпечний, шлях уздовж Озера Лордамер, що з'єднує північні підступи до Срібнолісся з переходами до Гір Альтерак.",["race:Undead"]="Утримання Осяйного Узмор'я захищає південний озерний фланг Андерсіті й дає цінні зразки для досліджень нової чуми, які веде Королівське Аптекарське Товариство."},sec={{t="Спірне узбережжя",b="Осяйне Узмор'я, що тягнеться східним краєм Срібнолісся, межує з туманними водами Озера Лордамер. Колись плем'я мурлоків-Темноплавців заснувало на цих мілинах кілька агресивних поселень, і кожен, хто намагався йти дорогою вздовж озера, наражався на смертельну небезпеку. Хоч Темноплавці здебільшого перебралися на схід, до Світанкових Островів, на березі аж ніяк не спокійно. Розвідники й аптекарі Відступників закріпилися на узмор'ї, відбиваючись від диких воргенів, що виходять із глибини лісу, і пильно стежачи і за водами, і за пагорбами на межі з Альтераком."},{t="Алхімічний урожай",b="Окрім стратегічного розташування між Лордероном і південними кордонами, Осяйне Узмор'я та сусідні води рано привернули увагу Королівського Аптекарського Товариства. Покійний Аптекар Берард записував спостереження про дивні затверділі пухлини, вирізані в місцевих мурлоків-Темноплавців, і припускав, що їхня спотворена будова може стати цінним каталізатором для нової чуми молодої держави Сильвани Віндраннер."}},faq={{q="Де розташоване Осяйне Узмор'я?",a="Осяйне Узмор'я — східне узбережжя Срібнолісся на березі Озера Лордамер. Воно починається трохи на південь від Руїн Лордерона й упирається в нерівні пагорби, що відділяють Срібнолісся від Гір Альтерак.",al={"розташування осяйного узмор'я","де осяйне узмор'я","узбережжя сілверпайну"}},{q="Які небезпеки чатують на Осяйному Узмор'ї?",a="Табори Відступників на узмор'ї раз у раз відбиваються від воргенів, що виходять із лісів Срібнолісся. Колись мурлоки-Темноплавці мали на березі опорні пункти, але більшість із них перебралася на сусідні Світанкові Острови, хоча на мілинах досі чатують водяні загрози.",al={"монстри осяйного узмор'я","що на осяйному узмор'ї","вороги осяйного узмор'я"}},{q="Чому цей край цікавить Королівське Аптекарське Товариство?",a="Покійний Аптекар Берард записав, що місцеві мурлоки-Темноплавці мають затверділі пухлини з особливими властивостями. Товариство побачило в цих наростах перспективний складник для своїх досліджень, спрямованих на створення нової смертоносної чуми.",al={"аптекар берард","чума осяйного узмор'я","пухлина нової чуми"}},{q="Куди поділися місцеві мурлоки?",a="Під натиском Відступників, що зачищали узбережжя, плем'я Темноплавців перенесло свої головні табори із суходолу на Світанкові Острови посеред Озера Лордамер.",al={"де мурлоки сілверпайну","розташування віл фіна","мурлоки осяйного узмор'я"}}},fp="14,349,21.638.0,18.433.1,36.238.0,48.285.0,60.241.0,31.175.0"}
P.entries["subzone:shrine-of-aessina"] = {n="Святилище Аессіни",s="Святилище Аессіни — священна ельфійська пам'ятка в лісах південно-західного Ашенвалю, присвячена давньому духові лісу, природи й диких створінь. Воно лежить між Постом Маестри й Астранааром і лишається тихим прихистком серед дедалі гостріших прикордонних чвар.",h="Святилище Аессіни — священна ельфійська пам'ятка в лісах південно-західного Ашенвалю, присвячена давньому...",kw={"святилище аессіни","аессіна","дика богиня","святилище","ашенваль"},ang={["class:Druid"]="Давнє святилище на честь живого духу диких лісів має глибоке значення для тих, хто присвятив себе збереженню природної рівноваги Калімдору.",["race:NightElf"]="Для калдореїв святилище — уособлення століть гармонії з корінними духами Ашенвалю, якій тепер постійно загрожують чужі сили."},sec={{t="Святилище глибокого лісу",b="Святилище Аессіни, що сховалося на захід від Астранаару, вшановує таємничу Дику Богиню — утілення серця й духу глибоких лісів. Покоління нічних ельфів та їхніх лісових родичів шанували це тихе місце, єднаючись тут із природою далеко від гамірних доріг. Проте тепер, коли Орда проникає в Ашенваль, щоб рубати ліс і закріплюватися, мир у священних місцях по всьому краю став хитким."}},faq={{q="Хто така Аессіна?",a="Аессіна — шанований давній дух природи й Дикий Бог, пов'язаний із серцем незайманих лісів. Нічні ельфи й лісові створіння вшановують її як живу душу природи, втілення дикої пущі.",al={"лор аессіни","хто така аессіна","святилище богині аессіни"}},{q="Де розташоване Святилище Аессіни?",a="Святилище лежить на південному заході Ашенвалю, на південний захід від Посту Маестри й на захід від поселення Астранаар.",al={"розташування святилища аессіни","де святилище аессіни","знайти святилище аессіни"}},{q="Чому це місце важливе для нічних ельфів?",a="Святилище — давня свята обитель, присвячена лісовим духам. Такі місця безпосередньо пов'язують суспільство нічних ельфів і друїдські традиції з дикою природою Калімдору.",al={"важливість святилища аессіни","священне місце нічних ельфів"}}},fp="17,295,29.432.0,15.208.0,39.121.0,49.188.0"}
P.entries["subzone:shrine-of-the-dormant-flame"] = {n="Святиня Приспаного Полум'я",s="На найвищій вершині на північний захід від Долини Випробувань стоїть Святиня Приспаного Полум'я — відлюдне святилище, яке шанують шамани Орди. Під проводом його самотнього хранителя Телфа Джулама посвячувані здійснюють небезпечний підйом, щоб поспілкуватися зі стихією вогню й довести свою духовну майстерність.",h="На найвищій вершині на північний захід від Долини Випробувань стоїть Святиня Приспаного Полум'я — відлюдне...",kw={"святиня приспаного полум'я","шамани","вогонь","вогняний тотем","телф джулам","вершина","дуротар"},ang={["class:Shaman"]="Кожен молодий шаман з орків чи тролів має здійснити виснажливий підйом на цю скелю, щоб розпалити духовний зв'язок із вогнем і здобути свій Вогняний Тотем.",["faction:Horde"]="Схована в горах над Дуротаром, ця відлюдна святиня зберігає прадавні стихійні обряди, життєво важливі для духовного серця нової Орди."},sec={{t="Вершина випробування й полум'я",b="Щоб дістатися Святині Приспаного Полум'я, треба здолати вузьку звивисту стежку, що починається біля Річки Південної Люті на південно-західному краю її водозбору. Високо над червоними скелями Дуротару гірська вершина відкриває панорамний краєвид на околиці, та один хибний крок над прірвою означає певну смерть. У цьому тихому прихистку блукає Телф Джулам — самотній відлюдник, якому доручено наглядати за священними обрядами. Для майбутніх шаманів з орків і тролів, що проходять обряд Поклику Вогню, жаровня святині — горнило, де вони мають розпалити приспане вугілля жариною переможеного елементаля, доводячи, що здатні спілкуватися з руйнівними духами полум'я й шанувати їх."}},faq={{q="Як дістатися до Святині Приспаного Полум'я?",a="Стежка починається біля Річки Південної Люті, на південно-західному краю її водозбору, трохи на північний захід від Долини Випробувань. Вузька гірська стежка спіраллю обвиває вершину й веде просто нагору.",al={"як дістатися до святині приспаного полум'я","шлях до приспаного полум'я","піднятися на гору приспаного полум'я"}},{q="Чому ця святиня важлива для шаманів?",a="Святиня — священне місце, де шамани Орди вчаться розуміти стихію вогню й керувати нею. На шляху до Поклику Вогню новачки мусять піднятися на цю вершину, щоб приготувати обрядовий напій і розпалити приспану жаровню.",al={"призначення святині приспаного полум'я","чому шамани йдуть сюди","святиня поклику вогню"}},{q="Хто такий Телф Джулам?",a="Телф Джулам — самотній троль-відлюдник, хранитель святині. Він провадить молодих шаманів крізь випробування, варить вогняний напій, що пробуджує їхній духовний зір, і випробовує їхню рішучість.",al={"хто такий телф джулам","нпс приспаного полум'я","хранитель святині"}},{q="Що буде, коли розпалиш жаровню?",a="Шамани, що зібрали потрібні обрядові складники й здолали ворожого вогняного елементаля, кладуть його палаючу жарину в жаровню. Це пожертва, що доводить: вони мають досить сили й дисципліни, щоб приборкати непокірний дух полум'я.",al={"жаровня приспаного полум'я","розпалити полум'я","завдання жаровні святині"}}},fp="27,297,27.723.0,49.218.0,39.242.0,19.211.0,41.245.0"}
P.entries["subzone:shrine-of-the-fallen-warrior"] = {n="Святиня Полеглого Воїна",s="На відлюдному кряжі на захід від Перехрестя лежить Святиня Полеглого Воїна — тихий пам'ятник, з якого видно безкраї червоні савани Пусток. Тут стоїть кам'яний постамент з ініціалами «МК» і спочиває тіло полеглого орка-воїна, а оберігає це місце лагідний Цілитель Духів на ім'я Койтер.",h="На відлюдному кряжі на захід від Перехрестя лежить Святиня Полеглого Воїна — тихий пам'ятник, з якого видно...",kw={"святиня полеглого воїна","цілитель духів","койтер","пам'ятник","перехрестя","пустки"},ang={["class:Warrior"]="Воїни всіх рас часто приходять на цей пагорб у тихе паломництво, щоб віддати шану полеглому братові по зброї, який хоробро бився, перш ніж стати легендою.",["faction:Horde"]="Це самотнє місце спочинку в самому серці земель Орди втілює честь, обов'язок і жертовність, на яких тримаються шаманські й воїнські традиції Калімдору."},sec={{t="Тиха варта",b="Святиня Полеглого Воїна, що сховалася високо на пагорбах на північний захід від Перехрестя, — напрочуд урочистий прихисток серед пилу й небезпек Пусток. Щоб знайти її, мандрівникам доведеться піднятися звивистою стежкою на південний захід від вершини, аж до пологого кургану. На його верхівці стоїть різьблений кам'яний пам'ятник, на постаменті якого вирізьблено ініціали «МК». Перед ним спочиває закутий в обладунки орк-воїн, а вдень і вночі його стереже Цілитель Духів на ім'я Койтер. Тут не сурмлять бойові роги — лише тиша й роздуми на честь героя, що колись ходив землями Калімдору."},{t="Значення пам'ятника",b="У самому світі гри святиня — незгасна шана полеглому герою Орди, чия душа перебуває під опікою духів. Поза ним пам'ятник — щира данина, яку художники гри створили на честь Мішеля Койтера, улюбленого ілюстратора, що пішов із життя під час розробки світу. Спочилий воїн точно повторює власного бета-персонажа Койтера, Твінкрузера, — і так його присутність назавжди закарбована під відкритим небом Калімдору."}},faq={{q="Де розташована Святиня Полеглого Воїна?",a="Святиня стоїть на вершині пагорба на захід від Перехрестя на півночі Пусток. Щоб дістатися туди, знайдіть підніжжя кряжа на південний захід від узвишшя й ідіть звивистою стежкою вгору, до трав'янистого горбка.",al={"розташування святині","де святиня","як дістатися до святині полеглого воїна"}},{q="Хто той орк, що лежить на постаменті?",a="У грі він уособлює шанованого полеглого воїна. Насправді ж його створено за образом Твінкрузера — орка-воїна, яким грав покійний художник Blizzard Мішель Койтер на ранніх етапах розробки.",al={"хто мертвий орк","особа полеглого воїна","твінкрузер"}},{q="Що означає вирізьблене на камені «MK»?",a="Рунічні ініціали «MK» вшановують Мішеля Койтера — провідного художника, що помер у 2004 році під час створення світу гри.",al={"що означає мк","ініціали мк","літери на камені"}},{q="Хто той Цілитель Духів, що стоїть біля святині?",a="Цілителя Духів звуть Койтер. На відміну від звичайних Цілителів Духів, яких бачать лише духи загиблих, Койтер стоїть на чатах, і його добре бачать живі мандрівники, що піднімаються на пагорб.",al={"цілитель духів койтер","ангел біля святині","хто привид"}},{q="Чи пов'язані з цією святинею якісь завдання?",a="Ні. Святиня Полеглого Воїна не входить до жодного ланцюжка завдань чи протистояння фракцій. Це лише урочисте місце роздумів, пам'яті й шани.",al={"завдання святині","завдання полеглого воїна","чи є тут завдання"}}},fp="28,327,14.608.0,27.487.0,50.210.0,37.199.0,46.121.0,52.209.0,49.162.0"}
P.entries["subzone:si-7-stormwind-city"] = {n="SI:7 (Стормвінд)",s="Захований у східному куті Старого Міста, цей непоказний кам'яний маєток містить штаб SI:7 — елітної служби розвідки й шпигунства Королівства Стормвінд. За його важкими дверима очільник шпигунів Майстер Матіас Шоу та його старші агенти тихо стежать за загрозами королівству й керують таємними агентами по всій країні.",h="Захований у східному куті Старого Міста, цей непоказний кам'яний маєток містить штаб SI:7 — елітної служби...",kw={"si:7","розвідка","матіас шоу","старе місто","шпигуни","стормвінд"},ang={["class:Rogue"]="Для розбійників Альянсу будівля SI:7 — важливий професійний осередок, де можна пройти поглиблене навчання, придбати отрути й отримати таємні доручення просто від очільника шпигунів Матіаса Шоу.",["faction:Alliance"]="Як невидимий фундамент оборони Стормвінда, розвідувальна мережа SI:7 забезпечує військо Альянсу важливими відомостями про загрози трону."},sec={{t="Серце шпигунства королівства",b="To the casual passerby in Old Town, this fortified stone structure looks little different from a standard manor or military barracks. In truth, it serves as the nerve center for Stormwind Intelligence, Section 7. Directed by Master Mathias Shaw, SI:7 gathers intelligence, conducts surveillance, and executes covert operations to protect the kingdom from subversion. While the city guard patrols the open cobblestones and the Royal Guard defends Stormwind Keep, SI:7 works in the margins, training handlers and dispatching stealthy operatives against foreign enemies, saboteurs, and domestic unrest alike."},{t="Пильне око в тінях",b="Король Варіан Рінн загадково зник, а Братство Дефіас сіє хаос у Вестфолі й Сутінколіссі, тож у штабі безупинно вирує таємна робота. Донесення стікаються сюди від глибоко законспірованих розвідників з усіх людських земель. У підвалах і тренувальних залах, обвішаних зброєю, відточують смертоносні прийоми й роздають завдання, щоб знешкодити загрози задовго до того, як вони дістануться тронної зали короля-хлопчика."}},faq={{q="Що таке SI:7?",a="SI:7 — це Розвідка Стормвінда, Відділ 7. Це найкраща служба таємного шпигунства, розвідки й ліквідацій на службі корони Стормвінда.",al={"що таке сі:7","хто такі сі:7","значення сі:7"}},{q="Хто очолює SI:7 у Стормвінді?",a="Організацію очолює з цієї будівлі Майстер Матіас Шоу. Він наглядає за всіма польовими завданнями, мережами розвідки й стратегічною розвідкою для корони.",al={"лідер сі:7","бос сі:7","хто керує сі:7"}},{q="Де в місті розташована ця будівля?",a="Штаб — у Старому Місті, на південно-східному краю кварталу, біля каналу й тренувальних дворів.",al={"де сі:7","розташування сі:7","як дістатися до сі:7"}},{q="Чому SI:7 так цікавиться Вестфолом?",a="SI:7 стежить за підривною діяльністю по всіх землях Стормвінда, а Братство Дефіас — найнебезпечніше повстання в королівстві. Люди Шоу розставили по Вестфолу агентів під прикриттям і розвідників, щоб вистежити проводирів Братства й перерізати його шляхи постачання.",al={"братство дефіас сі:7","чому сі:7 стежить за дефіасом"}}},fp="21,345,32.605.0,29.438.1,13.159.0,28.175.0,43.127.0,38.297.0"}
P.entries["subzone:silver-stream-mine"] = {n="Шахта Срібного Потоку",s="Шахта Срібного Потоку — вичерпана дворфійська копальня на півночі Лох Модану, між Станцією Алґаз і Каменетесною Греблею. Колись багата срібна жила королівства Айронфордж, вироблену порожнину перетворили на склад Ліги Шахтарів, доки її не заполонила паскудь. Сьогодні в тунелях засіли кобольди Тунельні Пацюки, що ховають викрадене спорядження й рідкісні мінеральні дивовижі.",h="Шахта Срібного Потоку — вичерпана дворфійська копальня на півночі Лох Модану, між Станцією Алґаз і...",kw={"шахта срібного потоку","кобольди","ліга шахтарів","заряджені самоцвіти розлому","лох модан"},ang={["class:Mage"]="Учні магів спускаються в небезпечні тунелі, повні кобольдів, саме по Заряджені Самоцвіти Розлому — незамінний інгредієнт для ритуальних шат.",["race:Dwarf"]="Для дворфів Шахта Срібного Потоку — прикра втрата здобутого тяжкою працею господарства: незграбні кобольди тепер паскудять шановний склад айронфорджської Ліги Шахтарів."},sec={{t="Від багатої жили до складу",b="Колись Шахта Срібного Потоку давала багато цінної руди, щедро поповнюючи запаси срібла Айронфорджа. З часом дворфійські кайла вгризлися так глибоко, що вичерпали головні жили, і розлогі зали перетворилися на порожній підземний комплекс. Замість кидати здобуті тяжкою працею виробки, Ліга Шахтарів обернула шахти на надійний склад для інструментів, ящиків рудокопів і спорядження з усього краю. Це також єдине відоме джерело рідкісних Заряджених Самоцвітів Розлому, по які приходять допитливі знавці таємної магії, шукаючи тонких кравецьких інгредієнтів."},{t="Навала кобольдів",b="Тихий склад недовго лишався безпечним. Агресивні кобольди Тунельні Пацюки, яких привабив запах занедбаних інструментів, воску свічок і забутих підземних щілин, хмарою ринули в шахти. Доглядачів із Ліги Шахтарів швидко вигнали на холод Лох Модану. Тепер кобольди з шаленим запалом стережуть вкрадені дворфійські ящики, а біля задніх входів забуто лежать старі розтрощені орківські катапульти й вози — мовчазні нагадування про давніші прикордонні сутички."}},faq={{q="Для чого спершу використовували Шахту Срібного Потоку?",a="Спершу це була прибуткова срібна копальня дворфів Айронфорджа. Коли жили вичерпалися, Ліга Шахтарів Айронфорджа перетворила порожні підземні зали на склад інструментів і приладдя для розкопок.",al={"що таке шахта срібного потоку","історія срібного потоку","навіщо збудували срібний потік"}},{q="Хто нині займає шахту?",a="Шахту цілком заполонили кобольди-Тунельні Пацюки. Вони прогнали дворфів-доглядачів і тепер стережуть тунелі, ховаючи покинуті ящики Ліги й вишкрібаючи останні рештки руди.",al={"хто в шахті срібного потоку","моби срібного потоку","що всередині срібного потоку"}},{q="Навіщо маги ходять до Шахти Срібного Потоку?",a="Шахта — єдине відоме джерело Заряджених Самоцвітів Розлому. Ці непостійні камені, чутливі до магії, шукають чарівники Альянсу, щоб ткати могутні зачаровані мантії.",al={"завдання магів срібний потік","заряджені самоцвіти розлому","мантії магів срібного потоку"}},{q="Що за зруйновані катапульти за шахтою?",a="За шахтою стоять розбиті оркські вози й зруйновані катапульти — вивітрені рештки давніших воєн, що колись загрожували шляхам між Лох Моданом і північними гірськими перевалами.",al={"орківські вози за срібним потоком","зламані катапульти лох модан","облогові машини орди лох модан"}}},fp="18,394,31.556.0,20.490.0,52.233.0,32.202.0,42.169.0,46.195.0"}
P.entries["subzone:silverwind-refuge"] = {n="Притулок Срібного Вітру",s="Притулок Срібного Вітру — тихе поселення нічних ельфів у південно-центральному Ашенвалі, трохи на північ від Озера Містраль. Під захистом Вартових і союзних водяних елементалів воно гостинно приймає мандрівників на лісових стежках.",h="Притулок Срібного Вітру — тихе поселення нічних ельфів у південно-центральному Ашенвалі, трохи на північ від...",kw={"притулок срібного вітру","озеро містраль","корчма","травництво","вартові","ашенваль"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що перетинають Ашенваль, Притулок Срібного Вітру — надійний табір, де можна відпочити, поповнити припаси й підучити ремесла, не йдучи аж до Астранаару.",["profession:Herbalism"]="Притулок — важлива зупинка в Ашенвалі для збирачів: тут можна навчитися травництва просто на місці, серед багатої флори Озера Містраль."},sec={{t="Лісовий прихисток",b="Притулок Срібного Вітру, що лежить між спокійними водами Озера Містраль і Озером Ірисів на півночі, — поряд з Астранааром один із головних перевалочних пунктів нічних ельфів у центральному Ашенвалі. Тут є затишна корчма, ремісники та наставники, які навчають мандрівників травництва, алхімії, білування й полювання. Під охороною стійких Вартових і місцевих духів води цей прихисток — мирна зупинка для союзників, що мандрують тінистим прадавнім лісом."}},faq={{q="Хто тримає Притулок Срібного Вітру?",a="Притулок Срібного Вітру — поселення Альянсу, яке збудували й утримують нічні ельфи. Його пильно охороняють Вартові, а також водяні елементалі, що допомагають берегти ці спокійні угіддя.",al={"хто володіє притулком срібного вітру","чи срібний вітер альянсу чи орди","хто живе в срібному вітрі"}},{q="Де розташований Притулок Срібного Вітру?",a="Він на півдні центрального Ашенвалю, просто на північ від Озера Містраль і на південь від Озера Ірисів.",al={"розташування притулку срібного вітру","де притулок срібного вітру","як дістатися до срібного вітру"}},{q="Які послуги є в притулку?",a="Мандрівники знайдуть тут корчму, крамарів і наставників травництва, алхімії, білування та мисливських умінь.",al={"що в притулку срібного вітру","наставники срібного вітру","торговці срібного вітру"}}},fp="17,253,18.477.0,31.191.0,35.107.0,38.147.0"}
P.entries["subzone:silverwing-grove"] = {n="Гай Срібнокрилих",s="Гай Срібнокрилих, що сховався в південно-центральному Ашенвалі біля Озера Впалого Неба, — місце збору Вартових Срібнокрилих. З цієї укріпленої улоговини воїни нічних ельфів збирають сили Альянсу, щоб відкинути лісорубів клану Бойової Пісні, які прорубуються крізь ліс.",h="Гай Срібнокрилих, що сховався в південно-центральному Ашенвалі біля Озера Впалого Неба, — місце збору...",kw={"гай срібнокрилих","вартові срібнокрилих","ущелина бойової пісні","альянс","ашенваль"},ang={["faction:Alliance"]="Гай — головне місце збору для героїв Альянсу, які готуються вступити в криваві сутички в Ущелині Бойової Пісні.",["race:NightElf"]="Для калдореїв Гай Срібнокрилих — утілення непохитної рішучості зупинити нищення священних дерев сокирами клану Бойової Пісні."},sec={{t="Передова лісової війни",b="Гай Срібнокрилих, захований під смарагдовими кронами на південний захід від Застави Срібнокрилих, — важливий військовий плацдарм Вартових Срібнокрилих. Це не тихий лісовий притулок, а бойове серце запеклої боротьби нічних ельфів за землю проти лісорубень Орди в Ущелині Бойової Пісні. Тут збираються високі офіцери Альянсу, припаси й розвідники: звідси організовують сутички й скликають героїв боронити прадавній Ашенваль від орківської експансії."}},faq={{q="Для чого потрібен Гай Срібнокрилих?",a="Гай Срібнокрилих — плацдарм Вартових Срібнокрилих. Тут військо нічних ельфів та їхні союзники з Альянсу організовують опір вирубці лісу кланом Бойової Пісні й вирушають у нескінченне протистояння в Ущелині Бойової Пісні.",al={"чому тут гай срібнокрилих","що таке гай срібнокрилих","призначення гаю срібнокрилих"}},{q="Де розташований Гай Срібнокрилих?",a="Він на півдні центрального Ашенвалю, на південний захід від Застави Срібнокрилих і трохи на захід від Озера Впалого Неба.",al={"розташування гаю срібнокрилих","де гай срібнокрилих","як знайти гай срібнокрилих"}},{q="Хто діє з Гаю Срібнокрилих?",a="У гаю стоять Вартові Срібнокрилих разом із військовими командирами Альянсу — зокрема Бригадним Генералом Альянсу, — інтендантами й офіцерами на кшталт Вартової Фарсонг, які керують боротьбою з Ордою.",al={"хто в гаю срібнокрилих","нпс гаю срібнокрилих","хто керує гаєм срібнокрилих"}},{q="Чи можуть гравці Орди увійти до Гаю Срібнокрилих?",a="Ні. Гай — діюча військова застава, повна ворожих вартових Альянсу, які одразу нападуть на будь-яких членів Орди, що наблизяться.",al={"чи ворожий гай срібнокрилих","чи може орда в гай срібнокрилих","орда гай срібнокрилих"}}},fp="16,273,28.504.0,40.250.0,34.116.0,37.228.0,41.159.0"}
P.entries["subzone:silverwing-outpost"] = {n="Застава Срібнокрилих",s="Застава Срібнокрилих — укріплений гарнізон нічних ельфів у південно-центральному Ашенвалі, на схід від Річки Фалфаррен. Під командуванням Дуріель Мунфаєр це найсхідніший оплот Альянсу проти Орди в спірному лісі.",h="Застава Срібнокрилих — укріплений гарнізон нічних ельфів у південно-центральному Ашенвалі, на схід від Річки...",kw={"застава срібнокрилих","дуріель мунфаєр","вартові срібнокрилих","торек","фронт","ашенваль"},ang={["faction:Alliance"]="Застава Срібнокрилих — ваш важливий передовий редут на ордівському березі річки, що стримує розширення орків від Застави Розщепленого Дерева.",["faction:Horde"]="Для Орди застава — нестерпна скалка в боці Застави Розщепленого Дерева, що перекриває вам шляхи пересування й постачання південним Ашенвалем."},sec={{t="На схід від Фалфаррену",b="Застава Срібнокрилих, що лежить на південний захід від Застави Розщепленого Дерева й трохи на північ від кордону з Пустками, займає вкрай небезпечну позицію. Вона стоїть на східному березі Річки Фалфаррен — на запекло спірній території, яку патрулює Орда, — і прикриває собою володіння нічних ельфів у глибині лісу. Дуріель Мунфаєр та її Вартові Срібнокрилих перебувають у постійній облозі: орки неподалік сповнені рішучості цілком вигнати нічних ельфів із цього краю."},{t="Нескінченний фронт",b="Сутички довкола Застави Срібнокрилих — одні з найзапекліших в Ашенвалі. Бойові загони орків із Застави Розщепленого Дерева, як-от нападники під проводом Торека, раз у раз влаштовують засідки під стінами гарнізону. Для Орди знешкодити заставу конче необхідно, щоб убезпечити дорогу й розширити заготівлі без постійної загрози контрударів Вартових."}},faq={{q="Де розташована Застава Срібнокрилих?",a="Вона на півдні центрального Ашенвалю — на південний захід від Застави Розщепленого Дерева, на північ від кордону з Пустками й на східному боці Річки Фалфаррен.",al={"розташування застави срібнокрилих","де застава срібнокрилих","застава срібнокрилих на мапі"}},{q="Хто командує Заставою Срібнокрилих?",a="Заставою командує Дуріель Мунфаєр — офіцерка нічних ельфів, що очолює Вартових Срібнокрилих, які боронять східні краї лісу.",al={"лідер срібнокрилих","хто очолює заставу срібнокрилих","дуріел місячний вогонь"}},{q="Чому Орда так завзято атакує цю заставу?",a="Застава Срібнокрилих стоїть просто на східному боці Річки Фалфаррен, неподалік від Застави Розщепленого Дерева. Звідси Вартові можуть перерізати шляхи постачання Орди й безпосередньо загрожувати оркським справам в Ашенвалі.",al={"чому нападати на срібнокрилих","інтерес орди до срібнокрилих","сплінтертрі проти срібнокрилих"}},{q="Хто такі Вартові Срібнокрилих?",a="Вартові Срібнокрилих — войовничий орден воїтельок і мисливиць нічних ельфів, що присвятили себе захисту Ашенвалю від вторгнень — насамперед від лісозаготівельних таборів і бойових загонів Орди, що підступають дедалі ближче.",al={"що таке срібнокрилі","лор вартових срібнокрилих","фракція срібнокрилих"}}},fp="18,248,21.501.0,18.384.1,36.150.0,32.142.0,55.217.0,33.213.0"}
P.entries["subzone:sishir-canyon"] = {n="Каньйон Сішир",s="Каньйон Сішир — дика ущелина в Горах Кам'яного Кігтя, що прорізає шлях на схід крізь скелясті височини. Тут кишать жахливі глибокомохові павуки, а все довкола обснуване павутинням; це небезпечний підхід до Руїн Ельдре'тара. Ті, хто зважиться пройти його заплутаними глибинами, муситимуть мати справу з отруйними павуками та їхньою матір'ю виводку.",h="Каньйон Сішир — дика ущелина в Горах Кам'яного Кігтя, що прорізає шлях на схід крізь скелясті височини.",kw={"каньйон","павуки","бесселет","павутиння","руїни ельдре'тара","гори кам'яного кігтя"},ang={["class:Hunter"]="Небезпечне павутиння та отруйні глибокомохові павуки роблять Каньйон Сішир суворим випробуванням для мисливців, які вистежують і ловлять диких звірів у тісноті ущелини.",["race:NightElf"]="Захоплений павуками каньйон відрізає легкий і безпечний шлях до Руїн Ельдре'тара — спадщини предків, тож вартовим і вченим калдореїв доводиться пробиватися крізь густі павучі гнізда, щоб дістатися свого минулого."},sec={{t="Обснований прохід",b="Каньйон Сішир, що відгалужується від гірських доріг хребта Кам'яного Кігтя, — підступний природний коридор до прадавніх Руїн Ельдре'тара. Це зовсім не тиха гірська стежка: ущелину геть заполонили глибокомохові павуки. Їхні липкі шовкові полотнища та грона яєчних коконів укривають кам'янисту землю й скельні стіни, перетворюючи яр на живе гніздо. Мандрівники й вартові, що прямують до ельфійських руїн за ним, мусять прорубувати собі шлях крізь рої лютих павуків-ткачів."},{t="Володіння Бесселет",b="У найглибшому закутку каньйону чатує Бесселет — величезна й смертоносна матір виводку глибокомохових павуків. Її отрута й жахливі розміри наводять страх на кожного, хто намагається очистити прохід. Місцеві сили в Кам'яному Кігті насторожено стежать за каньйоном і попереджають шукачів пригод: хто полізе в обснувані закутки, зіткнеться не лише з розрізненими павуками, а й із верховним хижаком, що люто стереже свій виводок."}},faq={{q="Що таке Каньйон Сішир?",a="Каньйон Сішир — ущелина в Горах Кам'яного Кігтя, де кишать павуки: вона в'ється від головних гірських стежок до давніх Руїн Ельдре'тару.",al={"де каньйон сішир","розташування каньйону сішир"}},{q="Хто живе в каньйоні?",a="Каньйон цілком захопили хижі павуки Глибокого Моху. Вони вкрили яр густим павутинням і коконами з яйцями й полюють на все, що потрапляє в їхні володіння.",al={"монстри каньйону сішир","павуки каменекігтя"}},{q="Хто така Бесселет?",a="Бесселет — грізна павучиха-матріарх, що живе глибоко в Каньйоні Сішир. Вона очолює виводок Глибокого Моху й становить найбільшу загрозу для мандрівників, що проходять цим краєм.",al={"бесселет","гігантський павук каньйону сішир"}},{q="Куди веде Каньйон Сішир?",a="Якщо йти каньйоном на схід, вийдете просто до Руїн Ельдре'тару — давньої пам'ятки нічних ельфів високо в горах.",al={"що в кінці каньйону сішир","шлях крізь каньйон сішир"}}},fp="13,352,15.507.0,18.412.0,22.148.0,34.180.0,17.178.0,30.134.0"}
P.entries["subzone:skittering-dark"] = {n="Шурхотлива Пітьма",s="Шурхотлива Пітьма — покинута шахта й темна лісова улоговина на заході Срібнолісся. Її заполонили агресивні велетенські павуки, і печера та ліси довкола густо обплетені павутинням і небезпечні для необачних звірів і мандрівників.",h="Шурхотлива Пітьма — покинута шахта й темна лісова улоговина на заході Срібнолісся.",kw={"шурхотлива пітьма","павуки","шахта","кретіс","срібнолісся"},ang={["faction:Horde"]="Мандрівникам Орди в Срібноліссі варто це знати: павуки Шурхотливої Пітьми влаштовують засідки на необачну здобич, що забрідає з довколишніх лісів до їхніх обплетених павутинням лігв."},sec={{t="Обплетена павутинням улоговина",b="Шурхотлива Пітьма, що сховалася серед пагорбів трохи на схід від західного узбережжя Потоку Північного Припливу, колись була діючою шахтою. Сьогодні її штреки геть задушені павутинням і стали розлогим гніздом велетенських павуків. Біля входу никає тіниста прядильниця Кретіс, а павуки полюють на все, що підійде надто близько."}},faq={{q="Що таке Шурхотлива Пітьма?",a="Це покинута копальня на заході Срібнолісся, яку цілком заполонили велетенські павуки. Печери й довколишні дерева густо обплутані липким павутинням і кишать хижими павуками.",al={"шурхотлива пітьма шахта","що це за шахта","павуча печера сілверпайн"}},{q="Хто верховодить павуками в копальні?",a="Єдиного володаря цього виводку не відомо. Найстрашніший серед павуків — Кретіс Шедовспіннер, рідкісний і небезпечний прядильник, що нишпорить у копальні й довкола неї.",al={"бос павуків","бос шурхотливої пітьми","матріарх"}},{q="Де розташована Шурхотлива Пітьма?",a="Вона сховалася серед пагорбів на заході Срібнолісся, трохи на схід від узбережжя, відомого як Потік Північного Припливу.",al={"розташування шурхотливої пітьми","як знайти шурхотливу пітьму"}}},fp="15,240,15.324.0,28.197.0,34.159.0,37.117.0"}
P.entries["subzone:skull-rock"] = {n="Череп-скеля",s="Череп-скеля — печера в східних прибережних скелях Дуротару, просто на схід від Оргріммара. Вона служить укріпленим ковеном демонічного культу Палаючого Клинка просто під носом у столиці.",h="Череп-скеля — печера в східних прибережних скелях Дуротару, просто на схід від Оргріммара.",kw={"череп-скеля","печера","культисти","палаючий клинок","ґазз'уз","чорнокнижник","дуротар"},ang={["class:Warlock"]="Темні мистецтва, що практикують у Череп-скелі, показують нестримне поширення демонічного впливу, який Орда Тралла прагне викорінити й узяти під контроль.",["faction:Horde"]="Очистити Череп-скелю від культистів украй важливо, щоб убезпечити прибережні підступи до Дуротару й захистити Оргріммар від підривної діяльності зсередини."},sec={{t="Лігво культистів",b="Схована під скелями північно-східного Дуротару, Череп-скеля — одна з найнебезпечніших твердинь культу Палаючого Клинка в цьому краї. Темні культисти, орки-шанувальники Скверни та прикликачі збираються глибоко у звивистих тунелях, щоб практикувати демонічні мистецтва й плести змови проти молодої Орди. Осередок очолює небезпечний чорнокнижник Ґазз'уз, чиї дії безпосередньо загрожують сусідній брамі Оргріммара та мандрівникам на східному узбережжі."}},faq={{q="Що таке Череп-скеля?",a="Череп-скеля — система печер на північному сході Дуротару, на узбережжі. Тут засіли сектанти Палаючого Клинка, що під її природним прикриттям плетуть змови проти Орди Тралла.",al={"печера череп-скеля","де череп-скеля","що в череп-скелі"}},{q="Хто тримає Череп-скелю?",a="Печеру заполонив культ Палаючого Клинка на чолі з орком-чорнокнижником Ґазз'узом, що засів у найглибшій залі печери.",al={"хто веде череп-скелю","хто керує череп-скелею","бос череп-скелі"}},{q="Чому ця печера турбує Орду?",a="Вона так близько до Оргріммара, що це серйозна загроза безпеці. Палаючий Клинок прагне підточити нове королівство Тралла й знову кинути орків у рабство до демонів.",al={"чому очищати череп-скелю","чому череп-скеля небезпечна"}}},fp="10,195,17.478.0,19.183.0,24.118.0,40.175.0"}
P.entries["subzone:slag-pit"] = {n="Шлакова Яма",s="Шлакова Яма — розлогі підземні копальні всередині Казана в Палючій Ущелині. Ними керують безжальні погоничі й работорговці Темного Заліза, а у вогняних тунелях під тінню Гори Блекрок гарують підневільні робітники. Непроханим гостям доведеться мати справу не лише з ворожими дворфами-наглядачами, а й із ненажерливими інцендозаврами, що нишпорять на нижніх рівнях.",h="Шлакова Яма — розлогі підземні копальні всередині Казана в Палючій Ущелині.",kw={"шлакова яма","казан","палюча ущелина","копальня","темне залізо","інцендозаври"},ang={["profession:Mining"]="Глибокі шахти Шлакової Ями врізаються просто в багате на мінерали черево Палючої Ущелини, тож тут можна розжитися добірною рудою — прибутково, хоч і надзвичайно небезпечно.",["race:Dwarf"]="Для дворфів Айронфорджа жорстокість работорговців Темного Заліза в Шлаковій Ямі — суворе нагадування про гірку прірву між кланами."},sec={{t="Підземна каторга",b="Шлакова Яма, вирубана в глибинах Казана, — невтомна промислова машина дворфів Темного Заліза в Палючій Ущелині. Вдень і вночі поневолених робітників женуть видобувати багаті руди й мінерали під батогом жорстоких наглядачів і погоничів. Тут важко й задушливо: усе заполонили пекуча спека, їдкий пил і брязкіт залізних кайл. Дворфи Темного Заліза тримають на своїх копальнях безжальну дисципліну й люто відбивають будь-яке втручання ззовні в постачання до Глибин Блекрок."},{t="Глибини ями",b="Окрім жорстокості работорговців, самі тунелі смертельно небезпечні і для робітників, і для непроханих гостей. На нижніх рівнях копалень земля розступається й відкриває розпечені печери, де живуть інцендозаври — люті рептилії, споконвічні мешканці вогняного підземелля. Попри постійну загрозу опинитися в пащі цих підземних хижаків, господарі з Темного Заліза женуть своїх робітників дедалі глибше в скелю, байдужі до життів, які це забирає."}},faq={{q="Де розташована Шлакова Яма?",a="Шлакова Яма — глибоко в Казані, величезному кратері розкопок у центрі Палючої Ущелини. Її тунелі розгалужуються просто під наземними копальнями.",al={"розташування шлакової ями","де шлакова яма","як дістатися до шлакової ями"}},{q="Хто тримає Шлакову Яму?",a="Копальнею цілком заправляє клан Темного Заліза. Рабовласники й наглядачі Темного Заліза патрулюють штольні, тримаючи всіх у жорсткій дисципліні й змушуючи бранців копати цілодобово.",al={"хто керує шлаковою ямою","фракція шлакової ями","темне залізо шлакова яма"}},{q="Чому раби нападають на зайд?",a="Поневолені робітники від природи не ворожі до чужинців, але страх перед господарями з Темного Заліза в них глибокий. Якщо поряд нападуть на рабовласника чи наглядача, перелякані робітники кинуться його захищати, щоб уникнути жорстокої кари.",al={"чому раби нападають","ворожі раби","раби-робітники агресивні"}},{q="Хто живе в Шлаковій Ямі?",a="Окрім дворфів Темного Заліза та їхніх рабів, у найглибших куточках ями кишать інцендозаври — агресивні ящероподібні хижаки з вогняною лускою, що нишпорять підземними тунелями.",al={"монстри шлакової ями","інсендозаври","звірі шлакової ями"}}},fp="8,370,17.539.0,17.505.0,30.181.0,26.185.0,42.256.0,36.197.0"}
P.entries["subzone:slaughter-hollow"] = {n="Лощина Різанини",s="Лощина Різанини — відлюдне огряче городище, заховане серед засніжених висот Гір Альтерак. Ним володіє брутальний клан Трощихребтів, і це радше грубий табір, ніж жваве поселення. Мандрівникам нема чого сюди потикатися, хіба що вони полюють на огрів або досліджують замерзлі гірські перевали.",h="Лощина Різанини — відлюдне огряче городище, заховане серед засніжених висот Гір Альтерак.",kw={"лощина різанини","альтерак","огри","хребтоломи","різз лусболт","бранці"},ang={["race:Gnome"]="Прикрий полон Різза Лусболта в Трощихребтів — суворе застереження для винахідників і розвідників, які блукають перевалами Альтерака непідготовленими."},sec={{t="Лігво огрів",b="Лощина Різанини, захована високо в горах на межі Гілсбреда й Альтерака, править за табір місцевим огрям-Трощихребтам. Як і безліч інших огрячих городищ на нагір'ї, вона завалена саморобними вогнищами, обгризеними кістками й грубими курінями. Тоді як за інші огрячі лігва в горах раз у раз спалахують сутички через землю чи вкрадені припаси, Лощина Різанини здебільшого лишається тихою — великі військові походи обходять її стороною."},{t="Бранці й мандрівники",b="Через свою відлюдність городище часом стає в'язницею для бідолашних бранців, схоплених на гірських стежках. Між мандрівниками ходять чутки про нещасного гнома на ім'я Різз Лусболт, що опинився тут замкненим у грубій клітці й намагається торгуватися з кожним перехожим. Таким нещасним бранцям рідко щастить устояти перед апетитом клану Трощихребтів."}},faq={{q="Що таке Лощина Різанини?",a="Лощина Різанини — табір огрів у Горах Альтерак, де живе клан Трощихребтів. Тут примітивні житла-кургани й вогнища, звичні для гірських огрських поселень.",al={"лор лощини різанини","що це за місце","лощина різанини гілсбрад"}},{q="Хто живе в Лощині Різанини?",a="У лощині живуть лише огри-Трощихребти — той самий клан, що тримає сусідні руїни Міста Альтерак і різні довколишні застави.",al={"хто тут","моби лощини різанини","хто контролює лощину різанини"}},{q="Чи є тут завдання?",a="Жодне офіційне завдання не посилає шукачів пригод просто до Лощини Різанини. Це здебільшого відлюдне лігво, на яке натрапляють, досліджуючи гори.",al={"завдання лощини різанини","чи є завдання в лощині різанини","навіщо йти сюди"}},{q="Хто той гном, що сидить тут у клітці?",a="У клітці в лощині тримають гнома на ім'я Різз Лусболт: він пропонує свій крам кожному, хто його знайде.",al={"різз лусболт","гном у клітці","торговець лощини різанини"}}},fp="16,307,14.439.0,22.381.0,25.183.0,30.145.0,26.151.0,29.112.0"}
P.entries["subzone:slaughtered-lamb"] = {n="Зарізане Ягня",s="Захована в Кварталі магів Стормвінда, таверна «Зарізане Ягня» здається лише тихим і сумнівним шинком. Але під її підлогою розлогі катакомби ховають святилище й тренувальні зали заборонених чорнокнижників Альянсу.",h="Захована в Кварталі магів Стормвінда, таверна «Зарізане Ягня» здається лише тихим і сумнівним шинком.",kw={"зарізане ягня","таверна","чорнокнижники","квартал магів","зардет","стормвінд"},ang={["class:Warlock"]="Катакомби внизу — ваш головний прихисток у Стормвінді: тут наставники класу, обряди підкорення демонів і завдання, без яких не опанувати темних мистецтв.",["faction:Alliance"]="Хоча Альянс стоїть за Світло й порядок, «Зарізане Ягня» відкриває мовчазну готовність королівства терпіти темну магію у своїй тіні."},sec={{t="Тонке прикриття",b="На поверхні «Зарізане Ягня» не пропонує нічого, крім темних кутків і нечисленних відвідувачів, яких обслуговує шинкар Джарел Мур, що радить випадковим гостям триматися подалі від тіней. І це попередження буквальне. Спустившись задніми ходами, можна знайти підземний комплекс склепів і кіл виклику, де людські чорнокнижники та їхні колеги, що перебралися сюди з Каз Модану, відкрито вивчають таємниці скверни, сховавшись від несхвальних очей Церкви Святого Світла й Кірін-Тору."},{t="Рахунок вельможі",b="Тримати осередок скверни в серці столиці — постійний ризик. Коли Лорд Баурлес К. Вішок дізнався про чорнокнижників у підвалі, він пригрозив підняти Дім Вельмож і звернутися до трону з вимогою повного розслідування. Насправді ж аристократ просто хотів відкрутитися від руйнівного рахунку за випивку. Перш ніж його галас привернув справжню увагу, Зардет із Чорного Кігтя влаштував так, що Вішок випив смертельне зілля, — і назавжди заткнув рота пройдисвітові, зберігши таємниці сховку."}},faq={{q="Що насправді відбувається під «Зарізаним Ягням»?",a="Катакомби під таверною — таємне святилище чорнокнижників Стормвінда. Знавці демонології й тіньової магії збираються там, щоб навчати учнів, викликати демонів і практикувати мистецтва Скверни, заборонені на вулицях нагорі.",al={"що під зарізаним ягням","підвал зарізаного ягняти","хто в зарізаному ягняті"}},{q="Чи знає міська варта Стормвінда про чорнокнижників?",a="Таверна тримається на хиткій завісі правдоподібного заперечення. Церква Святого Світла й Академія Магів глибоко не довіряють магії Скверни, тож ковен мусить діяти потай і рішуче затикати рота кожному, хто погрожує викрити його перед королівською владою.",al={"чи знає варта про чорнокнижників","чому чорнокнижників не арештовують","чи зарізане ягня незаконне"}},{q="Хто такий лорд Вішок і що з ним сталося?",a="Лорд Баурлес К. Вішок — вельможа й завсідник таверни, що викрив чорнокнижників, які ховаються внизу. Він здійняв галас у Домі Вельмож і домагався повного розслідування, сподіваючись переконати короля закрити заклад.",al={"баурлс вішок","доля лорда вішока","хто такий вішок"}},{q="Чому сюди приходять гноми-чорнокнижники?",a="After the fall of Gnomeregan, its warlock masters relocated to Ironforge, where Magni keeps a careful watch on them. Lago Blackwrench sends novices to Gakin the Darkbinder in the Slaughtered Lamb for training.",al={"гноми-чорнокнижники стормвінд","чорнокнижники каз модану"}}},fp="16,244,15.486.0,15.511.1,49.240.0,54.287.0,47.236.1,32.209.0"}
P.entries["subzone:slither-rock"] = {n="Звивиста Скеля",s="Звивиста Скеля — відлюдна печера в далеких північно-східних скелях Палаючих Степів, за небезпечним Шляхом Крил Жаху. Це самотній прихисток Сайруса Терепентуса, гострого на язик чорного драконорода з власними прихованими намірами.",h="Звивиста Скеля — відлюдна печера в далеких північно-східних скелях Палаючих Степів, за небезпечним Шляхом...",kw={"звивиста скеля","сайрус терепентус","драконород","палаючі степи","печера"},sec={{t="Відлюдна печера",b="Звивисту Скелю, сховану серед випалених скель за Шляхом Крил Жаху, легко не помітити посеред вогняних пустирів Палаючих Степів. Далеко від гуркітливих кузень і орчих ватаг Шпиля Блекрок у цій віддаленій печері живе самотній чорний драконород Сайрус Терепентус. Хоча драконороди зазвичай — люто віддані воїни чорного драконячого роду, Сайрус зберігає тут дивну, сварливу незалежність: він охоче розмовляє зі смертними мандрівниками, замість того щоб убивати їх на місці, — хоча й не скупиться на образи."}},faq={{q="Де розташована Звивиста Скеля?",a="Звивиста Скеля — у далекому північно-східному куті Палаючих Степів. Щоб дістатися до неї, мандрівникам доведеться пройти повз чорних драконячих створінь, що патрулюють Шлях Крил Жаху.",al={"розташування звивистої скелі","де звивиста скеля","знайти звивисту скелю"}},{q="Хто живе у Звивистій Скелі?",a="У печері живе Сайрус Терепентус — самотній чорний драконород. На відміну від більшості родичів, що одразу нападають на смертних, Сайрус охоче розмовляє з чужинцями, хоча вдачу має злу й зверхню.",al={"хто на звивистій скелі","моб звивистої скелі","нпс звивистої скелі"}},{q="Навіщо шукачеві пригод шукати цю печеру?",a="Шукачі пригод проходять небезпечним Шляхом Крил Жаху, щоб попросити в Сайруса Терепентуса поради й допомоги. Попри різку вдачу, драконород має спільних ворогів із мандрівниками, що протистоять чорному драконячому роду та його темним володарям.",al={"навіщо йти на звивисту скелю","завдання звивистої скелі","призначення сайруса"}}},fp="12,249,17.566.0,30.173.0,26.212.0,43.238.0"}
P.entries["subzone:slithering-scar"] = {n="Звивистий Шрам",s="Звивистий Шрам — розлогий вулик силітидів, що панує над південними кручами Кратера Ун'Ґоро. Це дім агресивного рою Ґоріші; його прориті тунелі й органічні шпилі — небезпечне вторгнення комах у первісну западину.",h="Звивистий Шрам — розлогий вулик силітидів, що панує над південними кручами Кратера Ун'Ґоро.",kw={"звивистий шрам","силітиди","ґоріші","вулик","ун'ґоро","кристалічні пілони"},ang={["class:Druid"]="Агресивне поширення вулика Ґоріші загрожує тендітній, неприборканій життєвій силі кратера, тож проти цієї неприродної навали треба бути пильними."},sec={{t="Вулик Ґоріші",b="Вигризений у червоній землі й скелях південного Ун'Ґоро, Звивистий Шрам стоїть чужорідним наростом серед буйного доісторичного краєвиду. Вуликом керують силітиди Ґоріші — організований різновид комахоподібних істот, що поточили кручі, наче соти, вологими норами й кладковими камерами. У цих підземних лабіринтах робітники й копачі доглядають величезні кладки яєць і личинок поряд із велетенськими виводками ос. Та ще тривожніше те, що колонія вирощує молодих силітидних колосів — жахливих велетнів, які мають прорубати собі шлях крізь усе живе в кратері. Дивні кристалічні утворення, вкраплені у вулик, пульсують неприродним резонансом і стають осередками темної, злагодженої волі колонії."},{t="Відсутній оберіг",b="Учені й дослідники, які обходять околиці Ун'Ґоро, часто помічають тривожну дивину в розташуванні вулика. Прадавні кристалічні пілони стоять на варті вздовж північної, східної та західної меж западини, але на півдні такого стовпа немає. Саме крізь цю незахищену прогалину Ґоріші й прокопалися всередину із сусідніх пустель. Чи силітиди навмисно підточили забутий південний оберіг, чи просто вдерлися туди, де первісний захист кратера був найслабшим, — досі лишається тривожною загадкою для тих, хто стежить за їхнім стрімким поширенням."}},faq={{q="Що таке Звивистий Шрам?",a="Це вулик силітидів, вирубаний у південних скельних стінах Кратера Ун'Ґоро, де живе рій Ґоріші.",al={"що це за місце","огляд звивистого шраму","вулик ун'ґоро"}},{q="Що тут роблять силітиди?",a="Рій Ґоріші риє величезні підземні тунелі, доглядає розплідні зали, повні личинок і яєць, і вирощує велетенських колосів силітидів, щоб запанувати над кратером.",al={"навіщо тут силітиди","мета силітидів ун'ґоро","ціль горішів"}},{q="Чому на півдні немає пілона, як в інших краях?",a="Північний, східний і західний краї Ун'Ґоро позначені давніми кришталевими пілонами, а на південній скелі їх немає. Звивистий Шрам з'явився саме там, де бракує цієї захисної межі.",al={"чому немає південного пілона","де південний пілон","пропущений південний пілон"}},{q="Які небезпечні створіння живуть у вулику?",a="Окрім легіонів робітників, розорювачів і жалоносців, Шрамом блукають колоси, що підростають, і горезвісно люті праматері, як-от Виводкова Матір Завас.",al={"боси вулика","помітні комахи","матір кладки завас"}}},fp="15,247,16.730.0,14.602.0,28.117.0,33.181.0,58.205.0,42.159.0"}
P.entries["subzone:sludge-fen"] = {n="Багнисте Болото",s="Багнисте Болото — отруйне промислове нафтове родовище Венчурної Компанії на північному сході Пусток. Колись тут було чисте, кришталево-блакитне озерце, але відколи гобліни звели бурові вишки й машини, водойма перетворилася на масну трясовину. Роботами керує Наглядач Луґвізл, і родовище постійно приваблює промислових шпигунів і диверсантів від суперників із Раджета.",h="Багнисте Болото — отруйне промислове нафтове родовище Венчурної Компанії на північному сході Пусток.",kw={"багнисте болото","венчурна компанія","наглядач луґвізл","нафта","подрібнювач","пустки"},ang={["class:Druid"]="Багнисте Болото — гидке свідчення неприродної експлуатації. Друїди Орди спускаються в його масні глибини під час Випробування Морського Лева, щоб здобути Половину Амулета Водної Спритності.",["profession:Engineering"]="Венчурна Компанія тримає тут передові подрібнювачі й машини, тож це місце — непереборна спокуса для крадіжок креслень, особливих деталей і секретів ремесла, які замовляють із Раджета."},sec={{t="Промислове спустошення",b="До приходу Венчурної Компанії Багнисте Болото було незайманим озерцем кришталево чистої води, яке живили природні джерела посеред посушливих Пусток. Гнана невситимою жадобою прибутку, Венчурна Компанія розгорнула над улоговиною широкі нафтові бурові роботи й перетворила водойму на заповнене мулом сховище, вкрите густими промисловими відходами. Під орудою Наглядача Луґвізла гобліни-бурильники, інженери й наглядачі цілодобово качають сиру нафту, не зважаючи на руйнування природи. Тепер вода загусла від стоків і отруйних залишків, а місцеве водне життя задихається під мастилом."},{t="Корпоративне суперництво й шпигунство",b="Машини й новітні подрібнювачі на болоті зробили його ласою ціллю для промислових крадіжок. У сусідньому Раджеті інженер Спілки Винахідників Спаттервалв опинився під жорстким тиском: йому треба наздогнати Венчурну Компанію з її передовою технікою для лісозаготівель і копалень. Замість винаходити власні креслення, Спаттервалв послав свого агента Візлкренка захопити подрібнювач Венчурної Компанії просто на Багнистому Болоті. Та Візлкренк необачно викрав машину, не прихопивши ключа запалювання, тож найманців часто втягують у трясовину, щоб відібрати ключі в Луґвізла й вивести викрадену бойову машину крізь стрій розлючених працівників Венчурної Компанії."}},faq={{q="Яким було Багнисте Болото до приходу Венчурної Компанії?",a="Спершу Багнисте Болото було улоговиною з чистою кришталево-блакитною водою. Венчурна Компанія занапастила цю природну оазу, збудувавши просто на ній нафтову вежу й переробку, і втопила довколишні болота в сирій нафті й хімічних відходах.",al={"минуле багнистого болота","чи болото завжди було забруднене","історія багнистого болота"}},{q="Хто керує роботами на Багнистому Болоті?",a="Нафтовим полем від імені Венчурної Компанії керує Наглядач Луґвізл. Він наглядає за робітниками — наглядачами, бурильниками й інженерами — разом із помічниками, як-от Наглядач Ґліббі й Наглядач Ґриллз.",al={"бос багнистого болота","хто керує багнистим болотом","наглядач лагвізл"}},{q="Чому посеред болота стоїть викрадений подрібнювач?",a="Гобліна Візлкренка послав Спаттервалв із Раджета викрасти досконалішу конструкцію подрібнювача Венчурної Компанії. Проте той стрибнув у кабіну, не роздобувши спершу ключа запалювання, і застряг серед ворожих робітників Венчурної Компанії.",al={"подрібнювач візлкранка","гоблін у подрібнювачі","чому подрібнювач застряг"}},{q="Навіщо друїди пірнають у ці забруднені води?",a="Друїдів Орди, що проходять Випробування Морського Лева, посилають на дно отруєного ставка, щоб дістати з затопленої скриньки Половину Амулета Водної Спритності, — це перевіряє їхню витривалість у мерзенному довкіллі.",al={"завдання друїдів багниста болото","половина кулона водної спритності","випробування водної форми"}}},fp="10,379,22.621.0,31.676.1,60.247.0,37.207.0,65.258.0,46.226.0"}
P.entries["subzone:solliden-farmstead"] = {n="Хутір Соллідена",s="Хутір Соллідена — діюча людська гарбузова ферма в західних Галявинах Тірісфалю, одразу на північ від Похоронного Подзвону. Це рідкісний виняток у північному Лордероні: живі тутешні фермери, що пережили Чуму Нежиті й запекло тримаються своєї землі під тінню Багряного Хрестового Походу.",h="Хутір Соллідена — діюча людська гарбузова ферма в західних Галявинах Тірісфалю, одразу на північ від...",kw={"хутір соллідена","гарбузи","живі фермери","багряний хрестовий похід","нова чума","аптекар йогаан","тірісфаль"},ang={["faction:Alliance"]="Бачити живих людей, що обробляють землю Лордерона, — проблиск надії, та гірка правда в тому, що ці відрізані від світу вцілілі дивляться на громадян Стормвінда з тією ж ксенофобською ненавистю, що й на нежить.",["race:Undead"]="Для щойно воскреслих Відступників Хутір Соллідена — негайний урок реальної політики: живі лордеронці, що зневажають те, ким ви стали, слугують водночас сировиною для аптекарських отрут і потенційним південним плацдармом."},sec={{t="Непокірний залишок",b="Поки більша частина Лордерона обернулася на руїну й гниль, поля Хутора Соллідена досі дають здорові врожаї. Поселення веде свій родовід від тих століть, коли дворянські родини-переселенці зі Строму придбали піонерські наділи по всьому Тірісфалю. Сьогодні ці вцілілі люди-фермери живуть під пильним щитом Багряного Хрестового Походу, що патрулює з сусідньої вежі. Травмовані й замкнуті, вони боронять свою садибу з непохитною ворожістю, нападаючи на всіх чужинців, що наближаються, — і з Орди, і з Альянсу."},{t="Очі в Андерсіті",b="Для Відступників, що лише виходять із Похоронного Подзвону, Солліден — і загроза, і ресурс. Королівське Аптекарське Товариство накинуло оком на бездоганні гарбузи ферми як на першокласний органічний матеріал для випробувань своєї Нової Чуми. Тим часом офіцери Відступників на кшталт Вартового Смерті Сіммера посилають новобранців-початківців грабувати поля, красти ці гарбузи для Аптекаря Йогаана в Бріллі й провчити живих."}},faq={{q="Чому на Галявинах Тірісфалю живі люди обробляють землю?",a="Фермери Соллідена — корінні люди Лордерона, які дивом уникли зараження під час Третьої війни. Під захистом Багряного Хрестового Походу, що патрулює із сусідньої вежі, вони вперто обробляють землю, а не тікають із рідного краю.",al={"чому живі люди в тіріфалі","хто ці фермери","живі люди тіріфалю"}},{q="Чому фермери Соллідена ворожі до гравців Альянсу?",a="Пережите падіння Лордерона зробило фермерів підозріливими, озлобленими й геть недовірливими до всіх, хто не з їхнього кола. Під захистом фанатичного Багряного Хрестового Походу вони вважають усіх зайд можливою загрозою чи зараженими мародерами й нападають і на мандрівників Альянсу, і на мандрівників Орди без розбору.",al={"чому фермери нападають на альянс","чи вони альянс","чому червоні до альянсу"}},{q="Навіщо Відступникам гарбузи з Хутора Соллідена?",a="Аптекарям Королівського Аптекарського Товариства потрібна свіжа, незіпсована органіка, щоб випробовувати й удосконалювати свою Нову Чуму. Великі незаражені гарбузи, що ростуть на землі Соллідена, — ідеальні живі носії для вирощування отруйних штамів.",al={"навіщо відступникам гарбузи","завдання з гарбузами","гарбузи аптекарського товариства"}},{q="Хто такий Вартовий Смерті Сіммер і чому він націлився на ферму?",a="Вартовий Смерті Сіммер — офіцер Відступників біля Похоронного Подзвону. Він посилає молодих Відступників напасти на ферму, викрасти десять гарбузів для Аптекаря Йогаана в Бріллі й провчити людей та їхніх захисників із Багряного Хрестового Походу.",al={"чому вбивати фермерів","завдання смертевартового сіммера","жнива жнив"}}},fp="18,295,17.511.0,21.395.0,55.257.0,57.315.0,58.243.0,58.238.0"}
P.entries["subzone:sorrow-hill"] = {n="Пагорб Скорботи",s="Пагорб Скорботи — розлогий цвинтар на південь від Андоргала в Західних Чумних Землях. Колись тут знаходили вічний спочинок прості люди, солдати й вельможі, та чумні казани неподалік обернули цвинтар на велике кубло неупокоєної нежиті.",h="Пагорб Скорботи — розлогий цвинтар на південь від Андоргала в Західних Чумних Землях.",kw={"пагорб скорботи","цвинтар","гробниця утера","андоргал","табір студеного вітру","гулі"},ang={["class:Paladin"]="Пагорб Скорботи — місце глибокої жалоби й шани для паладинів: вони приходять сюди вклонитися Гробниці Утера й відганяють нежить, що оскверняє землю довкола місця спочинку їхнього наставника.",["faction:Alliance"]="Цвинтар неподалік від Табору Студеного Вітру — це і стратегічний пункт на шляху до Андоргала, і священне місце спочинку полеглих захисників Лордерону."},sec={{t="Тягар могил",b="До Третьої війни Пагорб Скорботи був головним цвинтарем Андоргала й довколишніх містечок. Коли Погибель випустила чуму нежиття, гробарі не встигали ховати мертвих. Довкола доглянутих склепів невдовзі виросли мілкі, ледь позначені ями. Зрештою нажахані вцілілі зовсім облишили звичні поховання й стали спалювати тіла рідних на великому багатті південніше — зі страху, що ті повстануть. Ще до остаточного падіння містечка рештки його мешканців поховали лорда Утера Світлоносця на найвищому місці цвинтаря — звідти пагорб і дістав свою скорботну назву."},{t="Повсталі мерці",b="Мерзенні чумні казани Погибелі по всьому краю давно осквернили Пагорб Скорботи. Поховані тут солдати й містяни тепер блукають серед оповитих імлою надгробків як кістяні шкуродери й ненажерливі гулі, а скелети-маги та місцевий командир Погибелі загніздилися в південно-східних склепах. Цвинтар лежить просто при дорозі між Табором Студеного Вітру й Андоргалом, тож і Альянс, і Срібний світанок раз у раз висилають сюди загони, щоб прорідити ряди нежиті й утримати важливий плацдарм у цьому краї."}},faq={{q="Чому цей цвинтар назвали Пагорбом Скорботи?",a="Він дістав цю назву під час падіння Лордерона, коли вцілілі мешканці Андоргала зазнали страшних утрат від Погибелі. Останнє, що вони зробили разом, перш ніж утекти, — поховали свого полеглого героя, лорда Утера Світлоносця, у величній гробниці на вершині пагорба.",al={"значення назви пагорба скорботи","чому пагорб скорботи"}},{q="Чому тут стільки мілких могил?",a="Коли чума нежиття вразила Андоргал, люди вмирали так швидко, що мешканці не встигали будувати пристойні гробниці. Вони поспіхом копали ледь позначені могили, доки навала не стала такою нищівною, що від поховань узагалі відмовилися й почали масово спалювати тіла.",al={"неглибокі могили пагорба скорботи","чому могили погано позначені"}},{q="Хто похований на Пагорбі Скорботи?",a="Окрім тисяч полеглих вояків і мешканців Андоргала, на цвинтарі стоїть велична гробниця Утера Світлоносця. Тут також місце спочинку гармаша Дарґала й пам'ятник Джозефу Редпату, чиє тіло було знищено.",al={"відомі могили пагорба скорботи","хто похований тут"}},{q="Чим небезпечний Пагорб Скорботи сьогодні?",a="Зіпсовані чумними казанами Короля-Ліча, мерці цвинтаря повстали кістяками-шкуродерами, слинавими гулями й кістяками-магами. На чолі з командиром Погибелі, що засів у південно-східному склепі, ця нежить загрожує південному підступу до Андоргала.",al={"погибіль на пагорбі скорботи","хто контролює пагорб скорботи"}}},fp="11,257,18.667.0,20.521.0,41.275.0,42.265.0,29.248.0,40.260.0"}
P.entries["subzone:sorrowmurk"] = {n="Скорботна Мла",s="Скорботна Мла — підступні болотяні простори просто на схід від Ставка Сліз на Болоті Скорботи. Тут здавна патрулюють зелені дракони, що стережуть підступи до Затонулого Храму, тож ця місцина й досі — одна з найнебезпечніших на східних болотах.",h="Скорботна Мла — підступні болотяні простори просто на схід від Ставка Сліз на Болоті Скорботи.",kw={"скорботна мла","зелені дракони","ставок сліз","затонулий храм","болото скорботи","грізне море"},ang={["class:Druid"]="Скорботна скверна, що торкнулася вартових Смарагдового Сну в цих болотах, робить тутешніх зелених драконів трагічним видовищем для кожного слуги природи."},sec={{t="Небезпечне прикордоння",b="Скорботна Мла тягнеться вздовж східного краю Ставка Сліз — це густа, похмура трясовина, що межує з Грізним Морем. Роками у воді й серед сплутаного гілля кишіло люте зелене драконороди й величезні дрейки — рештки виводку, посланого стерегти затоплений Храм Атал'Гаккара. Через них лише досвідчені мандрівники наважуються бродити цими розмоклими нетрями."}},faq={{q="Де розташована Скорботна Мла?",a="Скорботна Мла лежить у найсхіднішій частині Болота Скорботи, одразу за Ставком Сліз і затонулими руїнами Храму Атал'Гаккара, на межі з узбережжям.",al={"розташування скорботної млі","де скорботна мла","скорботна мла на мапі"}},{q="Хто живе в Скорботній Млі?",a="Край славиться зеленими драконячими створіннями — агресивними драконородами й великими драконами, що люто патрулюють болото довкола храмових вод.",al={"моби скорботної млі","що живе в скорботній млі","вороги скорботної млі"}},{q="Чому в Скорботній Млі зелені дракони?",a="Ізера доручила зеленому драконячому родові пильнувати Ставок Сліз і стежити, щоб зло, затоплене в Храмі Атал'Гаккара, лишалося під замком.",al={"чому тут дракони","зелений політ болото скорботи","дракони храму"}}},fp="10,272,17.411.0,32.173.0,38.151.0,46.159.0"}
P.entries["subzone:south-gate-outpost"] = {n="Застава Південної Брами",s="Застава Південної Брами — укріплений дворфійський гірський пост на Проході Південної Брами між Дун Мороґом і Лох Моданом. Горяни, що тримають засніжену південну дорогу, оберігають постійний потік мандрівників між морозними висотами Айронфорджа й помірною долиною Озера.",h="Застава Південної Брами — укріплений дворфійський гірський пост на Проході Південної Брами між Дун Мороґом і...",kw={"застава південної брами","прохід південної брами","горяни","дун мороґ","лох модан"},ang={["faction:Alliance"]="Застава — надійний військовий прихисток на одному з головних внутрішніх шляхів постачання Каз Модану, що тримає відкритим прохід між столицею та східними поселеннями.",["race:Dwarf"]="Для дворфів, що вперше покидають Долину Холодного Хребта й Дун Мороґ, Застава Південної Брами — останній холодний орієнтир перед спуском у яскраві, залиті сонцем землі Лох Модану."},sec={{t="Вартові південної дороги",b="Застава Південної Брами, що стоїть посередині високого гірського розрізу Проходу Південної Брами, позначає межу між засніженими схилами Дун Мороґу й зеленою улоговиною Лох Модану. Тут несуть службу айронфорджські горяни, яким доручено патрулювати кам'янисті серпантини й тримати небезпечних звірів подалі від головного шляху. На відміну від своїх родичів, що ледве дають собі раду на Заставі Північної Брами, тутешні захисники здебільшого вже убезпечили свою ділянку дороги, тож мандрівники, прочани й торгові вози, що прямують до Телсамара, можуть подорожувати відносно безпечно."}},faq={{q="Для чого потрібна Застава Південної Брами?",a="Це укріплений прикордонний пост і гарнізон біля Проходу Південної Брами. Горяни, що стоять тут, тримають засніжену дорогу між Дун Мороґом і Лох Моданом вільною від гірських звірів і ворожих зайд.",al={"навіщо застава південної брами","призначення застави південної брами","що це за застава"}},{q="Чому тут набагато спокійніше, ніж на Заставі Північної Брами?",a="Гарнізон Застави Південної Брами успішно прорідив агресивних звірів біля самої дороги. Натомість Заставі Північної Брами доводиться відбиватися від сильніших навал серед дикішої гірської місцевості, тож південний прохід порівняно спокійний.",al={"різниця між північною і південною брамою","чи безпечна південна брама","південна брама проти північної"}},{q="Куди веде дорога через Заставу Південної Брами?",a="На захід, угору перевалом, ви потрапите на засніжене нагір'я Дун Мороґу, у бік Айронфорджа. На схід, униз, дорога веде просто в помірну долину Лох Модану, в'ючись до поселення Телсамар.",al={"куди веде дорога","кінець дороги південної брами","шлях проходу південної брами"}}},fp="18,291,29.544.0,42.228.0,57.255.0,52.251.0"}
P.entries["subzone:south-gate-pass"] = {n="Прохід Південної Брами",s="Прохід Південної Брами — головний гірський шлях, що з'єднує засніжені висоти Дун Мороґу з улоговиною Лох Модану. Оточений дворфійськими тунелями й дозорними постами, він править за найкоротшу дорогу між Айронфорджем і поселенням Телсамар.",h="Прохід Південної Брами — головний гірський шлях, що з'єднує засніжені висоти Дун Мороґу з улоговиною Лох...",kw={"прохід південної брами","застава південної брами","дун мороґ","лох модан","телсамар"},ang={["faction:Alliance"]="Прохід — важлива внутрішня артерія, що з'єднує Айронфордж зі східними землями Альянсу; його утримують і охороняють Королівські горяни.",["race:Dwarf"]="Для дворфів, що покидають Дун Мороґ, Прохід Південної Брами — поріг, де крижане гірське повітря поступається відкритим долинам і кар'єрам Лох Модану."},sec={{t="Дорога на схід",b="Прохід Південної Брами, прорубаний просто крізь хребет Каз Модану, з'єднує високі гори Дун Мороґу з пологою долиною Лох Модану на сході. Залишивши позаду холодні схили, мандрівники виходять крізь кам'яні арки в тепліше серце дворфійських земель. Оскільки шлях веде просто до Телсамара, ним постійно ходять горяни, гінці й щойно вишколені шукачі пригод, що вирушають зі столиці."},{t="Поріг під охороною",b="Від диких звірів і трогів, що никають довкола, прохід захищає Застава Південної Брами, де дворфійські горяни постійно несуть варту. Хоч тут загалом безпечніше, ніж у диких нетрях углибині долини, мандрівникам радять триматися дороги, бо ворожі звірі й мандрівні загрози раз у раз прощупують підступи."}},faq={{q="Куди веде Прохід Південної Брами?",a="На захід тунелями ви потрапите на засніжене нагір'я Дун Мороґу, на дорогу до Айронфорджа. На схід шлях спускається в улоговину Лох Модану, просто до поселення Телсамар.",al={"куди веде прохід південної брами","кінець проходу південної брами","дорога південної брами"}},{q="Чи безпечно подорожувати Проходом Південної Брами?",a="Сама дорога відносно безпечна завдяки дворфійським вартовим із Застави Південної Брами, але на довколишніх кручах і схилах за виходом із тунелю водяться ведмеді, павуки й троги, що підступають дедалі ближче.",al={"чи небезпечний прохід південної брами","загрози проходу південної брами"}},{q="Чому цим проходом користуються частіше, ніж Перевалом Північної Брами?",a="Прохід Південної Брами — найпряміший і найзручніший суходільний шлях між Дун Мороґом і Телсамаром, тож його обирають для місцевої торгівлі, обозів із припасами й мандрівників до центру Лох Модану.",al={"південна брама проти північної","чому користуватися південною брамою"}}},fp="15,259,13.416.0,19.325.0,32.214.0,34.211.0,48.220.0"}
P.entries["subzone:south-seas"] = {n="Південні Моря",s="Південні Моря — неосяжні, залиті сонцем води, що розділяють південні землі Калімдору й Східних Королівств. Вони омивають береги Танарісу й Долини Стренглторну і славляться прибутковими торговими шляхами, підступними рифами й зухвалими піратськими командами.",h="Південні Моря — неосяжні, залиті сонцем води, що розділяють південні землі Калімдору й Східних Королівств.",kw={"південні моря","пірати","кезан","зандалар","тель'абім","торгові шляхи"},ang={["class:Rogue"]="Беззаконні Південні Моря — життєва сила піратських картелів і каперів: тут безмежні можливості для шахраїв, які знаються на абордажах, контрабанді й підступній політиці портових гаваней.",["profession:Cooking"]="Екзотичні води й узбережжя Південних Морів дають цінну океанську рибу, велетенських кальмарів і славетні солодкі банани, які привозять із відлюдних островів на кшталт Тель'Абіму."},sec={{t="Прикордоння зірвиголів",b="Південні Моря простягаються на південь від Великого Моря й Виру та омивають пустелі Танарісу й буйні джунглі Долини Стренглторну. Відколи десять тисяч років тому Великий Розкол розтрощив первісний континент, цей океан плекав далекі тропічні острови, унікальних морських тварин і незалежні торгові мережі. Гоблінські судноплавні картелі, що діють із таких гаваней, як Порт Стімвідла й Буті Бей, підтримують хиткі морські шляхи. Проте ці води славляться беззаконням: тут кишать корсари, буканіри Кривавого Вітрила й морські хижаки, що полюють на кожне судно, яке наважиться відпливти далеко від берега."},{t="Приховані глибини й далекі острови",b="За прибережними торговими шляхами лежить мозаїка легендарних островів і затонулих небезпек. Серед відомих земель Південних Морів — батьківщина гоблінів Кезан, прадавній тролячий острів Зандалар, розбійницька твердиня Острів Здобичі й щедрі на врожаї береги Тель'Абіму. Та морякам-торговцям загрожують не лише головорізи: у глибших водах живуть колосальні велетенські кальмари, первісні морські черепахи й наги, що чатують біля прадавніх руїн, поглинутих хвилями. Щоб ходити цими водами, потрібні досвідчені капітани, надійні карти й чимала вогнева міць."}},faq={{q="З якими краями межують Південні Моря?",a="На півдні Калімдору Південні Моря омивають узбережжя Танарісу біля запечатаної брами Ульдуму. А за океаном на сході вони б'ються об береги Долини Стренглторну та її віддалених островів, як-от Острів Ягуеро й Острів Йоджамба.",al={"де південні моря","межі південних морів","яке це узбережжя"}},{q="Хто контролює судноплавство в Південних Морях?",a="Жодна сила не панує в Південних Морях. Картель Стімвідл тримає головну торгову лінію між Портом Стімвідла й Буті Беєм, але постійно воює за води з піратськими зграями-суперниками — Буканірами Кривавого Вітрила й Флібустьєрами Південних морів.",al={"хто керує південними морями","торгівля південних морів","порти південних морів"}},{q="Які небезпечні істоти живуть у цих водах?",a="Відкриті хвилі кишать небезпеками — від ненажерливих велетенських кальмарів і прибережних рифових акул до закутих у панцир велетенських черепах. Під час Другої війни клан Орди Штормового Розорювача навіть ловив тутешніх велетенських черепах, щоб переробити їх на підводні судна. А острови краю ховають м'ясоїдних кажанів-кривокрилів і патрулі наг, що чатують у засідці.",al={"монстри південних морів","морські чудовиська танарісу","істоти південних морів"}},{q="Які відомі острови лежать у Південних Морях?",a="Серед відомих островів у глибоких водах — гоблінський торговий осередок Кезан, піратське кубло Острів Здобичі, багатий на фрукти Тел'Абім і Зандалар — давнє королівство тролівської імперії. Ближче до узбереж лежать менші прикмети, як-от Острів Йоджамба й Острів Ягуеро.",al={"острови південних морів","кезан зандалар південні моря","список островів південних морів"}}},fp="10,284,25.656.0,31.584.0,33.241.0,40.273.0,46.341.0,47.286.0"}
P.entries["subzone:south-tide-s-run"] = {n="Південна Течія Припливу",s="Південна Течія Припливу — самотнє південно-західне узбережжя Срібнолісся, що тягнеться вздовж холодних вод Великого Моря. Ці вологі піски й прибій, що облямовують лісисті нутрощі краю, — південна пара до Потоку Північного Припливу.",h="Південна Течія Припливу — самотнє південно-західне узбережжя Срібнолісся, що тягнеться вздовж холодних вод...",kw={"південна течія припливу","узбережжя","велике море","срібнолісся"},ang={["race:Undead"]="Дике південно-західне узбережжя лежить далеко від захисту Гробниці, тож це безлюдне прикордоння, куди Відступники рідко ступають."},sec={{t="Західний берег",b="Південна Течія Припливу, що тягнеться південно-західним краєм Срібнолісся, — безлюдна межа між лісом і Великим Морем. На відміну від захищених східних доріг, що ведуть униз до Стіни Ґреймейна, цей відкритий берег бере на себе всю силу західних припливів і лишається похмурою дикою місциною, майже не зачепленою поселеннями в глибині краю."}},faq={{q="Де розташована Південна Течія Припливу?",a="Південна Течія Припливу займає південно-західне узбережжя Срібнолісся на межі з відкритими просторами Великого Моря.",al={"де південна течія припливу","розташування південної течії","південна течія на мапі"}},{q="Чим Південна Течія Припливу відрізняється від Потоку Північного Припливу?",a="Обидва — довгі смуги пляжу вздовж західного берега Срібнолісся, але Південна Течія Припливу охоплює південну частину узбережжя, а Потік Північного Припливу тягнеться північним заходом, біля кордону з Галявинами Тірісфалю.",al={"північна течія проти південної","різниця течій припливу"}},{q="Чи є поселення на Південній Течії Припливу?",a="На самому пляжі немає ні великих поселень, ні застав. Відступники здебільшого діють углибині краю, біля головних шляхів, тож узбережжя лишається відлюдним.",al={"містечка південної течії","хто живе в південній течії"}}},fp="16,238,17.353.0,34.119.0,55.234.0,49.159.0"}
P.entries["subzone:southern-gold-road"] = {n="Південна Золота Дорога",s="Південна Золота Дорога — важливий пустельний тракт, що тягнеться південною половиною Пусток і з'єднує центральні рівнини з Великим Підйомником. Це незамінна артерія торгівлі в краї: нею рухаються каравани, припаси й мандрівники між віддаленими куточками Калімдору.",h="Південна Золота Дорога — важливий пустельний тракт, що тягнеться південною половиною Пусток і з'єднує...",kw={"південна золота дорога","золотий шлях","великий підйомник","тисяча голок","каравани","пустки"},ang={["faction:Horde"]="Дорога — хребет шляхів постачання Орди між центральним перехрестям Пусток і південними заставами поблизу Тисячі Голок."},sec={{t="Артерія півдня",b="Офіційно Південна Золота Дорога починається біля кам'яного мосту, що розділяє північну й південну половини Пусток, і тягнеться просто на південь, аж до Великого Підйомника, яким спускаються в Тисячу Голок. Як і північна частина, що зветься просто Золотим Шляхом, цей курний тракт має назву завдяки нескінченному потоку прибуткових купецьких караванів. Попри постійні напади місцевих племен шипогривів і хижаків, що никають саваною, це один із найжвавіших далеких шляхів континенту, яким возять товари між віддаленими заставами й гамірними портами."},{t="Перехрестя далеких країв",b="Дорогою користується не лише місцева Орда. Шукачі пригод і загартовані торговці, що прямують до таких далеких місць, як Ґаджетзан у південних пустелях Танаріса, Обердайн на туманних берегах Темного Узбережжя чи священні гаї Нічного Притулку в Місячному Гаю, топчуть цей випалений сонцем простір. Для тих, хто подорожує нутрощами Калімдору пішки, подолати Південну Золоту Дорогу — виснажливий обряд посвяти."}},faq={{q="Де починається й закінчується Південна Золота Дорога?",a="Офіційно дорога починається від мосту, що розділяє північну й південну половини Пусток, і тягнеться на південь аж до краю Тисячі Голок біля Великого Підйомника.",al={"шлях південної золотої дороги","маршрут південної золотої дороги","де південна золота дорога"}},{q="Чому вона зветься Золотою?",a="Шлях названо на честь багатих торгових караванів, що регулярно ним ходять, перевозячи коштовні товари, руду й монети через серце Калімдору.",al={"чому золота","походження назви золотої дороги","значення золотої дороги"}},{q="Яка різниця між Золотим Шляхом і Південною Золотою Дорогою?",a="Межа — міст через центральний розлам Пусток. На північ від нього дорога зветься просто Золотим Шляхом, а відтинок, що веде на південь до Великого Підйомника, — Південною Золотою Дорогою.",al={"золотий шлях проти південної золотої дороги","дві золоті дороги"}},{q="Хто подорожує цим відтинком дороги?",a="Окрім місцевих гінців і патрулів Орди, цим шляхом користуються крамарі й дослідники, що мандрують між далекими краями, — він сполучає, наприклад, Ґаджетзан на далекому півдні з Темним Узбережжям і Місячним Гаєм на далекій півночі.",al={"хто користується південною золотою дорогою","каравани південної золотої дороги"}}},fp="18,301,19.606.0,29.443.0,48.191.0,31.158.0,72.228.0,39.226.0"}
P.entries["subzone:southern-savage-coast"] = {n="Південне Дике Узбережжя",s="Південне Дике Узбережжя — довга смуга пляжів і припливних вод уздовж південно-західної частини Долини Стренглторну. З одного боку до нього підступають зрадливі глибини Південних Морів, а на самому березі чатують хижі звірі, ворожі наги й одвічна загроза прибережних нальотників.",h="Південне Дике Узбережжя — довга смуга пляжів і припливних вод уздовж південно-західної частини Долини...",kw={"південне дике узбережжя","південні моря","мерзенний риф","наги","долина стренглторну","корсари"},ang={["class:Hunter"]="Широкі відкриті пляжі — чудові угіддя, щоб вистежувати земноводну дичину, прибережних хижих котів і василісків: тут видно далеко, і це куди краще, ніж задушливі хащі в глибині суходолу."},sec={{t="Підступна берегова лінія",b="Південне Дике Узбережжя тягнеться західним краєм південних джунглів — там, де суходіл поступається теплим течіям Південних Морів. Від північного Дикунського Узбережжя його відділяють затоплені руїни й небезпеки Мерзенного Рифу. Узбережжя оминає затоки біля Арени Ґурубаші та Джерела Нек'мані, а за Буті Беєм і Мисом Жанейро поступово сходить нанівець. Пляжі хоч і відкритіші за задушливі джунглі в глибині суходолу, та мандрівникам доводиться відбиватися від агресивних плазунів-хижаків, наг, що полюють на мілинах, і корсарів, які пропливають повз і видивляються на березі легку здобич."}},faq={{q="Де починається й закінчується Південне Дике Узбережжя?",a="Воно охоплює південно-західне узбережжя Долини Стренглторну: починається нижче Мерзенного Рифу й тягнеться на південь повз Буті Бей і Мис Жанейро, де переходить у Дикий Берег.",al={"розташування південного дикого узбережжя","де південне дике узбережжя","межі дикунського узбережжя"}},{q="Чим воно відрізняється від північного Дикунського Узбережжя?",a="Ці дві смуги узбережжя розділяє Мерзенний Риф. Північне Дикунське Узбережжя тягнеться вздовж вод Великого Моря на півночі Стренглторну, а Південне Дике Узбережжя лежить уздовж нижнього мису на межі з Південними Морями.",al={"різниця між дикунським і південним","чому два дикунські узбережжя","межа гидкого рифу"}},{q="Які загрози чекають мандрівників на пляжі?",a="На відкритих пісках повно лютих ящірок-василісків, клацаючих кроколісків, ворожих наг, що виповзають із мілин, і патрулів піратів, які ревно бережуть свої ділянки.",al={"чи небезпечне південне дике узбережжя","моби південного дикого узбережжя","загрози вздовж узбережжя"}},{q="Чи контролює це узбережжя Буті Бей?",a="Ні. Нападники Чорної Води й картель Стімвідл тримають лише гавань Буті Бею та найближчі підступи до неї. Дикі пляжі на північ і на південь лишаються беззаконною, неприборканою землею.",al={"чи бутті бей володіє пляжем","контроль стімвіддлів над узбережжям","гоблінська територія"}}},fp="21,281,23.616.0,51.203.0,51.226.0,50.167.0,38.205.0"}
P.entries["subzone:southfury-river"] = {n="Річка Південної Люті",s="Річка Південної Люті — одна з найпомітніших водних артерій центрального Калімдору: стрімка й широка, вона прокладає собі шлях на південь від висот Гори Гіджал. Річка слугує природним кордоном між Азшарою та Ашенвалем, а також між Дуротаром і Пустками, а неподалік Раджета впадає у Велике Море.",h="Річка Південної Люті — одна з найпомітніших водних артерій центрального Калімдору: стрімка й широка, вона...",kw={"річка","південна лють","дуротар","пустки","азшара","ашенваль","оргріммар"},ang={["faction:Horde"]="Річка Південної Люті — західний оборонний рубіж Дуротару й природний шлях, що з'єднує столицю із серцем Пусток."},sec={{t="Природний рубіж",b="Річка Південної Люті бере початок високо на Горі Гіджал, зривається каскадами водоспадів і мчить крізь центральний Калімдор. Її бурхливі води — чітка межа на мапі: вони відділяють священні ліси Ашенвалю від прадавньої Азшари, а посушливі пагорби Дуротару — від савани Пусток. Лише кілька мостів наважуються перетнути її бистру течію — передусім масивна переправа, що стереже задню браму Оргріммара, і міст, який з'єднує Дуротар із Пустками. Зрештою річка каскадом водоспаду обривається у Велике Море трохи на північний схід від нейтрального порту Раджет."},{t="Стратегічне значення",b="Для Орди Річка Південної Люті — водночас щит і життєво важливий природний шлях. Вона прикриває західні підступи до Дуротару й Оргріммара від раптового наземного наступу та несе свіжу гірську воду крізь випалений, висушений сонцем край. Трохи на північ від західної переправи до Оргріммара лежить унікальне перехрестя, де сходяться чотири великі краї: Ашенваль, Азшара, Дуротар і Пустки. Хто тримає цю вируючу ріку, той береже шляхи постачання між Оргріммаром і віддаленими поселеннями Орди."}},faq={{q="Де починається й закінчується Річка Південної Люті?",a="Річка Південної Люті бере початок у високогір'ї Гори Гіджал і спадає мальовничими водоспадами в низини. Вона тече на південь між Ашенвалем, Азшарою, Дуротаром і Пустками, а тоді водоспадом обривається у Велике Море на північний схід від Раджета.",al={"витік річки південної люті","куди тече південна лють","гирло південної люті"}},{q="З якими краями межує річка?",a="На півночі річка відділяє Ашенваль від Азшари, а на півдні — Пустки від Дуротару. Цікаво, що на північ від західного мосту Оргріммара є місце, де на берегах річки сходяться всі чотири краї.",al={"які зони на південній люті","межі південної люті"}},{q="Де мандрівники можуть перетнути Річку Південної Люті?",a="Через Річку Південної Люті перекинуто три головні мости: один сполучає Азшару з Ашенвалем, другий веде до задньої брами Оргріммара, а великий міст сполучає Дуротар із Пустками.",al={"мости південної люті","як перетнути південну лють","мости над південною люттю"}},{q="Чому річка важлива для Оргріммара?",a="Річка — грізна природна перепона, що захищає західний фланг Оргріммара й Дуротару. Крім того, її свіжі гірські води — безцінне джерело життя для цього посушливого краю.",al={"південна лють оргріммар","чому орді важлива південна лють"}}},fp="15,301,22.606.0,20.552.0,45.251.0,34.213.0,46.196.0,40.208.0"}
P.entries["subzone:southmoon-ruins"] = {n="Руїни Південного Місяця",s="Руїни Південного Місяця — прадавні кам'яні рештки на півдні Танарісу, трохи на північ від Долини Вартових. Їх давно захопили грубі огри Дюнного Молота, а розсипане муровання зберігає сліди прадавньої тролячої цивілізації, що панувала в пустелі, поки її не поглинули піски.",h="Руїни Південного Місяця — прадавні кам'яні рештки на півдні Танарісу, трохи на північ від Долини Вартових.",kw={"руїни південного місяця","дюнний молот","огри","тролячі руїни","долина вартових","танаріс"},ang={["race:Dwarf"]="Дворфійські мандрівники, що перетинають південний Танаріс, не знайдуть у Південному Місяці нічого, крім вивітреного тролячого муровання й огрів Дюнного Молота, що отаборилися серед нього.",["race:Troll"]="Для тролів Темного Списа ці розбиті колони — тверезий погляд на занепалу велич їхніх далеких тролячих родичів, що опинилися в злиднях під пустельним сонцем."},sec={{t="Каміння серед мінливих пісків",b="Руїни Південного Місяця, що здіймаються з розпеченої пустки південного Танарісу, — вивітрене свідчення прадавніх тролячих імперій, які колись володіли південними землями Калімдору. Як і в сусідніх руїнах Східного Місяця та Полуденної Тіні, тутешні кам'яні колони й вівтарі тисячоліттями витримували вітер і їдкий пісок. Місце часто правило за убогий табір для огрів Дюнного Молота, які анітрохи не шанують майстерність минулого й використовують прадавні споруди лише як прихисток і свою територію."},{t="Таємниці під уламками",b="Архітектурні рештки безсумнівно тролячі, але про народ, що звів каміння Південного Місяця, і про те, чому він його покинув, відомо мало. Усе, що вони лишили по собі, поховане під мінливим піском, а огрям, які отаборилися серед колон, до цього байдуже."}},faq={{q="Хто збудував Руїни Південного Місяця?",a="Руїни Південного Місяця — давні тролівські руїни, вивітрені рештки тролівської цивілізації, що колись володіла південними краями нинішньої пустелі Танаріс.",al={"хто збудував південний місяць","історія південного місяця","чи це тролячі руїни"}},{q="Хто нині живе в руїнах?",a="Здавна руїни займають огри Дюнного Молота, що забрели в Танаріс і забрали собі під табори різні напівзруйновані давні застави, прогнавши інших мародерів.",al={"хто тут живе","моби південного місяця","дюнний молот на південному місяці"}},{q="Де розташовані Руїни Південного Місяця?",a="Вони лежать у південній половині Танарісу, на північний захід від Долини Вартових і на південь від центральних пустельних пусток.",al={"розташування південного місяця","де руїни південного місяця","як знайти південний місяць"}}},fp="15,295,28.499.0,26.276.0,41.160.0,33.195.0,38.130.0"}
P.entries["subzone:southpoint-tower"] = {n="Вежа Південного Мису",s="Вежа Південного Мису — зруйнована лордеронська дозорна вежа на західному кордоні Передгір'я Гілсбреда, з якої видно дорогу до Срібнолісся. Колись тут стояла людська варта, а тепер розбиту споруду обжили розвідники Відступників, що стежать за пересуваннями Альянсу в краї.",h="Вежа Південного Мису — зруйнована лордеронська дозорна вежа на західному кордоні Передгір'я Гілсбреда, з якої...",kw={"вежа південного мису","гілсбред","срібнолісся","відступники","леш","розвідка"},ang={["faction:Alliance"]="У зруйнованій вежі сидить ворожий шпигун, що стежить за дорогою до Срібнолісся, тож розвідники, які захищають людські поселення Гілсбреда, неминуче беруть її на приціл.",["race:Undead"]="Вежа — незамінний розвідувальний пункт для Відступників біля кордону зі Срібноліссям, звідки можна стежити за пересуваннями людських загонів із Гілсбреда."},sec={{t="Зруйнований вартовий",b="Вежа Південного Мису стоїть трохи на південь від шляху, що з'єднує Срібнолісся з Передгір'ям Гілсбреда. Королівство Лордерон звело її, щоб стерегти рух між східними полями й західними лісами. Після Третьої війни, коли Погибель знищила королівство, кам'яна кладка почала руйнуватися. Нині вежа стоїть без даху, кришиться й лишається самотнім пам'ятником людського панування на роздертих землях."},{t="Очі над пагорбами",b="Попри руйнування, вежа досі цінна як оглядовий пункт. Відступники тримають тут заставу й розміщують своїх агентів — як-от Скрадача Смерті Леша, — щоб стежити за місцевими патрулями Альянсу, сусідніми людськими поселеннями на Полях Гілсбреду та мандрівниками на головному шляху. Через самотнє розташування просто біля ворожих земель вежа часто стає осередком сутичок."}},faq={{q="Де розташована Вежа Південного Мису?",a="Вежа Південного Мису стоїть на західному краю Передгір'я Гілсбреда, просто на південь від дороги до Срібнолісся й трохи на захід від Полів Гілсбреду.",al={"розташування вежі південного мису","де вежа південного мису","знайти вежу південного мису"}},{q="Хто зараз тримає Вежу Південного Мису?",a="Вежу тримають Відступники. У її зруйнованих стінах стоїть агент на ім'я Скрадач Смерті Леш, що стежить за дорогою й за силами Альянсу поблизу.",al={"хто у вежі південного мису","хто володіє вежею південного мису","фракція вежі південного мису"}},{q="Чому вежа в руїнах?",a="Вежу розбили й покинули під час падіння Лордерона, коли Погибель спустошувала край. Її так і не відбудували, тож лишилися тільки розбиті кам'яні стіни.",al={"чому вежа зруйнована","хто зруйнував вежу південного мису"}},{q="Чому гравці Альянсу нападають на цю заставу?",a="На посту стоїть самотній розвідник-Відступник, що стежить за людськими землями. Відрізаний від своїх біля кордону, він — легка й спокуслива ціль для мандрівників Альянсу між Саутшором і західними дорогами.",al={"чому вбивати скрадача смерті леша","альянс нападає на вежу південного мису"}}},fp="16,286,17.431.0,17.407.0,34.162.0,40.173.0,26.163.0,44.214.0"}
P.entries["subzone:southridge-beach"] = {n="Пляж Південного Хребта",s="Пляж Південного Хребта тягнеться вздовж південних берегів Затоки Бур у центральній Азшарі. Колись тут був розкішний квартал прадавнього калдорейського міста Елдарат, а нині його зруйновані рештки заполонили ворожі наги, мурлоки й могутні морські велетні.",h="Пляж Південного Хребта тягнеться вздовж південних берегів Затоки Бур у центральній Азшарі.",kw={"пляж","азшара","затока бур","елдарат","наги","морські велетні","високородні"},ang={["race:NightElf"]="Руїни на Пляжі Південного Хребта — болісне нагадування про велич і трагічне падіння прадавньої цивілізації Високородних перед Великим Розколом."},sec={{t="Затоплене узбережжя",b="Пляж Південного Хребта — південна межа неспокійної Затоки Бур. Тисячі років тому це узбережжя належало величному місту Високородних Елдарату, та Великий Розкол розламав землю й поглинув хвилями більшість його палаців. Нині пісок усіяний розкришеними мармуровими колонами та вивітреними кам'яними павільйонами. Замість учених і шляхетних придворних за берег змагаються агресивні наги Шиполуски, хижі макрури, люті гідри й зграї мурлоків-падальників. Часом із глибин на берег виходять навіть величезні морські велетні."}},faq={{q="Де розташований Пляж Південного Хребта?",a="Пляж Південного Хребта лежить у центрі Азшари, уздовж південного краю Затоки Бур, просто під кручами суходолу.",al={"розташування пляжу південного хребта","де пляж південного хребта","пляж південного хребта ашар"}},{q="Що за руїни розкидані по пляжу?",a="Кам'яні колони й арки на піску — зовнішні рештки Елдарата, колись величного міста нічних ельфів-Високородних, яке зруйнував і затопив Великий Розкол десять тисяч років тому.",al={"руїни пляжу південного хребта","руїни елдарата на пляжі","що за руїни тут"}},{q="Хто живе на Пляжі Південного Хребта?",a="Узбережжя щільно зайняли наги, а поряд живуть примітивні мурлоки, закуті в панцир макрури, небезпечні гідри й подеколи блукаючі морські велетні.",al={"моби пляжу південного хребта","вороги пляжу південного хребта","що тут живе"}},{q="Чому тут так багато наг?",a="Наги піднялися з океанських глибин, щоб повернути собі руїни своєї колишньої цивілізації по всій Азшарі, і міцно закріпилися на пляжах Затоки Бур.",al={"чому наги на пляжі","наги пляжу південного хребта","наги ашара"}}},fp="16,244,19.561.0,34.128.0,41.199.0,40.148.0,32.186.0"}
P.entries["subzone:southshore"] = {n="Саутшор",s="Саутшор — приморський людський порт у Передгір'ї Гілсбреда й одна з небагатьох уцілілих твердинь Альянсу в занепалому Лордероні. Колись сонне рибальське селище, тепер це оплот в облозі, якому постійно загрожують гарнізон Відступників у Таррен Міллі, свавільні розбійники Синдикату й прибережні потвори.",h="Саутшор — приморський людський порт у Передгір'ї Гілсбреда й одна з небагатьох уцілілих твердинь Альянсу в...",kw={"саутшор","альянс","таррен мілл","магістрат генрі малеб","маршал редпат","гілсбред"},ang={["faction:Alliance"]="Саутшор — ваш головний прихисток, джерело завдань і військовий редут на півночі Лордерона, що дає необхідну підтримку проти Відступників і Синдикату.",["faction:Horde"]="Для Орди — особливо для Відступників із сусіднього Таррен Мілла — Саутшор уособлює вперту твердиню Альянсу, що засіла на землі, яку відвоювали мерці."},sec={{t="Маяк у Лордероні",b="Саутшор уперше прославився під час Першої війни, коли на його берег висадилися човни з біженцями, що вціліли після падіння королівства Стормвінд. Хоч під час Другої війни за нього билися й навіть захоплювали, його відбудували, і згодом він пережив жахи Третьої війни. Сьогодні, коли решта Лордерона лежить у руїнах або під владою Відступників, Саутшор лишається затято вірним Великому Альянсу. Він дає прихисток людям, що втратили домівки, ветеранам-паладинам Срібної Длані й ученим Кірін-Тору."},{t="В облозі з усіх боків",b="Попри мальовничі доки й славетний черепаховий суп, життя в Саутшорі небезпечне. Під проводом Магістрата Генрі Малеба й Маршала Редпата містечко бореться з невпинним тиском. На півночі Відступники Таррен Мілла ведуть запеклу прикордонну війну за панування над Гілсбредом. У глибині суходолу розбійники-аристократи із Синдикату нападають на шляхи постачання й убивають місцевих ватажків, а огри, мурлоки й наги постійно турбують межі містечка."}},faq={{q="Чому Саутшор досі вірний Альянсу, хоча Лордерон упав?",a="Саутшор уник цілковитого знищення під час навали Погибелі. Його вцілілі мешканці-люди підтвердили давню присягу Великому Альянсу й отримують від Стормвінда військову та господарську підтримку, щоб утримувати плацдарм на півночі.",al={"чому саутшор вірний альянсу","хто контролює саутшор","саутшор альянс лордерон"}},{q="Чому між Саутшором і Таррен Міллом такі запеклі бої?",a="Таррен Мілл тримають Відступники, а Саутшор — головний оплот Альянсу в краї. Обидві сторони вважають Передгір'я Гілсбреда своїм по праву, тож на кордоні майже безупинно тривають сутички, набіги й диверсії.",al={"війна саутшора й таррен міла","чому б'ються саутшор і таррен мілл","конфлікт гілсбреду"}},{q="Хто очолює містечко Саутшор?",a="Цивільними справами опікується Магістрат Генрі Малеб, що обійняв посаду після того, як Синдикат убив попереднього магістрата. Військовою обороною й безпекою містечка керує Маршал Редпат.",al={"лідер саутшора","хто керує саутшором","магістрат малеб"}},{q="Що, окрім Відступників, загрожує Саутшору?",a="Окрім Відступників, Саутшор мусить відбиватися від прибережних мурлоків і наг, огрів-Трощихребтів, що спускаються з Гір Альтерак, і злочинного Синдикату, що засів у Твердині Дурнгольд.",al={"вороги саутшора","загрози саутшору"}}},fp="10,321,21.528.0,22.451.0,70.248.0,70.235.0,33.201.0,58.183.0"}
P.entries["subzone:southshore-town-hall"] = {n="Ратуша Саутшора",s="Ратуша Саутшора — адміністративний осередок південного узбережжя Передгір'я Гілсбреда, один з останніх дієвих осередків цивільної влади Лордерона. Звідси Магістрат Генрі Малеб керує місцевою обороною й урядує вцілілими мешканцями міста. Для Альянсу ратуша — життєво важливий центр у боротьбі за опору на зачумленій півночі.",h="Ратуша Саутшора — адміністративний осередок південного узбережжя Передгір'я Гілсбреда, один з останніх дієвих...",kw={"ратуша саутшора","саутшор","генрі малеб","магістрат","альянс","лордерон"},ang={["faction:Alliance"]="Для поборників Альянсу, що прибувають на північ, Ратуша Саутшора — головна цивільна застава, яка представляє владу в краї й дає важливі доручення проти навколишніх загроз.",["race:Human"]="Людям ратуша зворушливо нагадує про втрачену славу Лордерона: тут дієвий магістрат досі тримає прапори розбитого королівства."},sec={{t="Оплот цивільної влади",b="Тоді як більша частина Лордерона лежить у руїнах під скверною Погибелі й натиском Відступників, ратуша Саутшора зберігає подобу непорушеного людського врядування. Магістрат Генрі Малеб щодня порядкує справами зі свого кабінету тут, працюючи пліч-о-пліч із посадовцями на кшталт Кундріка Зандена, щоб забезпечити місто ресурсами й зберегти громадський лад. У краї, оточеному агресивною нежиттю, розбійниками Синдикату й запеклими прикордонними сутичками Гілсбреда, ратуша — нервовий центр, що спрямовує боротьбу міста за виживання перед безупинними загрозами."}},faq={{q="Хто керує містечком із Ратуші Саутшора?",a="Магістрат Генрі Малеб — головний цивільний очільник Саутшора: він вершить справи містечка з ратуші, керуючи обороною й управлінням уцілілого людського поселення.",al={"хто керує саутшором","мер саутшора","хто тут головний"}},{q="Яке стратегічне значення Ратуші Саутшора?",a="Це один з останніх осідків законної цивільної влади Лордерона на півночі. Члени Альянсу звертаються до ратуші по вказівки, винагороди й узгодження дій проти Відступників і розбійників Синдикату, що підступають дедалі ближче.",al={"чому ратуша важлива","значення саутшора"}},{q="Хто ще працює в ратуші?",a="Поряд із Магістратом Генрі Малебом у ратуші працюють урядовці, як-от Кундрік Занден, що допомагають вести місцеві справи й підтримують життя містечка.",al={"хто в ратуші саутшора","кундрік занден","нпс ратуші"}},{q="Як ратуша підтримує зв'язки з рештою Альянсу?",a="Хоча Саутшор історично належав до королівства Лордерон, тепер містечко та його влада значною мірою покладаються на Альянс, отримуючи підкріплення й припаси, щоб боронити цей відрізаний прибережний оплот від довколишніх ворогів.",al={"чи саутшор альянсу","зв'язки зі стормвіндом"}}},fp="20,389,23.520.0,49.201.0,57.228.0,36.174.0,61.231.0"}
P.entries["subzone:southwind-village"] = {n="Село Південного Вітру",s="Село Південного Вітру — руїни застави нічних ельфів серед пісків Силітусу, де живуть привиди. Кіражі стерли його з лиця землі під час Війни Мінливих Пісків, і тепер його вулицями блукають неспокійні духи полеглих захисників, а довкола нишпорять силітиди.",h="Село Південного Вітру — руїни застави нічних ельфів серед пісків Силітусу, де живуть привиди.",kw={"село південного вітру","вальстанн стаґгелм","війна мінливих пісків","кіражі","привиди","силітус"},ang={["class:Druid"]="Зруйновані споруди, схожі на гаї, і змучені духи давніх друїдів, що лишилися в Селі Південного Вітру, — похмуре нагадування про те, що втратила природа в боротьбі з ордами комах.",["race:NightElf"]="Для нічних ельфів Село Південного Вітру — одна з найболісніших поразок у їхній історії, а змучені привиди, що блукають його розваленими мурами, — це їхні побратими-калдореї, які досі чекають на спокій."},sec={{t="Трагедія в пісках",b="Тисячу років тому, під час прадавньої Війни Мінливих Пісків, Село Південного Вітру було однією з головних твердинь нічних ельфів. Коли легіони кіражів прорвали оборону, Вальстанн Стаґгелм — син архідруїда Фандрала Стаґгелма — повів загін, щоб утримати село. Оборона завершилася цілковитою катастрофою: захисників-калдореїв здолали й вирізали, а самого Вальстанна забрав у полон Генерал Раджакс. Село зруйнували вщент, і від колишніх будівель під пекучим сонцем лишилися самі уламки."},{t="Змучені мерці",b="Минуло тисячоліття, відколи село впало, а воно й досі — відкрита рана пустелі. Жах того нападу був такий нестерпний, що духи вбитих Вартових і друїдів з нічних ельфів не змогли піти далі. Збожеволілі від жаху своїх останніх миттєвостей, ці неспокійні привиди на чолі з Примарою Ембермуна без кінця блукають серед розвалених кам'яних мурів і кидаються на кожного, хто їх потривожить, а в дюнах довкола рояться хижі силітиди."}},faq={{q="Що сталося з Селом Південного Вітру?",a="Село Південного Вітру знищено тисячу років тому під час Війни Мінливих Пісків. Ненажерливе військо кіраджі заполонило гарнізон нічних ельфів, безжально вирізало захисників і зрівняло заставу з землею.",al={"чому село південного вітру зруйноване","лор південного вітру","що знищило село південного вітру"}},{q="Хто такий Валстанн Стаґгелм?",a="Валстанн Стаґгелм — улюблений син Верховного друїда Фандрала Стаґгелма. Він очолив відчайдушну оборону Села Південного Вітру від комашиної навали, але його військо було знищене, а самого його полонив командир кіраджі Генерал Раджакс.",al={"валстанн стаґгелм південний вітер","син фендрала стаґгелма","хто обороняв південний вітер"}},{q="Чому тут привиди нічних ельфів?",a="Раптова й жорстока різанина захисників замкнула їхні душі в руїнах. Духи вбитих друїдів і Вартових приречені вічно переживати свою останню, моторошну битву, а над ними досі нависає Примара Ембермуна.",al={"духи південного вітру","чому в південному вітрі привиди","тінь бурштинового місяця"}},{q="Чи пов'язані ці комахи з тим, що знищило село?",a="Так. Силітиди, що роються довкола руїн, — частина тієї самої комашиної навали, пов'язаної з кіраджі, тієї сили, що століття тому вдерлася в Силітус і знищила заставу.",al={"силітиди південний вітер","чи комахи пов'язані з південним вітром"}}},fp="17,249,22.540.0,18.438.0,35.214.0,26.242.0,36.239.0,51.183.0"}
P.entries["subzone:spirit-rise"] = {n="Узвишшя Духів",s="Узвишшя Духів — північно-західна столова гора Тандер Блафа, головне святилище тауренської столиці для духовних і шаманських студій. Тут, під опікою духовних провідників на кшталт племені Скайчейсер, нагорі стоять священні зали навчання, а внизу печера спускається до Ставків Видінь.",h="Узвишшя Духів — північно-західна столова гора Тандер Блафа, головне святилище тауренської столиці для...",kw={"узвишшя духів","тандер блаф","шамани","ставки видінь","зала духів","стихії"},ang={["class:Shaman"]="Для шаманів Орди Узвишшя Духів — важливе місце збору: тут можна порадитися з наставниками, провести стихійні обряди й поєднатися з духами предків.",["race:Tauren"]="Узвишшя втілює глибоке духовне коріння вашого народу й дарує розраду від мирських обов'язків поруч із містичними водами Ставків Видінь."},sec={{t="Святилище духів",b="Узвишшя Духів, що височіє над рівнинами Малгору, віддане єднанню зі стихіями й духами предків. З'єднане з центральною горою мотузяними мостами, воно прихищає Залу Духів і павільйон Духовного зцілення, де молоді й бувалі шамани збираються, щоб поглибити зв'язок із землею, повітрям, вогнем і водою. Плем'я Скайчейсер має на узвишші помітну присутність і веде шукачів давніми традиціями."},{t="Печери й переходи",b="Під продуваними вітром хатинами й тотемними святинями просто неба вхід веде вглиб самої гори — до сповнених пари Ставків Видінь, священної підземної печери, де провидці вдивляються у води, яких торкнулися духи."}},faq={{q="Чим славиться Узвишшя Духів?",a="Узвишшя Духів — духовне серце Тандер Блафа, присвячене насамперед шаманським практикам, зціленню й спілкуванню з духами природи та предків. Тут же вхід до Ставків Видінь.",al={"що таке узвишшя духів","призначення узвишшя духів","навіщо йти на узвишшя духів"}},{q="Яке плем'я тауренів верховодить на Узвишші Духів?",a="Тут має помітний вплив плем'я Скайчейзерів, що плекає духовні традиції, обряди ворожіння й навчання шаманів, якими славиться це узвишшя.",al={"хто керує узвишшям духів","плем'я узвишшя духів","плем'я небоходців"}},{q="Що можна знайти під Узвишшям Духів?",a="Спуск крізь узвишшя веде до Ставків Видінь — вологої підземної печери з гарячими водами, де провидці й духовні практики медитують і шукають видінь.",al={"печера узвишшя духів","що під узвишшям духів","вхід у ставки видінь"}}},fp="11,286,26.464.0,19.201.0,30.207.0,51.151.0,39.181.0"}
P.entries["subzone:spirit-rock"] = {n="Камінь Духів",s="Камінь Духів — священна скеля на суворих кручах над Долиною Випробувань у Дуротарі. Дістатися до неї можна звивистою стежкою, відомою як Прихована Стежка; це відлюдне святе місце, де посвячувані безпосередньо спілкуються зі стихійними силами землі.",h="Камінь Духів — священна скеля на суворих кручах над Долиною Випробувань у Дуротарі.",kw={"камінь духів","шамани","духи землі","сапта","прихована стежка","долина випробувань","дуротар"},ang={["class:Shaman"]="Камінь Духів — важливий обряд посвяти для молодих шаманів з орків і тролів, які піднімаються Прихованою Стежкою, щоб випити Земляну Сапту й укласти перший зв'язок із духами каменю та ґрунту."},sec={{t="Святилище стихій",b="Над червоним каньйоном, де молоді воїни та розвідники Орди починають навчання, Камінь Духів стоїть як вівтар єднання з духами. Відокремлений від гамору Долини Випробувань, він доступний лише Прихованою Стежкою, що в'ється скелястим гребенем. Майбутні шамани здійснюють паломництво до цього пустельного виступу, щоб випити традиційну сапту й, пронизавши завісу тілесного світу, почути гуркіт і шепіт самої землі."}},faq={{q="Для чого потрібен Камінь Духів?",a="Камінь Духів — священне місце, куди приходять здебільшого шамани-початківці Орди. Випивши біля каменя особливий напій — Земляну Сапту, — новачки здобувають духовний зір, потрібний, щоб безпосередньо спілкуватися з духами землі.",al={"призначення каменя духів","що відбувається біля каменя духів","навіщо камінь духів"}},{q="Як дістатися до Каменя Духів?",a="Камінь Духів — високо в скелях над Долиною Випробувань на південному заході Дуротару. Потрапити туди можна Прихованою Стежкою — вузькою непозначеною стежкою, що в'ється з дна каньйону в скелясті пагорби.",al={"як дістатися до каменя духів","шлях до каменя духів","розташування каменя духів"}},{q="Що таке сапта?",a="Сапта — обрядовий стихійний напій, який готують наставники шаманів. Випивши його, шукач бачить світ інакше й може помічати прояви стихій, невидимі для звичайних чуттів.",al={"земна сапта","що таке сапта","напій сапта"}}},fp="11,255,27.445.0,29.236.0,29.217.0,16.204.0"}
P.entries["subzone:splinterspear-junction"] = {n="Роздоріжжя Щербатого Списа",s="Роздоріжжя Щербатого Списа — стратегічна розвилка головної дороги, що в'ється серцем Болота Скорботи. Над нею височіє груба орківська сторожова вежа, а довкола регулярно патрулюють вартові Орди. Тут шлях розходиться: на північ — до відлюдних прихистків, на південь — до застав.",h="Роздоріжжя Щербатого Списа — стратегічна розвилка головної дороги, що в'ється серцем Болота Скорботи.",kw={"роздоріжжя щербатого списа","сторожова вежа","стонард","перша війна","кірос","болото скорботи"},ang={["faction:Alliance"]="Будьте обережні біля роздоріжжя: орківську сторожову вежу пильно охороняють вартові Орди, готові порубати кожного непроханого гостя, що забреде сюди з Даркширу.",["faction:Horde"]="Сторожова вежа на роздоріжжі — важливий орієнтир і пункт охорони, коли ви подорожуєте між Стонардом і північними куточками болота."},sec={{t="Перехрестя ворожнечі",b="Роздоріжжя Щербатого Списа, що лежить поблизу центру Болота Скорботи, розводить мандрівників двома шляхами: північна стежка веде до Притулку, сховку зламаних дренеїв, і до Занедбаного Святилища, а південна дорога біжить просто повз фортецю Стонард туди, де починаються Спустошені Землі. Над розвилкою здіймається прадавня орківська сторожова вежа з гарнізоном і дозорами Орди. Для воїнів Орди це надійний орієнтир серед підступного болота, а для мандрівників з Альянсу — смертельна пастка на й без того немилосердному шляху."},{t="Відлуння Кіроса",b="Задовго до того, як на нинішній вежі з'явилася варта, це місце мало гірке військове значення. Під час Першої війни тут стояв орківський табір Кірос — найближчий опорний пункт Орди, що загрожував людському поселенню Велике Селище. Стормвінд раз у раз посилав на болото ударні загони, щоб знищити цю заставу. Серед полеглих у тих сутичках був і лейтенант Блейк Ґодвін, лицар із Лордерону, чиї останки й родовий меч поглинула трясовина."}},faq={{q="Куди ведуть дороги з Роздоріжжя Щербатого Списа?",a="Дорога розгалужується на два окремі шляхи. Північна гілка веде повз Притулок — прихисток дренеїв — до Занедбаного Святилища, а південна спрямовує мандрівників на південь, до Стонарда, і далі — у спечені пустки Спустошених Земель.",al={"куди ведуть дороги","шляхи щербатого списа","який шлях на щербатому спису"}},{q="Чи безпечне Роздоріжжя Щербатого Списа для мандрівників Альянсу?",a="Ні. Роздоріжжя тримає Орда: тут укріплена сторожова вежа й регулярні патрулі довкола перехрестя. Ці вартові відверто ворожі до Альянсу й одразу кидаються в бій із заїжджими шукачами пригод.",al={"чи безпечний щербатий спис для альянсу","чи вартові ворожі","пвп щербатого списа"}},{q="Що таке Кайросс?",a="Кайросс — оркська військова застава, збудована саме на цьому перехресті під час Першої війни. Вона стояла небезпечно близько до Великого Селища за кордоном, тож королівство Стормвінд раз у раз посилало в болото загони, щоб її знищити.",al={"що таке кайросс","історія кайросса","перша війна кайросс"}},{q="Хто такий Лейтенант Блейк Ґодвін?",a="Лейтенант Блейк Ґодвін — офіцер із північного королівства Лордерон, що допомагав Стормвінду в Першій війні. Він загинув у запеклих боях довкола застави Кайросс, і його поховали десь серед довколишніх боліт разом із родовим клинком.",al={"блейк ґодвін","власник родового меча","лицар лордерона на болоті"}}},fp="22,259,24.581.0,16.508.0,50.256.0,54.222.0,16.236.0,32.290.0"}
P.entries["subzone:splintertree-post"] = {n="Застава Розщепленого Дерева",s="Застава Розщепленого Дерева — головна фортеця Орди у східному Ашенвалі, на північний захід від Пагорба Вогню Скверни. Заснована Ґроммашем Хеллскрімом і кланом Бойової Пісні під час Третьої війни, вона слугує потужно укріпленим оплотом проти нічних ельфів і плацдармом для захоплення нових земель.",h="Застава Розщепленого Дерева — головна фортеця Орди у східному Ашенвалі, на північний захід від Пагорба Вогню...",kw={"застава розщепленого дерева","орда","бойова пісня","ґроммаш хеллскрім","фортеця","ашенваль"},ang={["faction:Horde"]="Застава Розщепленого Дерева — головний табір для шукачів пригод, що пробиваються крізь Ашенваль: тут можна полагодити спорядження, перепочити й вирушити в політ до інших куточків Калімдору.",["race:NightElf"]="Для нічних ельфів ця фортеця — гіркий шрам на тілі Ашенвалю: її заснував той самий воєначальник, що вбив Кенарія, а тримають загарбники, які рубають їхні прадавні дерева."},sec={{t="Прикордонна твердиня",b="Застава Розщепленого Дерева, вирубана просто в прадавньому лісі, — головний військовий і постачальний осередок Орди у східному Ашенвалі. Її заснували Ґроммаш Хеллскрім і клан Бойової Пісні, коли орки вперше вдерлися в ліс під час Третьої війни, і вона досі лишається добре озброєним анклавом, який обороняють переважно розвідники й воїни — орки та таурени. Тут є господар вітрокрилів, корчма й надійні шляхи постачання до Оргріммара, тож застава — опора спірної присутності Орди під кронами лісу."},{t="Постійна загроза відплати",b="Застава Розщепленого Дерева живе в постійній готовності. Нічні ельфи не забули й не пробачили Ґроммашеві того, що він накоїв під час війни, і не миряться з орківськими вирубками та набігами на Астранаар. Тож поселення раз у раз зазнає відплатних ударів і партизанських нападів Вартових, що ховаються в довколишньому лісі, і вартові гарнізону не мають спокою ні вдень, ні вночі."}},faq={{q="Хто заснував Заставу Розщепленого Дерева?",a="Її заснували Ґроммаш Хеллскрім і клан Бойової Пісні, коли орки під час Третьої війни вперше вдерлися в Ашенваль, щоб заготовляти деревину й закріпитися тут.",al={"хто заснував розщеплене дерево","засновник розщепленого дерева","ґром розщеплене дерево"}},{q="Чому нічні ельфи так часто нападають на цю базу?",a="Нічні ельфи вважають Розщеплене Дерево незаконним і блюзнірським вторгненням на землі предків. Ворожнеча тягнеться ще від жорстоких походів Ґроммаша в Третій війні, а підживлюють її вирубка лісу Ордою й сутички з сусідньою ельфійською твердинею Астранаар.",al={"чому ельфи нападають","напади вартових на розщеплене дерево","рейди нічних ельфів"}},{q="Які зручності й можливості для подорожей тут є?",a="На Заставі Розщепленого Дерева є корчма, доглядач стайні, поштова скринька, ремонт обладунків і розпорядник польотів на вітрокрилах із маршрутами до Оргріммара, Перехрестя та інших застав Орди по всьому Калімдору.",al={"політ розщепленого дерева","послуги розщепленого дерева","корчма розщепленого дерева"}},{q="Хто зараз у гарнізоні Розщепленого Дерева?",a="Поселення населяють переважно орки й таурени — досвідчені розвідники, вартові й офіцери передової, яким доручено втримати прикордоння.",al={"охорона розщепленого дерева","хто живе в розщепленому дереві","раси розщепленого дерева"}}},fp="17,296,21.505.0,34.402.0,30.168.0,51.264.0,53.198.0,52.156.0"}
P.entries["subzone:splithoof-crag"] = {n="Круча Розколотого Копита",s="Круча Розколотого Копита — укріплене поселення кентаврів Ґалак під північними скелями Тисячі Голок. Поряд зі столовими горами це один з головних осередків племені, що стереже вхід до Твердині Розщепленого Копита. Мандрівникам, які йдуть дном каньйону, доводиться мати справу з агресивними дозорами Ґалак, що никають біля круч.",h="Круча Розколотого Копита — укріплене поселення кентаврів Ґалак під північними скелями Тисячі Голок.",kw={"круча розколотого копита","кентаври ґалак","тисяча голок","роздвоєне копито","печери","таурени"},ang={["faction:Horde"]="Контроль над проходом під кручами вкрай важливий, щоб безпечно мандрувати між південними Пустками, Заставою Вільного Вітру та Мерехтливими Низинами.",["race:Tauren"]="Через давню ворожнечу між тауренами й кентаврами Круча Розколотого Копита — нагальна турбота розвідників Орди, які стежать за ворогами по всій Тисячі Голок."},sec={{t="Твердиня Ґалак",b="Круча Розколотого Копита тулиться до прямовисної північної скельної стіни Тисячі Голок, трохи на схід від височенного Шпиля Темної Хмари. Це давній осередок кентаврів Ґалак із грубими наметовими таборами й ґрунтовими стежками, що в'ються поміж скель. У серці селища, під самою кручею, лежить Твердиня Розщепленого Копита — підземна печера, де зберігається Роздвоєне Копито, прадавня реліквія кентаврів, яку оберігає священна жаровня."},{t="Оборона печер",b="Ґалак люто обстоюють цей куток каньйону й нападають на всіх мандрівників, експедиції Орди та тауренських розвідників, які забредуть під їхні кручі. Поки Ґрімтотеми сидять на височенних шпилях неподалік, кентаври міцно тримають цей яр і печери, видовбані глибоко під каменем."}},faq={{q="Хто живе на Кручі Розколотого Копита?",a="Поселення належить племені кентаврів Ґалак — одному з помітних кланів, що живуть у Тисячі Голок поряд із ворожими тауренами-Ґрімтотемами.",al={"хто на кручі розколотого копита","моби розколотого копита","кентаври розколотого копита"}},{q="Де розташована Круча Розколотого Копита?",a="Вона лежить біля північної стіни каньйону Тисячі Голок, просто на схід від Шпиля Темної Хмари.",al={"де круча розколотого копита","розташування розколотого копита"}},{q="Що в Твердині Розщепленого Копита?",a="Твердиня Розщепленого Копита — центральна печера селища. Глибоко в її залах кентаври Ґалак стережуть Роздвоєне Копито — давній артефакт племені, захищений священним полум'ям, що палає в давній жаровні.",al={"що таке твердиня розщепленого копита","печера розколотого копита"}},{q="Чи в союзі тутешні кентаври з сусідніми Ґрімтотемами?",a="Ні. Кентаври Ґалак і таурени-Ґрімтотеми зі Шпиля Темної Хмари — запеклі суперники, що борються за панування над цією частиною каньйону.",al={"ґрімтотеми й ґалак","кентаври й таурени"}}},fp="14,336,18.447.0,21.318.0,28.145.0,32.105.0,30.196.0,54.155.0"}
P.entries["subzone:splithoof-hold"] = {n="Твердиня Розщепленого Копита",s="Твердиня Розщепленого Копита — глибока печерна твердиня, видовбана в камені Кручі Розколотого Копита в Тисячі Голок. Її тримає плем'я кентаврів Ґалак: печера править за укріплене лігво, а в ній стоїть Прадавня Жаровня, де вічно горить священне полум'я.",h="Твердиня Розщепленого Копита — глибока печерна твердиня, видовбана в камені Кручі Розколотого Копита в Тисячі...",kw={"твердиня розщепленого копита","кентаври ґалак","священне полум'я","печера","тисяча голок","жаровня"},ang={["class:Shaman"]="Вічне полум'я, що палає глибоко в темній кам'яній печері, неминуче привертає увагу кожного духовидця, налаштованого на первісні таємниці вогняної стихії.",["race:Tauren"]="Кентаври Ґалак лишаються заклятими кровними ворогами тауренів, тож будь-яка їхня твердиня в Тисячі Голок — пряма загроза спокою Застави Вільного Вітру."},sec={{t="Оплот кентаврів",b="Твердиня Розщепленого Копита, захована всередині Кручі Розколотого Копита, — укріплений сховок кентаврів Ґалак. На відміну від обвітреного дна каньйону, ця замкнена печера дає їм прихисток, вузькі проходи, які легко боронити, і надійне укриття від племен-суперників і мандрівників, що йдуть крізь Голки."},{t="Священне Полум'я",b="У темних глибинах твердині стоїть прадавня жаровня, у якій горить Священне Полум'я. Цей містичний вогонь палає без упину: для кентаврів він — осердя сили й предмет обрядового шанування, а для духовних шукачів з усього каньйону — велика загадка."}},faq={{q="Де розташована Твердиня Розщепленого Копита?",a="Твердиня Розщепленого Копита — серед круч і укріплень Кручі Розколотого Копита, біля північних скель Тисячі Голок. Вхід до неї — печера посеред головного поселення кентаврів.",al={"розташування твердині розщепленого копита","де твердиня розщепленого копита","як знайти твердиню розщепленого копита"}},{q="Хто тримає Твердиню Розщепленого Копита?",a="Печеру тримає плем'я кентаврів Ґалак, що люто боронить її від чужинців, звірів і сусідніх тауренів із Застави Вільного Вітру.",al={"хто живе в твердині розщепленого копита","моби розщепленого копита","хто володіє твердинею розщепленого копита"}},{q="Що всередині твердині?",a="Окрім ворожих захисників-кентаврів Ґалак, у печері стоїть Давня Жаровня — артефакт, що підтримує вічне горіння містичного Священного Полум'я в глибині скелі.",al={"що в твердині розщепленого копита","де давня жаровня","священне полум'я розщепленого копита"}}},fp="14,255,17.285.0,16.278.0,32.203.0,28.156.0,24.174.0"}
P.entries["subzone:stagalbog"] = {n="Стаґалбоґ",s="Стаґалбоґ — густа, просякнута водою смуга трясовини на півдні Болота Скорботи. Вона межує з південним гірським пасмом трохи нижче від Ставка Сліз і досі лишається неприборканою глушиною.",h="Стаґалбоґ — густа, просякнута водою смуга трясовини на півдні Болота Скорботи.",kw={"стаґалбоґ","болото скорботи","ставок сліз","трясовина","травництво","затонулий храм"},ang={["class:Hunter"]="Тихі смуги між болотяною водою й гірськими кручами роблять Стаґалбоґ чудовим місцем, щоб вистежувати місцевих болотяних звірів.",["profession:Herbalism"]="Волога земля Стаґалбоґу, куди майже не зазирає сонце, — чудове місце для болотяних рослин, які процвітають подалі від протоптаних стежок."},sec={{t="Південна трясовина",b="Стаґалбоґ, що простягається в тіні південних скель, — типовий куточок Болота Скорботи: стояча вода, похилений очерет і сплутані зарості. Він лежить одразу на південь від затонулих руїн Храму Атал'Гаккара, затиснутий між оскверненим озером і скелястою межею краю. Окрім дикої звірини, тут немає нічого — цивілізація так і не закріпилася в цих місцях."},{t="У тіні храму",b="Стаґалбоґ межує зі Ставком Сліз, тож сюди часто докочуються тіні й скверна, що просочуються із Затонулого Храму."}},faq={{q="Де розташований Стаґалбоґ?",a="Стаґалбоґ лежить у південній частині Болота Скорботи, просто на південь від Ставка Сліз, і тягнеться вздовж підніжжя південного гірського хребта.",al={"розташування стаґалбоґа","де стаґалбоґ","як знайти стаґалбоґ"}},{q="Які загрози блукають цим болотом?",a="На болоті живуть місцеві болотяні звірі й хижі створіння.",al={"моби стаґалбоґа","монстри стаґалбоґа"}}},fp="9,206,17.378.0,20.131.0,31.174.0,44.72.0"}
P.entries["subzone:stagalbog-cave"] = {n="Печера Стаґалбоґ",s="Печера Стаґалбоґ — волога підземна печера в Стаґалбоґу, на сході Болота Скорботи. Тут облаштували укріплене лігво болотяні мурлоки та їхній зловісний духовний провідник — Болотний Мовець.",h="Печера Стаґалбоґ — волога підземна печера в Стаґалбоґу, на сході Болота Скорботи.",kw={"печера стаґалбоґ","мурлоки","болотний мовець","болотяне плем'я","болото скорботи"},sec={{t="Лігво Болотяного племені",b="Печера Стаґалбоґ, що ховається в похмурих східних драговинах Болота Скорботи, захищає місцевих мурлоків від невпинних болотяних дощів. Ці земноводні створіння, відомі як Болотяне плем'я, ревно стережуть звивисті печерні зали разом зі своїм верховним містиком — Болотним Мовцем. Мандрівники, що підходять до потопленої трясовини Стаґалбоґу, часто чують, як їхні булькітливі поклики луною розлітаються над моховитими берегами, відганяючи чужинців від гнізд."}},faq={{q="Що таке Печера Стаґалбоґ?",a="Печера Стаґалбоґ — природна печера в Стаґалбоґу, на сході Болота Скорботи. Її здебільшого займає люте поселення мурлоків Болотного племені.",al={"де печера стаґалбоґ","що в печері стаґалбоґ"}},{q="Хто править печерою?",a="У печері панує Болотне плем'я та його ватажок — Болотний Мовець, впливовий мурлок-містик, що наглядає за обрядами й обороною племені у вологих печерних залах.",al={"бос печери стаґалбоґ","болотяний мовець","хто веде мурлоків"}},{q="Чи є поблизу дружні поселення?",a="Печеру оточують дикі, ворожі болота. Проте в ширшому Болоті Скорботи на заході стоїть застава Орди Стонард, а нейтральні мандрівники й гобліни часом розвідують довколишні водойми.",al={"найближче містечко","торговці біля стаґалбоґа"}}},fp="14,228,22.480.0,23.177.0,19.179.0,38.216.0"}
P.entries["subzone:staghelm-point"] = {n="Мис Стаґгелма",s="Мис Стаґгелма — прадавня сторожова вежа нічних ельфів на скелястій вершині в північно-східному Силітусі. Звідси видно дюни, що наступають, і недалекі печери Сутінкового Проходу, тож вежа несе варту проти прадавніх загроз, що чигають у пустелі.",h="Мис Стаґгелма — прадавня сторожова вежа нічних ельфів на скелястій вершині в північно-східному Силітусі.",kw={"мис стаґгелма","силітус","сутінковий прохід","рало'шан","війна мінливих пісків","калдореї"},ang={["class:Druid"]="Вежа носить ім'я Стаґгелмів і дає змогу в задумі споглядати зіпсований посушливий дикий край, що кидає виклик рівновазі природи.",["race:NightElf"]="Мис Стаґгелма пробуджує урочисту пам'ять про Війну Мінливих Пісків і суворо нагадує, якою тяжкою ціною калдореї стримали жахіття, що ховаються під Силітусом."},sec={{t="Мовчазна варта над пісками",b="Мис Стаґгелма, що високо здіймається над посушливими рівнинами північно-східного Силітусу, увінчує самотня вежа нічних ельфів. Застава — наче самотній вартовий, що стежить за пустелею й за культистами, які ховаються в тінях сусідніх печер на кшталт Сутінкового Проходу. Вежу стереже Рало'шан Вічний Вартовий, а над нею кружляє бронзовий дракон. Вона носить горде й трагічне ім'я роду Стаґгелмів — нагадування про величезні жертви, яких калдореї зазнали під час прадавньої Війни Мінливих Пісків."}},faq={{q="Хто живе на Мисі Стаґгелма?",a="Самотню вежу стереже Рало'шан Вічний Вартовий, а в небі над нею безупинно патрулює величний бронзовий дракон із Виводку Ноздорму.",al={"хто на мисі стаґгелма","нпс мису стаґгелма","рало'шан"}},{q="Які небезпеки чатують поблизу?",a="Унизу, куди в'ється стежка від вершини, лежить Сутінковий Прохід — печера з табором довкола, що кишать фанатиками культу Молота Присмерку.",al={"небезпеки мису стаґгелма","вороги поблизу","сутінковий прохід"}}},fp="14,257,30.531.0,28.165.0,24.154.0"}
P.entries["subzone:stagnant-oasis"] = {n="Застояна оаза",s="Застояна оаза — одна з цінних водойм у посушливому серці Пусток, між Золотим Шляхом і Узбережжям Крамарів. Оточена буйними пальмами й захоплена кентаврами Колкарами, вона своїми каламутними водами й берегами живить своєрідних місцевих звірів, зокрема черепах-хижощелепів і мандрівних кодо.",h="Застояна оаза — одна з цінних водойм у посушливому серці Пусток, між Золотим Шляхом і Узбережжям Крамарів.",kw={"застояна оаза","колкари","кодо","девіантна риба","оаза","пустки"},ang={["faction:Horde"]="Для гінців і розвідників Орди, що мандрують між Перехрестям і Тауражо, табори кентаврів біля оази — постійна загроза для руху припасів Золотим Шляхом.",["profession:Cooking"]="У водах Застояної оази водиться рідкісна Девіантна Риба — неодмінний інгредієнт для Смачних Девіантних Делікатесів."},sec={{t="Каламутний прихисток серед посухи",b="Застояна оаза, що сховалася на схід від Золотого Шляху й углиб суходолу від Узбережжя Крамарів, — важливий зелений куточок серед курних чагарників Пусток. Як і сусідні води, ставок живить густу зелень і агресивних черепах-хижощелепів, а ослаблені кодо Пусток часто забрідають сюди, відбившись від величезних стад Поля Велетнів. Проте мандрівникам варто бути обережними: кентаври Колкари тримають табори на берегах і люто бережуть право на воду від кожного, хто зайде на їхню землю."},{t="Дивні води",b="Попри застійний вигляд, ставок кишить незвичайним водним життям, зокрема дивними мутантами на кшталт Девіантної Риби. Учені й шамани пильно стежать за оазами Пусток, вивчаючи дивні сили, що впливають на місцеві джерела й на звірів, які з них п'ють."}},faq={{q="Де розташована Застояна оаза?",a="Застояна оаза лежить у південно-центральній частині Пусток, на схід від Золотого Шляху й на захід від круч, що тягнуться вздовж Узбережжя Крамарів.",al={"розташування застояної оази","де застояна оаза","як знайти застояну оазу"}},{q="Хто тримає Застояну оазу?",a="Довкола ставка отаборилися кочові кентаври-Колкари. Крім кентаврів, у зелені навколо блукають небезпечні звірі — оазові хапозуби й самотні мандрівні кодо.",al={"хто живе в застояній оазі","кентаври застояної оази","вороги застояної оази"}},{q="Чому на тутешніх кодо легше полювати?",a="На відміну від величезних згуртованих стад, що пасуться південніше на Полі Велетнів, кодо біля Застояної оази — самітники, часто ослаблені чи відбиті від стада, тож мисливцям і мандрівникам значно легше їх уполювати.",al={"загублені кодо пустовиськ","кодо застояної оази","полювання на кодо"}},{q="Яку рибу можна зловити в ставку?",a="Рибалки можуть виловити з каламутного ставка Девіантну Рибу — незвичний улов, з якого готують делікатеси, цінувані по всьому Калімдору.",al={"риболовля застояної оази","збочена риба застояної оази","рибалити в застояній оазі"}},{q="Чи бував Тралл у цій оазі під час Довгого Походу?",a="Поширена думка, що Застояна оаза була одним із трьох водопоїв, які забезпечили собі Тралл і щойно прибула Орда, коли разом із Кайрном Бладгуфом ішли Пустками.",al={"тралл застояна оаза","довгий похід оаза","оаза з варкрафта 3"}}},fp="14,329,28.530.0,14.291.0,36.151.0,32.208.0,38.221.0,44.135.0,50.186.0"}
P.entries["subzone:starbreeze-village"] = {n="Село Зоряного Вітерця",s="Село Зоряного Вітерця — покинуте поселення нічних ельфів на схід від Доланаара на Тельдрассилі. Колись тихе лісове сільце, воно нещодавно дісталося збожеволілим фурболгам племені Вузлошкірів. Зруйноване поселення тепер стоїть як кричущий символ скверни, що просочується в коріння Світового Дерева.",h="Село Зоряного Вітерця — покинуте поселення нічних ельфів на схід від Доланаара на Тельдрассилі.",kw={"село зоряного вітерця","покинуте село","фурболги","вузлошкіри","фероцитас","урусон","тельдрассил"},ang={["class:Druid"]="Божевілля, що пожирає фурболгів-Вузлошкірів, і осквернення Села Зоряного Вітерця — прямий виклик обов'язку Кола Кенарія відновити рівновагу живності Тельдрассила.",["race:NightElf"]="Бачити, як ельфійське поселення так близько до Доланаара обертається на руїну, — болісне нагадування про хистке становище Тельдрассила й скверну, що гризе Світове Дерево."},sec={{t="Занепале сільце",b="Село Зоряного Вітерця, що лежить на південний схід від Тінедолу, просто за дорогою від Доланаара, колись було домівкою мирних родин нічних ельфів під гіллям Тельдрассила. Сьогодні село в руїнах, а його дерев'яні будівлі заполонили агресивні фурболги-Вузлошкіри. Здичавілі від лиховісної скверни, що вразила гілля Світового Дерева, звіролюди вигнали ельфійських мешканців і тепер люто боронять зруйновані землі."},{t="Загроза Фероцитаса",b="Присутність Вузлошкірів у селі — не звичайний територіальний наскок. На околиці поселення чаїться Фероцитас, Пожирач Снів — загадкова зіпсута сутність, чия присутність свідчить, що фурболгів зводить з розуму темна, нечиста магія. Разом із такими здоровенними звірами, як Урусон, що нишпорить стежками, ці загарбники роблять Село Зоряного Вітерця справжньою небезпекою для мандрівників східного Тельдрассила."}},faq={{q="Чому Село Зоряного Вітерця покинуте?",a="Село захопили, коли фурболги-Вузлошкіри стали жертвою скверни, що розповзається Тельдрассилом. Збожеволілі й люті, фурболги напали на мешканців — нічних ельфів, — і тим довелося тікати, покинувши свої домівки.",al={"що сталося з зоряним вітерцем","чому зоряний вітерець зруйнований","зоряний вітерець порожній"}},{q="Хто тепер живе в Селі Зоряного Вітерця?",a="Нині в селі отаборилися ворожі фурболги-Вузлошкіри. Серед помітних постатей — Урусон, що блукає довкола з патрулем, і зіпсована істота, відома як Фероцитас, Пожирач Снів.",al={"хто в зоряному вітерці","моби зоряного вітерця","хто захопив зоряний вітерець"}},{q="Де розташоване Село Зоряного Вітерця?",a="Село Зоряного Вітерця лежить на сході Тельдрассилу, на південний схід від Тінедолу й на схід від Доланаару.",al={"де зоряний вітерець","зоряний вітерець на мапі","як знайти зоряний вітерець"}},{q="Хто такий Фероцитас, Пожирач Снів?",a="Фероцитас — небезпечна зіпсована істота на околицях Села Зоряного Вітерця, пов'язана з темними силами, що доводять місцеве плем'я Вузлошкірів до шаленства.",al={"лор фероцитаса","хто такий фероцитас","фероцитас зоряний вітерець"}}},fp="18,322,15.444.0,23.426.1,36.225.0,36.174.0,36.104.0,33.169.0"}
P.entries["subzone:starfall-village"] = {n="Селище Зорепаду",s="Селище Зорепаду — тихий притулок нічних ельфів, що затишно вмостився біля засніженої дороги у Вінтерспрінгу. Це єдиний аванпост Альянсу в скутій морозом долині: тут знаходять дах над головою й припаси ті, хто наважився кинути виклик лютому північному холоду. А ще селище пильнує сусіднє курганне лігво.",h="Селище Зорепаду — тихий притулок нічних ельфів, що затишно вмостився біля засніженої дороги у Вінтерспрінгу.",kw={"селище зорепаду","вінтерспрінг","альянс","нічні ельфи","курганне лігво","евірлук"},ang={["faction:Alliance"]="Селище Зорепаду — єдине поселення Альянсу у Вінтерспрінгу, тож у цьому підступному й віддаленому гірському краї саме тут ви зможете перепочити, придбати товари й розпитати дорогу.",["race:NightElf"]="Для нічних ельфів Зорепад — важливий північний аванпост, що стоїть біля тихого, безлюдного курганного лігва."},sec={{t="Прихисток Альянсу серед снігів",b="Селище Зорепаду лежить на північний захід від гоблінського торговельного містечка Евірлук і на південь від Каменю Морозних Шаблезубів. Це єдиний оплот цивілізації Альянсу у Вінтерспрінгу. Складене з традиційних дерев'яних осель нічних ельфів, поселення править за пристанище для подорожніх: тут можна поповнити конче потрібні припаси й погрітися біля теплого вогнища, сховавшись від суворої гірської негоди. Попри мирний вигляд, селище завжди насторожі, адже поруч із ним — тихе, безлюдне курганне лігво."}},faq={{q="Що таке Селище Зорепаду?",a="Селище Зорепаду — анклав нічних ельфів у Вінтерспрінгу. Це головний прихисток і табір постачання Альянсу в долині: тут є нічліг, торгівля й настанови для розвідників, що прямують до Каменя Морозних Шаблезубів чи досліджують сусідні курганні лігва.",al={"зорепад","містечко зорепад","що це за місце"}},{q="Чи можуть гравці Орди користуватися послугами Селища Зорепаду?",a="Ні. Селище Зорепаду служить лише нічним ельфам і Альянсу. Мандрівників Орди, що забредуть надто близько, місцеві захисники зустрінуть вороже.",al={"чи дружній зорепад до орди","чи орда може користуватися зорепадом","селище зорепаду орда"}},{q="Що за курганне лігво біля селища?",a="Печера просто за селищем — порожнє курганне лігво. Такі прихистки зазвичай дають сховок друїдам, поки їхні духи мандрують Смарагдовим Сном, але тут не спить жоден друїд.",al={"курганне лігво зорепаду","печера біля зорепаду"}},{q="Де розташоване Селище Зорепаду?",a="Селище стоїть біля головної засніженої дороги через Вінтерспрінг, на північний захід від гоблінського поселення Евірлук і на південь від Каменя Морозних Шаблезубів.",al={"розташування зорепаду","як дістатися до зорепаду","де зорепад"}}},fp="16,277,30.476.0,25.269.0,56.168.0,43.185.0,34.157.0"}
P.entries["subzone:steamwheedle-port"] = {n="Порт Стімвідла",s="Порт Стімвідла — гамірна прибережна застава на східному березі Танарісу, напряму пов'язана з Ґаджетзаном. Ним керує нейтральний картель Стімвідл, і порт править за важливий морський зв'язок із далекими островами на кшталт Кезану, водночас постійно відбиваючись від Піратів Південних морів, що підступають дедалі ближче.",h="Порт Стімвідла — гамірна прибережна застава на східному березі Танарісу, напряму пов'язана з Ґаджетзаном.",kw={"порт стімвідла","картель стімвідл","кезан","пірати південних морів","ґаджетзан","танаріс"},ang={["class:Rogue"]="Постійні тертя між гоблінськими купцями й сусідніми Піратами Південних морів відкривають прибуткові можливості для кишенькових злодіїв, розвідників і тих, хто береться повертати вкрадене за винагороду.",["profession:Engineering"]="Порт — неоціненний склад деталей і припасів, завезених прямо з Кезану, тож це природний осередок пліток і креслень для майстрів-механіків."},sec={{t="Брама на мінливих пісках",b="Порт Стімвідла, що тулиться до дюн на березі Південних Морів, дає пустельному місту Ґаджетзан у глибині суходолу прямий вихід до морської торгівлі. Поселенням керує картель Стімвідл, і тут вирує життя: портові робітники, торговці й капітани, що зважуються ходити підступними водами. Кораблі постачання регулярно курсують між портом і далекими гоблінськими твердинями, зокрема Кезаном, привозячи на південь Калімдору цінні механічні деталі, предмети розкоші й сировину."},{t="Пірати й дивні вчені",b="Життя в порту аж ніяк не мирне. Трохи південніше вздовж узбережжя лежить Бухта Загублених такелажників — лігво зухвалих Флібустьєрів Південних морів, які регулярно грабують гоблінські судна, крадуть вантажі й оспорюють владу над узбережжям. Окрім портових вантажників, що торгуються за кожну монету, і знервованих купців, які намагаються повернути вкрадені вантажі, порт дає прихисток і незвичним мандрівникам — як-от загадковому тролеві на ім'я Єх'кінья, що подалі від сторонніх очей вивчає прадавніх і зловісних духів світу."}},faq={{q="Хто тримає Порт Стімвідла?",a="Поселення збудував і ним керує картель Стімвідл — головне торговельне об'єднання нейтральних гоблінів. Доки ви в добрих стосунках із Ґаджетзаном і Картелем, тут радо приймають мандрівників і Альянсу, і Орди.",al={"хто володіє портом стімвідла","фракція порту стімвідла","чи дружній порт стімвідла"}},{q="Куди ходять кораблі з цього порту?",a="Порт — морський зв'язок Картелю через Південні Моря: звідси ходять кораблі, зокрема, до острова Кезан та інших торгових осередків краю, проте пасажирських рейсів для шукачів пригод він не має.",al={"куди пливуть кораблі зі стімвідла","поромна переправа стімвідла"}},{q="Чому поблизу так багато піратів?",a="Флібустьєри Південних морів облаштували свою базу трохи на південь, у Бухті Загублених такелажників. Вони часто захоплюють вантажі, що прибувають, грабують припаси на причалах і полюють на тих, хто відстав, уздовж берега, — це головна місцева загроза гоблінській торгівлі.",al={"пірати бухти загублених такелажників","пірати південних морів танаріс"}},{q="Хто такий Єх'кінья?",a="Єх'кінья — дивакуватий троль-учений, що зупинився в порту. Він наймає відчайдушних шукачів пригод, щоб ті вирушили в далекі краї й зловили духовні сутності — як-от верескунів із Фераласу, — для досліджень забутих первісних обрядів.",al={"призначення єх'кіньї","троль у порту стімвідла"}}},fp="17,282,31.468.0,28.464.0,31.238.0,41.226.0,37.237.0,17.212.0"}
P.entries["subzone:steelgrill-s-depot"] = {n="Склад Стілґрила",s="Склад Стілґрила — гамірна інженерна майстерня й ремонтна станція просто на схід від Хараноса в Дун Мороґу. Під наглядом Белдіна Стілґрілла та його бригади майстрів вона служить передовим осередком обслуговування машин, постачання для тінкерів і збору брухту.",h="Склад Стілґрила — гамірна інженерна майстерня й ремонтна станція просто на схід від Хараноса в Дун Мороґу.",kw={"склад стілґрила","інженерія","майстерня","белдін стілґрілл","харанос","дун мороґ"},ang={["profession:Engineering"]="Склад — лабораторія просто неба, оточена паровими машинами й припасами для майстрування, тож для інженерів-початківців, що мандрують Дун Мороґом, це природне місце перепочинку.",["race:Gnome"]="Тісно співпрацюючи з дворфськими господарями, гномські тінкери-вигнанці часто користуються вогнями кузні складу та запасними деталями, щоб їхні врятовані механізми не зупинялися."},sec={{t="Оплот пари та сталі",b="Склад Стілґрила трохи осторонь засніженої дороги на схід від Хараноса гуде брязкотом металу, шипінням парових клапанів і гулом дослідних двигунів. Дворфські шахтарі та дивакуваті гноми-інженери збираються тут серед важкої техніки, крокуючих механізмів і купи сирої руди, вивезеної з сусідніх кар'єрів. Поки Дун Мороґ потерпає від невпинних безчинств трогів і нестачі деталей, Белдін Стілґрілл зі своєю бригадою підтримує машини Альянсу в робочому стані, тож для мандрівників, яким на лютому морозі потрібні запчастини чи технічна порада, склад — незамінна зупинка."}},faq={{q="Що таке Склад Стілґрила?",a="Склад Стілґрила — інженерна майстерня й застава в Дун Мороґу, трохи далі дорогою на схід від Хараноса. Тут обслуговують рудокопів, майстрів і польових техніків, що доглядають важкі машини.",al={"склад стілґрила","що це за місце","стілґрили"}},{q="Хто керує складом?",a="Складом керує родина Стілґрилів, зокрема Белдін Стілґрілл, разом з іншими дворфійськими й гномськими майстрами, що доглядають довколишні машини й наглядають за видобутком.",al={"хто керує стілґрилом","лідер складу стілґрила","белбі стілґрил"}},{q="Які послуги тут є?",a="На складі є крамарі, ремонт і наставники для ремісників, які хочуть удосконалити свою інженерну майстерність і вміння збирати ресурси в польових умовах.",al={"наставники стілґрила","що тут можна робити","послуги складу стілґрила"}}},fp="18,272,28.601.0,27.200.0,19.189.0,33.150.0"}
P.entries["subzone:stendel-s-pond"] = {n="Ставок Стендела",s="Ставок Стендела — невелика водойма, можливо, отруєна, на південний захід від Сентінел Гілла у Вестфолі. Довкола нишпорять гноли, поряд видніються могили, але попри зловісні небезпеки це одне з небагатьох місць у висохлому краї, де можна порибалити в прісній воді.",h="Ставок Стендела — невелика водойма, можливо, отруєна, на південний захід від Сентінел Гілла у Вестфолі.",kw={"ставок стендела","вестфол","сентінел гілл","шавлієва риба","рибальство","гноли"},ang={["faction:Alliance"]="Ставок лежить неподалік Сентінел Гілла, але через табори гнолів лишається неприборканою загрозою на південних рубежах Народного ополчення.",["profession:Cooking"]="Шавлієву рибу з цих каламутних вод цінують кухарі — для своїх рибних страв."},sec={{t="Небезпечний водопій",b="Ставок Стендела, захований на південний захід від Сентінел Гілла, дарує тиху перерву серед курних рівнин Вестфолу, хоча небезпека завжди поруч. Мулкими берегами бродять гноли, а розкидані кістяки й дві самотні могили натякають, що чи то вода, чи то звірі довкола смертельні для необачних подорожніх. Та рибалки все одно ризикують сюди ходити заради косяків шавлієвої риби."}},faq={{q="Де розташований Ставок Стендела?",a="Він лежить на південний захід від Сентінел Гілл у центрі Вестфолу, трохи збоку від курних стежок, що ведуть на південь.",al={"розташування ставка стендела","де ставок стендела","знайти ставок стендела"}},{q="Хто чатує довкола ставка?",a="Мулистими берегами ставка нишпорять гноли Річколапів, що ревно бережуть свої угіддя й нападають на кожного, хто наближається до води.",al={"хто тут живе","монстри ставка стендела","гноли ставка стендела"}},{q="Чому біля берега кістяки й могили?",a="Кістяки й дві безіменні могили свідчать про смертельні небезпеки цього місця. Чи мандрівники стали жертвами гнолів, чи отруїлися смердючою водою зі ставка, лишається зловісною таємницею.",al={"чиї це могили","чому скелети","могила біля ставка"}}},fp="14,267,25.355.0,32.117.0,36.116.0,48.177.0"}
P.entries["subzone:stillwater-pond"] = {n="Ставок Тихої Води",s="Ставок Тихої Води — тиха застояна водойма одразу на захід від Брілла в Галявинах Тірісфалю. Колись улюблене місце пікніків і купання живих дітей Лордерона, він перетворився на каламутну калюжу, де водяться кістяні риби й нишпорять небезпечні падложери.",h="Ставок Тихої Води — тиха застояна водойма одразу на захід від Брілла в Галявинах Тірісфалю.",kw={"ставок тихої води","ставок","брілл","пікніки","кістяні риби","бейн","темні гончаки","тірісфаль"},ang={["class:Hunter"]="Уражена чумою живність довкола ставка, зокрема здичавілі темні гончаки на кшталт Бейна, робить цю місцину небезпечними мисливськими угіддями для розвідників, що патрулюють околиці Брілла.",["race:Undead"]="Для Відступників, що зберегли спогади про життя в Лордероні, Ставок Тихої Води — похмуре нагадування про втрачені дитячі дні пікніків і купання на його колись прозорих берегах."},sec={{t="Зруйнований перепочинок",b="До Третьої війни й спустошень Чуми Нежиті Ставок Тихої Води був тихим прихистком для люду Галявин Тірісфалю. Родини з сусідніх сіл збиралися на його трав'янистих берегах на пообідні пікніки, а діти, замалі для підступних глибин Озера Світлої Води, вчилися плавати на його мілинах. Сьогодні ідилічні води стали мертвими й сірими. Живі давно зникли, лишивши тільки кістяних риб, що шмигають під поверхнею, і блукаючу нежить, що тиняється довколишніми лісами."},{t="Нишпорки в імлі",b="Хоч тут спокійніше, ніж на обложених дорогах і спірних фермах Тірісфалю, Ставок Тихої Води має власні небезпеки. Каламутні води напувають лише уражених чумою звірів галявин — насамперед лютого темного гончака на ім'я Бейн, що нишпорить берегом. Мандрівникам, які зрізають шлях західними луками дорогою до Брілла, слід ступати обережно: хижі звірі й безцільні зомбі часто тиняються край води."}},faq={{q="Яким був Ставок Тихої Води до чуми?",a="За часів людського Лордерона Ставок Тихої Води був мальовничим і улюбленим місцем для пікніків. Він мілкий і спокійніший за просторе Озеро Світлої Води, тож родини часто приводили сюди малечу безпечно поплавати.",al={"історія ставка тихої води","для чого був ставок тихої води","місце для плавання тіріфалю"}},{q="Чи живе тепер щось у воді?",a="Звичайні водяні мешканці не пережили отруєння Тірісфалю. Під сірою гладдю плавають лише оживлені кістяки риб, що лишилися після скверни Погибелі.",al={"риба ставка тихої води","що живе в ставку тихої води","істоти ставка тихої води"}},{q="Які небезпечні створіння блукають біля ставка?",a="Окрім безмозкої нежиті, що блукає галявинами, найгорезвісніша загроза на березі — Бейн, надзвичайно сильний і лютий темний гончак, що полює на необачних мандрівників.",al={"монстри ставка тихої води","хто такий бейн","темна гончак біля брилля"}},{q="Де розташований Ставок Тихої Води?",a="Ставок Тихої Води лежить у центрі Галявин Тірісфалю, просто на захід від містечка Брілл і на південний захід від більшого Озера Світлої Води.",al={"де ставок тихої води","розташування ставка тихої води","як знайти ставок тихої води"}}},fp="15,272,16.533.0,20.437.0,48.231.0,42.196.0,46.178.0,33.129.0"}
P.entries["subzone:stonard"] = {n="Стонард",s="Стонард — укріплена застава Орди серед південних драговин Болота Скорботи. Його збудували ще під час Першої війни, а для сучасної Орди він став важливим опорним пунктом на півдні Східних Королівств і спостережним постом, звідки стежать за Спустошеними Землями.",h="Стонард — укріплена застава Орди серед південних драговин Болота Скорботи.",kw={"стонард","орда","перша війна","темний портал","болото скорботи","шамани"},ang={["class:Shaman"]="Стонард славиться як головний осередок на півдні Східних Королівств, де шамани Орди можуть знайти настанови й навчання далеко від Калімдору.",["faction:Horde"]="Стонард — єдиний укріплений опорний пункт Орди між Пустищами на півночі й Долиною Стренглторну на заході."},sec={{t="Пам'ятка Першої війни",b="Стонард — одне з найдавніших орківських поселень в Азероті. Його заснували, коли Стара Орда ринула крізь Темний Портал у край, що колись звався Чорною Трясовиною, і разом із сестринською заставою Рокард Стонард тримав лінії загарбників. Після Другої війни поселення покинули, і воно зазнало руйнувань, але Нова Орда Тралла відбудувала Стонард і поставила там гарнізон. Тепер, із традиційним орківським Великим Залом і укріпленими землянками, ця застава — важливий острівець влади Орди серед дикої й небезпечної трясовини."},{t="Прикордонна застава",b="Сучасний Стонард — водночас табір дослідників і плацдарм. Картографи й розвідники розходяться довколишніми драговинами, щоб нанести на мапу ще не досліджене болото й стежити за ворожими місцевими звірами, заблукалими дренеями та затонулим Храмом Атал'Гаккара на сході. І головне: Стонард дає Орді організований плацдарм просто на північ від розтрощених Спустошених Земель, тож Орда не спускає ока з приспаного Темного Порталу."}},faq={{q="Чому Стонард важливий для Орди?",a="Стонард дає Орді укріплений військовий і господарський осередок глибоко на півдні Східних Королівств. Звідси розвідники досліджують небезпечне Болото Скорботи, звідси вирушають напади на сусідній Затонулий Храм, і тут стоїть постійний гарнізон неподалік від Спустошених Земель.",al={"чому стонард тут","призначення стонарда","що таке стонард"}},{q="Скільки років Стонарду?",a="Він сягає часів Першої війни — це одне з найперших оркських поселень на Азероті. Засноване Старою Ордою невдовзі після того, як вона пройшла крізь Темний Портал, після Другої війни воно занепало, доки Нова Орда Тралла не відбудувала його.",al={"історія стонарда","коли збудували стонард","хто заснував стонард"}},{q="Що сталося з його поселенням-побратимом, Рокардом?",a="Рокард заснували разом зі Стонардом під час Першої війни. Але якщо Стонард Орда відновила, то Рокард захопили огри-Дредмоли й перетворили на ворожу твердиню, відому як Твердиня Жахокулака в Спустошених Землях.",al={"що таке рокард","історія рокарда","сестринське місто стонарда"}},{q="Чи можна полетіти чи дістатися просто до Стонарда?",a="Так. Зі Стонарда є польоти через увесь континент — до Карґата, Полум'яного Гребеня, Базового Базового Табору Ґром'ґол і нейтрального порту Буті Бей.",al={"політ до стонарда","як дістатися до стонарда","портали стонарда"}}},fp="7,270,24.519.0,16.452.0,38.289.0,19.260.0,48.235.0,42.150.0"}
P.entries["subzone:stone-cairn-lake"] = {n="Озеро Кам'яного Кургану",s="Озеро Кам'яного Кургану — кільцеподібна водойма на північному сході Лісу Елвінн. У його центрі лежить острів, увінчаний Дозором Героїв — меморіалом полеглим у Першій війні. Колись тихе місце для роздумів, нині озеро тривожать ворожі мурлоки на берегах і чародії-відступники, що зайняли острів.",h="Озеро Кам'яного Кургану — кільцеподібна водойма на північному сході Лісу Елвінн.",kw={"озеро кам'яного кургану","озеро","дозор героїв","мурлоки","чародії-відступники","мідь","ліс елвінн"},ang={["profession:Mining"]="Кручі й пагорби довкола Озера Кам'яного Кургану мають одне з найгустіших скупчень покладів міді в усьому Лісі Елвінн, тож це вигідна зупинка для майбутніх ковалів та інженерів.",["race:Human"]="Центральний острів — глибоко особистий меморіал для королівства Стормвінд, що вшановує загиблих, коли королівство впало під час Першої війни."},sec={{t="Пам'ятник в облозі",b="Озеро Кам'яного Кургану завдячує назвою помітному кам'яному меморіалу, зведеному на великому острові в його центрі. Цей пам'ятник, відомий як Дозор Героїв, поставили на честь тяжких людських втрат у Першій війні проти Орди орків. Колись родини та прочани безпечно діставалися острова, щоб ушанувати полеглих, дивлячись через спокійні води на урочисту кам'яну кладку. Та нині небезпечні чародії-відступники розбили табір просто біля меморіалу, перетворивши місце священної пам'яті на ворожий редут."},{t="Береги озера",b="Довкола кільцеподібного озера тягнеться мальовничий берег, що стає дедалі небезпечнішим для місцевих і мандрівників. Плем'я войовничих мурлоків захопило південні береги, поставило вздовж води грубі хатини й дошкуляє кожному, хто наблизиться. Окрім небезпек, пагорби й виступи довкола озера багаті на мінеральні жили, тож околиця — часта мета шукачів і шахтарів, готових знехтувати тутешніми загрозами."}},faq={{q="Чому воно зветься Озером Кам'яного Кургану?",a="Озеро названо за Дозором Героїв — пам'ятником-курганом, зведеним на острові посередині на честь вояків і мирних мешканців Альянсу, що загинули в Першій війні.",al={"походження назви озера кам'яного кургану","чому кам'яний курган","звідки назва"}},{q="Хто зараз займає острів посеред озера?",a="Острів заполонили чарівники-відступники й ренегати, що прогнали звичайних прочан і влаштували довкола меморіалу укріплений табір.",al={"хто на острові","чарівники на острові","розбійники-маги на озері"}},{q="Чому біля води зібралися мурлоки?",a="Місцеве плем'я мурлоків оселилося на південних мілинах і берегах річки: вони збудували примітивні хижі й забрали собі багаті на рибу води.",al={"мурлоки кам'яного кургану","мурлоки озера","хатини південного берега"}},{q="Як зветься меморіал на острові?",a="Пам'ятник відомий як Дозор Героїв: це кам'яний курган, який часто звуть Каменем Пам'яті.",al={"назва меморіалу на острові","назва пам'ятника","святиня кам'яного кургану"}}},fp="16,325,19.553.0,18.454.0,34.181.0,46.140.0,42.160.0,42.110.0"}
P.entries["subzone:stonebull-lake"] = {n="Озеро Кам'яного Бика",s="Озеро Кам'яного Бика — тихе водоймище у формі підкови, що огортає Село Бладгуф у центральному Малгорі. Живлене чистими водами, що стікають із рівнин, воно дає прісну воду, вдосталь риби й мирні береги молодим тауренам, які дорослішають під проводом Кайрна Бладгуфа.",h="Озеро Кам'яного Бика — тихе водоймище у формі підкови, що огортає Село Бладгуф у центральному Малгорі.",kw={"озеро кам'яного бика","село бладгуф","малгор","риба","міст","тандер блаф"},ang={["race:Tauren"]="Для тауренів, що облаштовують домівки по всьому Малгору, Озеро Кам'яного Бика — лагідна пожива й нагадування про щедрість Земної Матері біля їхньої столиці."},sec={{t="Води рівнини",b="Огинаючи Село Бладгуф із трьох боків, Озеро Кам'яного Бика визначає географію центрального Малгору. Дерев'яний міст перетинає найвужче місце озера, несучи головну ґрунтову дорогу між поселенням і великим плато Тандер Блафа на півночі. Спокійні води повняться місцевою рибою, тож береги облюбували мисливці на спочинку, втомлені мандрівники й рибалки-учні, що опановують ремесло під безкраїм відкритим небом."}},faq={{q="Де розташоване Озеро Кам'яного Бика?",a="Озеро Кам'яного Бика лежить у центрі Малгору. Воно підковою огинає Село Бладгуф, оточуючи поселення з трьох боків.",al={"розташування озера кам'яного бика","де озеро кам'яного бика","озеро мулґору"}},{q="Для чого міст через озеро?",a="Міст перетинає найвужчу частину Озера Кам'яного Бика й несе головну дорогу, що сполучає Село Бладгуф просто з Тандер Блафом на півночі.",al={"міст озера кам'яного бика","міст біля крівавого копита","дорога над озером кам'яного бика"}},{q="Чому Озеро Кам'яного Бика важливе для тауренів?",a="Озеро — важливе джерело прісної води й рибальське угіддя для мешканців Села Бладгуф. А ще це тихе місце для роздумів і зібрань юних тауренських сміливців, що навчаються в центрі Малгору.",al={"чому озеро кам'яного бика важливе","призначення озера кам'яного бика"}}},fp="14,298,19.448.0,32.132.0,44.147.0,46.222.0"}
P.entries["subzone:stonefield-farm"] = {n="Ферма Стоунфілдів",s="Ферма Стоунфілдів — діюча садиба на півдні Лісу Елвінн. Тут живе родина Стоунфілдів, що давно загрузла в запеклій ворожнечі із сусідами Маклюрами.",h="Ферма Стоунфілдів — діюча садиба на півдні Лісу Елвінн.",kw={"ферма стоунфілдів","ферма","ворожнеча","маклюри","томмі джо стоунфілд","ґолдшир","ліс елвінн"},ang={["race:Human"]="Для людей, що починають шлях із Нортширу, чвари між Стоунфілдами й Маклюрами — легковажний погляд на сільське життя королівства поза загрозою розбійників і гнолів."},sec={{t="Гірка садиба",b="Ферма Стоунфілдів серед хвилястої зелені на південь від Ґолдшира вирощує збіжжя для королівства, водночас плекаючи люту, десятиліттями давню образу на сусідні Виноградники Маклюрів. Злопам'ятство між господарствами породжує дрібні сварки, взаємні звинувачення в крадіжках і постійну напругу. Та за ворожими перепалками юний Томмі Джо Стоунфілд таємно покохав Мейбелл Маклур, і це тихе кохання може або перекинути міст між родинами, або розпалити ще більший гнів."}},faq={{q="Що за ворожнеча між Стоунфілдами й Маклурами?",a="Родини Стоунфілдів і Маклурів давно й уперто ворогують на півдні Лісу Елвінн. Вони постійно звинувачують одна одну в самочинному вторгненні, дрібних крадіжках і всіляких лихих учинках і не хочуть співпрацювати навіть у простих сусідських справах.",al={"ворожнеча стоунфілдів і маклурів","чому стоунфілди б'ються","суперники стоунфілдів"}},{q="Хто живе на Фермі Стоунфілдів?",a="Господарює на фермі рід Стоунфілдів — зокрема Бабуся Стоунфілд, Ма Стоунфілд і юний Томмі Джо Стоунфілд.",al={"нпс стоунфілдів","хто на фермі стоунфілдів"}},{q="Яка таємниця в Томмі Джо Стоунфілда?",a="Попри запеклу ворожнечу двох родин, Томмі Джо Стоунфілд потай закоханий у Мейбелл Маклур. Закохані покладаються на співчутливих мандрівників, що передають їхні листи й подарунки, поки родини нічого не помічають.",al={"таємниця томмі джо","романс томмі джо","кохання стоунфілдів"}}},fp="15,190,18.517.0,58.248.0,29.124.0,38.239.0"}
P.entries["subzone:stonefire-tavern"] = {n="Таверна «Кам'яний Вогонь»",s="Таверна «Кам'яний Вогонь» — головний заїзд для мандрівників у гірському місті Айронфорджі. Вона стоїть у гамірних Торгових Рядах, одразу на північ від міської брами, і дає шукачам пригод з усього Каз Модану тепле вогнище, міцний дворфійський ель і місце для відпочинку.",h="Таверна «Кам'яний Вогонь» — головний заїзд для мандрівників у гірському місті Айронфорджі.",kw={"таверна","кам'яний вогонь","айронфордж","торгові ряди","корчма","ель"},ang={["faction:Alliance"]="Як найближча велика корчма до головної брами Айронфорджа, «Кам'яний Вогонь» часто стає головним місцем збору для мандрівників Альянсу в дворфійській столиці.",["race:Dwarf"]="Для дворфів, що повертаються з походів Каз Моданом, Таверна «Кам'яний Вогонь» — перше місце в столиці, де можна вхопити холодний кухоль елю Файрбрю й послухати місцеві плітки."},sec={{t="Серце Торгових Рядів",b="Таверна «Кам'яний Вогонь» стоїть одразу на північ від брами фортеці, у Торгових Рядах, і вважається найкращим шинком Айронфорджа. Її тримає Шинкар Файрбрю разом зі своєю донькою Ґвенною: утомлені подорожні знаходять тут ситні страви, місцеве пиво й нічліг під горою. Хто ховається від лютих гірських снігів Дун Мороґу, хто обмінюється байками й припасами, перш ніж вирушити вглиб міста, — мандрівники з усіх куточків Альянсу раз у раз збираються біля її ревучого вогнища."}},faq={{q="Де розташована Таверна «Кам'яний Вогонь»?",a="Таверна стоїть у кварталі Майдан в Айронфорджі, за кілька кроків на північ від головної міської брами.",al={"розташування таверни кам'яний вогонь","корчма айронфорджа","де кам'яний вогонь"}},{q="Хто тримає Таверну «Кам'яний Вогонь»?",a="Таверною керує Шинкар Файрбрю з допомогою своєї доньки, Ґвенни Файрбрю.",al={"хто керує кам'яним вогнем","корчмар кам'яного вогню","корчма вогняного пива"}},{q="Чи можуть мандрівники прив'язати тут камінь повернення?",a="Так. Шинкар Файрбрю радо приймає мандрівників Альянсу, які хочуть зробити Таверну «Кам'яний Вогонь» своєю домівкою в Айронфорджі.",al={"прив'язати камінь у айронфорджі","домашня корчма айронфорджа","камінь повернення кам'яний вогонь"}},{q="Які зручності поблизу?",a="Просто біля входу до таверни стоїть міська поштова скринька, а довколишній Майдан повний банків, крамарів і торгових припасів.",al={"послуги кам'яного вогню","поштова скринька біля кам'яного вогню"}}},fp="16,284,20.513.0,38.120.0,34.97.0,43.122.0,26.136.0"}
P.entries["subzone:stonemaul-ruins"] = {n="Руїни Кам'яного Молота",s="Руїни Кам'яного Молота — розтрощені рештки Села Кам'яного Молота, колись гордого калімдорського поселення огрів Кам'яного Молота. Після того як чорні дракони вигнали клан, той утік на північ, а колишній дім заполонили вогнегриві драконороди.",h="Руїни Кам'яного Молота — розтрощені рештки Села Кам'яного Молота, колись гордого калімдорського поселення...",kw={"руїни кам'яного молота","кам'яний молот","огри","багно пилоброду","мок'морокк","рекссар","чорні дракони"},ang={["faction:Horde"]="Огри Кам'яного Молота — вірні союзники, що проливали кров пліч-о-пліч з Ордою Тралла проти Кул Тірасу. Допомагаючи їм дати відсіч чорним драконам, ви шануєте цей союз."},sec={{t="Злет і занепад родового дому",b="Перебравшись до Калімдору, огри Кам'яного Молота заснували поселення серед каламутних боліт Багна Пилоброду. Село прославилося, коли повелитель звірів Рекссар пройшов смертельні випробування клану, убив його жорстокого вождя Кор'ґалла й підняв огрів на захист молодої Орди від сил адмірала Праудмура. Після війни Рекссар лишив на чолі огра Мок'Морокка. Під себелюбним правлінням Мок'Морокка село занепало, а зрештою чорні дракони напали на нього зненацька й розтрощили. Уцілілі огри втекли на північ і заснували Село Папоротяної Стіни, а виводок Оніксії цілком заволодів руїнами."},{t="Боротьба за повернення",b="Нині руїни міцно затиснуті в межах Драконячої Мряки й кишать вогнегривими драконородами, що доглядають гніздовища виводку поблизу. Поки Володар Мок'Морокк став боягузом і вдовольняється бездіяльністю в Папоротяній Стіні, старші й гордовитіші члени клану, як-от Тарґ і Драз'Зілб, не хочуть зрікатися рідної землі. Діючи з Папоротяної Стіни, вони закликають чемпіонів Орди вирізати драконородів-загарбників і трощити драконячі яйця — у надії, що одного дня Кам'яний Молот повернеться й відвоює село предків."}},faq={{q="Хто раніше жив у Руїнах Кам'яного Молота?",a="Поселення, яке тоді звалося Селом Кам'яного Молота, збудував і населяв клан огрів Кам'яного Молота, щойно прибувши до Калімдору.",al={"хто тут жив","історія руїн кам'яного молота","хто збудував село кам'яного молота"}},{q="Чому село покинули?",a="Чорний драконячий рід Оніксії напав на поселення й прогнав огрів, перетворивши село на гніздовище драконородів-Вогнегривів.",al={"чому село зруйноване","що сталося з селом кам'яного молота","хто напав на кам'яний молот"}},{q="Куди поділися вцілілі огри?",a="Уцілілі відступили на північ, у Багно Пилоброду, під проводом Володаря Мок'Морокка й заснували Село Папоротяної Стіни як тимчасову твердиню.",al={"де огри тепер","розташування огрів кам'яного молота"}},{q="Як із цим місцем пов'язаний Рекссар?",a="Рекссар прийшов сюди, щоб залучити огрів до боротьби з Кул Тірасом. Він пройшов їхнє випробування, убив у двобої їхнього тирана-воєначальника Кор'ґалла й недовго був вождем, а тоді передав владу Мок'Морокку.",al={"рекскар кам'яний молот","рекскар вождь огрів"}},{q="Чи збираються огри відвоювати руїни?",a="Так. Мок'Морокк боявся діяти, але інші ватажки Кам'яного Молота, як-от Тарґ і Драз'Зілб, охоче наймають шукачів пригод з Орди, щоб ті прорідили драконородів-Вогнегривів і підготували повернення в рідний дім.",al={"чи повернуться огри","відвоювання кам'яного молота"}}},fp="15,257,30.654.0,28.522.0,36.124.0,30.146.0,33.144.0,43.201.0,38.196.0"}
P.entries["subzone:stonesplinter-valley"] = {n="Долина Кам'яного Уламка",s="Долина Кам'яного Уламка — сувора гірська долина на південному заході Лох Модану, яку заполонили ворожі троги. Колись незаймана альпійська улоговина, тепер вона перетворилася на укріплений табір під грубою орудою трогівського ватажка Ґраумуґа.",h="Долина Кам'яного Уламка — сувора гірська долина на південному заході Лох Модану, яку заполонили ворожі троги.",kw={"долина кам'яного уламка","троги","ґраумуґ","лох модан","телсамар","горяни"},ang={["faction:Alliance"]="Очищення Долини Кам'яного Уламка вберігає важливі шляхи постачання через Лох Модан, які стали вразливими, відколи сили Айронфорджа розпорошені по всьому королівству.",["race:Dwarf"]="Навала трогів тут — образа для безпеки Лох Модану, і горяни Телсамара покладаються на міцних родичів-дворфів, щоб вичистити громил Ґраумуґа, що підступають."},sec={{t="Гамірна твердиня трогів",b="Долина Кам'яного Уламка, що сховалася серед скелястих схилів південно-західного Лох Модану, колись була тихою альпійською улоговиною. Тому спокою настав кінець, коли хвилі підземних трогів видерлися на поверхню по всьому Каз Модану. Захопивши долину, плем'я Кам'яного Уламка швидко перетворило скелясті ущелини на грубі укріплення: риє лігва, ставить барикади й полює на все, що забреде надто близько. Через їхню численність долина стала відкритою раною на дорогах південного Лох Модану, і горяни з Телсамара змушені наймати відчайдушних найманців, щоб ті проріджували лави трогів і знищили їхнього велетенського ватажка Ґраумуґа."}},faq={{q="Де розташована Долина Кам'яного Уламка?",a="Вона врізана в гори в південно-західному куті Лох Модану, трохи на південь від головної дороги, що веде повз Хребет Сивої Лапи.",al={"розташування долини кам'яного уламка","де долина кам'яного уламка","долина троггів лох модан"}},{q="Хто править Долиною Кам'яного Уламка?",a="Табором заправляє грубий ватажок трогів на ім'я Ґраумуґ: із найглибшого кутка долини він спрямовує набіги племені на місцевих мандрівників і патрулі.",al={"хто керує троггами кам'яного уламка","ґраумуг","бос троггів лох модан"}},{q="Звідки в Лох Модані троги?",a="Трогів відкопали глибоко під землею під час дворфійських розкопок в інших куточках Каз Модану. Гнані безглуздою люттю, окремі ватаги вибралися на поверхню, і плем'я Кам'яного Уламка обрало цю відлюдну гірську долину своїм головним плацдармом.",al={"чому трогги в лох модані","звідки трогги","походження троггів лох модан"}},{q="Чому дворфам важливо очистити долину?",a="Долина небезпечно близько до дворфійських поселень, копалень і гірських доріг. Якщо лишити укріплене військо трогів Кам'яного Уламка без нагляду, це загрожуватиме мандрівникам на півдні Лох Модану й ще більше виснажить і без того розпорошені патрулі горян.",al={"чому воювати з троггами кам'яного уламка","проблема з троггами телсамара"}}},fp="20,234,23.646.0,38.136.0,31.171.0,38.260.0,50.267.0"}
P.entries["subzone:stonetalon-peak"] = {n="Пік Кам'яного Кігтя",s="Пік Кам'яного Кігтя — прадавнє святилище нічних ельфів у зеленій високогірній долині на північно-західному краю Гір Кам'яного Кігтя. Священне для калдореїв і доглянуте місцевими друїдами, воно є головним оплотом Альянсу серед цих скелястих висот.",h="Пік Кам'яного Кігтя — прадавнє святилище нічних ельфів у зеленій високогірній долині на північно-західному...",kw={"пік кам'яного кігтя","нічні ельфи","святилище","оракул","третя війна","альянс"},ang={["class:Druid"]="Святилище тісно пов'язане з історією Кола Кенарія та священним Лігвом Кігтя, тож для охоронців дикої природи це важливе місце прощі й оборони.",["faction:Alliance"]="Пік Кам'яного Кігтя — ваша єдина укріплена опора в західних горах: тут можна перепочити, полетіти далі й отримати допомогу із завданнями посеред ворожої території."},sec={{t="Священна гірська долина",b="Високо над посушливим пилом нижніх хребтів Пік Кам'яного Кігтя розкривається пишним, оповитим туманом святилищем. Цю долину здавна вважали священною й просякнутою прадавньою магією: тут збереглися руїни, вік яких сягає тисячоліть, — з тих часів, коли в краї стояли храми на честь королеви Азшари, ще до Великого Розколу. Нині вартові калдореїв і друїди знову мирно доглядають це місце: тут затишний притулок із підземною обителлю друїдів і важливою пристанню гіпогрифів Альянсу."},{t="Перехрестя долі",b="Окрім ідилічних лісів і прадавніх руїн, Пік Кам'яного Кігтя має й історичну вагу з часів Третьої війни. Ведені видіннями Медіва, людська експедиція Джайни Праудмур і Орда Тралла підіймалися на ці небезпечні висоти, шукаючи загадкового Оракула, що жив у глибоких печерах гори. Та доленосна зустріч змусила заклятих ворогів відкласти мечі й заклала підвалини хиткого союзу, який вистояв проти Палаючого Легіону біля Гори Гіджал. Сьогодні пік надійно стережуть вартові, хоча вилазки Орди в низинах не дають захисникам розслабитися."}},faq={{q="Чому Пік Кам'яного Кігтя такий зелений порівняно з рештою гір?",a="Пік Кам'яного Кігтя лежить у захищеній високогірній улоговині, просякнутій давньою магією. Дбайливий догляд нічних ельфів і друїдів із сусіднього Лігва Кігтя зберіг тут буйний лісистий прихисток, де рослинність квітне всупереч обвугленим зубчастим скелям унизу.",al={"чому пік кам'яного кігтя зелений","чому там ліс","погода піку кам'яного кігтя"}},{q="Що сталося тут під час Третьої війни?",a="Послухавши пророчих застережень Пророка Медіва, і Джайна Праудмур, і Тралл прийшли на Пік Кам'яного Кігтя, шукаючи Оракула в печерах гори. Їхня зустріч у кам'яних глибинах привела до історичного перемир'я, що об'єднало людей і орків проти Палаючого Легіону.",al={"що сталося на піку кам'яного кігтя","джайна й тралл кам'яний кіготь","оракул кам'яного кігтя"}},{q="Хто зараз тримає Пік Кам'яного Кігтя?",a="Пік — застава Альянсу, яку захищають і доглядають Вартові нічних ельфів і друїди. Це головний безпечний прихисток, осередок завдань і пункт польотів для шукачів пригод з Альянсу в Горах Кам'яного Кігтя.",al={"чи пік кам'яного кігтя альянсу чи орди","хто живе на піку кам'яного кігтя","фракція піку кам'яного кігтя"}},{q="Які давні руїни тут є?",a="Напівзруйновані колони й мармурові споруди, розкидані долиною, — рештки давньої імперії нічних ельфів: колись тут були храмові угіддя, присвячені Королеві Азшарі, ще до її падіння в божевілля й Великого Розколу.",al={"руїни піку кам'яного кігтя","давній храм кам'яного кігтя","храм азшари"}}},fp="15,269,22.491.0,21.593.0,70.293.0,40.291.0,39.233.0,36.239.0"}
P.entries["subzone:stonewatch"] = {n="Кам'яна Варта",s="Кам'яна Варта — укріплена твердиня в центрі Гір Редріджу, збудована, щоб захищати довколишні людські землі від вторгнень із півночі. Колись тут стояли солдати Стормвінда, а тепер фортецю тримають у жорстокому кулаці орки Блекрок, і вона становить безпосередню загрозу для сусіднього Лейкшира.",h="Кам'яна Варта — укріплена твердиня в центрі Гір Редріджу, збудована, щоб захищати довколишні людські землі...",kw={"кам'яна варта","фортеця","орки блекрок","морґант","ґат'ілзоґґ","гори редріджу"},ang={["faction:Alliance"]="Кам'яна Варта — один із найнебезпечніших плацдармів ворожих орків у самому серці земель Альянсу, тож її повернення життєво важливе для безпеки Редріджу.",["race:Human"]="Різанина 12-го Шабельного полку й падіння фортеці — болісні нагадування про вразливість Лейкшира й політичну байдужість Стормвінда."},sec={{t="Захоплений бастіон",b="Кам'яна Варта, що височіє над урвищами біля Водоспаду Кам'яної Варти, складається з міцної вежі та фортеці, зведених, щоб стерегти підступи з боку Палаючих Степів. Спершу її тримали захисники Лейкшира, але укріплення впало, коли чорнокнижник-ренегат Морґант уклав союз із кланом Блекрок. Сповнені темної магії, орки-загарбники розгромили місцевий людський гарнізон — 12-й Шабельний полк — і захопили фортецю. Згодом Морґант обернувся проти союзників і відступив до сусідньої Вежі Ілґалара з армією гнолів Тіньової Шкури, але орки Блекрок і далі міцно тримають фортецю під командою Генерала Ґат'Ілзоґґа та Лейтенанта Таріл'зуна."},{t="Загроза для Лейкшира",b="Поки в Кам'яній Варті стоїть ворожий орочий гарнізон, Лейкшир опинився просто на прицілі неминучого завоювання. Байдужий чи паралізований Дім Вельмож у Стормвінді відрізав місто від вагомої воєнної допомоги, тож Магістрат Соломон і Маршал Марріс змушені наймати найманців і добровольців. Обезголовити фортецю, знищивши і Таріл'зуна, і Ґат'Ілзоґґа, — головна відчайдушна надія міста зняти облогу з краю."}},faq={{q="Хто зараз тримає Кам'яну Варту?",a="Кам'яну Варту зайняв клан орків Блекрок під командуванням Генерала Ґат'Ілзоґґа і його лейтенанта Таріл'зуна. Вони вигнали королівський гарнізон і тепер використовують твердиню як плацдарм для нападів по всьому Редріджу.",al={"хто в кам'яній варті","хто тримає кам'яну варту","вороги кам'яної варти"}},{q="Як люди втратили Кам'яну Варту?",a="Фортеця впала під час злагодженого наступу клану Блекрок, підсиленого темним чаклунством людини-чорнокнижника, відступника Морґанта. Разом вони розбили захисників 12-го Шабельного полку й захопили весь комплекс.",al={"падіння кам'яної варти","як упала кам'яна варта","історія кам'яної варти"}},{q="Чому Стормвінд не пошле військо, щоб її відвоювати?",a="Стормвінд відмовився виділити досить війська для прикордонних земель, полишивши Магістрата Соломона й Маршала Марріса боронити Редрідж самотужки. Лейкшир покладається на заїжджих шукачів пригод і найманців, щоб контратакувати Кам'яну Варту.",al={"чому немає допомоги стормвінда","підкріплення лейкшира"}},{q="Як Кам'яна Варта пов'язана з Вежею Ілґалара?",a="Спершу Морґант допоміг оркам Блекрок захопити Кам'яну Варту, але невдовзі після перемоги зрадив своїх союзників. Він звів поблизу Вежу Ілґалара, щоб зібрати власну свиту зачарованих невільників і гнолів-гнолів Тіньової Шкури, і нападає і на орків, і на людей.",al={"вежа ілґалара","морґант кам'яна варта"}}},fp="10,295,17.689.0,23.484.0,34.240.0,35.228.0,52.247.0,69.264.0"}
P.entries["subzone:stonewatch-falls"] = {n="Водоспад Кам'яної Варти",s="Водоспад Кам'яної Варти — мальовничий водоспад і глибоке гірське плесо на сході Гір Редріджу, яких живлять води, що витікають з Озера Незрушного. Він спадає схилом під грізними висотами Кам'яної Варти, а його відлюдні води захопило вороже плем'я мурлоків.",h="Водоспад Кам'яної Варти — мальовничий водоспад і глибоке гірське плесо на сході Гір Редріджу, яких живлять...",kw={"водоспад кам'яної варти","водоспад","мурлоки","кам'яна варта","гори редріджу"},ang={["faction:Alliance"]="Поселення мурлоків біля Водоспаду Кам'яної Варти — ще одне небезпечне гніздо потвор, що допікає мандрівникам і без того обложеного східного Редріджу."},sec={{t="Небезпечна гірська чаша",b="Витікаючи зі східної річки Озера Незрушного, Водоспад Кам'яної Варти спадає скелястою місцевістю під твердинею орків Блекрок — Кам'яною Вартою. Падаюча вода видовбала глибоке плесо, сховане біля підніжжя гори. Попри природну красу, мандрівники рідко зупиняються помилуватися краєвидом: плесо заполонила зграя лютих мурлоків, що будує грубі очеретяні халупи й нападає на кожного, хто необачно ступить на берег."}},faq={{q="Звідки береться вода Водоспаду Кам'яної Варти?",a="Водоспад живить річка, що витікає зі східного боку Озера Незрушного й спадає вниз у відлюдну гірську улоговину під кручами Кам'яної Варти.",al={"звідки вода водоспаду кам'яної варти","початок водоспаду кам'яної варти","джерело річки кам'яної варти"}},{q="Хто живе біля Водоспаду Кам'яної Варти?",a="Береги водоспаду займає місцеве плем'я мурлоків. Вони живляться рибою з глибокого гірського ставка й ставлять уздовж берегів грубі навіси та прибережні хижі.",al={"що біля водоспаду кам'яної варти","мурлоки водоспаду","моби біля водоспаду"}},{q="Чи пов'язаний Водоспад Кам'яної Варти з Фортецею Кам'яної Варти?",a="Водоспад — біля підніжжя схилу просто під Кам'яною Вартою та її зруйнованою фортецею. Орки Блекрок тримають укріплені висоти нагорі, а мурлоки панують у водяній улоговині внизу.",al={"зв'язок водоспаду з фортецею","чи фортеця біля водоспаду","стосунки кам'яної варти"}}},fp="16,292,25.441.0,53.165.0,44.178.0,49.190.0"}
P.entries["subzone:stonewatch-keep"] = {n="Фортеця Кам'яної Варти",s="Фортеця Кам'яної Варти — укріплена кам'яна твердиня, що нависає над сходом Гір Редріджу; колись її звело й утримувало Королівство Стормвінд. Тепер її захопило військо орків Блекрок, і вона стала передовою базою, звідки їхні воєначальники тероризують Лейкшир.",h="Фортеця Кам'яної Варти — укріплена кам'яна твердиня, що нависає над сходом Гір Редріджу; колись її звело й...",kw={"фортеця кам'яної варти","орки блекрок","ґат'ілзоґґ","таріл'зун","лейкшир","гори редріджу"},ang={["faction:Alliance"]="Фортеця Кам'яної Варти — болюче нагадування про виснажені кордони Стормвінда; очистити її мури конче потрібно, щоб захистити вразливих мешканців Лейкшира.",["race:Human"]="Людські захисники пролили кров, боронячи ці стіни, і визволення фортеці допомагає помститися за полеглих солдатів і бранців, захоплених кланом Блекрок."},sec={{t="Полеглий бастіон",b="Фортеця Кам'яної Варти колись захищала східні кряжі й оберігала поселенців Лейкшира від ворожих вторгнень. Цей мир розлетівся на друзки, коли чорнокнижник-ренегат Морґант уклав союз із кланом Блекрок. Посилені темною магією, орки з лютою жорстокістю штурмували фортецю, розгромили людських захисників і захопили її. Хоча згодом Морґант покинув союзників, звів сусідню Вежу Ілґалара й підкорив місцевих гнолів, загарбники Блекрок таки зміцнили свою владу над Кам'яною Вартою й перетворили колишній бастіон Альянсу на укріплений плацдарм для наступу на долину."},{t="Престол воєначальника",b="Тепер у фортеці стоїть важкий гарнізон воїнів Блекрок, а керують нею грізний орочий воєначальник Ґат'Ілзоґґ і його жорстокий лейтенант Таріл'зун. З кам'яних мурів ці командири спрямовують набіги по всьому Редріджу й захоплюють бранців — як-от Капрала Кішана зі Стормвінда. Військо королівства розпорошене й не може вислати цілий полк, щоб звільнити фортецю, тож Магістрат Соломон і Маршал Марріс змушені наймати вільних поборників, які проберуться в твердиню й покарають верхівку Блекрок, перш ніж Лейкшир остаточно впаде."}},faq={{q="Кому зараз належить Фортеця Кам'яної Варти?",a="Фортецю нині займає клан Блекрок на чолі з місцевим воєначальником Ґат'Ілзоґґом і його лейтенантом Таріл'зуном. Доки її не захопили, це була твердиня Альянсу, що захищала містечко Лейкшир.",al={"хто контролює фортецю кам'яної варти","хто живе у фортеці кам'яної варти","вороги фортеці кам'яної варти"}},{q="Як орки Блекрок захопили фортецю?",a="Клан Блекрок уклав союз із людиною-чорнокнижником, відступником Морґантом. Підсилені його темним чаклунством, орки здійснили лютий напад, що змів людських захисників Кам'яної Варти.",al={"як орки захопили кам'яну варту","падіння фортеці кам'яної варти","чому впала кам'яна варта"}},{q="Чому армія Стормвінда не відвоює Фортецю Кам'яної Варти?",a="Армія Стормвінда здебільшого полишила Редрідж напризволяще через внутрішні чвари й брак війська по всьому королівству. Тож очільникам Лейкшира доводиться покладатися на незалежних шукачів пригод, щоб дати раду загрозі.",al={"чому немає армії стормвінда","де вартові","допомога армії лейкшира"}},{q="Як Морґант пов'язаний із цією фортецею?",a="Морґант допоміг клану Блекрок захопити Фортецю Кам'яної Варти, але невдовзі після перемоги зрадив орків. Він перебрався звідти й звів власне лігво — Вежу Ілґалара, — а виконувати свою волю змусив зачарованих гнолів-гнолів Тіньової Шкури замість орків.",al={"морґант кам'яна варта","чи морґант у фортеці"}}},fp="15,277,16.665.0,18.585.0,35.214.0,44.202.0,54.219.0,47.240.0"}
P.entries["subzone:stonewatch-tower"] = {n="Вежа Кам'яної Варти",s="Вежа Кам'яної Варти — кам'яна сторожова вежа в захопленій твердині Кам'яної Варти на північному сході Редріджу. Колись її доглядали захисники Лейкшира, а тепер клан Блекрок захопив цю заставу, щоб стежити за довколишніми кряжами й убезпечити свій гірський бастіон.",h="Вежа Кам'яної Варти — кам'яна сторожова вежа в захопленій твердині Кам'яної Варти на північному сході...",kw={"вежа кам'яної варти","вежа","орки блекрок","кам'яна варта","гори редріджу"},ang={["faction:Alliance"]="Вежа Кам'яної Варти — похмуре нагадування про те, як далеко клан Блекрок просунувся в землі Стормвінда, поки головне військо королівства відсутнє.",["race:Human"]="Для жителів Лейкшира орочі стяги над вежами Кам'яної Варти — постійна загроза самому їхньому існуванню."},sec={{t="Захоплений дозорний пост",b="Збудована Королівством Стормвінд, щоб стерегти високі гірські перевали над Озером Незрушним, Вежа Кам'яної Варти була передовою розвідувальною посестрою Фортеці Кам'яної Варти. З її висоти вартові легко бачили східні кряжі й попереджали Лейкшир про будь-яку загрозу з Палаючих Степів. Ця мережа раннього попередження розвалилася, коли орки Блекрок Генерала Ґат'Ілзоґґа спустилися з висот, розгромили людських захисників і забрали твердиню для власних воєнних потреб. Нині вежа наїжачилася вартовими Блекрок, і жоден розвідник Альянсу не підійде до фортеці непоміченим."}},faq={{q="Що таке Вежа Кам'яної Варти?",a="Це укріплена людська сторожова вежа в комплексі Кам'яної Варти на північному сході Гір Редріджу. Збудована, щоб захищати край, нині вона в руках загарбників із клану Блекрок.",al={"лор вежі кам'яної варти","що це за вежа","дозорна вежа кам'яної варти"}},{q="Хто зараз тримає Вежу Кам'яної Варти?",a="Вежу займають орки клану Блекрок під командуванням Генерала Ґат'Ілзоґґа, що відбив твердиню в місцевих людей Редріджу.",al={"хто володіє вежею кам'яної варти","хто у вежі","вороги вежі кам'яної варти"}},{q="Чому вежа важлива для орків Блекрок?",a="З її висоти клан Блекрок бачить сили Альянсу, що наближаються, і стереже підступ до своєї головної фортеці — Фортеці Кам'яної Варти.",al={"чому оркам потрібна вежа","стратегічне значення вежі кам'яної варти"}},{q="Чи може Лейкшир повернути вежу?",a="Лейкширу бракує війська, щоб самотужки відвоювати Кам'яну Варту, тож він покладається на мандрівних шукачів пригод, які проріджують гарнізон Блекрок у вежі й фортеці.",al={"чи лейкшир поверне вежу","плани лейкшира щодо вежі"}}},fp="16,281,18.624.0,25.214.0,40.149.0,49.151.0,32.168.0"}
P.entries["subzone:stonewrought-dam"] = {n="Каменетесна Гребля",s="Каменетесна Гребля — колосальне інженерне диво дворфів на північному краю Лох Модану. Вона стримує води Лоху, утворюючи величезне високогірне озеро, і водночас осушує Багнокрай унизу, перетворюючи його на придатні для життя болота.",h="Каменетесна Гребля — колосальне інженерне диво дворфів на північному краю Лох Модану.",kw={"каменетесна гребля","франклорн форджрайт","темне залізо","гіндервір","лох модан","багнокрай"},ang={["profession:Engineering"]="Для будь-якого інженера гребля — взірцевий урок керування водою й несучої механіки каменетесання, що не поступається навіть великим спорудам під Айронфорджем.",["race:Dwarf"]="Гребля — пам'ятник давньому дворфійському каменярству й архітектурній винахідливості, хоча її походження від Темного Заліза лишається болючою й суперечливою темою серед істориків Айронфорджа."},sec={{t="Диво дворфійського ремесла",b="Каменетесна Гребля, що перетинає каньйон на схід від Дун Алґаза, вважається одним із найбільших будівельних тріумфів дворфійської цивілізації. Спроєктована майстром-архітектором Темного Заліза Франклорном Форджрайтом, гребля зведена за його новаторською технікою каменетесання. Затримавши води гірської улоговини, гребля подвоїла площу Лоху й водночас поступово знизила рівень води на півночі, тож болотиста улоговина Багнокраю постала з колись цілком затопленої долини."},{t="Диверсії й оборона",b="Хоч греблю збудовано під проводом архітектора Темного Заліза, нині вона служить Айронфорджу — і стала головною ціллю диверсантів Темного Заліза, що діють із південних гір. Через недавні напади й спроби проникнення Айронфорджу довелося поставити тут гарнізон під орудою Головного Інженера Гіндервіра VII. Вартові й інженери вдень і вночі патрулюють кладку, знаючи, що будь-який прорив катастрофічно спустошить Лох і обрушить нищівну повінь на Багнокрай унизу."}},faq={{q="Хто збудував Каменетесну Греблю?",a="Її спроєктував і керував будівництвом славетний архітектор Темного Заліза Франклорн Форджрайт, що винайшов каменетесну техніку будівництва. Хоча її звів майстер із Темного Заліза, нині вона служить королівству Бронзбірдів.",al={"хто збудував каменетесну греблю","творець греблі","архітектор греблі"}},{q="Що буде, якщо гребля прорветься?",a="Прорив обернувся б катастрофою. Озеро швидко витекло б, лишивши від Лох Модану порожній кратер багнюки, а вода ринула б униз, у Багнокрай, нестримною нищівною повінню.",al={"якщо гребля прорветься","що як гребля впаде","зруйнована гребля"}},{q="Чому на неї нападають дворфи Темного Заліза?",a="Клан Темного Заліза прагне вдарити по життєво важливій інфраструктурі Айронфорджа й розхитати край. Зруйнувавши греблю, вони перерізали б шляхи постачання, затопили б північні болота й завдали б болючого удару по гордості Бронзбірдів.",al={"чому нападають на греблю","напад темного заліза на греблю"}},{q="Хто зараз відповідає за оборону греблі?",a="Повсякденною роботою й укріпленнями греблі керує Головний Інженер Гіндервір VII, що разом із силами Айронфорджа викорінює диверсантів.",al={"хто керує греблею","інженер греблі"}}},fp="16,239,25.518.0,20.490.0,31.218.0,31.209.0,39.225.0,48.162.0"}
P.entries["subzone:stonewrought-pass"] = {n="Каменетесний Прохід",s="Каменетесний Прохід — підземний тунель, прорубаний просто крізь південні гори Лох Модана до спустошених просторів Палючої Ущелини. Цей прохід, майстерно збудований славетним архітектором Франклорном Форджрайтом, сполучає Долину Королів із Долиною Пилового Вогню. Важкі залізні брами замикають обидва його кінці, захищаючи мирні дворфійські землі від вулканічних жахіть на півдні.",h="Каменетесний Прохід — підземний тунель, прорубаний просто крізь південні гори Лох Модана до спустошених...",kw={"каменетесний прохід","тунель","лох модан","палюча ущелина","франклорн форджрайт","брама"},ang={["faction:Alliance"]="Цей замкнений прохід, який стережуть дворфійські горяни, захищає вразливі поселення Лох Модана від вулканічних загроз, що визрівають у Палючій Ущелині.",["race:Dwarf"]="Тунель — свідчення інженерного генія Франклорна Форджрайта, хоча тепер він упирається в похмурі, загарбані землі ваших заблудлих родичів із Темного Заліза."},sec={{t="Брама, висічена в камені",b="Каменетесний Прохід висік у скельній основі легендарний майстер-архітектор Франклорн Форджрайт, якого прославила ще й велетенська Каменетесна Гребля. Прохід — прямий коридор між мальовничим спокоєм Лох Модана й випаленими пустелями Палючої Ущелини. Він починається в Лох Модані неподалік велетенської Долини Королів і прорізає гірський хребет аж до Долини Пилового Вогню. Оскільки Палючою Ущелиною заволоділи дворфи Темного Заліза й вогняні звірі, горяни Айронфорджа тримають прохід надійно замкненим за важкими брамами, щоб небезпека не перекинулася на північ."}},faq={{q="Куди веде Каменетесний Прохід?",a="Прохід прорізає гірський хребет наскрізь, сполучаючи Долину Королів на південному краю Лох Модану з Долиною Пилового Вогню на півночі Палючої Ущелини.",al={"куди веде каменетесний прохід","з'єднання тунелю","пекуча ущелина до лох модану"}},{q="Хто спроєктував цей тунель?",a="Його спроєктував видатний дворфійський архітектор Франклорн Форджрайт — легендарний майстер, уславлений по всьому Каз Модану Каменетесною Греблею та іншими монументальними кам'яними спорудами.",al={"хто збудував каменетесний прохід","архітектор проходу","франклорн фордж райт тунель"}},{q="Чому ворота замкнені?",a="Ворота міцно засунуті з обох боків, щоб вогняні чудовиська й ворожі дворфи Темного Заліза з Палючої Ущелини не вдерлися в заселені землі Лох Модану. Горянин Пебблбітті стереже вхід із боку Лох Модану й пропускає лише з дозволу.",al={"замкнена брама","чому прохід замкнений","як відчинити браму"}}},fp="17,396,25.591.0,38.181.0,25.190.0,25.272.0"}
P.entries["subzone:stormrage-barrow-dens"] = {n="Курганні Лігва Штормової Люті",s="Курганні Лігва Штормової Люті — прадавня підземна святиня, видовбана під священною долиною Місячного Гаю. Названі на честь Малфуріона Стормрейджа, ці тихі земляні покої — місце спочинку, де друїди поринають у довгий цілющий сон, щоб мандрувати Смарагдовим Сном.",h="Курганні Лігва Штормової Люті — прадавня підземна святиня, видовбана під священною долиною Місячного Гаю.",kw={"курганні лігва","штормова лють","малфуріон стормрейдж","місячний гай","смарагдовий сон","тіранда віспервінд","ріг кенарія"},ang={["class:Druid"]="Для друїдів обох рас Курганні Лігва Штормової Люті — священне серце спадщини Кенарія, зразок традиційних підземних святинь, де старші друїди переходять між Азеротом і Смарагдовим Сном.",["race:NightElf"]="Це підземелля має для калдореїв величезну історичну вагу: воно береже пам'ять і про тисячолітню варту їхніх сплячих чоловіків, і про небезпечний спуск Тіранди Віспервінд, щоб пробудити Малфуріона проти Палаючого Легіону."},sec={{t="Покої сплячих",b="Курганні лігва — священні притулки на всіх землях нічних ельфів: це безпечні підземні сховки, де тіла друїдів можуть лежати непорушно, поки ті надовго поринають у Смарагдовий Сон. Курганні Лігва Штормової Люті особливо шановані у священному краю Місячного Гаю. Названі на честь верховного друїда Малфуріона Стормрейджа, ці звивисті земляні зали зберігають і давню шану, і тиху варту. Хоч дехто з друїдів, як-от Клінтар Дрімвокер, досі безпечно спить у їхніх нішах, відсутність самого великого верховного друїда кидає сумну тінь на видовбане коріння й мирні сяйливі ліхтарі."},{t="Відлуння Третьої війни",b="У відчайдушні дні Третьої війни ці лігва опинилися на межі повної загибелі. Жахолорд Тіхондріус і сили Палаючого Легіону прагнули знищити сплячих друїдів, перш ніж ті встигнуть згуртуватися. Верховна жриця Тіранда Віспервінд пробилася крізь демонів-загарбників і ворожих зіпсованих звірів глибоко в ці земляні тунелі, щоб засурмити в Ріг Кенарія, — і пробудила Малфуріона Стормрейджа в останню мить. Після поразки Архімонда біля Гори Гіджал Малфуріон повернувся до Місячного Гаю, щоб єднатися з духами, але його сутність знову відплила в Сон, лишивши побратимів стерегти ці священні земляні глибини."}},faq={{q="Для чого потрібні Курганні Лігва Штормової Люті?",a="Курганні лігва — захищені, тихі підземні прихистки для друїдів нічних ельфів. Поки їхній розум і дух мандрують неосяжними шляхами Смарагдового Сну, їхні смертні тіла місяцями чи роками лежать нерухомі й беззахисні, тож їм потрібне тихе й надійне місце, де вони безпечно спочивають під пильним оком побратимів.",al={"для чого курганні лігва","чому спати в курганних лігвах","призначення курганних лігв штормової люті"}},{q="Чи перебуває зараз у цих лігвах Малфуріон Стормрейдж?",a="Відомо, що Малфуріон Стормрейдж спочивав у курганних лігвах під час Третьої війни, доки Тіранда його не розбудила. Коли війна скінчилася й почалися суперечки про те, чи садити нове Світове Дерево, він поринув у глибоке єднання з природою, і його дух загубився в Смарагдовому Сні, тож тепер про його місце спочинку дбає Коло Кенарія.",al={"де малфуріон","чи малфуріон у курганних лігвах","чи можна знайти малфуріона тут"}},{q="Хто зараз спить у цих лігвах?",a="Серед друїдів, що спочивають у лігвах, — Клінтар Дрімвокер: він лежить у глибокому сні під землею, поки його дух мандрує безтілесними стежками природи.",al={"хто спить тут","клінтар сновидець","сплячі друїди місячної поляни"}},{q="Що сталося з цим місцем під час Третьої війни?",a="Під час Третьої війни жахолорд Тіхондріус і демонічні сили Палаючого Легіону вдерлися до курганних лігв, щоб перебити сплячих друїдів нічних ельфів. Верховна Жриця Тіранда Віспервінд повела загін у глибини, пробилася крізь демонів, засурмила в Ріг Кенарія й розбудила Малфуріона.",al={"третя війна курганні лігва","напад тіхондріуса на місячну поляну","пробудження тайранди"}}},fp="21,283,26.620.0,23.651.0,49.330.0,51.334.0,44.189.0,49.326.0"}
P.entries["subzone:stormwind-city"] = {n="Стормвінд",s="Стормвінд — велична столиця Королівства Стормвінд і військове та політичне серце Альянсу. Відбудований із попелу після знищення в Першій війні, він стоїть як найбільший уцілілий бастіон людської могутності в Азероті після падіння північних королівств.",h="Стормвінд — велична столиця Королівства Стормвінд і військове та політичне серце Альянсу.",kw={"стормвінд","столиця","альянс","королівство стормвінд","собор світла","варіан рінн","болвар фордрагон"},ang={["faction:Alliance"]="Стормвінд — головний військовий, морський і духовний осередок Альянсу на півдні Східних Королівств, що однаково радо приймає дворфів, гномів і посланців нічних ельфів.",["race:Human"]="Для людей усього Азерота білі мури Стормвінда уособлюють витривалість, виживання й незгасну славу людства після цілковитої втрати північних королівств."},sec={{t="Відбудований маяк",b="Заснований понад тисячоліття тому нащадками араті, що рушили на південь, Стормвінд розквітнув як жвава прибережна столиця, оперезана кам'яними валами й живлена швидкими річковими млинами. Ця велич скінчилася в Першій війні, коли Орда орків узяла місто в облогу, пробила його оборону й спалила дощенту, змусивши сера Андуїна Лотара вести вцілілих біженців через Велике Море до Лордерону. Після перемоги Альянсу в Другій війні Гільдія каменярів узялася за грандіозне завдання — відбудувати столицю в сяйливу твердиню з білого каменю, мереживом каналів і стрімкими шпилями, що височіє на північ від Лісу Елвінн і сьогодні."},{t="Серце Альянсу",b="Коли Лордерон розтрощила Погибель, а Даларан тяжко зруйнувала Третя війна, Стормвінд став головним прихистком і твердинею людства. Його широкі проспекти й оборонні мури патрулюють дисципліновані міські вартові Стормвінда, а шпилі Собору Світла ведуть віру й відданість південних королівств. Та під його впорядкованими кварталами й церемоніальними брамами тліє тихе політичне сум'яття: Король Варіан Рінн загадково зник, і на троні лишився його юний син Андуїн під регентством Верховного Лорда Болвара Фордрагона та нашіптування королівської радниці Леді Катрани Престор."}},faq={{q="Чому Стормвінд відбудували після Першої війни?",a="Під час Першої війни оркська Орда сплюндрувала й спалила Стормвінд. Коли Великий Альянс Лордерона переміг орків у Другій війні, біженці-люди повернули собі королівство предків. Королівський двір доручив Гільдії Каменярів звести на старих руїнах нове, ще величніше місто-фортецю.",al={"хто відбудував стормвінд","відбудова стормвінда","чому стормвінд виглядає новим"}},{q="Хто зараз править Стормвіндом?",a="Формально на троні сидить король-хлопчик Андуїн Рінн — після раптового й незбагненного зникнення його батька, короля Варіана Рінна. Андуїн ще юний, тож справжня влада — у руках Верховного Лорда Болвара Фордрагона, що є регентом і командувачем оборони королівства.",al={"хто король стормвінда","хто править стормвіндом","правитель стормвінда"}},{q="Чому головна людська столиця — Стормвінд, а не Лордерон?",a="Під час Третьої війни північне королівство Лордерон знищили зсередини чума нежиття й Погибель. Лордерон зруйновано, інші північні людські держави спустошено, тож Стормвінд — найбагатше, найцілісніше й найлюдніше людське королівство, що вціліло на Азероті.",al={"що сталося з лордероном","чому не столиця лордерона","чи стормвінд останнє місто"}},{q="Які військові сили захищають місто?",a="Мир у кварталах і на мурах підтримує міська варта Стормвінда. Ширшу оборону земель і охорону короля забезпечують лицарі королівства, гарнізон Фортеці Стормвінда й паладини Церкви Світла.",al={"хто охороняє стормвінд","армія стормвінда","міська варта"}}},fp="14,298,16.651.0,21.636.0,46.327.0,35.292.0,61.301.0,38.284.0"}
P.entries["subzone:stormwind-gate"] = {n="Брама Стормвінда",s="Брама Стормвінда — монументальний укріплений вхід, що сполучає Ліс Елвінн зі Стормвіндом. Під невпинною охороною королівських вартових цей поріг — головна межа між спокійними лісами та величною Долиною Героїв.",h="Брама Стормвінда — монументальний укріплений вхід, що сполучає Ліс Елвінн зі Стормвіндом.",kw={"брама стормвінда","брама","вхід","долина героїв","вартові","стормвінд","ліс елвінн"},ang={["faction:Alliance"]="Брама уособлює безпеку й незламність Великого Альянсу: для солдатів у дорозі та молодих шукачів пригод це перший проблиск величі.",["race:Human"]="Для людей Стормвінда повернутися крізь ці кам'яні арки означає повернутися додому, у безпеку, після довгих мандрів Елвінном і далі."},sec={{t="Поріг королівства",b="Брама Стормвінда, що височіє над південною дорогою Лісу Елвінн, служить і оборонним оплотом, і церемоніальним порогом столиці. Міські вартові Стормвінда невпинно стежать за кам'яним порталом, охороняючи підступи з лісу, а регулярні патрулі крокують між зовнішньою аркою та Долиною Героїв. Попри тривалі заворушення по всьому Елвінну, величезна брама з заліза й каменю лишається широко відчиненою, щоб вітати мандрівників, купців і захисників, що повертаються, у серці Альянсу."}},faq={{q="Куди веде Брама Стормвінда?",a="Пройшовши браму з Лісу Елвінн, ви потрапляєте просто в Долину Героїв — величний вхід до Стормвінда, обабіч якого стоять височенні пам'ятники героям Другої війни.",al={"куди веде брама стормвінда","що за брамою","вхід у стормвінд"}},{q="Чому браму лишають відчиненою, якщо в Лісі Елвінн небезпечно?",a="Стормвінд живе відкритою торгівлею й безперервним рухом мандрівників із Ґолдшира та з усього Альянсу. Хоча довколишнім лісам дошкуляють розбійники й Дефіас, місто не замикається від власних мешканців і торгівлі, а ставить на прохід пильну варту.",al={"чому брами відчинені","чи закрита брама стормвінда","чому відчинено"}},{q="Хто охороняє браму?",a="Біля входу стоїть міська варта Стормвінда. Двоє вартових чатують одразу зовні, у Лісі Елвінн, ще двоє стережуть внутрішній прохід, а озброєні піхотинці патрулюють міст через Долину Героїв.",al={"охорона брами стормвінда","хто обороняє браму"}},{q="Чи відбуваються біля брами особливі події?",a="Так. Відкрита місцевість довкола Брами Стормвінда часто приймає великі міські свята й сезонні зібрання Альянсу — це просторе місце для зібрань поза тісними кварталами.",al={"свята біля брами стормвінда","події біля брами"}}},fp="14,246,28.536.0,35.176.0,56.267.0,21.226.0,42.193.0"}
P.entries["subzone:stormwind-keep"] = {n="Фортеця Стормвінда",s="Фортеця Стормвінда височіє над столицею як кам'яна твердиня й осідок влади Королівства Стормвінд. Відбудована після руйнування в Першу війну, нині вона прихищає королівський двір юного короля-хлопчика Андуїна Рінна та його регента, Верховного Лорда Болвара Фордрагона.",h="Фортеця Стормвінда височіє над столицею як кам'яна твердиня й осідок влади Королівства Стормвінд.",kw={"фортеця стормвінда","андуїн рінн","болвар фордрагон","двір","стормвінд","трон"},ang={["faction:Alliance"]="Фортеця — серце східного воєнного командування Альянсу, звідки Болвар Фордрагон і маршали керують обороною від нових загроз в Елвінні, Вестфолі й далі.",["race:Human"]="Відбудована з попелу після спустошень Першої війни, фортеця — свідчення стійкості й гордості людей Стормвінда."},sec={{t="Відроджена цитадель",b="Фортеця Стормвінда, що стоїть на плато над усім містом, — водночас палац і воєнний бастіон. Первісну твердиню спалила дотла Стара Орда, коли наприкінці Першої війни вбили короля Ллейна. Знову зведена на старих підвалинах після того, як Альянс повернув королівство, відбудована фортеця вміщує не лише велику тронну залу й Воєнну Кімнату, а й тихі садові дворики та простору Королівську Бібліотеку."},{t="Розколотий двір",b="За стягами й полірованим каменем фортеці ховається непевний мир. Король Варіан Рінн загадково зник дорогою на дипломатичну зустріч у Тераморі, і правління лягло на десятирічного короля Андуїна Рінна. Фактично ж правлять Верховний Лорд Болвар Фордрагон і шляхетна Леді Катрана Престор. Поки Болвар опікується обороною й воєнними справами, двірську політику паралізують чвари аристократів, тож віддалені землі лишаються вразливими, а корона — глибоко неуважною."}},faq={{q="Хто зараз править у Фортеці Стормвінда?",a="Формально трон посідає король Андуїн Рінн, але йому лише десять років, тож правлять регент Верховний Лорд Болвар Фордрагон і королівська порадниця Леді Катрана Престор.",al={"хто головний","хто править стормвіндом","хто король"}},{q="Що сталося з королем Варіаном Рінном?",a="Король Варіан за загадкових обставин зник, коли плив за море на мирну конференцію в Тераморі. Через його раптове зникнення трон спорожнів, і Болвар із двором мусили коронувати юного Андуїна, щоб зберегти політичну стабільність.",al={"де варіан","варіан зник","що сталося з королем"}},{q="Чи зруйнували фортецю в Першій війні?",a="Так. Після того як Ґарона вбила короля Ллейна Рінна, Стара Орда захопила місто й зрівняла фортецю з землею. Нинішню твердиню відбудували на давніх підмурках після перемоги Альянсу в Другій війні.",al={"чи орки зруйнували фортецю","руйнування замку першою війною"}},{q="Які головні крила фортеці можна відвідати?",a="У комплексі є головна тронна зала, Воєнна Кімната одразу за нею, Палата Прохача для прохачів, відкритий дворик-сад, Королівська Галерея й Королівська Бібліотека.",al={"кімнати фортеці","що всередині фортеці","крила фортеці стормвінда"}}},fp="14,269,19.466.0,15.482.1,38.178.0,35.249.0,40.232.0,48.194.0"}
P.entries["subzone:stormwind-stockade"] = {n="В'язниця Стормвінда",s="Захована під каналами вздовж північного краю Кварталу магів, В'язниця — головний каземат суворого режиму в Стормвінді. Призначена для вбивць, політичних бунтарів і чужоземних ворогів, ця підземна фортеця нещодавно поринула в цілковитий хаос після злагодженого бунту в'язнів.",h="Захована під каналами вздовж північного краю Кварталу магів, В'язниця — головний каземат суворого режиму в...",kw={"в'язниця стормвінда","бунт","базіл тредд","дефіас","дім вельмож","стормвінд"},ang={["class:Rogue"]="Бунт оголює діяльність Братства Дефіас і Базіла Тредда, даючи змогу побачити, наскільки організованим став злочинний світ просто під носом у корони.",["faction:Alliance"]="В'язниця стоїть просто в столиці, тож її приборкання життєво важливе для громадської безпеки; зачистивши її зали, ви побачите, як глибоко Братство Дефіас проникло в Стормвінд."},sec={{t="В'язниця в облозі",b="Зазвичай нею опікується Наглядач Телвотер, і саме сюди королівство кидає найнебезпечніших в'язнів — від головорізів і агентів Дефіас до полонених орків Блекрок і дворфів Темного Заліза. Проте жорстокий бунт, організований хитрим змовником Дефіас Базілом Треддом, цілком витіснив тюремну варту. Тепер в'язні вільно розгулюють нижніми камерами, перетворивши твердиню на фортецю бунту. Телвотер, якому ледве вдалося втримати вхід, покладається на вільних шукачів пригод, які мають зануритися в підземні коридори й придушити заколот, доки той не вихлюпнувся в канали."},{t="Бюрократія й закулісні оборудки",b="У В'язниці сидять не лише звичайні вуличні злочинці: вона давно служить розмінною монетою для продажного Дому Вельмож. Убивцям і цінним в'язням, яких засудили до смерті деінде, — як-от грабіжникові могил Декстренові Ворду із Сутінколісся чи воєначальникові Блекрок Тарґорру Жахливому з Редріджу, — аристократи відклали страту, щоб використовувати їх як політичних пішаків. Навіть сусідній Айронфордж звернув на це увагу й потай наймає найманців, щоб стратити таких небезпечних в'язнів, як Кам Діпф'юрі, коли людська бюрократія гальмує справедливе правосуддя."}},faq={{q="Де вхід до В'язниці Стормвінда?",a="Вхід — у кварталі каналів у Стормвінді, на північному вигині, біля самого мосту до Кварталу магів. Двері з вартою ведуть кам'яними сходами просто вниз, до підземних камер.",al={"вхід у в'язницю","як дістатися до в'язниці","розташування в'язниці"}},{q="Хто почав бунт у в'язниці?",a="Заколот задумав і розпалив Базіл Тредд — високопоставлений ватажок Братства Дефіас, ув'язнений у в'язниці. Під його проводом в'язні здолали вартових, захопили зброю й цілком заволоділи підземними блоками камер.",al={"хто такий базіл тред","хто почав бунт","хто керує в'язницею"}},{q="Звідки у в'язниці Стормвінда орки й дворфи Темного Заліза?",a="Стормвінд хапає найнебезпечніших ворогів у всіх спірних землях. Зокрема, Тарґорра Жахливого схопили в Горах Редріджу, а Кам Діпф'юрі уособлює загрозу Темного Заліза. Замість швидкої страти чимало з них опинилися тут як військовополонені або їх лишили живими указом вельмож заради політичних вигод.",al={"чому орки у в'язниці","в'язні темного заліза"}},{q="Чому Сутінколісся й Редрідж просять убивати тутешніх в'язнів?",a="Віддалені поселення на кшталт Даркширу й Лейкшира засудили до страти злочинців — як-от Декстрена Ворда й Тарґорра Жахливого, — але Дім Вельмож відклав їхні страти. Розлючені бюрократичним втручанням Стормвінда, місцеві очільники потай наймають мечників, щоб обійти королівську тяганину й довести справу до кінця.",al={"завдання сутінколісся про в'язницю","злочин і кара","що посієш"}}},fp="18,322,20.626.0,32.583.1,46.230.0,39.264.0,61.332.0,67.307.0"}
P.entries["subzone:stormwind-stockade-classic"] = {n="В'язниця Стормвінда (класична)",s="В'язниця Стормвінда — укріплена підземна в'язниця під кварталом каналів у Стормвінді. Спершу збудована для дрібних злочинців, жорстоких найманців і політичних бунтарів, нещодавно вона поринула в хаос після жорстокого бунту в'язнів.",h="В'язниця Стормвінда — укріплена підземна в'язниця під кварталом каналів у Стормвінді.",kw={"в'язниця стормвінда","бунт","тарґорр жахливий","декстрен ворд","базіл тредд","стормвінд"},ang={["faction:Alliance"]="Бунт просто під вулицями столиці — гостре приниження для правління Верховного Лорда Болвара Фордрагона: він показує, наскільки вразливий Стормвінд зсередини, поки короля немає.",["race:Human"]="Для людей із віддалених містечок негаразди у В'язниці доводять, що Домові Вельмож куди більше болить юридична тяганина в столиці, ніж захист прикордонних поселень від убивць."},sec={{t="В'язниця повстала",b="Захована біля каналів між Старим Містом і Кварталом магів, В'язниця — головна каральна установа Королівства Стормвінд. Під орудою Наглядача Телвотера підземний комплекс тримає найнебезпечніших лиходіїв королівства: головорізів Братства Дефіас, орка-грабіжника з Блекрок, огра й навіть дворфа-лазутчика з Темного Заліза. Нещодавно злагоджений тюремний бунт, організований хитрим злочинцем Базілом Треддом, здолав гарнізон: уцілілих вартових вигнали, а внутрішні зали цілком опинилися під владою каторжників."},{t="Бюрократія й відплата",b="Лихо у В'язниці оголює глибокі тріщини в управлінні Стормвінда. Кількох сумнозвісних в'язнів, як-от жах Блекрок Тарґорра Жахливого й грабіжника могил Декстрена Ворда, що торгував тілами, давно засудили до смерті, але їх тримали живими завдяки безкінечним відстрочкам страти, які влаштовували впливові вельможі. Розлючені зволіканням аристократів, сусідні поселення на кшталт Лейкшира й Даркшира, а також дворфійський гарнізон у Дун Модрі цілком обійшли королівські канали й найняли сторонніх шукачів пригод, щоб ті вдерлися досередини й серед загального безладу стратили головних ватажків."}},faq={{q="Де розташована В'язниця Стормвінда?",a="Вхід до В'язниці — у Стормвінді, на північному березі каналу, на переході між Старим Містом і кварталами Собору та магів.",al={"вхід у в'язницю","як дістатися до в'язниці","розташування в'язниці"}},{q="Хто зараз керує в'язницею?",a="Офіційний наглядач — Наглядач Телвотер, але під час бунту його вигнали. Фактично в'язницю тепер контролює в'язень, що розпалив заколот, — Базіл Тредд — разом із союзними бунтівниками Дефіас.",al={"хто керує в'язницею","бос в'язниці","базіл тред"}},{q="Чому в Стормвінді за ґратами орки й дворфи Темного Заліза?",a="Стормвінд тримає тут цінних військовополонених і диверсантів. Тарґорр Жахливий — полонений орк Блекрок, нападник із сусідніх гір, а Кам Діпф'юрі — ворожий дворф Темного Заліза, ув'язнений за підривну діяльність проти Альянсу.",al={"чому в в'язниці орки","кам дипфурі","таргорр жахливий"}},{q="Чому засуджених убивць лишили живими, а не стратили?",a="Бюрократія й політичне втручання високопоставлених вельмож Стормвінда раз у раз відкладали страти засуджених на кшталт Декстрена Ворда й Тарґорра, викликаючи обурення у віддалених краях — Редріджі й Сутінколіссі.",al={"чому їх не стратили","вельможі стормвінда","страта декстрена варда"}}},fp="28,265,18.586.0,27.590.1,30.162.0,36.231.0,64.239.0,60.218.0"}
P.entries["subzone:stoutlager-inn"] = {n="Корчма «Міцний Лагер»",s="Корчма «Міцний Лагер» — жваве серце Телсамара й головний прихисток для мандрівників у Лох Модані. Сховавшись під пологими пагорбами біля озера, вона пропонує теплі вогнища, міцний дворфійський ель і гамірне місце зустрічей для шукачів пригод і місцевих мешканців.",h="Корчма «Міцний Лагер» — жваве серце Телсамара й головний прихисток для мандрівників у Лох Модані.",kw={"корчма міцний лагер","телсамар","лох модан","дворфійський ель","корчма","нічліг"},ang={["faction:Alliance"]="Корчма — важливий збірний пункт і безпечний прихисток для шукачів пригод з Альянсу, що прямують на північ до Багнокраю чи патрулюють неспокійні долини довкола озера.",["race:Dwarf"]="Для дворфів із клану Бронзбірдів «Міцний Лагер» — знайоме тепло домівки, славетне щирою гостинністю, свіжим елем і надійним товариством далеко від Айронфорджа."},sec={{t="Гостинне вогнище серед пагорбів",b="Корчма «Міцний Лагер», що стоїть у самому Телсамарі, — осередок громадського життя західного Лох Модану. Рудокопи, горяни й мандрівники, що йдуть між Дун Мороґом і Багнокраєм, зупиняються тут, щоб обмінятися чутками, знайти нічліг і випити ситного дворфійського пива. Поки нетрі за Телсамаром стають дедалі небезпечнішими через трогів і кобольдів, товсті кам'яні стіни й палахкі вогнища «Міцного Лагеру» дають надійний прихисток."}},faq={{q="Які послуги надає Корчма «Міцний Лагер»?",a="Корчма пропонує звичні для таверни зручності: корчмаря, що прив'язує камені повернення, ліжка для втомлених мандрівників і місцевих крамарів із харчами та напоями в дорогу Лох Моданом.",al={"послуги корчми міцний лагер","що в корчмі","корчмар телсамара"}},{q="Де розташована Корчма «Міцний Лагер»?",a="Вона стоїть у самому центрі Телсамара — головного містечка Альянсу на заході Лох Модану, біля головної дороги.",al={"розташування корчми","де міцний лагер","знайти корчму міцний лагер"}},{q="Чому корчма така важлива для Телсамара?",a="Окрім їжі й нічлігу, Корчма «Міцний Лагер» — це міський майдан і осередок новин. Тут місцеві горяни оголошують винагороди, а мандрівники планують вилазки в довколишні пагорби.",al={"чому корчма популярна","лор таверни телсамара"}}},fp="14,255,31.482.0,50.207.0,36.126.0,41.193.0"}
P.entries["subzone:strahnbrad"] = {n="Странбрад",s="Странбрад — зруйноване людське поселення на північно-східних висотах Гір Альтерак, біля кордону із Західними Чумними Землями. Колись знане як місце, де принц Артас Менетіл уперше дав відсіч нападникам-оркам Блекрок, містечко відтоді занепало й стало укріпленою твердинею злочинного Синдикату.",h="Странбрад — зруйноване людське поселення на північно-східних висотах Гір Альтерак, біля кордону із Західними...",kw={"странбрад","артас менетіл","синдикат","гори альтерак","ґол'дір","блекрок"},ang={["class:Paladin"]="Ходячи бруківкою Странбрада, ви згадуєте ранні, ще не заплямовані дні принца Артаса Менетіла й Утера Світлоносця, — гірке нагадування про те, як низько впали герої Лордерона.",["faction:Horde"]="Те, що Синдикат поневолив орка Ґол'діра, робить Странбрад нагальною ціллю для героїв Орди, які прагнуть ударити по людських розбійниках і врятувати свого родича."},sec={{t="Містечко трагедії",b="Странбрад спершу належав королівству Альтерак, а після Другої війни увійшов до Лордерона, і його лихо почалося напередодні Третьої війни. Орки клану Блекрок напали на поселення, щоб захопити людей для жертвоприношень Палаючому Легіону, і принц Артас Менетіл разом із Лицарями Срібної Длані вирушив на захист містечка. Хоч Артас прогнав нападників і вбив їхнього наглядача рабів, містечко зазнало тяжких втрат. Коли невдовзі по тому Лордерон упав під натиском Погибелі, Странбрад кинули напризволяще стихіям."},{t="Лабети Синдикату",b="Сьогодні Странбрад став важливим осередком діяльності Синдикату — угруповання вигнаної альтерацької знаті й злочинців, що замишляють повернути своє занепале королівство. Тут патрулюють люди-розбійники й грабіжники, а покинута ратуша й кузня правлять за схованки й плацдарми. Синдикат тримає в зруйнованому містечку припаси й підневільних робітників, зокрема нещасних бранців на кшталт орка Ґол'діра, якого розвідники Орди з Таррен Мілла намагаються визволити."}},faq={{q="Чим Странбрад важливий в історії?",a="У Странбраді для принца Артаса Менетіла почалася Третя війна. Утер Світлоносець послав його захистити поселення від орків Блекрок, що лютували в окрузі, і саме тут Артас уперше уславився: урятував мешканців і порубав оркських нападників.",al={"чому странбрад важливий","артас странбрад","історія странбрада"}},{q="Хто тепер тримає Странбрад?",a="Странбрад у руках Синдикату. Ці люди-розбійники, вірні занепалим шляхетним родам Альтераку, укріпили зруйновану ратушу й кузню й зробили їх головним плацдармом для своїх задумів у горах.",al={"хто володіє странбрадом","моби странбрада","хто живе в странбраді"}},{q="Якому королівству спершу належав Странбрад?",a="До Першої війни Странбрад входив до королівства Альтерак. Після того як Альтерак зрадив Альянс у Другій війні, містечко перейшло під владу королівства Лордерон.",al={"альтерак чи лордерон странбрад","королівство странбрада"}},{q="Чому Орду цікавить це містечко?",a="Синдикат схопив орка на ім'я Ґол'дір і змусив його до жорсткої рабської праці в руїнах Странбрада. Агенти Орди з Таррен Мілла на чолі з Краском посилають сюди шукачів пригод, щоб прорвати оборону Синдикату й визволити Ґол'діра.",al={"завдання орди странбрад","круск странбрад","ґол'дір странбрад"}}},fp="10,344,17.552.0,20.482.0,41.275.0,28.226.0,50.207.0,40.243.0"}
P.entries["subzone:stratholme"] = {n="Стратгольм",s="Колись Стратгольм був перлиною Іствілду й другим за величиною містом Королівства Лордерон. У Третю війну тут відбулося сумнозвісне Очищення, яке влаштував принц Артас Менетіл, коли містяни з'їли зерно, заражене Чумою нежиття. Нині зруйнований мегаполіс досі палає й слугує головною твердинею Погибелі в північному Лордероні.",h="Колись Стратгольм був перлиною Іствілду й другим за величиною містом Королівства Лордерон.",kw={"стратгольм","очищення стратгольма","артас менетіл","мал'ганіс","орден срібної длані","культ проклятих","погибель"},ang={["class:Paladin"]="Для паладинів Стратгольм — свята земля, що обернулася трагедією: тут народився Орден Срібної Длані, і тут Артас розтрощив те саме братство, вимагаючи вбити невинних містян.",["faction:Alliance"]="Зруйноване місто — моторошний пам'ятник падінню Лордерона. Воно нагадує мандрівникам з Альянсу про страшну ціну, сплачену, коли північні королівства впали від чуми й зради."},sec={{t="Колиска паладинів і торгівлі",b="Задовго до свого занепаду Стратгольм був наріжним каменем північної цивілізації. Він постав століття тому, коли Араті поширювали свої володіння на Іствілд, і виріс у друге за величиною поселення Лордерона, славетне святими храмами й священною водою, здатною протистояти темному чаклунству. Перед Другою війною архієпископ Алонсус Фаол зібрав соратників у міській каплиці й заснував Орден Срібної Длані, висвятивши в лицарі таких легенд, як Утер Світлоносець. Протягом тієї війни Стратгольм був важливим портом, осередком постачання й північним центром переробки нафти для Альянсу Лордерона; він вистояв під натиском Старої Орди й відбудувався після перемоги."},{t="Очищення і вічна руїна",b="Доля Стратгольма вирішилася, коли Культ Проклятих переправив на міські ринки партії зараженого зерна з Андоргала. Тисячі людей, нічого не підозрюючи, з'їли отруєне борошно. Коли принц Артас прибув разом з Утером і Джайною Праудмур, він побачив, що зараза поширилася надто далеко, щоб її вилікувати. Вирішивши, що лише різанина не дасть Мал'Ганісу здобути ціле військо, Артас наказав знищити всіх містян. Цей злочин відштовхнув від нього Утера й Джайну і став початком сходження принца в безумство. Місто віддали вогню, а згодом Погибель перебралася в димні руїни й зробила їх своєю столицею в краї."}},faq={{q="Чому Стратгольм досі горить?",a="Коли під час Третьої війни принц Артас вичищав місто, його вояки підпалювали будинки й вулиці, щоб знищити заражених мешканців і зупинити поширення нежиття. Неприродне, отруєне чумою полум'я тліє відтоді й досі, живлене темною некромантичною силою й шаленою навалою Погибелі.",al={"чому стратгольм горить","вогонь у стратгольмі","дим стратгольма"}},{q="Що таке Очищення Стратгольма?",a="Очищення — це поголовна різанина мешканців Стратгольма, яку вчинив принц Артас Менетіл. Після того як місто з'їло зерно, заражене чумою нежиття, Артас вирішив стратити всіх мешканців — і хворих, і здорових, — перш ніж вони повстануть вояками Погибелі. Це рішення зруйнувало його союзи й зламало його моральний компас.",al={"очищення стратгольма","чистка артаса","чистка стратгольма"}},{q="Яку історичну роль відіграв Стратгольм для Срібної Длані?",a="Стратгольм — колиска Лицарів Срібної Длані. У міській Каплиці Алонсуса архієпископ Алонсус Фаол ще до Другої війни заснував паладинський орден і помазав його перших п'ятьох членів, серед яких були Утер Світлоносець, Туральйон і Сайдан Датроган.",al={"походження срібної длані","каплиця алонсуса","орден срібної руки стратгольм"}},{q="Що сталося тут із Тіріоном Фордрінгом?",a="Через кілька років після Другої війни Верховного Лорда Тіріона Фордрінга судили за зраду в Залі Правосуддя Стратгольма — за те, що він заступився за шляхетного орка-відлюдника Ейтріґґа. Суд Утера й ватажків Альянсу позбавив Тіріона титулу й вигнав його. Згодом він визволив Ейтріґґа під час нападу на місто, який очолив Тралл.",al={"суд над тіріоном фордрінгом","суд тіріона стратгольм","суд ейтріґґа"}}},fp="10,367,28.666.0,28.622.0,32.295.0,35.340.0,59.268.0,38.304.0"}
P.entries["subzone:stratholme-classic"] = {n="Стратгольм (класичний)",s="Стратгольм, колись найгордіша перлина північного Лордерона й колиска Срібної Длані, тепер — палаюча руїна й столиця Погибелі в цьому краї. Місто, поділене між фанатичним Багряним Хрестовим Походом і легіонами нежиті Барона Рівендера, досі охоплене нескінченною жорстокою війною.",h="Стратгольм, колись найгордіша перлина північного Лордерона й колиска Срібної Длані, тепер — палаюча руїна й...",kw={"стратгольм","барон рівендер","кел'тузад","багряний хрестовий похід","площа хрестоносців","погибель","підземелля"},ang={["class:Paladin"]="Осквернення Стратгольма глибоко ранить паладинів: це і священна колиска Срібної Длані, і цвинтар, де Артас розтоптав настанови Утера.",["faction:Alliance"]="Для Альянсу Стратгольм — це катастрофічне падіння Лордерона, що нагадує воякам і вцілілим про страшну ціну Третьої війни."},sec={{t="Проклята столиця",b="До Третьої війни Стратгольм був північною опорою Лордерона й священною колискою Лицарів Срібної Длані. Його доля вирішилася, коли принц Артас влаштував у місті чистку, вирізавши власних підданих після того, як заражене зерно занесло чуму в його мури. Тліючий і зруйнований, Стратгольм перейшов до Погибелі. Сьогодні під верховною владою ліча Кел'Тузада й польовим командуванням Барона Рівендера місто слугує головною базою сили нежиті в Чумних Землях."},{t="Розколотий фронт",b="Стратгольм поділений між двома лютими силами, що невпинно проливають кров. На заході фанатичний Багряний Хрестовий Похід укріпив Площу Хрестоносців і Багряний Бастіон під командуванням Великого хрестоносця Сайдана Датрогана. На сході лежать бойні й некрополі Погибелі, яких захищають височенні зикурати й лицар смерті Барон Рівендер. Кожен, хто входить до міста, мусить пробиратися крізь цей нищівний перехресний вогонь серед палаючих кам'яниць і неспокійних духів."}},faq={{q="Чому Стратгольм досі горить?",a="Принц Артас підпалив місто під час свого горезвісного очищення в Третій війні, щоб зупинити поширення чуми нежиття. Пожежі так і не згасли до кінця: їх підтримують темна магія, некромантія й нескінченні вуличні бої між Погибеллю й Багряним Хрестовим Походом.",al={"чому стратгольм горить","хто спалив стратгольм","вогонь стратгольма"}},{q="Хто зараз тримає Стратгольм?",a="Влада поділена. Великий Хрестоносець Датроган командує вцілілим загоном Багряного Хрестового Походу, що укріпився в західному бастіоні, а лицар смерті Барон Рівендер править східними руїнами для Погибелі під владою Кел'Тузада.",al={"хто править стратгольмом","хто головний","лідери стратгольма"}},{q="Яке історичне значення має місто для паладинів?",a="Стратгольм — колиска Ордену Срібної Длані: тут архієпископ Алонсус Фаол уперше висвятив Утера Світлоносця й перших паладинів. Його падіння — найглибша трагедія в історії ордену.",al={"срібна длань стратгольм","історія паладинів стратгольма"}},{q="Як потрапити на бік міста, підвладний Погибелі?",a="Шукачі пригод можуть пробитися туди від самої головної брами, але до східного кварталу Погибелі можна потрапити й просто через Службовий Вхід. Щоб пройти цією задньою брамою, потрібен ключ Магістрата Бартіласа, хоча вправні розбійники, могутні ковальські відмички чи гоблінська вибухівка теж її відчинять.",al={"ключ чорного ходу","службовий вхід стратгольм","як зайти на бік нежиті"}}},fp="20,296,18.522.0,18.475.0,32.278.0,34.232.0,60.223.0,57.327.0"}
P.entries["subzone:stratholme-main-gate"] = {n="Головна Брама Стратгольма",s="Головна Брама Стратгольма — величний палаючий вхід до північного мегаполісу Лордерона на північному заході Східних Чумних Земель. Вона веде прямо зруйнованими проспектами міста до Королівської Площі та укріплень хрестоносців усередині.",h="Головна Брама Стратгольма — величний палаючий вхід до північного мегаполісу Лордерона на північному заході...",kw={"головна брама","стратгольм","королівська площа","торговий ряд","багряний бастіон","артас"},ang={["class:Paladin"]="Стояти перед цією брамою для паладинів — велике горе: саме тут Срібна Длань розкололася, коли Артас розпустив орден у день, коли вирізав Стратгольм.",["race:Human"]="Головна арка колись була величним порогом другого за величиною міста Лордерона, а тепер це некрополь, задушений попелом."},sec={{t="Ворота до полеглої перлини",b="Колись Стратгольм був гордістю північного Лордерона й славився як колиска Ордену Срібної Длані. Нині його величезна арочна головна брама позначає поріг нескінченного жахіття. Саме тут у Третю війну принц Артас повстав проти свого наставника, Утера Світлоносця, і вирізав власних підданих, перш ніж Чума нежиття встигла їх забрати. Відтоді місто палає без упину й стало головною твердинею Погибелі в краї."},{t="Багряний підступ",b="За головною брамою шлях веде просто в руїни Королівської Площі й Торгового Ряду, а далі — до укріпленого кварталу, відомого як Багряний Бастіон. Фанатики Багряного Хрестового Походу пробилися крізь цей вхід, щоб відвоювати місто й вичистити мерців, і облаштували табір серед руїн. Проте хрестоносці опинилися в оточенні нездоланних потвор нежиті й ведуть виснажливу війну, якої не можуть виграти проти темних сил, що керують обороною Стратгольма."}},faq={{q="Куди веде ця брама?",a="Головна Брама — величний парадний вхід до Стратгольма, що відкривається просто на Королівську Площу й Торговий Ряд. Це головний шлях до Багряного Бастіону — кварталу, за який бореться Багряний Хрестовий Похід.",al={"куди веде головна брама стратгольма","що таке головна брама","парадний вхід стратгольма"}},{q="Чому місто за цією брамою досі горить?",a="Під час Третьої війни принц Артас вичистив місто й підпалив його, щоб зупинити поширення чуми нежиття. Темна некромантична магія, нечестиве полум'я й нестримна скверна Погибелі відтоді підтримують невгасиму пожежу в зруйнованому місті.",al={"чому місто горить","хто спалив стратгольм","вогонь стратгольма"}},{q="Чим ця брама відрізняється від Службового Входу?",a="Обидва входи ведуть до того самого величезного зруйнованого міста, але з протилежних кінців. Головна Брама веде до кварталів, де ще є живі й де тримаються багряні, а Службовий Вхід відкривається на східні вулиці, підвладні бойням Погибелі й Баронові Рівендеру.",al={"головна брама проти службового входу","який вхід у стратгольм","двері стратгольма"}},{q="Хто тримає місцевість одразу за Головною Брамою?",a="Перші вулиці за аркою сходжують шкандибаючі зомбі, гулі, кістяки-жахіття й блукаючі тіні, а Багряний Хрестовий Похід тримає обложений бастіон далі вглибині вулиць.",al={"хто всередині головної брами","моби біля парадного входу"}}},fp="20,259,25.472.0,20.494.0,26.214.0,49.258.0,66.289.0,55.203.0"}
P.entries["subzone:stratholme-service-entrance"] = {n="Службовий Вхід Стратгольма",s="Службовий Вхід Стратгольма — укріплений задній вхід біля Брами Східного Муру на півночі Східних Чумних Земель. Він дає прямий і потайний доступ до східного кварталу палаючого міста, який контролює Погибель, оминаючи величні передні ворота.",h="Службовий Вхід Стратгольма — укріплений задній вхід біля Брами Східного Муру на півночі Східних Чумних Земель.",kw={"службовий вхід","стратгольм","брама східного муру","барон рівендер","площа старійшин","погибель"},ang={["class:Paladin"]="Для лицарів Світла цей поріг веде просто в осквернену некромантичну машинерію Погибелі. Це прямий шлях, щоб знищити Рівендера й повернути полеглу честь святого міста.",["class:Rogue"]="Службова брама — класичне тактичне проникнення: вона дозволяє шукачам пригод оминути укріплені лінії фронту й тихо прослизнути в технічні проходи міста."},sec={{t="Проломлений бастіон",b="While the monumental Main Gate of Stratholme opens into King's Square and provides a route toward the Scarlet Bastion, the Service Entrance breaches the city's eastern fortification at Eastwall Gate. Today, it leads directly into the corrupted heart of the metropolis: Elders' Square and the blighted pathways leading toward Baron Rivendare's slaughterhouses."},{t="Лігво Погибелі",b="Venturing through the service portal offers a shorter approach to the Scourge's eastern districts. The surrounding alleys crawl with gargoyles, crypt fiends, and cultists guarding the dread ziggurats. For the Argent Dawn and daring adventurers seeking to strike at the ruling death knight directly, this hidden iron gate serves as the primary staging point for surgical strikes against the Lich King's commanders."}},faq={{q="Де розташований Службовий Вхід Стратгольма?",a="Вхід — біля Брами Східного Муру, під північними горами Східних Чумних земель, трохи на схід від головних руїн Стратгольма. Він сховався в кам'яній арці укріпленого муру.",al={"розташування службового входу","де чорна брама","бічний вхід стратгольма на мапі","як знайти чорний хід стратгольма"}},{q="Чим цей вхід відрізняється від Головної Брами Стратгольма?",a="The Main Gate opens into King's Square and provides a route across the city toward the Scarlet Bastion. The Service Entrance opens near Elders' Square, giving a shorter approach to the undead-held eastern districts and Slaughter Square.",al={"чорний хід проти парадного","різниця службового входу","який вхід у стратгольм"}},{q="Чому він зветься Службовим Входом?",a="Це задній вхід біля Брами Східного Муру, що оминає парадний підступ до міста. Яке міське призначення він мав спершу, не уточнюється.",al={"чому службовий вхід","лор службового входу"}},{q="Хто тримає цю частину міста?",a="Квартал за брамою міцно в руках Погибелі під наглядом Барона Рівендера і його прислужників, що доглядають зикурати — опору їхньої темної магії на Площі Старійшин.",al={"хто контролює чорну браму","боси службового входу","лідер сторони нежиті"}}},fp="27,253,18.359.0,19.413.0,49.202.0,60.236.0,38.124.0,35.182.0"}
P.entries["subzone:stromgarde-keep"] = {n="Фортеця Стромгард",s="Фортеця Стромгард — побита й розділена столиця занепалого людського королівства Стромґард в Аратійському нагір'ї. Колись вона була гордою колискою людської цивілізації під назвою Стром, а тепер фортецю поділили між собою ворожі розбійники Синдикату, огри Каменекулаків, що вдерлися сюди, і жменька відчайдушних королівських захисників на чолі з Принцом Ґаленом Троллбейном.",h="Фортеця Стромгард — побита й розділена столиця занепалого людського королівства Стромґард в Аратійському...",kw={"фортеця стромгард","стромґард","стром","аратор","торадін","троллбейн","синдикат"},ang={["faction:Alliance"]="Стромґард був одним із засновників Альянсу Лордерону в Другу війну. Його обложені захисники — один з останніх вірних оплотів на півночі, і вони відчайдушно борються, щоб не загинути остаточно.",["race:Human"]="Стромґард — прадавнє серце всієї вашої раси: тут перші людські племена об'єдналися під проводом Торадіна й навчилися тайної магії у високих ельфів. Гірко бачити, як його заполонили злочинці й огри."},sec={{t="Колиска людства",b="Задовго до того, як здобути теперішню назву, ця фортеця постала майже три тисячоліття тому як Стром — перша столиця об'єднаної людської імперії Аратор за короля Торадіна. Звідси люди рушили до перемоги над лісовими тролями, і тут народилося людське чарівництво: маги з високих ельфів навчали першу сотню людських чародіїв. З плином століть, коли піднялися й розквітли молодші королівства-сестри — Даларан, Лордерон і Стормвінд, — вплив Строму згас. Уперта династія Троллбейнів, що лишилася тут, перейменувала місто на Стромґард, і всю Другу війну воно лишалося гордим оплотом воїнів, опорою Альянсу Лордерону проти Орківської Орди."},{t="Розбитий оплот",b="Після спустошення Третьої війни Стромґард зрештою не витримав нових лих і зрад. Нині величне кам'яне місто розколоте на три ворожі частини. Аристократи-зрадники з Синдикату засіли у великій внутрішній цитаделі, а брутальні огри Каменекулаків заполонили колишнє святилище магічного кварталу. Притиснуті в останньому кварталі, Принц Ґален Троллбейн і знесилене військо Стромґарда ведуть виснажливу криваву війну на кілька фронтів лише для того, щоб їхня прадідівська домівка не лишилася тільки спогадом."}},faq={{q="Хто зараз тримає Фортецю Стромгард?",a="Зруйноване місто поділене на три запекло оспорювані частини. Підступний Синдикат тримає центральну внутрішню фортецю, огри-Каменекулаки, що вдерлися сюди, зайняли зруйнований квартал магів, а Принц Ґален Троллбейн очолює рештки війська Стромґарда в останньому кварталі.",al={"хто живе в стромґарді","хто володіє фортецею стромґард","хто в стромґарді"}},{q="Що таке Імперія Аратор?",a="Імперія Аратор — найперша об'єднана людська держава, заснована майже три тисячі років тому королем Торадіном. Її столицею був Стром, що стояв саме там, де нині височіє Фортеця Стромгард.",al={"що таке імперія аратор","перше людське королівство","імперія аратор"}},{q="Чому місто в руїнах?",a="Стромґард був могутньою силою аж до кінця Другої війни, але в хаосі після Третьої війни королівство опинилося вразливим і відрізаним від світу. Зрада зсередини, напади злочинного Синдикату, що скористався нагодою, і навала огрів-Каменекулаків розтрощили оборону міста.",al={"чому стромґард зруйнований","що сталося зі стромґардом"}},{q="Хто такий Ґален Троллбейн?",a="Принц Ґален Троллбейн — королівський нащадок і командир уцілілих сил Стромґарда. Зі свого обложеного оплоту у фортеці він керує відчайдушною обороною і від Синдикату, і від огрів.",al={"принц троллбейн","хто такий ґален"}}},fp="15,342,18.693.0,19.547.0,39.293.0,31.208.0,25.300.0,23.208.0"}
P.entries["subzone:sun-rock-retreat"] = {n="Притулок Сонячної Скелі",s="Притулок Сонячної Скелі — прихована святиня Орди високо серед центральних вершин Гір Кам'яного Кігтя, трохи південніше Озера Міркфаллон. Тут верховодять таурени й орки, і це головний плацдарм та пункт постачання Орди в краї. А ще селище стоїть на священній землі, яку таурени здавна шанують за її глибокий духовний відгук.",h="Притулок Сонячної Скелі — прихована святиня Орди високо серед центральних вершин Гір Кам'яного Кігтя, трохи...",kw={"притулок сонячної скелі","орда","таурени","ан'ше","святиня","шамани"},ang={["faction:Horde"]="Як головний плацдарм Орди в Горах Кам'яного Кігтя, Притулок Сонячної Скелі — важливий пункт поповнення припасів і вузол польотів посеред спірних вершин.",["race:Tauren"]="Для шу'гало Притулок Сонячної Скелі — більше, ніж застава: це священна земля, благословенна Ан'ше, де шамани століттями ходили царством духів."},sec={{t="Священна гавань серед вершин",b="Притулок Сонячної Скелі, захований у гірській улоговині на південь від Озера Міркфаллон, здавна мав для тауренів духовне значення. За давнім переказом, Ан'ше — Сонце — поцілувало саме ту вершину, на якій стоїть селище. Ще задовго до приходу Орди тауренські шамани й прочани ходили сюди на обряди, що прочиняють завісу смертного світу, і черпали силу з міцного зв'язку цієї землі з царством духів."},{t="Прикордонна застава",b="Сьогодні Притулок Сонячної Скелі — головна база Орди в Горах Кам'яного Кігтя. Орки й таурени пліч-о-пліч зміцнюють тут опору проти ворожих гарпій, місцевих вартових нічних ельфів і промислового грабунку Венчурної Компанії. Як осередок, що поєднує торгові й повітряні шляхи між Тандер Блафом, Перехрестям і кордонами Ашенвалю, притулок дає прихисток, провізію та духовну настанову тим, хто наважується йти крізь ці скелі."}},faq={{q="Що таке Притулок Сонячної Скелі?",a="Притулок Сонячної Скелі — головна застава Орди в Горах Кам'яного Кігтя. Тут живуть здебільшого таурени й орки, і це мирний прихисток, торговий пункт і командний пост для героїв Орди, що діють у краї.",al={"що таке сонячна скеля","притулок сонячної скелі","хто керує сонячною скелею"}},{q="Чому це місце священне для тауренів?",a="Тауренська легенда каже, що Ан'ше, Сонце, торкнулося гори, де нині стоїть притулок. Ця земля має давній зв'язок зі світом духів, тож здавна сюди приходять на прощу — шукати видінь і спілкуватися з предками.",al={"чому сонячна скеля священна","ансе кам'яний кіготь","лор сонячної скелі тавренів"}},{q="Що загрожує притулку?",a="Притулку доводиться протистояти агресивним гарпіям, що ревно бережуть свої володіння, ворожим нічним ельфам, що стережуть священні ліси, і руйнівному видобутку та вирубці Венчурної Компанії, що нищить природу.",al={"загрози сонячній скелі","хто нападає на сонячну скелю","вороги кам'яного кігтя"}},{q="Куди літають звідси?",a="Притулок Сонячної Скелі має сідало вітрокрилів із прямими польотами до головних місць центрального Калімдору — зокрема до Перехрестя в Пустках і до тауренської столиці Тандер Блаф.",al={"польоти сонячної скелі","політ у притулок сонячної скелі","майстер польотів сонячної скелі"}}},fp="16,391,27.428.0,16.496.0,25.221.0,39.234.0,35.212.0,43.192.0"}
P.entries["subzone:sundown-marsh"] = {n="Призахідне Болото",s="Призахідне Болото — найглибші, найзахідніші закутки Багнокраю, де застояні води сходяться з підступною звіриною. Попри раптори, слизи й гнолів, що там нишпорять, на його багнистому краю тримає самотню садибу дивакувата парочка.",h="Призахідне Болото — найглибші, найзахідніші закутки Багнокраю, де застояні води сходяться з підступною...",kw={"призахідне болото","фрадд свіфтґір","венна сілкбірд","вітряк","кроколіски","багнокрай"},ang={["race:Gnome"]="Те, що Фрадд Свіфтґір і Венна Сілкбірд процвітають зі своїм вітряком посеред небезпечної багнюки, доводить: гномська винахідливість здатна облаштувати затишний дім будь-де."},sec={{t="Дика й каламутна вирва",b="Призахідне Болото заховане на північному заході Багнокраю: глибока вода, густа багнюка й безліч хижаків. Велетенські кроколіски, мінливі слизи, мандрівні раптори й ревні до своєї території гноли-Мохошкірі вільно блукають у тумані. Через небезпечну місцевість більшість мандрівників тримаються лише головної брукованої дороги між Гаванню Менетіл і Айронфорджем, тож цей глибокий закуток лишається здебільшого диким."},{t="Життя на краю трясовини",b="Серед небезпек болота стоїть самотня кам'яна хатина з вітряком, що невтомно крутиться на даху. Там гном Фрадд Свіфтґір і дворфійка Венна Сілкбірд дивом заробляють на життя, нишпорячи болотом. Вони продають дивовижі й рідкісні торгові рецепти, видобуті з трясовини, мандрівникам, яким вистачить сміливості пробратися повз войовничих мешканців болота."}},faq={{q="Де розташоване Призахідне Болото?",a="Призахідне Болото — на північному заході Багнокраю. Це одна з найнижчих і найглибших частин боліт, далеко від головних королівських доріг.",al={"розташування призахідного болота","де призахідне болото","болото багнокраю"}},{q="Хто живе на Призахідному Болоті?",a="Тут у невеликій кам'яній хатці з вітряком живе дивна парочка — гном Фрадд Свіфтґір і дворфійка Венна Сілкбірд. Вони нишпорять болотом у пошуках дивовиж і продають рідкісний крам заїжджим мандрівникам.",al={"хто живе тут","нпс призахідного болота","хатина свіфтгір"}},{q="Які небезпеки чатують на Призахідному Болоті?",a="На болоті кишать небезпечні звірі й чудовиська — велетенські кроколіски, мерзенні слизи, болотяні звірі, раптори й ворожі гноли-Мохошкірі, тож охоти до безтурботних прогулянок тут не буде.",al={"монстри призахідного болота","небезпеки призахідного болота","вороги призахідного болота"}},{q="Навіщо шукачеві пригод іти на Призахідне Болото?",a="Окрім полювання на місцевих звірів, мандрівники приходять до хатки з вітряком, щоб поторгувати з Фраддом Свіфтґіром і Венною Сілкбірд, які пропонують рідкісні рецепти й дивні знахідки з довколишніх боліт.",al={"навіщо йти на призахідне болото","причини йти на призахідне болото","торговці призахідного болота"}}},fp="13,240,25.423.0,28.341.0,31.193.0,27.205.0,43.181.0,50.216.0"}
P.entries["subzone:sunnyglade"] = {n="Сонячна Галявина",s="Сонячна Галявина колись була багатим і заможним людським поселенням королівства Стормвінд за часів Першої війни. Спустошене й зрештою покинуте, коли лінія фронту розвалилася, зруйноване поселення нині занепадає під темним впливом культу Молота Присмерку.",h="Сонячна Галявина колись була багатим і заможним людським поселенням королівства Стормвінд за часів Першої...",kw={"сонячна галявина","стормвінд","перша війна","молот присмерку","вежа мага","стара орда"},ang={["class:Mage"]="Самотня вежа чарівника в Сонячній Галявині — моторошне нагадування про ранню людську магію: Стара Орда пощадила її лише для того, щоб розібрати по кісточках тайнознавчі знання людей.",["race:Human"]="Зарослі камені Сонячної Галявини — сумний пам'ятник віддаленим поселенням, які довелося покинути, коли Стормвінд мусив відступити під час Першої війни."},sec={{t="Падіння золотого містечка",b="До того як Перша війна розшматувала південь Азерота, Сонячна Галявина славилася багатством і затишним достатком. Цей спокій брутально обірвався, коли вдерлася Стара Орда. Загони орків-грабіжників напали на містечко й поневолили вцілілих мешканців, лишивши неушкодженою тільки самотню вежу чарівника, щоб вивчати тайнознавче мистецтво людських чаклунів. Сили Стормвінда спробували визволити полонених селян і відбудувати поселення, але Орда, що наступала, крок за кроком поглинала навколишні Річкові Галявини. Вирішивши, що віддалену провінцію втрачено, командувачі Стормвінда врешті відвели сили на захист рідних земель — і Сонячна Галявина лишилася на поталу руйнації."},{t="Отруєний прихисток",b="Нині Сонячна Галявина лежить далеко за безпечними межами відродженого королівства Стормвінд. Знаменита кам'яна вежа мага напрочуд уціліла і в Першій війні, і в подальші роки занедбання, але мирного містечка довкола неї вже немає. Натомість відлюдні руїни захопили фанатики культу Молота Присмерку, які обертають колись квітучу долину на знаряддя власних зловісних задумів."}},faq={{q="Що сталося із Сонячною Галявиною?",a="Під час Першої війни Стара Орда напала на Сонячну Галявину й сплюндрувала її. Людям удалося визволити полонених селян і спробувати відбудуватися, але зрештою Стормвінд покинув край Річкових Галявин, щоб зосередитися на обороні своїх головних земель.",al={"що таке сонячна галявина","історія сонячної галявини","чому сонячна галявина зруйнована"}},{q="Хто тепер тримає Сонячну Галявину?",a="Руїни Сонячної Галявини нині займає культ Молота Присмерку, що отаборився серед зруйнованих хат і давньої вежі чарівника.",al={"хто живе в сонячній галявині","вороги сонячної галявини","сутінки сонячної галявини"}},{q="Чому орки під час Першої війни лишили вежу магів цілою?",a="Коли Стара Орда плюндрувала Сонячну Галявину, вона навмисно залишила чарівну вежу містечка, щоб її чорнокнижники й командири могли вивчати людську магію й розгадати її таємниці.",al={"орківська вежа магів сонячна галявина","лор вежі сонячної галявини"}},{q="Чому Стормвінд не повернув містечко після війни?",a="Коли Перша війна розгорілася, проводирі Стормвінда визнали Річкові Галявини втраченими й спрямували всі військові сили на оборону серця королівства, покинувши Сонячну Галявину.",al={"чому покинуто","стормвінд сонячна галявина"}}},fp="10,277,21.665.0,17.396.0,28.256.0,28.151.0,68.168.0,52.193.0"}
